\title{Assessing the Alignment of Audio Representations with Timbre Similarity Ratings}

\multauthor
  {Haokun Tian$^1$ \hspace{1cm} Stefan Lattner$^2$ \hspace{1cm} Charalampos Saitis$^1$}
  {$^1$ Queen Mary University of London, UK \hspace{1cm} $^2$ Sony Computer Science Laboratories, Paris, France\\
