\title{On  $k_\IR$-spaces and $s_\IR$-spaces}


\author{Saak Gabriyelyan}%\tnotetext[label1]{The first named author was partially supported by Israel Science Foundation grant 1/12.}
\ead{saak@math.bgu.ac.il}
\address{Department of Mathematics, Ben-Gurion University of the Negev, Beer-Sheva, P.O. 653, Israel}

\author{Evgenii Reznichenko}%\tnotetext[label1]{The second named author was partially supported by Israel Science Foundation grant 1/12.}
\ead{erezn@inbox.ru}
\address{Department of Mathematics, Lomonosov Mosow State University, Moscow, Russia}


\begin{abstract}
We give new characterizations of spaces $X$ which are  $k_\IR$-spaces or $s_\IR$-spaces. Applying the obtained results we provide some sufficient and necessary conditions on $X$ for which $C_p(X)$ is a $k_\IR$-space or an $s_\IR$-space. It is proved that $C_p(X)$ is a $k_\IR$-space for any  space $X$ with one non-isolated point; if, in addition, $|X|$ is not sequential, then $C_p(X)$ is even an $s_\IR$-space. Under $(CH)$, it is shown that there exists a separable metrizable space $X$ such that $C_p(X)$ is an Ascoli space but not a $k_\IR$-space.
\end{abstract}

\begin{keyword}
Ascoli space \sep $k_\IR$-space \sep $s_\IR$-space \sep  $k^{\#}$-completion


\MSC[2010] 54A05 \sep  54B05 \sep   54C35 \sep 54D50

\end{keyword}

\end{frontmatter}

