\section{Universally $\si$-measurable and universal $\si$-measure zero spaces} \label{sec:px}

%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%



For a compact space $K$, we denote  by $C(K)$ the Banach lattice of all continuous real-valued functions on $K$ endowed with the $\sup$-norm, and let
\[
P(K) = \{\mu\in C(K)': \|\mu\|=1, \mu\geq  0\}
\]
be the positive unit sphere of the dual Banach space $C(K)'$, endowed with the weak$^\ast$ topology. By the fundamental Riesz Theorem, the functionals $\mu \in P (K)$ can be identified with Borel regular probability measures on $K$, see \cite[1.2]{Fedorchuk1991}. Every continuous function $f: X \to Y$ between compact spaces induces a map $P (f): P(X) \to P(Y)$ defined by
\[
P(f)(\mu)(g) := \mu(g \circ f )\; \mbox{ for }\; g \in C(Y).
\]


Let $X$ be a space. A countably additive measure $\mu$ on the $\si$-algebra $\cB(X)$ of Borel subsets of $X$ is called a {\em Borel} measure.
A measure $\mu$ is called {\em continuous} if $\mu(\{x\})=0$ for every $x\in X$.
A measure $\mu$ is called {\em discrete} if $|\mu|(C)=1$ for some countable $C\subseteq X$. For $x\in X$, we denote by $\delta_x$ the Dirac measure at $x$.
The set of all probability discrete measures on $X$ is denoted by $P_d(X)$. Each $\mu\in P_d(X)$ can be uniquely represented in the form $\mu=\sum_{n=1}^\infty \lambda_n \delta_{x_n}$, where $x_n\in X$ are distinct, $\lambda_n> 0$ and $\sum_{n=1}^\infty \lambda_n=1$.

We denote by $P_b(X)$ the family of all probability Borel $\sigma$-additive measures on a space $X$. A measure $\mu\in P_b(X)$ is called {\em Radon} if for every Borel set $B\subset X$ and for every $\e>0$, there exists a compact $K\subseteq B$ such that $\mu(B\setminus K)<\e$. The set of all probability Radon measures on $X$ is denoted by $P(X)$. A measure $\mu$ is called {\em $\tau$-additive} if
\[
\mu\big(\bigcup\cU\big) = \sup \big\{ \mu\big(\bigcup\cV\big) : \cV\subset \cU,\ |\cV|<\w \big\}
\]
for any family $\cU$ of open subsets of $X$. The set of all probability $\tau$-additive measures on $X$ is denoted by $P_\tau(X)$.
%Note that $P(X)\subset P_\tau(X)$.

%By Riesz's theorem, for a compact space $Y$, we identify $P(Y)$ with continuous positive functionals $\mu$ on $C(Y)$ for which $\|\mu\|=1$. On $P(Y)$ we consider the weak$^\ast$ topology.

Following \cite{BanakhChigogidzeFedorchuk2003}, we consider the aforementioned sets of probability measures as subspaces of $P(\beta X)$:
\begin{enumerate}
\item[$\bullet$] $P_d(X)=\{\mu\in P(\beta X): \mu(A)=1$ for some $A\subseteq X, |A|\leq\om \}$;
\item[$\bullet$] $P(X)=\{\mu\in P(\beta X): \mu(A)=1$ for some $\si$-compact $A\subseteq X\}$;
\item[$\bullet$] $P_\tau(X)=\{ \mu\in P(\beta X): \mu(K)=0 $ for every compact $K\subseteq \bt X\setminus X\}$;
\item[$\bullet$] $P_\si(X)=\{ \mu\in P(\beta X): \mu(K)=0 $ for every compact $K\subseteq \bt X\setminus X$ of  $G_\delta$ type$\}$.
\end{enumerate}
Then
\[
P_d(X) \subseteq P(X)  \subseteq P_\tau(X)  \subseteq P_\sigma(X)  \subseteq P(\beta X).
\]
By the general Riesz theorem,  the elements of $P(\beta X)$ can be identified with finitely additive regular probability measures defined on the algebra of Baire subsets of $X$ (i.e., the smallest algebra generated by all functionally closed subsets of $X$). Under this identification, the elements of $P_\sigma(X)$ correspond to $\sigma$-additive probability measures  defined
on Baire subsets of $X$ (see  \cite[Section 1]{Fedorchuk1991}).

%For the important case when $X$ is a Polish space (i.e., $X$ is separable and complete-metrizable),
%It is known that $P_b(X)=P_\sigma(X)$ for any Polish space $X$. Below we generalize this result.

\begin{proposition} \label{p:measure-pns}
If $X$ is a perfectly normal space, then $P_b(X)=P_\sigma(X)$.
\end{proposition}
\begin{proof}
Since in a perfectly normal space every closed set is a zero-set, the algebra of Baire subsets of $X$ coincides with the algebra of Borel subsets of $X$.
Thus, $P_b(X)=P_\sigma(X)$.
\end{proof}

Let $X$ be a subspace of a space $Y$. The family $P_b(X)$ can be naturally considered as a subspace of $P_b(Y)$: a measure $\mu\in P_b(X)$ corresponds to the measure $\tilde\mu\in P_b(Y)$ such that $\tilde\mu(B)=\mu(B\cap Y)$ for $B\in\cB(Y)$. We shall always identify $P_b(X)$ with its image in $P_b(Y)$ and write $P_b(X)\subseteq P_b(Y)$.

Let $A$ be a subset of a space $X$, and let $\mu\in P_b(X)$. The {\em external} and the {\em internal} measure of $A$ are defined as follows
\begin{align*}
\mu^\ast(A) &= \inf\{\mu(B): A\subseteq B\in \cB(X)\},
&
\mu_\ast(A) &= \sup\{\mu(B): A\supseteq B\in \cB(X)\}.
\end{align*}
A subset $M$ of $X$ is {\em $\mu$-measurable} if $\mu_\ast(M)=\mu^\ast(M)$. A subset $M$ of $X$ is called {\em universally measurable} if $M$ is $\mu$-measurable for any $\mu\in P_\sigma(X)$. A subset $A$ is called {\em universal measure zero} if $\mu^\ast(A)=0$ for any continuous $\mu\in P_b(X)$.

%\begin{proposition}[\cite{Banakh1995}]\label{p:px:1}
%Let $X$ be a subspace of a compact space $Y$. Then
%\begin{align*}
%P(X) &= \{\mu \in P(Y): \mu_*(X)=1\}, & P_\tau(X) &= \{\mu \in P(Y): \mu^*(X)=1\}.
%\end{align*}
%The embeddings of $P(X)$ and of $P_\tau(X)$ into $P(Y)$ are topological embeddings.
%\end{proposition}





%A space $X$ is called {\em universally measurable} if $P_\sigma(X)=P(X)$ \cite{BanakhChigogidzeFedorchuk2003}.
%Applying  Proposition \ref{p:px:1} to $X$ and $\beta Y$, we obtain the following assertion.

%\begin{proposition}\label{p:px:1+1}
%Let $X$ be a subspace of a space $Y$. If $X$ is a universally $\sigma$-measurable space, then $X$ is  $\mu$-measurable in $Y$ for any $\mu\in P(\beta Y)$.
%\end{proposition}


Let $X$ and $Y$ be spaces, and let  $f: X \to Y$  be a continuous mapping. Denote by $\beta f: \beta X\to \beta Y$ the unique extension of $f$. Then, by \cite{BanakhChigogidzeFedorchuk2003}, we have the following inclusions
\begin{equation} \label{equ:measure-1}
\begin{aligned}
P(\beta f)\big(P_d(X)\big)\subseteq P_d(Y),& \quad P(\beta f)\big(P(X)\big)\subseteq P(Y), \\
P(\beta f)\big(P_\tau(X)\big)\subseteq P_\tau(Y),& \quad P(\beta f)\big(P_\sigma(X)\big)\subseteq P_\sigma(Y).
\end{aligned}
\end{equation}


We shall say that a space $X$ is {\em universally $\sigma$-measurable} if $P_\sigma(X)=P(X)$. Such spaces in \cite{BanakhChigogidzeFedorchuk2003} were called universally measurable. The last inclusion in (\ref{equ:measure-1}) and the equality $P_\sigma(Y)=P(Y)$ imply the next assertion.

\begin{proposition}\label{p:px:ci}
Let $X$ be a space, $Y$ be a universally $\sigma$-measurable space, and let $f: X \to Y$ be a continuous map. If $\mu\in P_\sigma(X)$, then $P(\beta f)(\mu)\in P(Y)$.
\end{proposition}

Let us call the space $X$ to be {\em universal $\si$-measure zero} if $P_\sigma(X)=P_d(X)$. Clearly, any universal $\si$-measure zero space is universally $\si$-measurable. By Theorem 1 of \cite{Knowles1967}, all Radon measures on a compact space $X$ are discrete if, and only if, $X$ is scattered. Therefore, the following statement holds.

\begin{proposition}\label{p:px:sccs}
A compact space $X$ is universal $\sigma$-measure zero if, and only if, $X$ is scattered.
\end{proposition}

Now we characterize universal $\sigma$-measure zero spaces.
\begin{theorem}\label{t:px:sccs}
A space $X$ is universal $\sigma$-measure zero if, and only if, $X$ is universally $\sigma$-measurable and any compact subspace of $X$ is scattered.
\end{theorem}

\begin{proof}
$(\Ra)$ Since $X$ is universal $\sigma$-measure zero, the space $X$ is universally $\sigma$-measurable. Let $K\subseteq X$ be compact. Since $P(K)\subseteq P(X)=P_d(X)$, then $P(K)=P_d(K)$ and $K$ is universal $\sigma$-measure zero. It follows from Proposition \ref{p:px:sccs} that $K$ is scattered.

$(\La)$ Let $\mu\in P_\sigma(X)$. Since $X$ is universally $\sigma$-measurable, we have $\mu\in P(X)$. Then $\mu(S)=1$ for some $\sigma$-compact $S\subseteq X$. Let $S=\bigcup_{i=1}^\infty S_n$, where each $S_n$ is compact. Since $S_n$ is scattered, then, by Proposition \ref{p:px:sccs}, $S_n$ is universal $\si$-measure zero. Therefore, the measure $\mu{\restriction}_{S_n}$ is discrete. Then the measure $\mu$ is discrete.
\end{proof}


Recall (see \cite{Schwartz1973}) that a space $X$ is called {\em Radon} if $P_b(X)=P(X)$. Following \cite[439B]{Fremlin-IV}, a space $X$ is called {\em universally negligible} if $P_b(X)=P_d(X)$.


\begin{proposition}\label{p:px:2}
Let $X$ be a perfectly normal space. Then
\begin{enumerate}
\item[{\rm(i)}] $X$ is a universally $\sigma$-measurable space if, and only if, $X$ is Radon;
\item[{\rm(ii)}] $X$ is a universal $\sigma$-measure zero space if, and only if, $X$ is universally negligible.
\end{enumerate}
\end{proposition}

\begin{proof}
(i) follows from Proposition \ref{p:measure-pns}.

(ii) follows from (i), Theorem \ref{t:px:sccs}, and the following fact \cite[439C]{Fremlin-IV}:  a space $X$ is universally negligible if, and only if, $X$ is Radon and any compact subspace of $X$ is scattered.
\end{proof}

By Theorem 10 of   \cite[p.~122]{Schwartz1973}, every Souslin space is Radon. This result and  Proposition \ref{p:px:2} imply the following assertion.

\begin{proposition}\label{p:px:3}
Any Souslin space is universally $\sigma$-measurable.
\end{proposition}

\begin{theorem}\label{t:px:polish}
Let $M$ be a subspace of  a Polish space $X$. Then:
\begin{enumerate}
\item[{\rm(i)}] $M$ is a universally measurable set in $X$ if, and only if, $M$ is a universally $\sigma$-measurable space;
\item[{\rm(ii)}] $M$ is a universal measure zero set in $X$ if, and only if, $M$ is a universal $\sigma$-measure zero space.
\end{enumerate}
\end{theorem}

\begin{proof}
Recall that, by Theorem 10 of   \cite[p.~122]{Schwartz1973}, each Polish space is Radon.

(i) The set $M$ is  universally measurable in $X$ if, and only if, $M$ is a Radon space (see Propositions 8 and 9 in \cite[p.~118]{Schwartz1973}). Now Proposition \ref{p:px:2}(i) applies.

(ii) From (i) and Proposition \ref{p:px:2} it follows that $M$ is a universal $\sigma$-measure zero space if, and only if, $X$ is a universally $\sigma$-measurable set in $X$ and any compact subspace of $M$ is at most countable being scattered. By 1.2.1. Characterization of  \cite{Nishiura2008}, the latter property is equivalent to $M$ of being a universal measure zero set in $X$.
\end{proof}


\begin{theorem}\label{t:px:ums-realcompact}
If $X$ a universally $\sigma$-measurable space, then $P(X)$ and $X$ are realcompact spaces.
\end{theorem}
\begin{proof}
By Theorem 1.1 of  \cite{BanakhChigogidzeFedorchuk2003}, the space $P_\sigma(X)$ is always realcompact. Since $P(X)=P_\sigma(X)$, we obtain that $P(X)$ is also realcompact. Since $X$ is closely embedded in $P(X)$, we obtain that $X$ is realcompact, too.
\end{proof}





