\section{Spaces which are (strongly) functionally generated by a cover} \label{sec:sfg}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%


The importance of covers which (strongly) functionally generate a space $X$ is explained by numerous important result obtained in Section III, \S~4 of \cite{Arhangel}. Such covers are important also to obtain new characterizations of  $k_\IR$-spaces and  $s_\IR$-spaces.


Let $\mathcal{M}$ be a cover of a space $X$. Recall that  $X$ is called
\begin{enumerate}
\item[$\bullet$]  {\em generated} by the family $\mathcal{M}$ if for each non-closed set $A\subseteq X$, there is an $M \in\mathcal{M}$ such that $M\cap A$ is not closed in $M$;
\item[$\bullet$] {\em strongly functionally generated} by the family $\mathcal{M}$ if for each real-valued discontinuous function $f$ on $X$, there is an $M \in\mathcal{M}$ such that the function $f{\restriction}_M : M \to \IR$ is discontinuous;
\item[$\bullet$]     {\em functionally generated} by the family $\mathcal{M}$ if for every discontinuous function $f: X \to \IR$, there is an $M \in\mathcal{M}$ such that the function  $f{\restriction}_M$ cannot be extended to a real-valued continuous function on the whole space $X$.
\end{enumerate}
%It is clear that if $X$ is strongly functionally generated by $\mathcal{M}$, then $X$ is functionally generated by $\mathcal{M}$.
It is clear that $X$ is a $k$-space (resp., a sequential space or $X$ has countable tightness) if it is generated by the family $\KK(X)$ (resp., by $\mathcal{S}(X)$ or by $\mathcal{C}(X)$). The space $X$ has countable $\IR$-tightness if, and only if, it is functionally generated by $\mathcal{C}(X)$.

Below we characterize spaces generated by a cover, from which we deduce in Proposition \ref{p:generated-sfg} that any such space is strongly functionally generated by that cover.

\begin{proposition} \label{p:generated-family}
Let $\mathcal{M}$ be a cover of a space $X$. Then the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X$ is generated by the family $\mathcal{M}$;
\item[{\rm(ii)}] the natural mapping $I:\bigoplus \mathcal{M}\to X$, defined by $I(x)=x$ for $x\in M\in \mathcal{M}$, is quotient;
\item[{\rm(iii)}] for each non-closed $Q\subseteq X$, there are $x\in\overline{Q}\SM Q$ and $M\in\mathcal{M}$ such that $x\in M\cap \overline{M\cap Q}$.
\end{enumerate}
\end{proposition}

\begin{proof}
(i)$\Ra$(iii) Let $Q\subseteq X$ be non-closed. Then, by (i), there is $M\in\mathcal{M}$ such that $M\cap Q$ is not closed in $M$. So, there is a point $x\in M$ such that $x\in \overline{M\cap Q}\SM (M\cap Q)$; in particular, $x\in \overline{Q}$. It remains to note that $x\not\in Q$ (otherwise, we would have $x\in M\cap Q$ that is impossible).

(iii)$\Ra$(i)  Let $Q$ be a non-closed subset of $X$. By (iii), choose $x\in \overline{Q}\SM Q$ and $M\in \mathcal{M}$ such that $x\in M\cap \overline{M\cap Q}$. Since $x\not\in Q$ and $x\in M$ it follows that $M\cap Q$ is not closed in $M$, as desired.

(i)$\LRa$(ii) A space $X$ is generated by the family $\mathcal{M}$ if, and only if, the following condition is satisfied: a set $F\subseteq X$ is closed if and only if $F\cap M$ is closed in $M$ for each $M\in \cM$. It remains to apply the definitions of the mapping $I$ and the definition of a quotient mapping.
\end{proof}

%The next proposition shows a natural relation between $R$-quotient mappings and covers which strongly functionally generate $X$.
The implication (i)$\LRa$(iii) of the following statement is Theorem 2(1) of \cite{Delgadilo2000}.
\begin{proposition} \label{p:R-quotient-sfg}
Let $\mathcal{M}$ be a cover of a space $X$. Then the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X$ is strongly functionally generated by the family $\mathcal{M}$;
\item[{\rm(ii)}] the natural mapping $I:\bigoplus \mathcal{M}\to X$  is $R$-quotient; %, defined by $I(x)=x$ for $x\in M\in \mathcal{M}$, is $R$-quotient;
\item[{\rm(iii)}]
the adjoint mapping
\[
I^{\#}\: C_p(X)\to C_p\left(\bigoplus\cM\right)=\prod_{M\in \cM} C_p(M)
\]
is an embedding  with closed  image.
\end{enumerate}
\end{proposition}

\begin{proof}
(i)$\Ra$(ii) It is clear that $I$ is continuous and surjective. Now, let $f:X\to\IR$ be a function such that $f\circ I$ is continuous. Assuming that $f$ is discontinuous we could find $M\in\mathcal{M}$ such that $f{\restriction}_M$ is discontinuous, too. Since $f{\restriction}_M=f\circ I{\restriction}_M$ we obtain a contradiction. Thus $f$ is continuous, and hence $I$ is $R$-quotient.

(ii)$\Ra$(i) Let $f:X\to\IR$ be a discontinuous function. Since  $I$ is $R$-quotient, we obtain that $f\circ I$ is also discontinuous. Therefore there is $M\in\mathcal{M}$ such that $f{\restriction}_M=f\circ I{\restriction}_M$ is discontinuous. Thus  $X$ is strongly functionally generated by the family $\mathcal{M}$.

The implication (ii)$\LRa$(iii) follows from Proposition \ref{p:R-quotient-characterization}.
\end{proof}

Propositions \ref{p:generated-family}(ii) and \ref{p:R-quotient-sfg}(ii) imply the following assertion.

\begin{proposition} \label{p:generated-sfg}
If a space $X$ is generated by a family $\mathcal{M}$ of its subsets, then $X$ is strongly functionally generated by the family $\mathcal{M}$.
\end{proposition}

Taking into account that each space $X$, which is  strongly functionally generated by $\mathcal{M}$, is also functionally generated by $\mathcal{M}$, we obtain the following implications
\[
\xymatrix{
\mbox{generated} \ar@{=>}[r]  & \mbox{strongly functionally generated} \ar@{=>}[r] & \mbox{functionally generated.}}
\]

\begin{proposition} \label{p:generated-loc_fin}
Let $\mathcal{M}$ be a locally finite cover of a space $X$ such that every $M\in\mathcal{M}$ is closed. Then $X$ is generated by the family $\mathcal{M}$.
\end{proposition}
\begin{proof}
The natural mapping $I:\bigoplus \mathcal{M}\to X$ is closed and, hence, quotient (see Corollary 2.4.8 of \cite{Eng}). Therefore, by Proposition \ref{p:generated-family}, $X$ is generated by the family $\cM$.
\end{proof}


Recall that a subset $A$ of a space $X$ is {\em $C$-embedded} if each continuous function $f:A\to \IR$ can be extended to a continuous function $\bar f: X\to \IR$.
\begin{proposition} \label{p:fg=sfg-C-embedded}
Let $\mathcal{M}$ be a cover of a space $X$ such that every $M\in\mathcal{M}$ is $C$-embedded in $X$. Then the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X$ is functionally generated by the family $\mathcal{M}$;
\item[{\rm(ii)}] $X$ is strongly functionally generated by the family $\mathcal{M}$.
\end{enumerate}
\end{proposition}

\begin{proof}
We need to prove only the implication (i)$\Ra$(ii). Let $f:X\to \IR$ be a discontinuous function. Choose $M\in\mathcal{M}$ such that the function  $f{\restriction}_M$ cannot be extended to a real-valued continuous function on the space $X$. Since $M$ is $C$-embedded, it follows that $f{\restriction}_M$ is discontinuous, as desired.
\end{proof}


%Now we extract the main idea from the definition of  open-compact attainable spaces which will be used essentially in what follows.
%We denote by $\KK_\IR(X)$ the family of all $k_\IR$-subspaces of the space $X$.

The following notion plays an essential role in what follows.

\begin{definition} \label{def:M-dense}
Let $\mathcal{M}$ be a cover of a space $X$. A subset $A$ of $X$ is called {\em $\mathcal{M}$-dense} if for every $x\in X$, there is $M\in \mathcal{M}$ such that $x\in M\cap \overline{M\cap A}$.
\end{definition}
Observe that each $\mathcal{M}$-dense subset of $X$ is dense.

\begin{proposition} \label{p:M-sfg}
Let $\mathcal{M}_0$ and $\mathcal{M}$ be covers of a space $X$ such that $\mathcal{M}_0\subseteq \mathcal{M}$. Assume that each $M\in\mathcal{M}_0$ is $\mathcal{M}$-dense in $X$. Then $X$ is strongly functionally generated by the family $\mathcal{M}$.
\end{proposition}

\begin{proof}
Let $f:X\to\IR$ be a discontinuous function at some point  $x\in X$. Since $\mathcal{M}_0$ is a cover of $X$, there is an $M\in \mathcal{M}_0\subseteq \mathcal{M}$ such that $x\in M$. If $f{\restriction}_M$ is discontinuous we are done. Assume that $f{\restriction}_M$ is continuous. As $f$ is discontinuous at $x$, there is $\e>0$ such that
\[
x\in \overline{Q}\SM Q, \;\mbox{ where }\; Q=X\SM f^{-1} \big( (f(x)-\e,f(x)+\e)\big).
\]
Since $f$ is continuous on $M$, there is a neighborhood $U$ of $x$ such that
\[
f(M\cap U) \subseteq \big( f(x)-\tfrac{\e}{2},f(x)+\tfrac{\e}{2}\big).
\]
Let $y\in Q\cap U$. Since $M$ is $\mathcal{M}$-dense, there exists an $M'\in \mathcal{M}$ such that $y\in M'\cap \overline{M'\cap M}$; in particular, $y\in \overline{M'\cap M\cap U}$. It remains to note that the function $f{\restriction}_{M'}$ is discontinuous at $y$ because $f(y)\not\in (f(x)-\e,f(x)+\e)$ (by the definition of $Q$), but $f(M'\cap M\cap U)\subseteq \big( f(x)-\tfrac{\e}{2},f(x)+\tfrac{\e}{2}\big)$.
\end{proof}

\begin{proposition} \label{p:homeo-sfg}
Let $X$ be a homogenous space, and let $\mathcal{M}$ be a cover of $X$ such that $h(M)\in \mathcal{M}$ for any $M\in\mathcal{M}$ and each homeomorphism $h:X\to X$. If there is an $\mathcal{M}$-dense subset $A$ of $X$, then $X$ is strongly functionally generated by the family $\mathcal{M}$.
\end{proposition}

\begin{proof}
Let $\mathcal{M}_0:=\big\{ h(A):  \mbox{ where } h:X\to X \mbox{ is a homeomorphism}\big\}$. Then $\mathcal{M}_0$ is a cover of $X$ containing $\mathcal{M}$-dense subsets of $X$. Thus, by Proposition \ref{p:M-sfg}, $X$ is strongly functionally generated by  $\mathcal{M}$.
\end{proof}


