\section{Characterizations of $k_\IR$-spaces} \label{sec:k-R-spaces}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%


In this section we give two types of characterizations of $k_\IR$-spaces. In the first one we use the notions of $R$-quotient mappings and (strongly) functionally generated families (which are closely related by Propositions \ref{p:R-quotient-sfg} and \ref{p:fg=sfg-C-embedded}).

\begin{theorem} \label{t:characterization-kR}
For a Tychonoff space $X$, the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X$ is a $k_\IR$-space;
\item[{\rm(ii)}]  $X$ is strongly functionally generated by the family $\KK(X)$;
\item[{\rm(iii)}]  $X$ is functionally generated by the family $\KK(X)$;
\item[{\rm(iv)}] $X$ is strongly functionally generated by a family of $k_\IR$-subspaces of $X$;
\item[{\rm(v)}]  $X$ is an $R$-quotient image of some topological sum of compact spaces;
\item[{\rm(vi)}]  $X$ is an $R$-quotient image  of a locally compact space;
\item[{\rm(vii)}]  $X$ is an $R$-quotient  image of a $k$-space;
\item[{\rm(viii)}]  $X$ is an $R$-quotient  image of a $k_\IR$-space.
\end{enumerate}
\end{theorem}

\begin{proof}
The equivalence (i)$\Leftrightarrow$(ii) is essentially the definition of $k_\IR$-spaces.

(ii)$\Leftrightarrow$(iii) follows from Proposition \ref{p:fg=sfg-C-embedded} because each compact subset of $X$ is $C$-embedded in $X$.

(ii)$\Ra$(iv) is trivial, and (ii)$\Ra$(v) follows from Proposition \ref{p:R-quotient-sfg}.

(iv)$\Ra$(viii) Let $\cM$ be a family of $k_\IR$-subspaces of $X$ such that $X$ is strongly functionally generated by $\mathcal{M}$. It follows from Proposition \ref{p:R-quotient-sfg} that $X$ is an $R$-quotient image of the discrete sum of $k_\IR$-spaces $\bigoplus\cM$. It remains to note that  $\bigoplus\cM$ is a $k_\IR$-space.

The implications (v)$\Ra$(vi)$\Ra$(vii)$\Ra$(viii) are trivial.

(viii)$\Ra$(i) Assume that $T:Y\to X$ is an $R$-quotient mapping from a $k_\IR$-space $Y$. To show that also $X$ is a $k_\IR$-space, let $f:X\to \IR$ be a $k$-continuous map. Then the composition $f\circ T$ is also $k$-continuous. Since $Y$ is a $k_\IR$-space, we obtain that $f\circ T$ is continuous. Since $T$ is $R$-quotient it follows that $f$ is continuous. Thus $Y$ is a $k_\IR$-space.
\end{proof}


%We start this section with the following useful assertion.
%\begin{proposition} \label{p:open-sur-kR}
%If $T:X\to Y$ is an $R$-quotient mapping and $X$ is a $k_\IR$-space, then also $Y$ is a $k_\IR$-space. \end{proposition}
%\begin{proof}
%Let $f:Y\to \IR$ be a $k$-continuous map. Then the composition $f\circ T$ is also $k$-continuous. Since $X$ is a $k_\IR$-space, we obtain that $f\circ T$ is continuous. Since $T$ is $R$-quotient it follows that $f$ is continuous. Thus $Y$ is a $k_\IR$-space.
%\end{proof}

\begin{corollary} \label{c:open-sur-kR}
A quotient group of a topological group $G$ which is a $k_\IR$-space is also a $k_\IR$-space.
\end{corollary}
\begin{proof}
The assertion follows from Theorem \ref{t:characterization-kR} and the fact that quotient maps of topological groups are open, see Theorem 5.26 of \cite{HR1}.
\end{proof}

Let $X$ be a space and $L\subseteq X$. We shall say that $L$ is {\em $k_\IR$-dense} in $X$ if $L$ is $\KK_\IR(X)$-dense in $X$, where $\KK_\IR(X)$ is the family of all $k_\IR$-subspaces of $X$. Analogously, $L$ is {\em $k$-dense} in $X$ if $L$ is $\KK(X)$-dense in $X$. A subset $L$ of a topological space $X$ is $k$-dense if, and only if, for every $x\in X$, there is $M\subseteq L$ such that $x\in \overline{M}$ and $\overline{M}$ is compact. Any $k$-dense subset is $k_\IR$-dense, and each $k_\IR$-dense subset is dense.




Now we characterize $k_\IR$-spaces  using covers of the space by $k_\IR$-subspaces (being motivated by the condition $(\star)$ from Theorem 2.5 of \cite{Gabr-B1}). The equivalence (a)$\LRa$(iv) in the next theorem was obtained by Banakh in Theorem 3.3.5 of \cite{Banakh-Survey}.

\begin{theorem}\label{t:characterization-kRe}
For a space $X$, the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(a)}] $X$ is a $k_\IR$-space;
\item[{\rm(b)}] there is a cover $\mathcal{M}$ of $X$ containing $k_\IR$-spaces which has one of the following properties:
\begin{enumerate}
\item[{\rm(i)}] for every subset $A$ of $X$ and each point $x\in \overline{A}$, there is $B\in \mathcal{M}$ such that $x\in B\cap \overline{A\cap B}$;
\item[{\rm(ii)}] for every non-closed subset $Q$ of $X$, there are a point $x\in \overline{Q}\SM Q$ and an $M\in \mathcal{M}$ such that $x\in M\cap \overline{Q\cap M}$;
\item[{\rm(iii)}] $M$ is $k$-dense in $X$ for each $M\in\mathcal{M}$;
\item[{\rm(iv)}] $M\cap M'$ is dense in $X$ for all $M,M'\in\mathcal{M}$;
\item[{\rm(v)}] $M$ is $k_\IR$-dense in $X$ for each $M\in\mathcal{M}$;
\item[{\rm(vi)}]  $\mathcal{M}$ is locally finite and all $M\in\mathcal{M}$ are closed.
\end{enumerate}
\end{enumerate}
\end{theorem}

\begin{proof}
(a)$\Ra$(b) is clear (just take $\mathcal{M}=\{X\}$).  Now we prove (b)$\Ra$(a).
\smallskip

(i)$\Ra$(ii) is trivial.

(ii)$\Ra$(a) Propositions \ref{p:generated-family} and \ref{p:generated-sfg} applied to the family $\mathcal{M}$ imply that $X$ is strongly functionally generated by the family $\mathcal{M}$. Thus $X$ is a $k_\IR$-space by (i)$\LRa$(iv) of Theorem \ref{t:characterization-kR}.

(iii)$\Ra$(v) is clear because any $k$-dense subset is $k_\IR$-dense.

(iv)$\Ra$(v) To show that each $M\in \mathcal{M}$ is $k_\IR$-dense in $X$, let $x\in X$. Choose a $k_\IR$-subspace $M'\in \mathcal{M}$ such that $x\in M'$. By assumption on $\mathcal{M}$, the intersection $M\cap M'$ is dense in $X$. Therefore $x\in M'\cap \overline{M'\cap M}$. Thus $M$ is $k_\IR$-dense in $X$, as desired.

(v)$\Ra$(a) Proposition \ref{p:M-sfg} implies that the space $X$ is strongly functionally generated by the family $\mathcal{M}$ of $k_\IR$-subspaces of $X$. Thus $X$ is a $k_\IR$-space by  (i)$\LRa$(iv) of Theorem \ref{t:characterization-kR}.


(vi)$\Ra$(a)  Propositions \ref{p:generated-loc_fin} implies that $X$ is generated by the family $\mathcal{M}$. Therefore, by Proposition \ref{p:generated-sfg},  $X$ is strongly functionally generated by the family $\mathcal{M}$. Now Theorem \ref{t:characterization-kR} applies.
\end{proof}

