\section{Characterizations of $s_\IR$-spaces} \label{sec:s-R-spaces}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%


In this section we characterize $s_\IR$-spaces analogously to characterizations of $k_\IR$-spaces obtained in Section \ref{sec:k-R-spaces}. Our first characterization uses $R$-quotient mappings and (strongly) functionally generated families. % (which are closely related by Propositions \ref{p:R-quotient-sfg} and \ref{p:fg=sfg-C-embedded}).

\begin{theorem} \label{t:characterization-sR}
For a Tychonoff space $X$, the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X$ is an $s_\IR$-space;
\item[{\rm(ii)}]  $X$ is strongly functionally generated by the family $\mathcal{S}(X)$;
\item[{\rm(iii)}]  $X$ is functionally generated by the family $\mathcal{S}(X)$;
\item[{\rm(iv)}] $X$ is strongly functionally generated by a family of $s_\IR$-subspaces of $X$;
\item[{\rm(v)}]  $X$ is an $R$-quotient image of $\mathbf{s}\times D$, where $D$ is a discrete space;
\item[{\rm(vi)}]  $X$ is an $R$-quotient image  of a metrizable locally compact space;
\item[{\rm(vii)}]  $X$ is an $R$-quotient  image of a sequential space;
\item[{\rm(viii)}]  $X$ is an $R$-quotient  image of an $s_\IR$-space.
\end{enumerate}
\end{theorem}

\begin{proof}
The equivalence (i)$\Leftrightarrow$(ii) is essentially the definition of $s_\IR$-spaces.

(ii)$\Leftrightarrow$(iii) follows from Proposition \ref{p:fg=sfg-C-embedded} because each convergent sequence with its limit point in $X$ (as a compact subset)  is $C$-embedded in $X$.

(ii)$\Ra$(iv) is trivial.

(iv)$\Ra$(viii) Let $\mathcal{M}$ be a family of $s_\IR$-subspaces such that $X$ is strongly functionally generated by $\mathcal{M}$. Then, by Proposition \ref{p:R-quotient-sfg}, $X$ is an $R$-quotient image of the discrete sum $\bigoplus\mathcal{M}$. It remains to note that $\bigoplus\mathcal{M}$ is also an  $s_\IR$-space.
\smallskip

(ii)$\Ra$(v) follows from Proposition \ref{p:R-quotient-sfg} (applied to $\mathcal{M}=\mathcal{S}(X)$ and $D=|\mathcal{S}(X)|$).
\smallskip

The implications (v)$\Ra$(vi)$\Ra$(vii)$\Ra$(viii) are trivial.
\smallskip

(viii)$\Ra$(i) Let $f:Y\to \IR$ be an $s$-continuous map. Then the composition $f\circ T$ is also $s$-continuous. Since $X$ is an $s_\IR$-space, we obtain that $f\circ T$ is continuous. As $T$ is $R$-quotient it follows that $f$ is continuous. Thus $Y$ is an $s_\IR$-space.
\end{proof}



%\begin{proposition} \label{p:open-sur-sR}
%If $T:X\to Y$ is an $R$-quotient mapping and $X$ is a $s_\IR$-space, then also $Y$ is a $s_\IR$-space. \end{proposition}
%\begin{proof}
%Let $f:Y\to \IR$ be a $s$-continuous map. Then the composition $f\circ T$ is also $s$-continuous. Since $X$ is a $s_\IR$-space, we obtain that $f\circ T$ is continuous. Since $T$ is $R$-quotient it follows that $f$ is continuous. Thus $Y$ is a $s_\IR$-space.
%\end{proof}

\begin{corollary} \label{c:open-sur-sR}
A quotient group of a topological group $G$ which is an $s_\IR$-space is an $s_\IR$-space, too.
\end{corollary}
\begin{proof}
The assertion follows from Theorem \ref{t:characterization-sR} and the fact that quotient maps of topological groups are open, see Theorem 5.26 of \cite{HR1}.
\end{proof}

Let $X$ be a space and $L\subseteq X$. We shall say that $L$ is {\em $s_\IR$-dense} in $X$ if $L$ is $\cM$-dense in $X$, where $\cM$ is the family $\mathcal{S}_\IR(X)$ of all $s_\IR$-subspaces of $X$. Any sequentially dense subset is  $s_\IR$-dense, and each $s_\IR$-dense subset is dense.




Now we characterize $s_\IR$-spaces  using covers of the space by $s_\IR$-subspaces, it is similar to Theorem \ref{t:characterization-kRe}.

\begin{theorem}\label{t:characterization-sRe}
For a space $X$, the following assertions are equivalent:
\begin{enumerate}
\item[{\rm(a)}] $X$ is an $s_\IR$-space;
\item[{\rm(b)}] there is a cover $\mathcal{M}$ of $X$ containing $s_\IR$-spaces which has one of the following properties:
\begin{enumerate}
\item[{\rm(i)}] for every subset $A$ of $X$ and each point $x\in \overline{A}$, there is $B\in \mathcal{M}$ such that $x\in B\cap \overline{A\cap B}$;
\item[{\rm(ii)}] for every non-closed subset $Q$ of $X$, there are a point $x\in \overline{Q}\SM Q$ and an $M\in \mathcal{M}$ such that $x\in M\cap \overline{Q\cap M}$;
\item[{\rm(iii)}] $M$ is sequentially dense in $X$ for each $M\in\mathcal{M}$;
\item[{\rm(iv)}] $M$ is $s_\IR$-dense in $X$ for each $M\in\mathcal{M}$;
\item[{\rm(v)}]  $\mathcal{M}$ is locally finite and all $M\in\mathcal{M}$ are closed;
\item[{\rm(vi)}] $M\cap L$ is dense in $X$ for all $M,L\in \mathcal{M}$.
\end{enumerate}
\end{enumerate}
\end{theorem}

\begin{proof}
(a)$\Ra$(b) is clear (just take $\mathcal{M}=\{X\}$).  Now we prove (b)$\Ra$(a).
\smallskip

(i)$\Ra$(ii) is trivial.

(ii)$\Ra$(a) Propositions \ref{p:generated-family} and \ref{p:generated-sfg} applied to the family $\mathcal{M}$ imply that $X$ is strongly functionally generated by the family $\mathcal{M}$. Thus $X$ is an $s_\IR$-space by Theorem \ref{t:characterization-sR}.
\smallskip

(iii)$\Ra$(iv) is clear because any sequentially dense subset is $s_\IR$-dense.
\smallskip

(iv)$\Ra$(a) Proposition \ref{p:M-sfg} implies that the space $X$ is strongly functionally generated by the family $\mathcal{M}$ of $s_\IR$-subspaces of $X$. Therefore $X$ is an $s_\IR$-space by Theorem \ref{t:characterization-sR}.
\smallskip

(v)$\Ra$(a)  Propositions \ref{p:generated-loc_fin} implies that $X$ is generated by the family $\mathcal{M}$. Therefore, by Proposition \ref{p:generated-sfg},  $X$ is strongly functionally generated by the family $\mathcal{M}$. Now Theorem \ref{t:characterization-sR} applies.
\smallskip

(vi)$\Ra$(iv) We show that each $M\in \mathcal{M}$ is $s_\IR$-dense in $X$. Let $x\in X$. Since $\mathcal{M}$ is a cover, there is $L\in \mathcal{M}$ such that $x\in L$. Then $L$ is an $s_\IR$-space and $x\in L\cap \overline{M\cap L}=L$ (since $M\cap L$ is dense in $X$).
\end{proof}






\begin{theorem}\label{t:home-sRe}
Let $H$ be an $s_\IR$-dense (for example, sequentially dense) subspace of a homogenous space $G$. If $H$ is an $s_\IR$-space, then $G$ is also an $s_\IR$-space.
\end{theorem}

\begin{proof}
Proposition \ref{p:homeo-sfg} implies that $X$ is strongly functionally generated by the family of $s_\IR$-subspaces of $X$. By Theorem \ref{t:characterization-sRe}, $X$ is an $s_\IR$-space.
\end{proof}

