%Let $H$ be a sequentially dense subspace of a homogenous space $G$. If $H$ is a $s_\IR$-space, then $G$ is also a $s_\IR$-space.
%\end{corollary}


Recall that a space $X$ has {\em countable $\IR$-tightness} if the family $\mathcal{C}(X)$ of all countable subspaces of $X$ functionally generates $X$.


\begin{proposition}\label{p:sR-R-tightness}
Each $s_\IR$-space $X$ has countable $\IR$-tightness.
\end{proposition}
\begin{proof}
%Let $\mathcal{S}$ be the family of all convergent sequences of $X$ with their limits.
By definition, $X$ is an $s_\IR$-space if, and only if, $X$ is functionally generated by the family  $\mathcal{S}(X)$ of all convergent sequences of $X$ with their limits. Therefore, the family of all countable subspaces of $X$ functionally generates $X$.
\end{proof}

In Theorem of \cite{Blasco-78}, Blasco proved that an open subspace of a $k_\IR$-space is a $k_\IR$-space, too. Below we show that an analogous result is valid also for $s_\IR$-spaces.
\begin{proposition} \label{p:open-sR}
An open subspace $U$ of an $s_\IR$-space $X$ is an $s_\IR$-space.
\end{proposition}
\begin{proof}
By Theorem \ref{t:characterization-sR}, there exists a metrizable locally compact space $Y$ and a continuous $R$-quotient surjective map $f:Y\to X$. Put $V=f^{-1}(U)$. It follows from \cite[Proposition 1.6]{Okunev1990} that the map $g=f\rst V: V\to U$ is an $R$-quotient map. Therefore, $U$ is an $R$-quotient image of a metrizable locally compact space. Thus, by Theorem \ref{t:characterization-sR}, $U$ is an $s_\IR$-space.
\end{proof}


\begin{example} \label{exa:w-boun-sR}
Let $C$ be a metrizable compact space, and let $\xxx_\ast\in C^{\w_1}$.
Then $X=\big(C^{\w_1}\SM \{\xxx_\ast\}\big)^{\w_1}$ is an $s_\IR$-space.
\end{example}
\begin{proof}
By Proposition \ref{p:noble:fc-prod}, the space $C^{\w_1}$ is an $s_\IR$-space. It follows from Proposition \ref{p:open-sR} that $Y=C^{\w_1}\setminus \{\xxx_\ast\}$ is an $s_\IR$--space. The space $Y$ is pseudocompact (see Theorem 1.7.7 from \cite{Pseudocompact-1-2018}).
Thus, by Proposition \ref{p:noble:pseudo-prod},  $X=Y^{\w_1}$ is an $s_\IR$-space.
\end{proof}




\begin{remark} \label{rem:sR-perman}
(i) It follows from (i) of Remark \ref{rem:kR-perman} that in general the product of two $s_\IR$-spaces may be not an $s_\IR$-space.

(ii) The space $\IR^{\omega_1}$ is  an $s_\IR$-space (Proposition \ref{p:noble:fc-prod}). Since $\omega_1+1$ is closely embedded into $\IR^{\omega_1}$, it follows that even compact subspaces of $s_\IR$-spaces can be not $s_\IR$-spaces.
\end{remark}


