\section{Strongly sequentially separable spaces} \label{sec:sss}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


Recall that a space $X$ is called {\em strongly sequentially separable} if $X$ is separable and each countable dense subspace of $X$ is sequentially dense. Strongly sequentially separable are thoroughly studied in \cite{GLoM}.

\begin{proposition}\label{p:sR-sss}
Let $X$ be a separable space whose all countable subsets are Fr\'{e}chet--Urysohn. Then $X$ is a strongly sequentially separable $s_\IR$-space.
\end{proposition}
\begin{proof}
Let $D$ be a dense countable subspace of $X$. For every $x\in X$, set $D_x:=D\cup \{x\}$. Since $D_x$ is countable, the space $D_x$ is Fr\'{e}chet--Urysohn.
Therefore there is a sequence in $D_x$ converging to $x$. Thus $D$ is sequentially dense in $X$. Therefore $X$ is a strongly sequentially separable space.

The family $\cM=\{ D_x:x\in X\}$ consists of Fr\'{e}chet--Urysohn subsets. Since $M\cap L\supseteq D$ is dense in $X$ for any $M,L\in\cM$ and each $M\in\cM$ is an $s_\IR$-space, Theorem \ref{t:characterization-sRe}(vi) implies that $X$ is an $s_\IR$-space.
\end{proof}

Let $X$ be a space. Recall that the {\em local character $\chi(x,X)$} of $X$  at a point $x$ is the least cardinality of a local base at $x$. The {\em character} $\chi(X)$
 is the least upper bound of the local characters. Recall also that the small cardinal $\mathfrak{p}$ is defined as follows
\[
\begin{aligned}
\mathfrak{p}=\big\{ \mathcal{B}: & \;\mathcal{B} \mbox{ is a subbase for a free filter on $\w$, and there is no infinite $A$}\\
& \; \mbox{such that $A\subseteq^\ast B$ for all $B\in \mathcal{B}$}\big\},
\end{aligned}
\]
where $A\subseteq^\ast B$ means that $A\SM B$ is finite and $B\SM A$ is infinite.


\begin{theorem} \label{t:separable-p-ks}
Let $X$ be a separable space such that $\chi(X)<\mathfrak{p}$. Then $X$ is a strongly sequentially separable  $s_\IR$-space.
\end{theorem}
\begin{proof}
By Lemma 1.11 of  \cite{Nyikos1992}, each countable space whose character does not exceed $\mathfrak{p}$ is a Fr\'{e}chet--Urysohn space. It follows that every countable subspace of $X$ is a Fr\'{e}chet--Urysohn space. It remains to apply Proposition \ref{p:sR-sss}.
\end{proof}

Now we consider $C_p$-spaces which are strongly sequentially separable.

\begin{proposition}\label{p:cp-sep}
For a space $X$, the following conditions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $C_p(X)$ is separable;
\item[{\rm(ii)}] $X$ admits a condensation onto a separable metrizable space;
\item[{\rm(iii)}] $X$ is a submetrizable space and $|X|\leq\mathfrak{c}$.
\end{enumerate}
\end{proposition}
\begin{proof}
The equivalence (i)$\LRa$(ii) is well-known, see Theorem I.1.4 of \cite{Arhangel}. The implication (ii)$\Ra$(iii) is clear.

(iii)$\Ra$(ii) Let $f: X\to Y$ be a condensation onto a metrizable space. Then $w(Y)\leq|Y|\leq \mathfrak{c}$. Let $Y_*$ be a discrete space of cardinality $\mathfrak{c}$ and $Z=Y\oplus Y_*$. Then $Z$ is a metrizable space and $w(Z)=\mathfrak{c}$. By Theorem 3.4 of \cite{OsipovPytkeev2023}, the space $Z$ admits a condensation onto the Hilbert cube $[0,1]^\om$. Consequently, $Y$ and $X$ admit a condensation onto a separable metrizable space.
\end{proof}

\begin{proposition} \label{p:sss-characterization}
If $C_p(X)$ is separable, then the following conditions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $C_p(X)$ is strongly sequentially separable;
\item[{\rm(ii)}] each countable subset of $C_p(X)$ is Fr\'{e}chet--Urysohn.
\end{enumerate}
\end{proposition}

\begin{proof}
(i)$\Ra$(ii) Let $S$ be a countable subset of $C_p(X)$. Since $C_p(X)$ is separable, $S$ lies in a countable dense subset of $D\subseteq C_p(X)$. Put $\varphi=\bigtriangleup D: X\to \IR^D$, $\varphi(x):=\big(f(x)\big)_{f\in D}$, and $Y:=\varphi(X)$. Since $D$ is dense in $C_p(X)$, the map $\varphi: X\to Y$ is a condensation of $X$ onto a separable metrizable space $Y$. By Theorem 16 of \cite{GLoM}, $Y$ has the property $(\gamma)$.  Therefore $C_p(Y)$ is Fr\'{e}chet--Urysohn. Since $D\subseteq \varphi^{\#}(C_p(Y))$ and $\varphi^{\#}\big(C_p(Y)\big)$ is homeomorphic to $C_p(Y)$, we obtain that $D$ is Fr\'{e}chet--Urysohn.

(ii)$\Ra$(i) follows from Proposition \ref{p:sR-sss}.
\end{proof}


\begin{theorem} \label{t:cp-sms}
Let $X$ be a submetrizable space such that $|X|<\mathfrak{p}$. Then $C_p(X)$ is strongly sequentially separable.
\end{theorem}

\begin{proof}
Proposition \ref{p:cp-sep} implies that $C_p(X)$ is separable. Since $|X|<\mathfrak{p}$, Theorem I.1.1 of  \cite{Arhangel} implies that $\chi(C_p(X))<\mathfrak{p}$. It follows from Theorem \ref{t:separable-p-ks} that $C_p(X)$ is  strongly sequentially separable.
\end{proof}


\begin{proposition} \label{p:sss-fu}
Let  $C_p(X)$ be a strongly sequentially separable space. %Then $C_p(X)$ is an $s_\IR$-space.
Then the following conditions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X^n$ is Lindel\"{o}f for each $n\in\w$;
\item[{\rm(ii)}] $C_p(X)$ has countable tightness;
\item[{\rm(iii)}] $C_p(X)$ is Fr\'{e}chet--Urysohn.
\end{enumerate}
\end{proposition}
\begin{proof}
The equivalence (i)$\LRa$(ii) is the well-known Arhangelskii--Pytkeev theorem \cite[II.1.1]{Arhangel}. The implication (iii)$\Ra$(ii) is clear.

(ii)$\Ra$(iii) Observe that a space is  Fr\'{e}chet--Urysohn if, and only if, it has countable tightness and each of its countable subspaces is  Fr\'{e}chet--Urysohn. Now, since $C_p(X)$ is strongly sequentially separable, Propositions \ref{p:sss-characterization} implies that each countable subspace of $C_p(X)$ is Fr\'{e}chet--Urysohn. By (ii),  $C_p(X)$ has countable tightness. Thus $C_p(X)$ is Fr\'{e}chet--Urysohn.
\end{proof}

