\section{Probability measures on $C_p(X,[-1,1])$, universally $\kappa$-measurable and universal $\kappa$-measure zero spaces} \label{sec:func-cpb}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section we prove three propositions which allows us to study $C_p$-spaces in Section \ref{sec:Cp-kR-sR}.

\begin{proposition} \label{p:mu-P-sigma-discrete}
Let $X$ be a space, and let $\mu\in P(\beta X)$. Then $\mu$ is continuous on $C_p(X,[-1,1])$ if, and only if, $\mu\in P_d(X)$.
\end{proposition}
\begin{proof}
Let $I=[-1,1]$ and $Y=C_p(X,[-1,1])$.

$(\La)$
Since $\mu\in P_d(X)$ then $\mu=\sum_{n=1}^\infty \lambda_n \delta_{x_n}$, where $x_n\in X$, $\delta_{x_n}$ is the Dirac measure at $x_n$, $\lambda_n\geq 0$ and $\sum_{n=1}^\infty \lambda_n=1$. Each measure $\delta_x$ is continuous and bounded by unity on $Y$. Then the series $\sum_{n=1}^\infty \lambda_n \delta_{x_n}$ converges uniformly to $\mu$. Therefore, $\mu$ is continuous.

$(\Ra)$ Since $\mu$ is continuous on $Y$ and $Y$ is dense in $I^X$, it follows from Factorization Lemma 0.2.3 of \cite{Arhangel} that there exists a countable $A\subseteq X$, a continuous function $\psi\: C_p(X|Y,I)\to \IR$, such that $\mu\rst Y=\psi\circ \pi_A$, where
\[
\pi_A\: Y \to C_p(X|Y,I),\ f \mapsto f{\restriction}_{A}
\]
is the projection and $C_p(X|A,I)=\pi_A(Y)$. If $\mu(A)=1$, then $\mu\in P_d(X)$.

We prove that $\mu(A)=1$. Assume the contrary, that is, $\mu(A)<1$. Then there exist $\tilde\mu,\nu\in P(\beta X)$ such that $\mu = (1-\lambda)\tilde\mu + \lambda\nu$, $\tilde\mu(A)=1$ and $\nu(A)=0$, where $\lambda=1-\mu(A)>0$. Since $A\subseteq X$ is countable, we have $\tilde\mu\in P_d(X)$. It follows from the proved implication $(\La)$ that $\tilde\mu\rst Y$ is continuous. Consequently, the functions $\nu{\restriction}_Y$ and
\[
\varphi\: C_p(X|A,I)\to \IR,\ f\mapsto \tfrac{1}{\lambda} \big(\psi(f) - (1-\lambda)\tilde\mu(f)\big)
\]
are continuous. Then $\nu{\restriction}_Y= \varphi\circ \pi_A$. Let $\mathbf{0}_A$ be the zero function on $A$. Since $\mathbf{0}_A\in C_p(X|A,I)$ and $\varphi(\mathbf{0}_A)=0$, there exists a finite $B\subseteq A$ and $\e>0$ such that $\varphi(W)\subseteq (-\tfrac{1}{2},\tfrac{1}{2})$ for the neighborhood
\[
W = \big\{ f\in C_p(X|A,I) : f(B)\subseteq (-\e,\e) \big\}
\]
of $\mathbf{0}_A$. Since $\nu(B)=0$, there exists a neighborhood $U$ of $B$ in $\bt X$ such that $\nu(U)<\tfrac{1}{2}$. Let $\hat g\in C_p(\beta X, [0,1])$ be a function such that $\hat g(B)=\{0\}$ and $\hat b(\beta X\setminus U)=1$. Put $g=\hat g{\restriction}_X$. Then $g(B)=\{0\}$ and $\nu(g)\geq \nu(\beta X\setminus U)> \tfrac{1}{2}$. On the other hand, since $g(B)=\{0\}$, we have $\pi_A(g)\in W$ and therefore $\nu(g)=\varphi\big(\pi_A(g)\big)\in (-\tfrac{1}{2},\tfrac{1}{2})$. This contradiction finishes the proof.
\end{proof}



\begin{proposition} \label{p:continuity-measure-compact-1}
Let $X$ be  a space, and let $\mu\in P(X)$. Then $\mu$ is $k$-continuous on $C_p\big(X,[-1,1]\big)$.
\end{proposition}
\begin{proof}
Let $K\subseteq C_p\big(K,[-1,1]\big)$ be a compact subspace. Since $\mu\in P(X)$, there is a $\sigma$-compact subset $Q$ of $X$ such that $\mu(Q)=1$. Let $Q=\bigcup_{n\in\w} Q_n$, where $Q_n$ is compact and $Q_n\subseteq Q_{n+1}$ for each $n\in\w$. Set $Q_{-1}:=\emptyset$, and for every $n\in\w$, define $\lambda_n :=\mu(Q_n\SM Q_{n-1})$ and
\[
\pi_n: C_p(X) \to C_p(Q_n), \quad \pi_n(f):=f\rst{Q_n}.
\]
For every $n\in\w$, choose $\mu_n\in P(Q_n\SM Q_{n-1})$ such that $\mu\rst{Q_n\SM Q_{n-1}} =\lambda_n \mu_n$. Recall that if $Z$ is a compact space, then, by the Eberlein--\v{S}mulyan--Grothendieck theorem \cite[3.139]{fabian-10}, the topology of pointwise convergence coincides with the weak topology on all uniformly bounded weakly pointwise compact subsets of the Banach space $C(Z)$. Therefore, for every $n\in\w$ and  considering $\mu_n$ as a continuous functional of the Banach space $C(Q_n)$, we obtain that $\mu_n$ is continuous on the compact set $\pi_n (K)\subseteq C_p(Q_n,[-1,1])$. Since $\mu_n(h)=\mu_n(\pi_n(h))$ for $h\in C_p(X,[-1,1])$, we obtain that $\mu_n$ is continuous on $K$ and $\|\mu_n{\restriction}_{K}\|\leq 1$. As $\sum_{n\in\w} \lambda_n =1$, it easily follows that the uniformly convergent series
\[
\mu\rst{K} =\sum_{n\in\w} \lambda_n \mu_n{\restriction}_{K}
\]
is continuous.
\end{proof}

\begin{proposition} \label{p:continuity-measure-compact}
Let $X$ be  a space, and let $\mu\in P(\beta X)$. Then $\mu$ is $s$-continuous on $C_p\big(X,[-1,1]\big)$ if, and only if, $\mu\in P_\sigma(X)$.
\end{proposition}

\begin{proof}
$(\Ra)$ Suppose for a contradiction that $\mu\notin P_\sigma(X)$. Then $\mu(K)>0$ for some zero-set $K\subset \beta X\SM X$. Therefor, we can find a sequence $(f_n)_n\subseteq C_p(\beta X,[0,1])$ that converges pointwise to the characteristic function $\chi_K$ of $K$. Put $g_n:=f_n\rst{X}$. Then $(g_n)_n$ converges pointwise to the zero function $\mathbf{0}_X$ on $X$ and $\lim_{n\to\infty} \mu(g_n)=\mu(K)>0$. Therefore $\mu$ is discontinuous on the sequence $\{\mathbf{0}_X\}\cup\{g_n:n\in\w\}$. A contradiction.
\smallskip

$(\La)$ Let $K\subseteq C_p\big(K,[-1,1]\big)$ be a metrizable compact subspace. Set $Y:=C_p\big(K,[-1,1]\big)$ and define
\[
j: X\to Y, \quad j(x)(f):=f(x).
\]

The Banach space $C(K)$ is Polish. Therefore the space $C_p(K)$ is Souslin, and hence its closed subspace $Y$ is Souslin as well. Therefore, by Proposition \ref{p:px:3}, $Y$ is universally measurable.
%
From Proposition \ref{p:px:ci} it follows that $\nu=P(\beta j)(\mu)\in P(Y)$. The measure $\nu$ is determined by the fact that
\[
\nu(g) = \mu(g\circ j)\ \ \text{ for any }g\in C_p(Y,[-1,1]).
\]
Let
\[
i:K\to C_p(Y,[-1,1]),\ \ i(f)(h):=h(f),
\]
be the canonical embedding. Then $i(K)$ is a compact subset of $C_p(Y,[-1,1])$.
From Proposition \ref{p:continuity-measure-compact-1} it follows that the restriction $\nu\rst{i(K)}$ of $\nu$ onto $i(K)$ is continuous.

We claim that $\mu{\restriction}_K = \nu{\restriction}_{i(K)} \circ i$, that is, $(\nu\circ i)(f)=\mu(f)$ for $f\in K$. For every $x\in X$, we have
\[
(i(f)\circ j)(x)=i(f)(j(x))=j(x)(f)=f(x).
\]
Therefore $i(f)\circ j=f$. Hence
\[
(\nu\circ i)(f)= \nu(i(f))=\mu(i(f)\circ j)=\mu(f)\quad (f\in K)
\]
that proves the claim.

Since $\mu{\restriction}_K =  \nu{\restriction}_{i(K)} \circ i$ and $\nu{\restriction}_{i(K)}$ is continuous, it follows that $\mu$ is continuous on $K$.
\end{proof}

For a space $X$, we set
\[
P_\kappa(X):=\big\{ \mu\in P(\beta X): \mu\text{ is $k$-continuous on }C_p\big(X,[-1,1]\big)\big\}.
\]
Propositions \ref{p:continuity-measure-compact-1} and \ref{p:continuity-measure-compact} immediately imply the following assertion.

\begin{proposition} \label{p:psi=pka}
Let $X$ be a space. Then:
\begin{enumerate}
\item[{\rm(i)}] $P(X)\subseteq P_\kappa(X) \subseteq P_\sigma(X)$;
\item[{\rm(ii)}]  if $C_p\big(X,[-1,1]\big)$ is an $sk$-space, then $P_\kappa(X)=P_\sigma(X)$.
\end{enumerate}
\end{proposition}

%In \cite{GR-kappa} it is proved that $P_\kappa(X)$ is $\kappa$-space, $\kappa X=\beta X\cap P_\kappa(X)$, and $P_\kappa(X)=P_\kappa(\kappa X)$. In \cite{BanakhChigogidzeFedorchuk2003} it is proved that $P_\sigma(X)$ is a realcompact space, $\nu X=\beta X\cap P_\sigma(X)$, and $P_\sigma(X)=P_\sigma(\nu X)$.\footnote{\color{red}We do not use these unclear remarks at al, and hence they should be removed - one can add this to the kappa-spaces article as remark}

Being motivated by the notions of universally $\si$-measurable spaces and universal $\si$-measure zero spaces, we shall say that a space $X$ is
\begin{enumerate}
\item[$\bullet$] {\em universally $\kappa$-measurable} if $P_\kappa(X)=P(X)$;
\item[$\bullet$]  {\em universal $\kappa$-measure zero} if $P_\kappa(X)=P_d(X)$.
\end{enumerate}
Clearly, any universal $\kappa$-measure zero space is universally $\kappa$-measurable.



