\section{$C_p(X)$ which are $k_\IR$-spaces and $s_\IR$-spaces} \label{sec:Cp-kR-sR}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

This section is devoted to the $C_p$-part of Problem \ref{prob:Cp-kR-sR}. Following \cite{GR-kappa}, a space $X$ is called a {\em $\kappa$-space} if it is closely embedded into $C_p(Y)$ for some $k_\IR$-space $Y$. For numerous characterizations of $\kappa$-spaces, see \cite{GR-kappa}.


\begin{proposition}\label{p:Cp-kR-necessary}
If $C_p(X)$ is a $k_\IR$-space, then $X$ has the property $(\kappa)$, $X$ is universal $\kappa$-measure zero, and $X$ is a $\kappa$-space whose compact subsets are scattered.
\end{proposition}
\begin{proof}
Since $C_p(X)$ is a $k_\IR$-space and $X$ is closely embedded into $C_p\big(C_p(X)\big)$, the space $X$ is a $\kappa$-space. As $C_p(X)$ is also an Ascoli space, Theorem \ref{t:Cp-Ascoli} implies that $X$ has the property $(\kappa)$.  Let $K$ be a  compact subset of $X$. Since the property $(\kappa)$ is hereditary \cite{Sak2}, $K$ also has the property $(\kappa)$. Therefore, $K$ is scattered by Proposition 2.5 of \cite{GGKZ}.

To show that $X$ is a universal $\kappa$-measure zero space, let $\mu\in P_\kappa(X)$. By the definition of the space $P_\kappa(X)$, $\mu$ is continuous on each compact set $K\subseteq C_p\big(X,[-2,2]\big)$. Therefore, $\mu$ is continuous on each compact set $K\subseteq C_p\big(X,(-2,2)\big)$. Taking into account that $C_p(X)$ and $C_p\big(X,(-2,2)\big)$ are homeomorphic, it follows that $\mu$ is $k$-continuous on the $k_\IR$-space $C_p\big(X,(-2,2)\big)$. Therefore $\mu$ is continuous on $C_p\big(X,(-2,2)\big)$. Hence, $\mu$ is continuous on $C_p\big(X,[-1,1]\big)$. By Proposition \ref{p:mu-P-sigma-discrete}, we have $\mu\in P_d(X)$, as desired.
\end{proof}





%We do not know whether the converse is true.
