%Let $X$ be  a \kk-space with the property $(\kappa)$. Is then $C_p(X)$ a $k_\IR$-space?
%\end{problem}


Let $X$ and $Y$ be spaces, and let $T:X\to Y$ be a continuous mapping. Then the adjoint mapping $T^{\#}: C_p(Y)\to C_p(X)$ is continuous by Proposition 0.4.6(1) of \cite{Arhangel}. If $T$ is surjective, then, by Proposition 0.4.6(2) of \cite{Arhangel}, $T^{\#}$ is an embedding. Note also that, by Proposition 0.4.8(3) of \cite{Arhangel}, $T^{\#}$ is an embedding onto a dense subspace of $C_p(X)$ if, and only if, $T$ is a condensation.

\begin{definition}
A condensation $T:X\to Y$  is said to be a {\em $k^{\#}_\IR$-condensation} (resp., a {\em
$k^{\#}$-condensation, an $s^{\#}_\IR$-condensation or an $s^{\#}$-condensation}) if  $T^{\#}\big(C_p(Y)\big)$ is $k_\IR$-dense (resp., $k$-dense, $s_\IR$-dense or sequentially dense) in $C_p(X)$.
\end{definition}

Any $k^{\#}$-condensation is a $k^{\#}_\IR$-condensation, and each $s^{\#}$-condensation is an $s^{\#}_\IR$-condensation.

\begin{proposition} \label{p:kR-condensation-kR}
Let $T:X\to Y$ be a $k^{\#}_\IR$-condensation (in particular, a $k^{\#}$-condensation). If $C_p(Y)$ is a $k_\IR$-space, then so is $C_p(X)$.
\end{proposition}

\begin{proof}
Since $T$ is a $k^{\#}_\IR$-condensation, the $k_\IR$-space $C_p(Y)$  is homeomorphic to a $k_\IR$-dense linear subspace of $C_p(X)$. Thus, by Theorem \ref{t:home-kRe},  $C_p(X)$ is a $k_\IR$-space.
\end{proof}



\begin{proposition} \label{p:sR-condensation-sR}
Let $T:X\to Y$ be an $s^{\#}_\IR$-condensation (in particular, an $s^{\#}$-condensation). If $C_p(Y)$ is an $s_\IR$-space, then so is $C_p(X)$.
\end{proposition}

\begin{proof}
Since $T$ is an $s^{\#}_\IR$-condensation, the $s_\IR$-space $C_p(Y)$  is homeomorphic to an $s_\IR$-dense linear subspace of $C_p(X)$. Thus, by Theorem \ref{t:home-sRe},  $C_p(X)$ is an $s_\IR$-space.
\end{proof}


To obtain a concrete example of $C_p(X)$ which is a $k_\IR$-space we need the next lemma.



