\begin{lemma} \label{l:one-point-k-conden}
Let $\alpha D=D\cup\{d_\infty\}$ be a one-point compactification of an infinite discrete set $D$, and let $X$ be the set $D\cup\{d_\infty\}$ endowed with a topology $\tau$ such that the identity map $T:X\to \alpha D$ is a condensation. Then  $T$ is a $k^{\#}$-condensation.
%
If $|X|$ is not sequential, then $T$ is an $s^{\#}_\IR$-condensation.
\end{lemma}
\begin{proof}
Let $f\in C_p(X)$. For every $a,b\in\IR$, let $I(a,b):=[a,b]$ if $a\leq b$, and $I(a,b):=[b,a]$ if $a>b$. Set
\[
K:=\big\{ h\in \IR^X: h(x)\in I\big(f(d_\infty),f(x)\big)  \; \mbox{ for all }\; x\in X\big\}.
\]
Then $K$ is a compact subset of $\IR^X$. It is easy to see that $K\subseteq C_p(X)$.
Note that $f(d_\infty)=g(d_\infty)$ for every $g\in K$.

We show that $f\in \overline{K\cap C_p(\alpha D)}$. Since $f\in K$, it suffices to verify that $K\cap C_p(\alpha D)$ is dense in $K$. Put
\[
M = \{ g\in K : |\{x\in D: g(x)\neq f(d_\infty)\}| < \omega \}.
\]
Then $M\subseteq K\cap C_p(\alpha D)$ and $M$ is dense in $K$. In particular, $f\in K\cap \overline{K\cap C_p(\alpha D)}$. Therefore $C_p(\alpha D)=T^{\#}(C_p(\alpha D))$ is $k$-dense in $C_p(X)$. Thus $T$ is a $k^{\#}$-condensation.

Assume that $|X|$ is not a sequential cardinal. The compact set $K$ is homeomorphic to the Tychonoff cube $[0,1]^\tau$, where $\tau\leq |X|$. Therefore, $\tau$ is not sequential, too.
It follows from Proposition \ref{p:noble:fc-prod} that $K$ is an $s_\IR$-space. Therefore, $C_p(\alpha D)=T^{\#}(C_p(\alpha D))$ is $s_\IR$-dense in $C_p(X)$.
\end{proof}


\begin{theorem} \label{t:exa-kR-Cp}
Let $X$ be a space with one non-isolated point. Then $C_p(X)$ is a $k_\IR$-space. If $|X|$ is not sequential, then $C_p(X)$ is an $s_\IR$-space.
\end{theorem}

\begin{proof}
Let $d_\infty$ be the non-isolated point of $X$, and let $D=X\SM \{d_\infty\}$. Let $Y=D\cup \{d_\infty\}$ be the one point compactification of the discrete space $D$. Then the identity map $T:X\to Y$ is a condensation. By Lemma \ref{l:one-point-k-conden}, $T$ is a $k^{\#}$-condensation and if $|X|$ is not a sequential cardinal, then $T$ is an $s^{\#}_\IR$-condensation. Since $Y$ is a scattered compact space, then, by Theorem III.1.2 of  \cite{Arhangel},  $C_p(Y)$ is a Fr\'{e}chet--Urysohn space. From Theorem \ref{t:home-kRe} it follows that $C_p(X)$ is a $k_\IR$-space. If $|X|$ is not sequential, then, by Theorem \ref{t:home-sRe},  the space $C_p(X)$ is an $s_\IR$-space.
\end{proof}


\begin{theorem} \label{t:lc-kR-Cp}
Let $X=\bigoplus_{\alpha\in \AAA}X_\alpha$, where all $X_\alpha$ are countable spaces. Then $C_p(X)$ is a $k_\IR$-space. If $|X|$ is not sequential, then $C_p(X)$ is an $s_\IR$-space.
\end{theorem}
\begin{proof}
Since $C_p(X_\alpha)$ is metrizable for $\alpha\in \AAA$, Proposition \ref{p:noble:fc-prod}(i) implies that $C_p(X)$ is a $k_\IR$-space.
If $|X|$ is not a sequential cardinal, then Proposition \ref{p:noble:fc-prod}(ii) implies that $C_p(X)$ is an $s_\IR$-space.
\end{proof}



\begin{theorem} \label{t:lP-kR-Cp}
Let $X=\bigoplus_{\alpha\in \AAA}X_\alpha$, where all $X_\alpha$ are Lindel\"{o}f $P$-spaces. Then $C_p(X)$ is a $k_\IR$-space. If $|\AAA|$ is not sequential, then $C_p(X)$ is an $s_\IR$-space.
\end{theorem}
\begin{proof}
Let $Y=X\cup\{x_{\infty}\}$ be a one point Lindel\"{o}fication of the space $X$: sets of the form $Y\setminus \bigcup_\alpha\{X_\alpha\in \cB\}$, where $\cB\subseteq\AAA$ and $|\cB|\leq\om$, form a base at the point $x_{\infty}$. The space $Y$ is a Lindel\"{o}f $P$-space. Therefore, by Problem 135 of  \cite{Tkachuk-2}, the space $C_p(Y)$ is Fr\'{e}chet--Urysohn. Any $\si$-product in the product $\prod_{\alpha\in \AAA}C_p(X_\alpha)=C_p(X)$ is embedded in $C_p(Y)$, so it is a Fr\'{e}chet--Urysohn space. It remains to apply Proposition \ref{p:noble:prod}.
\end{proof}


\begin{problem}
Let a space $X$ be such that $C_p(X)$ is a $k_\IR$-space and $|X|$ is not sequential. Is then $C_p(X)$ an $s_\IR$-space?
\end{problem}


\begin{problem}
Is there an example in ZFC of a   space $X$ such that $C_p(X)$ is a $k_\IR$-space and $C_p(X)$ is not an $s_\IR$-space?
\end{problem}


\begin{problem} \label{pr:Rc-sr}
Is  $\IR^{\mathfrak{c}}$ an $s_\IR$-space?
\end{problem}

Note that Problem \ref{pr:Rc-sr} is equivalent to the Keisler--Tarski problem \cite{KeislerTarski1963}, which was discussed in Section \ref{sec:s-R-spaces}.

As the statement below shows, for many cases of $C_p$-spaces, the property of being an $s_\IR$-space coincides with the property of being a $k_\IR$-space.

\begin{proposition} \label{p:cp-sR=kR}
Let a space $X$ satisfy the conditions of Proposition \ref{p:sk:cp}. Then $C_p(X)$ is a $k_\IR$-space if and only if $C_p(X)$ is an $s_\IR$-space.
\end{proposition}
\begin{proof}
It follows from Proposition \ref{p:sk:cp} that $C_p(X)$ is $sk$-space. It remains to apply Proposition \ref{p:sk-space}(ii).
\end{proof}

\begin{problem}
Is it possible to prove Proposition \ref{p:cp-sR=kR} in ZFC?
\end{problem}

Till the end of this section we consider the case when $C_p(X)$ is/or not an $s_\IR$-space.



\begin{proposition}\label{p:sR-Cp-realcompact}
\begin{enumerate}
\item[{\rm(i)}] If $X$ is an $s_\IR$-space, then $C_p(X)$ is realcompact.
\item[{\rm(ii)}] If $C_p(X)$ is an $s_\IR$-space, then $X$ is realcompact.
\end{enumerate}
\end{proposition}
\begin{proof}
(i) Since, by  Proposition \ref{p:sR-R-tightness}, the $\IR$-tightness of  $X$ is countable, Corollary~II.4.17 of \cite{Arhangel} implies that $C_p(X)$ is realcompact.

(ii) follows from (i) and the fact that $X$ is closely embedded into $C_p(C_p(X))$.
\end{proof}





\begin{theorem} \label{t:sss-sr}
Let  $C_p(X)$ be a strongly sequentially separable space. Then $C_p(X)$ is an $s_\IR$-space, and the following conditions are equivalent:
\begin{enumerate}
\item[{\rm(i)}] $X^n$ is Lindel\"{o}f for each $n\in\om$;
\item[{\rm(ii)}] $C_p(X)$ has countable tightness;
\item[{\rm(iii)}] $C_p(X)$ is Fr\'{e}chet--Urysohn.
\end{enumerate}
\end{theorem}
\begin{proof}
Propositions \ref{p:sR-sss} and \ref{p:sss-characterization} imply that $C_p(X)$ is an $s_\IR$-space. The equivalences  (i)$\LRa$(ii)$\LRa$(iii) follow from Proposition \ref{p:sss-fu}.
\end{proof}

\begin{problem} \label{pr:sms---sr=fu}
Does there exist a separable metrizable space $X$ for which $C_p(X)$ is an $s_\IR$-space which is not Fr\'{e}chet--Urysohn?
\end{problem}

The following assertion follows from Theorems \ref{t:cp-sms} and \ref{t:sss-sr}.

\begin{theorem} \label{t:cp-p-sr}
Let $X$ be a submetrizable space and $|X|<\mathfrak{p}$. Then $C_p(X)$ is a strongly sequentially separable $s_\IR$-space.
\end{theorem}


\begin{theorem} \label{t:Cp-sR-space-necessary}
If $C_p(X)$ is an $s_\IR$-space, then $X$ is a realcompact, universal $\sigma$-measure zero space and has the property $(\kappa)$.
\end{theorem}

\begin{proof}
Since $C_p(X)$ is an $s_\IR$-space, Proposition \ref{p:sR-Cp-realcompact} implies that $X$ is realcompact.
Since any $s_\IR$-space is a $k_\IR$-space,  Proposition \ref{p:Cp-kR-necessary} implies that $X$ has the property $(\kappa)$.

To show that $X$ is a universal $\si$-measure zero space, let $\mu\in P_\sigma(X)$.  Proposition \ref{p:continuity-measure-compact} implies that $\mu$ is continuous on each metrizable compact set $K\subseteq C_p\big(X,[-2,2]\big)$.
Therefore, $\mu$ is continuous on each metrizable compact set $K\subseteq C_p\big(X,(-2,2)\big)$.
Taking into account that $C_p(X)$ and $C_p\big(X,(-2,2)\big)$ are homeomorphic, it follows that $\mu$ is $s$-continuous on the $s_\IR$-space $C_p\big(X,(-2,2)\big)$. Therefore $\mu$ is continuous on $C_p\big(X,(-2,2)\big)$.
Hence, $\mu$ is continuous on $C_p\big(X,[-1,1]\big)$.
By Proposition \ref{p:mu-P-sigma-discrete}, $\mu\in P_d(X)$, as desired.
\end{proof}



Recall (see \cite[\S~40.III]{Kuratowski}) that a separable metrizable space $X$ is said to be a {\em $\lambda$-space} if every countable subset of $X$ is a $G_\delta$-set of $X$.  In ZFC, there exists a $\lambda$-space of real numbers of cardinality $\w_1$ \cite[p.~215]{Miller1984}.
A {\em Sierpi\'{n}ski set} is an uncountable subset of $\IR$ whose intersection with every measure-zero (= Lebesgue zero) set is countable. The existence of Sierpi\'{n}ski  sets is independent of the axioms of ZFC. In \cite{Sierpinski}, Sierpi\'{n}ski  showed that they exist in $\IR$ if the continuum hypothesis is true. On the other hand, they do not exist if Martin's axiom for $\aleph_1$ is true.

\begin{proposition} \label{p:Cp-Sierpinski}
If $X$ is a Sierpi\'{n}ski set, then $C_p(X)$ is an Ascoli space which is not an $s_\IR$-space. Consequently, under $(CH)$, there exists a separable metrizable space $X$ such that $C_p(X)$ is an Ascoli space but not a $k_\IR$-space.
\end{proposition}
\begin{proof}
Every Sierpi\'{n}ski set is a $\lambda$-space \cite[10.1]{Miller1984}. Hence, by Theorem 3.2 of \cite{Sak2}, $X$ has the property $(\kappa)$. Therefore, by Theorem \ref{t:Cp-Ascoli}, $C_p(X)$ is an Ascoli space.
Since a Sierpi\'{n}ski set is an uncountable subset of $\IR$ whose intersection with every Lebesgue zero set is countable, it follows that the Lebesgue measure of  $X$ is not equal to zero. Since the Lebesgue measure is continuous, the space $X$ is not a universal measure zero set. It follows from Theorem \ref{t:px:polish} that $X$ is not a universal $\sigma$-measure zero space. Therefore, by Theorem \ref{t:Cp-sR-space-necessary}, $C_p(X)$ is not an $s_\IR$-space.

It follows from Proposition \ref{p:cp-sR=kR} that $C_p(X)$ is not a $k_\IR$-space.
\end{proof}

\begin{remark}
In \cite{Mi73}, Michael constructed an $\aleph_0$-space which is a $k_\IR$-space but not a $k$-space. In Problem 6.8 of \cite{BG} the next question is posed: {\em Does there exist a cosmic (or an $\aleph_0$-space) which is Ascoli but not a  $k_\IR$-space}? Since a Sierpi\'{n}ski set is cosmic, the space $C_p(X)$ is also cosmic. Therefore, under the continuum hypothesis $\mathrm{(CH)}$, Proposition \ref{p:Cp-Sierpinski} gives a positive answer to this question.
\end{remark}


\begin{problem}
Is there an example in ZFC of a  separable metrizable space $X$ such that $X$ has the property $(\kappa)$ ($X$ is a $\lambda$-space) but not universal measure zero?
\end{problem}

\begin{problem}
Is there a universal measure zero separable metrizable space $X$ such that $C_p(X)$ is  Ascoli but not an $s_\IR$-space?
\end{problem}

