\section{Shulga intervals and their intersections}
\label{sec_intersec}
In this section we rephrase the Shulga algorithm in Definition \ref{def:shulga} in terms of intersection of certain intervals. Analyzing the arrangements of these intervals is the key for many of our results. Along the way we will rephrase some results and proofs from \cite{shulga}. In particular, the analysis that appears in this section does not rely on Theorem \ref{thm:shulga} and offers a self-contained proof of it.

For every $n\geq1$ and positive integers $b_1,\ldots,b_n\geq2$ and $c_1,\ldots,c_n$, define for every $1\leq k \leq n$ the intervals
\begin{equation}
\begin{aligned}
\label{cn_bn_def}
%B_{k}&\defeq\Bigl[[0;b_1,\ldots,b_{k}-1]+[0;c_1,\ldots,c_{k-1}],  [0;b_1,\ldots,b_{k}]+[0;c_1,\ldots,c_{k-1}]\Bigr)\,,\\
B_{k}&\defeq\bigl[[0;b_1,\ldots,b_{k}-1],[0;b_1,\ldots,b_{k}]\bigr)+[0;c_1,\ldots,c_{k-1}]\,,\\
C_{k}&\defeq\bigl[[0;c_1,\ldots,c_{k}],[0;c_1,\ldots,c_{k}+1]\bigr)+[0;b_1,\ldots,b_{k}]\,.
\end{aligned}
\end{equation}
Note that for odd $k$ the left and right endpoints of these intervals interchange according to our Convention \ref{conv}. Also, define
\begin{equation*}
    A_n\defeq\bigcap\limits_{k=1}^{n}(B_k\cap C_k)\,,
\end{equation*}
and set $A_0\defeq B_0\defeq C_0\defeq [0,1]$.
\begin{lem}
\label{large_intersec_lem}
For every $n\geq0$ and positive integers $b_1,\ldots,b_n\geq2$ and $c_1,\ldots,c_n$, if %\begin{equation*}%\label{intersec_prop_inf}
$
\alpha\in A_n
$
%\end{equation*}
then the first $n$ steps in Definition \ref{def:shulga} are well defined and yield the two sequences $b_1,\ldots,b_{n}$ and $c_1,\ldots,c_{n}$.
%\alpha = [0;b_1,\ldots,b_k] + [0;c_1,\ldots,c_k],
%\begin{equation*}
%\begin{aligned}
%    b_k &= a_k(\alpha-[0;c_1,\ldots,c_n])\,,\quad\textrm{and} \\
%    c_k &= a_k(\alpha-[0;b_1,\ldots,b_n])\,.
%\end{aligned}
%\end{equation*}
%if and only if
\end{lem}

\begin{proof}
By induction on $0\leq k\leq n-1$. The base case $k=0$ is trivial. Assume that the first $k$ steps in Definition \ref{def:shulga} are $b_1,\ldots,b_{k}$ and $c_1,\ldots,c_{k}$. Since $\alpha\in B_{k+1}$ one has
\begin{equation*}
\alpha-[0;c_1,\ldots,c_{k}]\in\bigl[[0;b_1,\ldots,b_{k+1}-1],[0;b_1,\ldots,b_{k+1}] \bigr),
\end{equation*}
and hence by \eqref{cyl_def} the $(k+1)$th partial quotient of $\alpha-[0;c_1,\ldots,c_{k}]$ is well defined and satisfies
$$
b_{k+1}=a_{k+1}(\alpha-[0;c_1,\ldots,c_{k}])+1\,.
$$ 
In particular, we have $\alpha-[0;c_1,\ldots,c_{k}]\neq[0;b_1,\ldots,b_{k}]$, and the $(k+1)$th digit of the first sequence in Definition \ref{def:shulga} is well defined and equals $b_{k+1}$. Similarly, since $\alpha\in C_{k+1}$, one has
\begin{equation*}
\alpha-[0;b_1,\ldots,b_{k+1}]\in\bigl[[0;c_1,\ldots,c_{k+1}],[0;c_1,\ldots,c_{k+1}+1]\bigr)
\end{equation*}
and hence by \eqref{cyl_def} the $(k+1)$th partial quotient of $\alpha-[0;b_1,\ldots,b_{k+1}]$ is well defined and satisfies
$$
c_{k+1}=a_{k+1}(\alpha-[0;b_1,\ldots,b_{k+1}])\,,$$
which again agrees with Definition \ref{def:shulga}. This finishes the induction.
\end{proof}

%Since the intervals $B_n(a)$ are pairwise disjoint, and similarly for the intervals $C_n(a)$, the sequences $b_n$ and $c_n$ in the condition of Lemma \ref{large_intersec_lem}, if exist, are unique. The fact that such sequences exist follows from the property (\ref{shulga_cyl_long}) 
The following lemma plays a key role in the proofs of Theorems \ref{Th1} and \ref{Th2}. Only the last part of it is new and the rest were established by Shulga \cite{shulga}, who used equivalent formulations. However, in order to practice the usefulness of Lemma \ref{large_intersec_lem}, we will provide a self-contained proof for all five parts. %From this point on it will be convenient to use a fixed notation for the denominators of the relevant continued fraction expansion.

\begin{lem}
\label{Cn_Bn_lem}
Suppose that $b_1,\ldots,b_n\geq2$ and $c_1,\ldots,c_n$ are positive integers, and let 
\begin{equation}
    \label{eq:fractions}
    \frac{p_k}{q_k} \defeq [0;b_1,\ldots,b_k] \,,\quad \textrm{and}\quad \frac{s_k}{t_k} \defeq [0;c_1,\ldots,c_k]
\end{equation}
be the numerator and denominator of the corresponding continued fraction. We have:
\begin{enumerate}[wide, labelindent=0pt]
    \item \label{item:cnbn}$B_n\cap C_n\ne\emptyset$ if and only if
        \begin{equation}
        \label{CnBn_ineq1}
        \frac{1}{t_{n-1}(t_n+t_{n-1})}<\frac{1}{q_n(q_n-q_{n-1})}\,.
        \end{equation}
    \item \label{item:cncn1}
    $C_n\cap C_{n-1}\ne\emptyset$ 
    if and only if \begin{equation}
        \label{CnCn1_ineq0}
        \frac{1}{q_{n}q_{n-1}}<\frac{c_{n}}{(t_{n}+t_{n-1})(t_{n-1}+t_{n-2})}\,.
    \end{equation}
    \item \label{item:bncn1_lem}
        $B_n\cap C_{n-1}\ne\emptyset$ if and only if
        \begin{equation*}\label{bncn1_ineq04}
            \frac{1}{q_nq_{n-1}}<\frac{1}{t_{n-1}(t_{n-1}+t_{n-2})}\,.
        \end{equation*}
    \item \label{item:cn_gt_lem}
        If $B_n\cap C_n\cap C_{n-1}\ne\emptyset$ then
        \begin{equation*}
        \label{CnCn1_ineq03}
                c_{n}>(1+[0;c_{n-1},\ldots,c_1])(b_{n}-1+[0;b_{n-1},\ldots,b_1])\,.
        \end{equation*}
    \item \label{bn_gt_lem}
    If $B_{n-1}\cap C_n\cap C_{n-1}\ne\emptyset$ then
