We are now ready to rephrase and prove Theorem \ref{thm:shulga}.

\begin{lem}
Given $\alpha\in[0,1]$, either there exist unique $n\geq0$ and finite sequences $b_1,\ldots,b_n$ and $c_1,\ldots,c_n$ such that $\alpha\in A_n$ and 
\begin{equation*}
\label{alpha_fin_decomp}
\alpha=[0;b_1,\ldots,b_n]+[0;c_1,\ldots,c_n]
\end{equation*}
or there exist unique infinite sequences $b_1,b_2,\ldots$ and $c_1,c_2,\ldots$ such that
%I prefer not to have footnotes. If this is important we should add it to the main text. However, I think that the Lemma which repharases the algorithm in terms of Shulga intervals implies this uniqueness since different intervals give different outcome
%\footnote{Of course, the intersection of the intervals $A_n$ is either empty or has one point, as the length of the intervals $B_n$ and $C_n$ tends to zero as $n\to\infty$.} 
$$
\alpha\in \bigcap_{n=0}^\infty A_n\,.
$$
\end{lem}

\begin{proof}
%One can easily verify that for any $\alpha\in(0,1]$ there are integer numbers $c_1\ge b_1\ge 2$ such that $\alpha\in I_1$. 
By induction on $n$. Let $n\ge 1$, $b_1,\ldots, b_n\geq2$ and $c_1,\ldots, c_n$ satisfy $\alpha\in A_n$. Recall that by definition \eqref{eq:bncn} one has
\begin{equation*}
    \begin{aligned}
        B_{n}&=\bigl[[0;b_1,\ldots,b_{n}-1], [0;b_1,\ldots,b_{n}]\bigr)+[0;c_1,\ldots,c_{n-1}]\,,\\
        C_{n}&=\bigl[[0;c_1,\ldots,c_{n}],[0;c_1,\ldots,c_{n}+1]\bigr)+[0;b_1,\ldots,b_{n}]\,,
    \end{aligned}
\end{equation*}
and for every two integers $b\geq2$ and $c\geq 1$ let this notation be extended by setting
\begin{align*}
B_{n+1}(b)&=\bigl[[0;b_1,\ldots,b_{n},b-1],[0;b_1,\ldots,b_{n},b]\bigr)+[0;c_1,\ldots,c_{n}]\,,\\
C_{n+1}(b,c)&=\bigl[[0;c_1,\ldots,c_{n},c],[0;c_1,\ldots,c_{n},c+1]\bigr)+[0;b_1,\ldots,b_{n},b]\,.
\end{align*}
It is enough to show that
\begin{align}
\label{subset_C_inB_n1}
C_n&\sub\bigcup\limits_{b=2}^{\infty}B_{n+1}(b)\cup\{[0;b_1,\ldots,b_{n}]+[0;c_1,\ldots,c_{n}]\}\,,\quad\textrm{and}\\
\label{subset_Bn1_inC_n1}
B_{n+1}(b)&\sub\bigcup\limits_{c=1}^{\infty}C_{n+1}(b,c)\,,\quad\textrm{for any $b$ such that $B_{n+1}(b)\cap C_n\neq\emptyset$}\,.
\end{align}
%By Statement 3 of Proposition \ref{int_prop}, 
Since the unions in \eqref{subset_C_inB_n1} and \eqref{subset_Bn1_inC_n1} are disjoint, this also implies the uniqueness in the statement of the theorem. It follows from \eqref{eq:mon} that the right-hand sides of \eqref{subset_C_inB_n1} and \eqref{subset_Bn1_inC_n1} are the intervals
\begin{align*}
&\bigl[[0;b_1,\ldots,b_{n}], [0;b_1,\ldots,b_{n}+1]\bigr]+[0;c_1,\ldots,c_{n}]\,,\quad\textrm{and}\\
&\bigl([0;c_1,\ldots,c_{n}],[0;c_1,\ldots,c_{n}+1]\bigr]+[0;b_1,\ldots,b_{n},b]\,.
\end{align*}
respectively. Thus, the containments in \eqref{subset_C_inB_n1} and \eqref{subset_Bn1_inC_n1} are equivalent to the inequalities
\begin{align}
\label{eq:first}
[0;b_1,\ldots,b_n+1]+[0;c_1,\ldots,c_{n}]&\ge[0;b_1,\ldots,b_n]+[0;c_1,\ldots,c_{n}+1]\,,\quad\textrm{and}\\
\label{eq:second}
[0;b_1,\ldots,b_{n},b]+[0;c_1,\ldots,c_{n},1]&> [0;b_1,\ldots,b_{n},b-1]+[0;c_1,\ldots,c_{n}]\,.
\end{align}
Similarly to the way it was done in the proof of Lemma \ref{Cn_Bn_lem}, the inequality \eqref{eq:first} can rewritten as
\begin{equation}
\label{tn_le_qn}
\frac{1}{t_n(t_n+t_{n-1})}\le\frac{1}{q_n(q_n+q_{n-1})}\,.
\end{equation}
Lemma \ref{Cn_Bn_lem}\eqref{item:cn_gt_lem} implies that $c_k\geq b_k$ for all $1\leq k\leq n$. Therefore, from the recurrence law \eqref{eq:convergents} one can easily deduce that $t_k\geq q_k$ for every $1\leq k \leq n$. In particular, this holds for $k=n$ and $k=n-1$, which implies \eqref{tn_le_qn}. 

As for \eqref{eq:second}, fix any $b$ that satisfies $B_{n+1}(b)\cap C_n\neq\varnothing$. Setting $b_{n+1}=b$ and arguing as before, shows that \eqref{eq:second} can be rewritten as
\begin{equation*}
\label{qnq_qn_letn_tn1}
\frac{1}{q_{n+1}(q_{n+1}-q_{n})}<\frac{1}{t_n(t_n+t_{n-1})}\,.
\end{equation*}
The last inequality follows from Lemma \ref{Cn_Bn_lem}\eqref{item:bncn1_lem} with $n+1$ instead of $n$. Indeed, as $b_{n+1}\ge 2$, one has $q_{n+1}-q_n>q_n$ and therefore
\begin{equation*}
\label{qnq_qn_letn_tn1_2}
\frac{1}{q_{n+1}(q_{n+1}-q_{n})}<\frac{1}{q_{n+1} q_{n}}\,.
\end{equation*}
.
\end{proof}

%Thus, we provided an independent proof of properties (\ref{shulga_cyl_long}) and (\ref{eq:main-shulga}). 
Starting from this point and until the end of this section and through Sections \ref{sec:rationals} and \ref{sec:growth}, given a real number $\alpha$, the sequences $b_n(\alpha)$ and $c_n(\alpha)$ stand for the corresponding digits that arise from Shulga's algorithm with input $\alpha$. We will omit the dependency on $\alpha$ when it does not create ambiguity.

Now we are ready to prove Theorem \ref{Th1}.
\begin{proof}[Proof of Theorem 4]
Assume by contradiction that for some $n\geq2$ the partial quotients do not satisfy $c_n>b_n$. By \eqref{eq:main-shulga} this means that $c_n=b_n$. Denoting 
\begin{align*}
    x&=[0;b_{n-1},\ldots,b_1]\,,\\ 
    y&=[0;c_{n-1},\ldots,c_1]\,,\quad\textrm{and}\\
    z&=c_n=b_n\,,
\end{align*}
and substituting it into Lemma \ref{Cn_Bn_lem}\eqref{item:cn_gt_lem} and Lemma \ref{Cn_Bn_lem}\eqref{bn_gt_lem} gives
\begin{align*}
%\label{ineq_cn_eq_bn_sip1}
z&>(1+y)(z-1+x)\,,\quad\textrm{and}\\
%\label{bn_ge_ineq_main_symp}
z&>\left(1+\frac{1}{z}\right)\left(1+\frac{1}{y}\right)(1-x)-1\,,
\end{align*}
respectively. This is a contradiction since these inequalities can be rearranged into
\begin{align*}
%\label{ab_and_ba}
z&<\left(1+\frac{1}{y}\right)(1-x)\,,\quad\textrm{and}\\
z&>\left(1+\frac{1}{y}\right)(1-x),
\end{align*}    
respectively.
\end{proof}

\section{Rational or divergent decomposition}\label{sec:rationals}
In this section we use Theorem \ref{Th1} in order to deduce Corollary \ref{cor:main}. Fix a number $\alpha\in[0,1]$ and let $b_n$ and $c_n$ be as defined in Defition \ref{def:shulga}. Also, let $p_n,q_n,s_n,t_n$ be as defined in \eqref{eq:fractions}.

\begin{lem}\label{lem:mon}
The sequence of ratios $\frac{t_n}{q_n}$ is strictly increasing.
\end{lem}

\begin{proof}
Indeed, since $b_n$ and $c_n$ are integers, the inequality \eqref{cnbn_main_ineq} implies that $c_n-b_n\ge 1$. Therefore, we have
\begin{equation}
\label{step_1_ratio}
\begin{aligned}
\frac{t_{n}}{t_{n-1}}\frac{q_{n-1}}{q_{n}}
&=
\frac{[c_{n};c_{n-1},\ldots,c_1]}{[b_{n};b_{n-1},\ldots,b_1]}
\\
&=1+\frac{(c_{n}-b_{n})+([0;c_{n-1},\ldots,c_1]-[0;b_{n-1},\ldots,b_1])}{b_{n}+[0;b_{n-1},\ldots,b_1]}>1+\frac{1}{2b_n+1}\,.
\end{aligned}
\end{equation}
The inequality in \eqref{step_1_ratio} follows from the trivial estimates 
$$
[0;c_{n-1},\ldots,c_1],\;[0;b_{n-1},\ldots,b_1] < 1/2\,,
$$
which follow from the fact that $c_{n-1},b_{n-1}\ge 2$. 
\end{proof}

\begin{lem}\label{lem:t_n_q_n_infty}
If the algorithm takes infinitely many steps then
\begin{equation}\label{eq:statement}
\lim\limits_{n\to\infty}\frac{t_n}{q_n}=\infty\,.
\end{equation}
\end{lem}
\begin{proof}
Suppose that the sequence $c_n$ is unbounded. From (\ref{CnBn_ineq1}) one can see that
\begin{equation*}
%\label{CnBn_ineq1_weak}
\frac{c_n}{2t^2_n}<\frac{1}{2t_{n-1}t_n}<\frac{2}{q^2_n}\,.
\end{equation*}
Thus,
\begin{equation*}
%\label{t_n_q_n_b_n4}
\frac{t^2_n}{q^2_n}>\frac{c_n}{4}\,.
\end{equation*}
Therefore, the divergence \eqref{eq:statement} follows directly from Lemma \ref{lem:mon}.

Considering the remaining case, if all the numbers $c_n$, and hence $b_n$, do not exceed some positive constant $N$, then \eqref{step_1_ratio} implies that
\begin{equation*}
%\label{t_n_q_n_exp}
\frac{t_n}{q_n}>\left(1+\frac{1}{2N-1}\right)^{n-1}\,,
\end{equation*}
thus finishing the proof.
\end{proof}

\begin{remark}
    In fact, it follows from the growth rate estimates of Section \ref{sec:growth} that the situation in the second paragraph of the proof of Lemma \ref{lem:t_n_q_n_infty} cannot occur, namely, that if $\{c_n\}_{n\geq1}$ is an infinite sequence then it is unbounded. However, since the above argument is short we decided to present it here and keep the more involved analysis for the next section.
\end{remark}

Now we are ready to prove Corollary \ref{cor:main}.
\begin{proof}[Proof of Corollary \ref{cor:main}]
First, we show that if $\alpha=p/q\in\mathbb{Q}$ then the algorithm converges in finitely many steps.
Let $C_n$ be the interval obtained on the $n$th step of the algorithm. The fact that $\alpha\in C_n$ is equivalent to the property
\begin{equation*}
%\label{x_min_pnqn_in_cylinder}
\frac{p}{q}-\frac{p_n}{q_n}\in\bigl[[0;c_1,\ldots c_n],\ [0;c_1,\ldots,c_n+1]\bigr).    
\end{equation*}
Therefore, it follows from \eqref{cyl_def} that the denominator of $\frac{p}{q}-\frac{p_n}{q_n}$ is at least $t_n$. On the other hand, this denominator does not exceed $q_nq$. Thus, we have the inequality
\begin{equation*}
\frac{t_n}{q_n}\le q\,.    
\end{equation*}
Due to Lemma \ref{lem:t_n_q_n_infty}, the algorithm must stop at a finite step.

If $\alpha$ is irrational, one can easily see that the numbers $[0;b_1,b_2,\ldots]$ and $[0;c_1,c_2,\ldots]$ must lie in the set $G$. Indeed, from \eqref{c_n_bn1} we have
\begin{equation*}
%\label{CnBn_ineq1_weak2}
q_{n+1}q_n>t_n^2\,.
\end{equation*}
Thus,
\begin{equation*}
b_{n+1}>\left(\frac{t_n}{q_n}\right)^2-1\,.    
\end{equation*}
Due to Lemma \ref{lem:t_n_q_n_infty}, the sequences $\{b_n\}_{n\geq1}$, and therefore $\{c_n\}_{n\geq1}$, both tend to infinity as $n$ tends to infinity.
\end{proof}

\section{Growth rate}\label{sec:growth}
In the previous section, we showed that the sequences $b_n$ and $c_n$ 
%and $\frac{t_n}{q_n}$ 
tend to infinity as $n\to\infty$. In this section, we provide some quantitative estimates on the growth rate of these sequences. First, we establish the inequality \eqref{monot_main_ineq}.
\begin{lem}
\label{bn_monot_lem}
For all $n\ge1$ one has $b_{n+1}\ge b_n$.    
\end{lem}
\begin{proof}
We suppose the contrary, and denote $b_n=t$. Then $c_n\ge t+1$ and $b_{n+1}\le t-1$. From \eqref{bn_ge_ineq_main}, applying the trivial estimates $1+\frac{1}{c_{n+1}}>1$ and $[0;c_{n-1},\ldots,c_1]>0$, we get
\begin{equation*}
%\label{bn_ge_ineq_main_2}
t>\left(t+2\right)\left(1-\frac{1}{t}\right),
\end{equation*}
and thus obtain a contradiction, as $t\ge 2$.
\end{proof}
\begin{lem}
\label{lem_32}
Suppose that $b_n\ge 8$. If $b_{n+1}<c_n$, then $c_{n+1}>\frac{3}{2}b_n$.    
\end{lem}
\begin{proof}
Denote $c_n=t$, hence $b_{n+1}\le t-1$. Applying \eqref{bn_ge_ineq_main}, we obtain
\begin{equation*}
%\label{bn_ge_ineq_bn1_gt_cn}
t>\left(1+\frac{1}{c_{n+1}}\right)\left(t+1\right)\left(1-\frac{1}{b_n}\right).
\end{equation*}
Thus, we have
\begin{equation*}
1>\left(1+\frac{1}{t}+\frac{1}{c_{n+1}}\right)\left(1-\frac{1}{b_n}\right),
\end{equation*}
which is equivalent to
\begin{equation}
\label{bn_ge_ineq_bn1_gt_cn2}
\frac{c_{n+1}}{b_{n}-1}>1+\frac{c_{n+1}}{t}\,.
\end{equation}
If $c_{n+1}\ge t$ then
\begin{equation*}
\frac{c_{n+1}}{b_n}>2\frac{b_n-1}{b_n}\ge\frac{7}{4}\,.
\end{equation*}
If $c_{n+1}<t$ then it follows from \eqref{bn_ge_ineq_bn1_gt_cn2} that
\begin{equation*}
%\label{cn_ge_2bn}
c_n=t> 2(b_n-1)\,.
\end{equation*}
From \eqref{bn_ge_ineq_main} with $n+1$ instead of $n$ and Theorem \ref{Th1}, it follows that
\begin{align*}
c_{n+1}&\ge b_{n+1}+1>\left(1+\frac{1}{c_{n+1}}\right)\left(c_n+1+[0;c_{n+1},\ldots,c_1]\right)\left(1-[0;b_{n},\ldots,b_1]\right)
\\[2pt]
& >
\left(2(b_n-1)+1\right)\left(1-\frac{1}{b_n}\right)>2(b_n-1)\left(1-\frac{1}{b_n}\right)
\\[2pt]
&=
2b_n\left(1-\frac{1}{b_n}\right)^2\ge\frac{49}{32}b_n\,.    
\end{align*}
The lemma is proved.
\end{proof}

Now we are ready to prove Theorem \ref{Th2}.
\begin{proof}[Proof of Theorem \ref{Th2}]
The first inequality \eqref{monot_main_ineq} is already established in Lemma \ref{bn_monot_lem}. One can easily check (e.g., by a computer program) that \eqref{monot_main_ineq2} and \eqref{bn_main_ineq} hold if $n\le 6$. In fact, all $\alpha\in[0,1]$ for which $b_6$ is defined satisfy
\begin{equation}\label{eq:b_6}
    b_6\ge 8\,.
\end{equation} 
Note that for all $n,k\in\mathbb{N}$ we have $b_{n+k}\ge b_n$, $c_{n+k}>b_n$, so for $n\geq6$ we may apply the consequence of Lemma \ref{lem_32}. 

We start with the second inequality \eqref{monot_main_ineq2}. Denote $b_n=t$. Then $c_n\ge t+1$. If $b_{n+1}\ge t+1$ then $b_{n+2}\ge t+1=b_n+1$ by Lemma \ref{bn_monot_lem}, so \eqref{monot_main_ineq2} is established. Otherwise, by Lemma \ref{lem_32} we have $c_{n+1}\ge\frac{3}{2}b_n$, and therefore, applying \eqref{bn_ge_ineq_main} for index $n+2$ instead of $n$, we obtain
\begin{equation*}
b_{n+2}>\frac{3}{2}b_n\left(1-\frac{1}{b_{n+1}}\right)-1\ge \frac{3}{2}b_n\left(1-\frac{1}{b_{n}}\right)-1=\frac{3}{2}(b_n-1)-1>b_n+1\,. 
\end{equation*}
Thus, we established \eqref{monot_main_ineq2}.

Let us now prove the last inequality \eqref{bn_main_ineq}. Let $n>6$ be an arbitrary integer greater than $6$. If $b_{k+1}\ge c_k$ for all $6\leq k\leq n-2$ then Theorem \ref{Th1} implies by induction that $b_{n-1}\ge n+1$. Therefore, Lemma \ref{bn_monot_lem} gives $b_n \geq n+1$. Otherwise, let $l$ be the smallest index $6\leq l\le n-2$ satisfying $b_{l+1}<c_l$. Due to the definition of the index $l$ we conclude as above that $b_{l+1}\ge b_{l}\geq l+1$. By Lemma \ref{lem_32}, one has

\begin{equation*}
c_{l+1}>\frac{3}{2}b_l\,,
\end{equation*}
and therefore, applying \eqref{bn_ge_ineq_main} once again we have
\begin{equation*}
b_{l+2}>\frac{3}{2}b_l\left(1-\frac{1}{b_{l+1}}\right)-1\ge
\frac{3}{2}b_l\left(1-\frac{1}{b_{l}}\right)-1=\frac{3}{2}(b_l-1)-1\ge b_l+\frac{3}{2}\ge l+\frac{7}{2}\,.
\end{equation*}
Since $b_{l+2}$ and $l$ are integers this implies that $b_{l+2}\ge l+4=(l+2)+2$. This argument can be repeated with the index $6$ replaced by $l+2$, so it follows by induction with base \eqref{eq:b_6} that \eqref{bn_main_ineq} holds for every $n\geq1$. Thus, the proof of Theorem \ref{Th2} is completed.
\end{proof}

\subsection{Proof of Theorem \ref{examp_thm}}
In this subsection, we construct an irrational number $\alpha$ that satisfies Theorem \ref{examp_thm}. In our construction, we define the infinite sequences $b_1, b_2,\ldots$ and $c_1,c_2,\ldots$ and put
\begin{equation}
\label{alpha_def}
\alpha=[0;b_1,b_2,\ldots]+[0;c_1,c_2,\ldots]\,.
\end{equation}
Using \eqref{cn_bn_def}, we will define the intervals $B_1, C_1, B_2, C_2,\ldots$. Our goal will be to show that these intervals are nesting, i.e.,
\begin{equation}
\label{nesting_property}
B_1\supseteq C_1\supseteq B_2\supseteq C_2\supseteq\ldots\supseteq B_n\supseteq C_n\supseteq\ldots
\end{equation}
By Lemma \ref{large_intersec_lem}, the property \eqref{nesting_property} yields that \eqref{alpha_def} is the Shulga decomposition of $\alpha$. 

%We define the first nine partial quotients as follows:
%\begin{equation*}
%[0;b_1,\ldots,b_9]=[0;2,6,11,16,21,26,30,34,38],\
%[0;c_1,\ldots,c_9]=[0;4,9,14,19,24,28,32,36,41].
%\end{equation*}
%One can verify that 
%\begin{equation*}
%B_1\supseteq C_1\supseteq B_2\supseteq %C_2\supseteq\ldots\supseteq B_9\supseteq C_9.
%\end{equation*}
We put $b_1=2$ and $c_1=4$, and continue by recursion. Suppose that the numbers $b_1,\ldots,b_n$ and $c_1,\ldots,c_n$ are defined. Define 
\begin{equation}\label{eq:the_definition0}
    b_{n+1}\defeq c_n+2\,.
\end{equation}
The definition of $c_{n+1}$ is slightly more complicated. We define for $m=2,3$ the quantities
\begin{equation}\label{eq:the_definition}
c^{(m)}_{n+1}\defeq b_{n+1}+m\,,\quad \frac{s^{(m)}_{n+1}}{t^{(m)}_{n+1}}\defeq[0;c_1,\ldots,c_n,b_{n+1}+m]\,,
\end{equation}
and then
\begin{equation}\label{eq:the_definition2}
c_{n+1}\defeq 
\begin{cases}
    c^{(2)}_{n+1}&\textrm{if }0<c^{(2)}_{n+1}-\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2<1\,,\\
    c^{(3)}_{n+1}&\textrm{otherwise.}
\end{cases}
\end{equation}
So the first several digits are
\begin{equation}\label{eq:beginning}
\begin{aligned}
%[0;b_1,\ldots,b_9,\ldots]&=[0;2,6,11,16,21,26,30,34,38,\ldots]\,,\\
%[0;c_1,\ldots,c_9,\ldots]&=[0;4,9,14,19,24,28,32,36,41,\ldots]\,.
\relax
[0;b_1,\ldots,b_6,\ldots]&=[0;2,6,11,16,21,26,\ldots]\,,\\
[0;c_1,\ldots,c_6,\ldots]&=
[0;4,9,14,19,24,28,\ldots]\,.
\end{aligned}
\end{equation}

The proof of the nesting property \eqref{nesting_property} is based on the following observation: 

%we first show that for every $n$ the partial quotient $c_n$ satisfies
%The fact that \eqref{tn_qn_ratio} holds for every $n\ge 2$ then follows by induction via the following lemma:

\begin{lem}
\label{cn_cn1_2}
For every $n\geq2$ the partial quotient $c_n$ satisfies
\begin{equation}
\label{tn_qn_ratio}
0<c_{n}-\left(\frac{t_{n}}{q_{n}}\right)^2 < 1\,.
\end{equation}
\end{lem}
%\DG{For $n=1$ we have $c_n=t_n=4$ and $q_n=2$. Hence, we have $c_{n}-\left(\frac{t_{n}}{q_{n}}\right)^2=0$. That is why the inequality at the l.h.s is not strict.}
%Then,
%\begin{enumerate}
%    \item $x<y$.
%    \item If $x<1$ then $y<x+1/2$.
%    \item If $x<1$ and $y\geq1$ then $0<z<1$.
%\end{enumerate}

\begin{proof}
The proof goes by induction. For $2\leq n \leq6$ the inequality \eqref{tn_qn_ratio} is verified by a direct computation. Let $n\geq6$ and
\begin{align*}
x\defeq c_{n}-\left(\frac{t_{n}}{q_{n}}\right)^2,
&&y\defeq c^{(2)}_{n+1}-\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2,
&&z\defeq c^{(3)}_{n+1}-\left(\frac{t^{(3)}_{n+1}}{q_{n+1}}\right)^2.
\end{align*}
We note that by definition \eqref{eq:the_definition} and by \eqref{eq:common}, one gets
\begin{equation}
\label{tn1_qn1_m_ratio_term_n}
\begin{aligned}
\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2&=\left(\frac{t_{n}}{q_{n}}\right)^2
\left(\frac{c_n+4+[0;c_n,\ldots,c_1]}{c_n+2+[0;b_n,\ldots,b_1]}\right)^2\\
&=
\left(1+\frac{2+[0;c_n,\ldots,c_1]-[0;b_n,\ldots,b_1]}{c_n+2+[0;b_n,\ldots,b_1]}\right)^2(c_n-x)\,.
\end{aligned}
\end{equation}
Due to $c_n>b_n$, one has $[0;c_n,\ldots,c_1]<[0;b_n,\ldots,b_1]$. Thus,
\begin{equation*}
%\label{tn1_qn1_m_ratio_term_n2}
\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2<\left(1+\frac{2}{c_n+2}\right)^2(c_n-x)=\left(\frac{c_{n}+4}{c_{n}+2}\right)^2(c_n-x)\,.
\end{equation*}
Thus, we obtain the following lower bound on $y$:
\begin{align*}
y&>c_n+4-\left(\frac{c_{n}+4}{c_{n}+2}\right)^2(c_n-x)=(c_n+4)\left(1-\frac{c_n+4}{c_n+2}\frac{c_n-x}{c_n+2}\right)\\[2pt]
&>(c_n+4)\left(1-\frac{c_n-x}{c_n}\right)=\frac{c_{n}+4}{c_n}x\,.
\end{align*}
Therefore, by definition \eqref{eq:the_definition2}, in order to complete the induction it is enough to show that if $0<x<1$ and $y\geq1$ then $0<z<1$. On one hand, the assumption $y\geq1$ and \eqref{eq:common} imply that
\begin{equation}\label{eq:similar}
\begin{aligned}
\left(\frac{t^{(3)}_{n+1}}{q_{n+1}}\right)^2
&=    
\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2\left(\frac{t^{(2)}_{n+1}+t_n}{t^{(2)}_{n+1}}\right)^2
\\[2pt]
&=
\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2\left(1+\left[0;c^{(2)}_{n+1},c_n,\ldots,c_1\right]\right)^2
\\
&< \left(c^{(2)}_{n+1}-1\right)\left(1+\frac{1}{c^{(2)}_{n+1}}\right)^2
\\[2pt]
&<c^{(2)}_{n+1}+1=c^{(3)}_{n+1}\,.
\end{aligned}
\end{equation}
So, $z>0$. On the other hand, since $n\geq6$, equation \eqref{eq:beginning} gives that $b_n,c_n\geq10$.
From \eqref{tn1_qn1_m_ratio_term_n} one gets
\begin{equation}
\label{tn1_qn1_m_ratio_term_ge}
\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2>\left(1+\frac{1.9}{c_n+2.1}\right)^2(c_n-x)=\left(\frac{c_{n}+4}{c_{n}+2.1}\right)^2(c_n-x)\,.
\end{equation}
Thus, we obtain the following upper bound on $y$:
\begin{align*}
y
&<c_n+4-\left(1+\frac{1.9}{c_{n}+2.1}\right)^2(c_n-x)
\\[2pt]
&<
c_n+4-\left(1+\frac{3.8}{c_{n}+2.1}\right)(c_n-x)
\\[2pt]
&=
4-\frac{3.8(c_n-x)}{c_n+2.1}(c_n-x)+x < 3/2\,,
\end{align*}
where the last inequality follows from $x<1$ and $c_n\geq26$. Therefore, similarly to \eqref{eq:similar}, one gets
\begin{align*}
\left(\frac{t^{(3)}_{n+1}}{q_{n+1}}\right)^2    
&=
\left(\frac{t^{(2)}_{n+1}}{q_{n+1}}\right)^2\left(\frac{t^{(2)}_{n+1}+t_n}{t^{(2)}_{n+1}}\right)^2
\\[2pt]
&>
\left(c^{(2)}_{n+1}-3/2\right)\left(1+\frac{1}{c^{(2)}_{n+1}+1}\right)^2
\\[2pt]
&>
\frac{\left(c^{(2)}_{n+1}-3/2\right)\left(c^{(2)}_{n+1}+3\right)}{c^{(2)}_{n+1}+1}
\\[2pt]
&>c^{(2)}_{n+1}=c^{(3)}_{n+1}-1\,,
\end{align*}
where the last inequality follows from $c_n\ge 10$. Thus, we established that $z<1$ and therefore the inequality \eqref{tn_qn_ratio} holds for all $n\geq1$.
\end{proof}
Now we are ready to prove Theorem \ref{examp_thm}.

\begin{proof}[Proof of Theorem \ref{examp_thm}]
Due to the definition of $b_n$ and $c_n$ in \eqref{eq:the_definition0} and \eqref{eq:the_definition2}, one can see that the inequality \eqref{2n_3n} is satisfied. Hence, it suffices to establish the nesting property \eqref{nesting_property}. %Without loss of generality, we assume that $n$ is even. 
First, let us show that $B_n\supseteq C_n$. 
%We need to show that $C_n^{(r)}<B_n^{(r)}$ and $C_n^{(l)}>B_n^{(l)}$. The first inequality follows the basic properties of continued fractions. The second inequality is

With out loss of generality, we assume that $n$ is even. This containment is equivalent to (recall Figure \ref{fig:intervals})
\begin{equation}
\label{BnCn_compl_case}
[0;b_1,\ldots,b_{n-1},b_n]+[0;c_1,\ldots,c_{n-1},c_n]>[0;b_1,\ldots,b_{n-1},b_n-1]+[0;c_1,\ldots,c_{n-1}].
\end{equation}
The inequality \eqref{BnCn_compl_case} is equivalent to 
\begin{equation*}
\frac{1}{t_n t_{n-1}}<\frac{1}{q_n(q_n-q_{n-1})}\,,
\end{equation*}
which can be rewritten as
\begin{equation*}
c_n+[0;c_{n-1},\ldots,c_1]<\left(\frac{t_n}{q_n}\right)^2\frac{1}{1-[0;b_n,\ldots,b_1]}\,.
\end{equation*}
Applying \eqref{tn_qn_ratio}, one can see that it suffices to show
\begin{equation*}
c_n+\frac{1}{c_{n-1}}<\frac{c_n-1}{1-[0;b_n,\ldots,b_1]}\,,   
\end{equation*}
which is equivalent to
\begin{equation*}
1-[0;b_n,\ldots,b_1]<1-\frac{1+1/c_{n-1}}{c_n+1/c_{n-1}}\,.
\end{equation*}
Taking into account that $b_{n-1}\ge 2$, we see that it is sufficient to show
\begin{equation}
\label{ineq22bn1}
\frac{c_{n-1}+1}{c_nc_{n-1}+1}<\frac{2}{2b_n+1}\,.
\end{equation}
As $c_n\ge b_n+2=c_{n-1}+4$, the inequality \eqref{ineq22bn1} follows from
\begin{equation}
\label{ineq22bn1case3}
\frac{c_{n-1}+1}{c^2_{n-1}+4c_{n-1}+1}<\frac{2}{2c_{n-1}+5}\,.
\end{equation}
One can easily see that \eqref{ineq22bn1case3} holds whenever $c_{n-1}>3$. Thus, we established that $B_n\supseteq C_n$.

Now we show that $C_n\supseteq B_{n+1}$. 
%This property means that $B_{n+1}^{(l)}>C_n^{(l)}$ and $B_{n+1}^{(r)}<C_n^{(r)}$. Once again, the first inequality follows from basic properties of continued fractions. The second inequality is
This containment is equivalent to
\begin{equation}
\label{CnBn1_compl_case}
[0;b_1,\ldots,b_n,b_{n+1}-1]+[0;c_1,\ldots,c_n]<[0;b_1,\ldots,b_n]+[0;c_1,\ldots,c_n+1]\,.
\end{equation}
The inequality \eqref{CnBn1_compl_case} is equivalent to
\begin{equation}
\frac{1}{q_n(q_{n+1}-q_n)}<\frac{1}{t_n(t_n+t_{n-1})}   
\end{equation}
which can be written as
\begin{equation*}
%\label{before_tnqn_upest}
\frac{1}{b_{n+1}-1+[0;b_n,\ldots,b_1]}\left(\frac{t_n}{q_n}\right)^2<\frac{1}{1+[0;c_n,\ldots,c_1]}\,.
\end{equation*}
Taking into account \eqref{tn_qn_ratio}, we obtain that it is sufficient to show that
\begin{equation}
\label{tnqn_cn_ineq}
\frac{c_n}{c_n+1+[0;b_n,\ldots,b_1]}<\frac{1}{1+[0;c_n,\ldots,c_1]}\,.
\end{equation}
Note that the left-hand side of \eqref{tnqn_cn_ineq} is less than $\frac{c_n}{c_n+1}$, while the right-hand side of \eqref{tnqn_cn_ineq} is greater than this quantity.
Thus, we established the property $C_n\supseteq B_{n+1}$ and Theorem \ref{examp_thm} is proved. 
\end{proof}


