\section{On the size of character classes}\label{bantay}
Throughout this section, let $\cc$ be a fusion category with a commutative Grothendieck ring, $K(\cc)$. Then as above, $\cfcc$ is a commutative semisimple algebra isomorphic to $\kc\cong K_0(\cc)\ot_{\Z}\comp$. As above, Let $\mtc J^{\cc}:= \{0, \dots, m\}$ represent the set of indices corresponding to the conjugacy classes of $\cc$. It is clear that the rank of $\cc$ is $\rank(\cc) = |\mtc J^\cc| = m + 1$.


Suppose $\cd$ is a fusion subcategory of $\cc$. Note that the Grothendieck ring $K(\cd)$ is also commutative, and, as in the case above, $K(\cd)\simeq \cf(\cd)$ as algebras.  We let $\mtc J^{\cd}:= \{0, \dots, m'\}$ represent the set of indices corresponding to the conjugacy classes of $\cd$. As above, it is clear that the rank of $\cd$ is $\rank(\cd) = |\mtc J^\cd| = m' + 1$.


Let $\{F_j\}_{0 \leq j \leq m}$ be  the (central) primitive idempotents of $\cfcc$, and let $\{\cc^j\}_{0\leq j \leq m}$ be their associated conjugacy classes. For each (central) primitive  idempotent $F_j\in \cfcc$, let $\muj:\cfcc\ra \comp$ denote its associated linear character. Similarly, let $\{G_t\}_{0 \leq t \leq m'}$ be the (central) primitive idempotents of  $\cf(\cd)$, with  $\{\cd^t\}_{0\leq t \leq m'}$ being  their associated conjugacy classes.  Additionally, let $\nu_t: \cfcd \to \comp$ denote the characters associated with these idempotents.



We say that two characters $\muj, \mu_{j'}:\cfcc\ra \comp$ are \emph{$\cd$-equivalent} ($\mu_j \simeq_\cd \mu_{j'}$) if their restrictions to $\cf(\cd)$ coincide.

The set of equivalence classes is denoted by $\clcrd$. There is a natural bijection between this set and the characters of $\cfcd$.
%This set is   in bijection with the set  of the characters of $\nu_t:\cfcd\ra\comp$ with $0\leq t\leq m'$.  

Moreover, an element $C\in  \clcrd$ consists of all the indices $j$ such that the restriction $\mu_j\dw_{\cfcd}$ corresponds to the same character in $\cfcd$, denoted as $\ro_C:=\nu_s$ for some $s\leq m'$. Thus, we use $\ro_C$ to represent the common restriction to  $\cfcd$ of all characters $\mu_j$ belonging to some class $C\in \clcrd$. 

As noted above, the set of character classes of $\cc$ relative to $\cd$ corresponds bijectively to the characters of $\cfcd$. Consequently,  the central primitive idempotents of $\cfcd$ are also indexed by the classes $C\in \clcrd$. We denote the central primitive idempotent associated with a class $C \in \clcrd$ by $G_C \in \cf(\cd)$. Thus, the elements $G_C$ for $C \in \clcrd$ form a linear basis for $\cf(\cd)$, consisting of the complete set of (central) primitive idempotents of the commutative $\comp$-algebra $\cf(\cd)$. For the remainder of this section, we identify the set of indices $\mtc J^\cd$ of the central primitive idempotents of $\cf(\cd)$ with the elements of $\clcrd$. For any primitive idempotent $G_C$ of $\cfcd$, as described in Subsection \ref{bij-conj}, let  $\mtr{D}_C\in \cecd$ denote  the corresponding conjugacy class sum of $\cd$ associated with $G_C$. 

In \cite[Appendix]{ccc-march} we have constructed  two $\comp$-algebra maps, denoted by
$
\pif:\cfcd \ra \cfcc \;\text{and},\;\pie:\cecc \ra \cecd.
$ 
Furthermore, by \cite[Lemma 7.7]{ccc-march} it is known that $\pif$ is a monomorphism and $\pie$ is an epimorphism.
\bn{exmp}
If $\pi:H\ra K$ is a surjective Hopf algebra homomorphism, then clearly we have $\rep(K)\subseteq \rep(H)$. In this case, $\pi_e=\pi\big|_{Z(H)}:Z(H)\ra Z(K)$ is the restriction of $\pi$ to the center $Z(H)$ of $H$. Furthermore, $\pi_f$ corresponds to the  canonical inclusion  of the character algebra $C(K)$ of $K$ into that $H$, i.e, $C(K)\hookrightarrow C(H)$.
\end{exmp}

By \cite[Theorem 3.3]{b-conj-im} for any character class $C\in \clcrd$ and any index  $j\in C$ we have:
\beq\label{piz-form}
\piz(\lbarcj)=\frac{\mtr{D}_C}{\dim(\cd^C)}
\eeq
where $D_C$ is the conjugacy class sum associated to $\ro_C$.
%\subsection*{A general extent formula}
Following \cite[Definition 2.5]{b-pa}, for any subset $\mtc Z\in \wirrc$ we define its \emph{dimensional order} as 
\beq\label{n-dim-def}
\ndim(\mtc Z)=\sum_{\muj\in \mtc Z}\dim(\ccj).
\eeq
Next Proposition is a generalization of \cite[Prop. 5.1]{b-conj-im}.
\bp \label{indep-prop}
Let $\cc$ be a pivotal fusion category with a commutative Grothendieck ring  $K(\cc)$ and let $\cd$ be a fusion subcategory of $\cc$.  Then for any $C \in \clcrd$ we have:
\beq\label{ext-f}
\ndim(C) = \frac{\dimcc}{\dimcd}.
\eeq
\ep
\bpf
%Since $\cd\subseteq \cc$, by \cite[Lemma 7.5, item 1)]{ccc-march}, as already mentioned above, there exists a surjective homomorphism of $\comp$-algebras
%$
%\pi_e: \cecc \ra \mtr{CE}(\cd).
%$
According to Equation \eqref{piz-form}, for any 
$C \in \clcrd$, there exists a conjugacy class sum $D_C\in \cecd$ such that we have: 
$
\pi_e(C_j)= \frac{\dim(\ccj)}{\dim(\cd^C)} D_C, \;\text{for all indices}\;j\in C.
$
On the other hand, \cite[Lemma 3.4]{b-conj-im}, gives that:
\beq\label{wtlam}
\pi_e( \widehat{\Lam}_\cc) =\frac{\dimcc}{\dimcd} \widehat{\Lam}_\cd.
\eeq
Recall that $\widehat{\Lam}_\cd=\sum_{C\in \clcrd} D_C.$ by  \cite[Proposition 4.1]{ccc-march}.  The same proposition applied for $\cd=\cc$ gives that 
$\widehat{\Lam}_\cc=\sum_{j\in \mtc J} C_j.$
Counting the multiplicity of $D_C$ in the left hand side of Equation \eqref{wtlam} we find:
$$
\ndim(C)=\sum_{l \in C} \dim(\cc^l) = \frac{\dimcc}{\dimcd}.
$$
%This completes the proof.
\epf
\br\label{n-vs-ndim}
Recall that for any subset $\mtc Z\subseteq \wirrc$ we have defined its order as $n(\mtc Z)=\sum_{\muj\in C}\whj$.  Using Equation \eqref{whj}, for a spherical fusion category $\cc$, dimensional and formal orders relate via: 
$$
\ndim(\mtc Z)=\frac{\dimcc}{\fpcc}n(\mtc Z),
$$
which can be written as:
\beq\label{ndim}
\frac{\fpcc}{n(\mtc Z)}=\frac{\dimcc}{\ndim(\mtc Z)}.
\eeq
Thus, for a spherical fusion category,  Equation \eqref{ext-f} implies that
\beq\label{ext-f-3}
n(C) = \frac{\fpcc}{\dimcd},
\eeq
for any  character class $C \in \clcrd$
\er
\subsection{Main Size Theorem}
\bt\label{bantay-pass}
Let $\cc$ be a pivotal fusion category with a  commutative Grothendieck ring $\kc$,  and  $\cd=\genx$ with $X\in \irrcc$. Then, with the above notations, we have:
\beq\label{eq-bantay}
\frac{\dimcc}{\ndim(Z_\cc(X))}=\frac{\dimcd}{|U(\cd)|}.
\eeq
\et
%\blue{\SMALL Q2 Can I get rid of pivotal here, in passing from single generated to general?}
\bpf
It is straightforward to see that $\zccx$ is a union of character classes $C\in \clcrd$. Specifically, if $\mu_1\simeq \mu_2$ and $\mu_1\in \zccx$, then  since $X$ is a simple object of  $\cd$, we have $\mu_2([X])=\mu_1([X])$. Consequently, $|\mu_2([X])|=\fpx$, which implies that $\mu_2\in \zccx$ as well.


Since $\cd$ is a fusion subcategory of $\cc$, there is an algebra inclusion $K(\cd)\subseteq K(\cc)$, which gives rise to a well-defined restriction map:
\beqn
\res:\wkc\ra \wkcd, \;\mu\sent \mu\big|_\wkcd.
\eeqn


Moreover, from the definition of the centers, we have $\mu\in \zccx$ if and only if $\res(\mu)\in \zcdx$. Suppose that $\zccx=C_1\sqcup C_2\dots\sqcup C_r$ with $C_i\in \clcrd$. Then, we can express the total order as: $\ndim(\zccx)=\sum_{i=1}^r\ndim(C_i)$. By Equation \eqref{ext-f}, we know that  $\ndim(C_i)=\frac{\dimcc}{\dimcd}$, for all $1\leq i\leq r$.  Therefore, we have: $\ndim(\zccx)=r \frac{\dimcc}{\dimcd}$. 


On the other hand, note that $r$ is the cardinality of the set $Z_\cd(X)$. By Lemma \ref{gkcd} we have $r=|G(\wkcd)|$, and then $r=|U(\cd)|$ by Remark \ref{gwkc-uc}. This completes the proof. 
\epf
\br
Note that $n(\gwkc)=|\gwkc|$ since $\wh_j=1$ for all $\muj\in \gwkc$. For a spherical fusion category,  the above Theorem and Equation \eqref{ndim} gives  that:
\beq\label{eq-bantay-2}
\frac{\fpcc}{ n(Z_\cc(X))}=\frac{\dimcc}{\ndim(Z_\cc(X))}=\frac{\dimcd}{|U(\cd)|}.
\eeq
\er
\section{Action of dual group-like elements}
Let $\cc$ be a fusion category with a commutative Grothendieck group  $\kzc$.  By \cite[Corollary 2.39]{b-pa}, since $\kc$ is an abelian real non-negative (RN) hypergroup, it follows that $\gwkc$ is a group. Moreover, for any $\mu\in \gwkc$, left multiplication by $\mu$ permutes the dual basis $\wirrc$. Specifically, if $\mu_i\in \wirrc$ and $\mu_z\in \gwkc$ then $\mu_z\star \mu_i=\mu_j$ for some $\mu_j\in \wirrc$. 
\subsection{Invariance properties under the group action}
We begin by establishing several key invariance properties of characters under the $\gwkc$-action.
\bl\label{abs-value-ct}
Under the $\gwkc$-action on $\wirrc$ by left multiplication, for any simple object $Y\in \irrcc$, the absolute value
$\big |\mu_j([Y]) \big |$ is constant on each orbit of this action.
\el
\bpf
Suppose  $\mujo=\mujtw\star \mu_z$ for some $z\in Z$. Then we compute:
\begin{eqnarray*}
\mu_\jtw([Y])&=&[\mu_\jo\star \mu_z]([Y])=\fp(Y)[\mu_\jo\star \mu_z](\frac{[Y]}{\fp(Y)})
\\&=&\fp(Y)\mu_\jo(\frac{[Y]}{\fp(Y)}) \mu_z(\frac{[Y]}{\fp(Y)})
\\&=&\mu_\jo([Y]) \mu_z(\frac{[Y]}{\fp(Y)}).
\end{eqnarray*}
Taking absolute values and applying Equation \eqref{int-center} yields $|\mu_{j_1}([Y])| = |\mu_{j_2}([Y])|$.
\epf
\begin{lemma}\label{nj-value-ct}
Under the $\gwkc$-action, the formal codegree $n_j$ is constant on each orbit.
\end{lemma}
\bpf
Suppose that $\mu_j=\mu_z \star \mu_k$ for some $\mu_z \in \gwkc$. Since $|\mu_z(Y)|=\fp(Y)$ for all  $Y\in \irrcc$ we have:
$$
n_j=\sum_{Y\in \irrcc}|\muj(Y)|^2= \sum_{Y\in \irrcc}|\muk(Y)|^2=n_k.
$$
Thus, characters in the same orbit share the same formal codegree.
\epf

\begin{corollary}\label{conj-dim-ct}
For a spherical fusion category $\cc$, the dimension $\dim(\cc^j)$ is constant on each orbit of the $\gwkc$-action.
\end{corollary}

\begin{proof}
This follows immediately from Lemma \ref{nj-value-ct} and Equation \eqref{nj-sph}, which relates formal codegrees to dimensions in the spherical case.
\end{proof}
\subsection{Single Generator Subcategory Case $\cc = \genx$}
We now specialize to the case where $\cc$ is generated by a single simple object $X$.
\begin{defn}
A character $\mu \in \wirrc$ is \emph{non-vanishing} if $\mu([X]) \neq 0$. An orbit $\mathcal{O} \subset \wirrc$ is called a \textit{non-vanishing orbit} if it consists of non-vanishing characters.
\end{defn}
%\bn{defn}
%We say that a character $\mu\in \wirrc$ is {\it non-vanishing} if $\mu([X])\neq 0$. Note that from above it follows that if a character $\mu$ is non-vanishing then its entire orbit $\ca(\mu)$ consists of non-vanishing characters. We say that such an orbit is a {\it non-vanishing orbit}. 
%\end{defn}

\bl\label{free-act}%RL2
Let $\cc = \genx$ with $X \in \irrcc$. Then the $\gwkc$-action on $\wirrc$ is free when restricted to any non-vanishing orbit. 
\el
\bpf
Suppose $\mu_z \star \mu = \mu$ for some non-vanishing $\mu \in \wirrc$ and $\mu_z \in \gwkc$. Evaluating at $\nx$ gives that $\mu_z(\nx)\mu(\nx)=\mu(\nx)$.  Since $\mu(\nx) \neq 0$, we conclude $\mu_z(\nx) = 1$. As $X$ is faithful, Lemma \ref{faith-center} implies $\mu_z = \mu_1$, the identity of $\gwkc$.
\epf
\section{Isaacs fusion categories with $s\geq 1/2$}\label{s-geq 1/2}
In this section we prove some results for $s$-Isaacs fusion categories for a rational number, $s\geq 1/2$. In particular, we prove Theorem \ref{s-geq-1/2-gf-uc}.
\subsection{Definition and Basic Properties}

Let $s\geq 0$ be a rational number.   
Following \cite{eno-nec}, we have the following definition:
\begin{defn}\label{sdef} 
We say that $\cc$ is $s$-{\bf Isaacs} if for any linear character $\muj: \kc\to \comp$ and any simple object $X\in \cc$,
$$
\lambda_s(\muj,X):=(\dim \cc)^s\dimccj^{1-s}\frac{\muj([X])}{\dim(X)} \in \mathbb{A}
$$
where $\mathbb{A}$ denotes the algebraic integers.
\end{defn}   
%Note that for a pseudo-unitary fusion category, this condition simplifies using central characters:
%\beq\label{issacs-omega}
%\lambda_s(\muj,X)=(\dim \cc)^s\dimccj^{1-s}\omega_X(\muj)\in \mathbb A.
%\eeq
%\blue{\SMALL This identity is not used anymore!}
\br
Since $\dimccj$ divides $\dim \cc$, if $\cc$ is $s$-Isaacs then it is $t$-Isaacs for any $t>s$.  As in \cite{eno-nec}, the $0$-Isaacs property will simply be called the {\it Isaacs property}. This was introduced in \cite{lpr1, lpr2} and by \cite[Proposition 5.2]{eno-nec}, any ribbon fusion category is Isaacs.
\er
Recall that $\cc$ is said to be Frobenius type if dimensions of its simple objects divide $\dimcc$.
The Kaplansky 6th conjecture for fusion categories states that any spherical fusion category
is Frobenius type. 

Following \cite{eno-nec}, we say that a category $\cc$ is {\it $s$-Frobenius type} for a
rational number $s \geq 1$ if the dimensions of its simple objects divide $(\dimcc)^s$. %; so 1-Frobenius type is Frobenius type in the usual sense. 
Clearly, $s$-Frobenius type implies $t$-Frobenius type for any $t > s$.
\subsection{Single Generator Case}
%First we prove the following Lemma:
\bl\label{s-geq-1/2-sgl} 
Suppose that $\cc=\genx$ is a spherical fusion category with a commutative Grothendieck ring generated by a simple object $X$. If $\cc$ is s-Isaacs ($s\geq 1/2$), then 
$$
\frac{(\dimcc)^{2s+1}}{|\ucc|\dim(X)^2}\in \mathbb A.
$$
\el
\bpf
Let $\{\mathcal{A}_i\}_{i=0}^r$ be the non-vanishing orbits of $\widehat{K(\mathcal{C})}$ under $G(\widehat{K(\mathcal{C})})$-action. Since the action of $\gwkc$ is free on these orbits, it follows that $|\ca_i|=|\gwkc|$ for all $0\leq i\leq r$.
%Let as above, $\ca_0, \ca_1, \dots, \ca_r\subseteq \wirrc$ be the non-vanishing orbits of the aforementioned left multiplication action of $\gwkc$.


From Equation \eqref{second:orth-2} we derive:
\beq\label{second:orth-cc}
\dimcc=\sum_{j=0}^m\dim(\ccj)\mu_j([X])\mu_{j^\#}([X])
\eeq
Multiplying both sides by $\frac{(\dimcc)^{2s}}{\dim(X)^2}$ we obtain
{\Small
\beq\label{second:orth-cc-s1}
\frac{(\dimcc)^{2s+1}}{\dimx^2}=\sum_{j=0}^m\dim(\cc)^s\dim(\ccj)^{1-s}\frac{\mu_j([X])}{\dimx}\dim(\ccj)^{1-s}\dim(\cc)^s\frac{\mu_{j^\#}([X])}{\dimx}\dim(\ccj)^{2s-1}
\eeq
}
and this can be written as
\beq\label{second:orth-cc-s2}
\frac{(\dimcc)^{2s+1}}{\dimx^2}=\sum_{j=0}^m\lam_s(\muj, X)\lam_s(\mu_{j^\#}, X)\dim(\ccj)^{2s-1}
\eeq
Lemma \ref{abs-value-ct} together with Corollary \ref{conj-dim-ct} imply that each summand
$$
\lambda_s(\muj,X)\lambda_s(\mu_{j^\#},X)\dim(\ccj)^{2s-1}
$$
is constant within any non-vanishing orbit $\ca_i$. Thus the above Equation can be rewritten as: 
\begin{eqnarray*}
\frac{(\dimcc)^{2s+1}}{\dimx^2}
&=&
\sum_{i=0}^r\sum_{j\in \ca_i}\lambda_s(\muj,X)\lambda_s(\mu_{j^\#},X)\dim(\ccj)^{2s-1}
\\&=&
\sum_{i=0}^r |\ca_i|
\lambda_s(\mu_\ji,X)\lambda_s(\mu_{\ji^\#},X)\dim(\cc^{\ji})^{2s-1}
\\&=& 
|\gwkc|\sum_{i=0}^r 
\lambda_s(\mu_\ji,X)\lambda_s(\mu_{\ji^\#},X)\dim(\cc^{\ji})^{2s-1},
\end{eqnarray*}
where $j_i\in \ca_i$ is arbitrarily chosen. Since  $\gwkc\simeq \ucc$ by Remark \ref{gwkc-uc} we obtain that
\beqn
\frac{(\dimcc)^{2s+1}}{\oucc\dimx^2}=\sum_{i=0}^r 
\lambda_s(\mu_\ji,X)\lambda_s(\mu_{\ji^\#},X)\dim(\cc^{\ji})^{2s-1}.
\eeqn
Since $s\geq 1/2$ and $\dim(\ccj)\in \mathbb A$  it follows that $\dim(\ccj)^{2s-1}\in \mathbb A$. Since $\cc$ is s-Isaacs we also have $\lambda_s(\mu_\ji,X),\;\lambda_s(\mu_{\ji^\#},X) \in \mathbb A$ and the proof is completed. 
\epf
\br
If $\cc$ is spherical and $s$-Isaacs  for $s\geq 1/2$ then $\cc$ is $1+s/2$ Frobenius, see \cite[Proposition 5.4]{eno-nec}. Note that previous lemma  strengthen this result in the case of an Isaacs fusion category generated by a simple object. More precisely, under these hypotheses we derive that:
$$
\frac{(\dimcc)^{s+1/2}}{\dim(X)\sqrt{\oucc}}\in \mathbb A.
$$

\er
\subsection{General Case for $s\geq 1/2$.}
\bt \label{s-geq-1/2-gf-zccx}%C_s
Let $s\geq 1/2$ be a rational number and $\cc$ be a  spherical fusion category. Suppose that $X$ is a simple object of $\cc$ such that the fusion subcategory $\genx$ generated by $X$ is $s$-Isaacs. Then 
$$
\frac{(\dimcc)^{2s+1}}{\dim(X)^2\ndim(\zccx)}\in \mathbb A.
$$
\et
\bpf
Let $\cd:=\genx$. Applying Lemma \ref{s-geq-1/2-sgl}  for $\cd$ we have that:
$$
\dim(X)^2\mid \frac{(\dimcd)^{2s+1}}{\oucd }.
$$
By Equation \eqref{eq-bantay} we have
\beq\label{eq-bantay-pr}
\frac{(\dimcd)^{2s+1}}{\oucd }=\frac{\dimcd}{|U(\cd)|}(\dimcd)^{2s}=\frac{\dimcc}{\ndim(Z_\cc(X))}(\dimcd)^{2s}
\eeq
and therefore $$
\dim(X)^2\mid \frac{(\dimcc)^{2s+1}}{\ndim(Z_\cc(X))},
$$
since $\dim(\mathcal{C})/\dim(\mathcal{D}) \in \mathbb{A}$, see \cite{EGNO15}.
\epf
\subsubsection{Proof of Theorem \ref{s-geq-1/2-gf-uc}}
\bpf
Theorem \ref{s-geq-1/2-gf-zccx}  establishes
that $\dim(X)$ divides $\frac{(\dimcc)^{2s+1}}{\ndim(\zccx)}$. Using Equation \eqref{ndim} we obtain that $\dim(X)$ divides
\beq\label{eq-bantay-22}
(\dimcc)^{2s}\frac{\dimcc}{\ndim(\zccx)}=(\dimcc)^{2s}\frac{\fpcc}{n(\zccx)}
\eeq
On the other hand, the RN property of $\widehat{K(\mathcal{C})}$ gives that $|U(\mathcal{C})| \mid n(Z_\mathcal{C}(X))$, by Theorem \ref{uc-div}. Then the required divisibility follows.
\epf
\section{Isaacs fusion categories with $s\geq 0$}\label{s-geq-0}
In this section, we establish divisibility results for $s$-Isaacs fusion categories when $s \geq 0$, culminating in the proof of Theorem \ref{s-geq-0-gf-uc}.
\subsection{Single Generator Case}
\bl\label{gen-x}
Let $\cc=\genx$ be a spherical fusion category with a commutative Grothendieck ring, generated by a simple object $X$. Then:
\beq\label{eq-act}
\frac{\dimcc}{|\gwkc|}=\sum_{i=0}^r\dim(\cc^{j_i})\mu_{j_i}(X)\overline{\mu_{j_i}([X])},
\eeq
where $\mu_{j_i}\in \ca_i$ is arbitrarily chosen. 
\el
\bpf
Let $\ca_0, \ca_1, \dots, \ca_r\subseteq \wirrc$ be the non-vanishing orbits of the aforementioned group action. Since  $\gwkc$ actss freely on these orbits, we have that $|\ca_i|=|\gwkc|$ for all $0\leq i\leq r$. 


Starting from Equation \eqref{second:orth-2}, which we rewrite as:
\beq\label{second:orth-cc}
\dimcc=\sum_{j=0}^m\dim(\ccj)\big|\mu_j([X])\big |^2
\eeq
we observe that both the absolute value $|\mu_j([X])|$ and $\dim(\ccj)$ are constant on each orbit $\ca_i$. Thus, we may reorganize the sum as:
\begin{eqnarray*}
\dimcc
&=&
\sum_{i=0}^r\sum_{j\in \ca_i}\dimccj\big|\mu_j([X])\big|^2
=\sum_{i=0}^r |\ca_i|
\dim(\cc^\ji) \muji([X])\overline{\muji([X])}
\\&=& 
|\gwkc|\sum_{i=0}^r 
\dim(\cc^\ji) \muji([X])\overline{\muji([X])}
\end{eqnarray*}
The result follows by dividing both sides by $|\gwkc|$ and noting that $\gwkc \simeq \ucc$ by Remark \ref{gwkc-uc}.
\epf
\bl\label{s-geq-0-sgl} 
Let $\cc = \genx$ be a spherical fusion category with commutative Grothendieck ring generated by a simple object $X$. If $\cc$ is $s$-Isaacs, then:
$$
\frac{(\dimcc)^{s+1}}{\oucc\dim(X)}\in \mathbb A.
$$
\el
\bpf
From Equation \eqref{eq-act}, we derive:
\beq\label{eq-act-dimx}
\frac{\dimcc}{|\gwkc|\dim(X)}=\sum_{i=0}^r\dim(\cc^{j_i})\frac{\mu_{\ji}([X])}{\dim(X)}\overline{\mu_{j_i}([X])},
\eeq
Multiplying both sides by ${(\dimcc)^s}/{\dim(X)}$ yields:
\beq\label{eq-act-is-0}
\frac{(\dimcc)^{s+1}}{|\gwkc|\dim(X)}=\sum_{i=0}^r\lambda_0(\mu_\ji, X)\dim(\cc^{\ji})^{s}\overline{\mu_{j_i}([X])}\in \mathbb A.
\eeq
Since $\cc$ is Isaacs, $\lambda_0(\mu_\ji, X)\in \mathbb A$. For $s\geq 0$ we have that $\dim(\cc^{\ji})^{s}\in \mathbb A$ and also $\overline{\mu_{j_i}([X])}$ isn algebraic integer. Then the conclusion follows.
\epf
\subsection{General case for $s\geq 0$.}
We now extend our results to the general setting.
\bt\label{s-geq-0-gf-zcx}
Let $\cc$ be a  spherical fusion category and $X$ be a simple object of $\cc$ such that the fusion subcategory $<X>$ generated by $X$ is $s$- Isaacs fusion category. Then 
$$
\frac{(\dimcc)^{s+1}}{\ndim(Z_\cc(X))\dim(X)}\in \mathbb A.
$$
\et
\bpf
Let $\cd:=\genx$. Applying Lemma \ref{s-geq-0-sgl}  to  $\cd$ gives that:
$$
\dim(X)\mid \frac{(\dimcd)^{s+1}}{\oucd }.
$$
By Equation \eqref{eq-bantay} we have:
\beq\label{eq-bantay-pr}
\frac{(\dimcd)^{s+1}}{\oucd }=\frac{\dimcd}{|U(\cd)|}(\dimcd)^s=\frac{\dimcc}{\ndim(Z_\cc(X))}(\dimcd)^s.
\eeq
Since ${\dimcc}/{\dimcd}\in \mathbb A$ \cite{EGNO15}, we conclude that
$$
\dim(X)\mid \frac{(\dimcc)^{s+1}}{\ndim(Z_\cc(X))}.
$$
\epf
\subsubsection{Proof of Theorem \ref{s-geq-0-gf-uc}}
\begin{proof}
By Theorem \ref{s-geq-0-gf-zcx} we have that $\dim(X)$ divides $\frac{(\dimcc)^{s+1}}{\ndim(\zccx)}$. Using Equation \eqref{ndim} we obtain that $\dim(X)$ divides
\beq\label{eq-bantay-22}
(\dimcc)^{s}\frac{\dimcc}{\ndim(\zccx)}=(\dimcc)^{s}\frac{\fpcc}{n(\zccx)}.
\eeq
The result follows from Theorem \ref{uc-div} since $\wkc$ is real non-negative (RN).
\end{proof}
\subsubsection{Proof of Theorem \ref{ribbon-uc}}
By Remark \ref{br-unitary}, for pseudo-unitary braided fusion categories,  $\wkc$  is real non-negative (RN). Applying Theorem \ref{s-geq-0-gf-uc} with $s = 0$ yields:
$$
\frac{\fpcc}{\oucc \dim(X)}\in \mathbb A.
$$
\bt\label{isaacs-gf-uc-zccx}
Let $\cc$ be a  spherical fusion category and $X$ be a simple object of $\cc$ such that  $\genx$ is Isaacs. Then 
$$\dim(X)\mid \frac{\fp(\cc)}{n(Z_\cc(X))}$$
\et
\bpf
For $s=0$ in Theorem \ref{s-geq-0-gf-zcx} we have 
$$
\frac{\dimcc}{\ndim(Z_\cc(X))\dim(X)}\in \mathbb A.
$$
The conclusion follows from  Equation \eqref{ndim} .
\epf
\bt\label{isaacs-gf-uc}
Let $\cc$ be a spherical fusion category such that $\wkc$ is real non-negative (RN). Let $X$ be a simple object in $\cc$ such that  $\genx$ is Isaacs. Then 
$$\dim(X)\mid \frac{\fpcc}{\oucc}.$$
\et
\bpf
Since $\wkc$ is RN, Theorem \ref{uc-div} implies $\oucc \mid n(\zccx)$. The result then follows from Theorem \ref{isaacs-gf-uc-zccx}.
\epf
\br
Let $\cc$ be a spherical fusion category such that $\genx$ is $s$-Isaacs for some $X\in \irrcc$. 
Let 
$$
C_s:=\frac{(\dimcc)^{2s}\fpcc}{\dim(X)^2\oucc},\;D_s:=\frac{(\dimcc)^{s}\fpcc}{\dim(X)\oucc}.
$$
Note that $$D_s^2=C_s\frac{\fpcc}{\oucc}$$ and this implies that if $C_s\in \mathbb A$ then $D_s\in \mathbb A$ since $\fpcc/\oucc\in \mathbb A$. Thus, if $\genx$ is $s$-Isaac with $s\geq 1/2$ then the divisibility result of Theorem \ref{s-geq-0-gf-uc} is also satsfied.
\er
\section{The modular case}
Let $\cc$ be a premodular fusion category (i.e. braided and spherical). We maintain all previous  notation, particularly $\irr(\cc)=\{X_0, X_1,\dots,X_m\}$ for the simple objects, and $d_i:=\dim(X_i)$ for their quantum dimensions.



By \cite[Example 6.14]{scalg}  there is $\comp$-algebra homomorphism  (the Drinfeld map): $\fq: {\cfcc}\ra \cecc$ given by the following formula:
\beq\label{sh}
\fq(\ch_i)=\sum_{i'=0}^m\frac{s_{ii'}}{d_{i'}}E_{i'}.
\eeq
where $S=(s_{ij})$ is the $S$-matrix of $\cc$.


A premodular fusion category $\cc$ is called {\it modular} if its $S$-matrix is non-degenerated. By \cite[Proposition 3.7]{dgno} the S-matrix is non-degenerate if and only if $\ccpp=\vect$.


In the case of a modular tensor category $\cc$, the Drinfeld map $f_Q:\cfcc\ra\cecc$, as discussed in \cite[Example 6.14]{scalg}, is a an algebra isomorphism. Thus, for any (central) primitive idempotent  $F_j$ of $\cfcc$, we have that $\fq(F_j)$ is a (central) primitive idempotent of $\cecc$. Therefore, we have $\fq(F_j)=E_i$ for some central primitive idempotent $E_i\in \cecc$ corresponding to the simple object $V_i\in \irrcc$.   This yields a bijection $F_j\leftrightarrow V_i$  between the set of (central) primitive idempotents $\{F_j\}$ of $\cfcc$ and $\irrcc$. % the set $\{E_i\}$ of (central) primitive idempotents of $\cecc$.


This bijection was also discussed in  \cite[Section 6]{ccc-march}.  It allows us to index the (central) primitive idempotents of $\cfcc$ by the set $\mtc I$ defined above.  With this new indexation, the second item of \cite[Theorem 6.9]{ccc-march} implies that $\dim(\cci)=\dim(V_i)^2$ for any $i \in \mtc I$.

Moreover, under this new notation, applying $\fq^{-1}$ to Equation \eqref{sh} we have that
\beq\label{sh-2}
\ch_i=\sum_{i'=0}^m\frac{s_{ii'}}{d_{i'}}F_{i'}.
\eeq
which implies the crucial evaluation formula:
\beq\label{mf-i}
\mu_{i'}([\ch_i])=\frac{s_{ii'}}{d_{i'}}.
\eeq

\subsection{Proof of Theorem \ref{modular-uc}}
\bpf
Using Equation \eqref{mf-i}  and the fact that $\dim(\cc^i)=d_i^2$ for all $i$,  we transform Equation \eqref{eq-act} as:
\beq\label{eq-act-m}
\frac{\dimcc}{{|\gwkc|}}=\sum_{i=0}^rd_i^2\mu_{X_{i}}([X])\overline{\mu_{X_{i}}([X])}
\eeq
Equation \eqref{mf-i} gives that:
$d_i\mu_{i}([X])=\dim(X)\mu_X([X_i]),$ and Equation \eqref{eq-act-m}  becomes:
\beq\label{eq-act-m2}
\frac{\dimcc}{|\gwkc|\dim(X)^2}=\sum_{i=0}^r\mu_X([{X_{i}}])\overline{\mu_X([{X_{i}}])}
\eeq
which shows that  $\frac{\fpcc}{|\gwkc|\fp(X)^2}\in \mathbb A$ since $\mu_X([{X_{i}}])\in \mathbb A$.
\epf

\subsection{Ito-Michler theorem for modular categories.}
In this section we prove Theorem \ref{im-converse}: 
\bpf
For any simple object $X$, consider $\mathcal{D} = \genx$. Then  $\cd$ is weakly integral and therefore pseudo-unitary. Since $\cd$ is also braided it is Isaacs and therefore Theorem \ref{ribbon-uc} can be applied. 

Thus we have that $\fp(X)^2\mid \frac{\fpcc^2}{\oucc^2}$. Since $\cc$ is weakly integral it follows that $\fp(X)^2\in \mathbb Z_{>0}$ and since $p\nmid  \frac{\fpcc^2}{\oucc^2}$ it follows that $p\nmid \fpx^2$.
\epf
\subsubsection{Proof of Corollary \ref{complete-im}}
It follows from \cite[Proposition 1.3]{b-conj-im} and Theorem \ref{im-converse}.
\subsection{Conjectural Extensions}
In \cite{eno-nec}, the authors proposed the following conjecture:
\begin{conjecture} \label{eno-conj}\cite{eno-nec}
Any spherical fusion category is 1-Isaacs. 
\end{conjecture}  
Using Theorem \ref{s-geq-1/2-gf-uc}, note that  Conjecture \ref{eno-conj} implies the following:
\begin{conjecture}\label{mine}
Let $\cc$ be a spherical fusion category such that $\wkc$ is real non-negative (RN).
For any simple object $X$ of $\cc$, we have:
$$
\frac{(\dimcc)^2\fp(\cc)}{\dimx^2\oucc}\in \mathbb A.
$$
\end{conjecture}
