\section{Hodge theoretical aspects of the infinitesimal Torelli problems} \label{section_geo_torelli}
	The goal of this section is to prove Theorem~\ref{main_theorem_1} and Proposition~\ref{main_theorem_Verra}. We first collect some background materials on Hodge theory of double covers of Fano threefolds in Subsection~\ref{subsec_pairys} and Subsection~\ref{subsec_rigidfano}. In particular, a result that will be needed later on deformations of branch divisors is recalled. Then we focus on the case of special Gushel-Mukai threefolds and prove Theorem~\ref{main_theorem_1} in Subsection~\ref{subsec_reductionk3} and Subsection~\ref{subsec_twistedtorelli}. Our approach can also be applied to study infinitesimal Torelli problems for other double covers of rigid Fano threefolds ramified over an anticanonical divisor, such as special Verra threefolds. We conclude this section by giving an outline of the proof for Proposition~\ref{main_theorem_Verra} in Subsection~\ref{subsec_specialverra}.

\subsection{Exact sequences associated with a divisor}\label{subsec_pairys}

	In this subsection, we collect some short exact sequences that will be used later. Let $Y$ be a smooth projective variety of dimension $n$, and let $S\subset Y$ be a smooth prime divisor. Let $\langle z_{1}, z_{2}, \cdots z_{n}\rangle$ be a local coordinate of $Y$ such that $S=\{z_{1}=0\}$. Define $T_{Y}(-\log S)$ as the sub-sheaf of the tangent bundle $T_{Y}$ locally generated by $\langle z_{1}\partial_{z_{1}}, \partial_{z_{2}}, \cdots, \partial_{z_{n}}\rangle$. Similarly, define the sheaf $\Omega^{m}_{Y}(\log S)$ to be the $\mathcal{O}_Y$-module locally generated by $m$-forms $dz_{J}$ and $\frac{dz_{1}}{z_{1}}\wedge dz_{I}$, where $dz_{I}$ and $dz_{J}$ do not contain  $dz_{1}$. We will need the following short exact sequences:
\begin{equation}\label{normalbundle}
    0\rightarrow T_{S}\rightarrow T_{Y}\vert_{S}\rightarrow\mathcal{N}_{S\vert Y}\rightarrow 0.
\end{equation}
\begin{equation}\label{second}
    0\rightarrow T_{Y}(-\log S)\rightarrow T_{Y}\rightarrow\mathcal{N}_{S\vert Y}\rightarrow 0.
\end{equation}
\begin{equation}\label{third}
    0\rightarrow T_{Y}\otimes \mathcal{O}_{Y}(-S)\rightarrow T_{Y}(-\log S)\rightarrow T_{S}\rightarrow 0.
\end{equation}
The first exact sequence is the normal bundle exact sequence. Locally, the second exact sequence \eqref{second} can be described as
\begin{equation*}
    0\rightarrow \mathcal{O}_{\mathbb{C}^{n}}\otimes\langle z_{1}\partial_{z_{1}},\partial_{z_{2}}, \cdots, \partial_{z_{n}}\rangle\rightarrow \mathcal{O}_{\mathbb{C}^{n}}\otimes\langle \partial_{z_{1}},\partial_{z_{2}}, \cdots, \partial_{z_{n}}\rangle\rightarrow \mathcal{O}_{\{z_{1}=0\}}\otimes \partial_{z_{1}}\rightarrow 0,
\end{equation*}
where the rightmost arrow is given by the natural homomorphism which maps $\sum^{n}_{i=1}f_{i}\otimes \partial_{z_{i}}$ to $f_{1}\vert_{z_{1}=0}\otimes \partial_{z_{1}}$.
The third exact sequence \eqref{third} is locally given by
\begin{equation*}
     0\rightarrow \mathcal{O}_{\mathbb{C}^{n}}\otimes z_{1}\langle \partial_{z_{1}},\partial_{z_{2}}, \cdots, \partial_{z_{n}}\rangle\rightarrow \mathcal{O}_{\mathbb{C}^{n}}\otimes \langle z_1\cdot\partial_{z_1},\partial_{z_2}, \cdots, \partial_{z_n} \rangle\rightarrow \mathcal{O}_{\{z_1=0\}}\otimes \langle \partial_{z_2}, \cdots, \partial_{z_n}\rangle\rightarrow 0, 
\end{equation*}
where the last natural map sends $f_{1}\otimes z_{1}\cdot \partial_{z_{1}}+\sum^{n}_{i=2}f_{i}\otimes \partial_{z_{i}}$ to $\sum^{n}_{i=2}f_{i}\vert_{z_{1}=0}\otimes \partial_{z_{i}}$.
In addition, the following short exact sequence will also be useful for us:
\begin{equation}\label{4}
    \xymatrix{0\ar[r]& \Omega^{m}_{Y}\ar[r]& \Omega^{m}_{Y}(\log S)\ar[r]^{res}&\Omega^{m-1}_{S}\ar[r]& 0.}    
\end{equation}
Here the arrow $res$ denotes the residue map and is locally defined by mapping $f(z_1,z_2,\cdots,z_n)\frac{dz_{1}}{z_{1}}\wedge dz_2\wedge dz_3\wedge \cdots \wedge dz_n +\alpha$ to $f(z_1,z_2,\cdots,z_n)\vert_{z_1=0}\cdot dz_2\wedge dz_3\wedge \cdots \wedge dz_n$.

\begin{lem}\label{commutativesheaves}
	We have a commutative diagram up to a sign (where the horizontal arrows denote the natural multiplication maps).
    $$\xymatrix@C=2cm{T_{S}\otimes \Omega^{m-1}_{S}\ar[r]^{m_1}&\Omega^{m-2}_{S}\\
 T_{Y}(-\log S)\otimes\Omega^{m}_{Y}(\log S)\ar[u]^{res_1}\ar[r]^{m_2}&\Omega^{m-1}_{Y}(\log S)\ar[u]^{res_2}.}$$
\end{lem}
\begin{proof}
	We prove this claim locally. Let $U=\langle z_1,z_2,\cdots, z_n \rangle$ be a local coordinate of $X$ such that $S=\{z_1=0\}$. Let $\alpha=a_1\cdot z_1\cdot \partial_{z_1}+\sum^{n}_{i=2}a_{i}\cdot\partial_{z_{i}}\in \Gamma_{U}(T_{Y}(-\log S))$, and $\beta=\frac{dz_1}{z_1}\wedge K_1+K_2\in \Gamma(\Omega^{m}_{U}(\log S))$. On one hand,
\begin{align*}
    res_2\circ m_{2}(\alpha,\beta)=& res_{2}(a_1K_1-\frac{dz_1}{z_1}\wedge(\sum^{n}_{i=2}a_{i}\cdot\partial_{z_{i}})\cdot K_1+(\sum^{n}_{i=2}a_{i}\cdot\partial_{z_{i}})\cdot K_2))\\
    =&-(\sum^{n}_{i=2}a_{i}\cdot\partial_{z_{i}})\cdot K_1\vert_{z_{1}=0}.
\end{align*}
On the other hand,
\begin{align*}
    m_1\circ res_1(\alpha,\beta)=&m_1(\sum^{n}_{i=2}a_{i}\vert_{z_{1}=0}\cdot\partial_{z_{i}},K_1\vert_{z_{1}=0}) \\
                    =& (\sum^{n}_{i=2}a_{i}\cdot\partial_{z_{i}})\cdot K_1\vert_{z_{1}=0}.
\end{align*}
Thus $res_2\circ m_2=-m_1\circ res_1$. Namely, the diagram above is commutative up to a sign.   
\end{proof}

\subsection{Double covers of Fano threefolds}\label{subsec_rigidfano}
	Let us first recall in this subsection some fundamental results concerning infinitesimal Torelli problems for double covers of Fano threefolds (more generally, see \cite{konno1985deformations}). In the remaining part, we restrict ourself to the case when the base is a rigid Fano threefold and the branch divisor is an anticanonical divisor (which is also a $K3$ surface). In particular, we identify a subspace inside the space of infinitesimal deformations of the branch divisor which will play an important role in our approach. 

	For our purpose, suppose that $X$ is a Fano threefold admitting a double covering map to another Fano threefold $Y$ ramified over a smooth prime divisor $S\subset Y$. Let us also denote the associated line bundle on $Y$ by $\mathcal{L}$; in particular, $\mathcal{L}^{2}\cong \mathcal{O}_Y(S)$. We say the infinitesimal Torelli theorem holds for $X$ if the infinitesimal period map 
    $$d\mathcal{P}: \mathrm{H}^{1}(X,T_{X})\rightarrow \mathrm{Hom}(\mathrm{H}^{1}(X,\Omega^{2}_{X}), \mathrm{H}^{2}(X,\Omega^{1}_{X})),$$ 
which is induced by the cup product map $T_{X}\otimes \Omega^{2}_{X}\rightarrow \Omega^{1}_{X}$, is injective. 

	Taking the covering involution into consideration, one has the following decompositions.
\begin{prop}(\cite[Lemma 1.1]{konno1985deformations})\label{doublecovercohomology}
	We have the following isomorphisms which are decompositions into the invariant and anti-invariant subspaces with respect to the covering involution:
\begin{itemize}
	\item $\mathrm{H}^{1}(X,T_{X})\cong \mathrm{H}^{1}(Y,T_{Y}(-\log S))\oplus \mathrm{H}^{1}(Y,T_{Y}\otimes \mathcal{L}^{-1})$;
	\item $\mathrm{H}^{1}(X,\Omega^{2}_{X})\cong \mathrm{H}^{1}(Y,\Omega^{2}_{Y})\oplus \mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)\otimes \mathcal{L}^{-1})$;
       \item $\mathrm{H}^{2}(X,\Omega^{1}_{X})\cong \mathrm{H}^{2}(Y,\Omega^{1}_{Y})\oplus \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)\otimes \mathcal{L}^{-1})$.
\end{itemize}
\end{prop}

	Furthermore, since the cup product map is compatible with the Leray spectral sequence, the infinitesimal period map $d\mathcal{P}$ can be decomposed into the invariant and anti-invariant maps (cf.~\cite[P.609]{konno1985deformations}) as follows:
    $$
    \begin{array}{lll}
    \mathrm{H}^{1}(Y,T_{Y}(-\log S)) & \rightarrow & \mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}), \mathrm{H}^{2}(Y,\Omega^{1}_{Y}))  \\
    & & \oplus \ \mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)\otimes \mathcal{L}^{-1}), \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)\otimes \mathcal{L}^{-1})); \\
    \mathrm{H}^{1}(Y,T_{Y}\otimes \mathcal{L}^{-1}) & \rightarrow & \mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}), \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)\otimes \mathcal{L}^{-1})) \\
    & & \oplus \ \mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)\otimes \mathcal{L}^{-1}), \mathrm{H}^{2}(Y,\Omega^{1}_{Y})).
    \end{array}
    $$

\begin{rem}
	Assume that $\mathrm{H}^{1}(Y,\Omega^{2}_{Y})=0$ (and by Hodge decomposition $\mathrm{H}^{2}(Y,\Omega^{1}_{Y})=0$). Then the invariant part of the infinitesimal period map becomes 
    $$\mathrm{H}^{1}(Y,T_{Y}(-\log S)) \rightarrow\mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)\otimes \mathcal{L}^{-1}), \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)\otimes \mathcal{L}^{-1}))$$
and the anti-invariant part is the zero map.
\end{rem}

	Now we assume in addition that $Y$ is a rigid Fano threefold. Namely $\mathrm{H}^1(Y,T_{Y})=0$. We also assume that $\mathrm{H}^{1}(T_{Y}\otimes \mathcal{O}_{Y}(-S))=0$. Note that this condition automatically holds when $S$ is a smooth anticanonical $K3$ surface.
\begin{lem}\label{vanishincondition}
	Assume $S\in \vert -K_{Y}\vert$ and $\mathrm{H}^{1}(Y,\Omega^{2}_{Y})=0$, then $\mathrm{H}^{1}(T_{Y}\otimes \mathcal{O}_{Y}(-S))=0$.  
\end{lem}
\begin{proof}
  Since $T_{Y}\otimes \mathcal{O}_{Y}(-S)\cong \Omega^{2}_{Y}$, we have $\mathrm{H}^{1}(Y,T_{Y}\otimes \mathcal{O}_{Y}(-S))\cong \mathrm{H}^{1}(Y,\Omega^{2}_{Y})=0$.  
\end{proof}

	The short exact sequence \eqref{second} induces the following long exact sequence by taking global sections on $Y$:
\begin{equation}
   \ldots \rightarrow \mathrm{H}^{0}(S,\mathcal{N}_{S\vert Y})\rightarrow \mathrm{H}^{1}(Y,T_{Y}(-\log S))\rightarrow  \mathrm{H}^{1}(Y,T_{Y})\rightarrow \ldots.
\end{equation}
Hence we have a map $\mathrm{H}^{0}(S,\mathcal{N}_{S\vert Y})\twoheadrightarrow \mathrm{H}^{1}(Y,T_{Y}(-\log S))$ and this map is surjective since $\mathrm{H}^1(Y,T_Y)=0$. 

	Similarly, the short exact sequence \eqref{third} induces a long exact sequence
\begin{equation}\label{6}
    \ldots\rightarrow \mathrm{H}^{1}(Y,T_{Y}\otimes \mathcal{O}_{Y}(-S))\rightarrow \mathrm{H}^{1}(Y,T_{Y}(-\log S))\rightarrow \mathrm{H}^{1}(S,T_{S})\rightarrow\ldots.
\end{equation}
By our assumption, $\mathrm{H}^{1}(T_{Y}\otimes \mathcal{O}_{Y}(-S))=0$. As a consequence, we get an injective map $\mathrm{H}^{1}(Y,T_{Y}(-\log S))\hookrightarrow \mathrm{H}^{1}(S,T_{S})$.

\begin{prop}\label{equalKS}
	The composition $\mathrm{H}^{0}(S,\mathcal{N}_{S\vert Y})\twoheadrightarrow \mathrm{H}^{1}(Y,T_{Y}(-\log S))\hookrightarrow \mathrm{H}^{1}(S,T_{S})$ coincides with the Kodaira-Spencer map $\operatorname{KS}$ obtained using the long exact sequence associated to the short exact sequence \eqref{normalbundle}. In particular, the image of $\mathrm{H}^{1}(Y,T_{Y}(-\log S))$ in $\mathrm{H}^{1}(S,T_{S})$ is the image $\mathrm{H}^{1}(S,T_{S})_0$ of the Kodaira-Spencer map.
\end{prop}
\begin{proof}
	The first claim follows from the commutativity of restriction and difference of vector fields. The second claim is an immediate consequence of the surjectivity of the map $\mathrm{H}^{0}(S,\mathcal{N}_{S\vert Y})\rightarrow \mathrm{H}^{1}(Y,T_{Y}(-\log S))$.   
\end{proof}

\begin{rem}\label{rmk_equivariantdp}
   Geometrically, $\mathrm{H}^{1}(Y,T_{Y}(-\log S))$ represents the equivalent classes of deformations of $S$ inside $Y$. By Proposition~\ref{equalKS}, it can be identified with the image $\mathrm{H}^{1}(S,T_{S})_0$ of the Kodaira-Spencer map which will play an important rule in the proof of Theorem~\ref{main_theorem_1}.
\end{rem}

\begin{rem}
	In \cite{Guilargregri24}, the authors introduce infinitesimal variations of mixed Hodge structures associated to pairs $(Y,S)$ where $Y$ is a Fano threefold and $S$ an anticanonical divisor. It would be an interesting problem to study related infinitesimal Torelli problems.
\end{rem}

\subsection{Special Gushel-Mukai threefolds and the branch $K3$ surfaces}\label{subsec_reductionk3}
    From now on, we focus on special Gushel-Mukai threefolds. Let $Y$ be a codimension $3$ linear section of the Grassmannian $\mathrm{Gr}(2,5)$, i.e. $Y=\mathrm{Gr}(2,5)\cap \mathbb{P}^{6}\subset \mathbb{P}^{9}$. Note that $Y$ is a rigid Fano threefold with $\mathrm{H}^{1}(Y,\Omega^{2}_{Y})=0$. We use $\mathcal{O}_{Y}(m)$ to denote $\mathcal{O}_{Y}(mH)$, where $H$ is a hyperplane section on $Y$ in $\mathbb{P}^6$. In particular, the canonical bundle $\omega_Y\cong\oh_Y(K_{Y})\cong \mathcal{O}_Y(-2)$. Let $S=Y\cap Q$ where $Q$ is a quadric in $\mathbb{P}^{9}$. Then $S\in \vert-K_{Y}\vert$ and it is a degree $10$ smooth $K3$ surface. A special Gushel-Mukai threefold $X$ is the double cover of $Y$ branched along $S$ (which is associated with the line bundle $\mathcal{L}=\mathcal{O}_{Y}(1)$). It is known that $h^{1}(X,T_X)=\operatorname{dim}\mathrm{H}^{1}(X,T_{X})=22$. Moreover, all the discussions in Subsection~\ref{subsec_pairys} and Subsection~\ref{subsec_rigidfano} are applicable for special Gushel-Mukai threefolds. 

\begin{lem}\label{invariantsubspace3k}
	The anti-invariant subspace $\mathrm{H}^{1}(Y,T_{Y}(-1))$ of $\mathrm{H}^{1}(X,T_{X})$ is contained in the kernel of the infinitesimal period map $d\mathcal{P}$ (see Subsection~\ref{subsec_rigidfano}). Moreover, $\operatorname{dim} \mathrm{H}^{1}(Y,T_{Y}(-1))=3$.
\end{lem}
\begin{proof}
	Let $\iota$ be the covering involution associated with the special Gushel-Mukai threefold $X$. The first statement essentially follows from the decomposition of $d\mathcal{P}$ into the invariant and the anti-invariant parts with respect to $\iota$ (see Remark~\ref{rmk_equivariantdp}). In more detail, suppose there exists $\beta\in \mathrm{H}^{1}(Y,T_{Y}(-1))$ such that $d\mathcal{P}(\beta)\neq 0$. Then there exists $\alpha\in \mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1))$ such that $\beta\cdot \alpha\neq 0$. However, $$\iota(\beta\cdot \alpha)=\iota(\beta)\cdot \iota(\alpha).$$
The left hand side is $-\beta\cdot \alpha$, but the right hand side is $\beta\cdot \alpha$. Therefore $\beta\cdot \alpha=0$ which is a contradiction. Thus, $\mathrm{H}^{1}(Y,T_{Y}(-1))$ is contained in the kernel of $d\mathcal{P}$. For the second statement, consider the exact sequence which is obtained from \eqref{second}
\begin{equation}\label{7}
    \ldots\rightarrow \mathrm{H}^{1}(S,\mathcal{N}_{S\vert Y})\rightarrow \mathrm{H}^{2}(Y,T_{Y}(-\log S))\rightarrow \mathrm{H}^{2}(Y,T_{Y})\rightarrow\ldots.  
\end{equation}
By Kodaira-Akizuki–Nakano vanishing, $\mathrm{H}^{1}(S,\mathcal{N}_{S\vert Y})\cong \mathrm{H}^{1}(S,-K_{Y}\vert_{S})=0$, and $\mathrm{H}^{2}(Y,T_{Y})\cong \mathrm{H}^{2}(Y,\Omega^{2}_{Y}\otimes \omega^{-1}_{Y})=0$. Therefore, we have $\mathrm{H}^{2}(Y,T_{Y}(-\log S))=0$. 
Since $T_{Y}\otimes \mathcal{O}_{Y}(-S)\cong \Omega^{2}_{Y}$, we get $\mathrm{H}^{1}(Y,T_{Y}\otimes \mathcal{O}_{Y}(-S))=0$, and $\mathrm{H}^{2}(Y,T_{Y}\otimes \mathcal{O}_{Y}(-S))=\mathbb{C}$. Therefore, the exact sequence~\eqref{6} becomes
\begin{equation}\label{8}
    0\rightarrow \mathrm{H}^{1}(Y,T_{Y}(-\log S))\hookrightarrow \mathrm{H}^{1}(S,T_{S})\rightarrow \mathbb{C}\rightarrow 0.
\end{equation}
It follows that $\operatorname{dim}\mathrm{H}^{1}(Y,T_{Y}(-\log S))=\operatorname{dim}\mathrm{H}^{1}(S,T_{S})-1=19$. According to Proposition~\ref{doublecovercohomology}, we conclude that $\operatorname{dim}\mathrm{H}^{1}(Y,T_{Y}(-1))=\operatorname{dim}\mathrm{H}^{1}(X,T_{X})- \operatorname{dim}\mathrm{H}^{1}(Y,T_{Y}(-\log S))=3$. 
\end{proof}

Next, we state the first main result of our article. 
\begin{thm}\label{maintheorem}
	Let $X$ be a special Gushel-Mukai threefold. Then the kernel of the infinitesimal period map 
    $$\mathrm{H}^1(X,T_X)\rightarrow \mathrm{Hom}(\mathrm{H}^{1}(X,\Omega^{2}_{X}), \mathrm{H}^{2}(X,\Omega^{1}_{X}))$$
is isomorphic to the direct summand $\mathrm{H}^1(Y,T_Y(-1))$ of $\mathrm{H}^1(X,T_X)$ which has dimension 3.
\end{thm}

	By Proposition~\ref{doublecovercohomology} and Lemma~\ref{invariantsubspace3k}, it suffices to prove the following theorem.
\begin{thm}\label{logtorelli}
	The invariant infinitesimal period map
    $$\mathrm{H}^{1}(Y,T_{Y}(-\log S))\rightarrow \mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1)), \mathrm{H}^{2}(Y,\Omega_{Y}(\log S)(-1)))$$
    is injective.
\end{thm}

    We will reduce the proof of Theorem~\ref{logtorelli} to a result regarding the branch $K3$ surface $S$. First, by taking $m=1,2$ in the short exact sequence \eqref{4}, we get the following short exact sequences:
\begin{equation}\label{8}
    0\rightarrow \Omega^{1}_{Y}(-1)\rightarrow \Omega^{1}_{Y}(\log S)(-1)\rightarrow \mathcal{O}_{S}(-1)\rightarrow 0. 
\end{equation}
\begin{equation}\label{9}
    0\rightarrow \Omega^{2}_{Y}(-1)\rightarrow \Omega^{2}_{Y}(\log S)(-1)\rightarrow \Omega^{1}_{S}(-1)\rightarrow 0.     
\end{equation}
Note that the rightmost maps of the short exact sequences are the residual maps. The short exact sequences \eqref{8} and \eqref{9} induce the following exact sequences respectively:
\begin{equation}
    \ldots\rightarrow \mathrm{H}^{1}(Y,\Omega^{2}(\log S)(-1))\rightarrow \mathrm{H}^{1}(S,\Omega^{1}_{S}(-1))\rightarrow \mathrm{H}^{2}(Y,\Omega^{2}_{Y}(-1))\rightarrow \ldots.
\end{equation}
\begin{equation}
    \ldots\rightarrow \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1))\rightarrow \mathrm{H}^{2}(S,\mathcal{O}_{S}(-1))\rightarrow \ldots.
\end{equation}

\begin{prop}\label{commutativediagram}
    We have a commutative diagram up to a sign. Moreover, the leftmost vertical map is injective. 
    $$\xymatrix{& &\mathrm{H}^{2}(Y,\Omega^{2}_{Y}(-1)) & \\
    \mathrm{H}^{1}(S,T_{S}) &\otimes &\mathrm{H}^{1}(S,\Omega^{1}_{S}(-1))\ar[r]^{m_1}\ar[u] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1))\\
    \mathrm{H}^{1}(Y,T_{Y}(-\log S))\ar@{^{(}->}[u] &\otimes &\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1))\ar[r]^{m_2}\ar[u]^{res_1} &\mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1))\ar[u]^{res_2}.\\}$$ 
\end{prop}
\begin{proof}
	Twisting the commutative diagram in Lemma~\ref{commutativesheaves} with $\mathcal{O}_{Y}(-1)$, we get the following commutative diagram of sheaves up to a sign:
    $$\xymatrix@C=2cm{T_{S}\times \Omega^{1}_{S}(-1)\ar[r]^{m_1}&\mathcal{O}_{S}(-1)\\
    T_{Y}(-\log S)\times\Omega^{2}_{Y}(\log S)(-1)\ar[u]^{res_1}\ar[r]^{m_2}&\Omega^{1}_{Y}(\log S)(-1)\ar[u]^{res_2}.}$$
Taking the cohomology of the sheaves, we obtain the commutative diagram in the proposition. The injectivity of the leftmost arrow follows from Proposition~\ref{equalKS}.
\end{proof}

\begin{lem}\label{vanishingsurjective}
	The cohomology group $\mathrm{H}^{2}(Y,\Omega^{2}_{Y}(-1))=0$, and hence the map $res_1$ in Proposition~\ref{commutativediagram} is surjective.
\end{lem}
\begin{proof}
First, we have an isomorphism of vector bundles $\Omega^{2}_{Y}\otimes \omega^{-1}_{Y}\cong T_{Y}$. Next, since $\omega_{Y}\cong \mathcal{O}_{Y}(-2)$, we get $\Omega^{2}_{Y}(-1)\cong T_{Y}(-3)$. Therefore,
$$\mathrm{H}^{2}(Y,\Omega_{Y}^2(-1))\cong \mathrm{H}^{2}(Y,T_{Y}(-3)).$$
According to the normal bundle formula, there exists a short exact sequence
\begin{equation}
    0\rightarrow T_{Y}\rightarrow T_{\mathrm{Gr}(2,5)}\vert_{Y}\rightarrow \mathcal{O}_{Y}(1)^{\oplus 3}\rightarrow 0.
\end{equation}
Tensoring with $\mathcal{O}_{Y}(-3)$, one obtains a short exact sequence
\begin{equation}\label{13}
    0\rightarrow T_{Y}(-3)\rightarrow T_{\mathrm{Gr}(2,5)}(-3)\vert_{Y}\rightarrow \mathcal{O}_{Y}(-2)^{\oplus 3}\rightarrow 0.
\end{equation}
Consider the long exact sequence associated with \eqref{13}
\begin{equation}\label{14}
    \ldots\rightarrow \mathrm{H}^{1}(Y,\mathcal{O}_{Y}(-2))^{\oplus 3}\rightarrow \mathrm{H}^{2}(Y,T_{Y}(-3))\rightarrow \mathrm{H}^{2}(Y, T_{\mathrm{Gr}(2,5)}(-3)\vert_{Y}) \rightarrow\ldots.   
\end{equation}
By Kodaira vanishing theorem, $\mathrm{H}^{1}(Y,\mathcal{O}_{Y}(-2))=0$. Now let us show the vanishing of $\mathrm{H}^{2}(Y,T_{\mathrm{Gr}(2,5)}(-3)\vert_{Y})$, and then the proof will be finished.
Since $Y\subset \mathrm{Gr}(2,5)$, we have a Koszul resolution
 \begin{equation}
     0\rightarrow\mathcal{O}_{\mathrm{Gr}(2,5)}(-3)\rightarrow \mathcal{O}_{\mathrm{Gr}(2,5)}(-2)^{\oplus 3}\rightarrow \mathcal{O}_{\mathrm{Gr}(2,5)}(-1)^{\oplus 3}\rightarrow \mathcal{O}_{\mathrm{Gr}(2,5)}\rightarrow \mathcal{O}_{Y}\rightarrow 0. 
 \end{equation}
 Tensoring with the bundle $T_{\mathrm{Gr}(2,5)}(-3)$, we obtain a new exact sequence
 \begin{equation}\label{16}
  0\rightarrow T_{\mathrm{Gr}(2,5)}(-6)\rightarrow T_{\mathrm{Gr}(2,5)}(-5)^{\oplus 3}\rightarrow T_{\mathrm{Gr}(2,5)}(-4)^{\oplus 3}\rightarrow T_{\mathrm{Gr}(2,5)}(-3)\rightarrow T_{\mathrm{Gr}(2,5)}(-3)\vert_{Y}\rightarrow 0.   
\end{equation}
Next, we introduce a trick from homological algebra, which will be useful for our computation.
\begin{lem}\label{homologicalvanishing}
	Let $\mathcal{A}$ be an abelian category. Consider an exact sequence of finite length 
\begin{equation}\label{17}
    0\rightarrow E_{n}\rightarrow E_{n-1}\rightarrow \cdots \rightarrow E_{1}\rightarrow E_{0}\rightarrow 0.
\end{equation}
Fix an integer $i$, if 
    $$\mathrm{H}^{i}(E_{1})=\mathrm{H}^{i+1}(E_{2})=\cdots=\mathrm{H}^{n+i-2}(E_{n-1})=\mathrm{H}^{n+i-1}(E_{n})=0,$$
then $\mathrm{H}^{i}(E_{0})=0$.
\end{lem}
\begin{proof}
We prove this by induction. For $n=2$, we have a short exact sequence
    $$0\rightarrow E_{2}\rightarrow E_{1}\rightarrow E_{0}\rightarrow 0.$$
The exact sequence associated to this short exact sequence is
   $$\ldots\rightarrow \mathrm{H}^{i}(E_{1})\rightarrow \mathrm{H}^{i}(E_{0})\rightarrow \mathrm{H}^{i+1}(E_{2}) \rightarrow\ldots.$$
By assumption, $\mathrm{H}^{i}(E_{1})=\mathrm{H}^{i+1}(E_{2})=0$, hence $\mathrm{H}^{i}(E_{0})=0$. Now, assume the result holds for length $n-1$ exact sequences. Split the exact sequence of \eqref{17} into the following two exact sequences:
\begin{equation*}
    0\rightarrow E_{n}\rightarrow E_{n-1}\rightarrow \operatorname{Im}d_{n-1}\rightarrow 0.
\end{equation*}
\begin{equation*}
    0\rightarrow \operatorname{Im}d_{n-1}\rightarrow E_{n-2}\rightarrow E_{n-3}\rightarrow \cdots \rightarrow E_{1}\rightarrow E_{0}\rightarrow 0.
\end{equation*}
Since $\mathrm{H}^{i+n-1}(E_{n})=\mathrm{H}^{i+n-2}(E_{n-1})=0$, we know $\mathrm{H}^{i+n-1-1}(\operatorname{Im}d_{n-1})=0$. By induction, we get $\mathrm{H}^{i}(E_{0})=0$.
\end{proof}

\begin{lem}\label{grassmanianvanishing}
    The following cohomology groups of the Grassmiann $\mathrm{Gr}(2,5)$ vanish: $\mathrm{H}^{5}(\mathrm{Gr}(2,5),T_{\mathrm{Gr}(2,5)}(-6))=\mathrm{H}^{4}(\mathrm{Gr}(2,5),T_{\mathrm{Gr}(2,5)}(-5))=\mathrm{H}^{3}(\mathrm{Gr}(2,5),T_{\mathrm{Gr}(2,5)}(-4))=\mathrm{H}^{2}(\mathrm{Gr}(2,5),T_{\mathrm{Gr}(2,5)}(-3))=0.$
\end{lem}
\begin{proof}
 According to \cite[P.171]{Sno86}, $\mathrm{H}^{p}(\mathrm{Gr}(2,5),\Omega^{q}_{\mathrm{Gr}(2,5)}(k))=0$ for $1\leq k\leq 4$ if any of the following conditions hold:
\begin{enumerate}
    \item $2p\geq q>0$;
    \item $p>6-q$;
    \item $q>4$;
    \item $q\leq k$, and $p>0$.
\end{enumerate}
Since $\omega_{\mathrm{Gr}(2,5)}\cong \mathcal{O}_{\mathrm{Gr}(2,5)}(-5)$, we have 
$T_{\mathrm{Gr}(2,5)}(-5)\cong \Omega^{5}_{\mathrm{Gr}(2,5)}$. Then, using condition (3), we get that $\mathrm{H}^{3}(\mathrm{Gr}(2,5), T_{\mathrm{Gr}(2,5)}(-4))\cong \mathrm{H}^{3}(\mathrm{Gr}(2,5), \Omega^{5}_{\mathrm{Gr}(2,5)}(1))=0$, and that $\mathrm{H}^{2}(\mathrm{Gr}(2,5), T_{\mathrm{Gr}(2,5)}(-3))\cong \mathrm{H}^{2}(\mathrm{Gr}(2,5), \Omega^{5}_{\mathrm{Gr}(2,5)}(2))=0$. Because $\mathrm{H}^{9}(\mathrm{Gr}(2,5), \mathbb{C})=0$, Hodge decomposition implies that $\mathrm{H}^{4}(\mathrm{Gr}(2,5), T_{\mathrm{Gr}(2,5)}(-5))\cong \mathrm{H}^{4}(\mathrm{Gr}(2,5), \Omega^{5}_{\mathrm{Gr}(2,5)})=0$. Finally, by Serre duality,
    $$\mathrm{H}^{5}(\mathrm{Gr}(2,5), T_{\mathrm{Gr}(2,5)}(-6))\cong \mathrm{H}^{1}(\mathrm{Gr}(2,5), \Omega^{1}_{\mathrm{Gr}(2,5)}(6)\otimes \omega_{\mathrm{Gr}(2,5)})^{\vee}\cong \mathrm{H}^{1}(\mathrm{Gr}(2,5), \Omega^{1}_{\mathrm{Gr}(2,5)}(1))^{\vee}=0$$
where the last equality is deduced from condition (1).
\end{proof}

    Now let us go back to the proof of Lemma~\ref{vanishingsurjective}. By Lemma~\ref{homologicalvanishing}, Lemma~\ref{grassmanianvanishing} and the exact sequence \eqref{16}, we have $\mathrm{H}^{2}(Y,T_{\mathrm{Gr}(2,5)}(-3)\vert_{Y})=0$, which implies $\mathrm{H}^{2}(Y,\Omega^{2}_{Y}(-1))\cong \mathrm{H}^{2}(Y,T_{Y}(-3))=0$ (using the exact sequence \eqref{14}). The proof is then completed.
\end{proof}

    Recall that, according to Proposition~\ref{equalKS}, we have an injection $\mathrm{H}^{1}(Y,T_{Y}(-\log S))\hookrightarrow \mathrm{H}^{1}(S,T_{S})$. Moreover, the image coincides with the image of the Kodaira-Spencer map $\operatorname{KS}: \mathrm{H}^{0}(S,\mathcal{N}_{S\vert Y})\rightarrow \mathrm{H}^{1}(S,T_{S})$ (induced by the short exact sequence \eqref{normalbundle}), which we denote by $\mathrm{H}^{1}(S,T_{S})_{0}$ from now on. The following lemma explains how to reduce the proof of Theorem~\ref{logtorelli} to a twisted version of the infinitesimal Torelli theorem for the anticanonical $K3$ surface $S\subset Y$. 
\begin{lem}\label{twistedtorelliK3tologtorelli}
If the pairing 
    $$\mathrm{H}^1(S,T_S)_{0}\otimes \mathrm{H}^1(S,\Omega_S^{1}(-1))\rightarrow \mathrm{H}^2(S,\oh_S(-1))$$
is non-degenerate with respect to the first factor, then the pairing
    $$\mathrm{H}^{1}(Y,T_{Y}(-\log S)\otimes \mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1))\rightarrow \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1))$$
is non-degenerate with respect to the first factor.
\end{lem}
\begin{proof}
	Notation as in Proposition~\ref{commutativediagram}. Take any non-zero element $\alpha\in \mathrm{H}^{1}(Y,T_{Y}(-\log S))$ and regard $\alpha\in \mathrm{H}^{1}(S,T_{S})_{0}$. Since   
    $$\mathrm{H}^1(S,T_S)_{0}\otimes \mathrm{H}^1(S,\Omega_S^{1}\otimes\oh_S(-1))\rightarrow \mathrm{H}^2(S,\oh_S(-1))$$
is non-degenerate with respect to the first factor, there exists an element $0\neq \beta\in \mathrm{H}^{1}(S,\Omega^{1}_{S}(-1)\vert_{S})$ such that $m_{1}(\alpha,\beta)\neq 0$. Because $res_{1}$ is surjective by Lemma~\ref{vanishingsurjective}, there exists an element $0\neq \beta'\in \mathrm{H}^{1}(Y,\Omega_{Y}(\log S)(-1))$ such that $res_1(\beta')=\beta$. By Theorem~\ref{commutativediagram}, 
    $$res_2(m_2(\alpha,\beta'))=-m_1(\alpha,res_1(\beta'))\neq 0.$$
Thus, $m_2(\alpha,\beta')\neq 0$ which further implies the pairing
    $$\mathrm{H}^{1}(X,T_{Y}(-\log S)\otimes \mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1))\rightarrow \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1))$$
 is non-degenerate with respect to the first factor.
\end{proof}

\subsection{A twisted Torelli for the branch $K3$ surfaces}\label{subsec_twistedtorelli}
	In this subsection, we prove the following proposition which can be viewed as a twisted version of the infinitesimal Torelli theorem for the branch $K3$ surface $S$ of a special Gushel-Mukai threefold $X$. 
\begin{prop}\label{twistedtorelliK3}
	The pairing $$\mathrm{H}^1(S,T_S)_{0}\otimes \mathrm{H}^1(S,\Omega_S^{1}(-1))\rightarrow \mathrm{H}^2(S,\oh_S(-1))$$
is non-degenerate with respect to the first factor.
\end{prop}

	Let us divide the proof of Proposition~\ref{twistedtorelliK3} into several lemmas. First we consider the conormal bundle exact sequence for $S\subset Y$ (note that $\mathcal{N}_{S\vert Y}\cong \mathcal{O}_S(2)$)
\begin{equation}\label{18}
    0\rightarrow \mathcal{O}_{S}(-2)\rightarrow \Omega^{1}_{Y}\vert_{S}\rightarrow \Omega^{1}_{S}\rightarrow 0.
\end{equation}
Using \cite[Theorem 2.1]{Flenner1986} and the above conormal exact sequence (and then tensor with $\mathcal{O}_{S}(1)$), we obtain an exact sequence
\begin{equation}\label{19}
    0\rightarrow \Omega^{1}_{S}(-1)\rightarrow \Omega^{2}_{Y}(1)\vert_{S}\rightarrow \Omega^{2}_{S}(1)\rightarrow 0.
 \end{equation}
Now fix a non-degenerate holomorphic $2$-form $\omega\in \mathrm{H}^{0}(S,\omega_{S})$ which defines an isomorphism $\xymatrix{\mathcal{O}_{S}\ar[r]_{\wedge \omega}^{\simeq}& \Omega^{2}_{S}}$.  Contraction of $\omega$ defines an isomorphism $T_{S}\cong \Omega^{1}_{S}$ which induces 
    $$\lrcorner\omega: \mathrm{H}^{1}(S,T_{S})\cong \mathrm{H}^{1}(S,\Omega^{1}_{S}).$$ 
Let us write the composition $\mathrm{H}^{1}(S,T_{S})_{0}\hookrightarrow \mathrm{H}^{1}(S,T_{S})\cong \mathrm{H}^{1}(S,\Omega^{1}_{S})\rightarrow \mathrm{H}^{2}(S,\oh_{S}(-2))$ as $I$:
    $$I: \mathrm{H}^{1}(S,T_{S})_{0}\hookrightarrow \mathrm{H}^{1}(S,T_{S})\stackrel{\lrcorner\omega}{\longrightarrow} \mathrm{H}^{1}(S,\Omega^{1}_{S})\rightarrow \mathrm{H}^{2}(S,\oh_{S}(-2)).$$
By \eqref{18}, we have a map $\mathrm{H}^{1}(S,\Omega^{1}_{S})\rightarrow \mathrm{H}^{2}(S,\oh_{S}(-2))$. From \eqref{19}, we get a map $\mathrm{H}^{0}(S,\oh_{S}(1))\rightarrow \mathrm{H}^{1}(S,\Omega^{1}_{S}(-1))$. Observe that the anticanonical $K3$ surface $S=Y\cap Q=\mathrm{Gr}(2,5)\cap \mathbb{P}^6\cap Q$ is a $2$-dimensional Gushel-Mukai variety. This allows us to adapt the techniques in the proof of \cite[Theorem 7.1]{debarre2008period} to $S$. Specifically, using the short exact sequences \eqref{18}, \eqref{19} and \cite[Lemma 2.10]{Flenner1986}, we obtain the following lemma.
\begin{lem}\label{commutativediagramlemma}
	The following diagram commutes up to a sign.
     $$\xymatrix{\mathrm{H}^{1}(S,T_{S})_{0}\ar[d]^{I}&\otimes &\mathrm{H}^{1}(S,\Omega^{1}_{S}(-1))\ar[r] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1))\\
\mathrm{H}^{2}(S,\mathcal{O}_{S}(-2))& \otimes&\mathrm{H}^{0}(S,\Omega^{2}_{S}(1))\ar[r] \ar[u] &\mathrm{H}^{2}(S,\Omega^{2}_{S}(-1))\ar@{=}[u]^{\wedge \omega}.\\}$$  
\end{lem}

	Thus, to show Proposition~\ref{twistedtorelliK3}, we only need to prove that the map $I$ is injective, and that the map in the bottom row of the diagram in Lemma~\ref{commutativediagramlemma} is non-degenerate with respect to the first factor. 

\begin{lem}\label{injectivitylemma}
	The map $I$ in Lemma~\ref{commutativediagramlemma} is injective.
\end{lem}
\begin{proof}
	From the exact sequence \eqref{normalbundle}, we get a long exact sequence
    $$0=\mathrm{H}^{0}(S,T_{S})\rightarrow \mathrm{H}^{0}(S,T_{Y}\vert_{S})\rightarrow \mathrm{H}^{0}(S,\oh_{S}(2))\stackrel{\operatorname{KS}}{\longrightarrow} \mathrm{H}^{1}(S,T_{S})\stackrel{J_1}{\longrightarrow} \mathrm{H}^{1}(S,T_{Y}\vert_{S})\rightarrow \mathrm{H}^{1}(S,\oh_{S}(2))=0.$$
%$$\xymatrix{\mathrm{H}^{0}(Y,T_{Y})=0\ar[r]&\mathrm{H}^{0}(Y,T_{X}\vert_{Y})\ar[r] &\mathrm{H}^{0}(Y,\oh_{Y}(2))\ar[r]^{\operatorname{KS}} &\mathrm{H}^{1}(Y,T_{Y})\ar[r]^{J_1} &\mathrm{H}^{1}(Y,T_{X}\vert_{Y})\ar[d]\\ &&&&\mathrm{H}^{1}(Y,\oh_{Y}(2))=0}$$
Using the exact sequence \eqref{18}, we have a long exact sequence
    $$0=\mathrm{H}^{1}(S,\oh_{S}(-2))\rightarrow \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})\stackrel{J_2}{\longrightarrow} \mathrm{H}^{1}(S,\Omega^{1}_{S})\rightarrow \mathrm{H}^{2}(S,\oh_{S}(-2))\rightarrow \mathrm{H}^{2}(S,\Omega^{1}_{Y}\vert_{S})\rightarrow \mathrm{H}^{2}(S,\Omega^{1}_{S})=0.$$
%$$\xymatrix{\mathrm{H}^{1}(S,\oh_{S}(-2))=0\ar[r]&\mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})\ar[r]^{J_2} &\mathrm{H}^{1}(S,\Omega^{1}_{S})\ar[r] &\mathrm{H}^{2}(S,\oh_{S}(-2))\ar[r]&\mathrm{H}^{2}(S,\Omega^{1}_{Y}\vert_{S})\ar[d] \\ &&&& \mathrm{H}^{2}(S,\Omega^{1}_{S})=0}$$
To proceed, we will need the following lemma.

\begin{lem}\label{polarizedclass}
	The restriction map $\mathrm{H}^{1}(Y,\Omega^{1}_{Y})\rightarrow \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$ is an isomorphism. As a consequence, $\operatorname{dim}\mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})=1$.  
\end{lem}
\begin{proof}
	Consider the short exact sequence
\begin{equation*}
    0\rightarrow \oh_{Y}(-S)\rightarrow \oh_{Y}\rightarrow \oh_{Y}\vert_{S}\rightarrow 0.
\end{equation*}
Tensoring with $\Omega^{1}_{Y}$, we get
\begin{equation*}
    0\rightarrow \Omega^{1}_{Y}(-S)\rightarrow \Omega^{1}_{Y}\rightarrow \Omega^{1}_{Y}\vert_{S}\rightarrow 0.  
\end{equation*}
The associated long exact sequence is
\begin{equation*}%\label{22}
    \ldots\rightarrow \mathrm{H}^{1}(Y,\Omega^{1}_{Y}(-S))\rightarrow \mathrm{H}^{1}(Y,\Omega^{1}_{Y})\rightarrow \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})\rightarrow \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(-S)) \rightarrow\ldots.
\end{equation*}
Note that $\omega_{Y}\cong \oh_{Y}(-S)\cong \oh_{Y}(-2)$. By Serre duality and the Kodaira-Akizuki–Nakano vanishing, we have 
    $$\mathrm{H}^{1}(Y,\Omega^{1}_{Y}(-S))\cong \mathrm{H}^{2}(Y,T_{Y})^{\vee}\cong \mathrm{H}^{2}(Y,\Omega^{2}_{Y}(2))^{\vee}=0.$$
Serre duality also implies that
    $$\mathrm{H}^{2}(Y,\Omega^{1}_{Y}(-S))\cong \mathrm{H}^{1}(Y,T_{Y})^{\vee}=0.$$
It follows that the restriction map $\mathrm{H}^{1}(Y,\Omega^{1}_{Y})\rightarrow \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$ is an isomorphism. In particular, $\operatorname{dim} \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})=\operatorname{dim}\mathrm{H}^{1}(Y,\Omega^{1}_{Y})=1$.
\end{proof}

    We continue with the proof of Lemma~\ref{injectivitylemma}. By functoriality of Serre duality, we have the following diagram which is commutative with respect to the Serre pairings:
\begin{equation}\label{23} 
    \xymatrix{0&\mathrm{H}^{1}(S,T_{Y}\vert_{S})\ar[l] &\mathrm{H}^{1}(S,T_{S})\ar[l]_{J_1} &\mathrm{H}^{0}(S,\oh_{S}(2))\ar[l]_{\operatorname{KS}} &\mathrm{H}^{0}(S,T_{Y}\vert_{S})\ar[l]&0\ar[l]\\
&\otimes &\otimes & \otimes&\otimes\\
0\ar[r]&\mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})\ar[r]^{J_2}\ar[d] &\mathrm{H}^{1}(S,\Omega^{1}_{S})\ar[r]\ar[d] &\mathrm{H}^{2}(S,\oh_{S}(-2))\ar[r]\ar[d]&\mathrm{H}^{2}(S,\Omega^{1}_{Y}\vert_{S})\ar[r]\ar[d]&0.\\
&\mathbb{C} &\mathbb{C} &\mathbb{C} &\mathbb{C}}
\end{equation}
Let $\omega\in \mathrm{H}^{0}(S,\omega_{S})$ be the fixed non-degenerate holomorphic $2$-form on $S$. According to Proposition~\ref{equalKS}, $\mathrm{H}^{1}(S,T_{S})_{0}=\operatorname{KS}(\mathrm{H}^{0}(S,\oh_{S}(2)))$. Now we show that the intersection of $\operatorname{KS}(\mathrm{H}^{0}(S,\oh_{S}(2)))\lrcorner\omega\subset \mathrm{H}^{1}(S,\Omega^{1}_{S})$ and $J_2(\mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S}))\subset \mathrm{H}^{1}(S,\Omega^{1}_{S})$ is trivial, which will imply that $I$ is injective into $\mathrm{H}^{2}(S,\oh_{S}(-2))$. Take a non-trivial $\tau$ in the image of $\operatorname{KS}$, then $J_{1}(\tau)=0$. Suppose there exists some non-zero $a\in \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$ such that $\tau\lrcorner\omega=J_{2}(a)$. Then, for any element $b\in \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$,
we have an equality of Serre pairings
    $$\langle J_{1}(\tau),b\rangle=\langle\tau, J_{2}(b) \rangle.$$
Since $\langle J_{1}(\tau),b\rangle=0$, it holds that
    $$\int_{S}J_2(a)\wedge J_{2}(b) =\int_{S}(\tau\lrcorner\omega)\wedge J_{2}(b)=-\langle\tau, J_{2}(b) \rangle=0.$$
Here the second equality holds since $(\tau\lrcorner \omega)\wedge J_{2}(b)=-(\tau\lrcorner J_{2}(b))\wedge \omega$ which can be verified locally. Namely, write $\tau=a_{1}\partial_{z_1}+b_{1}\partial_{z_2}$ as a $\Bar{\partial}$ closed form in $\mathcal{A}_{S}^{0,1}(T_{S})$, and write $J_{2}(b)= a_{2}dz_{1}+b_{2}dz_{2}$ as a $\Bar{\partial}$ closed form in $\mathcal{A}_{S}^{1,1}$. Without loss of generality, suppose $\omega=dz_1\wedge dz_2$. Then $(\tau\lrcorner \omega)\wedge J_{2}(b)=-(\tau\lrcorner J_{2}(b))\wedge \omega=-(a_{1}\wedge a_{2}+ b_{1}\wedge b_{2})dz_{1}\wedge dz_{2}$. However, by Lemma~\ref{polarizedclass}, $J_{2}(a)=k_{1}H_S$ and $J_{2}(b)=k_{2}H_S$ ($k_{1}, k_{2}\in \mathbb{C}$) where $H_S$ is the restriction of the polarization of $Y$ to $S$. Since $\int_{S}J_2(a)\wedge J_{2}(b)=0$ for any element $b\in \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$, we have $J_{2}(a)=0$. Therefore, $\tau=0$, which is a contradiction.
\end{proof}

\begin{rem}\label{rem_whyIinjective}
    We remark that Lemma~\ref{injectivitylemma} fails without restricting to the $19$-dimensional subspace $\mathrm{H}^1(S,T_S)_0$ of $ \mathrm{H}^1(S,T_S)$. Indeed, let us use the notation in the proof of Lemma~\ref{injectivitylemma} and let $\lrcorner\omega: \mathrm{H}^{1}(S,T_{S})\cong \mathrm{H}^{1}(S,\Omega^{1}_{S})$ be the contraction isomorphism. Then the inverse image of $J_{2}(\mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S}))$ under the contraction map $\lrcorner\omega$ is a subspace of $\mathrm{H}^1(S,T_S)$ of dimension $1$, and is contained in the kernel of the map $I$.   
\end{rem}

\begin{lem}\label{nondegeneratelemma}
	The pairing
    $$\mathrm{H}^{2}(S,\oh_{S}(-2))\otimes \mathrm{H}^{0}(S,\Omega^{2}_{S}(1))\rightarrow \mathrm{H}^{2}(S,\Omega^{2}_{S}(-1))$$
  is non-degenerate with respect to the first factor.  
 \end{lem}
\begin{proof}
Since $S$ is a $K3$ surface, $\Omega^{2}_{S}\cong \mathcal{O}_{S}$. By Serre duality, it suffices to prove the following multiplication map is surjective
    $$\mathrm{H}^{0}(S,\mathcal{O}_{S}(1))\otimes \mathrm{H}^{0}(S,\mathcal{O}_{S}(1))\rightarrow \mathrm{H}^{0}(S,\mathcal{O}_{S}(2)).$$
Recall that $Y=\mathrm{Gr}(2,4)\cap \mathbb{P}^6$ and $S\in\vert -K_{Y} \vert=\vert\mathcal{O}_Y(2)\vert$. Let $H$ be a general hyperplane in $\mathbb{P}^6$ and let $C=S\cap H\in \vert\mathcal{O}_{S}(1)\vert$. Then $C$ is a smooth curve of genus $6$ and $\mathcal{O}_{S}(C)\cong \mathcal{O}_{S}(1)$. By \cite[Proposition 2.12]{debarre2015gushel}, $C$ is non-hyperelliptic (indeed, by adjunction formula $\omega_{C}\cong \mathcal{O}_{C}(C)\otimes \omega_{S}\vert_{C}\cong \mathcal{O}_{C}(C)\cong \mathcal{O}_{C}(1)$ which induces an embedding of $C$). Now according to \cite[Observation 1.3]{GalPuraprajna00}, it suffices to prove that the restriction of the multiplication map to the curve $C$, namely
\begin{equation}\label{21}
    \mathrm{H}^{0}(C,\mathcal{O}_{C}(C))\otimes \mathrm{H}^{0}(C,\mathcal{O}_{C}(C))\rightarrow \mathrm{H}^{0}(C,\mathcal{O}_{C}(2C)),
\end{equation}
is surjective. As above, we have $\mathcal{O}_{C}(C)\cong \omega_{C}$. Since $C$ is non-hyperelliptic, Noether's theorem implies that the multiplication map \eqref{21} is surjective (in fact, this is the infinitesimal Torelli theorem for non-hyperelliptic curves). The proof is then completed.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{twistedtorelliK3}]
	Combining Lemma~\ref{commutativediagramlemma}, Lemma~\ref{injectivitylemma}, and Lemma~\ref{nondegeneratelemma}, we conclude the proposition (see also the proof of Lemma~\ref{twistedtorelliK3tologtorelli}).
\end{proof}

\begin{proof}[Proof of Theorem~\ref{logtorelli}]
	By Lemma~\ref{twistedtorelliK3tologtorelli} and Proposition~\ref{twistedtorelliK3}, the pairing
    $$ \mathrm{H}^{1}(Y,T_{Y}(-\log S)\otimes \mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1))\rightarrow \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1))$$
is non-degenerate with respect to the first factor. Thus, the map
    $$\mathrm{H}^{1}(Y,T_{Y}(-\log S))\rightarrow \mathrm{Hom}(\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1)), \mathrm{H}^{2}(Y,\Omega_{Y}^{1}(\log S)(-1)))$$
is injective.
\end{proof}

\subsection{Special Verra threefolds}\label{subsec_specialverra}
    In the remaining part of Section \ref{section_geo_torelli}, we apply the methods in the previous subsections to study the infinitesimal Torelli problem for special Verra threefolds. Since the arguments are quite similar, we will only give an outline in this subsection. Let $X$ be the double cover of a smooth $(1,1)$-divisor $Y\subset \mathbb{P}^2\times\mathbb{P}^2$ branched along a smooth $K3$ surface $S\in\vert-K_Y\vert$. Such a threefold $X$ is called a special Verra threefold. By the Lefschetz theorem, the inclusion map $Y\hookrightarrow \mathbb{P}^2\times\mathbb{P}^2$ induces an isomorphism of Picard groups $\Pic(X)\cong \Pic(\mathbb{P}^2\times\mathbb{P}^2)\cong \mathbb{Z}\times \mathbb{Z}$. Note that $\omega_Y\cong \mathcal{O}_Y(-2,-2)$. Moreover, the line bundle $\mathcal{L}$ associated with the double cover $X\rightarrow Y$ is $\mathcal{L}=\mathcal{O}_Y(1,1)$ (in particular, $\mathcal{L}^{2}=\omega_Y^{-1}$). 

    Let $d\mathcal{P}: \mathrm{H}^1(X,T_X)\to \mathrm{Hom}(\mathrm{H}^1(X,\Omega_X^2), \mathrm{H}^2(X,\Omega_X^1))$ be the infinitesimal period map for special Verra threefolds. By Proposition \ref{doublecovercohomology}, we obtain a decomposition of $d\mathcal{P}$ with respect to the covering involution associated with $X\to Y$. Since $\mathrm{H}^1(Y,\Omega_Y^2)=0$, the anti-variant part of $d\mathcal{P}$ is the zero map. From the proof of Lemma \ref{invariantsubspace3k}, we also deduce that the anti-invariant space $\mathrm{H}^1(Y,T_Y(-1,-1))$ of $\mathrm{H}^1(Y,T_Y)$ has dimension $1$. Thus, to determine the kernel of $d\mathcal{P}$, it suffices to study the injectivity of the invariant infinitesimal period map. 
\begin{prop}\label{thm_Appendix_sV}
    The invariant infinitesimal period map for special Verra threefolds
    $$\mathrm{H}^1(Y,T_Y(-\log S))\to \mathrm{Hom}(\mathrm{H}^1(Y,\Omega_Y^2(\log S)(-1,-1), \mathrm{H}^2(Y,\Omega_Y^1(\log S)(-1,-1)))$$
is injective. As a result, the kernel of the infinitesimal period map 
    $$d\mathcal{P}:\mathrm{H}^1(X,T_X)\to \mathrm{Hom}(\mathrm{H}^1(X,\Omega_X^2), \mathrm{H}^2(X,\Omega_X^1))$$ 
 has dimension $1$. 
\end{prop}    

    The rest of this subsection is devoted to prove Proposition~\ref{thm_Appendix_sV}. First, as in Proposition~\ref{commutativediagram} we reduce the injectivity statement to a twisted infinitesimal Torelli type result for the anticanonical $K3$ surface $S$. Specifically, by Lemma~\ref{commutativesheaves} and Proposition~\ref{commutativediagram} we have the following commutative diagram up to a sign:
    \begin{equation} \label{eqn:commutative_diagram_special_verra}
    \xymatrix{&&\mathrm{H}^{2}(Y,\Omega^{2}_{Y}(-1,-1)) & \\
   \mathrm{H}^{1}(S,T_{S}) & \otimes&\mathrm{H}^{1}(S,\Omega^{1}_{S}(-1,-1))\ar[r]^{m_1}\ar[u] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1,-1))\\
    \mathrm{H}^{1}(Y,T_{Y}(-\log S))\ar[u]&\otimes &\mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1,-1))\ar[r]^{m_2}\ar[u]^{res_1} &\mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1,-1))\ar[u]^{res_2}.\\}
    \end{equation}
Since \[\mathrm{H}^1(Y,T_Y\otimes \mathcal{O}_Y(-S))=\mathrm{H}^1(Y,T_Y\otimes \omega_Y)\cong \mathrm{H}^1(Y,\Omega_Y^2)=0,\] the leftmost vertical map of the diagram \eqref{eqn:commutative_diagram_special_verra} is injective (see also the short exact sequence \eqref{third}). Let us denote its image by $\mathrm{H}^{1}(S,T_{S})_{0}$.

    Now let us compute $\mathrm{H}^2(Y,\Omega_Y^2(-1,-1))$ and show that the map $res_1$ in the diagram \eqref{eqn:commutative_diagram_special_verra} is surjective. As in Lemma \ref{vanishingsurjective}, we first observe that \[\Omega_Y^2(-1,-1)\cong \Omega_Y^2\otimes \omega_Y^{-1}\otimes \mathcal{O}_Y(-3,-3)\cong T_Y(-3,-3).\]
Twisting the normal bundle sequence \eqref{normalbundle} for $Y\subset \mathbb{P}^2\times \mathbb{P}^2$ by $\mathcal{O}_Y(-3,-3)$, one obtains \[0\to T_Y(-3,-3)\to T_{\mathbb{P}^2\times\mathbb{P}^2}(-3,-3)\vert_Y\to \mathcal{O}_Y(-2,-2)\to 0.\]
By Kodaira vanishing theorem, $\mathrm{H}^1(Y,\mathcal{O}_Y(-2,-2))=0$. Besides, we have the following lemma.
\begin{lem}
	The cohomology group $\mathrm{H}^2(Y,T_{\mathbb{P}^2\times\mathbb{P}^2}(-3,-3)\vert_Y)=0$. As a consequence, $\mathrm{H}^2(Y,\Omega_Y^2(-1,-1))=0$, and hence the map $res_1$ in the diagram \eqref{eqn:commutative_diagram_special_verra} is surjective.
\end{lem}
\begin{proof}
	Using Serre duality, it suffices to show that $\mathrm{H}^1(Y,\Omega_{\mathbb{P}^1\times\mathbb{P}^2}^1(1,1)|_Y)=0$. By the following short exact sequence \[0\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1(1,1)\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1(1,1)\vert_Y\to 0,\] one only needs to verify the following:
    \begin{enumerate}
        \item[(a)] $\mathrm{H}^1(\mathbb{P}^2\times\mathbb{P}^2,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1(1,1))=0$;
        \item[(b)] $\mathrm{H}^2(\mathbb{P}^2\times\mathbb{P}^2,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1)=0$.
    \end{enumerate}
Let us take (a) as an example. Note that $\Omega_{\mathbb{P}^1\times\mathbb{P}^2}^1(1,1)\cong (\Omega_{\mathbb{P}^2}^1(1)\boxtimes \mathcal{O}_{\mathbb{P}^2}(1))\oplus (\mathcal{O}_{\mathbb{P}^2}(1)\boxtimes \Omega_{\mathbb{P}^2}^1(1)))$. Applying the Kunneth's formula for sheaf cohomology, this vanishing condition can then be verified readily. 
\end{proof}

    Next, we show that the multiplication map $m_1$ in the commutative diagram \eqref{eqn:commutative_diagram_special_verra} is non-degenerate with respect to the first factor (after restricting to the subspace $\mathrm{H}^{1}(S,T_{S})_{0}$ which is the image of  $\mathrm{H}^{1}(Y,T_{Y}(-\log S))\hookrightarrow \mathrm{H}^1(S,T_S)$). Consider the conormal sequence for $S\subset Y$ (note that $\mathcal{N}_{S\vert Y}\cong \mathcal{O}_S(2,2)$) and apply \cite[Theorem 2.1]{Flenner1986}, we obtain the following exact sequences:
    $$0\rightarrow \mathcal{O}_{S}(-2,-2)\rightarrow \Omega^{1}_{Y}\vert_{S}\rightarrow \Omega^{1}_{S}\rightarrow 0.$$
    $$0\rightarrow \Omega^{1}_{S}(-1,-1)\rightarrow \Omega^{2}_{Y}(1,1)\vert_{S}\rightarrow \Omega^{2}_{S}(1,1)\rightarrow 0.$$
By \cite[Lemma 2.10]{Flenner1986} (see also Lemma \ref{commutativediagramlemma}), we get a commutative diagram up to a sign.
     $$\xymatrix{\mathrm{H}^{1}(S,\Omega^{1}_{S})\ar[d]&\otimes &\mathrm{H}^{1}(S,\Omega^{1}_{S}(-1,-1))\ar[r] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1,-1))\ar@{=}[d]\\
 \mathrm{H}^{2}(S,\mathcal{O}_{S}(-2,-2))& \otimes&\mathrm{H}^{0}(S,\mathcal{O}_{S}(1,1))\ar[r] \ar[u] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1,-1)).\\}$$ 
Let us fix a non-degenerate holomorphic $2$-form $\omega\in \mathrm{H}^{0}(S,\omega_{S})$ and identify $\mathrm{H}^{1}(S,T_{S})$ with $\mathrm{H}^{1}(S,\Omega^{1}_{S})$ via contraction of $\omega$. After restricting to the subspace $\mathrm{H}^{1}(S,T_{S})_{0}\subset \mathrm{H}^{1}(S,T_{S})$, the above diagram gives rise to the following:
$$\xymatrix{\mathrm{H}^{1}(S,T_{S})_{0}\ar[d]^{I}&\otimes &\mathrm{H}^{1}(S,\Omega^{1}_{S}(-1,-1))\ar[r] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1,-1))\ar@{=}[d]\\
 \mathrm{H}^{2}(S,\mathcal{O}_{S}(-2,-2))& \otimes&\mathrm{H}^{0}(S,\mathcal{O}_{S}(1,1))\ar[r] \ar[u] &\mathrm{H}^{2}(S,\mathcal{O}_{S}(-1,-1)).\\}$$

    Now we verify that $I:\mathrm{H}^1(S,T_S)_0\hookrightarrow \mathrm{H}^1(S,T_S)\stackrel{\lrcorner \omega}{\to} \mathrm{H}^1(S,\Omega_S^1)\to \mathrm{H}^2(S,\mathcal{O}_S(-2,-2))$ is injective. Since in addition the bottom row of the above diagram is non-degenerate with respect to the first factor (see the proof of Lemma \ref{nondegeneratelemma}), this implies that the multiplication map $m_1$ in the commutative diagram \eqref{eqn:commutative_diagram_special_verra} is non-degenerate with respect to $\mathrm{H}^1(S,T_S)_0$. By Proposition \ref{equalKS}, the composition $\mathrm{H}^0(S,\mathcal{N}_{S\vert Y})\twoheadrightarrow \mathrm{H}^1(Y,T_Y(-\log S))\hookrightarrow \mathrm{H}^1(S,T_S)$ is the Kodaira-Spencer map $\mathrm{KS}$ (which is the connecting homomorphism induced by the short exact sequence \eqref{normalbundle}). Repeating the arguments in Lemma \ref{injectivitylemma} and Lemma \ref{polarizedclass}, it is not difficult to show that $I$ is injective. In more detail, let us use the notation in the proof of Lemma \ref{injectivitylemma} and in the diagram \eqref{23}. Take a non-trivial $\tau$ in the image of $\operatorname{KS}$; note that $J_{1}(\tau)=0$. Since the kernel of $\mathrm{H}^1(S,\Omega_S^1)\to \mathrm{H}^2(S,\mathcal{O}_S(-2,-2))$ is $J_2(\mathrm{H}^1(S,\Omega_Y^1\vert_S))$, it is enough to prove that $\tau\lrcorner\omega$ is not in the image of $J_2$. Suppose that there exists a non-zero $a\in \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$ such that $\tau\lrcorner \omega=J_{2}(a)$. As shown in the proof of Lemma \ref{injectivitylemma}, one has $\int_{S}J_2(a)\wedge J_2(b)=0$ for any $b\in \mathrm{H}^{1}(S,\Omega^{1}_{Y}\vert_{S})$. But this is absurd. On one side, taking $J_2(b)$ to be the polarization class, we get $\int_{S}J_2(a)\wedge J_2(a)\neq0$ by Hodge index theorem; on the other side, for $b=a$ we have $\int_{S}J_2(a)\wedge J_2(a)=0$. (Note that the composition $\mathrm{H}^1(S,T_S)\stackrel{\lrcorner \omega}{\to} \mathrm{H}^1(S,\Omega_S^1)\to \mathrm{H}^2(S,\mathcal{O}_S(-2,-2))$ is not injective. In fact, the kernel has dimension $2$ since $\mathrm{H}^1(S,\Omega_Y^1\vert_S)\cong \mathrm{H}^1(Y,\Omega_Y^1)\cong \mathbb{C}^2$ as in Lemma \ref{polarizedclass}; see also Remark~\ref{rem_whyIinjective}.)   

    Lastly, the proof of Lemma~\ref{twistedtorelliK3tologtorelli} shows that the pairing
    $$\mathrm{H}^{1}(Y,T_{Y}(-\log S)\otimes \mathrm{H}^{1}(Y,\Omega^{2}_{Y}(\log S)(-1,-1))\rightarrow \mathrm{H}^{2}(Y,\Omega^{1}_{Y}(\log S)(-1,-1))$$
is non-degenerate with respect to the first factor. The proof of Proposition \ref{thm_Appendix_sV} is then completed.



\section{Categorical aspects of the Infinitesimal Torelli problems}\label{section_cat_torelli}
	In this section, we study infinitesimal Torelli problems for prime Fano threefolds of genus $g\geq 6$ using categorical methods. Our first goal is to prove Theorem~\ref{main_theorem_categorical} which (together with Proposition~\ref{lemma_injectivity_gamma}) describes the kernels of the infnitesimal period maps for these Fano threefolds. Note that Gushel-Mukai threefolds are prime threefolds of genus $6$. As a consequence, we obtain a categorical argument for Theorem~\ref{main_theorem_1}. In the remaining part, we focus on prime threefolds of genus $6$ (i.e. Gushel-Mukai threefolds) and genus $8$. Specifically, we give a geometric description for the kernels of the infnitesimal period maps via certain Bridgeland moduli spaces (see Theorem~\ref{main_theorem_geometric_interpretation}).

    Let $X$ be a prime Fano threefold of genus $g$. Recall that $2\leq g\leq12$ and $g\neq 11$. It has been shown in \cite[Theorem 1.4]{jacovskis2022infinitesimal} that infinitesimal Torelli theorems hold for prime Fano threefolds of genus $g=2,4,5$ and for non-hyperelliptic prime Fano threefolds of genus $3$. In what follows, we focus on the case when $X$ has genus $g\geq 6$. Recall that $X$ admits a semi-orthogonal decomposition
    $$D^b(X)=\langle\Ku(X),\oh_X,\mathcal{U}_X^{\vee}\rangle,$$
where $\Ku(X)$ is the Kuznetsov component of $X$, and $\mathcal{U}_X$ is the pullback of tautological subbundle on the corresponding Grassmannian. By \cite[Theorem 1.1]{jacovskis2022infinitesimal}, there exists a commutative diagram
\begin{equation}\label{diagram_cattorelli}
    \xymatrix@C8pc@R2pc{\HH^{2}(\Ku(X))\ar[r]^{\Gamma_X}&\mathrm{Hom}(\mathrm{H}^{1}(X,\Omega_{X}^{2}),\mathrm{H}^{2}(X,\Omega_{X}^{1})).\\
\mathrm{H}^{1}(X,T_{X})\ar[ru]^{\mathrm{d} \mathcal{P}}\ar[u]^{\eta}&}
\end{equation}
As explained in op. cit., the map $\eta$ can be thought of as a categorical analogue of the infinitesimal period map. Moreover, we shall prove that the morphism $\Gamma_{X}$ is injective, and hence this commutative diagram allows us to reduce the classical infinitesimal Torelli problem (i.e. $d\mathcal{P}$ is injective) to the categorical one (that is, $\eta$ is injective).

    More precisely, by the HKR isomorphism we have $\mathrm{HH}_{-1}(\Ku(X))\cong\mathrm{H}^{1}(X, \Omega_{X}^{2})$ and $\mathrm{HH}_1(\Ku(X))\cong\mathrm{H}^{2}(X, \Omega_{X}^{1})$. Now consider the map 
    $$\gamma_X: \mathrm{HH}^2(\Ku(X))\rightarrow\mathrm{Hom}(\mathrm{HH}_{-1}(\Ku(X)),\mathrm{HH}_1(\Ku(X)))$$
defined in \cite[P.11]{jacovskis2022infinitesimal} via the action of Hochschild cohomology. We will show that $\gamma_X$ is injective which implies the horizontal arrow $\Gamma_X$ in the diagram \eqref{diagram_cattorelli} is also injective. Let us also mention that for Gushel-Mukai threefolds the key ingredient of the proof is the ``categorical duality" between ordinary ones and special ones.

\begin{prop}\label{lemma_injectivity_gamma}
	Let $X$ be a prime Fano threefold of genus $g\geq 6$, then the morphism 
$$\gamma_X: \mathrm{HH}^2(\Ku(X))\rightarrow\mathrm{Hom}(\mathrm{HH}_{-1}(\Ku(X)),\mathrm{HH}_1(\Ku(X)))$$
is injective. 
\end{prop}
\begin{proof} \noindent
\begin{itemize} 
\item Let us first consider the case of Gushel-Mukai threefolds. For ordinary Gushel-Mukai threefolds, the claim follows from \cite[Theorem 4.6]{jacovskis2022infinitesimal}. Now let $X$ be a special Gushel-Mukai threefold. By \cite[Theorem 1.6]{kuznetsov2019categorical} there exists an ordinary Gushel-Mukai threefold $X'$ such that $\Ku(X')\simeq\Ku(X)$. Moreover, the equivalence is of Fourier-Mukai type (cf.~\cite[Theorem 1.3]{li2022derived}). From \cite[Theorem 4.8]{jacovskis2021categorical}, we know that $\gamma_X$ is injective if and only if $\gamma_{X'}$ is injective. Therefore $\gamma_X$ is injective since $\gamma_{X'}$ is, by \cite[Theorem 4.6]{jacovskis2022infinitesimal}. 
\item Let $X$ be a prime Fano threefold of genus $7\leq g\leq 10$, then the map $\gamma_X$ is injective by \cite[Theorem 4.10]{jacovskis2022infinitesimal}. (When $X$ is a genus $8$ prime Fano threefold, one can also prove this in the following way. By \cite[Theorem 3.17]{MR2101293}, there exists a cubic threefold $Y$ such that $\Ku(Y)\simeq\Ku(X)$. Then the injectivity of $\gamma_X$ is equivalent to the injectivity of $\gamma_Y:\mathrm{HH}^2(\Ku(Y))\rightarrow\mathrm{Hom}(\mathrm{HH}_{-1}(\Ku(Y),\mathrm{HH}_1(\Ku(Y)))$. Since $\gamma_Y$ is injective by \cite[Theorem 4.4(2)]{jacovskis2022infinitesimal}, so is $\gamma_X$.)
\item When the prime Fano threefold $X$ has genus $12$, the Hochschild cohomology $\mathrm{HH}^2(\Ku(X))=0$. Since $\mathrm{H}^{1}(X,\Omega_{X}^{2})=\mathrm{H}^{2}(X,\Omega_{X}^{1})=0$, we have $\mathrm{HH}_{1}(\Ku(X))=\mathrm{HH}_{-1}(\Ku(X))=0$. Then $\gamma_X$ is trivially injective. 
\end{itemize}
\end{proof}

    By Proposition~\ref{lemma_injectivity_gamma}, the map $\Gamma_X$ in the commutative diagram \eqref{diagram_cattorelli} is injective. Thus $\mathrm{Ker}d\mathcal{P}=\mathrm{Ker}\eta$. Now we are ready to state and prove the following theorem (which is also Theorem~\ref{main_theorem_categorical}) where we use categorical methods to determine the kernel $\mathrm{Ker}\eta$ of the categorical infinitesimal period map $\eta$.    
\begin{thm}\label{thm_inf_torellI_Categorical}
    Let $X$ be a prime Fano threefold of genus $g\geq 6$. Then 
\begin{enumerate}
\item $\mathrm{Ker}\eta\cong\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$, where $\mathcal{U}_X$ and $\mathcal{Q}_X$ are tautological subbundle and quotient bundle pulling back from the corresponding Grassmannian, when $g=6$ and $g=8$;
\item there exists a short exact sequence 
    $$0\rightarrow\mathrm{Ker}\eta\rightarrow\mathrm{H}^1(X,T_X)\rightarrow\mathrm{HH}^2(\Ku(X))\rightarrow 0,$$ 
and thus $\mathrm{Ker}\eta\cong \mathbb{C}^{\mathrm{h}^1(X,T_X)-\mathrm{hh}^2(\Ku(X))}$, when $g=7,9,10;$
\item $\mathrm{Ker}\eta\cong\mathrm{H}^1(X,T_X)$, when $g=12$. 
\end{enumerate}
\end{thm}

\begin{proof}
	For (1), let $X$ be a Gushel-Mukai threefold or a prime Fano threefold of genus $8$. By \cite[Theorem 3.3]{kuznetsov2015height}, we have a long exact sequence $$\ldots\rightarrow\mathrm{HH}^1(\Ku(X))\rightarrow\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)\rightarrow\mathrm{HH}^2(X)\rightarrow\mathrm{HH}^2(\Ku(X))\rightarrow\ldots$$
where $\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)$ is the normal Hochschild cohomology of $\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle$ in $D^b(X)$ defined in \cite[Definition 3.2]{kuznetsov2015height}. 
Note that in both cases $\mathrm{HH}^2(X)\cong(\mathrm{H}^2(X,\oh_{X})\bigoplus\mathrm{H}^1(X,T_{X})\bigoplus\mathrm{H}^0(X,\bigwedge^2T_{X}))\cong \mathrm{H}^1(X,T_{X})$ (cf.~\cite{belmans2023polyvector}). Moreover, suppose $X$ is a Gushel-Mukai threefold, then by \cite[Proposition 2.12]{kuznetsov2018derived} $\mathrm{HH}^1(\Ku(X))=0$. If $X$ is a genus $8$ prime Fano threefold, then it also holds that $\mathrm{HH}^1(\Ku(X))=0$, according to \cite[Theorem 8.9]{kuznetsov2009derived}. Now the long exact sequence above becomes
    $$ 0\rightarrow\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)\xrightarrow{i}\mathrm{H}^1(X,T_{X})\xrightarrow{\eta}\mathrm{HH}^2(\Ku(X))\rightarrow\ldots.$$
Thus $\mathrm{Ker}\eta=\mathrm{Im}(i)\cong\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)$. 

    Next we compute the normal Hochschild homology $\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)$ via the normal Hochschild spectral sequence introduced in \cite[Proposition 3.7]{kuznetsov2015height}. Recall that the $E_1$ term of the normal Hochschild spectral sequence for $\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)$ is (where $H=-K_X$ is the polarization)
    $$E_1^{-p,q}=\bigoplus^{k_0+\ldots k_p=q}_{1\leq a_0<\ldots<a_p\leq 2}\mathrm{Hom}^{k_0}(E_{a_0},E_{a_1})\otimes\ldots\otimes\mathrm{Hom}^{k_{p-1}}(E_{a_{p-1}},E_{a_p})\otimes\mathrm{Hom}^{k_p-3}(E_{a_p},E_{a_0}\otimes\oh_X(H)).$$
Thus $$E_1^{0,3}=\mathrm{Hom}(\oh_X,\oh_X(H))\oplus\mathrm{Hom}(\mathcal{U}^{\vee}_X,\mathcal{U}^{\vee}_X(H))\cong\mathrm{Hom}(\oh_X,\oh_X(H))\oplus\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X\otimes\mathcal{U}^{\vee}_X),$$ and 
    $$E^{-1,3}_1=\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)\otimes\mathrm{Hom}(\mathcal{U}^{\vee}_X,\oh_X(H))=\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)\otimes\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X).$$
Let us note that $E^{-2,3}_1=0$. Thus the differential $d_1:E^{-1,3}_1\rightarrow E^{0,3}_1$ is given by the sum of two maps
    $$\eta_1:\mathrm{Hom}(\oh_X,\mathcal{U}_X^{\vee})\otimes\mathrm{Hom}(\mathcal{U}_X^{\vee},\oh_X(H))\rightarrow\mathrm{Hom}(\oh_X,\oh_X(H)),$$
and 
    $$\eta_2:\mathrm{Hom}(\mathcal{U}_X^{\vee},\oh_X(H))\otimes\mathrm{Hom}(\oh_X(H),\mathcal{U}_X^{\vee}(H))\rightarrow\mathrm{Hom}(\oh_X,\mathcal{U}_X^{\vee}\otimes\mathcal{U}_X^{\vee}).$$
Furthermore, $\eta_1$ factors through $\eta_2$, thus $\eta_1(\mathrm{Ker}\eta_2)=0$ and $\mathrm{Ker}\eta_2\subset\mathrm{Ker}\eta_1$; it also follows that $\mathrm{Ker}d_1\cong\mathrm{Ker}\eta_1\cap\mathrm{Ker}\eta_2\cong\mathrm{Ker}\eta_2$. Indeed, let $s_1\in\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)$ and $s_2\in\mathrm{Hom}(\mathcal{U}_X^{\vee},\oh_X(H))\stackrel{\alpha}{\cong}\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)$, where $\alpha$ is the natural isomorphism. Then we have a sequence of morphisms:
    $$\oh_X\xrightarrow{s_1}\mathcal{U}^{\vee}_X\otimes\oh_X\xrightarrow{\alpha(s_2)}\mathcal{U}^{\vee}_X\otimes\mathcal{U}^{\vee}_X\cong\mathcal{U}^{\vee}_X\otimes\mathcal{U}_X\otimes\oh_X(H)\rightarrow\oh_X(H).$$
It is then not difficult to see that $\eta_1:s_1\otimes s_2\mapsto s_2\circ s_1$ factors through the multiplication map $\eta_2$ of sections of $\mathcal{U}^{\vee}_X$. To compute $\mathrm{Ker}\eta_2$, we consider the tautological exact sequence
    $$0\rightarrow\mathcal{Q}^{\vee}_X\rightarrow\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)\otimes\oh_X\rightarrow\mathcal{U}^{\vee}_X\rightarrow 0.$$
Applying $\mathrm{Hom}(\mathcal{U}_X,-)$ to it, we get a long exact sequence
    $$0\rightarrow \mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)\rightarrow\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)\otimes\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X)\xrightarrow{d}\mathrm{Hom}(\oh_X,\mathcal{U}^{\vee}_X\otimes\mathcal{U}^{\vee}_X)\rightarrow \mathrm{Ext}^1(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)\rightarrow 0,$$
where $d$ is the multiplication map $\eta_2$. Then $\mathrm{Ker}\eta_2\cong \mathrm{Ker}d\cong\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$.

    Note that $p$ can only be $0$ or $1$, and $q\geq 3$ (because $q=k_0+\ldots+k_p$ with $k_0\geq 0$ and $k_p\geq 3$). Suppose that $q-p=2$, then $p=1$ and $q=3$. It is also easy to see this normal Hochschild spectral sequence degenerates at the $E_2$-page. In other words, the term $E^{-1,3}_2$ survives the spectral sequence and we have $\mathrm{NHH}^2(\langle\oh_{X},\mathcal{U}^{\vee}_{X}\rangle,X)\cong E^{-1,3}_2\cong\mathrm{Ker}d\cong\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$, thus we have proved the desired results.	 

    For (2), let $X$ be a prime Fano threefold of genus $7$. To compute $\mathrm{Ker}\eta$, we use the long exact sequence in \cite[Theorem 8.8(2)]{kuznetsov2009hochschild}
    $$\ldots\rightarrow\mathrm{HH}^1(\Ku(X))\rightarrow\mathrm{H}^0(X,\mathcal{N}_{X\vert\mathrm{Gr}}^{\vee}\otimes\omega^{-1}_X)\rightarrow\mathrm{H}^1(X,T_X)\xrightarrow{\eta}\mathrm{HH}^2(\Ku(X))\rightarrow\mathrm{H}^1(X,\mathcal{N}_{X\vert\mathrm{Gr}}^{\vee}\otimes\omega^{-1}_X)\rightarrow\ldots$$
where $\mathcal{N}_{X\vert\mathrm{Gr}}$ is the normal bundle of $X$ in Grassmannian $\mathrm{Gr}(2,7)$. Note that $\mathcal{N}_{X\vert\mathrm{Gr}}\cong\mathcal{Q}^{\vee}(1)\oplus\oh_X(1)^{\oplus 2}$, thus $\mathrm{H}^1(X,\mathcal{N}_{X\vert\mathrm{Gr}}^{\vee}\otimes\omega^{-1}_X)=0$. It follows that $\eta$ is surjective and the above exact sequence induces a short exact sequence 
$$0\rightarrow\mathrm{Ker}\eta\rightarrow\mathrm{H}^1(X,T_X)\xrightarrow{\eta}\mathrm{HH}^2(\Ku(X))\rightarrow 0,$$
which clearly implies that $\mathrm{Ker}\eta\cong\mathbb{C}^{\mathrm{h}^1(X,T_X)-\mathrm{hh}^2(\Ku(X))}$. The proof is entirely the same for genus $9$ and $10$ prime Fano threefolds.

    For (3), the case of genus $12$ prime Fano threefolds is trivial: since $\mathrm{HH}^2(\Ku(X))=0$, $\mathrm{Ker}\eta\cong\mathrm{H}^1(X,T_X)$. This completes the proof of the theorem.
\end{proof}

    Using Proposition~\ref{lemma_injectivity_gamma} and Theorem~\ref{thm_inf_torellI_Categorical}, we compute the dimensions of the kernels of the infinitesimal period maps for prime Fano threefolds of genus $g\geq 6$.    
\begin{cor}\label{cor_ker_dP}
	Let $X$ be a prime Fano threefold of genus $g\geq 6$. Denote the infinitesimal period map for $X$ by $d\mathcal{P}$. Then the kernel of $d\mathcal{P}$ are computed as follows.
\begin{itemize}
\item{$g=6$:} If $X$ is an ordinary Gushel-Mukai threefold, then $\mathrm{Ker}d\mathcal{P}\cong \mathbb{C}^2$; if $X$ is a special Gushel-Mukai threefold, then $\mathrm{Ker}d\mathcal{P}\cong \mathbb{C}^3$.
\item{$g=7$:} $\mathrm{Ker}d\mathcal{P}=0$ and thus $d\mathcal{P}$ is injective. 

%for a genus $7$ prime Fano threefold. 
\item{$g=8$:} $\mathrm{Ker}d\mathcal{P}\cong \mathbb{C}^5$. 
%for a genus $8$ prime Fano threefold $X$.
\item{$g=9$:} $\mathrm{Ker}d\mathcal{P}\cong \mathbb{C}^6$. 
%if $X$ is a genus $9$ prime Fano threefold
\item{$g=10$:} $\mathrm{Ker}d\mathcal{P}\cong \mathbb{C}^7$. 
%if $X$ is a genus $10$ prime Fano threefold. 
\item{$g=12$:} $\mathrm{Ker}d\mathcal{P}\cong\mathbb{C}^6$. 

%for a genus $12$ prime Fano threefold.
\end{itemize}
\end{cor}
\begin{proof}
    For a prime Fano threefold of genus $6$ or $8$, the dimension of $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ has been computed in \cite[Lemma 5.1]{jacovskis2021categorical} or \cite[Lemma A.8]{jacovskis2022brill}. One can then compute the dimension of $\mathrm{Ker}d\mathcal{P}$ using Proposition~\ref{lemma_injectivity_gamma}. If the genus $g=7,9,10$, then the Kuznetsov component $\Ku(X)\simeq D^b(C)$ for a smooth curve $C$, see \cite{kuznetsov2006hyperplane}. As a result, $\mathrm{HH}^2(\Ku(X))\cong\mathrm{H}^1(C,T_C)\cong\mathbb{C}^{3g(C)-3}$. By Proposition~\ref{lemma_injectivity_gamma} and Theorem~\ref{thm_inf_torellI_Categorical}, $\dim\mathrm{Ker}d\mathcal{P}=\dim \mathrm{Ker}\eta=\mathrm{h}^1(X,T_X)-3g(C)+3$. For a genus $7$ prime Fano threefold, $\mathrm{h}^1(X,T_X)=18$ and $g(C)=7$, then we get $\mathrm{Ker}d\mathcal{P}=0$ and $d\mathcal{P}$ is injective. Similarly, for a genus $9$ prime Fano threefold, $\mathrm{h}^1(X,T_X)=12$ and $g(C)=3$, then $\mathrm{Ker}\eta\cong\mathbb{C}^6$. If $X$ has genus $10$, then $\mathrm{h}^1(X,T_X)=10$ and $g(C)=2$, and hence $\mathrm{Ker}\eta\cong\mathbb{C}^7$. The claim on genus $12$ prime Fano threefolds holds since $\mathrm{H}^1(X,T_X)\cong\mathbb{C}^6$.   
\end{proof}

\begin{rem}\label{lemma_kernel_normal_hh_ordinary}
	For an ordinary Gushel-Mukai threefold $X'$, the kernel of $d\mathcal{P}$ has been described in \cite[Theorem 7.1]{debarre2008period}. Indeed, the proof of the injectivity of $\gamma_{X'}$ (see Proposition~\ref{lemma_injectivity_gamma}) in  \cite[Theorem 4.6]{jacovskis2022infinitesimal} relies on this result (i.e. $\mathrm{Ker}d\mathcal{P}$ has dimension $2$ for $X'$). For a special Gushel-Mukai threefold, Corollary~\ref{cor_ker_dP} provides an alternative proof of Theorem~\ref{main_theorem_1}. 
\end{rem}

    Next, we provide a geometric interpretation of $\mathrm{Ker}d\mathcal{P}=\mathrm{Ker}\eta$ for a prime Fano threefold of genus $6$ or $8$. In this direction, let $X$ be a genus $6$ prime Fano threefold (i.e.~a Gushel-Mukai threefold). Denote the Hilbert scheme of conics on $X$ by $\mathcal{C}(X)$. Let $\sigma$ be a Serre invariant stability condition on $\Ku(X)$. By \cite[Theorem 7.12]{jacovskis2021categorical}, the projection functor induces a birational morphism $\mathcal{C}(X)\rightarrow\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ from $\mathcal{C}(X)$ to the Bridgeland moduli space $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ where $I_C$ denotes the ideal sheaf of a conic $C$. The exceptional locus of this birational morphism is either a line or a $\mathbb{P}^2$ depending on whether $X$ is ordinary or special. Our observation is that, in either case, the exceptional locus can be identified with $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ which by Theorem~\ref{thm_inf_torellI_Categorical} is also isomorphic to the projectivization $\mathbb{P}\mathrm{Ker}d\mathcal{P}$ of the kernel of the infinitesimal period map. The case for a prime Fano threefold of genus $8$ is quite similar.    
\begin{thm}\label{main_theorem_geometric_interpretation_text}
    Let $X$ be a genus $6$ or $8$ prime Fano threefold, then $\mathbb{P}\mathrm{Ker}d\mathcal{P}\cong\mathbb{P}\mathrm{Ker}\eta\cong \mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ can be identified with the following:
\begin{enumerate}
\item the exceptional locus of the birational morphism $\mathcal{C}(X)\rightarrow\mathcal{M}_{\sigma}(\Ku(X),[I_C])$, where $\mathcal{C}(X)$ is the Hilbert scheme of conics on $X$ and $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ is the Bridgeland moduli space of $\sigma$-stable objects with character the same as the ideal sheaf $I_C$ of a conic $C$ in the Kuznetsov component $\Ku(X)$, if $g=6$;
\item the exceptional divisor of the birational morphism $\mathcal{M}_X(2,0,4)\rightarrow\mathcal{M}_{\sigma}(\Ku(X),2[I_C])$, where $\mathcal{M}_X(2,0,4)$ is the moduli space of stable sheaves of rank $2$ with Chern classes $c_1=0, c_2=4, c_3=0$ and $\mathcal{M}_{\sigma}(\Ku(X),2[I_C])$ denotes the Bridgeland moduli space of stable objects of class being twice of the ideal sheaf of a conic, if $g=8$.
\end{enumerate}
\end{thm}

    To prove Theorem~\ref{main_theorem_geometric_interpretation_text} for a genus $8$ prime Fano threefold, we will need the following lemmas and propositions. For basic properties of stability conditions on Kuznetsov components of Fano threefolds and Bridgeland moduli spaces, we refer the reader to \cite[Section 3]{liu2021note}.

\begin{lem}\label{lemma_numerical_constraint}
    Let $X$ be a genus $8$ prime Fano threefold, and let $E\in \mathrm{Coh}^{-\frac{1}{2}}(X)$ be a $\sigma_{\alpha, -\frac{1}{2}}$-semistable object for some $\alpha>0$, with $\mathrm{ch}(E)=(1,0,-2L,kP)$. Then $k\leq 0$.
\end{lem}
\begin{proof}
    The argument is the same as the proof of \cite[Lemma 6.3]{liu2021note}.
\end{proof}

\begin{lem}\label{204-in-ku}
    Let $X$ be a genus $8$ prime Fano threefold, and let $E\in M_X(2,0,4)$, then $h^i(E)=0$ for all $i$, and $E\notin\Ku(X)$ if and only if there is a short exact sequence
\[0\to \mathcal{U}_X\to \mathcal{Q}_X^{\vee}\to E\to 0.\]		
\end{lem}
\begin{proof}
	By \cite[Lemma 4.3]{BCFacm} we know $\mathrm{h}^2(E)=0$. From the stability and Serre duality, we have   $\mathrm{h}^3(E)=\mathrm{ext}^3(\mathcal{O}_X, E)=\mathrm{hom}(E, \mathcal{O}_X(-1))=0$ and $\mathrm{h}^0(E)=\mathrm{hom}(\mathcal{O}_X, E)=0$. Since $\chi(E)=0$, we know $\mathrm{h}^1(E)=0$. Thus $\mathrm{h}^i(E)=0$ for every $i$.

	First we show that if there exists a sheaf $E\in M_X(2,0,4)$ such that $E\notin\Ku(X)$, then we have the desired resolution of $E$. By stability and Serre duality, we have $\mathrm{hom}(\mathcal{U}^{\vee}_X, E)=\mathrm{ext}^3(\mathcal{U}^{\vee}_X, E)=0$. Since $\chi(\mathcal{U}^{\vee}_X, E)=0$, we have $\mathrm{ext}^1(\mathcal{U}^{\vee}_X, E)=\mathrm{ext}^2(\mathcal{U}^{\vee}_X, E)$. Thus if $E\notin\Ku(X)$, we have $\mathrm{ext}^1(\mathcal{U}^{\vee}_X, E)=\mathrm{ext}^2(\mathcal{U}^{\vee}_X, E)\neq 0$. If we apply $\mathrm{Hom}(-, E)$ to the exact sequence $0\to \mathcal{Q}^{\vee}_X\to \mathcal{O}_X^{\oplus 6}\to \mathcal{U}^{\vee}_X\to 0$, from $\mathrm{h}^i(E)=0$ we obtain $\mathrm{Hom}(\mathcal{Q}^{\vee}_X, E)\neq 0$. Let $s:\mathcal{Q}^{\vee}_X\to  E$ be a non-trivial morphism. Since $E$ is Gieseker-stable, we know that $\mathrm{ch}_1(\mathrm{Im}(s))=0$. Hence $\mathrm{ch}_1(\mathrm{ker}(s))=-H$, and from the stability of $\mathcal{Q}^{\vee}_X$, $\mathrm{ker}(s)$ is $\mu$-stable.

	If $\mathrm{Im}(s)$ has rank $1$,  then $\mathrm{ch}_2(\mathrm{Im}(s))=aL$, where $a\leq -2$. We claim that $a\neq -2$. Indeed, since $E$ is Gieseker-stable, we know that $\mathrm{ch}_{3}(\mathrm{Im}(s))=bP$, where $b\leq -1$. And by \cite[Proposition 4.8]{bayer2020desingularization} we know that $\mathrm{Im}(s)$ and $E$ are both $\sigma_{\alpha, -\frac{1}{2}}$-semistable for some $\alpha\gg 0$. Moreover, we have $\mu_{\alpha, -\frac{1}{2}}(\mathrm{Im}(s))=\mu_{\alpha, -\frac{1}{2}}(E)$. Hence $E/\mathrm{Im}(s)$ is also $\sigma_{\alpha, -\frac{1}{2}}$-semistable. But this contradicts the Lemma~\ref{lemma_numerical_constraint} since $\mathrm{ch}_3(E/\mathrm{Im}(s))=-bP$ and $-b\geq 1$. Hence we get $a\leq -3$, and $\mathrm{ch}_{\leq 2}(\mathrm{ker}(s))=(3, -H, -aL-2L)$ and then $-a-2\geq 0$, but this contradicts \cite[Proposition 3.2]{Li15}. 

	If $\mathrm{Im}(s)$ has rank $2$, then from $\mathrm{Im}(s)\subset E$ we have  $\mathrm{ch}_2(\mathrm{Im}(s))=aL$, where $a\leq -4$. This means $\mathrm{ch}_{\leq 2}(\mathrm{ker}(s))=(2, -H, -aL-2L)$. %By the stability of $\mathcal{Q}^{\vee}$, $\mathrm{ker}(s)$ is also slope-stable. 
	Thus by \cite[Proposition 3.2]{Li15}, the only possible case $a=-4$. Therefore, we have $\mathrm{ch}(\mathrm{ker}(s))=(2,-H,2L, (c-\frac{1}{6})P)$, where $c\geq 0$. Now from \cite[Proposition 3.5]{BCFacm}, we obtain $\chi(\mathrm{ker}(s))=0$, which implies $c=0$. Thus, $s$ is surjective and $\mathrm{ch}(\mathrm{ker}(s))=\mathrm{ch}(\mathcal{U}_X)$. Then we get $\mathrm{ker}(s)\cong \mathcal{U}_X$. Therefore, if there exists a sheaf $E\in M_X(2,0,4)$ such that $E\notin \Ku(X)$, then we have an exact sequence $0\to \mathcal{U}_X\to \mathcal{Q}^{\vee}_X\to E\to 0.$

	Conversely, for any non-trivial morphism $t\in \mathrm{Hom}(\mathcal{U}_X, \mathcal{Q}^{\vee}_X)=\mathbb{C}^5$, by the stability of $\mathcal{U}_X$ and $\mathcal{Q}^{\vee}_X$, we know that $t$ is injective. Let $W$ be the cokernel of $t:\mathcal{U}_X\hookrightarrow \mathcal{Q}^{\vee}_X$. It's easy to see that $W$ is torsion-free. We need to show that $W$ is Gieseker-stable. By the $\mu$-stability of $\mathcal{Q}^{\vee}_X$, we know that $W$ is $\mu$-semistable. Let $W'$ be the minimal destabilizing quotient sheaf with respect to the Gieseker-stability. Then we have $\mathrm{ch}_{\leq 2}(W')=(1,0,xL)$, where $x\leq -2$. Then the kernel $K'$ of the composition $\mathcal{Q}^{\vee}_X\twoheadrightarrow W\twoheadrightarrow W'$ has Chern character $\mathrm{ch}_{\leq 2}(K')=(3,-H,(-x-2)L)$. Since $W'\subset \mathcal{Q}^{\vee}_X$, from the stability of $\mathcal{Q}^{\vee}_X$ we have $W'$ is $\mu$-stable. This makes a contradiction by \cite[Proposition 3.2]{Li15} since $-x-2\geq 0$.	
\end{proof}

\begin{prop} \label{prop_description_contraction}
    Let $X$ be a genus $8$ prime Fano threefold and $\sigma$ be a Serre-invariant stability condition on $\Ku(X)$. Then the projection functor induces a morphism
\[s: M^{ss}_X(2,0,4)\to \mathcal{M}^{ss}_{\sigma}(\Ku(X), 2[I_C])\] 
such that $s$ is a birational morphism contracting a $\mathbb{P}^4$ to a unique point.
%and the restriction gives an isomorphism
%\[M_X(2,0,4)\xrightarrow{\cong} \mathcal{M}_{\sigma'}(\mathcal{A}_X, 2-4L)\]
%for every Serre-invariant stability condition $\sigma'$ on $\mathcal{A}_X$.
\end{prop}		
\begin{proof}
    It is routine to show that the projection functor $\mathrm{pr}$ induces a morphism $s: M^{ss}_X(2,0,4)\to \mathcal{M}^{ss}_{\sigma'}(\Ku(X), 2[I_C])$. We know that $M^{ss}_X(2,0,4)$ is projective and  $\mathcal{M}^{ss}_{\sigma'}(\Ku(X), 2[I_C])$ is proper, hence $s$ is also projective. If $X$ is a genus $8$ prime Fano threefold, then $s$ is \'etale over the open locus $U\subset M^{ss}_X(2,0,4)$, parametrizing $E\in M^{ss}_X(2,0,4)$ such that $E\in\Ku(X)$. Since $s|_U$ is injective, $s|_U$ is an open immersion. Hence $s$ is a birational morphism. Now note that $\mathrm{ext}^1(\mathcal{Q}^{\vee}_X, \mathcal{U}_X[1])=1$, then $s$ maps $E$ such that $E\notin\Ku(X)$, to a unique point. By Lemma~\ref{204-in-ku}, such $E$ are parametrized by $\mathbb{P}(\mathrm{Hom}(\mathcal{U}_X, \mathcal{Q}^{\vee}_X))=\mathbb{P}^4$. Thus, the result follows.
\end{proof}

