\begin{proof}[Proof of Theorem~\ref{main_theorem_geometric_interpretation_text}]
\noindent
\begin{enumerate}
\item Let $X$ be a Gushel-Mukai threefold, and denote by $\mathcal{C}(X)$ the Hilbert scheme of conics on $X$, which consists of curves $C$ whose Hilbert polynomial is $p_C(t)=2t+1$. See \cite[Section 6]{jacovskis2021categorical} for an explicit description of $\mathcal{C}(X)$. By \cite[Proposition 7.1]{jacovskis2021categorical}, the ideal sheaf $I_C\not\in\Ku(X)$ if and only if 
\begin{itemize}
\item $C$ is a $\sigma$-conic (cf.~\cite[P.5]{debarre2008period}) when $X$ is an ordinary Gushel-Mukai threefold (these conics are parametrized by a line $L_{\sigma}$, which is the unique exceptional curve in the surface $\mathcal{C}(X)$ if $X$ is general); 
\item $C$ is the preimage of a line in $Y$ when $X$ is a special Gushel-Mukai threefold (here we use the notation in Subsection~\ref{subsec_reductionk3}; such a family of conics is parametrized by the Hilbert scheme of lines $F(Y)\cong \mathbb{P}^2$ in $Y$ which is also one of the two components of $\mathcal{C}(X)$).
\end{itemize}
In particular, for such a conic $C$ there is a short exact sequence
    $$0\rightarrow\mathcal{U}_X\rightarrow\mathcal{Q}_X^{\vee}\rightarrow I_C\rightarrow 0.$$
Denote by $\mathrm{pr}:=\bL_{\oh_X}\bL_{\mathcal{U}^{\vee}_X}:D^b(X)\rightarrow\Ku(X)$ the projection functor. Then by \cite[Proposition 7.2, Lemma 7.6]{jacovskis2021categorical}, the projection functor induces a contraction of $\mathcal{C}(X)$ along the exceptional locus $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ (which by the above short exact sequence parametrizes conics $C$ with $I_C\not\in\Ku(X)$) to the Bridgeland moduli space of $\sigma$-stable objects $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ constructed in \cite[Theorem 7.12]{jacovskis2021categorical}. When $X$ is ordinary, the exceptional locus $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)\cong L_\sigma\cong \mathbb{P}^1$ (if in addition $X$ is ordinary and general, then $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ is isomorphic to the minimal model $\mathcal{C}_m(X)$ of the Fano surface $\mathcal{C}(X)$ of conics on $X$); when $X$ is special, the exceptional locus $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)\cong F(Y)\cong \mathbb{P}^2$. The claim then follows from Theorem~\ref{main_theorem_geometric_interpretation_text}.
\item Let $X$ be a genus $8$ prime Fano threefold, and denote by $\mathcal{M}^{ss}_X(2,0,4)$ the moduli space of semistable sheaves of rank $2$, $c_1=0,c_2=4L,c_3=0$. Then by Lemma~\ref{204-in-ku}, those sheaves $E$ are not in $\Ku(X)$ if and only if there is a short exact sequence 
    $$0\rightarrow\mathcal{U}_X\rightarrow\mathcal{Q}^{\vee}_X\rightarrow E\rightarrow 0.$$
A family of such sheaves is then parametrized by $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)\cong\mathbb{P}^4$. On the other hand, by Proposition~\ref{prop_description_contraction}, the projection functor $\bL_{\oh_X}\bL_{\mathcal{U}^{\vee}_X}$ induces a morphism $\mathcal{M}^{ss}_X(2,0,4)\rightarrow\mathcal{M}_{\sigma}^{ss}(\Ku(X),2[I_C])$, which is a birational morphism contracting the $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)\cong \mathbb{P}^4$ to a single smooth point in the moduli space. The proof can then be finished using Theorem~\ref{main_theorem_geometric_interpretation_text}.
\end{enumerate}
\end{proof}

We conclude this section using the following remarks.

\begin{rem}\label{rmk_alternativeproof}
    The identification of $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ with the exceptional locus of the contraction morphism $\mathcal{C}(X)\rightarrow\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ in Theorem~\ref{main_theorem_geometric_interpretation_text} is not accidental. Let us first consider the case when $g=6$. Let $X$ be an ordinary Gushel-Mukai threefold with semi-orthogonal decomposition 
    $$D^b(X)=\langle\Ku(X),\mathcal{Q}^{\vee}_X,\oh_X\rangle,$$
where $\mathcal{Q}^{\vee}_X\cong\bL_{\oh_X}\mathcal{U}^{\vee}_X[-1]$. Consider the distinguished object $\pi(\mathcal{Q}^{\vee}):=\bR_{\mathcal{U}_X}\mathcal{Q}^{\vee}_X$ in the Kuznetsov component $\Ku(X)$. By \cite[Lemma 5.4]{jacovskis2021categorical}, there is a two-term complex given by 
    $$\mathcal{U}_X[1]\rightarrow\pi(\mathcal{Q}^{\vee}_X)\rightarrow\mathcal{Q}^{\vee}_X,$$ which is also isomorphic to the projection object $\mathrm{pr}(I_C)$ if $I_C\not\in\Ku(X)$. By \cite[Lemma 7.4]{jacovskis2021categorical}, it is $\sigma$-stable in $\Ku(X)$ and thus represents a point $[\pi(\mathcal{Q}^{\vee}_X)]$ in the moduli space $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$. The tangent space of the moduli space at the point $[\pi(\mathcal{Q}^{\vee}_X)]$
is given by $\mathrm{Ext}^1(\pi(\mathcal{Q}_X^{\vee}),\pi(\mathcal{Q}^{\vee}_X))$. By adjunction, it is isomorphic to $\mathrm{Ext}^1(\pi(\mathcal{Q}^{\vee}_X),\mathcal{Q}^{\vee}_X)$. Applying $\mathrm{Hom}(-,\mathcal{Q}^{\vee}_X)$ to the triangle defining $\pi(\mathcal{Q}^{\vee}_X)$, we get a long exact sequence 
    $$\ldots\rightarrow\mathrm{Ext}^1(\mathcal{Q}^{\vee}_X,\mathcal{Q}^{\vee}_X)\rightarrow\mathrm{Ext}^1(\pi(\mathcal{Q}^{\vee}_X),\mathcal{Q}^{\vee}_X)\rightarrow\mathrm{Ext}^1(\mathcal{U}_X[1],\mathcal{Q}^{\vee}_X)\rightarrow\mathrm{Ext}^2(\mathcal{Q}^{\vee}_X,\mathcal{Q}^{\vee}_X)\rightarrow\ldots.$$
Since $\mathcal{Q}^{\vee}_X$ is an exceptional object, we have $\mathrm{Ext}^{\geq 1}(\mathcal{Q}^{\vee}_X,\mathcal{Q}^{\vee}_X)=0$. It then follows that $\mathrm{Ext}^1(\pi(\mathcal{Q}_X^{\vee}),\pi(\mathcal{Q}^{\vee}_X))\cong\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$. This means that the vector space $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ is isomorphic to the tangent space of the Bridgeland moduli space $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ at $[\pi(\mathcal{Q}^{\vee}_X)]$. Moreover, when blowing up $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ at the point $[\pi(\mathcal{Q}^{\vee}_X)]$, one obtains the birational morphism $\mathcal{C}(X)\rightarrow\mathcal{M}_{\sigma}(\Ku(X),[I_C])$. As a result, the projectivization $\mathbb{P}\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ is identified with the exceptional divisor for the contraction morphism $\mathcal{C}(X)\rightarrow\mathcal{M}_{\sigma}(\Ku(X),[I_C])$. When $X$ is a special GM threefold, the point $[\pi(\mathcal{Q}^{\vee}_X)]$ is a singular point, but a similar identification as above still holds. The genus $8$ case is entirely analogous.
\end{rem}

\begin{rem}\label{rmk_geometricinterpretation}
    Using Theorem~\ref{main_theorem_geometric_interpretation_text} and Remark~\ref{rmk_alternativeproof}, we give an explanation of $\mathrm{Ker}d\mathcal{P}=\mathrm{Ker}\eta\cong \mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ proved in Theorem~\ref{thm_inf_torellI_Categorical} for general ordinary Gushel-Mukai threefolds $X$. Consider the period map sending $X$ to its intermediate Jacobian $J(X)$. It is known that the connected component of the fiber containing $X$ is the Bridgeland moduli space $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$, modulo an involution (cf.~\cite[Theorem 7.4]{debarre2008period} and \cite[Theorem 7.12]{jacovskis2021categorical}). Thus the kernel of the differential of the period map $d\mathcal{P}$ can be identified with the tangent space of $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ at the distinguished point $[\pi(\mathcal{Q}^{\vee}_X)]$ (note that when identifying the connected component of the fiber of the period map with $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$, this point corresponds to the isomorphism class of $X$, according to Logachev's reconstruction theorem \cite[Theorem 7.7]{logachev2012fano}). By Theorem~\ref{main_theorem_geometric_interpretation_text} and Remark~\ref{rmk_alternativeproof}, the tangent space of $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ at $[\pi(\mathcal{Q}^{\vee}_X)]$ is isomorphic to $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$. Combining the above, we get $\mathrm{Ker}d\mathcal{P}\cong \mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$. 
\end{rem}

\begin{rem}    
    We have used both Hodge theoretical and categorical methods to describe the kernel $\mathrm{Ker}d\mathcal{P}$ for a special Gushel-Mukai threefold $X\rightarrow Y$ in Theorem~\ref{maintheorem} and Theorem~\ref{thm_inf_torellI_Categorical} respectively. Using the notation there, we get $\mathrm{H}^1(Y,T_Y(-1))\cong \mathrm{Ker}d\mathcal{P}=\mathrm{Ker}\eta\cong\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$. On one side, $\mathrm{H}^1(Y, T_Y(-1))$ represents infinitesimal deformations of $X$ in the ``normal direction" to the locus of special Gushel-Mukai threefolds. Moreover, $\mathrm{H}^1(Y,T_Y(-1))\cong \mathrm{Ker}d\mathcal{P}$. Thus $\mathrm{H}^1(Y, T_Y(-1))$ can be thought of as the space of infinitesimal deformations of $X$ to possibly ordinary Gushel-Mukai threefolds, with the property that its intermediate Jacobian $J(X)$ remains the same. On the other side, $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ is isomorphic to the tangent space of $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ at the distinguished point $[\pi(\mathcal{Q}^{\vee}_X)]$ corresponding to $[X]$. Since $\mathcal{M}_{\sigma}(\Ku(X),[I_C])$ can be identified with the connected component of the fiber of the (categorical) period map containing $[X]$ (cf.~\cite[Theorem 1.9]{bayer2022kuznetsov} and \cite[Theorem 1.1]{jacovskis2022brill}), $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$ parametrizes infinitesimal deformations of $X$ to possibly ordinary Gushel-Mukai threefolds that are period partners of $X$, sharing the same intermediate Jacobian with $X$. In this way, we identify $\mathrm{H}^1(Y,T_Y(-1))$ with $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$. We hope there is direct way to relate $\mathrm{H}^1(Y,T_Y(-1))$ and $\mathrm{Hom}(\mathcal{U}_X,\mathcal{Q}^{\vee}_X)$, see Question~\ref{question_interpretation_two_kernel}.  
\end{rem}



