\section{Infinitesimal Torelli for ordinary Verra threefolds}\label{section_Verra_Torelli}
    In this appendix, we study the infinitesimal Torelli problem for ordinary Verra threefolds. An ordinary Verra threefold is a smooth $(2,2)$-divisor $V\subset \mathbb{P}^2\times\mathbb{P}^2$. Our goal is to prove the infinitesimal Torelli theorem (cf.~ Proposition~\ref{thm_inftorelli_ordinary_verra}) for these Verra threefolds. Let us also mention that the Torelli theorem for a general Verra threefold has been proved, cf.~\cite[Theorem 5.6]{MR1474894}.

	The strategy is quite similar to that in the proof of \cite[Theorem 1.1]{Flenner1986} or \cite[Theorem 5.1]{debarre2008period}. Specifically, we start with the conormal bundle sequence for $V\subset \mathbb{P}^2\times\mathbb{P}^2$:
\begin{equation}\label{eq:overraconormal}
    0\to \mathcal{O}_V(-2,-2)\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1\vert_V\to \Omega_V^1\to 0.
\end{equation}
By \cite[Theorem 2.1]{Flenner1986}, we get 
    \[0\to \Omega_V^1(-2,-2)\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2\vert_V\to \Omega_V^2\to 0.\]
Tensoring the above sequence with $\omega_V^{-1}\cong\mathcal{O}_V(1,1)$ and observing that $T_V\otimes \omega_V\cong \Omega_V^2$ (and also that $\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2\vert_V\otimes \mathcal{O}_V(1,1)\cong \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2\vert_V\otimes \mathcal{O}_{\mathbb{P}^2\times\mathbb{P}^2}(1,1)\vert_V\cong \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\vert_V$), one has 
\begin{equation}\label{eq:overratangent}
 0\to \Omega_V^1(-1,-1)\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\vert_V\to T_V\to 0.   
\end{equation}
We also need the following sequence which is obtained by taking the dual sequence of \eqref{eq:overraconormal} and then tensoring it with $\omega_V\cong \mathcal{O}_V(-1,-1)$:
\begin{equation}\label{eq:overraOmega2}
    0\to \Omega_V^2\to (\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1\vert_V)^\vee\otimes \omega_V\to \mathcal{O}_V(1,1)\to 0.
\end{equation}

	Applying \cite[Lemma 2.10]{Flenner1986}, we get the following diagram which is commutative up to sign.
\begin{equation}\label{eq:overrainftorelli}
    \xymatrix{\mathrm{H}^1(V,T_V)\ar[d]^{\eqref{eq:overratangent}} &\otimes &\mathrm{H}^1(V,\Omega_V^2)\ar[r]\ar@{=}[d] &\mathrm{H}^2(V,\Omega_V^1)\ar[d]^{\eqref{eq:overraconormal}} \\
   \mathrm{H}^2(V,\Omega_V^1(-1,-1))\ar[d]^{\eqref{eq:overraconormal}} &\otimes &\mathrm{H}^1(V,\Omega_V^2)\ar[r] &\mathrm{H}^3(V,\mathcal{O}_V(-2,-2))\ar@{=}[d]\\
    \mathrm{H}^3(V,\mathcal{O}_V(-3,-3)) &\otimes &\mathrm{H}^0(V,\mathcal{O}_V(1,1))\ar[r]\ar[u]^{\eqref{eq:overraOmega2}} &\mathrm{H}^3(V,\mathcal{O}_V(-2,-2))\\}
\end{equation}

	The bottom row of the above diagram is Serre dual the following sequence 
    \[\mathrm{H}^0(V,\mathcal{O}_V(1,1))\otimes \mathrm{H}^0(V,\mathcal{O}_V(1,1))\to \mathrm{H}^0(V,\mathcal{O}_V(2,2))\]
which is surjective. In more detail, using the ideal sheaf sequence $0\to \mathcal{O}_{\mathbb{P}^2\times \mathbb{P}^2}(-2,-2)\to \mathcal{O}_{\mathbb{P}^2\times \mathbb{P}^2}\to \mathcal{O}_V\to 0$ for $V\subset \mathbb{P}^2\times\mathbb{P}^2$, we get the following commutative diagram:
\begin{equation*} 
    \xymatrix{\mathrm{H}^0(\mathbb{P}^2\times \mathbb{P}^2,\mathcal{O}_{\mathbb{P}^2\times \mathbb{P}^2}(1,1))\ar[d]^{\cong} &\otimes &\mathrm{H}^0(\mathbb{P}^2\times \mathbb{P}^2,\mathcal{O}_{\mathbb{P}^2\times \mathbb{P}^2}(1,1))\ar[r]\ar[d]^{\cong} &\mathrm{H}^0(\mathbb{P}^2\times \mathbb{P}^2,\mathcal{O}_{\mathbb{P}^2\times \mathbb{P}^2}(2,2))\ar@{->>}[d]^{} \\
   \mathrm{H}^0(V,\mathcal{O}_V(1,1)) &\otimes &\mathrm{H}^0(V,\mathcal{O}_V(1,1))\ar[r] &\mathrm{H}^0(V,\mathcal{O}_V(2,2)).\\}
\end{equation*}
By Kunneth's formula (see also \cite[P.317]{Flenner1986}), the map in the top row is surjective, and hence so is the arrow in the bottom row. As a result, the bottom row of \eqref{eq:overrainftorelli} is non-degenerate with respect to the first factor. Therefore, the infinitesimal Torelli theorem for an ordinary Verra threefold $V\subset \mathbb{P}^2\times\mathbb{P}^2$ (that is, the top row of \eqref{eq:overrainftorelli} is non-degenerate with respect to the first factor) follows from the lemma below (which implies that the vertical maps on the leftmost column in the commutative diagram \ref{eq:overrainftorelli} are both injective, see \eqref{eq:overraconormal} and \eqref{eq:overratangent}).

\begin{lem}
	Let $V\subset \mathbb{P}^2\times\mathbb{P}^2$ be an ordinary Verra threefold. Then it holds that 
\begin{enumerate}
\item $\mathrm{H}^1(V,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\vert_V)=0$;
\item $\mathrm{H}^2(V,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1(-1,-1)\vert_V)=0$.
\end{enumerate}
\end{lem}
\begin{proof}
	For (1), by twisting the ideal sheaf sequence for $V\subset \mathbb{P}^2\times\mathbb{P}^2$ by $\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)$, one gets
\[
0\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(-1,-1)\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\to \Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\vert_V\to 0.
\]
It suffices to verify that %(noting by the projection formula that $(i_*i^*\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2)\otimes\mathcal{O}_{\mathbb{P}^2\times\mathbb{P}^2}(1,1)\cong i_*(\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\vert_V)$)
\begin{enumerate}
\item[(a)] $\mathrm{H}^1(\mathbb{P}^2\times\mathbb{P}^2,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1))=0$;
\item[(b)] $\mathrm{H}^2(\mathbb{P}^2\times\mathbb{P}^2,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(-1,-1))=0$,
\end{enumerate}
Further note that \[
\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^2(1,1)\cong (\Omega_{\mathbb{P}^2}^2(1)\boxtimes \mathcal{O}_{\mathbb{P}^2}(1))\oplus (\Omega_{\mathbb{P}^2}^1(1)\boxtimes \Omega_{\mathbb{P}^2}^1(1))\oplus (\mathcal{O}_{\mathbb{P}^2}(1)\boxtimes \Omega_{\mathbb{P}^2}^2(1))),\] then the vanishing of the cohomology group in $(a)$ follows from Kunnenth's formula for sheaf cohomology. The proof of $(b)$ is similar. For (2), a similar computation reduces the claim to the following:
\begin{enumerate}
\item[(c)] $\mathrm{H}^2(\mathbb{P}^2\times\mathbb{P}^2,\Omega_{\mathbb{P}^2\times\mathbb{P}^2}^1(-1,-1))=0$;
\item[(d)] $\mathrm{H}^3(\mathbb{P}^2\times\mathbb{P}^2,\Omega_{\mathbb{P}^\times\mathbb{P}^2}^1(-3,-3))=0$.
\end{enumerate}
The statement $(c)$ follows from Kodaira-Akizuki-Nakano vanishing, and the statement $(d)$ can be deduced again from Kunneth's formula. 
\end{proof}

	In conclusion, we have proved the following proposition.
\begin{prop} \label{thm_inftorelli_ordinary_verra}
    Let $V\subset \mathbb{P}^2\times\mathbb{P}^2$ be an ordinary Verra threefold. Then the infinitesimal period map 
    \[d\mathcal{P}:\mathrm{H}^1(V,T_V)\to \mathrm{Hom}(\mathrm{H}^1(V,\Omega_V^2), \mathrm{H}^2(V,\Omega_V^1))\]
    is injective.
\end{prop}



