\section{Variance Reduction through Aggregation}
A Bagged Sharpe Ratio estimate is defined as the average of $K$ bootstrapped Sharpe Ratio estimates:
$$
\hat{\theta}^{B} = \tfrac{1}{K}\sum_{k=1}^K \hat{\theta}_k^* 
$$
where bootstrapped Sharpe Ratio estimates are generated through IID resampling of asset returns. 
The average of many estimators has lower variance than a single estimator (``diversification"):
%	CV variance
\begin{align}
    \operatorname{var}\left(\hat{\theta}^{B} \right) = \operatorname{var}\left(\tfrac{1}{K}\sum_{k=1}^K\hat{\theta}_k^*\right) = \tfrac{1}{K} \operatorname{var}\left(\hat{\theta}\right) + \tfrac{1}{K^2}\sum_{\substack{j=1 \\ k \neq j}}^K\operatorname{cov}\left(\hat{\theta}_j^*, \hat{\theta}_k^* \right).  \nonumber
\end{align}
If $\operatorname{cov}\left(\hat{\theta}_j^*, \hat{\theta}_k^* \right) = \rho \operatorname{var}\left(\hat{\theta}_h^*\right)$ is constant for all $i,j$, we have
$$
\operatorname{var}\left(\hat{\theta}^{B} \right) = \tfrac{1}{K}\operatorname{var}\left(\hat{\theta}\right) + \tfrac{K-1}{K}\rho\operatorname{var}\left(\hat{\theta}\right)
$$

Then, as we increase the number of bootstrap samples,  $$\lim_{K \rightarrow \infty} \operatorname{var}\left(\hat{\theta}^{B} \right) = \rho\operatorname{var}\left(\hat{\theta}\right).$$
The limiting variance of the bootstrap aggregated Sharpe ratio is $\rho \times 100 \%$ of the standard backtest Sharpe ratio variance.

\section{Bias Expressions}
We prove the expressions for $\text{bias}\left(\hat{\mu}_{p}^{*}\right)$ and $\text{bias}\left(\hat{\sigma}_p^{*2}\right)$ under the assumptions in Section \ref{ssec:assumptions}.

Firstly, for $\text{bias}\left(\hat{\mu}_{p}^{*}\right)$, we have:
$$
\begin{aligned}
\text{bias}\left(\hat{\mu}^{*}_p\right) &= \E\left[R^{*}_{p,t+1}\right] - \E\left[R_{p,t+1}\right] \\
&= \E[w^{*}_t]\E[R^{*}_{t+1}] - \left({\E[w_t]\E[R_{t+1}] + \text{cov}(w_t,R_{t+1})}\right) \\
&= -\text{cov}(w_t,R_{t+1})
\end{aligned}
$$
When the variance is known, the expectations $\E[w_t]$ and $\E[R_{t+1}]$ are the same whether data is iid or temporally dependent, {\it i.e.} $\E[w_t] = \E[w_t^{*}]$ and $\E[R_{t}] = \E[R_t^*]$. This is because the autocorrelation does not affect the mean of the risky asset, and then we have that $E \left[ R^{*}_{t+1} \right] = E \left[ R_{t+1} \right]$, so that $E\left[\hat{\mu}^{*}_t\right] = E\left[\hat{\mu}_t\right]$, and finally $E[w_t] = E[w_t^{*}]$. This is not true when the variance is unknown. 

Next, for $\text{bias}\left(\hat{\sigma}_p^{*2}\right)$, we have:
\begin{align}
\text{bias}\left(\hat{\sigma}_p^{*2}\right) &= \sigma_{p}^{*2}-\sigma_{p}^{2}  \nonumber \\
&=\text{var}\left( R_{p}^* \right)- \text{var}\left( R_{p} \right) \nonumber  \\
&= \E[R_{p}^{*2}]- \mu_{p}^{*2}-\E[R_{p}^{2}]+\mu_{p}^{2} \nonumber\\
&= \E \left[ w^{*2}_t \right]\E[R^{*2}_{t+1}] - \E \left[ w^{*}_t \right]^{2}\E\left[R^{*}_{t+1}  \right]^{2}\nonumber \\
&\qquad - \left(   \E \left[ w_t^{2} \right]\E[R_{t+1}^{2}] + \operatorname{cov}\left(w_{t}^{2},R_{t+1}^{2}\right)\right) \nonumber \\
&\qquad +   \E \left[ w_t \right]^{2}\E[R_{t+1}]^{2} + 2\E \left[ w_t \right]\E\left[ R_{t+1} \right] \operatorname{cov}\left(w_{t},R_{t+1}\right) \nonumber\\
&\qquad \qquad +\operatorname{cov}^{2}\left(w_{t},R_{t+1}\right). \nonumber
\end{align}
We have (by adding and subtracting $\E \left[ w^{*}_t \right]^{2}\E\left[R^{*2}_{t+1}  \right]$),
\begin{equation}\label{eqn:varw}
\begin{aligned}
&\E \left[ w^{*2}_t \right]\E[R^{*2}_{t+1}] - \E \left[ w^{*}_t \right]^{2}\E\left[R^{*}_{t+1}  \right]^{2}  \\
&= \E \left[ w^{*}_t \right]^{2}\text{var}\left( R_{t+1} \right) + \E \left[ R_{t+1}^{2} \right]\text{var}\left(w^{*}_{t}  \right).  
\end{aligned} 
\end{equation}
Similarly  (by adding and subtracting $\E \left[ w_t \right]^{2}\E\left[R^{2}_{t+1}  \right]$), we have
\begin{equation}\label{eqn:varwstar}
\begin{aligned}
& \E \left[ w^{2}_t \right]\E[R^{2}_{t+1}] - E \left[ w_t \right]^{2}\E\left[R_{t+1}  \right]^{2} \\
&= \E \left[ w_t \right]^{2}\text{var}\left( R_{t+1} \right) + \E \left[ R_{t+1}^{2} \right]\text{var}\left(w_{t}  \right). 
\end{aligned}    
\end{equation}
Therefore, \ref{eqn:varw} - \ref{eqn:varwstar} is $\E \left[ R_{t+1}^{2} \right]\left({ \text{var}\left( w^{*}_{t} \right) - \text{var}(w_{t})}\right)$ because when the variance is known then $E \left[ w_t \right]^{2} - E \left[ w^{*}_t \right]^{2}=0$. Now, 
$$
\begin{aligned}
&2\E \left[ w_t \right]\E\left[ R_{t+1} \right] \operatorname{cov}\left(w_{t},R_{t+1}\right)+\operatorname{cov}^{2}\left(w_{t},R_{t+1}\right) \\
&= \operatorname{cov}\left(w_{t},R_{t+1}\right) \left(\operatorname{cov}\left(w_{t},R_{t+1} \right) + 2 \E[w_{t}]\E \left[ R_{t+1} \right]  \right)  \\
&=\tfrac{1}{2}\operatorname{cov}\left(w^2_{t},R_{t+1}^{2}\right)
\end{aligned}
$$
where equality between the second and third lines is true for Gaussian returns with known variance. 

Putting it all together, 
$$
\text{bias}\left(\hat{\sigma}_p^{*2}\right) = \E \left[ R_{t+1}^{2} \right]\left({\text{var}(w^{*}) - \text{var}(w)}\right) - \tfrac{1}{2}\operatorname{cov}\left(w^{2},R_{t+1}^{2}\right).
$$

\section{Preliminaries}
For the derivations below, we define the following sums:
\begin{align}
A_{n,\phi} &= \tfrac{1}{n}\sum_{i=t-n+1}^t\phi^{|t+1-i|} =\tfrac{1}{n} \sum_{k=1}^n\phi^k,  \label{eqn:appC.A}\\
B_{n,\phi} &= \tfrac{1}{n^2}\sum_{i=1}^n\sum_{\substack{ j \neq i}}^n\phi^{|i-j|}, \\
\end{align}

The sums $A_{n,\phi}$, $B_{n,\phi}$ are bounded for $\phi \in [0,1)$ and all $n$. We use the following bounds in our derivations for the bias in the mean and variance.

Since $\phi^{k}\leq\phi$ for all $k \geq 1, \phi \in [0,1)$, we have 
$$
\begin{aligned}
A_{n,\phi}&: \quad 0\leq   \tfrac{1}{n}\sum_{k=1}^n\phi^k \lt \tfrac{1}{n}n\phi \lt \phi, \\
B_{n,\phi}&: \quad 0 \leq \tfrac{1}{n^2}\sum_{i=1}^n\sum^n_{\substack{j=1, j\neq i}}\phi^{|i-j|} \lt \phi. \\
\end{aligned}
$$

Our derivations use the following useful property of multivariate Gaussian variables. If $X$ and $Y$ are jointly normally distributed, with non-zero means, we have:
$$\label{eq:mvprop3}
\text{cov}(X^2,Y^2) = 2\text{cov}(X,Y)\left(\text{cov}(X,Y) +2\E[X]\E[Y]\right)
$$


