\section{Bounding the resampled performance}\label{appsec:mean_bound}

Here we consider the bounds on the normalised resampled portfolio performance bias: $\tfrac{1}{\mu_{p}} \text{bias}\left(\hat{\mu}_{p}^{*}\right)$.

\subsection{Resampled performance bias bounds}

We start by considering the bounds on the portfolio performance bias $\text{bias}\left(\hat{\mu}_{p}^{*}\right)$:
\begin{align}
\text{bias}\left(\hat{\mu}^{*}_p\right) &= -\text{cov}(w_t,R_{t+1})
= -\tfrac{1}{\sigma_{R}^{2}}\text{cov}(\hat{\mu}_{t},R_{t+1}). \label{eqn:appD1.bias}
\end{align}
Assuming rolling sample estimators:
\begin{align}
	\hat{\mu}_t = \tfrac{1}{n}\sum_{i=t-n+1}^tR_{i} &= \tfrac{1}{n}\sum_{i=t-n+1}^t\mu_{i} + \epsilon_i = \bar{\mu}_t + \bar{\epsilon}_t. \label{eqn:appD1.mean}
\end{align}
Additionally, we have $R_{t+1} = \mu_{t+1}+\epsilon_{t+1}$. Therefore, we have:
\begin{align}
-\tfrac{1}{\sigma_{R}^{2}}\text{cov}(\hat{\mu}_{t},R_{t+1}) =-\tfrac{1}{\sigma_{R}^{2}}\text{cov}(\bar{\mu}_t, \mu_{t+1}) \label{eqn:appD1.cov}
\end{align}
since the noise terms $\epsilon_{t}$ are IID. Now, focusing on the first term we have:
$\text{cov}(\mu_t, \mu_{t-k}) = \phi^k\sigma^2_\mu$. Therefore using Eqn. \ref{eqn:appC.A} and Eqn. \ref{eqn:appD1.cov}
$$
\text{cov}(\bar{\mu}_t, \mu_{t+1}) = \tfrac{\sigma_\mu^2}{n}\sum_{k=1}^n\phi^k =\sigma_\mu^2A_{n,\phi}.
$$
Which gives an expression for the bias:
\begin{align}
\text{bias}\left(\hat{\mu}_p^{*}\right)=-\frac{1}{\gamma} \frac{\sigma_{\mu}^{2}}{\sigma_{R}^{2}} A_{n,\phi}.
\end{align}
If we assume $\phi>0$, then we can bound the covariance:
$$
0  \leq\text{cov}(\bar{\mu}_t, \mu_{t+1}) \leq\sigma_{\mu}^2\phi
$$
where the upper bound is attained when $n=1$. This allows us to bound the portfolio performance bias. Furthermore, we define $\psi = \text{corr}(R_t, R_{t+1})$. Then, assuming constant covariance
$$
\begin{aligned}
\psi &= \tfrac{1}{\sigma^2_R}\text{cov}(R_t, R_{t+1})\\
     &= \tfrac{1}{\sigma^2_R}\text{cov}(\mu_t + \epsilon_t, \mu_{t+1} + \epsilon_{t+1}) \\
     &= \tfrac{1}{\sigma^2_R}\text{cov}(\mu_t, \mu_{t+1}) = \tfrac{\sigma_{\mu}^2}{\sigma^2_R}\phi.
\end{aligned}
$$

Therefore, 
$$
-\tfrac{1}{\gamma} \psi \leq -\tfrac{1}{\gamma} \tfrac{\sigma_{\mu}^{2}}{\sigma_{R}^{2}} \phi \leq \text{bias}\left(\hat{\mu}_p^{*}\right) \leq 0
$$
where the lower bound is attained when $n=1$.

\subsection{Bounding portfolio performance}

We start by solving for average portfolio performance $\mu_{p}$ under the original DGP.
\begin{align}
\mu_{p} &= \E[R_{p,t+1}] \nonumber  \\
&= \E[w_{t}]\E[R_{t+1}] + \operatorname{cov}\left(w_{t},R_{t+1}\right) \nonumber  \\
&= \tfrac{1}{\gamma}\tfrac{1}{\sigma_{R}^{2}}\E\left[\hat{\mu}_t\right]\E \left[ R_{t+1} \right] + \tfrac{1}{\gamma}\tfrac{1}{\sigma_{R}^{2}}\operatorname{cov}\left(\hat{\mu}_{t},R_{t+1}\right) \nonumber  \\
&= \tfrac{1}{\gamma}\left( \tfrac{\mu^{2}}{\sigma_{R}^{2}}+\tfrac{\sigma_{\mu}^{2}}{\sigma_{R}^{2}} A_{n,\phi}\right) \leq \tfrac{1}{\gamma}\left( \theta^{2}+\psi \right) . 
\end{align}

Similarly, we have:
\begin{align}
\mu^{*}_{p} &= \E[R^{*}_{p,t+1}] \nonumber  \\
&= \E[w^{*}_{t}]\E[R^{*}_{t+1}] + \operatorname{cov}\left(w^{*}_{t},R^{*}_{t+1}\right) \nonumber  \\
&= \tfrac{1}{\gamma}\tfrac{1}{\sigma_{R}^{2}}\E\left[\hat{\mu}^{*}_t\right]\E \left[ R^{*}_{t+1} \right] \nonumber  \\
&= \tfrac{1}{\gamma}\left( \tfrac{\mu^{2}}{\sigma_{R}^{2}}\right) = \tfrac{1}{\gamma} \theta^{2}  . 
\end{align}


