\section{Bounding the resampled portfolio variance}\label{appsec:var_bound}

Here we consider the bounds on the resampled portfolio performance variance $\tfrac{1}{\sigma^{2}_{p}}\text{bias}\left(\hat{\sigma}_p^{*2}\right)$.

\subsection{Resampled performance variance bias}

We showed earlier that bias in the variance of the resampled portfolio performance is: 
$$
\text{bias}\left(\hat{\sigma}_p^{*2}\right) = \E \left[ R_{t+1}^{2} \right]\left(\text{var}(w^{*}) - \text{var}(w)\right) - \tfrac{1}{2}\operatorname{cov}\left(w^{2},R_{t+1}^{2}\right).
$$
First, we find a bound for $\text{var}(w^*) - \text{var}(w)$. This follows from:
$$
\begin{aligned}
\text{var}\left( w \right) &= \tfrac{1}{\gamma^{2}\sigma_{R}^{4}}\text{var}\left(\hat{\mu}_{t}  \right)  \\
&= \tfrac{1}{\gamma^{2}\sigma_{R}^{4}} \tfrac{1}{n^2}\text{var}\left(\textstyle\sum_{i=t-n+1}^t R_i\right) \\
&= \tfrac{1}{\gamma^{2}\sigma_{R}^{4}} \left( \tfrac{1}{n}\text{var}(R_i) + \tfrac{1}{n^2}\textstyle\sum_{i, j \neq i} \text{cov}\left(R_i, R_j\right) \right) \\
&= \tfrac{1}{\gamma^{2}\sigma_{R}^{4}} \left( \tfrac{1}{n}\text{var}(R_i) + \tfrac{1}{n^2}\textstyle\sum_{i,j \neq i} \text{cov}\left(\mu_i, \mu_j\right) \right) \\
&= \tfrac{1}{\gamma^{2}\sigma_{R}^{4}} \left(    \tfrac{\sigma^2_R}{n} + \sigma^2_{\mu}B_{n,\phi}\right) \\
& \leq \tfrac{1}{\gamma^{2}\sigma_{R}^{4}} \left( \tfrac{\sigma_{R}^{2}}{n} + \sigma_{\mu}^{2} \phi \right) \\
&\leq  \tfrac{1}{\gamma^{2}\sigma_{R}^{2}} \left( \tfrac{1}{n} + \tfrac{\sigma_{\mu}^{2}}{\sigma_{R}^{2}}\phi  \right).
\end{aligned}
$$
Now, $\text{var}\left( w^{*} \right)$ is the same as $\text{var}(w)$ except that $\operatorname{cov}\left(R_{i},R_{j}\right) = 0$ for $i \neq j$. Therefore, $B_{n,\phi}=0$, and we have
$$
\text{var}(w^*) = \frac{1}{\gamma^{2}} \frac{\sigma_{R}^{2}}{n},
$$
Furthermore, 
$$
\begin{aligned}
\text{var}(w^*) - \text{var}(w) &=-\frac{1}{\gamma^{2}} \sigma_{\mu}^{2} B_{n,\phi} \geq -\frac{1}{\gamma^{2}} \sigma_{\mu}^{2}\phi.
\end{aligned}
$$
Using this result, we can bound bias in the resampled portfolio performance variance $\text{bias}\left(\hat{\sigma}_p^{*2}\right)$:
$$
\begin{aligned}
\text{bias}&\left({\hat{\sigma}_p^{*2}}\right) = \E \left[ R_{t+1}^{2} \right]\left(\text{var}(w^{*}) - \text{var}(w)\right) - \tfrac{1}{2}\operatorname{cov}\left(w^{2},R_{t+1}^{2}\right) \\ 
&=\tfrac{1}{\gamma^{2}}\tfrac{1}{\sigma_{R}^4}\left[\E \left[ R_{t+1}^{2}   \right] \left(\text{var}\left( \hat{\mu}_{t}^{*} \right) - \text{var}\left( \hat{\mu}_{t} \right)\right) - \tfrac{1}{2}\operatorname{cov}\left(\hat{\mu}_{t}^{2}, R_{t+1}^{2}\right)\right] \\
&= \tfrac{1}{\gamma^{2}}\tfrac{1}{\sigma_{R}^4} \left[{\E \left[ R_{t+1}^{2} \right]\left(\text{var}\left( \hat{\mu}_{t}^{*} \right) - \text{var}\left( \hat{\mu}_{t} \right)\right) } \right. \\ 
 &~~~~~~~\left.{-\operatorname{cov}\left(\hat{\mu}_{t},R_{t}\right)\left( \operatorname{cov}\left(\hat{\mu}_{t},R_{t}\right) + 2 \E\left[\hat{\mu}_t\right] \E[R_{t+1}]\right) }   \right] \\
&= \tfrac{1}{\gamma^{2}}\tfrac{1}{\sigma_{R}^4} \left[{ -\left( \mu^{2}+\sigma_{R}^{2} \right)\sigma^2_{\mu}B_{n,\phi}  -\sigma_\mu^2 A_{n,\phi}\left( \sigma_\mu^2 A_{n,\phi} +2\mu^{2} \right) }    \right] \\
&\geq \tfrac{1}{\gamma^{2}}\tfrac{1}{\sigma_{R}^4}\left[{ -\left( \mu^{2}+\sigma_{R}^{2} \right)\sigma^2_{\mu}\phi - \sigma_{\mu}^{2}\phi\left( \sigma_{\mu}^{2}\phi+2\mu^{2} \right)}  \right] \\
&\geq -\tfrac{1}{\gamma^{2}} \tfrac{\sigma_{\mu}^{2}}{\sigma_{R}^{2}} \phi\left( \tfrac{3\mu^{2}}{\sigma_{R}^{2}}+\tfrac{\sigma_{\mu}^{2}}{\sigma_{R}^{2}}\phi + \tfrac{\sigma_{R}^{2}}{\sigma_{R}^{2}} \right) \\
&\geq -\tfrac{1}{\gamma^{2}}\psi\left( 3\theta^{2} + \psi+1 \right)  \\
&\geq -\tfrac{C}{\gamma^{2}}\psi  \quad \text{where} \quad C= \psi\left( 3\theta^{2} + \psi+1 \right).
\end{aligned}
$$

\subsection{Bounding the portfolio performance variance}

Furthermore, we have:
$$
\begin{aligned}
\sigma^{*2}_p &= E[R^{*2}_p]-\mu^{*2}_p\\
&= E[w^{*2}_t]E[R^2_{t+1}]-\mu^{*2}_p\\
&\approx \frac{1}{\gamma^2}\frac{\mu^2}{\sigma^4_R}\left(\sigma_{R}^2+\mu^2\right)-\mu^{*2}_p \\
&= \frac{1}{\gamma^2}\frac{\mu^2}{\sigma^2_{R}} + \frac{1}{\gamma^2}\frac{\mu^4}{\sigma^4_{R}} -\left(\frac{1}{\gamma}\frac{\mu^2}{\sigma_{R}^2}\right)^2 \\
&= \frac{1}{\gamma^2}\frac{\mu^2}{\sigma^2_{R}} = \frac{1}{\gamma^2}\theta^2
\end{aligned}
$$

