\section{Gauge potentials on M5-probes of 11D SuGra in Twisted cohomotopy}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We want to couple the theory to background gravitational charges. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{In Tangentially twisted cohomotopy}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\medskip
Since the only other field apart from $C_{3}$ in 11D SuGra is (super-)gravity, this must be {\it tangentially} twisted 4-cohomotopy. In other words, C-field flux is charge quantized in tangentially Sp(2) twisted 4-cohomotopy \cite[\S 3.1]{FSS20-H}.

We define {\it tangentially twisted or J twisted Cohomotopy} (described in \cite[\S 2.1]{FSS20-H}, \cite[\S 2.41]{FSS23-Char})
\begin{equation}
    \pi^{4+\tau}(X):=\mathrm{H}^{\tau}(X; S^{4})
    \end{equation}
    where we have the {\it twist} $\tau:X\longrightarrow{\mathrm{BSp}}(2)$.

    Also, we have the Borel-equivariantized quarternionic Hopf fibration $$h_{\mathbb{H}}\sslash\mathrm{Sp}(2):S^{7}\sslash\mathrm{Sp}(2)\longrightarrow{S^{4}}\sslash\mathrm{Sp}(2)$$ which will be useful here.
\begin{definition}[\bf Flux densities]
We are concerned with {\it flux densities} of the following form (\cite[\S 3.7]{FSS20-H}): 
\begin{equation}
\renewcommand{\arraystretch}{1.3}
  \label{TheFluxDensities}
	\Omega_{\mathrm{dR}}^{1}\left(
      -;
      \,
      \mathfrak{l}_{S^{4}\sslash \mathrm{Sp}{(2)}} S^{7}\sslash \mathrm{Sp}(2)\right)_{\mathrm{clsd}}
        :=
      \left\{\begin{array}{l|l}
		H_{3} & 
          \mathrm{d}\, H_{3}=\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega) \\
		G_{7} & \mathrm{d}\, G_{7}=\tfrac{1}{2} \tilde{G}_{4}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)\right) \\
		G_{4} & \mathrm{d}\, G_{4}=0 \\
		\tfrac{1}{2} p_{1}(\omega) & d\left(\tfrac{1}{2} p_{1}(\omega)\right)=0
	\end{array}\right\}
    \,,
\end{equation}
where we set
\begin{equation}
    \tilde{G}_{4}
    := 
    G_{4} + \tfrac{1}{4} p_{1}(\omega)
\end{equation}
and where $p_1(\omega)$ denotes the first Pontrjagin form for a given spin-connection on spacetime:
\begin{equation}
    \omega 
    \in 
    \Omega^{1}_{dR}\big(
      \tilde{X}; 
      \mathfrak{so}(d,1)
    \big)
    \,,
\end{equation}
 where $\tilde{X}:= \sqcup_{i} U_{i}$ for $\big\{ U_{i} \xrightarrow{\iota_i} X \}_{i \in I}$ an open cover of spacetime.
\end{definition}
\begin{remark}
Here we have already assumed $\widehat{M5}$ structure, thus the eight form $\chi_{8}$ coming from $l B\mathrm{Sp}(2)$ vanishes, cf. \cite[Ex. 3.2]{FSS21-Hopf}. Also note that
\begin{equation}
    \mathrm{CE}\big(
      \mathfrak{l} B\mathrm{Sp}(2)
    \big)
      \;\simeq\;
    \mathbb{R}\left[
      \begin{array}{c}
        \tfrac{1}{2}p_{1}(\omega)
        \\
        \chi_{8}
      \end{array}
    \right]
      \Big/
    \left(
      \begin{array}{ccl}
        \mathrm{d} (\tfrac{1}{2}p_{1}(\omega)) &=& 0, 
        \\
        \mathrm{d}\chi_{8} &=& 0
      \end{array}
    \right).
\end{equation}
\end{remark}
\begin{remark}
    Let $\omega$ be a connection 1-form on a principal bundle with structure group $SO(d,1)$ taking values in the Lie algebra $\mathfrak{so}(d,1)$, that is 
$\omega\in \Omega_{\mathrm{dR}}(\tilde{X}, \mathfrak{so}(d,1))$.
Then the Chern-Simons 3-form of the $\mathfrak{so}(d,1)$ valued spin connection $\omega$, on each $U_i$ is given by,
\begin{equation}
    \mathrm{CS}(\omega)
    \,=\, {\mathrm Tr}(\omega\wedge d\omega + \tfrac{2}{3} \omega \wedge \omega \wedge \omega)
\end{equation}
where the trace is taken over the fundamental/vector representation of $\mathfrak{so}(d,1)$,
satisfying 
\begin{equation}
  \mathrm{d} \, \mathrm{CS}(\omega) 
  \,=\, 
  \iota_i^\ast \tfrac{1}{2} p_{1}(\omega)
  \;\;\;
  \in
  \;
  \Omega^4_{\mathrm{dR}}(U_i)
  \,.
\end{equation}
The Chern–Simons form itself is not gauge invariant, but its exterior derivative is. 

{\it Globally}, it is a 3-form supported on $\tilde{X}$, that is, $$CS(\omega)\in \Omega_{\mathrm{dR}}^{3}(\tilde{X}, \mathfrak{so}(d,1).$$


\begin{definition}[\bf Traditional gauge potentials and gauge transformations]
\label{TraditionalFormulas}
Given such flux densities \eqref{TheFluxDensities} on some $U_i$, 
a traditional choice of {\it gauge potentials} is 
\begin{equation}
  \label{TraditionalGaugePotentials}
    \renewcommand{\arraystretch}{1.4}
	\left\{\begin{array}{l|l}
		C_{3} \in \Omega_{dR}^{3}\left(U_{i}\right) & \dd C_{3}=\tilde{G}_{4} \\
		C_{6} \in \Omega_{dR}^{6}\left(U_{i}\right) & \dd C_{6}= G_{7}-\tfrac{1}{2} C_{3}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)\right) \\
		B_{2} \in \Omega_{dR}^{2}\left(U_{i}\right) & \dd B_{2}= H_{3}-C_{3}+ \mathrm{CS}(\omega)
	\end{array}\right\}.
\end{equation}
Now, a {\it gauge transformation} between a pair of such gauge potentials is
\begin{align}
  \label{GaugeTransformations}
  \hspace{-3mm}
	\left(C_{3}, C_{6}, B_{2} \right) \sim\left(C_{3}^{\prime}, C_{6}^{\prime}, B_{2}^{\prime} \right) & \Longleftrightarrow 
    \nonumber 
    \\
    \exists & \left\{\!\!
    \renewcommand{\arraystretch}{1.3}
    \begin{array}{l|l}
		C_{2} \in \Omega_{dR}^{2}\left(U_{i}\right) & \dd C_{2}=C_{3}^{\prime}-C_{3} \\
		C_{5} \in \Omega_{dR}^{5}\left(U_{i}\right) & \dd C_{5}=C_{6}^{\prime}-C_{6}-\tfrac{1}{2} C_{3}^{\prime} C_{3}
        -
       \tfrac{1}{4} C_{2}
        \,
        p_1(\omega)
        \\
		B_{1} \in \Omega_{dR}^{1}\left(U_{i}\right) & \dd B_{1}=B_{2}^{\prime}-B_{2}+C_{2} -\int_{t\in[0,1]} \mathrm{Tr}((\omega^{\prime}-\omega)\wedge\omega
        _{t}) dt
        \\
	\end{array}
    \!\!
    \right\}
\end{align}
where $$
\omega_{t}=\omega+t(\omega^{\prime}-\omega)\,.
$$
\end{definition}

Our goal now is to (re-)derive these traditional formulas (Def. \ref{TraditionalFormulas}) and to lift them to {\it concordances} of flat $L_\infty$-valued forms. To recall
\begin{definition}[\bf Null-concordances of flux densities]
\label{NullConcordancesOfFluxDensities}
Given flux densities as in \eqref{TheFluxDensities}, we say that a {\it null concordance} is
\begin{equation}
  \label{NullConcordances}
	\begin{array}{c}
		\left(\hat{G}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{p}_{1}(\omega)\right) \in \Omega_{\text{dR}}^{1}\left(U_{i} \times[0,1], \mathfrak{l}_{S^{4}\sslash \mathrm{Sp}(2)} S^{7}\sslash \mathrm{Sp}(2)\right)_{ \mathrm{clsd} }
	\end{array}
\end{equation}
    such that
\begin{equation}
  \renewcommand{\arraystretch}{1.7}
    \begin{array}{l}
		\iota_{0}^{*}\left(\hat{G}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{p}_{1}(\omega)\right)
          =
        0 
        \\
		\iota_{1}^{*}\left(\hat{G}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{p}_{1}(\omega)\right)
          =
        \left(G_{4}, G_{7}, H_{3}, p_{1}(\omega)\right)\,;
    \end{array}
\end{equation}
and given a pair of these, we say that a {\it concordance-of-concordances} between them is
\begin{equation}
  \label{ConcordanceOfConcordances}
	\begin{array}{l}
		({\hat{\hat{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{p}}}_{1}(\omega, \omega^{\prime})) 
              \;\in\; 
            \Omega_{dR}^{1}(U_{i} \times \underbrace{[0,1]}_{t} \times \underbrace{[0,1]}_{s}; \mathfrak{l}_{S^{4}\sslash \mathrm{Sp}(2)}S^{7}\sslash \mathrm{Sp}(2))_{ \mathrm{clsd }}
    \end{array}
\end{equation}
such that
\begin{equation}
  \renewcommand{\arraystretch}{1.8}
  \begin{array}{l}
	\iota_{s=0}^{*}\left({\hat{\hat{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{p}}}_{1}(\omega, \omega^{\prime}) \right)
    =
    \left(\hat{G}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{p}_{1}(\omega)\right) 
    \\
	\iota^{*}_{s=1}\left({\hat{\hat{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{p}}}_{1}(\omega, \omega^{\prime})\right)
    =
    \left(\hat{G}_{4}^{\prime}, \hat{G}_{7}^{\prime}, \hat{H}_{3}^{\prime}, \hat{p}_{1}(\omega^{\prime})\right) \\
			\iota^{*}_{t=0}\left({\hat{\hat{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{p}}}_{1}(\omega, \omega^{\prime}) \right)=0 \\
			{ \iota}^{*}_{t=1}\left({\hat{\hat{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{p}}}_{1}(\omega, \omega^{\prime}) \right) = \operatorname{pr}_{U_{i}}^{*}\left(G_{4}, G_{7}, H_{3}, p_{1}(\omega)\right),
		\end{array}\\
    \end{equation}
	where 
    $$
      \mathrm{pr}_{U_{i}}: U_{i} \times[0,1]_{s} \longrightarrow U_{i}
    $$
    is projection onto the first factor.
\end{definition}    
\begin{remark}
    In the remainder of this article, we can identify $2 \mathrm{CS}(\omega)$ with $s_{3}(\omega)$, which will appear later in the expression for $\hat{p}_{1}(\omega)$. 
Also, $s_{2}(\omega, \omega')$ denotes the concordance between two Chern-Simons forms with spin connections $\omega$ and $\omega^{\prime}$, the usual trangression form  $s_{2}(\omega, \omega')$ given by 
\begin{equation}
\dd s_{2}(\omega, \omega'):= s_{3}^{\prime}- s_{3}= 2[\mathrm{CS}(\omega^{\prime})- \mathrm{CS}(\omega)]\\
=2 \int_{t\in[0,1]}\frac{d}{dt}\mathrm{CS}(\omega
_{t})dt
\end{equation}
where $\omega_{t}=\omega+ t (\omega^{\prime}-\omega)$.
Explicitly, it is given in terms of the spin connections $\omega$, $\omega^{\prime}$ as
\begin{equation}
s_{2}(\omega, \omega')=2 \int_{t\in[0,1]} \mathrm{Tr}(\omega^{\prime}-\omega)\wedge \omega_{t} dt.
\end{equation}
The form $s_{2}(\omega, \omega')$ will appear later in the expression for $\doublehat{p}_{1}(\omega, \omega')$.
\end{remark}
\begin{remark}
     In the remainder of the article, we will write  $s_{3}(\omega), s_{3}(\omega'), p_{1}(\omega), s_{2}(\omega, \omega'), \hat{p}_{1}(\omega), \hat{p}_{1}(\omega^{\prime})$, $\doublehat{p}_{1}(\omega, \omega^{\prime})$ as 
     $s_{3},s_{3}^{\prime}, p_{1}, s_{2}, \hat{p}_{1}, \hat{p}_{1}^{\prime}, \doublehat{p}_{1}$, 
     respectively and omit the arguments involving $\omega,\omega^{\prime}$ for notational brevity.

\end{remark}
\end{remark}
\begin{proposition}[\bf Gauge potentials from null concordances]:
Given null concordances \eqref{NullConcordances} the following formulas define the gauge potentials for the flux densities \eqref{TheFluxDensities}
\vspace{-2mm} 
\begin{equation}
  \label{FluxDensitiesFromNullConcordances}
  \renewcommand{\arraystretch}{1.7}		
		\begin{array}{rcl}
			2 \mathrm{CS}(\omega)
              &:=& 
            s_{3}=\int_{[0,1]}\hat{p}_{1}
            \\
			C_{3}
              &:=&
            \int_{[0,1]} \hat{G}_{4}+\tfrac{1}{4} \int_{[0,1]} \hat{p}_{1}=\int_{[0,1]} \hat{\tilde{G}}_{4}
            \\
			C_{6}
              &:=&
            \int_{[0,1]} (\hat{G}_{7}-\tfrac{1}{2}\left(\int_{[0,-]}\hat{\tilde{G}}_{4}\right)\left(\hat{\tilde{G}}_{4}-\tfrac{1}{2} \hat{p}_{1}\right))
            \\
			B_{2} &:=& \int_{[0,1]} \hat{H}_{3}
            \,.
		\end{array}
\end{equation}
\end{proposition}
Moreover, this construction is surjective, in that every traditional gauge potential arises from some null-concordance this way.
\begin{proof}
First to see that the claimed flux densities satisfy their defining differential equations, we compute as follows:
\begin{equation}
\renewcommand{\arraystretch}{1.5}
    \begin{array}{ll}
   \dd(2CS(\omega)) &=\dd s_{3}
       =\int_{[0,1]}\hat{{p_{1}}}
      \\
&= \iota^{*} _{1}\hat{{p_{1}}}-\iota^{*}_{0} \hat{{p_{1}}} -\int_{[0,1]} d \hat{{p_{1}}}
      \\
 &      =p_{1}-0-0
      \\[-2pt]
 &   =p_{1}\,.
  \end{array}
\end{equation}
Moving onto $C_{3}$ we find,
\begin{equation}
 \renewcommand{\arraystretch}{1.5}
  \begin{array}{rcl}
	\dd C_{3}
      &=& \dd \int_{[0,1]}\hat{\tilde{G_{4}}}
      \\
      &=&
      \iota^{*} _{1}\hat{\tilde{G_{4}}}-\iota^{*}_{0} \hat{\tilde{G_{4}}} -\int_{[0,1]} d \hat{\tilde{G_{4}}}
      \\
      &=& \tilde{G_{4}}-0-0
      \\[-2pt]
      &=&
      \tilde{G_{4}}\,.
  \end{array}
\end{equation}
Next, we check the expression for $C_{6}$.
\begin{equation}
   \renewcommand{\arraystretch}{1.6}
	\begin{array}{rcl}
		\dd C_{6}
        &=&
        \dd\left(\int_{[0,1]} \hat{G}_{7}-\tfrac{1}{2} \int_{[0,-]} \hat{\tilde{G}}_{4}\left(\hat{\tilde{G}}_{4}-\tfrac{1}{2} \hat{p}_{1}\right)\right)
        \\
        &=& \iota^{*}_{1}\left(\hat{G}_{7}-\tfrac{1}{2} \hat{C}_{3}\left(\hat{\tilde{G}}_{4}-\tfrac{1}{2} \hat{p}_{1}\right)\right)-0-\int_{[0,1]} d\left[\hat{G}_{7}-\tfrac{1}{2} \hat{C}_{3}\left(\hat{\tilde{G}}_{4}-\tfrac{1}{2} \hat{p}_{1}\right)\right] 
        \\
		&=&
        G_{7}-\tfrac{1}{2}{C_{3}}{}\left(\tilde{G}_{4}-\tfrac{1}{2}p_{1}\right)-0-0= G_{7}-\tfrac{1}{2}{C_{3}}{}\left(\tilde{G}_{4}-\tfrac{1}{2}p_{1}\right).
	\end{array}
\end{equation}
Next, we would like to check the equation for $B_{2}$.
\begin{equation}
  \renewcommand{\arraystretch}{1.7}
	\begin{array}{rcl}
		\dd B_{2}
        &=&
        \dd \int_{[0,1]} \hat{H}_{3}=\iota^{*}_{1} \hat{H_{3}}-\iota^{*}_{0}\hat{{H}_{3}}-\int_{[0,1]} \dd \hat{H}_{3}
        \\
        &=&
        H_{3}-0-\int_{[0,1]}\left(\hat{G}_{4}-\tfrac{1}{4} \hat{p}_{1}\right)
        \\
        &=&
        H_{3}-0-\int_{[0,1]} \hat{\tilde{G}}_{4}+\tfrac{1}{2} \int_{[0,1]} \hat{p}_{1} 
        \\
		&=&
        H_{3}-C_{3}+\tfrac{1}{2} \int_{[0,1]} \hat{p}_{1}
        \\
        &=&
        H_{3}-C_{3}+CS(\omega)\,.
	\end{array}
\end{equation}
Thus, the expressions in equation \eqref{FluxDensitiesFromNullConcordances} are all consistent.

Next, to show that this construction is surjective, we claim that for given gauge potentials $(B_2, C_3, C_6)$ the following is a null concordance that recovers these gauge potentials via \eqref{FluxDensitiesFromNullConcordances}:
\vspace{-2mm} 
\begin{equation}
  \label{NullConcordancesForGivenGaugPotentials}
  \renewcommand{\arraystretch}{1.5}
	\begin{array}{rcl}
		\hat{p}_{1}
          &=&
        t{p_{1}}+\dd t \, s_{3} 
        \\
        \hat{G}_{4}
        &=& 
        t G_{4}+\dd t\, (C_{3}-\tfrac{1}{4}s_{3}), \quad \hat{p}_{1}=t {p_{1}}+\dd t\, s_{3}
        \\
        \hat{\tilde{G}}_{4}
        &=&
			t (\left(G_{4}+\tfrac{1}{4}p_{1}\right)+\dd t\, C_{3} = t \tilde{G_{4}}+ \dd t\, C_{3}
        \\ 
        \hat{G}_{7}
          &=&
         t^{2} G_{7}+2 t\, \dd t\, C_{6}+\tfrac{1}{4}t \dd t C_{3} s_{3}
         \\
        \hat{H}_{3} &=& t H_{3}+\dd t\, B_{2}\,.
		\end{array}
        \end{equation}

We need to check 

\begin{itemize}[
  leftmargin=2cm
]
\item[(1.)] that \eqref{NullConcordancesForGivenGaugPotentials} recovers the given gauge potentials when plugged into the formulas \eqref{FluxDensitiesFromNullConcordances},

\item[(2.)] that \eqref{NullConcordancesForGivenGaugPotentials} are actually null concordances for the given flux densities.
\end{itemize}


Keeping in mind that inside the $t$-integrals, only the terms having $\dd t$ give non-zero contributions, one can check that the expressions listed above reproduce the usual forms of the gauge potentials mentioned in \eqref{FluxDensitiesFromNullConcordances}, and also the usual null concordance conditions at $t=0$ and $t=1$. So the expressions are consistent.

\smallskip


Now, we go ahead to check that these expressions satisfy the usual Bianchi identities in \eqref{TheFluxDensities}.

We start with $\hat{{G}}_{4}$,
        \begin{equation}
            \begin{array}{l}

		\dd \,\hat{G}_{4}=\dd t\, G_{4}-\dd\, t \tilde{G_{4}}+\tfrac{1}{4}\dd t \,p_{1}=0 \\

	\end{array}
\end{equation}
Next, we want to check $\hat{p}_{1}$
        \begin{equation}
            \dd\hat{p}_{1}=\dd t\, p_{1}-\dd t\, \dd s_{3}=0 \,( ds_{3}=p_{1}).
        \end{equation}
        Next, we check $\hat{\tilde{G}}_{4}$
        \begin{equation}
		\dd \hat{\tilde{G_{4}}}=\dd t\, \tilde{G}_{4}-\dd t\, \tilde{G}_{4}=0\,.
\end{equation}
Now, moving onto $\hat{H}_{3}$, we see
\begin{align}
\dd \hat{H}_{3}&=\dd t\, H_{3}+t\left(G_{4}-\tfrac{1}{4} p_{1}\right)-\dd t\left(H_{3}-C_{3}+
\tfrac{1}{2}s_{3}\right)=t\left(G_{4}-\tfrac{1}{4} p_{1}\right)+\dd t\left(C_{3}-
\tfrac{1}{2}s_{3}\right),
\\
\hat{G}_{4}-\tfrac{1}{4} \hat{p}_{1}&=t G_{4}+\dd t\left(c_{3}-\tfrac{1}{4}s_{3}\right)-\tfrac{t}{4} p_{1}-\tfrac{\dd t}{4} s_{3}=t\left(G_{4}-\tfrac{1}{4} p_{1}\right)+\dd t\left(C_{3}-\tfrac{1}{2}s_{3}\right).
        \end{align}

		\text { Thus, we recover the expected Bianchi identity } 
        \begin{equation}\dd \hat{H}_{3}=\hat{G}_{4}-\tfrac{1}{4} \hat{p}_{1}\end{equation}



	Now, $$\tilde{G}_{7}:=G_{7}-\tfrac{1}{2} C_{3}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}\right),\qquad \dd C_{6}=\tilde{G}_{7},\qquad \dd \tilde{G}_{7}=0 $$
    Also,
		\begin{equation}
		    \hat{C}_{3}=\int_{[0,t]} \hat{\tilde{G}}_{4}=\int_{[0,t]} t^{\prime}\tilde{G}_{4}+\dd t'\, C_{3}=t C_{3}\,,
            \end{equation}
            $$\iota^{*}_{0}\hat{C}_{3}=0,\iota^{*} _{1} \hat{C}_{3}=C_{3}\,,
            $$
$$d\hat{C_{3}}= \dd \,t C_{3}+ t \tilde{G_{4}}= \hat{\tilde{G}}_{4}
\,,$$
\begin{equation}
	\begin{array}{c}
		\hat{\tilde{G}}_{7}=t^{2} \tilde{G}_{7}+2 t \dd t\, C_{6} \,,\\
		C_{6}=\int_{[0,1]} \hat{\tilde{G}}_{7}\,,
        \\
        \dd C_{6}=\iota_{1}^{*} \hat{\tilde{G}}_{7}-\iota_{0}^{*} \hat{\tilde{G}}_{7}-\int_{[0,1]} \dd \hat{\tilde{G}}_{7}=\left[G_{7}-\tfrac{1}{2} C_{3}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1} \right)\right]-0-0= \tilde{G}_{7}\,, \\
	\end{array}
\end{equation}

\begin{equation}
	\begin{aligned}
		\dd \hat{\tilde{G}}_{7} & =2 t \dd t\, \tilde{G}_{7}+t^{2} \dd \tilde{G}_{7}-2 t \dd t\, \dd C_{6} \\
		& =2 t \dd t \widetilde{G}_{7}-2 t \dd t \tilde{G}_{7}+0=0\,.
	\end{aligned}
\end{equation}
Now, using the above-listed expressions, we want to get to $\hat{G}_{7}$
\begin{equation}
\renewcommand{\arraystretch}{1.5}
	\begin{array}{l}
		\hat{\tilde{G}}_{7}=t^{2} \tilde{G}_{7}+2 t \dd t\, C_{6} \\
		\hat{G}_{7}-\tfrac{1}{2} \hat{C}_{3}\left(\hat{G}_{4}-\tfrac{1}{4} \hat{p}_{1}\right)=t^{2}\left(G_{7}-\tfrac{1}{2} C_{3}\big(\tilde{G}_{4}-\tfrac{1}{2} p_{1}\big)\right)+2 t \dd t\, C_{6} \\
