		\hat{G}_{7}-\tfrac{t^{2}}{2} C_{3}\left(G_{4}-\tfrac{1}{4} p_{1}\right)-\tfrac{1}{4}t \dd t C_{3} s_{3}=t^{2} G_{7}-\tfrac{t^{2}}{2} C_{3}\left(G_{4}-\tfrac{1}{4} p_{1}\right)+2 t \dd t\, C_{6} \\
		\hat{G}_{7}=t^{2} G_{7}+2 t \dd t\, C_{6}+\tfrac{1}{4} t \dd t\, C_{3} s_{3}
	\end{array}
