    \dd\hat{G}_{7}&= \tfrac{1}{2}t^{2} (G_{4}+\tfrac{1}{4}p_{1})(G_{4}-\tfrac{1}{4}p_{1})+ t \dd \,t C_{3}(G_{4}-\tfrac{1}{4}p_{1}) + \tfrac{1}{4}t\dd t\, C_{3} p_{1}- \tfrac{1}{4}t \dd t\,(G_{4}+\tfrac{1}{4}p_{1}) s_{3} 
