		{\hat{\hat{G}}}_{7} =&  \; {\hat{\hat{\tilde{G}}}}_{7}+\tfrac{1}{2}{\hat{\hat{C}}}_{3}\left(\hat{\hat{G}}_{4}-\tfrac{1}{4} \hat{\hat{p}}_{1}\right) \\
		=& \; t^{2} G_{7}+2 t\, \dd t C_{6}+ \tfrac{1}{4} t\, \dd \,t C_{3}s_{3}+ 2 s t\, \dd t\left(C_{6}^{\prime}-C_{6}\right)-2t \, \dd s\, \dd t\,\left(C_{5}+\tfrac{1}{2} C_{2} C_{3}\right) \\
		&-  \tfrac{1}{4}s t \, \dd t C_{3}\left(s_{3}-s_{3}^{\prime}\right)+\tfrac{1}{4}s t\, \dd t\left(C_{3}^{\prime}-C_{3}\right) s_{3}-\tfrac{1}{4} s^{2} t\, \dd t\,\left(C_{3}^{\prime}-C_{3}\right)\left(s_{3}-s_{3}^{\prime}\right) \\
		& +\tfrac{1}{4}t\, \dd s\,\dd t\left(C_{3} s_{2}-C_{2} s_{3}\right)+\tfrac{ 1}{4}st\,\dd s\, \dd t\left(C_{3}^{\prime}-C_{3}\right) s_{2}-\tfrac{1}{4}s\, t\, \dd s\, \dd t C_{2}\left(s_{3}^{\prime}-s_{3}\right).
	\end{aligned}
\end{equation}
Finally, we want to check its Bianchi identity.
 \begin{equation}
\renewcommand{\arraystretch}{1.6}
     \begin{array}{ll}
         \dd \hat{\hat{{G}}}_{7}&= \frac{1}{2}t^{2} (G_{4}+\tfrac{1}{4}p_{1})(G_{4}-\tfrac{1}{4}p_{1})+ t\, \dd t\left( C_{3} G_{4} - \tfrac{1}{4}s_{3} (G_{4}+ \tfrac{1}{4}p_{1})\right) 
         \\ 
         &\;\;\;+st\, \dd t \left((C^{\prime}_{3}-C_{3})G_{4} + \tfrac{1}{4} (G_{4}+\tfrac{1}{4}p_{1}) (s_{3}- s^{\prime}_{3})\right) + t\, \dd s\, \dd t\, (-C_{2}G_{4}+ \tfrac{1}{4}s_{2} (G_{4}+\tfrac{1}{4}p_{1}))\\
         &= \tfrac{1}{2}\hat{\hat{\tilde{G}}}_{4}(\hat{\hat{\tilde{G}}}_{4}-\tfrac{1}{2}\hat{\hat{p}}_{1}).
         \end{array}
 \end{equation} 

 \vspace{-5mm} 
\end{proof}

%   So, every relation seems consistent with our expectations.

\noindent  \textbf{Note}: If we set $p_{1}, s_{3}, s_{2} = 0$, we will exactly reproduce the results known earlier in \cite[\S 2.1.4]{GSS24-SuGra}\cite[\S 4.1]{GSS24-FluxOnM5}.
\begin{remark}
We should keep in mind that $\hat{\hat{\tilde{G}}}_{7}$ is {\it not} a concordance of concordance between the pair $\hat{\tilde{G}}_{7}$ and $\hat{\tilde{G}}^{\prime}_{7}$ for the same $\tilde{G}_{7}$, as it contains the potential term $C_{3}$ which is {\it not} topological. We have done the calculations by just defining something to be like that, to derive the explicit expressions for $\hat{G}_{7}$ and $\hat{\hat{G}}_{7}$. Alternatively, we can omit together $\tilde{G}_{7}$, it's hatted and doublehatted counterparts, and directly write down the expressions for  $\hat{G}_{7}$ and $\hat{\hat{G}}_{7}$ and show them to satisfy the required equations, as checked explicitly here.

\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{In Twistorial Cohomotopy}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


 Now, Hypothesis H {\it generalizes} to heterotic M-Theory where Cohomotopy is enhanced to twistorial Cohomotopy (constructed in \cite[\S 2.45]{FSS23-Char}, \cite[\S 2.14]{FSS22-GS}). Here the target $\infty$-stack is represented by $\mathbb{C}P^{3}\sslash\mathrm{Sp}(2)$ instead of $S^{4}\sslash\mathrm{Sp}(2)$, and we have the Borel equivariantized twistor fibration $t_{\mathbb{H}}\sslash\mathrm{Sp}(2):\mathbb{C}P^{3}\sslash\mathrm{Sp}(2)\longrightarrow{S^{4}}\sslash\mathrm{Sp}(2)$.

Following the above, we define {\it twistorial Cohomotopy} 
\begin{equation}
    \zeta^{\tau}(X):=\mathrm{H}^{\tau}(X; \mathbb{C}P^{3})
    \end{equation}
    where we have the {\it twist} $\tau:X\longrightarrow{\mathrm{BSp}}(2)$.

\begin{definition}[\bf Flux densities]
In the case of twistorial cohomotopy, we are concerned with {\it flux densities} of the following form (\cite[\S 2.14]{FSS22-GS}):
\begin{equation}
\renewcommand{\arraystretch}{1.3}
\label{Twistorial flux densities}
	\Omega_{d R}^{1}\left(-; \mathfrak{l}_{S^{4}\sslash \mathrm{Sp}{(2)}} \mathrm{\mathbb{C}P}^{3}\sslash \mathrm{Sp}(2)\right)_{\mathrm{clsd}}:=\left\{\begin{array}{l|l}
		F_{2} & \dd F_{2}=0 \\H_{3} & \dd H_{3}=\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)-F_{2}^{2} \\
		G_{7} & \dd G_{7}=\tfrac{1}{2} \tilde{G}_{4}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)\right) \\
		\tilde{G}_{4} & \dd \tilde{G}_{4}=0 \\
		\tfrac{1}{2} p_{1}(\omega) & \dd\left(\tfrac{1}{2} p_{1}(\omega)\right)=0
	\end{array}\right\}
\end{equation}
\end{definition}

\begin{definition}[\bf Gauge potentials and gauge transformations]
Given the flux densities \eqref{Twistorial flux densities} on some $U_{i}$, we have the following traditional choice of {\it gauge potentials}
\begin{equation}
\renewcommand{\arraystretch}{1.3}
\label{Twistorial gauge potentials}
	\left\{\begin{array}{l|l}
		C_{3} \in \Omega_{dR}^{3}\left(U_{i}\right) & \dd C_{3}=\tilde{G}_{4} \\
		C_{6} \in \Omega_{dR}^{6}\left(U_{i}\right) & \dd C_{6}=G_{7}-\tfrac{1}{2} C_{3}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)\right) \\
		B_{2} \in \Omega_{dR}^{2}\left(U_{i}\right) & \dd B_{2}=H_{3}-C_{3}+ \mathrm{CS}(\omega) + A_{1} F_{2}\\
        A_{1} \in \Omega_{dR}^{1}\left(U_{i}\right) & \dd A_{1}= F_{2}\\
    \end{array}\right\}
\end{equation}
and the corresponding {\it gauge transformations} between the gauge potentials
\begin{equation}
\label{Twistorial gauge tranfomrations}
\renewcommand{\arraystretch}{1.3}
\begin{aligned}
&\begin{array}{c}
\left(C_{3}, C_{6}, B_{2}, A_{1}\right) \sim \left(C_{3}^{\prime}, C_{6}^{\prime}, B_{2}^{\prime}, A_{1}^{\prime}\right) \\
\phantom{\left(C_{3}, C_{6}, B_{2}, A_{1}\right)}\vcenter{\hbox{$\Updownarrow$}}\phantom{\left(C_{3}^{\prime}, C_{6}^{\prime}, B_{2}^{\prime}, A_{1}^{\prime}\right)}
\end{array}
\\[1ex]
&\exists \left\{
\begin{array}{l|l}
C_{2} \in \Omega_{dR}^{2}\left(U_{i}\right) & \dd C_{2} = C_{3}^{\prime} - C_{3} \\
C_{5} \in \Omega_{dR}^{5}\left(U_{i}\right) & \dd C_{5} = C_{6}^{\prime} - C_{6} - \tfrac{1}{2} C_{3}^{\prime} C_{3} - \tfrac{1}{4}C_{2}{p_{1}}(\omega) \\
B_{1} \in \Omega_{dR}^{1}\left(U_{i}\right) & \dd B_{1} = B_{2}^{\prime} - B_{2} + C_{2} - \int dt\, \mathrm{Tr}(\omega^{\prime} - \omega) \wedge \omega_{t} - A_{0} F_{2} \\
A_{0} \in \Omega_{dR}^{0}\left(U_{i}\right) & \dd A_{0} = A_{1}^{\prime} - A_{1}
\end{array}
\right\}.
\end{aligned}
\end{equation}

\end{definition}
\begin{definition}[\bf Null concordances]
Given the flux densities in \eqref{Twistorial flux densities}, we say that a {\it null concordance} is
\begin{equation}
	\begin{array}{c}
		\left(\hat{\tilde{{G}}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}(\omega)\right) \in \Omega_{\text {dR}}^{1}\left(U_{i} \times[0,1], \mathfrak{l}_{S^{4}\sslash \mathrm{Sp}(2)} \mathrm{CP}^{3}\sslash \mathrm{Sp}(2)\right)_{ \mathrm{clsd} }
        \end{array}
        \end{equation}
        such that
        \begin{equation}
        \label{Twistorial Boundary conditions}
        \renewcommand{\arraystretch}{1.3}
        \begin{array}{l}
		\iota_{0}^{*}\left(\hat{\tilde{G}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}(\omega)\right)=0 \\
		\iota_{1}{ }^{*}\left(\hat{\tilde{G}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}(\omega)\right)=\left(\tilde{G}_{4}, G_{7}, H_{3}, F_{2}, p_{1}(\omega)\right)
	\end{array}
\end{equation}
and a {\it null} concordance of concordances between a pair of them is given by
\begin{equation}
	\begin{array}{l}
			\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}(\omega, \omega')\right) \in \Omega_{dR}^{1}(U_{i} \times \underbrace{[0,1]}_{t} \times \underbrace{[0,1]}_{s} ; \mathfrak{l}_{S^{4}\sslash \mathrm{Sp}(2)}\mathrm{CP}^{3}\sslash \mathrm{Sp}(2))_{\mathrm{ clsd} }
            \end{array}
            \end{equation}
            such that
            \begin{equation}
            \label{Twistorial higher boundary conditions}
            \renewcommand{\arraystretch}{2.2}
            \begin{array}{l}
\iota_{s=0}^{*}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right)=\left(\hat{\tilde{G}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}\right) \\
		\iota^{*}_{s=1}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right)=\left(\hat{\tilde{G}}_{4}^{\prime}, \hat{G}_{7}^{\prime}, \hat{H}_{3}^{\prime}, \hat{F}_{2}^{\prime},\hat{p}_{1}^{\prime}\right) \\
			\iota^{*}_{t=0}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right)=0 \\
			{ \iota}^{*}_{t=1}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right) = \operatorname{pr}_{U_{i}}^{*}\left(\tilde{G}_{4}, G_{7}, H_{3}, F_{2}, p_{1}\right)
		\end{array}\\
    \end{equation}
	where $$pr_{U_{i}}: U_{i} \times[0,1]_{S} \longrightarrow U_{i}$$
    \end{definition}

Similarly to the last section:

\begin{proposition}[\bf Gauge potentials from null concordances]
Every traditional gauge potential in twistorial cohomotopy arises from the null concordances in the following way:
\begin{equation}
\label{Twistorial gauge potentials from null concordances}
\renewcommand{\arraystretch}{1.5}
	\begin{array}{l}

		\begin{array}{l}
			2\mathrm{CS}(\omega)= s_{3}=\int_{[0,1]}\hat{p}_{1}\\

			C_{3}=\int_{[0,1]} \hat{G}_{4}+\tfrac{1}{4} \int_{[0,1]} \hat{p}_{1}=\int_{[0,1]} \hat{\tilde{G}}_{4}.\\
			C_{6}=\int_{[0,1]} \left(\hat{G}_{7}-\tfrac{1}{2}\left(\int_{[0,-]}\hat{\tilde{G}}_{4}\right)\left(\hat{\tilde{G}}_{4}-\tfrac{1}{2} \hat{p}_{1}\right)\right) .\\
			B_{2}=\int_{[0,1]} \hat{H}_{3} \\
            A_{1}=\int_{[0,1]} \hat{F}_{2}\,.
		\end{array}
	\end{array}
\end{equation}
\end{proposition}
\begin{proof}
We show the above expressions for the gauge potentials satisfy the expected Bianchi identities as mentioned in \eqref{Twistorial gauge potentials}.

We start with $B_{2}$
\begin{equation}
\renewcommand{\arraystretch}{1.5}
	\begin{array}{ll}
		\dd B_{2}&=\dd \int_{[0,1]} \hat{H}_{3}=\iota^{*}_{1} \hat{H_{3}}-\iota^{*}_{0}\hat{{H}_{3}}-\int_{[0,1]} \dd \hat{H}_{3}=H_{3}-0-\int_{[0,1]}\left(\hat{G}_{4}-\frac{1}{4} \hat{p}_{1}- \hat{F}_{2}^{2}\right)
        \\
        &=H_{3}-0-\int_{[0,1]} \hat{\tilde{G}}_{4}+\frac{1}{2} \int_{[0,1]} \hat{p}_{1}+ \int_{[0,1]}\hat{F}_{2}^{2}
        \\
	&	=H_{3}-C_{3}+\frac{1}{2} \int_{[0.1]} \hat{p}_{1} + A_{1} F_{2}\\
       & =H_{3}-C_{3}+\mathrm{CS}(\omega) + A_{1} F_{2}\,.
	\end{array}
    \end{equation}
    Then, we want to check the $A_{1}$ potential
    \begin{equation}
    \dd A_{1}=\dd \int_{[0,1]} \hat{F}_{2}=\iota^{*}_{1} \hat{F_{2}}-\iota^{*}_{0}\hat{{F}_{2}}-\int_{[0,1]} \dd \hat{F}_{2}=F_{2}-0-0= F_{2}\,.
    \end{equation}
So the above relations satisfy the usual Bianchi identities.
\end{proof}


 \begin{proposition}[\bf Surjections]
    Let us turn to the surjections from the null concordances to the gauge potentials explicitly
    \vspace{-2mm} 
\begin{equation}
\label{Twistorial surjections}
\renewcommand{\arraystretch}{1.4}
	\begin{array}{l}
		\hat{p}_{1}=t{p_{1}}+\dd t\, s_{3} \\
        \hat{\tilde{G}}_{4}=
			t (\left(G_{4}+\tfrac{1}{4}p_{1}\right)+\dd t\, C_{3} = t \tilde{G_{4}}+ \dd t\, C_{3}\\ \hat{G}_{7}=t^{2} G_{7}+2 t \dd t\, C_{6}+\tfrac{1}{4}t \dd t C_{3} s_{3}\\
            \hat{H}_{3}=t H_{3}+\dd t\, B_{2}   + t(1-t) A_{1} F_{2}\\
		\hat{F}_{2}=t F_{2}+ \dd t \,A_{1}\,.	
		\end{array}\\
        \end{equation}
\end{proposition}

\begin{proof}
We immediately see that they are consistent when plugged in \eqref{Twistorial gauge potentials from null concordances} and they satisfy the usual null concordance conditions at $t=0,1$.

We want to check whether these relations satisfy the Bianchi identities in \eqref{Twistorial gauge potentials}.
We start with $\hat{H}_{3}$.
        \begin{equation}
        \hspace{-5mm}
        \renewcommand{\arraystretch}{1.4}
        \begin{array}{ll}
\dd \hat{H}_{3}&=\dd t\, H_{3}+t\left(G_{4}-\tfrac{1}{4} p_{1}- F_{2}^{2}\right)-\dd t\left(H_{3}-C_{3}+\tfrac{1}{2}s_{3}+ A_{1} F_{2}\right) + t(1-t) F_{2}^{2} + (1-2t)\dd t A_{1} F_{2}\\
&=t\left(G_{4}-\tfrac{1}{4} p_{1}- F_{2}^{2}\right)+\dd t\left(C_{3}-\tfrac{1}{2}s_{3}- A_{1} F_{2}\right)  -2t \dd t A_{1} F_{2} -t^{2} F_{2}^{2}\\ 
&= t\left(G_{4}-\tfrac{1}{4} p_{1}\right)+\dd t\left(C_{3}-\tfrac{1}{2}s_{3}\right) -2t \dd t  A_{1} F_{2}  -t^{2} F_{2}^{2}
\\ 
&= \hat{\tilde{G}}_{4}- \tfrac{1}{2}\hat{p}_{1}-\hat{F}_{2}^{2}\,.
\end{array}
\end{equation}
Also, we find $$\hat{F}_{2}^{2}= (tF_{1}+ \dd t\, A_{1})(tF_{1}+ \dd t\, A_{1})= 2t\dd t\, A_{1} F_{2}+ t^{2} F_{2}^{2}\,.
$$
We now want to check for $\hat{F}_{2}$
\begin{equation}
\dd\hat{F}_{2}= \dd(tF_{2}+\dd t\, A_{1})= \dd t\, F_{2}+0 - \dd t\, F_{2}=0.
\end{equation}
So the relations are consistent.
\end{proof}


Let us turn to the concordance of concordances.

\begin{proposition}[\bf Gauge equivalences from null-concordance of concordances]
In twistorial cohomotopy, the null concordances of concordances surject onto usual gauge transformations between the usual gauge potentials
\begin{equation}
\label{Twistorial gauge equivalnes from null concordances of concordances}
\renewcommand{\arraystretch}{1.5}
\begin{array}{l}
	C_{2}=\int_{s \in{[0,1]}} \int_{t \in[0,1)} \hat{\hat{\tilde{G}}}_{4}\\ B_{1}=\int_{s \in{[0,1]}} \int_{t \in{[0,1]}} {\hat{\hat{H}}}_{3}\\C_{5}=\int_{s \in{[0,1]}}\int_{ t \in{[0,1]}} (\hat{\hat{{G}}}_{7}-\tfrac{1}{2}\hat{\hat{C}}_{3}(\hat{\hat{\tilde{G}}}_{4}-\tfrac{1}{2}\hat{\hat{p}}_{1}))-\tfrac{1}{2} C_{2} C_{3}\\ A_{0}= \int_{s \in{[0,1]}} \int_{t \in[0,1)} \hat{\hat{F}}_{2}\\
    s_{2}= \int_{s \in{[0,1]}} \int_{t \in[0,1)} \hat{\hat{p}}_{1}\,.
    \end{array}
\end{equation}
\end{proposition}
\begin{proof}
We want to check whether these relations satisfy the Bianchi identities in \eqref{Twistorial gauge tranfomrations}.

Firstly, we want to check $B_{1}$.
 \begin{equation}
\renewcommand{\arraystretch}{1.8}
  \begin{array} {l}  
 \dd B_{1}=\dd \int_{s\in{[0,1]}} \int_{t\in{[0,1]}}{\hat{\hat{H}}}_{3}=\iota^{*}_{s=1}\int_{t \in{[0,1]}} {\hat{\hat{H}}}_{3}-\iota^{*}_{s=0} \int_{t \in{[0,1]}}{\hat{\hat{H}}}_{3}-\int_{s \in{[0,1]}} \dd \int_{t \in{[0,1]}} {\hat{\hat{H}}}_{3} \\

	=\int_{t\in[0,1]} \iota^{*}_{s=1} \hat{\hat{H}}_{3}-\int_{t \in[0,1]} \iota^{*}_{s=0} {\hat{\hat{H}}}_{3}-\int_{s \in[0,1]}(\iota^{*}_{t=1} \hat{\hat{H}}_{3}-\iota^{*}_{t=0} \hat{\hat{H}}_{3})+\int_{s \in[0,1]}\int_{ t\in{[0,1]}} \dd {\hat{\hat{H}}}_{3} \\
    =\int_{t\in[0,1]}\hat{H^{\prime}}_{3}- \int_{t\in[0,1]}\hat{H}_{3}-0+\int_{s\in[0,1]}\int_{t\in[0,1]}\hat{\hat{\tilde{G}}}_{4}-\tfrac{1}{2}\int_{s\in[0,1]}\int_{t\in[0,1]}\hat{\hat{p}}_{1}-\int_{s\in[0,1]}\int_{t\in[0,1]}\hat{\hat{F}}_{2}^{2} \\
    =B_{2}^{\prime}-B_{2}+C_{2}-\tfrac{1}{2}\int_{s\in[0,1]}\int_{t\in[0,1]}\hat{\hat{p}}_{1}- A_{0}F_{2}\\
    =B_{2}^{\prime}-B_{2}+C_{2}-\tfrac{1}{2}s_{2}- A_{0}F_{2}\,.
    \end{array}
    \end{equation}
    Next, we want to check $A_{0}$.
    \begin{equation}
\renewcommand{\arraystretch}{1.7}
    \begin{array}{ll}
     \dd A_{0}=\dd \int_{s\in{[0,1]}} \int_{t\in{[0,1]}}{\hat{\hat{F}}}_{2}=\iota^{*}_{s=1}\int_{t \in{[0,1]}} {\hat{\hat{F}}}_{2}-\iota^{*}_{s=0} \int_{t \in{[0,1]}}{\hat{\hat{F}}}_{2}-\int_{s \in{[0,1]}} \dd \int_{t \in{[0,1]}} {\hat{\hat{F}}}_{2}\\
     =\int_{t\in[0,1]} \iota^{*}_{s=1} \hat{\hat{F}}_{2}-\int_{t \in[0,1]} \iota^{*}_{s=0} \hat{\hat{F}}_{2}-\int_{s \in[0,1]}\left(\iota^{*}_{t=1} \hat{\hat{F}}_{2}-\iota^{*}_{t=0} \hat{\hat{F}}_{2}\right)+\int_{s \in[0,1]}\int_{ t\in[0,1]} \dd {\hat{\hat{F}}}_{2} \\
    =\int_{t\in[0,1]}\hat{F^{\prime}}_{2}- \int_{t\in[0,1]}\hat{F_{2}}-\int_{s\in{[0,1]}}\hat{F}_{2}+ \int_{s\in{[0,1]}} \int_{t\in{[0,1]}}{\dd\hat{\hat{F}}}_{2}\\
    =A_{1}^{\prime}-A_{1}\,.
    \end{array}
    \end{equation}
    So they are consistent with our expectations.
    \end{proof}

    Let us now turn to the surjections from the  null concordance of concordances to the gauge transformations between the gauge potentials in twistorial cohomotopy explicitly.

    \begin{proposition}[\bf Surjections] The surjections are given by setting:
    \begin{equation}
    \label{Twistorial higher surjections}
\renewcommand{\arraystretch}{1.5}
    \begin{array}{ll}
    \hat{\hat{p}}_{1}&=t p_{1}+\dd t s_{3}+s\dd t\left(s_{3}^{\prime}-s_{3}\right)-\dd s\, \dd t\, s_{2},
    \\
        {\hat{\hat{\tilde{G}}}}_{4} &=t{\tilde{G}_{4}}+\dd t \,C_{3}+s \dd t\left(C_{3}^{\prime}-C_{3}\right)-\dd s\,\dd t\, C_{2},
        \\
        {\hat{\hat{G}}}_{7}
		&= t^{2} G_{7}+2 t \dd t\, C_{6}+ \tfrac{1}{4} t\dd t\, C_{3}s_{3}+ 2 s\, t\, \dd t \left(C_{6}^{\prime}-C_{6}\right)-2 t\, \dd s\, \dd t\left(C_{5}+\tfrac{1}{2} C_{2}, C_{3}\right) 
        \\
		&-  \tfrac{1}{4}s t\,\,\dd t C_{3}\left(s_{3}-s_{3}^{\prime}\right)+\tfrac{1}{4}s \,t\, \dd t\left(C_{3}^{\prime}-C_{3}\right) s_{3}-\tfrac{1}{4} s^{2} t \dd t\left(C_{3}^{\prime}-C_{3}\right)\left(s_{3}-s_{3}^{\prime}\right) 
        \\
		& +\tfrac{1}{4}t\, \dd s\, \dd t(\left(C_{3} s_{2}-C_{2} s_{3}\right)+\tfrac{1}{4} st \dd s\, \dd t\left(C_{3}^{\prime}-C_{3}\right) s_{2}-\tfrac{1}{4}s t\, \dd s\, \dd t C_{2}\left(s_{3}^{\prime}-s_{3}\right),
         \\[4pt]
    \hat{\hat{H}}_{3}&= t H_{3}+ \dd t\, B_{2} + t(1-t) A_{1} F_{2}
    + s\dd t\, (B_{2}^{\prime}-B_{2})\\
    &+ s t (1-t) (A_{1}^{\prime}- A_{1}) F_{2} + \dd s\, (t-t^2) A_{0} F_{2}- \dd s\, \dd t\, B_{1},
    \\[3pt]
   \hat{\hat{F}}_{2}&= tF_{2}+ \dd t A_{1} + s\dd t (A_{1}^{\prime}-A_{1})- \dd s\, \dd t\, A_{0}\,.
   \end{array}
    \end{equation}
    \end{proposition}

    \begin{proof}
    We can see that \eqref{Twistorial gauge equivalnes from null concordances of concordances} is satisfied and also the usual conditions for null concordance of concordances at $s=0,1$ and $t=0,1$.

    Similarly, we can compute 
    \begin{equation}
        \hat{\hat{F}}_{2}^{2}=t^{2} F_{2}^{2} + 2t \dd t A_{1} F_{2}+ 2 st \dd t (A_{1}^{\prime}-A_{1})F_{2}- 2 t \dd s\, \dd tA_{0} F_{2}\,.
\end{equation}
Let us check these equations to be consistent with \eqref{Twistorial gauge tranfomrations}.
We want to start with
\begin{equation}
\begin{array}{l}
\dd\hat{\hat{F}}_{2}= \dd t F_{2} -\dd t F_{2} + \dd s\, \dd t (A_{1}^{\prime}-A_{1})+0-\dd s\, \dd t (A_{1}^{\prime}-A_{1})=0.
\end{array}
\end{equation}
    Now, we want to see 
\begin{equation}
\renewcommand{\arraystretch}{1.4}
\begin{array}{l}
   \dd\hat{\hat{H}}_{3}= \dd t\, H_{3}+ t (G_{4}-\tfrac{1}{4}p_{1}- F_{2}^{2}) -\dd t\, (H_{3}-C_{3}+\tfrac{1}{2} s_{3} + A_{1}F_{2}) + t(1-t) F_{2}^{2} + (1-2t)\dd \,t A_{1}F_{2}\\- \dd s\, \dd t (B_{2}^{\prime}-B_{2}+C_{2}-\tfrac{1}{2}s_{2}-A_{0}F_{2})+ \dd s\, \dd t \,(B_{2}^{\prime}-B_{2}) -s \dd t (-C_{3}^{\prime}+\tfrac{1}{2}s_{3}^{\prime}+A_{1}^{\prime}F_{2}+C_{3} - \tfrac{1}{2}s_{3}- A_{1}F_{2})\\ + \dd s t(1-t) (A_{1}^{\prime}-A_{1})F_{2}+ s(1-2t)\dd t\, (A_{1}^{\prime}-A_{1})F_{2} -ds (1-2t)\dd t\, A_{0}F_{2}- \dd s\, t(1-t) (A_{1}^{\prime}-A_{1})F_{2}
   \\[5pt]
    = (t \tilde{G}_{4}+\dd t\, C_{3}+s \dd t\,\left(C_{3}^{\prime}-C_{3}\right)-\dd s \dd\, t C_{2} )- \tfrac{1}{2}(t p_{1}+\dd t s_{3}+s \dd t\,\left(s_{3}^{\prime}-s_{3}\right)-\dd s \dd t \,s_{2})\\- (t^{2} F_{2}^{2} + 2t \dd t\, A_{1} F_{2}+ 2 st\, \dd t\, (A_{1}^{\prime}-A_{1})F_{2}- 2 t \dd s\, \dd t\,A_{0} F_{2})
    \\[5pt]
    =\hat{\hat{\tilde{G}}}_{4}-\tfrac{1}{2}\hat{\hat{p}}_{1}
-\hat{\hat{F}}_{2}^{2}
\end{array}
    \end{equation}
as expected from the Bianchi identities.
\end{proof}
\begin{remark}
In this section on twistorial cohomotopy, we have only proved the results that new or are different from the tangentially twisted case; the ones not proven here follow the same results from the last section on tangentially twisted gauge potentials.
\end{remark}
\begin{remark}
The Borel-equivariantized quarternionic Hopf fibration $$h_{\mathbb{H}}\sslash \mathrm{Sp}(2):S^{7}\sslash\mathrm{Sp}(2)\longrightarrow{S^{4}}\sslash\mathrm{Sp}(2)$$ factorizes through the 7d Borel-equivariantized complex Hopf fibration $$h_{\mathbb{C}}\sslash\mathrm{Sp}(2):S^{7}\sslash\mathrm{Sp}(2)\rightarrow{\mathbb{C}P^{3}}\sslash\mathrm{Sp}(2)$$ and the Borel-equivariantized twistor fibration 
$$
t_{\mathbb{H}}\sslash\mathrm{Sp}(2):{\mathbb{C}P^{3}}\sslash\mathrm{Sp}(2)\longrightarrow{S^{4}}\sslash\mathrm{Sp}(2).
$$
    If we add the 7d Borel-equivariantized complex Hopf fibration $$h_{\mathbb{C}}\sslash\mathrm{Sp}(2):S^{7}\sslash\mathrm{Sp}(2)\rightarrow{\mathbb{C}P^{3}}\sslash\mathrm{Sp}(2)$$
    into the story then we have one more generator (on top of the twistorial cohomotopy fluxes) corresponding to the flux \cite[\S 2.14]{FSS22-GS}
    \begin{equation}
   \begin{array}{l}
       ({h}_{1},...)\in \Omega^{1}_{\mathrm{dR}}(-;\mathfrak{l}_{\mathbb{C}P^{3}\sslash\mathrm{Sp(2)}_{S^{4}\sslash\mathrm{Sp(2)}}}(S^{7}\sslash\mathrm{Sp(2)))}_{\mathrm{clsd}}
   \end{array}    
   \end{equation}
   where the dots denote the fluxes already mentioned in \eqref{Twistorial flux densities}.

   Thus on top of the other fluxes, we have

    \begin{equation}
    \label{Extra Flux}
        h_{1}\in \Omega^{1}_{\mathrm{dR}}(U_{i}), \hspace{0.2cm} \dd h_{1}=F_{2}
    \end{equation}
    and the corresponding gauge potential (on top of \eqref{Twistorial gauge potentials}) to be 
    \begin{equation}
    \label{Extra gauge potential}
\phi\in\Omega^{0}_{\mathrm{dR}}(U_{i}), \hspace{0.2cm} \dd\phi= h_{1}-A_{1}\,.
    \end{equation}
   The corresponding null concordance is
   \begin{equation}
   \begin{array}{l}
       (\hat{h}_{1},...)\in \Omega^{1}_{\mathrm{dR}}({U_{i}\times[0,1];\mathfrak{l}_{\mathbb{C}P^{3}\sslash\mathrm{Sp(2)}_{S^{4}\sslash\mathrm{Sp(2)}}}(S^{7}\sslash\mathrm{Sp(2))}})_{\mathrm{clsd}};\qquad
       \iota^{*}_{0}\hat{h}_{1}= 0, \hspace{0.2cm}\iota^{*}_{1}\hat{h}_{1}= h_{1}
   \end{array}    
   \end{equation}
   where the dots denote the null concordances already discussed earlier. There is a surjection from the null concordance $\hat{h}_{1}$ to the usual gauge potential $\phi$, given by
   \begin{equation}
       \phi= \int_{t\in[0,1]}\hat{h}_{1}\,.
   \end{equation}
   and we check its consistency.
   \begin{equation}
   \renewcommand{\arraystretch}{1.5}
   \begin{array}{ll}
       \dd\phi&= \dd \int_{[0,1]} \hat{h}_{1}
       \\
       &=\iota^{*}_{1} \hat{h}_{1}-\iota^{*}_{0}\hat{{h}}_{1}-\int_{[0,1]} \dd \hat{h}_{1}=h_{1}-0-\int_{[0,1]}  \hat{F}_{2}= h_{1}- A_{1}\,.
       \end{array}
   \end{equation}
   Thus, it is consistent with the Bianchi identity \eqref{Extra gauge potential}.   We now give the explicit form of the surjection  from the null concordance $\hat{h}_{1}$ to the usual gauge potential $\phi$ to be
   \begin{equation}
       \hat{h}_{1}= t^{2}h_{1}+2t\dd t \, \phi + t(1-t)A_{1}\,.
   \end{equation}
   We can easily check the expected conditions at t=0,1 for this null concordance.

   Also, we can calculate 
   \begin{equation}
      \dd\hat{h}_{1}= t F_{2} + \dd t\, A_{1} = \hat{F}_{2}
   \end{equation}
   which is the expected Bianchi identity \eqref{Extra Flux}.

   For the null-concordance of concordances, it's trivial for the $h_{1}$ flux, as one can convince oneself easily due to the absence of a `-1-form'.


\end{remark}

\section{Gauge potentials on M5-probes of 11D SuGra in Equivariant Twistorial cohomotopy}
Now, we want to take a step further and place the M5 brane on an orbifold. We will be interested in the case of $\mathrm{Sp}(1)$ parametrized $\mathbb{Z}_{2}$-equivariant twistorial cohomotopy, as these two commute with each other as subgroups of $\mathrm{Sp}(2)$. The particular choice is discussed in \cite[p.7]{SS20-Equitwistorial}.

\begin{definition}[\bf Flux densities] In the case of equivariant twistorial cohomotopy \cite[\S 2.48]{SS20-Equitwistorial}, we are concerned with {\it flux densities} of the following form (\cite[\S 1.1]{SS20-Equitwistorial}):
\begin{equation} 
\begin{aligned}
\label{Equitwistorial flux densities}
\hspace{-3mm}
	\Omega_{\rm d R}^{1}
    \left(\! \orbisingular X\sslash{\mathbb{Z}_{2}}\,; \; \mathfrak{l}_{\orbisingular} (S^{4}\sslash{\mathbb{Z}_{2})\sslash \mathrm{Sp}{(1)}} 
    \orbisingular (\mathrm{\mathbb{C}P}^{3}\sslash{\mathbb{Z}}_{2})\sslash \mathrm{Sp}(1)\right)_{\mathrm{clsd}}
   & :=\left\{\!
    \begin{array}{l|l}
		F_{2} & \dd F_{2}=0  \\H_{3} & \dd H_{3}=\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)-F_{2}^{2} \\
		G_{7} & \dd G_{7}=\tfrac{1}{2} \tilde{G}_{4}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)\right) \\
		\tilde{G_{4}} & \dd \tilde{G_{4}}=0 \\
        \tfrac{1}{4} p_{1}(\omega) & \dd \left(\tfrac{1}{4} p_{1}(\omega)\right)=0\\
	\end{array}
    \!\!\!\right\}
    \\
   & \rightarrow
    \left\{\begin{array}{l|l}
		F_{2} & \dd F_{2}|_{X^{\mathbb{Z}_{2}}}=0  \\H_{3} & \dd H_{3}|_{X^{\mathbb{Z}_{2}}}=-\frac{1}{2} p_{1}(\omega)-F_{2}^{2} \\
		G_{7} &  G_{7}|_{X^{\mathbb{Z}_{2}}}=0 \\
		\tilde{G_{4}} &  \tilde{G_{4}}|_{X^{\mathbb{Z}_{2}}}=0 \\
        \tfrac{1}{4} p_{1}(\omega) & \dd \left(\tfrac{1}{4} p_{1}(\omega)\right)|_{X^{\mathbb{Z}_{2}}}= 0\\
	\end{array}
    \right\}
    \end{aligned}
    \end{equation}

    \medskip 
\noindent where the fluxes in the bulk $\mathrm{X}^{11}$ correspond to the first blob, and the blob below it corresponds to the fluxes along the $\mathbb{Z}_{2}$-fixed locus $\mathrm{X}^{\mathbb{Z}_{2}}$.
    In what follows below, we will denote open charts on the bulk $\mathrm{X}^{11}$ by $\mathrm{U}_{i}$, and open charts on the fixed locus $\mathrm{X}^{\mathbb{Z}_{2}}$ by $\mathrm{U}_{i}^{\mathbb{Z}_{2}}$.
\end{definition}

\begin{definition}[\bf Gauge potentials and gauge transformations]
Given the flux densities \eqref{Equitwistorial flux densities} on some $U_{i}$, we have the following traditional choice of {\it gauge potentials}
\begin{equation}
\begin{aligned}
\renewcommand{\arraystretch}{1.3}
\label{Equitwistorial gauge potentials}
	\left\{\begin{array}{l|l}
		C_{3} \in \Omega_{dR}^{3}\left(U_{i}\right) & \dd C_{3}=\tilde{G}_{4} \\
		C_{6} \in \Omega_{dR}^{6}\left(U_{i}\right) & \dd C_{6}=G_{7}-\tfrac{1}{2} C_{3}\left(\tilde{G}_{4}-\tfrac{1}{2} p_{1}(\omega)\right) \\
		B_{2} \in \Omega_{dR}^{2}\left(U_{i}\right) & \dd B_{2}=H_{3}-C_{3}+ \mathrm{CS}(\omega) + A_{1} F_{2}\\
        A_{1} \in \Omega_{dR}^{1}\left(U_{i}\right) & \dd A_{1}= F_{2}\\
    \end{array}\right\}
    \\ \rightarrow
    \left\{\begin{array}{l|l}

		B_{2} \in \Omega_{dR}^{2}\left(U_{i}^{\mathbb{Z}_{2}}\right) & \dd B_{2}|_{U_{i}^{\mathbb{Z}_{2}}}=H_{3}+ \mathrm{CS}(\omega) + A_{1} F_{2}\\
        A_{1} \in \Omega_{dR}^{1}\left(U_{i}^{\mathbb{Z}_{2}}\right) & \dd A_{1}|_{U_{i}^{\mathbb{Z}_{2}}}= F_{2}
    \end{array}\right\}
    \end{aligned}
\end{equation}
and the corresponding {\it gauge transformations} between the gauge potentials $\left(C_{3}, C_{6}, B_{2}, A_{1}\right)$ and $ \left(C_{3}^{\prime}, C_{6}^{\prime}, B_{2}^{\prime},A_{1}^{\prime}\right)$
\begin{equation}
\label{Equitwistorial gauge tranfomrations}
\renewcommand{\arraystretch}{1.0}
\begin{aligned}
\left\{\begin{array}{l|l}
C_{2} \in \Omega_{dR}^{2}\left(U_{i}\right) & \dd C_{2} = C_{3}^{\prime} - C_{3} \\
C_{5} \in \Omega_{dR}^{5}\left(U_{i}\right) & \dd C_{5} = C_{6}^{\prime} - C_{6} - \tfrac{1}{2} C_{3}^{\prime} C_{3} - \tfrac{1}{4}C_{2} {p_{1}}(\omega) \\
B_{1} \in \Omega_{dR}^{1}\left(U_{i}\right) & \dd B_{1} = B_{2}^{\prime} - B_{2} + C_{2} - \int dt\, \mathrm{Tr}(\omega^{\prime} - \omega) \wedge \omega_{t} - A_{0} F_{2} \\
A_{0} \in \Omega_{dR}^{0}\left(U_{i}\right) & \dd A_{0} = A_{1}^{\prime} - A_{1}
\end{array}\right\}
\\ 
\rightarrow
\left\{\!\!
\begin{array}{l|l}

B_{1} \in \Omega_{dR}^{1}\left(U_{i}^{\mathbb{Z}_{2}}\right) & \dd B_{1}|_{U_{i}^{\mathbb{Z}_{2}}} = B_{2}^{\prime} - B_{2}  - \int dt\, \mathrm{Tr}(\omega^{\prime} - \omega) \wedge \omega_{t} - A_{0} F_{2} \\
A_{0} \in \Omega_{dR}^{0}\left(U_{i}^{\mathbb{Z}_{2}}\right) & \dd A_{0}|_{U_{i}^{\mathbb{Z}_{2}}} = A_{1}^{\prime} - A_{1}
\end{array}
\right\}.
\end{aligned}
\end{equation}
{\it The gauge potentials corresponding to the fluxes that are not supported at the fixed locus $\mathrm{X}^{\mathbb{Z}_{2}}$ get decoupled at the orbi-fixed locus.}
\end{definition}
\begin{definition}[\bf Null concordances]
Given the flux densities in \eqref{Equitwistorial flux densities}, we say that a {\it null concordance} is
\begin{equation}
	\begin{array}{c}
		\left(\hat{\tilde{G}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}\right) \in \Omega_{\text {dR}}^{1}\left(\orbisingular U_{i}\sslash{\mathbb{Z}}_{2} \times[0,1], \mathfrak{l}_{\orbisingular(S^{4}\sslash{\mathbb{Z}}_{2})\sslash \mathrm{Sp}(1)} \orbisingular(\mathrm{CP}^{3}\sslash{\mathbb{Z}}_{2})\sslash \mathrm{Sp}(1)\right)_{ \mathrm{clsd} }
        \end{array}
        \end{equation}
        such that
        \begin{equation}
        \label{Equitwistorial boundary}
        \renewcommand{\arraystretch}{1.3}
        \begin{array}{l}
		\iota_{0}^{*}\left(\hat{\tilde{G}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}\right)|_{U_{i}^{\mathbb{Z}_{2}}}=0 \\
		\iota_{1}{ }^{*}\left(\hat{\tilde{G}}_{4}, \hat{G}_{7}, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}\right)|_{U_{i}^{\mathbb{Z}_{2}}}=\left(0, 0, H_{3}, F_{2}, p_{1}\right)
	\end{array}
\end{equation}
and a {\it null} concordance of concordances between a pair of them is given by
\begin{equation}
	\begin{array}{l}
			\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right) \in \Omega_{dR}^{1}(\orbisingular U_{i} \sslash{\mathbb{Z}}_{2}\times \underbrace{[0,1]}_{t} \times \underbrace{[0,1]}_{s} ; \mathfrak{l}_{\orbisingular(S^{4}\sslash{\mathbb{Z}}_{2})\sslash \mathrm{Sp}(1)}\orbisingular(\mathrm{CP}^{3}\sslash{\mathbb{Z}}_{2})\sslash \mathrm{Sp}(1))_{\mathrm{ clsd} }
            \end{array}
            \end{equation}
            such that
            \begin{equation}
            \label{Equitwistorial higher boundary}
            \renewcommand{\arraystretch}{2}
            \begin{array}{l}
		\iota_{s=0}^{*}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right)=\left(0, 0, \hat{H}_{3}, \hat{F}_{2}, \hat{p}_{1}\right) \\
		\iota^{*}_{s=1}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right)=\left(0, 0, \hat{H}_{3}^{\prime}, \hat{F}_{2}^{\prime}, \hat{p}_{1}^{\prime}\right) \\
			\iota^{*}_{t=0}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2}, \hat{\hat{p}}_{1}\right)=0 \\
			{ \iota}^{*}_{t=1}\left(\hat{\hat{\tilde{G}}}_{4}, {\hat{\hat{G}}}_{7}, {\hat{\hat{H}}}_{3}, {\hat{\hat{F}}}_{2},\hat{\hat{p}}_{1}\right) = \operatorname{pr}_{U_{i}}^{*}\left(0, 0, H_{3}, F_{2}, p_{1}\right)
		\end{array}\\
    \end{equation}
	where we have shown {\it only} the boundary conditions of the concordances and higher concordances on the chart $\mathrm{U_{i}}^{\mathbb{Z}_{2}}$ of the fixed locus $\mathrm{X}^{\mathbb{Z}_{2}}$, the bulk relations are the same as in \eqref{Twistorial Boundary conditions} and \eqref{Twistorial higher boundary conditions}.
    \end{definition}
\begin{proposition}
[\bf Gauge potentials from null concordances]
1) Every traditional gauge potential in equivariant twistorial cohomotopy arises from the null concordances in the following way:
\begin{equation}
\label{Equitwistorial gauge potentials from null concordances}
\renewcommand{\arraystretch}{1.3}
	\begin{array}{l}
		\begin{array}{rl}
		2 \mathrm{CS}(\omega)|_{U_{i}^{\mathbb{Z}_{2}}}
        & 
        = s_{3}=\int_{[0,1]}\hat{p_{1}}(\omega)\\
			B_{2}|_{U_{i}^{\mathbb{Z}_{2}}} &=\int_{[0,1]} \hat{H}_{3} \\
            A_{1}|_{U_{i}^{\mathbb{Z}_{2}}}&=\int_{[0,1]} \hat{F}_{2}\,.
		\end{array}
	\end{array}
\end{equation}
These are the results for the fixed locus, the bulk results are shown in \eqref{Twistorial gauge potentials from null concordances}.


2) The surjections from the null concordances to the usual potentials in the bulk $\mathrm{X}^{11}$ take the same forms as in \eqref{Twistorial surjections} and take the following forms on the fixed locus $\mathrm{X}^{\mathbb{Z}_{2}}$:
\begin{equation}
\label{Equitwistorial surjections}
\renewcommand{\arraystretch}{1.3}
	\begin{array}{l}
    \hat{p}_{1}= t p_{1} + \dd t\, s_{3}\\
            \hat{H}_{3}=t H_{3}+\dd t\, B_{2}   + t(1-t) A_{1} F_{2}\\
		\hat{F}_{2}=t F_{2}+ \dd t \,A_{1}.\\	
		\end{array}\\
        \end{equation}
\end{proposition}
They can be easily seen to satisfy the conditions in \eqref{Equitwistorial boundary} and also be consistent with \eqref{Equitwistorial gauge potentials}. The proofs for the fixed loci $\mathrm{X}^{\mathbb{Z}_{2}}$ follow analogous steps as in section 3.2 by setting $\tilde{G}_{4}|_{\mathrm{X}^{\mathbb{Z}_{2}}}=0,  {G}_{7}|_{\mathrm{X}^{\mathbb{Z}_{2}}}=0  $.

Let us turn to the concordance of concordances.

\begin{proposition}[\bf Gauge equivalences from null-concordance of concordances]:
1)In equivariant twistorial cohomotopy, the null concordances of concordances surject onto usual gauge transformations between the usual gauge potentials.
\begin{equation}
\label{Equitwistorial gauge equivalences from null concordances of concordances}
\renewcommand{\arraystretch}{1.3}
\begin{array}{l}
s_{2}|_{U_{i}^{\mathbb{Z}_{2}}}=\int_{s \in {[0,1]}} \int_{t \in {[0,1]}} \hat{\hat{p}}_{1}\\
	 B_{1}|_{U_{i}^{\mathbb{Z}_{2}}}=\int_{s \in{[0,1]}} \int_{t \in{[0,1]}} {\hat{\hat{H}}}_{3}\\A_{0}|_{U_{i}^{\mathbb{Z}_{2}}}= \int_{s \in{[0,1]}} \int_{t \in[0,1)} \hat{\hat{F}}_{2}\\

    \end{array}
\end{equation}
These are the results for the fixed locus, the bulk results are shown in \eqref{Twistorial gauge equivalnes from null concordances of concordances}.


2)The surjections from the null  concordance of concordances to the usual gauge transformations for the bulk $\mathrm{X}^{11}$ take the same form as in \eqref{Twistorial higher surjections}, and they take the following forms on the fixed locus $\mathrm{X}^{\mathbb{Z}_{2}}$:
\begin{equation}
    \label{Equitwistorial higher surjections}
    \renewcommand{\arraystretch}{1.6}
    \begin{array}{l}
    \hat{\hat{p}}_{1}=t p_{1}+\dd t s_{3}+s\dd t\left(s_{3}^{\prime}-s_{3}\right)-\dd s\, \dd t\, s_{2}\\

    \hat{\hat{H}}_{3}= t H_{3}+ \dd t\, B_{2} + t(1-t) A_{1} F_{2}
    + s\dd t\, (B_{2}^{\prime}-B_{2})\\
    + s t (1-t) (A_{1}^{\prime}- A_{1}) F_{2} + \dd s\, (t-t^2) A_{0} F_{2}- \dd s\, \dd t\, B_{1}\\
   \hat{\hat{F}}_{2}= tF_{2}+ \dd t A_{1} + s\dd t (A_{1}^{\prime}-A_{1})- \dd s\, \dd t\, A_{0}\,.
   \end{array}
    \end{equation}
    \end{proposition}

    These can be easily seen to satisfy the conditions in \eqref{Equitwistorial higher boundary} and also consistent with \eqref{Equitwistorial gauge tranfomrations}.



\section{Conclusion}
In this article, we have emphasized that flux quantization laws require the extra fields to make a theory globally defined. Motivated by the fact that the conjectured cohomology for eleven-dimensional supergravity is (twisted equivariant differential) cohomotopy, we have shown the modified Bianchi identities for M5 brane probes in 11D supergravity for tangentially twisted cohomotopy, twistorial cohomotopy and for equivariant twistorial cohomotopy. We have proved in these cases that the null concordances surject onto the usual differential forms of gauge potentials. Also, the concordances between the null concordances serve to provide the gauge transformations between the gauge potentials via surjections, thus providing the extra field content required to completely understand the {\it global} picture of M5 branes in 11D supergravity for tangentially twisted cohomotopy, twistorial cohomotopy and equivariant twistorial cohomotopy.

