\subsection{Gradient nonlinearities }\label{ss:GNC}
\noindent
Nonuniform magnetic field gradients introduce artifacts in dMRI. %\dn{this begs for references}
This causes not only image distortions\cite{THILAKA1994} but also spatially varying errors in the direction and strength of the applied diffusion encoding\cite{BAMMER2003}. Thus, the actual gradient ${\bf G}(\r)=\nabla B_z(\r)$ affecting the local Larmor frequency (and responsible for the diffusion encoding) differs both in its strength and orientation from the nominal gradient $\Gz$. Since the Maxwell's equations are linear, the deviations from the nominal $\Gz$ can be parametrized by the gradient coil tensor field\cite{BAMMER2003} $\mathsf{L}_{ij}(\mathbf{r})$, which relates the actual to the nominal gradient in the coordinate system of the gradient coils:
%basis of the principal gradient axes: 
\begin{equation}\label{eq:Gactual}
	G_i(\r) =  \mathsf{L}_{ij}(\r) \, \GGz_j \, ,
\end{equation}
where the summation over repeated indices is implied, and 
\begin{equation}
	\mathsf{L}_{ij}(\r) \equiv {\partial G_i(\r) \over \partial \GGz_j} = {\partial B_z(\r) \over \partial x_i} \cdot \frac1{\GGz_j} \,. 
%	\mathsf{L}_{ij}(\r) \equiv {\partial G_i(\r) \over \partial \GGz_j} = {\partial B_z^j(\r) \over \partial x_i} \cdot \frac1{\GGz_j} \,, 
		%	L_{ij}(\r) = \left( \frac{\partial B^j_z(\mathbf{r})}{\partial x_i} \right)/  G_{\mathrm{ideal},j} \, ,
\end{equation}
%\update{where $B_z^j$ is the magnetic field along z of the gradient coil $j$.} 
Introducing the wave vector $\mathbf{q}(t)$ as the antiderivative, 
\[
q_i(t) \equiv \int_0^t\! \d \tau\, \gamma G_i(\tau) = \mathsf{L}_{ij} \, \qqz_j(t) , \ \  \qqz_j = \int_0^t\! \d \tau\, \gamma \GGz_j(\tau) ,
\] 
where $\gamma$ is gyromagnetic ratio, one obtains the diffusion-encoding $\mathsf{B}$-tensor\cite{MITRA1995,MORI1995,WONG1995,CHENG1999} as a spatially varying field\cite{BAMMER2003}
\begin{equation}\label{Bactual}
	\mathsf{B}(\r)  \equiv \int\! \d t\, \q(t)\otimes \q(t) =  \mathsf{L}(\r) \, \Bz \, \mathsf{L}^t(\r) 
\end{equation}
in terms of the nominal $\mathsf{B}$-tensor\cite{WESTIN2016,TOPGAARD2017}
%\dn{add four refs from 1990s, see Webex}
\begin{equation} \label{Bz}
	\Bz  = \int\! \d t\,  \qz(t)\otimes \qz(t) \,. 
\end{equation}

The rank of $\B$ reflects how many dimensions of the diffusion process are being simultaneously probed; $\mathrm{rank}\,\B>1$ means probing the diffusion along more than one dimension. 
%The shape of $\B$ is affected by $\L(\r)$, as it can be observed in Eq.~(\ref{BactualAsym}) and (\ref{BactualAxSym}). For example, when a nominal isotropic diffusion encoding $\beta^{[0]}=0$ is applied, the actual $\B$ will become anisotropic and axially asymmetric since $\N$ is not constrained to have axial symmetry. 
%%Since the main eigenvector of $\L$ cannot coincide with $\g$ for all measurements, in many cases the resulting $\B$ will not be axially symmetric even if $\\bz$ was.
%Therefore, i
%In the remaining of this work we will focus on PGSE\cite{STEJSKAL&TANNER1965}, the most common case of diffusion encoding also known as linear tensor encoding since $\\bz=\bz \, \gz \otimes {\gz}$. Here, the actual $\mathsf{B}$-tensor becomes
Let us consider \emph{linear tensor encoding} (LTE, $\mathrm{rank}\,\B=1$), for which pulsed gradient spin echo (PGSE)\cite{STEJSKAL&TANNER1965} is the most common gradient waveform. The nominal LTE tensor $\Bz = \bz \, \gz \otimes {\gz}$, defined by its nominal unit direction $|\gz|=1$ and  $b$-value $\bz$, becomes
\begin{equation}
	\begin{aligned}\label{BLTE}
		\mathsf{B}(\r) &=  \bz \,  \L(\r)\big(\gz \otimes {\gz} \big) \L^t(\r) \,.
%		\\ 
%		b(\r) & = \mathrm{tr}\, \mathsf{B}(\r) =\bz \,\mathsf{N}(\r,\g) .
	\end{aligned}
\end{equation}
%where we define the \textit{nonlinearity tensor} $\N_{ij} = \L_{ik}\L_{jk}$. 
Remarkably, the LTE rank remains unchanged by the gradient nonlinearities: $\mathrm{rank}\,\B(\r)=1$ for any $\L(\r)$, when $\mathrm{rank}\,\Bz=1$.   
Both the LTE direction $\L \gz$ and the $b$-value 
\begin{equation}\label{bLTE}
\begin{aligned}
		b\big(\r,\gz\big)  = \mathrm{tr}\, \B(\r) &=\bz \, \g^{\circ\,t } \, \N(\r) \, \gz \,, \\
%		b\big(\r,\gz\big)  = \mathrm{tr}\, \B(\r) &=\bz \, {\gz}^t \, \N(\r) \, \gz \,, \\
		\N(\r) &= \L^t(\r) \L(\r) \,, 
\end{aligned}
		%\Big( \mathsf{N}^{00}(\r)  + \sum_m \mathsf{N}^{2m}(\r)Y^{2m}(\gz) \Big).
\end{equation}
get modified by $\L(\r)$. Here, we introduced the  \textit{nonlinearity tensor field} $\N_{ij}(\r)=\L_{ki}(\r) \L_{kj}(\r)$, which at every point $\r$ is a symmetric $3\times3$ matrix, determined by 6 independent parameters, instead of 9 parameters in $\L_{ij}$. 
%\dn{$\N_{ij}=\L_{ki} \L_{kj}$}
%To quantify this, we define a \textit{nonlinearity tensor} $\N_{ij} = \L_{ik}\L_{jk}$ 
%We can define a second-order symmetric \textit{nonlinearity tensor} $\N_{ij} = \L_{ik}\L_{jk}$, 
It admits the irreducible decomposition (we follow the notations of Ref.~\cite{COELHO2025}):
\begin{equation}
	\label{Ndecomp}
		\N_{ij} = \N^{(0)}_{ij} +  \N^{(2)}_{ij} \equiv \N_0  \delta_{ij}+ \sum_{m=-2}^2 \N^{2m} \Y^{2m}_{ij} \,. 
%		\N(\g)= \g^t \N \g  = \N^{00}  + \sum_{m=-2}^2 \N^{2m} Y_{2m}(\g) \,,	
%		\N(\gz)&= \N_{ij} g_i g_j = 	\N^{00}  + \sum_{m=-2}^2 \N^{2m} Y_{2m}(\gz) \,,
\end{equation}
Decomposition (\ref{Ndecomp}) separates the isotropic part $\N^{(0)}$, defined by a single parameter $\N_0=\frac13 \tr \N$, 
from its anisotropic counterpart $\N^{(2)}$, defined by five $\N^{2m}$. %and $\N(\g)= \N_{ij} g_i g_j$. 
Here, $\delta_{ij}$ is Kronecker's delta, and $\Y^{2 m}_{ij}$ are the symmetric trace-free basis tensors \cite{THORNE1980,COELHO2025}, such that 
$\Y^{2 m}_{ij} \hat g^\circ_i \hat g^\circ_j = Y_{2 m}(\gz)$ for a unit vector $\gz \in \mathbb{S}^2$ yield complex spherical harmonics (SH) $Y_{2 m}(\gz)$. 
We employ Racah normalization for SH and for the basis tensors $\Y^{\ell m}_{i_1\dots i_\ell}$: 
\begin{equation} \label{racah}
\int_{\mathbb{S}^2} \d\n \, Y_{\ell m}^*(\n) Y_{\ell' m'}(\n) = {\delta_{\ell \ell'} \, \delta_{m m'} \over 2\ell +1} \,, \quad \d\n = {\d\Omega \over 4\pi} \,, 
\end{equation}
where $\d\Omega = \sin\theta \d\theta \d\phi$ is the standard measure on the unit sphere $\mathbb{S}^2$, such that $\int_{\mathbb{S}^2} \d\n \equiv 1$, 
and $Y_{00}(\n)\equiv 1$. 
%We adopt  \textit{Racah normalization}\cite{RACAH1942} for SH: 
%\begin{equation*}
%	\int_{\mathbb{S}^2} \d \hat{\mathbf{n}}\, Y_{\ell m}^*(\hat{\mathbf{n}}) Y_{\ell' m'}(\hat{\mathbf{n}}) = {1\over 2\ell +1} \, \delta_{\ell \ell'} \delta_{m m'} \,,
%\end{equation*}
%such that $Y_{00}(\hat{\mathbf{n}})\equiv 1$ and $p_{00}\equiv 1$ (fODF normalization). 
%\dn{change $\gz\to \g_0$, $\bz \to b_0$ ? }
As a result, the LTE $b$-value (\ref{bLTE}) can be recast as 
\begin{equation}\label{bLTE=}
\begin{aligned}
		b(\r,\gz) =\bz\, \N(\r, \gz)\,, \quad \N &=  \N_0(\r)  + \N_2(\r,\gz) \,, \\ 
		\N_2(\r, \gz) =& \sum_{m=-2}^2 \N^{2m}(\r) Y_{2m}(\gz) \,. 
		%\Big( \mathsf{N}^{00}(\r)  + \sum_m \mathsf{N}^{2m}(\r)Y^{2m}(\gz) \Big).
\end{aligned}
\end{equation}
Namely, at each point $\r$ in the FOV, the LTE $b$-value depends on the nominal direction $\gz$ via an ellipsoidal shape 
$\N(\gz)=\N_{ij}\hat g^\circ_i \hat g^\circ_j$, 
such that its  average over all directions $\gz\in \mathbb{S}^2$ is 
%\dn{maybe $\langle \dots \rangle$?}
\begin{equation}  \label{Nrotinvs0}
		\mathrm{mean}_{\gz}\,\N(\gz) 
		= \int_{\mathbb{S}^2} \d \gz\,  \N(\gz) 
		= \N_{0} \,, 
\end{equation}
and the directional variance 
\begin{equation} \label{Nrotinvs}
\mathrm{var}_{\gz}\,\N(\gz) =  \int_{\mathbb{S}^2} \d \gz\,  \big(\N(\gz) - \N_0\big)^2 = \tfrac15 {\N_2}^2 \, ,
\end{equation}
where 
\begin{equation}\label{Nrotinvs2}
	{\N_{2}}^2 = \left\| \N^{2m} \right\|^2= \sum_{m=-2}^2 \N^{2m*} \, \N^{2m}  
\end{equation}
is the $\ell=2$  invariant of tensor $\N$, cf. Ref.\cite{COELHO2025}. 
Figure \ref{fig:gradientNonlinearities}a shows the dimensionless ratio $b(\r,\gz)/\bz=\N(\r,\gz)$ for a generic $\gz$, as well as the vector field $\L(\r)\, \gz$ distorted relative to $\gz$, 
for the system\cite{FOO2020} used in this study. 
Figure~\ref{fig:gradientNonlinearities}b,c shows  maps of mean and standard deviation of 
$b(\r,\gz)/\bz$, Eqs.~(\ref{bLTE=})--(\ref{Nrotinvs2}). 

Throughout the main text, we will limit ourselves to LTE, as the shape of the $\B$-tensor (\ref{BLTE}) is determined by a single unit direction 
\begin{equation}\label{g}
\g(\r) = {\L(\r) \gz \over  |  \L(\r) \gz |} \,, 
\end{equation} 
and remains LTE (rank-1) for arbitrary $\L(\r)$. In Appendix \ref{AppBactual}, we outline how the $b$-value and shape of an arbitrary $\Bz$ tensor are affected by $\L(\r)$.  
As one may expect, a generic $\L(\r)$ removes any special symmetries of the nominal $\Bz$ tensor. Hence, the moment we use beyond-LTE encodings (\ref{Bz}) with $\mathrm{rank}\,\Bz>1$, we should assume that the actual $\B$-tensor (\ref{Bactual}) is neither axially- nor spherically-symmetric; working with generic-shape $\B$ tensors would take us away from a familiar spherical convolution, as described below. 
%The corresponding biophysical models should be adjusted accordingly. 


\subsection{Spherical convolution: kernel -- fODF factorization}
\noindent
PIPE applies for any microstructure model that can be represented as a spherical convolution. This functional form, 
%The key assumption of PIPE is the {spherical convolution} framework for microstructure models. 
%This framework, 
empirically introduced at the level of signal representations \cite{TOURNIER2004,ANDERSON2005,TOURNIER2007,JEURISSEN2014}, 
%is extremely general, as it 
encompasses the vast majority of biophysical models for white matter \cite{JESPERSEN2007,FIEREMANS2011,ZHANG2012,KADEN2016,JENSEN2016,REISERT2017,NOVIKOV2018,VERAART2017} and gray matter \cite{PALOMBO2020,JELESCU2022,OLESEN2022}.  
Namely, a voxel is assumed to contain a collection of identical fiber bundles with arbitrary fODF (Fig.~\ref{fig:convFramework}). 
Under the assumption of every fiber bundle in a voxel having the same microstructure (justified in Ref.~\cite{CHRISTIAENS2020}), one introduces the fiber response kernel $\mathcal{K}$ that depends on the \emph{mutual orientation} of the fiber direction ${\bf \hat n}$ and  the direction ${\bf \hat g}$ of the diffusion encoding. 
%The axis $\g$  is well defined for LTE, as well as for any axially symmetric $\B$-tensor, Eq.~(\ref{eq:AxSymB}) in Appendix~\ref{AppBactual}.  
Because this response does not depend on  ${\bf \hat n}$ and ${\bf \hat g}$ separately, but only on their relative ``distance" 
%The fact that this response does not depend on  ${\bf \hat n}$ and ${\bf \hat g}$ separately, but only on their relative ``distance" 
$\hat{\mathbf{g}}\cdot\hat{\mathbf{n}}$ on a unit sphere, we can represent %allows one to represent 
the dMRI signal as a convolution over the unit sphere $\mathbb{S}^2$ of the kernel with the fODF, Fig. \ref{fig:convFramework}: 
%arise from the convolution of a fiber bundle response function (or kernel) with a fiber orientation distribution function (fODF) over the unit sphere: 
%Standard Model (SM) of diffusion in WM. At long diffusion times WM can be modeled as a convolution over the sphere
%\cite{NOVIKOV2019,KROENKE2004,JESPERSEN2007,FIEREMANS2012,ZHANG2012,JENSEN2016}:
\begin{equation}\label{eq:DWIasConvolution}
	S(b,\hat{\mathbf{g}}\mid\,\!\xi,p_{\ell\!\,m})=\int_{\mathbb{S}^2}\!\mathrm{d}\hat{\mathbf{n}}\,\mathcal{K}(b,\hat{\mathbf{g}}\cdot\hat{\mathbf{n}}\mid\,\!\xi)\,\mathcal{P}(\hat{\mathbf{n}}\mid\,\!p_{\ell\,\!m}) \,.
\end{equation}
Here $b$ and $\hat{\mathbf{g}}$, Eqs.~(\ref{bLTE=}) and (\ref{g}), define the measurement, %(\ref{eq:AxSymB}),
$\xi$ are the scalar \emph{tissue parameters} describing the kernel $\mathcal{K}$ (e.g., compartment fractions and diffusivities), 
%$\d  \hat{\mathbf{n}} = \d\Omega_{ \hat{\mathbf{n}}}/4\pi$ is the measure on a sphere normalized to $\int_{\mathbb{S}^2} \d \hat{\mathbf{n}} = 1$, 
and 
\begin{equation}\label{fODF}
\mathcal{P}(\hat{\mathbf{n}}\mid\,\!p_{\ell\,\!m})=\sum_{\ell=0,2,4,\dots} \sum_{m=-\ell}^\ell p_{\ell m}\,Y_{\ell\,\!m}(\hat{\mathbf{n}})
\end{equation} 
is the fODF  parametrized using coefficients $p_{\ell\,\!m}$ 
in the %spherical harmonics (SH) 
SH basis $Y_{\ell\,\!m}(\hat{\mathbf{n}})$, Eq.~(\ref{racah}), 
%We adopt  \textit{Racah normalization}\cite{RACAH1942} for SH: 
%\begin{equation*}
%\int_{\mathbb{S}^2} \d \hat{\mathbf{n}}\, Y_{\ell m}^*(\hat{\mathbf{n}}) Y_{\ell' m'}(\hat{\mathbf{n}}) = {1\over 2\ell +1} \, \delta_{\ell \ell'} \delta_{m m'} \,,
%\end{equation*}
%such that $Y_{00}(\hat{\mathbf{n}})\equiv 1$ and 
with $p_{00}\equiv 1$ (fODF normalization). 
%This formalism also applies to varying diffusion times, echo times, etc. Without loss of generality we focus on LTE acquisitions only.
%, $S(b=0)$ is the non-diffusion-weighted signal, %$x=[f,D_a,D_e^{||},D_e^{\perp},\hdots]$ 

In Eq.~(\ref{eq:DWIasConvolution})  we can further include the diffusion time $t$, echo time $T_E$ and inversion time $T_I$ dependence of the signal. 
From now on, for brevity we will write $\mathcal{K}(b, \hat{\mathbf{g}}\cdot\hat{\mathbf{n}} \mid \xi)$, 
implying that $b$ stands for all scalar \emph{protocol parameters}, $b\to \{b, T_E, T_I, t, \dots \}$ defining the measurement, 
such that, e.g., compartments within the fiber bundle can have different $T_2$ and $T_1$ values\cite{VERAART2017,LAMPINEN2020,COELHO2024} (with the respective compartment relaxation times included as tissue parameters $\xi$). 
The dependence on PGSE diffusion time $t$ and pulse duration $\delta$ allows one to incorporate different classes of structural disorder in different compartments \cite{NOVIKOV2014,LEE2018,LEE2020,LEE2020b,CHAN2024},  as well as exchange between them \cite{JELESCU2022,OLESEN2022,NOVIKOV2023,LEE2025}, with the corresponding model parameters added to $\xi$. 

