	\centering
	\includegraphics[width=\linewidth]{./figures/Fig0_v4.png}
	\caption[caption FIG 0]{PIPE central assumption: dMRI signal is  a spherical convolution of an axially-symmetric fiber response (kernel $\mathcal{K}$), characterized by scalar model parameters $\xi$, and an arbitrary fODF ${\cal P}(\n)$ characterized by its spherical harmonics coefficients $p_{\ell m}$. 
	}%
	\label{fig:convFramework}
\end{figure}


Much like convolutions become products under the ordinary Fourier transform, the convolution (\ref{eq:DWIasConvolution}) becomes a  product\cite{TOURNIER2004,ANDERSON2005,REISERT2017,NOVIKOV2018} in the SH basis: 
\begin{equation}\label{eq:SHfactorization}
		S_{\ell\,\!m}(b \mid \xi,p_{\ell m}) = \mathcal{K}_{\ell}(b,\mid \xi)\,p_{\ell\,\!m} \,, 
\end{equation}
where $S_{\ell m}$ are the signal's SH coefficients 
\begin{equation}\label{eq:SHfactorization2}
		S\left(b,\hat{\mathbf{g}}\mid\,\!\xi,p_{\ell\!\,m}\right) = \sum_{\ell\,\!m}S_{\ell\,\!m}(b \mid \xi,p_{\ell m})\,Y_{\ell\,\!m}(\hat{\mathbf{g}}) 
\end{equation}
with respect to the  directions (\ref{g}), and $\mathcal{K}_{\ell}\equiv \mathcal{K}_{\ell 0}$ are the projections of the kernel (aligned with the ${\bf \hat z}$ axis) onto Legendre polynomials $P_\ell(\zeta)=Y_{\ell 0}(\zeta)$, where $\zeta = \hat{\mathbf{g}}\cdot {\bf \hat z}$: 
\begin{equation}\label{eq:KrotInvs}
		\mathcal{K}_{\ell}(b \mid \xi) = \int_0^1 \,\d \zeta \, \mathcal{K}(b, \zeta \mid \xi) \, P_\ell(\zeta)  \, ,
\end{equation}
such that the kernel is expanded as 
\begin{equation}\label{eq:Kexpansion}
\mathcal{K}(b, \hat{\mathbf{g}}\cdot\hat{\mathbf{n}} \mid \xi) 
= \sum_{\ell = 0,2,4,\hdots} 	\mathcal{K}_{\ell}(b \mid \xi)\, P_\ell(\hat{\mathbf{g}}\cdot\hat{\mathbf{n}}) \, .
\end{equation}
%By assuming fiber bundles are axially symmetric, only $\mathcal{K}_{\ell}=\mathcal{K}_{\ell 0}$ are needed, which are rotationally invariant. 
%Note that if the kernel were not axially symmetric we would need $\mathcal{K}_{\ell m}$ for nonzero $m$. 
The factorization (\ref{eq:SHfactorization}), essential for what follows, 
is valid as long as the kernel possesses axial symmetry ($\mathcal{K}_{\ell m}=0$ for nonzero $m$ in the fiber basis $\n={\bf \hat z}$). 
Note that beyond this %mild 
assumption, the microstructure of the  fiber bundle is not constrained --- it can have an arbitrary number of compartments (with gaussian or non-gaussian diffusion), they can be coupled by exchange, have distinct relaxation properties, etc. 

We note in passing that the convolution for generic $\B$-tensors and non-axially symmetric kernels has to be defined on the SO(3) rotation group manifold 
$\mathbb{S}^3/\mathbb{Z}_2$ (the 3-dimensional sphere $\mathbb{S}^3$ with the antipodal points identified, $\mathbb{Z}_2=\{1,\ -1\}$), 
rather than on the 2-dimensional sphere $\mathbb{S}^2$. The corresponding Fourier transform involves a product of non-commuting matrices (the coefficients in the Wigner functions' basis), as the SO(3) group is non-abelian. 
For  axially symmetric response kernels, invariant under the SO(2) rotation around the fiber bundle axis, 
%and the corresponding axially-symmetric $\B$-tensors (\ref{eq:AxSymB}), 
the convolution becomes effectively defined\cite{HEALY1998} on a quotient space $\mathbb{S}^2\cong\mathrm{SO(3)/SO(2)}$ that is equivalent to the 2-dimensional sphere  $\mathbb{S}^2$, which explains the integration over fODF directions in Eq.~(\ref{eq:DWIasConvolution}). 


