\section{Proof of the Theorems in Section \ref{sec:theory}}

Note that $\{X(t)\}_{t\ge 0}$ is a Continuous Time Markov  Process (CTMP) over a general (uncountable) space state (i.e., $\mathbb{R}^+:= (0, \infty$)).
Given the times $T_n$ of $n$-th jump, we consider the Discrete Time Markov Priocess (DTMP), denoted by  $\{X_n\}_{n\in\mathbb{N}}$, which is defined on the same space state \cite{Twedie-Meyn}
by $
X_n=X(T_n^{-})=X(T_n)$ where $X(t^{-})$ stands for the left limit $\lim_{u\uparrow t} X(u)$.
We first characterize the distribution of inter jumps times.
\begin{proposition}\label{prop:T_n}Let $\Delta T_n=T_{n+1}-T_n$ be the inter-jump time and $X(t^+)=\lim_{s\downarrow t} X(s)$. We have 
\begin{align*}
    &\overline F_{\Delta T_n {|\color{black}X(T_n^+)}}(\zeta\mid z) :=\mathbb{P}(\Delta T_n> \zeta \mid {\color{black}X(T_n^+)}=z)= \\
    &\exp\left(-(\lambda_{0}+\mu){\color{black}{\zeta}}-\frac{\lambda_{1} }{\gamma\phi} z^{\phi} 
    (1-\mathrm{e}^{-\gamma \phi\zeta})\right)
\end{align*}
and the conditional probability distribution is given by
\begin{align*}
f_{\Delta T_n{|X(T_n^+)}}(\zeta\mid z) &= (\lambda_{0} +\mu + \lambda_{1}  z^{\phi}) \\
&\cdot \mathrm{e}^{-\gamma \phi\eta} )\mathrm{e}^{-(\lambda_{0}+\mu)\zeta-\frac{\lambda_{1} }{\gamma\tau} z^{\phi} 
\left(1-\mathrm{e}^{-\gamma \phi\zeta}\right)}.
\end{align*}

\end{proposition}

\begin{proof}
We compute the distribution by noting that the event 
 $\{\Delta T_n>\zeta\}$, is equivalent to the event that no jumps occur in the interval $(T_{n},T_{n}+\zeta]$. Therefore, as rather immediate consequence of the stochastic intensity definition,  given $X(T_n^+)=z$, we have that $\Delta T_n$ is  distributed as:
    \begin{align*}
    &\overline F_{\Delta T_n{|\color{black}X(T_n^+)}}(\zeta\mid z)= \mathbb{E}[\mathrm{e}^{-\int_0^\zeta \lambda(\eta) \mathrm{d\eta} }\mid z]\\
    &=\mathrm{e}^{- \int_0^\zeta \left(\lambda_0+\mu+ \lambda_1\cdot(z\mathrm{e}^{-\gamma \eta})^\tau\right) \mathrm{d} \eta}=\mathrm{e}^{-(\lambda_0+\mu)\zeta-\frac{\lambda_1 }{\gamma\tau} z^\tau 
    (1-\mathrm{e}^{-\gamma \tau\eta})}
\end{align*}

The conditional probability distribution is then obtained by taking the derivative of cumulative distribution function $f_{\Delta T_n{|\color{black}X(t_n^+)}}(\zeta\mid z)=\frac{\mathrm d}{\mathrm{d}\zeta}[1-\overline F_{\Delta T_n {|\color{black}X(t_n^+)}}(\zeta\mid z)]$.
\end{proof}

Now, turning our attention to the DTMP $\{ X_n\}_n$, we have:

\begin{proposition}
Let $\{X_n\}_{n\in\mathbb{N}}$ be the embedded chain associated to {{$\{X(t)\}_{t\geq 0}$}. Then the sequence $\{X_n\}_{n\in\mathbb{N}}$  evolves according to the following recursion
\begin{align}\label{eq:dtmc}
X_{n+1}=&[X_n +V(X_n)\ind_{
\{T_n\in N_I \}} +W\ind_{\{T_n\in N_E\}} ] \nonumber\\
&\cdot \mathrm{e}^{-{ \color{black}\gamma}\Delta T_n(X_n+V(X_n))} 
\end{align}
with  transition kernel defined by}
\begin{align}\label{eq:kernel}
    P(x, dy)
    = & \frac{1}{\gamma y} \int^\infty_{y} \Big[ p^{(n)}_I (x) f_{V|X}(z-x\mid x)\\  + & p^{(n)}_E (x)   f_{W}(z-x)
        \Big] f_{\Delta T_n}\left(\frac{1}{\gamma}\log \frac{z}{y} \mid z \right) dz
\end{align}
{{where $p^{(n)}_I $ and $p^{(n)}_E$ are the probabilities of the events $\{T_n \in N_I\}$ and $\{T_n \in N_E\}$, respectively, satisfying 
\[
\begin{split}
 p^{(n)}_E(x) =\frac{\mu}{\lambda_{0}+\mu+\lambda_{1}(x^{\phi})}\\
  p^{(n)}_I(x) =1- \frac{\mu}{\lambda_{0}+\mu+\lambda_{1}(x^{\phi})}.
\end{split}
\]}}
\end{proposition}
\begin{proof} Note that by construction: $\ind_{\{T_n\in N_I \}} +\ind_{\{T_n\in N_E\}}=1$, and
\[
\begin{split}
  p^{(n)}_E(x) :=\mathbb{E}[\ind_{\{T_n\in N_I \}}\mid X_n=x] =\frac{\mu}{\lambda_{0}+\lambda_{1}(x^{\phi})+\mu}
\end{split}
\]
from which
\begin{align*}
  p^{(n)}_I(x) & :=\mathbb{E}[\ind_{\{T_n\in N_E \}}\mid X_n=x] \\
  &=1-p^{(n)}_E(x)=1- \frac{\mu}{\lambda_{0}+\lambda_{1}(x^{\phi})+\mu}.
\end{align*}

Therefore the value of the process immediately after the \(n\)-th jump is:
\begin{align*}
 X(T_n^+) = &
 X(T_n) + V(X(T_n))\ind_{
    \{T_n\in N_I \}} +W\ind_{\{T_n\in N_E\}}\\ = & X_n + V(X_n )\ind_{
    \{T_n\in N_I \}} +W\ind_{\{T_n\in N_E\}} 
 \end{align*}
and the process evolves according to the decay dynamics:
   $$
   X(t)\ind_{\{ T_n< t \le T_{n+1}  \}} = X(T_n^+) \mathrm{e}^{-\gamma (t - T_n)}\ind_{\{ T_n< t \le T_{n+1}  \}}.
   $$
   Evaluating the process at \(T_{n+1} = T_n + \Delta T_n\), we get:
   $
   X(T_{n+1}) = X(T_n^+) \mathrm{e}^{-\gamma \Delta T_n}
   $
 and by replacing the post-jump value into the above expression:
   \[
   X_{n+1} =  \Big(X_n + V(X_n )\ind_{
    \{t_n\in N_I \}} +W\ind_{\{t_n\in N_E\}} \Big)
  \mathrm{e}^{-\gamma \Delta T_n(X_n + V(X_n))}.
   \]
   whose distribution is given in Proposition \ref{prop:T_n}.
   Recalling the  definition of  the transition kernel as: 
\[
P(x, dy):=  \mathbb{P}(X_{n+1}\in dy \mid X_n= x)
\]
and conditioning on the event $\{
 X_n + V(X_n )\ind_{
    \{t_n\in N_I \}} +W\ind_{\{t_n\in N_E\}} =z\}$, from \eqref{eq:dtmc}
 we obtain for any $z>y$ 
 $$
\left\{\Delta T_n(z) \ge  \frac{1}{\gamma} \log \frac{z}{y}\right\}=\{X_{n+1}\le y \}
$$
Then the probability that $X_{n+1}$ falls within a small interval around $y$ is given by 
\begin{align*}
P(x, dy)= & \int_{0}^{\infty} \mathbb{P}(X_{n+1} \in dy \mid X_n = x,\\ & V_n \ind_{
    \{t_n\in N_I \}} +W\ind_{\{t_n\in N_E\}}=z-x)\\ 
 &\times \Big[ p^{(n)}_I(x)  f_{V|X}(z-x\mid x) + p^{(n)}_E (x)   f_{W}(z-x)
\Big] dz.
\end{align*}

Substitute $\Delta T_n(z)$ and express the integral over $z$ from $y$ to $\infty$:

\begin{align*}
P(x, dy) = & \frac{1}{\gamma y} \int_{y}^{\infty}  \Big[ p^{(n)}_I (x) f_{V|X}(z-x\mid x)+ p^{(n)}_E (x)   f_{W}(z-x)
\Big] \\ & f_{\Delta T_n\mid z}\left(\frac{1}{\gamma} \log \frac{z}{y} \mid z \right) dz.
\end{align*}
\end{proof}

