It should be noted that the $P(\cdot, dy)$ is  continuous (and hence lower semi-continuous) as long as $y\in (0, \infty)$ and the total variation distance 
$\delta(F_V(z \mid x_1), F_V(z \mid x_2))\to 0$  as $|x_1-x_2|\to 0$. 

In the following to simplify the notation we denote with $Z(X_n )= V(X_n )\ind_{
    \{t_n\in N_I \}} +W\ind_{\{t_n\in N_E\}} $ and $f_Z(y\mid x)= p^{(n)}_I (x) f_{V|X}(y\mid x) + p^{(n)}_E (x)   f_{W}(y)$

\begin{Lemma}
    The following facts are true.
    \begin{enumerate}
    \item[a)] The DTMP $\{X_n\}_{n\in\mathbb{N}}$ is irreducible with respect to the restriction to $[\kappa_I,\kappa_S]$ of the Lebesgue measure $\mu_{\text{Leb}(0,\infty)} $ for any $\kappa_I>0$ and  $\kappa_S>\kappa_I$;
     \item[b)] The DTMP $\{X_n\}_{n\in\mathbb{N}}$ is strongly aperiodic.
     \end{enumerate}
\end{Lemma}
\begin{proof}	In order to prove irriducibility we show that,  for any set  $A\in \mathcal{B}([\kappa_I,\kappa_S])$
    such that $\mu_{\text{Leb}}(A)>0$ and any $x\in (0,  \infty)$,  there exists $k\in\mathbb{N}$ such that: 
    \[
    \mathbb{P}(X_{n+k}\in A\mid X_n= x)>\delta_{x,A}>0.
    \]
    Now, for any $\varepsilon\in(0,1)$,
    let   $z_{\varepsilon} (x) := \sup \{z:   1- F_{V|X}(z\mid x)> \varepsilon
    %	 \mathbb{P}(V(x)>z)>\varepsilon
    \}$,
    note that as a consequence of model assumptions $z_{\varepsilon}(x)$   is non decreasing with respect to its argument.
    Then, uniformly  for every  $y\in (\kappa_I, \min(z_{\varepsilon}(\kappa_I), \kappa_S)]$
    \[
    P(x, dy)> \delta_{x,\varepsilon}> 0
    \]
    as it can be easily checked by inspection.  Therefore  for any 
    $A\in \mathcal{B}([\kappa_I, \min(z_{\varepsilon}(\kappa_I), \kappa_S)])$.
    \[
    \mathbb{P}(X_{n+1}\in A\mid X_n= x):= \int_A P(x,dy)\ge  \delta_{x,\varepsilon} \mu_{\text{leb}}(A)
    \]	  
    Now   if     $z_{\sup}(0)>\kappa_S$ we are done, otherwise,
    consider  the $k$ -steps transition kernel, recursively defined as 
    \[
    P^k(x, dy)= \int_z P^{k+1}(x,dz)P(z,dy) 
    \]
    It turns out that  for any $y\in [\kappa_I, \min(k z_{\varepsilon}(\kappa_I), \kappa_S)]$
    \[
    P^k(x, dy)>\delta'_{x,\varepsilon}
    \]
    and therefore similarly  as before we can conclude that 
    \[
    \mathbb{P}(X_{n+k}\in A\mid X_n= x):= \int_A P^k(x,dy)\ge  \delta'_{x,\varepsilon} \mu_{\text{leb}}(A)
    \]
    for any $A\in \mathcal{B}([\kappa_I, \min(  k z_{\varepsilon}(0), \kappa_S)].$  

    To complete the proof  it is enough to observe that 
    for a sufficiently large $k$  necessarily $k z_{\varepsilon}(\kappa_I)>\kappa_S$. Then the item a) is proved.

    Since it can easily shown that   $\inf_{x\in [\kappa_I,\min(  z_{\varepsilon}(\kappa_I), \kappa_S) ]} \delta_{x,\varepsilon}= \delta_\varepsilon >0$, we deduce
    as in  \cite{Twedie-Meyn} (see definition on page 114) that 
    $\{X_n\}_n$ is  the strongly a-periodic.	
    Indeed   the set $[\kappa_I,  \min(z_{\varepsilon}(\kappa_I),\kappa_S)]$  turns out to be  $\nu_1$-small with respect to $\nu_1=  \delta_{\varepsilon} \mu_{\text{Leb}}([\kappa_I,\min (z_{\varepsilon}(\kappa_I),\kappa_S ) ])$.
\end{proof}	
Therefore by Theorem  $4.0.1$ in \cite{Twedie-Meyn}  there exist a unique maximal  measure with respect to which 
$\{X_n\}_n$ is irreducible. Such a measure  necessarily dominates $\mu_{\text{Leb}} (0,\infty)$. 
Moreover 
given an arbitrary open set $O\in \mathcal{B}((0,\infty))$ the transition probability
\[
P(x, O)=\int_O P(x,dy)  
\]
is clearly lower-continuous with respect to $x\in(0, \infty)$, therefore 
$\{X_n\}_n$  is  weak Feller. Now by Theorem  6.0.1 (iii) in  \cite{Twedie-Meyn},
since the  support of $\mu_{\text{Leb}}$ has clearly  a non empty-interior,
$\{X_n\}_n$ is a  T-chain.
At last   by Theorem  6.0.1 (ii) in  \cite{Twedie-Meyn} we deduce that every compact set is petite
(observe that any subset of a petite set is trivially petite).

Now we turn our attention to recurrence properties of our DTMP. 


\begin{Lemma}
    As long as $\theta+\phi<1$ or $\theta+\phi=1$  and  $c/\beta>1$ with $c:=\frac{\gamma }{\lambda_0+ \lambda_1+\gamma}\alpha^{-\phi} F_Z\left((\alpha-1)x\mid x\right)$ for an arbitrary $\alpha>1$
    $\{X_n\}_n$  
    is  $\mu_{\text{Leb}}$-irriducible, stongly aperiodic  positive Harris recurrent.
    Therefore a unique stationary probability measure, $\pi$  exists, and   i.e. for any  inital condition as $n$  grows large the $\sup_{A\in \mathcal{B}(0,\infty)}| P^n(x, A)- \pi(A)|\to 0$
    (i.e. the MC ergodic).
\end{Lemma}


\begin{proof} 
    By Theorem 11.3.4 in \cite{Twedie-Meyn},  to prove that $\{X_n\}_n$   is  a  positive Harris recurrent MC , it is enough to apply a drift argument.
    In particular, given petite set $C$, if 
    a real valued function $\mathcal{L}(\cdot)$ $(0,\infty) \to [0,\infty]$
    can be found such that:
    \begin{equation} \label{drift}
        \mathbb{E} [\mathcal{L}(X_{n+1})-\mathcal{L}(X_{n})\mid X_n=x]<-1 +b \ind_C(x)
    \end{equation}
    Then the DTMP is positive Harris recurrent.

    Now choosing  $\mathcal{L}(x)=x$, we have:
    \begin{align*}
        &\mathbb{E} [\mathcal{L}(X_{n+1})- \mathcal{L}(X_{n})\mid X_n=x]
        =\mathbb{E} [X_{n+1}\mid X_n=x]-x \\
        &=\mathbb{E}  [ (x +Z(x)) \mathrm{e}^{-\gamma \Delta T_n(x+Z(x))})] -x \\
        &=x(\mathbb{E}  [ \mathrm{e}^{- \gamma\Delta T_n(x+Z(x))} ]-1) +\mathbb{E}[Z(x) \mathrm{e}^{-\gamma\Delta T_n(x+Z(x))})] 
    \end{align*}
    Let us start to consider the case $\theta+\phi<1$, then:

    \begin{align*}
    &\mathbb{E}[Z(x) \mathrm{e}^{- \gamma\Delta T_n(x+Z(x))})]<\mathbb{E}[Z(x) ] \\ &=p^{(n)}_I(x)\mathbb{E}[V(x)] + p^{(n)}_E (x) \mathbb{E}[W] \le (\beta+ \delta)  x^\theta
    \end{align*}
    for any constant $\delta>0$
    while 

    \begin{align*}
        &\mathbb{E}  [ \mathrm{e}^{- \gamma \Delta T_n(x+Z(x))} ]=\int \int  \mathrm{e}^{-\gamma \zeta} f_{\Delta t }(\zeta \mid x+v) f_Z(v\mid x)
        \mathrm{d}v\mathrm d \zeta \\
        &\le   \int \int  \mathrm{e}^{-\gamma \zeta} [\lambda_0+ \lambda_1(x+v)^\phi] e^{-[\lambda_0+ \lambda_1(x+v)^\phi]\zeta } 
        \mathrm d \zeta f_Z(v\mid x)
        \mathrm{d}v\\ 
       &= \int \frac{\lambda_0+ \lambda_1(x+v)^\phi }{\lambda_0+ \lambda_1(x+v)^\phi+\gamma} f_Z(v\mid x)
        \mathrm{d}v \\  
        &= 1- \int \frac{\gamma }{\lambda_0+ \lambda_1(x+v)^\phi+\gamma} f_Z(v\mid x)
        \mathrm{d}v\\
    %   & < 1- \gamma c'(x^{-\phi})
    \end{align*}
%again for some $c'>0$.
Note that the first inequality holds because the stochastic intensity in $(X_n,X_{n+1})$ 
is upper bounded by $ \lambda_0+ \lambda_1(X_n+Z(X_n))^\phi$.
Now  given an arbitrary $\alpha>1$
\begin{align*}
&\int_0^\infty \frac{\gamma }{\lambda_0+ \lambda_1(x+v)^\phi+\gamma} f_Z(v\mid x)
        \mathrm{d}v\\
        &=\Big(\int_0^{\alpha x} +\int_{\alpha x}^\infty\Big) \frac{\gamma }{\lambda_0+ \lambda_1(x+v)^\phi+\gamma} f_Z(v\mid x)
        \mathrm{d}v\\\ & \ge \frac{\gamma }{\lambda_0+ \lambda_1(\alpha x)^\phi+\gamma} F_Z\left((\alpha-1)x\mid x\right)
\end{align*}

    Therefore for $\alpha x>1$
\begin{align*}
&\mathbb{E}  [ \mathrm{e}^{- \gamma \Delta T_n(x+Z(x))} ]\le 1- \frac{\gamma }{\lambda_0+ \lambda_1(\alpha x)^\phi+\gamma} F_Z\left((\alpha-1)x\mid x\right)\\
&\le 1- \frac{\gamma }{\lambda_0+ \lambda_1+\gamma}(\alpha x)^{-\phi} F_Z\left((\alpha-1)x\mid x\right)= 1- c x^{-\phi} 
\end{align*}
with $c:=\frac{\gamma }{\lambda_0+ \lambda_1+\gamma}\alpha^{-\phi} F_Z\left((\alpha-1)x\mid x\right)$ and  
    \begin{align}
        \Delta \mathcal{L}(x):=\mathbb{E} [\mathcal{L}(X_{n+1})- \mathcal{L}(X_{n})\mid X_n=x]\nonumber\\
        < x(1 -  cx^{-\phi} -1 ) + (\beta+\delta)x^\theta\nonumber\\
        = -c x^{1-\phi}+ (\beta+\delta) x^\theta  \label{drift-components}
    \end{align}
    Now  if $\theta<1-\phi$, the first negative term asymptotically for large $x$ dominates,
      when instead $\theta+\phi=1$  the two terms in \eqref{drift-components} 
      are comparable and    a negative drift is observed  only under the additional condition that $\frac{ c}{\beta} >1$.
    In both cases   there exists a $x_0$ such that  $\Delta \mathcal{L}(x)< -1  $ for any $x\ge x_0$. 
    Moreover 
    \[
    \Delta \mathcal{L}(x)=\mathbb{E}  [ (x +Z(x)) \mathrm{e}^{- \Delta T(x+Z(x))})] -x
    \le \mathbb{E}[Z(x)]
    \]
    therefore 
    \[
    \sup_{x\le x_0} \Delta \mathcal{L}(x)=  \sup_{x\le x_0}  \mathbb{E}[Z(x)]\le  \mathbb{E}[Z(x_0)]. 
    \]
    In conclusion condition \eqref{drift} is met by setting $C=\{x\le x_0\}$ and $b=\mathbb{E}[Z(x_0)] +1$.

\end{proof}

    At last, with rather standard arguments it can be shown that the ergodicity of $\{X_n\} _n$ implies  the ergodicity of $\{X(t)\}$
    (i.e. a unique stationary distribution $\Pi(A)$  exists and   $P^t(x,A)\to \Pi(A)$  for every $x\in \mathbb{R}^+$  and $A\in \mathcal{B}(\mathbb{R}^+)$.

    Now, since  the measure induced by $P^t(x,A)$ can be easily shown to be absolutely continuous with respect to the Lebesgue measure $\mu_{\text{Leb}}(\mathbb{R})^+)$,
    for any $t>0$
    we have that: 
    \[
    \Pi(t,A)=\int_{y\in A}\int_{x\in \mathrm{R}^+} P^t(x, \mathrm{d}y) \Pi(0,\mathrm{d}x)  \ \
    \]
    is, as well, absolutely continuous  with respect to the Lebesgue measure $\mu_{\text{Leb}}(\mathbb{R}^+)$ with density  (i.e Radon-Nikodyn derivative)
    $f(x,t)$.


    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \subsection{Kolmogorov equation}
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    Now defined with $F(y,t):= \mathbb{P}(X(t)\le y )=\int_0^x f(x,t) \mathrm{d}x $   we have that th $F(y,t)$ satisfies the following Partial Integro-Differential Equation:
    \begin{equation}\label{diff-eq-5.1}
        \frac{\partial F(y,t)}{\partial t}=  \gamma y \frac{\partial F(y,t)}{\partial y}- \int  ( \lambda(t)+\mu)\bar F_Z( y-x \mid x) \frac{\partial F(x,t) }{\partial x}     \mathrm{d}x
    \end{equation}
    While the unique stationary distribution $F(y)$ satisfies the following ODE:
    \begin{equation}\label{stat-diff-eq-5.1}
        \gamma y \frac{\mathrm{d} F(y)}{\mathrm{d} y}=\int  (\lambda(t)+\mu)\bar F_Z( y-x \mid x) \frac{\mathrm{d}  F(x) }{\mathrm{d}  x}     \mathrm{d}x
    \end{equation}

\begin{proof}
    Observe that  by construction:
    \[
    F(y, t +\Delta t ) = F(y, t ) + \Delta F^+(y,t)- \Delta F^-(y,t)
    \]
    with 
    \[
    \Delta F^+(y,t)=\mathbb{P} ( X(t+\Delta t)\le y,   X(t)> y )
    \]
    and
    \[
    \Delta F^-(y,t)=\mathbb{P} ( X(t+\Delta t)>y,   X(t)\le y )
    \]
    now  denoted with $N(t,\Delta t):= N(t+\Delta t)-N(t)$, the number of jumps in $[t, t+ \Delta t)$, as immediate consequence of the definition of stochastinc intensity we have
    that:

    \begin{align*}
        &\mathbb{P}(N(t,\Delta t)=0\mid X(t)=y )= 1- (\lambda(y)+\mu)\Delta t + o(\Delta t)\\
        &\mathbb{P}(N(t,\Delta t)=1\mid X(t)=y  )= (\lambda (y)+\mu) \Delta t + o(\Delta t)\\
        &\mathbb{P}(N(t,\Delta t)>1\mid X(t)=y )= o(\Delta t)
    \end{align*}
    where $\lambda(y)=\lambda^{(0)}+\lambda^{(1)}y^\phi$.

    Now:



    \begin{align*}
        &\Delta F^+(y,t)=\sum_{k\in \mathbb{N}\cup \{0\} } \mathbb{P} ( X(t+\Delta t)\le y,   X(t)> y, N(t,\Delta t)=k )\\
    \end{align*}
    %\textcolor{red}{va riscritta...}



    Now
    \begin{align*}
        &\mathbb{P} ( X(t+\Delta t)\le y,   X(t)> y,  N(t,\Delta t)=0)\\
        =&\mathbb{P} ( X(t) \mathrm{e}^{-\gamma \Delta t} \le y,   X(t)> y, N(t,\Delta t)=0 )\\
        =&\mathbb{P} ( y<  X(t) \le y \mathrm{e}^{\gamma \Delta t }, N(t,\Delta t)=0  ) \\
        =&\mathbb{P}( N(t,\Delta t)=0 \mid   y<  X(t) \le y \mathrm{e}^{\gamma \Delta t } )
         \mathbb{P} ( y<  X(t) \le y \mathrm{e}^{\gamma \Delta t } ).
    \end{align*}
    with
    \begin{align*}
        &\mathbb{P} ( y<  X(t) \le y \mathrm{e}^{\gamma \Delta t } ) 
        =\int_{y}^{ y \mathrm{e}^{\gamma \Delta t} }  f(z, t)\mathrm{d}z\\
        &=\int_{y}^{ y (1+\gamma y \Delta t+ o(\Delta t)) }  f(z, t)\mathrm{d}z
        =   (\gamma y \Delta t +o(\Delta t)  ) f(y,t) \\
        & = (\gamma y \Delta t +o(\Delta t)  ) \frac{F(y,t)}{\partial y} 
    \end{align*}

    and 

    \[
    \mathbb{P}( N(t,\Delta t)=0 \mid   y<  X(t) \le y \mathrm{e}^{\gamma \Delta t } )=1- \lambda(y)\Delta t +o(\Delta t)
    \]
    by the continuity of $\lambda(y )$ with respect to $y$.  
    Moreover  by construction
    \begin{align*}
        &\{\ X(t+\Delta t)\le y,   X(t)> y, N(t,\Delta t)=1\} \\
        &\subseteq \{   y<  X(t) \le y \mathrm{e}^{\gamma \Delta t} ,   N(t,\Delta t)=1 \}
    \end{align*}
    therefore 
    \begin{align*}
        \mathbb{P}(  y<  X(t) \le y \mathrm{e}^{\gamma \Delta t} ,   N(\Delta t)=1  )= o(\Delta t)
    \end{align*}

    Similarly
    \[
    \Delta F^-(y,t)= \sum_{k\in \mathbb{N}\cup \{0\} } \mathbb{P} ( X(t+\Delta t)> y,   X(t)< y, N(t,\Delta t)=k )
    \]
    Now observe that  the event 
    \[
    \{   X(t+\Delta t)> y,   X(t)< y, N(t, \Delta t)=0    \}=\emptyset
    \]

    Therefore 
    \[
    \Delta F^-(y,t)= \mathbb{P} ( X(t+\Delta t)> y,   X(t)< y, N(t,\Delta t)=1) +o(\Delta t )
    \]
    since
    \[
    \mathbb{P}(    N(t,\Delta t)>1 \mid X(t)<y  )    = o(\Delta t)
    \]
    Now
    \begin{align*}
        &\mathbb{P} ( X(t+\Delta t)> y,   X(t)< y, N(t,\Delta t)=1)\\
        &= \int_{x<y} \mathbb{P} ( X(t+\Delta t)> y,  N(t,\Delta t)=1 \mid  X(t)=x) \mathrm{d}F(x,t)   \\
        &= \int_{x<y} \mathbb{P} ( X(t+\Delta t)> y  \mid N(t,\Delta t)=1,  X(t)=x)\\
        &\qquad  \mathbb{P} (   N(t,\Delta t)=1 \mid  X(t)=x)  \mathrm{d}F(x,t)  \\
        &= \Delta t \int_{x<y} \bar F_Z(y-x\mid x)(\lambda(x)+\mu)\mathrm{d}F(x,t)  +o(\Delta t )
    \end{align*}
\end{proof}

    Then, summarizing:
    \begin{align*}
        &\frac{F(y,t+\Delta t)-F(y,t)}{\Delta t }=(\gamma y  +o(1)  ) \frac{F(y,t)}{\partial y} \\ 
        &\quad -\int_{x<y} \bar F_Z(y-x\mid x)(\lambda(x)+\mu)\mathrm{d}F(x,t)  + o(1)
    \end{align*}
    The result  is then obtained taking  liminf and limsup of both sides for $\Delta t\to 0$.

    Equation  \eqref{stat-diff-eq-5.1} is then immediately obtained from  \eqref{diff-eq} 
    by  looking for  solutions that are stationary  i.e., $F(y,t)=F(y)$.


