\section{Background}

\subsection{Gradings}
\label{ss:gradings}
The three gradings on triply graded Khovanov--Rozansky link homology are referred to as the $Q$-grading, the $T$-grading, and the $A$-grading.  The $Q$-grading is the quantum (i.e.~the grading internal to all rings and (bi)modules), the $T$-grading is the cohomological grading on complexes, and the $A$-grading is the Hochschild cohomological grading.

If $V=\bigoplus_{i,j,k\in \Z}V^{i,j,k}$ is a $\Z^3$-graded vector space, then the (tri)degree of a homogeneous element $v\in V^{i,j,k}$ may be written $\deg_{Q,T,A}(v):=(\deg_Q(v),\deg_T(v),\deg_A(v))=(i,j,k)$.  We may also express the degree of $v$ exponentially (using the term \emph{weight}), writing $\wt(v)=Q^i T^j A^k$.



We also use the symbol $Q^i T^j A^k$ for the corresponding grading shift functor:
\[
(Q^i T^j A^k V)^{i',j',k'} = V^{i'-i,j'-j,k'-k}
\]

\begin{remark}
When clarification is desired, we may write the various grading groups with subscripts indicating the relevant degrees.  For instance, we may refer to $\Z_Q$-graded modules, or $\Z_Q\times \Z_T$-graded complexes, and so on.
\end{remark}

\begin{remark}
By default the notation $\Hom(-.-)$ will always mean enriched homs in the appropriate sense.  For instance, if $R$ is a $\Z_Q$-graded ring, and $M,N$ are graded $R$-modules, then $\Hom_R(M,N)$ will always mean the $\Z_Q$-graded abelian group of (not necessarily degree preserving) $R$-linear homs. 

Similarly, if $X$ and $Y$ are complexes of $\Z_Q$-graded $R$-modules, then $\Hom_R(X,Y)$ will mean the $\Z_Q\times \Z_T$-graded complex of homs.
\end{remark}


As is common in the link homology literature (e.g., \cite{EH}) we will sometimes change variables to
\begin{equation}
\label{eq: qta to QTA}
q=Q^2,\ t=Q^{-2}T^2,\ a=Q^{-2}A.
\end{equation}
In other words, $(\deg_Q,\deg_T,\deg_A)=(2\deg_q-2\deg_t-2\deg_a, 2\deg_t, \deg_a)$.

Throughout this paper, we will be working with various graded (super)polynomial rings in variables $x_i$, $y_i$, or $\theta_i$; by convention the weights of these variables are
\begin{equation}\label{eq:weights of xyt}
\wt(x_i)=q \, , \qquad \wt(y_i)=t \, , \qquad \wt(\theta_i)=a.
\end{equation}
where $q,t,a$ are as in \eqref{eq: qta to QTA}.  Written additively, the (tri)degrees are
\begin{equation}\label{eq:degrees of xyt}
\deg_{Q,T,A}(x_i)=(2,0,0) \, , \qquad \deg_{Q,T,A}(y_i)=(-2,2,0) \, , \qquad \deg_{Q,T,A}(\theta_i)=(-2,0,1).
\end{equation}
The variables $\theta_i$ are odd (meaning they square to zero and anticommute amongst themselves) since they carry Hochschild cohomological degree 1.  We will also abbreviate by writing alphabets in these various variables as in
\begin{equation}\label{eq:alphabet soup}
\xx=(x_1,\ldots,x_n) \, ,\qquad \yy=(y_1,\ldots,y_n) \, , \qquad \ttheta=(\theta_1,\ldots,\theta_n),
\end{equation}
where the integer $n$ will be understood from context.  For instance, the notation $\k[\xx,\yy,\ttheta]$ denotes the $\Z_Q\times \Z_T\times \Z_A$-graded super polynomial ring generated by even variables $x_i,y_i$, and odd variables $\theta_i$.  

\subsection{Rouquier complexes}
\label{sec: rouquier}


Fix an integer $n\geq 1$ and a commutative ring $\k$ (soon we will specialize $\k$ to a field of characteristic zero). Let $R:=\k[\xx]$ be the $\Z_Q$-graded polynomial ring, which we regard as a $\Z_Q$-graded algebra by declaring that $x_i$ has degree 2, i.e.~$\wt(x_i)=Q^2=q$ in the above notation. Let $R\text{-gmod-}R$ denote the category of $\Z_Q$-graded $(R,R)$-bimodules, with morphisms given by (not necessarily degree zero) bimodule maps.

Introduce a second alphabet of $x$-variables, denoted $\xx'=(x_1',\ldots,x_n')$.  We will identify $R\otimes R=\k[\xx,\xx']$ with $x_i\otimes 1$ identified with $x_i$, and $1\otimes x_i$ identified with $x_i'$.  This gives an identification of categories
\begin{equation}\label{eq:bimod to mod}
\k[\xx]\text{-gmod-}\k[\xx]=\k[\xx,\xx']\text{-gmod}.
\end{equation}
On the left hand side of this identification we have the monoidal structure $\otimes_R$ which we denote by $\star$.  On the right hand side this is most conveniently written as a bilinear functor
\[
(\k[\xx,\xx']\text{-gmod})\times (\k[\xx',\xx'']\text{-gmod})\to \k[\xx,\xx'']\text{-gmod} \, \qquad (M,N)\mapsto M\otimes_{\k[\xx']}N.
\]
The unit object for this tensor product is $R$ which we will sometimes denote as $\one_n$.


Let $\Ch(R\text{-gmod-}R)$ denote the category of complexes of graded bimodules, with grading-preserving differentials.  An object $X$ of this category is $\Z_Q\times \Z_T$-graded with differentials of weight $\wt(d_X)=T$.  The monoidal structure $\star$ extends to  $\Ch(R\text{-gmod-}R)$.


We recall some basic definitions for link homology. 
Let $$B_i=\k[\xx,\xx'] \Big/ (x_i+x_{i+1}=x'_{i}+x'_{i+1},x_ix_{i+1}=x'_{i}x'_{i+1},x_j=x'_j \ \text{for}\ j\neq i)$$

We interpret $B_i$ as a graded $(R,R)$-bimodule, via the identification \eqref{eq:bimod to mod}.  The category of Soergel bimodules $\SBim_n$ is defined as the smallest full subcategory of the category of graded $(R,R)$-bimodules containing $B_i$ and $R$ and closed under tensor product $\star$, direct sums, grading shifts and direct summands.


There are canonical maps $b_i\in \Hom(B_i, R)$ and $b^*_i\in \Hom(R,B_i)$ with $\wt(b_i)=Q^0$, $\wt(b_i^*)=Q^2$, defined by
$$
b_i(1)=1,\ b_i^*(1)=x_i-x'_{i+1}.
$$
We define the Rouquier complexes by 
$$
F_i=\left[ 
\begin{tikzcd}
Q^{-1}\underline{B_i}\arrow {r}{b_i} & Q^{-1}R 
\end{tikzcd}\right],\ 
F^{-1}_i=\left[ 
\begin{tikzcd}
QR\arrow {r}{b^*_i} & Q^{-1}\underline{B_i} 
\end{tikzcd}\right].
$$
The terms in homological degree zero are underlined.
\begin{theorem}\cite{Rouquier}
The complexes $F_i$ and $F_i^{-1}$ satisfy braid relations 
$$
F_i\star F_{i+1}\star F_i\simeq F_{i+1}\star F_i\star F_{i+1},\ F_i\star F_j\simeq F_j\star F_i\ (|i-j|>1),\ F_{i}\star F_i^{-1}\simeq R$$
up to homotopy.
\end{theorem}
 By tensoring these, for any braid $\beta$ one can construct a  complex $F(\beta)$   which is well-defined up to homotopy equivalence. We denote the differential in this complex by $d$.

 \begin{example}
 \label{ex: rightmost R}
 If $\beta$ is a positive braid, then $F(\beta)$ has a unique copy of $R$ in the rightmost homological degree shifted by $Q^{-\ell(\beta)}T^{\ell(\beta)}$. It defines a special chain map 
 \begin{equation}
 \label{eq: rightmost R}
 Q^{-\ell(\beta)}T^{\ell(\beta)}R\to F(\beta).
 \end{equation}
 \end{example}



\begin{lemma}\cite{GH}
\label{lem: dot sliding}
Let $\b\in \Br_n$ be a braid with underlying permutation $w\in S_n$.  Then for all $i$ there exists $\eta_i\in \mathrm{End}^{2,-1}(F(\beta))$ such that 
\begin{align}
\label{eq: def xi}
[d,\eta_i]&=x_{i}-x'_{w\inv(i)}\\
[\eta_i,\eta_j]&=0\\
\eta_i^2&=0
\end{align}
\end{lemma}
We remind the reader that the notation $\eta_i\in \mathrm{End}^{2,-1}(F(\beta))$ means that $\wt(\eta_i)=Q^2T\inv$.

We will refer to $\eta_i$ as to {\em dot-sliding homotopies.}  




\subsection{$y$-fication}

\begin{definition}
Let $V$ be a $\Z_A\times \Z_Q\times \Z_T$ graded (resp. $\Z_Q\times \Z_T$ graded)  $\k$-module. We define the completed tensor product $V\cotimes\k[\yy]=V\cotimes\k[y_1,\ldots,y_n]$ as follows.
A homogeneous element of weight $A^{k}Q^{m}T^{s}$ in $V\cotimes\k[\yy]$  is a (possibly infinite) linear combination 
\begin{equation}
\label{eq: completed tensor}
\sum_{k_1,\ldots,k_n\geq 0} f_{k_1,\ldots,k_n} y_1^{k_1}\cdots y_n^{k_n}
\end{equation}
where $f_{k_1,\ldots,k_n}$ is a homogeneous element of $V$ of weight $A^kQ^{m+2K}T^{s-2K}$, $K=k_1+\ldots+k_n$. 
An arbitrary element of $V\cotimes\k[\yy]$ is a finite linear combination of homogeneous elements.
\end{definition}

\begin{remark}
It is easy to see that 
$$
V[y_1,\ldots,y_n]\subset V\cotimes\k[y_1,\ldots,y_n]\subset V\llbracket y_1,\ldots,y_n\rrbracket.
$$
The second inclusion is strict if $V\neq 0.$
\end{remark}


Recall the conventions from Equations \eqref{eq:alphabet soup}, \eqref{eq:weights of xyt}.  If $X,Y\in \Ch(\SBim_n)$ are   complexes of Soergel bimodues, then we will adjoin variables $y_1,\ldots,y_n$ to the hom complex $\Hom(X,Y)$, obtaining
\begin{equation}\label{eq:complex with ys}
\Hom(X,Y)\cotimes\k[\mathbf{y}].
\end{equation} 
There is a differential on \eqref{eq:complex with ys}, given by
\[
d\left(\sum_{k_1,\ldots,k_n\geq 0} f_{k_1,\ldots,k_n} y_1^{k_1}\cdots y_n^{k_n}\right) := \sum_{k_1,\ldots,k_n\geq 0} d(f_{k_1,\ldots,k_n}) y_1^{k_1}\cdots y_n^{k_n}.
\]
When $X=Y$ also abbreviate by writing $\End(X)\cotimes\k[\mathbf{y}]:=\Hom(X,X)\cotimes\k[\mathbf{y}]$.  We say that $f\in \Hom(X,Y)\cotimes\k[\mathbf{y}]$ is \emph{polynomial} if the terms $f_{k_1,\ldots,k_n}$ are zero for all but finitely many tuples $(k_1,\ldots,k_n)$.  The polynomial elements form a subcomplex, denoted by
\[
\Hom(X,Y)[\mathbf{y}]\subset \Hom(X,Y)\cotimes\k[\mathbf{y}]
\]
\begin{remark}
\label{rem: poly 1}
If $X$ and $Y$ are such that $\Hom^{i+2K,j-2K}(X,Y)=0$ for $K\gg 0$, then we have $\Hom(X,Y)\cotimes\k[\mathbf{y}] = \Hom(X,Y)\otimes \k[\mathbf{y}]$.  In particular, this is the case if $X$ and $Y$ are bounded complexes.
\end{remark}

\begin{definition}\label{def:yified cat}
Let $w\in S_n$ be a given permutation.  We define a category $\mathcal{Y}_{n,w}$ as follows.  Objects of this category are formal expressions $\tw_{\alpha}(X)$ where $X\in \Ch(\SBim_n)$ and $\alpha\in \End(X)\cotimes\k[\mathbf{y}]$ is an element of weight $T$ such that
\begin{equation}\label{eq:y curvature}
(d_X+\alpha)^2 = \sum_{i=1}^n(x_{i}-x_{w\inv(i)}')y_i
\end{equation}
The expression $D:=d_X+\alpha$ is called the \emph{total differential} acting on $\tw_{\alpha}(X)$.  The homs in $\mathcal{Y}_{n,w}$ are the $\Z_Q\times \Z_T$-graded complexes given by
\[
\Hom_{\mathcal{Y}_{n,w}}(\tw_{\alpha'}(X'),\tw_\alpha(X)) = \Hom(X,Y)\cotimes\k[\mathbf{y}]
\]
with differential given by the supercommutator with $D$, i.e.
~$f\mapsto [D,f]$.
\end{definition}

Up to isomorphism, the object $\tw_\alpha(X)$ only depends on the total differential $d_X+\alpha$. Consequently, we have
\[
\tw_{\alpha}(X) \cong \tw_{\alpha_+}(X,d_X+\alpha_0),
\]
where we have written $\alpha_0:=\alpha|_{y_1=\cdots=y_n=0}$ and $\alpha_+:=\alpha-\alpha_0$.  Thus, we can always write objects of $\mathcal{Y}_{n,w}$ as expressions $\tw_\alpha(X)$ with $\alpha_0=0$. In this case we think of $\tw_\alpha(X)$ as $X$ with a deformed differential.

\begin{remark}
Given $X\in \Ch(\SBim_n)$ we may write $X^y$ for an object $\tw_\alpha(X)\in \mathcal{Y}_{n,w}$ with $\alpha_0=0$ (as in the preceding discussion).  In practice, we only write $X^y$ when the choice of deformation is unique up to isomorphism.  
\end{remark}

For establishing the existence and uniqueness of lifts we recall some results from \cite[Section 2]{GH}.

\begin{lemma}\label{lemma:obstructions}
Suppose we are given a permutation $w\in S_n$ and a complex $X\in \Ch(\SBim_n)$ on which the action of $x_i-x_{w\inv(i)}'$ is null-homotopic for all $1\leq i\leq n$.  Suppose $X$ satisfies the ext-vanishing condition that any closed element of $\End(X)$ of weight $Q^{2+2K}T^{-2K}$ (with $K\in \Z_{\geq 1}$) is null-homotopic.  Then there exists a lift $X^y\in \mathcal{Y}_{n,w}$. %\EG{Check gradings}
\end{lemma}

\begin{proof}
For the reader's convenience, we sketch the proof and refer to \cite{GH} for more details. We write
$$
\alpha=\sum_{k=1}^{\infty}\alpha_k
\ , \quad \text{where}\quad \ \alpha_k=\sum_{k_1+\ldots+k_n=k}\alpha_{k_1,\ldots,k_n}y_1^{k_1}\cdots y_n^{k_n}.
$$
Since $\alpha$ has weight $T$, all coefficients $\alpha_{k_1,\ldots,k_n}$ of $\alpha_k$ have weight $Q^{2k}T^{1-2k}$.
The equation  \eqref{eq:y curvature} unpacks to an infinite sequence of equations:
\begin{align*}
[d,\alpha_1]&=\sum_{i=1}^n(x_i-x_{w\inv(i)}')y_i\\
[d,\alpha_k]+\sum_{i+j=k}\alpha_i\alpha_j&=0,\ k>1.
\end{align*}
For the first equation, we can use null-homotopies for $x_i-x_{w\inv(i)}'$ as coefficients of $\alpha_1$. For $k>1$, we construct  $\alpha_k$ by induction, assume that we have constructed $\alpha_1,\ldots,\alpha_{k-1}$. One can check that the sum $\sum_{i+j=k}\alpha_i\alpha_j$ is closed under $d$, and to construct $\alpha_k$ it is sufficient to prove that it is null-homotopic.

Observe that for $i+j=k$ all coefficients in $\alpha_i\alpha_j$ have weights 
$$
(Q^{2i}T^{1-2i})\cdot (Q^{2j}T^{1-2j})=Q^{2k}T^{2-2k}=Q^{2+2(k-1)}T^{-2(k-1)}. 
$$
By our assumption, this implies that $\sum_{i+j=k}\alpha_i\alpha_j$ is null-homotopic, and the result follows.
\end{proof}

For the uniqueness of lifts of $X$ the following is useful.

\begin{lemma}\label{lemma:lifting maps}
Suppose we are given complexes $X,Y\in \Ch(\SBim_n)$ and lifts $X^y,Y^y\in \mathcal{Y}_{n,w}$, and let $f\colon X\to Y$ be a degree zero chain map.  Suppose that we have the ext-vanishing condition that any closed element of $\Hom(X,Y)$ of weight $Q^{2K}T^{1-2K}$ (with $K\in \Z_{\geq 1}$) is null-homotopic. Then there exists a lift of $f$ to a degree zero chain map $f^y\colon X^y\to Y^y$.
\end{lemma}
One can also formulate a statement on the uniqueness of $f^y$ up to homotopy, but we will not need it. 

\begin{lemma}\label{lemma:lift of equiv}
If $X\in \Ch(\SBim_n)$ is contractible, then so is $X^y$ for any lift $X^y\in \mathcal{Y}_{n,w}$.  If $\phi\colon X\to X'$ is a homotopy equivalence then any lift $\phi^y\colon X^y\to (X')^y$ is a homotopy equivalence in $\mathcal{Y}_{n,w}$.
\end{lemma}

Combining Lemmas \ref{lemma:lifting maps} and \ref{lemma:lift of equiv} gives the following.

\begin{lemma}\label{lemma:uniqueness of lifts}
Let $X\in \Ch(\SBim_n)$ be given, and assume that we have the ext-vanishing condition that any closed element of $\End(X)$ of weight $Q^{2K}T^{1-2K}$ (with $K\in \Z_{\geq 1}$) is null-homotopic. Then any $X^y\in \mathcal{Y}_{n,w}$ lifting $X$ is unique up to homotopy equivalence.
\end{lemma}
\begin{proof}
Let $\tw_{\alpha}(X)$ and $\tw_{\alpha'}(X)$ be two lifts of $X$ to $\mathcal{Y}_{n,w}$. The ext-vanishing condition tells us that $\id_X$ has a lift to a closed morphism  $\tw_{\alpha}(X)\to \tw_{\alpha'}(X)$, by Lemma \ref{lemma:lifting maps}. This lift is a homotopy equivalence by Lemma \ref{lemma:lift of equiv}.
\end{proof}

\begin{definition}\label{def:yified Rouquier}
Given a braid $\b\in \Br_n$ with underlying permutation $w\in S_n$, we let $F^y(\b)\in \mathcal{Y}_{n,w}$ be defined by
\[
F^y(\b):=\tw_{\sum_i \eta_i y_i}(F(\b))
\]
where the $\eta_i$ are as in Lemma \ref{lem: dot sliding}. 
\end{definition}

Note that by Lemma \ref{lem: dot sliding} we have
$$
\left(d+\sum_i \eta_i y_i\right)^2=d^2+\sum_{i}[d,\eta_i]y_i+\left(\sum_i \eta_i y_i\right)^2=\sum_{i=1}^n(x_{i}-x_{w\inv(i)}')y_i.
$$
The last term vanishes since $\eta_i$ square to zero and anticommute.

\begin{example}
For the elementary braid $\sigma_i,\sigma_i\inv$  the corresponding deformed Rouquier complex is visualized as in the diagrams
$$
F^y(\sigma_i)=\left[ 
\begin{tikzcd}
Q^{-1}\underline{\yBi}\arrow[bend left]{r}{b_i} & Q^{-1}\yR \arrow[bend left,pos=0.55]{l}{b^*_i(y_i-y_{i+1})}
\end{tikzcd}\right],\ 
F^y(\sigma_i\inv)=\left[ 
\begin{tikzcd}
Q\yR\arrow[bend left,pos=0.55]{r}{b^*_i} & Q^{-1}\underline{\yBi} \arrow[bend left,pos=0.4]{l}{b_i(y_i-y_{i+1})}
\end{tikzcd}\right].
$$
The indicated arrows define the total differential $D$.  Note that the cohomological degree of the $y_i$ is 2, which gives the leftward arrows cohomological degree $+1$, rather than the degree $-1$ which they would otherwise have.
\end{example}



There is a tensor product operation $\mathcal{Y}_{n,w}\star \mathcal{Y}_{n,v}\to \mathcal{Y}_{n,wv}$, defined as follows:
\[
\tw_{\alpha}(X)\star \tw_{\alpha'}(X') := \tw_{\gamma}(X\star X'),
\]
where $\gamma=\alpha\star \id_{X'} + \id_X\star \alpha'|_{y_i\mapsto y_{w(i)}}$.

The properties of $y$-ified Rouquier complexes $F^y(\beta)$ can be summarized as follows.

\begin{theorem}\cite{GH}
a) Each Rouquier complex admits a unique-up-to-homotopy deformation to an object of the appropriate category $\mathcal{Y}_{n,w}$.

b) For any braids $\b,\b'\in \Br_n$ we have $F^y(\b)\star F^y(\b')\simeq F^y(\b\b')$.  In particular the complexes $F^y(\sigma_i^\pm)$ satisfy the braid relations up to homotopy.
\end{theorem}

We give a proof for the reader's convenience.

\begin{proof}
For part (a), observe that $F(\beta)$ is invertible hence $\End(F(\beta))=\End(R)=R$, and all closed endomorphisms of nonzero $T$-degree are null-homotopic. Now the result follows from Lemmas \ref{lemma:obstructions} and \ref{lemma:uniqueness of lifts}. Part (b) follows from (a). 
\end{proof}



\begin{definition}
For each reflection $r=(i\ j)$ in $S_n$ we define the Koszul $y$-ification
$$
K_r=K_{ij}=\left[
\begin{tikzcd}
Q^{-1}R\arrow[bend left, pos=0.4]{r}{x_i-x_j} & Q\underline{R} \arrow[bend left]{l}{y_i-y_j}
\end{tikzcd}
\right]\in \mathcal{Y}_{n,r}.
$$
\end{definition}

The following facts were proved in \cite{GH,GHM}.


\begin{lemma}(\cite[Proposition 4.3]{GH})
\label{lem: skein}
a) There is a (unique up to homotopy) degree zero chain map $\psi_i:\yTi\to \yTii$ such that $\Cone(\psi_i)\simeq K_{i,i+1}$. As a consequence, we have an exact triangle in $\mathcal{Y}_{n,s_i}$:
$$
\yTi\xrightarrow{\psi_i} \yTii\to K_{i,i+1}\to \yTi[1]
$$

b) There is a (unique up to homotopy) chain map $\a_i:Q^{-2}T^2\yTii\to \yTi$ such that $\Cone(\a_i)$ is a complex build of two copies of $B_i$. 

c) We have $\a_i\circ \psi_i=\psi_i\circ \a_i=y_i-y_{i+1}$.
\end{lemma}

Explicitly, the maps $\psi_i$ and $\a_i$ are given by the following diagram:
$$
\psi_i:
\begin{tikzcd}
Q^{-1}\underline{\yBi}\arrow[bend left]{rr}{b_i} \arrow[swap,pos=0.2]{ddrr}{1} & & Q^{-1}\yR \arrow{ll}{b^*_i(y_i-y_{i+1})} \arrow[pos=0.2]{ddll}{y_i-y_{i+1}}\\ 
 & & \\
Q\yR\arrow{rr}{b^*_i} & & Q^{-1}\underline{\yBi} \arrow[bend left,pos=0.45]{ll}{b_i(y_i-y_{i+1})}
\end{tikzcd}
\quad
\a_i:
\begin{tikzcd}
Q^{-1}\underline{\yBi}\arrow[bend left]{rr}{b_i}  & & Q^{-1}\yR \arrow{ll}{b^*_i(y_i-y_{i+1})} \\ 
 & & \\
Q\yR\arrow{rr}{b^*_i} \arrow[pos=0.2]{uurr}{1}& & Q^{-1}\underline{\yBi} \arrow[bend left,pos=0.45]{ll}{b_i(y_i-y_{i+1})} \arrow[swap,pos=0.2]{uull}{y_i-y_{i+1}}
\end{tikzcd}
$$

\begin{definition}
Let $A_{ij}=\sigma_{j-1}\cdots\sigma_{i+1}\sigma_i^2\sigma_{i+1}\inv\cdots \sigma_{j-1}\inv$ denote Artin's generator of the pure braid group. 
 \[
 A_{ij} \ =\  
