\begin{lemma}
\label{lem: rightmost R y-ified}
Let $\beta=A_{i_1,j_1}\cdots A_{i_k,j_k}$ be a positive pure braid presented as a product of $A_{ij}$. Then there exists morphisms in $\mathcal{Y}_{n,1}$:
$$
\psi_{\beta}: F^y(\beta)\to R,\ \a_{\beta}: Q^{-\ell(\beta)}T^{\ell(\beta)}R\to F^y(\beta)
$$
such that 
$$
\psi_{\beta}\circ \rho_{\beta}=\rho_{\beta}\circ \psi_{\beta}=(y_{i_1}-y_{j_1})\cdots (y_{i_k}-y_{j_k}).
$$
Furthermore, $\a_{\beta}$ deforms the map from \eqref{eq: rightmost R}.
\end{lemma}

\begin{proof}
First, by Lemma \ref{lem: skein} we can construct maps 
$$\psi_{i}: F^y(\sigma_i^2)\to R,\ \a_{i}: Q^{-2}T^{2}R\to F^y(\sigma_i^2)
$$
with the desired properties. Since $A_{ij}$ is conjugate to $\sigma_i^2$, we get 
$$
\Hom_{\mathcal{Y}_{n,1}}\left(F^y(A_{ij}),R\right)=\Hom_{\mathcal{Y}_{n,1}}\left(F^y(\sigma_i^2),R\right),
$$
$$
\Hom_{\mathcal{Y}_{n,1}}\left(R,F^y(A_{ij})\right)=\Hom_{\mathcal{Y}_{n,1}}\left(R,F^y(\sigma_i^2)\right),
$$
and this yields maps
$$\psi_{ij}: F^y(A_{ij})\to R,\ \a_{ij}: Q^{-2}T^{2}R\to F^y(A_{ij})
$$
which compose to $y_i-y_j$. The result follows by multiplying $\psi_{ij}$ and $\a_{ij}.$
 \end{proof}

 \begin{remark}
 The maps $\psi_{\beta}$ and $\rho_{\beta}$ defined above might depend on the choice of factorization of $\beta$ as the product of Artin generators. We plan to study this dependence in the future work, but for the purposes of this paper we simply choose one such factorization. See also Lemma \ref{lem: connecting map Delta} for the case when $\beta$ is the full twist braid.
 \end{remark}

\section{Rasmussen spectral sequences}

In this section we define a family of spectral sequences relating triply graded Khovanov--Rozansky homology to $\mathfrak{gl}(N)$ homology. Our description is slightly different from the original construction of Rasmussen \cite{RasDiff} but equivalent to it, see Remark \ref{rmk: Rasmussen}.  

\subsection{Hoschschild (co)homology}
\label{ss:HH}

We start by reviewing Hochschild homology.   
\begin{definition}\label{def:Delta}
Define the chain complex $\Delta_n(\xx,\xx')$ to have underlying module $\k[\xx,\xx',\ttheta]$  (with conventions as in \eqref{eq:alphabet soup}), and differential
\begin{equation*}
    d_{\HH} = \sum_{i = 1}^n (x_i-x_i') \theta_i
\end{equation*}
We regard $\Delta_n(\xx,\xx')$ as a $\Z_Q\times \Z_A$-graded complex, with gradings as in \eqref{eq:weights of xyt}, the differential $d_{\HH}$ has weight $A=qa$.
\end{definition}


\begin{remark}\label{rmk:Delta_n}
The top monomial in $\Delta_n(\xx,\xx')$ has $\wt(\theta_1\cdots \theta_n)=a^n$.  The dual complex $$\Hom_{\k[\xx,\xx']}\left(\Delta_n(\xx,\xx'),\k[\xx,\xx']\right)$$ is isomorphic to $a^{-n}\Delta_n(\xx,\xx')$.  In turn, this is  the Koszul complex resolving $R=\k[\xx,\xx']/(x_i-x'_i)$ over $\k[\xx,\xx']$.
\end{remark}

\begin{definition}
\label{def: HH}
Let $M\in R\text{-gmod-}R$ be a graded bimodule.  Then we define $\HH(M)$ to be the homology of the complex $\left(M \otimes_{\k[\xx,\xx']} \Delta_n(\xx,\xx'),d_{\HH}\right)$, where we identify $R\otimes R=\k[\xx,\xx']$ as in \S \ref{sec: rouquier}. 
\end{definition}

We will regard $\HH(M)$ as $\Z_Q\times \Z_A$-graded $\k$-module.

\begin{remark}
In light of Remark \ref{rmk:Delta_n}, we have that $\HH(M)$ is the Hochschild cohomology of $M$ or, equivalently, the Hochschild homology of $M$ up to a shift:
$$
\HH(M)=a^n\Tor^{\k[\xx,\xx']}(M,R) = \Ext_{\k[\xx,\xx']}(R,M).
$$

See also \cite[Lemma 3.4]{GHMN}.
\end{remark}

\begin{remark}
\label{rem: HH is a functor}
It follows from the definition that $\HH$ is a functor, that is, for any bimodule morphism $M\to N$ we get a $\k$-linear map $\HH(M)\to \HH(N)$.
\end{remark}

The general properties of the $\Tor$ functor immediately imply the following:

\begin{proposition}
\label{prop: Tor invariance}
Let $F^{\bullet}$ be a free resolution of $M$ over $\k[\xx,\xx']$. Then the homology of $F^{\bullet}\otimes_{\k[\xx,\xx']}R$ is isomorphic to $a^{-n}\HH(M)$.
\end{proposition}

Below (in particular, to compare our constructions with \cite{RasDiff}) we will need some explicit models for such resolutions. %\EG{check}

\begin{lemma}
\label{lem: examples resolutions}
a) Let $M$ be a Soergel bimodule. Then $M\otimes_{\k[\xx']}\Delta_n(\xx',\xx'')$ is free a resolution of $M$.

b) Let $M=B_{i_1}\star \cdots \star B_{i_r}$, and let $F_{i}^{\bullet}$ be a free resolution of $B_i$ over $\k[\xx,\xx']$. Then $F_{i_1}^{\bullet}\star \cdots \star F_{i_r}^{\bullet}$ is a free resolution of $M$.
\end{lemma}

\begin{proof}
It is well known (e.g., \cite[Corollary 3.6]{GHMN}) that any Soergel bimodule is free as a left or as a right $R$-module. Therefore for any Soergel bimodules $M$ and $N$ and their free resolutions $F_M^{\bullet}$ and $F_N^{\bullet}$ the tensor product $F_M^{\bullet}\star F_N^{\bullet}$ is a free a resolution of $M\star N$. In other words, the derived tensor product of $M$ and $N$ agrees with the underived one. This implies (b).

For (a), observe that $M$ is free over $\k[\xx]$, so 
$M\otimes_{\k[\xx']}\Delta_n(\xx',\xx'')$ is free over $\k[\xx,\xx'']$.
\end{proof}

Next, we discuss well-known multiplicative structure on $\HH$.

\begin{proposition}\label{prop:HH monoidal}
The functor $\HH$ has is lax monoidal, in the sense that we have a canonical multiplication map
\begin{equation}
\label{eq: multiplication HH}
\HH(M)\otimes \HH(N)\to \HH(M\star N).
\end{equation}
for bimodules $M,N\in R\text{-mod-}R$, satisfying appropriate naturality, associativity, and unit constraints.
\end{proposition}

\begin{proof}
This is well known, but we include the details for completeness.  We introduce sets of variables $\xx,\xx',\xx'',\xx'''$, so that each of $\k[\xx], \k[\xx'], \k[\xx''], \k[\xx''']$ may be regarded as a copy of $R$.  We regard $M$ as a module over $\k[\xx,\xx']$ and $N$ as a module over $\k[\xx'',\xx''']$.  For convenience we regard $R$ as a module over $\k[\xx',\xx'']$ (in which $x_i'-x_i''$ acts by zero for all $i$).  Thus, the tensor product $M\star N$ may be written as $M\otimes_{\k[\xx']} R\otimes_{\k[\xx'']} N$.

Now, the two sides of \eqref{eq: multiplication HH} may be computed as
\begin{align*}
    \HH(M) \otimes \HH(N) &= \left(M \otimes_{\k[\xx,\xx']} \Delta_n(\xx,\xx')\right) \otimes_\Q \left(N \otimes_{\k[\xx'',\xx''']} \Delta_n(\xx'',\xx''') \right) \\
    & \cong \left(M \otimes_\k N\right) \otimes_{\k[\xx,\xx',\xx'',\xx''']} \left( \Delta_n(\xx,\xx') \otimes_\Q \Delta_n(\xx'',\xx''')\right),
\end{align*}
where the isomorphism simply switches factors in the tensor product, and
\begin{equation*}
    \HH(M \otimes_{\k[\xx']} N) = (M \otimes_{\k[\xx']} R\otimes_{\k[\xx'']} N) \otimes_{\k[\xx,\xx''']} \Delta_n(\xx,\xx''').
\end{equation*}
The multiplication map is then a composite of two parts: first, the quotient identifying $x_i'$ with $x_i''$, and second the map
\begin{equation*}
    \left( \Delta_n(\xx,\xx') \otimes_\k \Delta_n(\xx'',\xx''') \right) / (x_i'-x_i'') \to \Delta_n(\xx,\xx''')
\end{equation*}
given by multiplication on the exterior algebras underlying the $\Delta_n$. This multiplication gives a chain map since, modulo $x_i'-x_i''$, $$(x_i - x_i') + (x_i'' - x_i''') = x_i-x_i'''.$$
Clearly the multiplication map just constructed is natural in the arguments $M,N$, since it involves only terms acting on the $\Delta_n$ so commutes with any map on the other tensor factors $M$ and $N$.
\end{proof}

Now, we forget its cohomological origins, and regard $\HH$ as a functor from $\SBim_n$ to $\Z_Q\times \Z_A$-graded $\k$-modules.  
%\MH{vector spaces? sorry i have no clue what coefficients we want at this point}  
\begin{definition}\label{def:HHH}
If $X\in \Ch(\SBim_n)$ then we let $\CHH(X)$ denote the $\Z_Q\times \Z_T\times \Z_A$-graded complex obtained by applying $\HH$ termwise to $X$.  Let $\HHH(X)$ denote the homology of $\CHH(X)$. 

For a braid $\b\in \Br_n$ we will abbreviate by writing $\CHH(\b):=\CHH(F(\b))$, and similarly for $\HHH(\b)$. 
\end{definition}


\begin{theorem}[\cite{KhSoergel}]
The homology $\HHH(\beta)$ is a topological invariant of the link obtained as the closure of $\beta$, up to an overall shift in tridegree.
\end{theorem}

\begin{remark}
We recall how to normalize $\HHH(\b)$ to obtain a well-defined link invariant.  Given $\b\in \Br_n$, let $e=e(\b)$ be the number of positive crossings minus the number of negative crossings, and let $c=c(\b)$ denote the number of components of the link represented by $\b$.  We define the \emph{normalizing exponent} of the braid $\b$ by the formula
\begin{equation}\label{eq:normalizing exponent}
\delta(\b):=\frac{1}{2}(e(\b)+c(\b)-n(\b)).
\end{equation} 
The normalized Khovanov--Rozansky complex of $\b$ is
\[
(a t^{-1/2}q^{-1/2})^{\delta(\b)} \Big(t^{(c-n)/2} \CHH(F(\b))\Big)
\]
\end{remark}

\begin{remark}
Sometimes we will need to emphasize the role of the coefficient ring $\k$ below. In this case, we will write $\HHH(\beta;\k)$ instead of $\HHH(\beta)$.
\end{remark}


\begin{example}
Recall that $O_n$ denotes the $n$-component unlink, which is the closure of the $n$-strand identity braid.  The associated Rouquier complex is $R$, and (using notation from \S \ref{ss:gradings}) we get
$$
\HHH(O_n)=\HH(R)=\k[\xx,\ttheta]
$$
\end{example}


The lax monoidal structure on the functor $\HH$ from Proposition \ref{prop:HH monoidal} immediately gives us a (degree zero, closed) multiplication map
\begin{equation}
\label{eq: multiplication HHH}
\CHH(X)\otimes \CHH(X')\to \CHH(X\star X').
\end{equation}

When $X=R$ and $X'=F^y(\b)$ we obtain the following corollary.

\begin{corollary}
There is an action of $\HHH(O_n)=\k[\xx,\ttheta]$ on $\HHH(\beta)$ for any $\beta$. If $w_{\beta}$ is the corresponding permutation then the action factors through
$$
\k[\xx,\ttheta]/(x_i-x_{w_{\beta}(i)},\theta_i-\theta_{w_{\beta}(i)}).
$$
\end{corollary}

\begin{proof}
The only nontrivial part is the relations for $x_i$ and $\theta_i$ which follow from \ref{lem: dot sliding} and \cite[Section 3.4]{GH}.
\end{proof}

\subsection{Rasmussen differentials}
\label{ss: Rasmussen}

In this section we recall the family of differentials $d_N$ on Hochschild homology of Soergel bimodules, constructed in \cite{RasDiff}. 
From now on we assume that $\k$ is a field of characteristic zero.

Recall that $p_{N+1}(\xx)=\sum_{i=1}^{n}x_i^{N+1}$ is the power sum in $x_i$.

\begin{lemma}\label{lemma:res and h}
Let $F^{\bullet}$ be a free resolution of $M\in \SBim_n$.  Then there exists $d_N\in \End(F^{\bullet})$ of weight $q^Na\inv$ such that $[d_F,d_N]=\frac{1}{N+1}(p_{N+1}(\xx)-p_{N+1}(\xx'))$. Moreover, $d_N$ is unique up to homotopy in the sense that if $(F'^{\bullet},d_N')$ is such pair and $\phi\colon F^{\bullet}\to F'^{\bullet}$ is a lift of $\id_M$, then $d_N'\circ \phi-\phi\circ d_N$ is closed and exact.  Furthermore, $d_N\circ d_N$ is closed and exact.
\end{lemma}
\begin{proof}
Let $F^{\bullet}$ be a free resolution of $M$.  We know that $\frac{1}{N+1}(p_{N+1}(\xx)-p_{N+1}(\xx'))$ acts by zero on $M$, hence is null-homotopic when regarded as an endomorphism of $F^{\bullet}$.  This shows that $d_N$ exists.  Now, let $F'^{\bullet}$ be another free resolution, with homotopy $d_N'\in \End(F'^{\bullet})$.  Since $[[d_F,d_N],\phi]=0$, it follows that $[d_F,[d_N,\phi]]=0$.  In other words, $[d_N,\phi]$ a closed element of $\Hom(F^{\bullet},F'^{\bullet})$ of weight $q^Na\inv$.  The homology of $\Hom(F^{\bullet},F'^{\bullet})$ is isomorphic to the ext algebra $\Ext(M,M)$, which has no nonzero elements of negative $A$-degree.  This shows that $[d_N,\phi]$ is exact, as claimed.  A similar argument shows that $d_N^2$ is exact.
\end{proof}

Given a free resolution $F^{\bullet}$ and endomorphism $d_N$ as above, $d_N$ becomes closed when acting on $F^{\bullet}\otimes_{\k[\xx,\xx']} R$.  Recall that by Proposition \ref{prop: Tor invariance} the homology of this complex $F^{\bullet}\otimes_{\k[\xx,\xx']} R$ is isomorphic to $a^{-n}\HH(M)$. Since $d_N^2$ is exact on $F^{\bullet}$, we get $d_N^2=0$ on $\HH(M)$ and we can regard $d_N$ as a differential on $\HH(M)$. By Lemma \ref{lemma:res and h} it does not depend on a choice of resolution $F^{\bullet}$.

\begin{definition}\label{def:dN general}
Given $M\in \SBim_n$, let $d_N$ denote the endomorphism of $\HH(M)$ induced from the $d_N$ from Lemma \ref{lemma:res and h} on a free resolution $F$ of $M$.  Let $\HH_{\gll_N}(M):=\tw_{d_N}(\HH(M))$ denote the complex $\HH(M)$ with differential given by $d_N$.  We regard $\tw_{d_N}(\HH(M))$ as graded by the group
\[
\Z_Q\times \Z_T \ \cong \ \Z_Q\times \Z_T\times \Z_A/(2+2N,-1,-1)
\]
\end{definition}
When ``turning on'' the differential $d_N$, we must collapse the trigrading to a bigrading as in the above, since the weight of all differentials ought to be $T$, but the weight of $d_N$ is $Q^{2+2N}A\inv$.

It will be useful to have a concrete model for $\tw_{d_N}(\HH(M))$.  To this end, recall the definition of $\Delta_n(\xx,\xx')$ from \S \ref{ss:HH}. By Lemma \ref{lem: examples resolutions} $M\star \Delta_n(\xx,\xx')$ is a free resolution of $M$ over $\k[\xx,\xx']$, so we can use it as a model for $F^{\bullet}$.

Define an endomorphism $d_N$ of $\Delta_n(\xx,\xx')$ by
\begin{equation}
\label{eq: dN Koszul}
    d_N(\theta_i) = \frac{1}{N+1}h_{N}(x_i,x_i')
\end{equation}
and extend to the rest of $\Delta_n(\xx,\xx')$ via the graded Leibniz rule. Note that $\wt(d_N)=q^N a\inv$. This will not be a chain map, but $d_N^2 = 0$ and $d_{\HH}d_N + d_Nd_{\HH} =\frac{1}{N+1}( p_{N+1}(\xx) - p_{N+1}(\xx'))$ (so $d_{\HH} + d_N$ turns $\Delta_n$ into a matrix factorization; this is the $\gll_N$-matrix factorization associated to $n$ vertical arcs in \cite{RasDiff}). However, on any Soergel bimodule $M$, the difference $p_{N+1}(x_i) - p_{N+1}(x_i')$ vanishes, so $d_N$ yields a well defined chain map on $M\otimes_{\k[\xx,\xx']} \Delta_n(\xx,\xx')$.  Taking homology yields the action of $d_N$ on $\HH(M)=H\left(M\otimes_{\k[\xx,\xx']}\Delta_n(\xx,\xx')\right)$. 

\begin{example}
\label{ex: dN unknot}
For $M=R$ we get $\HH(M)=\k[\xx,\ttheta]$. The differential $d_N$ is given by
$$
d_N(\theta_i)=x_i^N
$$
which is a specialization of \eqref{eq: dN Koszul} at $\xx=\xx'$.
\end{example}

The following is clear from definitions:
\begin{proposition}\label{prop:HH with dN is functor}
For bimodules $M,N\in \SBim_n$, any bimodule map $f\colon M\to N$ defines a map $\HH(f):\HH(M)\to \HH(N)$ which commutes with $d_N$.  In other words, $\HH_{\gll_N}$ is a functor from $\SBim_n$ to the category of $\Z_Q\times \Z_A$-graded modules over the exterior algebra $\k[d_N]$ (where $d_N$ has weight $\wt(d_N)=Q^{2+2N}A\inv=q^Na\inv$).
\end{proposition}

Furthermore, $d_N$ interacts well with the multiplicative structure.

\begin{lemma}
\label{lem: bimodule dN multiplicativity}
    For Soergel bimodules $M,M'$, the multiplication map
    \begin{equation*}
        \HH(M) \otimes \HH(M') \to \HH(M \star M')
    \end{equation*}
    commutes with $d_N$, where $d_N$ acts on the left via the graded Leibniz rule.  In other words, the functor $\HH_{\gll_N}$ is lax monoidal with respect to the usual tensor product on modules over the Hopf algebra $\k[d_N]$.
\end{lemma}

\begin{proof}
We we need to prove that the diagram:
$$
\begin{tikzcd}
\Delta_n(\xx,\xx')\otimes_{\k[\xx']} \Delta_n(\xx',\xx'') \arrow{r}{m} \arrow{d}{d_N} \arrow[dotted]{dr}{\nu}& \Delta_n(\xx,\xx'') \arrow{d}{d_N}\\
\Delta_n(\xx,\xx')\otimes_{\k[\xx']} \Delta_n(\xx',\xx'') \arrow{r}{m}& \Delta_n(\xx,\xx'')
\end{tikzcd}
$$
with horizontal arrows given by multiplication and vertical by $d_N$, commutes up to homotopy. Recall that on $\Delta_n(\xx,\xx')$ we have $[d_{\HH},d_N]=p_{N+1}(\xx)-p_{N+1}(\xx')$. Therefore on $\Delta_n(\xx,\xx')\otimes_{\k[\xx']} \Delta_n(\xx',\xx'')$ we have
$$
[d_{\HH},d_N]=\frac{1}{N+1}(p_{N+1}(\xx)-p_{N+1}(\xx'))+\frac{1}{N+1}(p_{N+1}(\xx')-p_{N+1}(\xx''))=
$$
$$
\frac{1}{N+1}(p_{N+1}(\xx)-p_{N+1}(\xx'')).
$$
In particular, $[d_{\HH},d_N]$ commutes with $m$ and 
$$
[d_{\HH},d_N\circ m-m\circ d_N]=0.
$$
Now $d_N\circ m-m\circ d_N$ is a chain map of $A$-degree $-1$, but the corresponding $\Ext^{-1}$ group vanishes (there are no negative $\Ext$ between modules over polynomial rings), so $d_N\circ m-m\circ d_N$ is nullhomotopic.
\end{proof}

See also \cite{Becker} for a closely related lax monoidal functor on Soergel bimodules.

\begin{remark}
Alternatively, one can construct a nullhomotopy $\nu$ for $[d_N,m]$ explicitly by writing
$$
\nu(\theta_i\otimes \theta_j)=\delta_{i,j}h_{N-1}(x_i,x'_i,x''_i).
$$
We have  
$$
d_N(m(\theta_i\otimes 1))-m(d_N(\theta_i\otimes 1))=h_{N}(x_i,x''_i)-h_{N}(x_i,x'_i)=(x''_i-x'_i)h_{N-1}(x_i,x'_i,x''_i).
$$
On the other hand, 
$$
\nu(d(\theta_i\otimes 1))=\nu(\sum_{j\neq i}(x_j-x'_j)\theta_i\theta_j\otimes 1)-\nu(\sum_{j}(x'_j-x''_j)\theta_i\otimes \theta_j)=0-(x'_i-x''_i)h_{N-1}(x_i,x'_i,x''_i).
$$
Similarly,
$$
d_N(m(1\otimes \theta_i))-m(d_N(1\otimes \theta_i))=h_{N}(x_i,x''_i)-h_{N}(x_i',x''_i)=
$$
$$
(x_i-x'_i)h_{N-1}(x_i,x'_i,x''_i)=\nu(d(1\otimes \theta_i)).
$$
One can now check that $\nu$ extends to the map between exterior algebras such that 
$$
d_N\circ m-m\circ d_N=-[d,\nu]
$$
and the result follows. 
\end{remark}

Now we can define our version of the Rasmussen spectral sequence \cite{RasDiff}. 
\begin{definition}\label{def:slN homology}
For a complex $X\in \Ch(\SBim_n)$, we let $\CHH_{\gll_N}(X)$ be the double complex $\CHH(X)$ with horizontal differential $\HH(d_X)$ and vertical differential given by $d_N$. Let $C_{\gll_N}(X)=\mathrm{Tot}(\CHH_{\gll_N}(X))$.  Denote the homology of this complex by $H_{\gll_N}(X)$. 
\end{definition}
Note that $C_{\gll_N}(X)$ is graded by $\Z_Q\times\Z_T\times\Z_A/(2+2N,-1,-1)$. 


\begin{definition}\label{def:Rasmussen SS}
 Given a complex $M\in \Ch(\SBim_n)$, the Rasmussen spectral sequence is that of a double complex, with terms given by $\CHH^{\bullet,k,i}(M)$ %\MH{upper indices ok?} 
 horizontal differential $\HH(d_M)$ and vertical differential $d_N$, converging to $H_{\gll_N}(M)$.  %entries $\HH_k(M_i)$, horizontal differentials $\HH_k(d)$ induced by the original differential, and vertical differential $d_N$.
\end{definition}

\begin{remark}
\label{rmk: Rasmussen}
    In \cite{RasDiff}, Rasmussen originally defined these $d_N$ differently, by working with particular free resolutions $F_i^\bullet$ of each $B_i$, and building the homotopy $h$ as in Lemma~\ref{lemma:res and h} on $F_{i_1}^\bullet \star \cdots \star F_{i_n}^\bullet$ via a concrete choice of $h$ for each $F_i^\bullet$. Lemma~\ref{lem: examples resolutions} and Proposition \ref{prop: Tor invariance} now say that the complex coming from closing up $F_{i_1}^\bullet \star \cdots \star F_{i_n}^\bullet$, which in \cite{RasDiff} is called the positive homology of a MOY graph, agrees with $\CHH(M)$. Similarly, $\HH(d_M)$ agrees with Rasmussen's $d_v$, and, using Lemma~\ref{lemma:res and h}, $d_N$ agrees with Rasmussen's $d_-$. (Note that our conventions for which of the two differentials in this double complex should be drawn vertically are reversed). All of this is more-or-less the statement (see Proposition \ref{prop: Tor invariance}) that $\HH(M)$ may be computed either by resolving $M$ or by resolving the diagonal; we work with a resolution of the diagonal so that all of the constructions manifestly commute with any map of Soergel bimodules.

    In particular, while what we call $H_{\gll(N)}$ above does not obviously agree with the original Khovanov--Rozansky definition of $\gll(N)$ link homology from \cite{KR2}, it does agree with the group to which the spectral sequence from \cite{RasDiff} converges. Rasmussen's detailed arguments from \cite{RasDiff} about the collapse of this spectral sequence on a fixed Soergel bimodule (as opposed to a complex) are then needed to show that this $H_{\gll(N)}$ agrees with the version from \cite{KR2}.
\end{remark}

\begin{proposition}
\label{prop: braid dN multiplicativity}
    For braids $\beta$, $\beta'$, the multiplication map
    \begin{equation*}
        \HHH(\beta) \otimes \HHH(\beta') \to \HHH(\beta \beta')
    \end{equation*}
    commutes with all pages of the Rasmussen $\gll_N$ spectral sequence. 
\end{proposition}

\begin{proof}
The multiplication map $\HHH(\beta) \otimes \HHH(\beta') \to \HHH(\beta \beta')$ is just column-by-column the multiplication map on Hochschild homology, so commutes with both differentials of the double complex by Lemma~\ref{lem: bimodule dN multiplicativity}. Therefore, it commutes with the differential on each page of the spectral sequence.
\end{proof}




\subsection{$y$-ified homology and spectral sequences}

Next we recall the deformed (or $y$-ified) triply graded link homology from \cite{GH}.

\begin{definition}\label{def:HY}
Given $\tw_\alpha(X)\in \mathcal{Y}_{n,w}$, we let
\[
\CY(\tw_\alpha(X)):= \HH(X)\cotimes\k[\yy]/ (y_i = y_{w(i)})_{1\leq i\leq n}
\]
with differential given by applying the functor $\HH$ componentwise to the total differental $d_X+\alpha$. Then $\CY(\tw_\alpha(X))$ is a $\Z_Q\times \Z_T\times \Z_A$-graded complex; we denote the homology of this complex by $\HY(\tw_\alpha(X))$.
 If $X=F^y(\b)$ then we will abbreviate by writing $\CY(\b):=\CY(F^y(\b))$, and similarly for $\HY(\b)$.
\end{definition}
\begin{definition}
Similarly we let
\[
\CY_{\gll_N}(\tw_\alpha(X)):= C_{\gll_N}(X)\cotimes\k[\yy] / (y_i = y_{w(i)})_{1\leq i\leq n}
\]
with differential given by applying the functor $\HH_{\gll_N}$ componentwise to the total differential $d_X+\alpha$.  This is a graded by $\Z_Q\times \Z_T\times \Z_A/(2+2N,-1,-1)$.

 If $X=F^y(\b)$ then we will abbreviate by writing $\CY_{\gll_N}(\b):=\CY_{\gll_N}(F^y(\b))$, and similarly for $\HY_{\gll_N}(\b)$. 
\end{definition}

\begin{remark}\label{rmk:poly 2}
As mentioned already in Remark \ref{rem: poly 1}, if $X$ is such that $\HH^{i+2L,j-2L,k}(X)=0$ for $L\gg 0$, then every element of $\CY$ is polynomial, i.e.~ $\CY(\tw_\alpha(X)) = \HH(X)\otimes \k[y_1,\ldots,y_n]$.  This is the case whenever $X$ is a bounded complex.
\end{remark}

\begin{theorem}\label{thm:HY}[\cite{CK,GH}]
If $\b$ and $\b'$ represent the same link, then $\CY(\b)\simeq\CY(\b')$ and $\CY_{\gll_N}(\b)\simeq\CY_{\gll_N}(\b')$  up to an overall shift in tridegree.
\end{theorem}

\begin{remark}
    In fact, once it is known that $\CY(\beta)$ and $\HH_{\gll_N}(\beta)$ are link invariants, there is nothing further to check to see that $\CY_{\gll_N}$ is: since we know from Proposition~\ref{prop:HH with dN is functor} that the action of $d_N$ on complexes of Soergel bimodules is functorial, the isomorphisms $\CY(\beta) \cong \CY(\beta')$ when $\beta$ and $\beta'$ differ by a second or third Reidemeister move automatically commute with $d_N$ and so descend to $\CY_{\gll_N}$. Therefore, the only possible issue is with the first Reidemeister move, but here the relation $y_i = y_{w(i)}$ makes all terms with $y$'s drop out of the relevant part of the differential, and now the proof is identical to the one for $\HH_{\gll_N}$.
\end{remark}

\begin{proposition}\label{prop:CY is multipicative}
The constructions $X\mapsto \CY(X)$ and $X\mapsto \CY_{\gll_N}(X)$ are multiplicative  (lax monoidal) in the following sense.  Given $\tw_{\alpha}(X),\tw_{\alpha'}(X')\in \mathcal{Y}_{n,1}$ we have chain maps
\[
\CY(\tw_{\alpha}(X))\otimes \CY(\tw_{\alpha'}(X')) \to \CY(\tw_{\alpha}(X)\star \tw_{\alpha'}(X'))
\]
(and similarly for $\CY_{\gll_N}$) satisfying appopriate associativity and unit constraints.
\end{proposition}
\begin{proof}
This follows from the fact that the multiplication $\HH(M)\otimes \HH(M')\to \HH(M\star M')$ is natural in $M$ and $M'$ (Proposition \ref{prop:HH monoidal}), and commutes with with $d_N$ (Lemma \ref{lem: bimodule dN multiplicativity}).
\end{proof}

\begin{lemma}(\cite[Theorem 4.20]{GH})
\label{lem: parity}
Assume that $\k$ is a field, $\tw_{\alpha}(X)\in \mathcal{Y}_{n,w}$ and $\HHH(X)$ is supported in {\bf even} homological degrees. Then we have an isomorphism of $\k[\yy]$-modules
$$
\HY(\tw_{\alpha}(X))=\HHH(X)\cotimes\k[\yy] / (y_i = y_{w(i)})_{1\leq i\leq n} 
$$
and an isomorphism of $\k$-vector spaces
$$
\HHH(X)=\HY(X)/(y_1,\ldots,y_n).
$$
\end{lemma}

Note that \cite{GH} did not use completed tensor product since it focused on bounded complexes. Nevertheless, the same arguments apply verbatim if we use bounded above complexes and completed tensor product. 

\section{Projectors and symmetric colored homology}


\subsection{Categorified symmetrizers}
\label{ss:Pn}


We recall some constructions from \cite{Hog,idempotents}.  

\begin{definition}\label{def:Pn}
Define $\PP_n\in \Ch^-(\SBim_n)$ by the formula
\[
\PP_n \ := \ \left[\cdots \to T^{-3}\bigoplus_{i_1,i_2,i_3} B_{i_1}\star B_{i_2}\star B_{i_3}\to T^{-2}\bigoplus_{i_1,i_2} B_{i_1}\star B_{i_2} \to T\inv \bigoplus_{i_1} B_{i_1}\to \underline{R}\right]
\]
in which the indices $i_j$ range from $1$ to $n-1$, 
and the differential is an alternating sum $\sum_{j=1}^r(-1)^{j-1}\id^{\star j-1}\star b_{i_j}\star \id^{\star r-j}$. We will be often omitting the tensor product symbol $\star$ for brevity.

Let $\upsilon\colon R\to \PP_n$ denote the inclusion of the degree zero bimodule.
\end{definition}

\begin{theorem}\label{thm:P unique}(\cite{Hog,idempotents})
The complex $\PP_n$ is uniquely characterized up to homotopy equivalence in $\Ch^-(\SBim_n)$ by (1) $\PP_n\star B_i\simeq 0 \simeq B_i\star \PP_n$ for all $1\leq i\leq n-1$ and (2) there exists a chain map $\upsilon\colon R\to \PP_n$ such that $\Cone(\upsilon)$ is homotopy equivalent to a complex whose chain groups are (direct sums of shifts of) nontrivial tensor products of the $B_i$.\qedhere
\end{theorem}

The complex $\PP_n$ admits the structure of a dg algebra object in $\Ch^-(\SBim_n)$, with multiplication given componentwise by concatenation
\begin{equation}\label{eq:concatenate Bs}
(B_{i_1}\cdots  B_{i_r})\star (B_{j_1} \cdots  B_{j_s})\buildrel\cong\over\to B_{i_1} \cdots B_{i_r} B_{j_1}\cdots  B_{j_s},
\end{equation}
and unit map given by $\upsilon\colon R\to \PP_n$.

One of the main results in \cite{Hog} is the computation of $\End(\PP_n)$ and $\HHH(\PP_n)$.

\begin{theorem}\label{thm:end Pn}(\cite{Hog})
We have quasi-isomorphisms of dg algebras 
$$
\End(\PP_n;\Z)\simeq \Hom(R,\PP_n)\simeq \Z\left[\widetilde{u}_0,\ldots,\widetilde{u}_{n-1}\right]
$$ 
where the $\widetilde{u}_i$ are even variables of weight $qt^{1-i}$. Moreover, 
$$
\HHH(\PP_n;\Z)\simeq \Z\left[\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\dots,\widetilde{\xi}_{n-1}\right]
$$ 
where the $\widetilde{\xi}_i$ are odd variables of weight $at^{1-i}$.
\end{theorem}



Next, we define a lift of $\PP_n$ to the category $\mathcal{Y}_{n,1}$.  For each linear polynomial $f\in R$, let $\eta_f\in \End(\PP_n)$ be the weight $T\inv$ endomorphism defined as follows.  Given a sequence $i_1,\ldots,i_r$ and an index $1\leq j\leq r$, let $(\eta_f)_{i_1,\ldots,i_j,\ldots,i_r}^{i_1,\ldots,i_j,i_j,\ldots,i_r}$ be the composition of maps
\[
\begin{tikzpicture}
\node (a) at (0,0) {$B_{i_1}\cdots B_{i_j}\cdots B_{i_r}$};
\node (b) at (6,0) {$B_{i_1}\cdots B_{i_j}B_{i_j}\cdots B_{i_r}$};
\node (c) at (12,0) {$B_{i_1}\cdots B_{i_j}B_{i_j}\cdots B_{i_r}$};
\path[-stealth]
(a) edge node[above] {\tiny$\id^{\star j-1}\star \Delta \star \id^{\star r-j}$} (b)
(b) edge node[above] {\tiny$\id^{\star j}\star f\star \id^{\star r-j}$} (c);
\end{tikzpicture}
\]
where the $\Delta$ here is the comultiplication $B_{i_j}\to B_{i_j}\star B_{i_j}$ and in the second map, $f$ acts by ``middle multiplication'' on $B_{i_j}\star B_{i_j}$.   Then we let $\eta_f$ be the sum of all such maps, over all sequences $i_1,\ldots,i_r\in \{1,\ldots,n-1\}$ and all indices $1\leq j\leq r$, times the sign $(-1)^{j-1}$.

 It is a straightforward exercise to verify that $[d_{\PP},\eta_f]=f(\xx)-f(\xx')$, and that the $\eta_f$ anti-commute and square to zero.  Let us abbreviate by writing $\eta_i:=\eta_{x_i}$.   Thus, we have a well defined lift
\[
\PP_n^y := \tw_{\sum_i \eta_iy_i}(\PP_n) \in \mathcal{Y}_{n,1}
\]

The deformed projector $\PP_n^y$ has the structure of a dg algebra object in $\mathcal{Y}_{n,1}$, with multiplication and units defined by the exact same formulas for $\PP_n$.

The following says that lifts of $\PP_n$ to $\mathcal{Y}_{n,1}$ are unique up to equivalence.
\begin{theorem}\label{thm:Py unique}
Suppose $\PP_n', \PP_n$ are two different models for the symmetrizer, and suppose $\tw_{\alpha}(\PP_n)$, $\tw_{\alpha'}(\PP_n')$ are lifts to objects of $\mathcal{Y}_{n,1}$. 
 Then $\tw_{\alpha}(\PP_n)\simeq \tw_{\alpha'}(\PP_n')$.
\end{theorem}
\begin{proof}
The complexes $\PP_n'$ and $\PP_n$ are homotopy equivalent by the unique characterization from Theorem \ref{thm:P unique}.  By Theorem \ref{thm:end Pn} all elements of $\Hom(\PP_n,\PP_n')$ of weight $T^{1-2r}Q^{2r}$ vanish, so by Lemma \ref{lemma:uniqueness of lifts} we get  $\tw_{\alpha}(\PP_n)\simeq \tw_{\alpha'}(\PP_n')$.
\end{proof}



The following are some useful properties of $\PP_n^y$.
\begin{proposition}\label{prop:Py is idempt}
The $y$-ified symmetrizer $\PP_n^y$ is a unital idempotent in $\mathcal{Y}_{n,1}$.
\end{proposition}
\begin{proof}
We must show that $\PP_n^y\star \Cone(\one_n\to \PP_n^y)\simeq 0 \simeq \Cone(\one_n\to \PP_n^y)\star \PP_n^y$.  Both of these homotopy equivalences follow from their undeformed versions \cite{Hog}, by Lemma \ref{lemma:lift of equiv}.
\end{proof}

\begin{proposition}\label{prop:Py is central}
$\PP_n^y$ has the structure of an object in the Drinfeld center of the triangulated monoidal category $\bigoplus_w H^0(\mathcal{Y}_{n,w})$.
\end{proposition}
\begin{proof}
For any $X^y\in \mathcal{Y}_{n,w}$ we have homotopy equivalences
\[
X^y\star \PP_n^y\rightarrow \PP_n^y\star X^y\star \PP_n^y\leftarrow \PP_n^y\star X^y
\]
given by applying the unit map of $\PP_n^y$ on the left (respectively right) of $X^y$ as in \cite[Theorem 4.23]{idemptriang}. These homotopy equivalences are obviously natural in $X^y$.
\end{proof}

\begin{corollary}
Let $X_1^y,X_2^y\in \mathcal{Y}_{n,w}$ be such that $X_2^y\star \PP^y_n\simeq X_2^y$.  Then
\[
\Hom(X_1^y\star \PP^y_n , X_2^y)\simeq \Hom(X_1^y, X_2^y)
\]
\end{corollary}
\begin{proof}
See \cite[Proposition 4.16]{idemptriang}.
\end{proof}
In the special case $X_1^y=X_2^y=R$, we have the following.

\begin{lemma}\label{lem:end Pn y}
We have quasi-isomorphisms of dg algebras 
$$
\End_{\mathcal{Y}_{n,1}}(\PP_n^y;\Z)\simeq \Hom_{\mathcal{Y}_{n,1}}(R,\PP_n^y)\simeq \Z\left[\yy,\widetilde{u}_0,\ldots,\widetilde{u}_{n-1}\right]
$$ 
where the $\widetilde{u}_i$ are even variables of weight $qt^{1-i}$. Moreover, 
$$
\HY(\PP_n^y;\Z)\simeq \Z\left[\yy,\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\dots,\widetilde{\xi}_{n-1}\right]
$$ 
where the $\widetilde{\xi}_i$ are odd variables of weight $at^{1-i}$.
\end{lemma}

\begin{proof}
We prove the last statement about $\HY$, the proofs of other statements are identical.
By Lemma \ref{lem: parity} and Theorem \ref{thm:end Pn} we have
\begin{equation}
\label{eq: HY Pn completed}
\HY(\PP_n^y;\Z)\simeq \Z\left[\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\dots,\widetilde{\xi}_{n-1}\right]\cotimes\Z[\yy].
\end{equation}
It remains to check that the completed tensor product with $\Z[\yy]$ coincides with the usual one.
Let us describe the subspace of homogeneous elements with weight $a^{k}q^{m}t^{s}$ in \eqref{eq: HY Pn completed}. Recall that $\widetilde{u}_i$ have weight $qt^{-i}$ and $\widetilde{\xi}_i$ have weight $at^{-i}$. The $(a,q)$-weights determine the monomials in $\widetilde{\uu}$ and $\widetilde{\xx_i}$ which might appear, and the degree in $\yy$ is determined from the $t$-weight. 

Therefore the homogeneous subspace
is spanned by the expressions
\begin{equation}
\label{eq: basis HY}
\widetilde{u}_{i_1}\cdots \widetilde{u}_{i_m}\widetilde{\xi}_{j_1}\cdots \widetilde{\xi}_{j_k}g(\yy)
\end{equation}
where $g(\yy)$ is a homogeneous polynomial of degree $i_1+\ldots+i_m+j_1+\ldots+j_k+s$. Here $k,m\ge 0$ and $s\in \Z$, but we sum over terms with
$i_1+\ldots+i_m+j_1+\ldots+j_k\ge -s$.
In particular, this subspace  is finite-dimensional for fixed $k,m,s$ and 
$$
\Z[\widetilde{\uu},\widetilde{\xxi}]\cotimes\Z[\yy]=\Z[\yy,\widetilde{\uu},\widetilde{\xxi}].
$$
\end{proof}



\subsection{Symmetrizers and Rouquier complexes}
\label{ss:symmetrizer and Rouquier}

Let $e\colon \Br_n\to \Z$ be the group homomorphism sending $\sigma_i^{\pm}\mapsto \pm 1$ for all $i$.

\begin{definition}
Let $\sT(\b):=(TQ\inv)^{-e(\b)} F(\b)$ and $\sTy(\b):=(TQ\inv)^{-e(\b)} F^y(\b)$.
\end{definition}

Note that the unique copy of $R$ sits in degree zero in $\sT(\b)$ and $\sTy(\b)$. Also, it is clear that
$$
\sTy(\beta)\star \sTy(\gamma)=\sTy(\beta\gamma).
$$

\begin{proposition}\label{prop:twisted projectors}
There exists an object $\PP_{n,w}^y\in \mathcal{Y}_{n,w}$, depending on a choice of permutation $w\in S_n$, with the property that $\sT^y(\b)\star \PP_n^y\simeq  \PP_{n,w}^y$ for any braid $\b\in \Br_n$ with underlying permutation $w$.
\end{proposition}

\begin{proof}
Suppose that $\beta=\beta_1\sigma_i\beta_2$ and $\beta'=\beta_1\sigma_i^{-1}\beta_2$, it is sufficient to show that $\sTy(\beta)$ and $\sTy(\beta')$ become homotopy equivalent after tensoring with $\PP_n^y$.
For this, recall the map $\rho_i\colon (TQ\inv) \yTii\to(TQ\inv)\inv \yTi$ from Lemma \ref{lem: skein}.  The cone of this map is homotopy equivalent to a deformation of a complex constructed from two copies of $B_i$. We get a map
$$
\Id_{\beta_1}\star \rho_i\star \Id_{\beta_2}:\sTy(\beta')\to \sTy(\beta)
$$
with the cone filtered by $F^y(\beta_1)\star B_i\star F^y(\beta_2)$. Therefore $\Cone(\Id_{\beta_1}\star \rho_i\star \Id_{\beta_2})$ belongs to the tensor ideal generated by $B_i$ and becomes contractible after tensoring with $\PP_n^y$: this follows from Lemma \ref{lemma:lift of equiv} together with the annihilating properties of $\PP_n$ from Theorem \ref{thm:P unique}.  This shows that $\Id_{\beta_1}\star \rho_i\star \Id_{\beta_2}$ becomes a homotopy equivalence after tensoring with $\PP_n^y$, and the proposition follows.
\end{proof}



Proposition \ref{prop:twisted projectors} says that $\sTy(\b)\star \PP_n^y\simeq \PP_{n,w}^y$ depends only on the permutation $w$ represented by $\b$, up to homotopy equivalence.  Precomposing with the unit map of $\PP_n^y$ gives us a map $\upsilon_{\b}:\sTy(\b)\to \PP_{n,w}^y$. More precisely, we get the following result.

\begin{theorem}\label{thm:map of diagrams}
There is a family of maps $\mu_{w,v}\colon \PP^y_{n,w}\star \PP^y_{n,v}\to \PP^y_{n,wv}$, $\upsilon_\b\colon \sTy(\b)\to \PP_{n,w}^y$ such that 
\begin{enumerate}
\item $\upsilon_{\one_n}=\upsilon_n$. %\MH{notation for identity braid?}
\item the $\mu_{w,v}$ are homotopy equivalences.
\item the $\mu_{w,v}$ satisfy the associative axiom up to homotopy.
\item the $\mu_{w,v}$ satisfy the unit axiom up to homotopy, with unit given by $\upsilon_n$.
\item the following diagram commutes up to homotopy for any braids $\b,\gamma\in \Br_n$ with underlying permutations $w,v\in S_n$:
\[
\begin{tikzpicture}
\node (a) at (0,0) {$\sTy(\b)\star \sTy(\gamma)$};
\node (b) at (4,0) {$\sTy(\b\gamma)$};
\node (c) at (0,-2) {$\PP^y_{n,w}\star \PP^y_{n,v}$};
\node (d) at (4,-2) {$\PP^y_{n,wv}$};
\path[-stealth]
(a) edge node[above] {} (b)
(c) edge node[above] {$\mu_{w,v}$} (d)
(a) edge node[left] {$\upsilon_\b\star \upsilon_\gamma$} (c)
(b) edge node[right] {$\upsilon_{\b\gamma}$} (d);
\end{tikzpicture}
\]
\end{enumerate}
\end{theorem}
\begin{proof}
Fix a permutation $w\in S_n$. Let $\pi\colon \Br_n\to S_n$ denote the canonical projection. The complexes $\sTy(\b)\star \PP^y_n$ with $\b\in \pi\inv(w)$  are all homotopy equivalent by Proposition \ref{prop:twisted projectors}.  If $\b,\b'\in\pi\inv(w)$ then the hom complex from $\sTy(\b)\star \PP^y_n$ to  $\sTy(\b')\star \PP^y_n$ is homotopy equivalent to
\[
\Hom\left(\sTy(\b)\star \PP^y_n, \sTy(\b')\star \PP^y_n\right) \simeq \Hom\left(\PP^y_n, \sTy(\b\inv \b')\star \PP^y_n\right)\simeq 
\]
\[
\End(\PP^y_n)\simeq \k[\yy,\widetilde{u}_0,\cdots,\widetilde{u}_{n-1}]
\]
where we have used the fact that $\b\inv\b'$ is a pure braid, as well as Lemma \ref{lem:end Pn y}.  In particular, in bidegree $(0,0)$ this hom space is $\k$.  Thus, any two homotopy equivalences $\phi_1,\phi_2\colon\sTy(\b)\star \PP^y_n\simeq \sTy(\b')\star \PP^y_n$ must be homotopic up to an invertible scalar.  We can fix the scalar by requiring that the unique copies of $R$ be mapped to each other by $\id$.

Now, we compute if $\b\in \pi\inv(w)$ and $\gamma\in \pi\inv(v)$ then
\begin{align*}
\PP^y_{n,w}\star \PP^y_{n,v}&=\sTy(\b_w)\star \PP^y_n \star \sTy(\b_v)\star \PP^y_n\\
&\simeq \sTy(\b)\star \sTy(\gamma)\star \PP^y_n\star \PP^y_n \simeq  \sTy(\b\gamma)\star \PP^y_n \simeq \PP^y_{n,wv}
\end{align*}
When in the second line we used the centrality and idempotence of $\PP^y_n$.  All of the above homotopy equivalences are unique in their bidegree, up to homotopy and invertible scalar.  The invertible scalar can be fixed by requiring, as always, that the unique copies of $R$ be mapped to each other via $\id$.  This defines $\mu_{w,v}$.

The asserted properties are all straightforward to check.
\end{proof}

\begin{remark}
Un-$y$-ified, the maps $\mu_{w,v}$ are all the standard multiplication on $\PP_n$, and the maps $\upsilon_\b$ are easily defined by explicit formulas.
\end{remark}

\subsection{Colored homology: definition and invariance}
\label{sec: colored homology}
We can use the projectors $\PP_n^y$ to defined $y$-ified symmetric-colored link homology following \cite{CooperKrushkal} (see also \cite{Cautis,Hog,HM,Rozansky}).


Fix a braid $\b\in \Br_m$, and let $w\in S_m$ be the permutation represented by $\b$.  Let $L=\hat{\b}$ be the braid closure. The set of components of $L$ can be identified with $\{1,\ldots,m\}/\sim$, where $\sim$ is the equivalence relation generated by $i\sim w(i)$ for all $i$. For each $1\leq i\leq m$ let $[i]$ denote the equivalence class containing $i$ (i.e.~the component of $\hat{\b}$ containing the $i$-th strand of $\b$).


Fix a sequence $\vec{n}=(n_1,\ldots, n_m)\in \Z_{\geq0}^m$.  We say that $\vec{n}$ is \emph{closeable} if $n_i=n_{w(i)}$ for all $i$; in this case we write $\mathbf{n}\colon \pi_0(L)\to\Z_{\geq0}$ for the induced map.  

Let $\beta^{(n_1,\ldots,n_m)}$ be the braid on $\sum_{i=1}^{m}n_i$ strands obtained by cabling $\beta$: the strand indexed by $i$ is replaced by $n_i$ parallel copies of the same strand (with respect to the blackboard framing).   For example, for the elementary Artin braid generator $\sigma_1\in \Br_2$ we have
\[
\sigma_1^{n_1,n_2} := (\sigma_{n_1}\cdots \sigma_2\sigma_1) \cdots (\sigma_{n_1+n_2}\cdots \sigma_{2+n_2}\sigma_{1+n_2})  = 
\begin{tikzpicture}[scale=1.5,baseline=.5cm]
\draw[very thick]
(1,0) -- (0,1)
(1.3,0) -- (.3,1)
(1.6,0) -- (.6,1);
\draw[line width=5pt,white]
(0,0) -- (1,1)
(.2,0) -- (1.2,1)
(.4,0) -- (1.4,1)
(.6,0) -- (1.6,1);
\draw[very thick]
(0,0) -- (1,1)
(.2,0) -- (1.2,1)
(.4,0) -- (1.4,1)
(.6,0) -- (1.6,1);
\node at (0,1.1) {\scriptsize$1$};
\node at (.3,1.1) {\scriptsize$\cdots$};
\node at (.6,1.1) {\scriptsize$n_1$};
\node at (1,1.1) {\scriptsize$1$};
\node at (1.3,1.1) {\scriptsize$\cdots$};
\node at (1.6,1.1) {\scriptsize$n_2$};
\end{tikzpicture}
\in \Br_{n_1+n_2}
\]

If $\vec{n}$ is closeable, then the closure of $\beta^{\vec{n}}$ is the $\mathbf{n}$-cable of $L$.


\begin{definition}
\label{def: symmetric colored homology}
Let $\b\in \Br_m$ and let $\vec{n}=(n_1,\ldots,n_m)\in \Z_{\geq 0}^m$ be closeable. We define $S^{\mathbf{n}}$-colored $y$-ified homology of $L=\hat{\b}$ as follows:
$$
\CY_{S^{\vec{n}}}(\b) := \CY\left[\left(\PP^y_{n_1}\boxtimes \cdots \boxtimes \PP^y_{n_m}\right)\star F^y\left(\beta^{\vec{n}}\right)\right]
$$
and
$$
\CY_{\gll_N,S^{\vec{n}}}(\b) := \CY_{\gll_N}\left[\left(\PP^y_{n_1}\boxtimes \cdots \boxtimes \PP^y_{n_m}\right)\star F^y\left(\beta^{\vec{n}}\right)\right]
$$
Denote the homologies of these complexes by $\HY_{S^{\vec{n}}}(\b)$ and $\HY_{\gll_N,S^{\vec{n}}}(\b)$.
\end{definition}

\begin{theorem}
\label{thm: colored homology invariant}
The homologies $\HY_{S^{\vec{n}}}(\b)$ and $\HY_{\gll_N,S^{\vec{n}}}(\b)$ depend only on the oriented link $L=\hat{\b}$ up to isomorphism and overall shift.
\end{theorem}

\begin{proof}
We focus entirely on the triply graded colored homology, as the $\gll_N$ version is similar.  First, observe that the cable $\b^{\vec{n}}$ is invariant under the braid relations applied to $\b$.  To prove the theorem we need to show that our construction is invariant under the Markov moves.

For invariance under the Markov 1 move (i.e.~invariance under conjugation $\b\mapsto \gamma\b\gamma\inv$) we need to show that
\begin{equation}\label{eq:sliding projectors}
\left(\PP^y_{v(n_1)}\boxtimes \cdots \boxtimes \PP^y_{v(n_m)}\right)\star F^y(\gamma^{\vec{n}}) \simeq F^y(\gamma^{\vec{n}})\star \left(\PP^y_{n_1}\boxtimes \cdots \boxtimes \PP^y_{n_m}\right)
\end{equation}
whenever $\gamma$ is a braid with underlying permutation $v\in S_m$.  The un-$y$-ified version of the homotopy equivalence \eqref{eq:sliding projectors} is proven by standard techniques.  Indeed, the general result in \cite[Corollary 1.10]{EHdrinfeld}, independently proved by different methods in \cite{LMRSW,SW}, implies that the cabled Rouquier complex  $F(\gamma^{\vec{n}})$ is in the $A_\infty$ Drinfeld centralizer of $\SBim_{n_1}\otimes \cdots \otimes \SBim_{n_m}$ inside $\Ch(\SBim_{n_1+\cdots+n_m})$ (with the standard right action and left action twisted by the permutation $v$).  Thus, any complex of objects in $\SBim_{n_1}\otimes \cdots \otimes \SBim_{n_m}$ can be slid past the cabled Rouquier complex $F(\gamma^{\vec{n}})$.  

Since $F(\gamma^{\vec{n}})$ is invertible, we get
\[
\End\left(\left(\PP_{n_1}\boxtimes \cdots \boxtimes \PP_{n_m}\right)\star F(\gamma^{\vec{n}})\right) \simeq \End\left(\PP_{n_1}\boxtimes \cdots \boxtimes \PP_{n_m}\right) \simeq \bigotimes_{i=1}^m \End(\PP_{n_i})
\]
and \eqref{eq:sliding projectors} now follows from Theorem \ref{thm:end Pn} and Lemma \ref{lemma:lift of equiv}.

For invariance under the Markov 2 move, we need to show that
\begin{equation}
\CY\left((\PP^y_{n_1}\boxtimes\cdots\boxtimes \PP^y_{n_m}\boxtimes \PP^y_{n_m}) \star F^y((\sigma_m \b)^{(\vec{n},n_m)} \right) \simeq \CY\left((\PP^y_{n_1}\boxtimes\cdots\boxtimes \PP^y_{n_m}) \star F^y(\b^{\vec{n}}) \right).
\end{equation}
where $(\vec{n},n_m)=(n_1,\ldots,n_m,n_m)$.
One constructs the above homotopy equivalence as a composition of homotopy equivalences corresponding to local moves of the form
\[
\begin{tikzpicture}[scale=1.5,baseline=.5cm]
\draw[very thick]
(1,-.65)--(1,0) -- (0,1)--(0,1.65)
(1.2,-.65)--(1.2,0) -- (.2,1)--(.2,1.65)
(1.4,-.65)--(1.4,0) -- (.4,1)--(.4,1.65)
(1.6,-.65)--(1.6,0) -- (.6,1)--(.6,1.65);
\draw[line width=5pt,white]
(0,0) -- (1,1)
(.2,0) -- (1.2,1)
(.4,0) -- (1.4,1)
(.6,0) -- (1.6,1);
\draw[very thick]
(0,-.65)--(0,0) -- (1,1)--(1,1.65)
(.2,-.65)--(.2,0) -- (1.2,1)--(1.2,1.65)
