\begin{remark}
One should compare the above construction of projector-colored homology with the construction of Cooper--Krushkal \cite{CooperKrushkal}. The projectors $\PP_n^y$ satisfy the same kind of local properties satisfied by the Cooper-Krushkal projectors (idempotence, sliding over and under crossings, absorption of crossings), and so a proof strategy similar to \cite[Section 5]{CooperKrushkal} would work here as well. But our construction and proof of invariance look a bit different from \cite{CooperKrushkal} on the surface, since we start with a braid presentation and place all projectors at the top of the cabled braid.
\end{remark}

\begin{remark}
Recall that $\mathbf{n}\colon \pi_0(L)\to \Z_{\geq 0}$ denotes the function induced by $\vec{n}=(n_1,\ldots,n_m)$.  One can show that the product of symmetric groups $\prod_{c\in \pi_0(L)} S_{\mathbf{n}(c)}$ acts on the colored complex $\CY_{S^{\mathbf{n}}}(\b)$ (regarded as an object of a suitable derived category).   Roughly speaking, a permutation $x\in S_{\mathbf{n}(c)}$ acts as a composition:
\begin{enumerate}
    \item produce a canceling pair of Rouquier complexes $F^y(\gamma_x)\star F^y(\gamma_x\inv)$ on the appropriate component of $L$, where $\gamma_x$ denotes a positive braid lift of $x$.
    \item slide $F^y(\gamma_x\inv)$ around the entire link component; when sliding  $F^y(\gamma_x\inv)$ past a projector $\PP^y_n$ we use centrality of $y$-ified projectors.
    \item cancel the pair $F^y(\gamma_x\inv)\star F^y(\gamma_x)$.
\end{enumerate}
This action factors through the symmetric group (up to homotopy) by arguments similar to \cite{GLW,GHW}.  Taking the invariants with respect to this symmetric group action would yield a link invariant that might also be referred to $S^{\mathbf{n}}$-colored homology.
\end{remark}

\begin{remark}
In \cite[Theorem 5.24]{Conners} Conners described a different  model of $\PP_n^y$ (compare with Theorem \ref{thm:Pn as colimit} below) and conjectured in \cite[Conjecture 5.26]{Conners} that it satisfies all desired properties. Theorem \ref{thm: colored homology invariant} resolves this conjecture in the positive.
\end{remark}





\section{From full twists to colored homology}

\subsection{Powers of the full twist}
\label{ss:powers of ft}

\begin{definition}
Let $\htt_n= (\sigma_1)(\sigma_2\sigma_1)\cdots (\sigma_{n-1}\cdots \sigma_2\sigma_1)\in \Br_n$ denote the half-twist braid, and let $\ft_n = \htt_n^2$ denote the full twist.
\end{definition}

For example, $\htt_2=\sigma_1$ and $\ft_2=\sigma_1^2$.

\begin{definition}
We define by $\FT_n=F(\ft_n)$ the Rouquier complex for the full twist braid, and by $\FTy_n=F^y(\ft_n)$ the corresponding $y$-ified Rouquier complex.
\end{definition}

\begin{definition}
Let $\Sigma_n:=(T^2Q^{-2})^{\binom{n}{2}}=t^{\binom{n}{2}}$, and let $\a\colon \one\to \Sigma_n\inv\FTy_n$ given by the inclusion of the right-most chain bimodule, see Lemma \ref{lem: rightmost R y-ified}.


For each $k\in \Z_{\geq 0}$ let $\a_k\colon \Sigma_n^{-k}\FTy_n^k\to \Sigma_n^{-k-1}\FTy_n^{k+1}$ be the chain map defined by $\a \star \Id_{\FTy_n^k}$.
\end{definition}

\begin{theorem}\label{thm:Pn as colimit}
We have
$$
\PP_n^y\simeq \hocolim_{k\to \infty}\left(\Sigma_n^{-k}\FTy_n^k,\a_k\right),
$$
where the homotopy colimit is taken inside the dg category $\mathcal{Y}_{n,1}$. The unit map $\upsilon:R\to \PP_n^y$ is given by the inclusion of $\FT^0=R$ in the homotopy colimit.
\end{theorem}
\begin{proof}
For a concrete description of the stated homotopy colimit $\PP_n^y$ we use the mapping telescope construction.  Consider the countable direct sum $\mathbf{L}=\bigoplus_{k\geq 0} \Sigma_n^{-k} \FTy_n^k$.  Let $A\in \End(\mathbf{L})$ be the degree zero closed endomorphism whose components are the $\a_k$.  Then we set
\begin{equation}\label{eq:Py}
\hocolim_{k\to \infty}(\Sigma_n^{-k}\FTy_n^k,\a_k):= \Cone(\mathbf{L}\buildrel A-\id \over \longrightarrow\mathbf{L}) = 
\left( \begin{tikzcd}
T\inv\FTy_n^0 \arrow{r}{-\Id} \arrow{dr}{\a_0} & \FTy_n^0\\
T\inv\Sigma_n\inv\FTy_n^1 \arrow{r}{-\Id}   \arrow{dr}{\a_1}& \Sigma_n\inv\FTy_n^1\\
T\inv \Sigma_n^{-2}\FTy_n^2 \arrow{r}{-\Id}   \arrow{dr}{\a_2}& \Sigma_n^{-2}\FTy_n^2\\
\vdots & \vdots
\end{tikzcd}
\right). 
\end{equation}
It is proven in \cite{Hog} that the undeformed projector $\PP_n$ is the homotopy colimit of powers of undeformed full twists, with maps given by $\a_k$ (mod $\yy$).  Theorem \ref{thm:Py unique} then completes the proof.
\end{proof}

Combining the above description of $\PP_n^y$ with results in \cite{GH} will yield a useful presentation of $\HY(\PP_n^y)$.  We begin by recalling some results on homology of the powers of the full twist following \cite{GH}.

\begin{definition}
We denote by  $\one_n$ the $n$-strand identity braid, its closure is the $n$-component unlink $O_n$. We have
$$   
\HY(\one_n)=\k[\xx,\yy,\ttheta]
$$
with $\Z^3$-grading determined by \eqref{eq:weights of xyt}.
There is an action of $S_n$ permuting $x_i,y_i$ and $\theta_i$ simultaneously, and we define $\cJ_n$ as the ideal in $\HY(\one_n)$ generated by the antisymmetric polynomials under this action.
\end{definition}

\begin{proposition}(\cite[Proposition 6.1]{GH})
\label{prop: psi}
We have 
\begin{equation}
\label{eq: Psi}
\Hom_{\mathcal{Y}_{n,1}}(\FTy_n,\one_n)\simeq \k[\xx,\yy].
\end{equation}
The generator $\Psi$ of \eqref{eq: Psi} is given by the composition of crossing change maps $\psi_i$, as in Lemma \ref{lem: rightmost R y-ified}.
\end{proposition}

\begin{definition}\label{def:splitting map 2}
Let $\Psi\colon \HY(\FTy_n)\to \HY(\one_n)$ denote the map in $\HY$ induced by the generator of \eqref{eq: Psi}.  
By abuse of notation, we denote the tensor powers $\Psi^{\star k} \colon \HY(\FTy_n^k)\to \HY(\one_n)$ also by $\Psi$.  We refer to the maps $\Psi$ and $\Psi^{\star k}$ as to \emph{splitting maps}.
\end{definition}


\begin{theorem}\cite{GH}
\label{thm:GH ft}
Assume $\k=\C$.
The map $\Psi\colon \HY(\FTy_n^k;\C)\to \HY(\one_n;\C)$ is  injective, with image equal to the ideal  $\cJ^k_n\subset \HY(\one_n;\C)$, so that $\HY(\FTy^k_n;\C)\cong \cJ^k_n$. 
These isomorphisms are compatible with the multiplicative structures, in the sense that the diagram
\[
\begin{tikzpicture}
\node (a) at (0,0) {$\HY(\FTy_n^k;\C)\otimes \HY(\FTy_n^m;\C)$};
\node (b) at (5,0){$\HY(\FTy_n^{k+m};\C)$};
\node (c) at (0,-2) {$\cJ_n^k\otimes \cJ_n^m$};
\node (d) at (5,-2) {$\cJ_n^{k+m}$};
\path[-stealth]
(a) edge node[above] {} (b)
(c) edge node[above] {} (d)
(a) edge node[left] {} (c)
(b) edge node[right] {} (d);
\end{tikzpicture}
\]
commmutes for all $k,m\geq 0$.
\end{theorem}

Next, we identify the connecting maps $\a_k$ using Theorem \ref{thm:GH ft}.

\begin{lemma}
\label{lem: connecting map Delta}
The maps $\Psi$ and $\rho$ are independent of the factorization in Lemma \ref{lem: rightmost R y-ified}. Furthermore, we have the commutative diagram
\begin{equation}
\label{eq: psi and alpha}
\begin{tikzcd}
\Sigma_n^{-k-1}\HY(\FTy_n^{k+1};\C) \arrow{r}{\Psi^{\star(k+1)}}& \Sigma_n^{-k-1}\cJ_{n}^{k+1}\\
\Sigma_n^{-k}\HY(\FTy_n^k;\C) \arrow{r}{\Psi^{\star k}} \arrow{u}{\a_k}& \Sigma_n^{-k}\cJ_{n}^{k}\arrow{u}{\Delta_n}
\end{tikzcd}
\end{equation}
where  $\Delta_n=\prod_{1\le i<j\le n} (y_i-y_j)$ is the Vandermonde determinant.
\end{lemma}

\begin{proof}
The splitting map $\Psi$ is independent of factorization by Proposition \ref{prop: psi}, let us prove that $\a$ is independent as well.
We can identify $\a\in \Hom_{\mathcal{Y}_{n,1}}(\one_n,\FTy_n)$ with the corresponding class in $\HY^{a=0}(\FTy_n;\C)$ of bidegree $q^{0}t^{n(n-1)/2}$. 

By Theorem \ref{thm:GH ft} the $(q,t)$ bidegree on $\HY^{a=0}(\FTy_n;\C)$ matches the $(\xx,\yy)$ bidegree on $\cJ_n^{a=0}\subset \C[\xx,\yy]$. The ideal $\cJ_n^{a=0}$ is concentrated in nonnegative $q$-degrees and its homogeneous components of $q$-degree zero are generated over $\C[\yy]$ by antisymmetric polynomials in $\C[\yy]$, hence generated by $\Delta_n$.  Therefore  $\Delta_n$ is the unique (up to a scalar) antisymmetric polynomial of bidegree $q^{0}t^{n(n-1)/2}$, which corresponds to $\a$. 

By Lemma \ref{lem: rightmost R y-ified} we get $\Psi\circ \a=\Delta_n$.
Next, we get the identity
$$
\Psi^{\star(k+1)}\circ \a_k=\Psi^{\star(k+1)}\circ (\a \star \Id_{\FT_n^k})=(\Psi\circ\a)\star (\Psi^{\star k}\circ \Id_{\FT_n^k})=(\Delta_n \Id_{\one})\star \Psi^{\star k}=\Delta\Psi^{\star k}.
$$
which implies the following commutative diagram:
$$
\begin{tikzcd}
\Sigma_n^{-k-1}\FTy_n^{k+1} \arrow{r}{\Psi^{\star(k+1)}}& \Sigma_n^{-k-1}\one\\
\Sigma_n^{-k}\FTy_n^k \arrow{r}{\Psi^{\star k}} \arrow{u}{\a_k}& \Sigma_n^{-k}\one\arrow{u}{\Delta_n}
\end{tikzcd}
$$
By applying $\HY$ to this diagram, we get \eqref{eq: psi and alpha}.
\end{proof}

\begin{definition}
Let $\cA_n=\bigoplus_{k=0}^{\infty}s^k\cJ_n^k$, regarded as a graded subalgebra of $\C[\xx,\yy,\ttheta,s]$.  An element of $\cJ_n^k$ will be regarded as an element of $\cA_n$ of \emph{$s$-degree $k$}.
\end{definition}

We will consider a certain localization of $\cA_n$ momentarily, but since  $\cA_n$ has zero divisors, we need to be careful.

\begin{lemma}
\label{lem: not zero divisor}
The polynomial $\Delta_n\in \cJ_n$  (considered as an $s$-degree one element in $\cA_n$) is not a zero divisor in $\cA_n$.
\end{lemma}
\begin{proof}
 Indeed, $\HY(\one_n;\C)=\C[\xx,\yy,\ttheta]$ is a free module of rank $2^n$ over 
$\C[\xx,\yy]$, so multiplication by $\Delta_n$ is injective on $\HY(\one_n;\C)$. Since $\cJ_n^k$ is a submodule of $\HY(\one_n;\C)$, the multiplication by $\Delta_n$ is injective on $\cJ_n^k$ as well.
\end{proof}

\begin{corollary}
The map $\a_k: \Sigma_n^{-k}\HY(\FTy_n^k;\C)\to \Sigma_n^{-k-1}\HY(\FTy_n^{k+1};\C)$ is injective.\qed
\end{corollary}

Next, we compute the $y$-ified homology of $\PP_n^y$ in terms of the algebra $\cA_n$.

 \begin{lemma}
 \label{lem: homology colimit}
 (a) We have (for any $\k$):
 $$\displaystyle \HY(\PP_n^y)=\colim_{k\to \infty} \left(\Sigma_n^{-k}\HY(\FTy_n^k),\a_k\right).
 $$
 (b)The homology of $\PP_n^y$ is isomorphic to the (homogeneous) localization of $\cA_n$ in $\Delta_n$:
$$
\HY(\PP_n^y;\C)=\Span\left\{\frac{p}{\Delta_n^k}: p\in \cJ_n^k\right\}/\left(\frac{p}{\Delta_n^k}\sim \frac{p\Delta_n}{\Delta_n^{k+1}}\right)
$$
(c) Also,
$$
\HY(\PP_n^y;\C)=\C\left[\frac{p}{\Delta_n}: p\in \cJ_n\right]\subset \Frac\ \cA_n.
$$

\end{lemma}
We denote the localization of $\cA_n$ by $\cA_n[\Delta_n^{-1}]$. Note that $\cA_n[\Delta_n^{-1}]$ embeds into  $\Frac\ \cA_n$ by Lemma \ref{lem: not zero divisor}.



 \begin{proof}
 (a) This is standard but we recall the proof for completeness.  Consider the long exact sequence associated to the mapping cone $\HY(\PP_n^y) = \Cone\left(\HY(\mathbf{L})\buildrel A-\id \over \longrightarrow \HY(\mathbf{L})\right)$ as in the proof of Theorem \ref{thm:Pn as colimit}.  The map $\HY(\mathbf{L})\to \HY(\mathbf{L})$ is injective, since it is the identity map plus terms that increase the evident  filtration by rows in \eqref{eq:Py}.  Thus, we have a short exact sequence
 \[
0\to \bigoplus_{k\geq 0} \Sigma_n^{-k} \HY(\FTy_n^k) \buildrel A-\id\over \longrightarrow \bigoplus_{k\geq 0} \Sigma_n^{-k} \HY(\FTy_n^k) \to \HY(\PP_n^y)\to 0
\]
where the map $A-\id$ sends $x\in \HY(\FTy_n^k)$ to $\a_k(x)-x$. This shows that $\HY(\PP_n^y)\cong \operatorname{coker}(A-\id)$, which in turn is isomorphic to $\colim_{k\to \infty} (\Sigma_n^{-k}\HY(\FTy_n^k),\a_k)$. This completes the proof.

(b) By part (a) and Lemma \ref{lem: connecting map Delta} we have
\[
\HY(\PP_n^y;\C)=\colim_{k\to \infty}\left(
\begin{tikzcd}
\cJ_n^0 \arrow[r,"\Delta_n"] & \Sigma_n\inv \cJ_n^1 \arrow[r,"\Delta_n"]& \Sigma_n^{-2}\cJ_n^2\arrow[r,"\Delta_n"] & \cdots 
\end{tikzcd}
\right)
\]
By definition, this colimit is spanned by pairs $(p,k)$ for $p\in \cJ_n^k$ modulo equivalence relation $(p,k)\sim (\Delta_n p,k+1)$. We can
identify $(p,k)$ with $\frac{p}{\Delta_n^k}$, and this immediately implies (b).

For (c), we  observe that the graded algebra $\cA_n$ is generated in degrees 1 and 0. For $p_1,\ldots,p_k\in \cJ_n$ we get  $p_1\cdots p_k \in \cJ_n^k$ and
$$
\frac{p_1\cdots p_k}{\Delta_n^k}=\frac{p_1}{\Delta_n}\cdots \frac{p_k}{\Delta_n}.
$$
So $\cA_n[\Delta_n\inv]$ is generated (as a subalgebra of $\Frac\ \cA_n$) by the ratios $\frac{p}{\Delta_n},\ p\in \cJ_n$.
\end{proof}




\begin{lemma}
The isomorphism
$$
\HY(\PP_n^y)\simeq \cA_n[\Delta_n^{-1}]
$$
is compatible with the multiplication $\HY(\PP_n^y)\otimes \HY(\PP_n^y)\to \HY(\PP_n^y)$.
\end{lemma}

\begin{proof}
First, we would like to make the maps $\Sigma_n^{-k}\HY(\FTy^k_n)\to \HY(\PP_n^y)$ more explicit. For this, note that 
$$
\Hom_{\mathcal{Y}_{n,1}}(\Sigma_n^{-k}\FTy_n^k,\PP_n^y)\simeq \Hom_{\mathcal{Y}_{n,1}}(R,\Sigma_n^{k}\FTy_n^{-k}\star\PP_n^y)=\Hom_{\mathcal{Y}_{n,1}}(R,\PP_n^y)
$$
The second equation follows from Proposition \ref{prop:twisted projectors}. The map $\upsilon\in \Hom_{\mathcal{Y}_{n,1}}(R,\PP_n^y)$ then corresponds to a family of maps  
$$
\upsilon_k:\Sigma_n^{-k}\FTy_n^k\to \PP_n^y
$$
which are compatible with multiplication $(\Sigma_n^{-k}\FTy_n^k)\star (\Sigma_n^{-m}\FTy_n^m)\simeq \Sigma_n^{-k-m}\FTy_n^{k+m}$ on one side and $\PP_n^y\star \PP_n^y\to \PP_n^y$ from Theorem \ref{thm:map of diagrams} on the other.
Therefore we have an algebra homomorphism
$$
\bigoplus_k\Sigma_n^{-k}\HY(\FTy_n^k)\to \HY(\PP_n^y).
$$
Furthermore, it follows from the proof of Lemma \ref{prop:twisted projectors} that the map 
$$
\a_k\star \Id:\Sigma_n^{-k}\FTy_n^k\star \PP_n^y\to \Sigma_n^{-k-1}\FTy_n^{k+1}\star \PP_n^y 
$$
is a homotopy equivalence. Therefore the following triangle commutes up to homotopy:
$$
\begin{tikzcd}
\Sigma_n^{-k}\FTy_n^k \arrow{dr}{\upsilon_k}  \arrow{dd}{\a_k}& \\
 & \PP_n^y\\
\Sigma_n^{-k-1}\FTy_n^{k+1} \arrow[swap]{ur}{\upsilon_{k+1}}& 
\end{tikzcd}
$$
and $\upsilon_k$ define a degree zero chain map
$$
\upsilon_{\infty}:\hocolim_{k\to \infty}(\Sigma_n^{-k}\FTy_n^k,\a_k)\to \PP_n^y
$$
By Theorem \ref{thm:Pn as colimit} and Lemma \ref{lem:end Pn y}  the space of such maps is one-dimensional, so $\upsilon_n$ is homotopy equivalent to the map from Theorem \ref{thm:Pn as colimit} up to a scalar. By looking at the unit maps $\upsilon$ from $R$ to $\hocolim_{k\to \infty}(\Sigma_n^{-k}\FTy_n^k,\a_k)$ and $\PP_n^y$, we conclude that this scalar is 1 and the result follows.  
\end{proof}

Next, we compute the above localization $\cA_n[\Delta_n^{-1}]$  explicitly. 

\begin{theorem}
\label{thm: y-ified projector}
There is an algebra isomorphism
$$
\HY(\PP_n^y;\C)\cong \cA_n[\Delta_n\inv]\cong \C[y_1,\ldots,y_n,u_0,\ldots,u_{n-1},\xi_0,\ldots,\xi_{n-1}].
$$
The elements $u_i$, $\xi_i$  are uniquely characterized by the equations:
\begin{align}
\label{eq: interpolation u}
u_0+u_1y_i+u_2y_i^2+\ldots+u_{n-1}y_i^{n-1}&=x_i\ \mathrm{for\ all}\ i \\
\label{eq: interpolation xi}
 \xi_0+\xi_1y_i+\xi_2y_i^2+\ldots+\xi_{n-1}y_i^{n-1}&=\theta_i\ \mathrm{for\ all}\ i.
\end{align}
\end{theorem}
Note that \eqref{eq: interpolation u} and \eqref{eq: interpolation xi} imply
\begin{equation}
\label{eq: deg u and theta}
\wt(u_i)=qt^{-i}=Q^{2+2i}T^{-2i},\quad \wt(\xi_i)=at^{-i}=Q^{2i-2}T^{-2i}A.
\end{equation}



\begin{proof}
We abbreviate $\C[\yy,\uu,\xxi] =\C[y_1,\ldots,y_n,u_0,\ldots,u_{n-1},\xi_0,\ldots,\xi_{n-1}]$.
One can obtain $u_i$ and $\xi_i$ as elements of $\cA_n[\Delta_n\inv]$ by solving the equations \eqref{eq: interpolation u} and \eqref{eq: interpolation xi} using Cramer's Rule:
\begin{equation}
\label{eq: Cramer u}
u_i=\frac{\Alt\left(y_1^0y_2^1\cdots \widehat{y_i^{i-1}}\cdots y_n^{n-1}\cdot x_i\right)}{\Delta_n},
\end{equation}
\begin{equation}
\label{eq: Cramer xi}
\xi_i=\frac{\Alt\left(y_1^0y_2^1\cdots \widehat{y_i^{i-1}}\cdots y_n^{n-1}\cdot \theta_i\right)}{\Delta_n}.
\end{equation}
Clearly, the numerators in \eqref{eq: Cramer u} and \eqref{eq: Cramer xi} are antisymmetric, so $u_i$ and $\xi_i$ are well defined elements of the $\cA_n[\Delta_n\inv]$. This defines a homomorphism $\varphi: \C[\yy,\uu,\xxi]\to \cA_n[\Delta_n^{-1}]$.

Next, consider the homomorphism
$\varphi': \cA_n[\Delta_n^{-1}]\to \C[\yy,\uu,\xxi][\Delta_n^{-1}]$
defined by substituting $x_i$ and $\theta_i$ via
\eqref{eq: interpolation u} and \eqref{eq: interpolation xi}. We claim that the image of $\varphi'$ is actually contained in $\C[\yy,\uu,\xxi]$ and therefore $\varphi'$ is inverse to $\varphi$. 

Indeed, by Lemma \ref{lem: homology colimit}(c) the algebra $\cA_n[\Delta_n\inv]$ is generated by the elements $p/\Delta_n$ for $p\in \cJ_n$. Furthermore, we can write $p=\sum_k f_k(\xx,\yy,\ttheta)g_k(\xx,\yy,\ttheta)$ where $f_k$ are arbitrary polynomials and $g_k$ are antisymmetric polynomials, and
$$
\varphi'\left(\frac{p}{\Delta_n}\right)=\sum_k \varphi'(f_k(\xx,\yy,\ttheta))\frac{\varphi'(g_k(\xx,\yy,\ttheta))}{\Delta_n}.
$$
The  action of $S_n$ permutes $x_i,y_i$ and $\theta_i$ simultaneously, and fixes $u_i$ and $\xi_i$.  Therefore $\varphi'(g_k(\xx,\yy,\ttheta))$
 can be written as a polynomial in  $u_i$ and $\xi_i$ with coefficients being antisymmetric polynomials in $y_i$. In particular, it is divisible by $\Delta$ and $\varphi'(g_k(\xx,\yy,\ttheta))/\Delta_n.$ is a polynomial in  $u_i$ and $\xi_i$ with coefficients being
symmetric polynomials in $y_i$. We conclude that
$$
\varphi'\left(\frac{p}{\Delta_n}\right)\in \C[\yy,\uu,\xxi].
$$
\end{proof}


\begin{corollary}
\label{cor: u tilde comparison}
Let $\k$ be an arbitrary field of characteristic zero. Then 
$$
\HY(\PP_n^y;\k)\cong \k[y_1,\ldots,y_n,u_0,\ldots,u_{n-1},\xi_0,\ldots,\xi_{n-1}]
$$ where $u_i,\xi_i$ satisfy \eqref{eq: interpolation u} and \eqref{eq: interpolation xi}.
\end{corollary}

\begin{proof}
Without loss of generality we can assume $\k=\Q$. 
By Lemma \ref{lem:end Pn y} and the universal coefficients theorem we get
$$
\HY(\PP_n^y;\Q)\simeq \Q\left[\yy,\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\dots,\widetilde{\xi}_{n-1},\right]
$$
By applying the universal coefficients theorem again , we can identify $$\HY(\PP_n^y;\C)\simeq \HY(\PP_n^y,\Q)\otimes \C,$$ and by Theorem \ref{thm: y-ified projector} get an embedding
$$
\Q\left[\yy,\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\dots,\widetilde{\xi}_{n-1}\right]   \hookrightarrow
\C[\yy,u_0,\ldots,u_{n-1},\xi_0,\ldots,\xi_{n-1}] 
$$
which becomes an isomorphism after tensoring with $\C$. Note that the abstract generators $\widetilde{u}_i$ (resp. $\widetilde{\xi}_i$) do not need to agree with the explicit desired generators $u_i$ (resp. $\xi_i$), but they have the same respective weights.

Since $x_i$ belongs to $\HY(\PP_n^y;\Q)$, by \eqref{eq: basis HY} it can be written as a linear combination of $\widetilde{u}_j$ with coefficients in $\Q[\yy]$. The numerators of \eqref{eq: Cramer u} can then be also written as linear combinations of $\widetilde{u}_j$ with coefficients in $\Q[\yy]$. These coefficients are divisible by $\Delta_n$ over $\C$ and hence they are divisible by $\Delta_n$ over $\Q$ as well. So the element $u_i$ defined by \eqref{eq: Cramer u} is a linear combination of $\widetilde{u}_j$ with coefficients in $\Q[\yy]$. Similarly, $\xi_i$ defined by \eqref{eq: Cramer xi} a linear combination of $\widetilde{\xi}_j$ with coefficients in $\Q[\yy]$.

Here we used the following easy fact. Suppose $f,g\in \Q[z_1,\ldots,z_s]$ and there exists $h\in \C[z_1,\ldots,z_s]$ such that $f=gh$. Then $h\in \Q[z_1,\ldots,z_s]$. This can be proved by induction in $s$ using polynomial long division.

Going back to the proof, we can clarify the relation between $u_i$ and $\widetilde{u}_j$. By applying \eqref{eq: basis HY} again, we get
\begin{equation}
\label{eq: u tilde triangular}
u_i=p_{ii}\widetilde{u}_i+\sum_{j>i}p_{ij}(\yy)\widetilde{u}_j 
\end{equation}
where $p_{ij}$ are homogeneous polynomials in $\yy$ of degree $j-i$ with rational coefficients, in particular $p_{ii}\in \Q$. 

We claim that $p_{ii}\neq 0$ for all $i$. Suppose not, and $i$ is the largest index such that $p_{ii}=0$. Then by \eqref{eq: u tilde triangular} we have 
$$
u_i\in \Q[\yy,\widetilde{u}_{i+1},\ldots,\widetilde{u}_{n-1}]=\Q[\yy,u_{i+1},\ldots,u_{n-1}],
$$
so $u_j$ are not algebraically independent, contradiction.

Therefore $(p_{ij}(\yy))$ form an invertible triangular matrix and $\widetilde{u}_i$ can be written as polynomials in $u_j$ and $\yy$. Similarly, $\widetilde{\xi}_i$ can be written as polynomials in $\xi_j$ and $\yy$. We conclude that
$$
\HY(\PP_n^y;\Q)\cong \Q\left[\yy,\widetilde{u}_{0},\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_{0},\ldots,\widetilde{\xi}_{n-1}\right]=\Q\left[\yy,u_{0},\ldots,u_{n-1},\xi_0,\ldots,\xi_{n-1}\right] 
$$
and the result follows.
\end{proof}







\subsection{Differentials in $y$-ified  homology}


The $y$-ified homology of $\one_n$ has a standard $\fgl_N$ differential  which is defined on generators (see Example \ref{ex: dN unknot}) by $$d_N(\theta_i)=x_i^N$$ and extended by Leibniz rule
$$
d_N(fg)=d_N(f)g+(-1)^{|f|}d_N(g).
$$ 
The differential $d_N$ has weight $q^{N}a\inv$, i.e.~it decreases $a$-degree by 1 and increases $q$-degree by $N$.  

\begin{lemma}
The differential $d_N$ preserves the ideal $\cJ_n$ and its powers $\cJ_n^k$.
\end{lemma}

\begin{proof}
For any $g\in \HY(\one_n;\C)=\C[\xx,\yy,\ttheta]$ and $w\in S_n$ we clearly have $d_N(w(g))=w(d_N(g))$. 

If $g$ is antisymmetric then $$w(d_N(g))=d_N(w(g))=d_N((-1)^{\sgn(w)} g)=(-1)^{\sgn(w)}d_N(g),$$ so $d_N(g)$ is also antisymmetric. Furthermore, for any $f$ and antisymmetric $g$ we have $d_N(fg)=d_N(f)g+fd_N(g)$, so $d_N(fg)\in \cJ$. We conclude that $d_N(\cJ_n)\subset \cJ_n$ and similarly $d_N(\cJ_n^k)\subset \cJ_n^k$. 
\end{proof}

\begin{lemma}
The $y$-ified Rasmussen $\fgl_N$ differential on $\HY(\FTy_n^k;\C)\simeq \cJ_n^k$ is given by the restriction of $d_N$ to $\cJ_n^k$. 
\end{lemma}

\begin{proof}
By Proposition \ref{prop:HH with dN is functor} the splitting map $\Psi$ commutes with $d_N$, and the result follows.  
\end{proof}

Next, we compute the action of the $y$-ified differential $d_N$ in $\HY(\PP_n^y;\k)$. 
First, we need some notations.  Define
$$
p(z)=\prod_{i=1}^{n}(z-y_i).
$$
This is a monic polynomial in $z$ of degree $n$ with coefficients in $\k[y_1,\ldots,y_n]$. Let $f(z)$ be a polynomial in $z$ with coefficients in $S[y_1,\ldots,y_n]$ where $S$ is some unique factorization domain (UFD) over $\k$. Using polynomial long division, we can divide $f(z)$ by $p(z)$ with remainder:
\begin{equation}
\label{eq: division with remainder}
f(z)=q(z)p(z)+r(z),\ \deg r(z)\le n-1.
\end{equation}
Such polynomials $q(z)$ and $r(z)$ are uniquely determined by $f(z)$ and have coefficients in $S[y_1,\ldots,y_n]$.
Below we will abbreviate \eqref{eq: division with remainder} by $r(z)=f(z)\mod p(z)$.

\begin{lemma}
\label{lem: remainder}
Suppose that $f(z)$ and $r(z)$ are as in \eqref{eq: division with remainder}. Then $r(z)$ is the unique polynomial of degree at most $n-1$ such that $r(y_i)=f(y_i)$ for all $i$.
\end{lemma}

\begin{proof}
If we substitute $z=y_i$ into \eqref{eq: division with remainder}, we get
$$
f(y_i)=q(y_i)p(y_i)+r(y_i)=r(y_i).
$$
Conversely, suppose that $h(z)\neq g(z)$,  $h(y_i)=f(y_i)$ and 
$\deg h(z)\le n-1$. Then $h(y_i)-g(y_i)=0$ for all $i$, so $h(z)-g(z)$ is divisible by $z-y_i$ for all $i=1,\ldots,n$. 

Since $S$ is a UFD, $S[y_1,\ldots,y_n,z]$ is also a UFD, and the polynomials $z-y_i$ are pairwise coprime for different $i$. Therefore $h(z)-g(z)$ is divisible by $\prod_{i=1}^{n}(z-y_i)=p(z)$ and $\deg (h(z)-g(z))\ge n$. Contradiction.
 \end{proof}



\begin{theorem}
\label{thm: y-ified differential}
Suppose $\k$ is a characteristic zero field.
The $y$-ified $\fgl_N$ Rasmussen spectral sequence for $\PP_n^y$ has $E_1$ page $$E_1=\HY(\PP_n^y;\k)\simeq \k[y_1,\ldots,y_n,u_0,\ldots,u_{n-1},\xi_0,\ldots,\xi_{n-1}]$$ and the first differential $d_N$ given by \eqref{eq: dN y-ified}. 
\begin{equation}
\label{eq: dN y-ified}
d_N(\xi(z))=u(z)^N \mod p(z)
\end{equation}
where 
$$
\xi(z)=\xi_0+\xi_1z+\xi_2z^2+\ldots+\xi_{n-1}z^{n-1}, u(z)=u_0+u_1z+u_2z^2+\ldots+u_{n-1}z^{n-1}
$$
and $p(z)=\prod_{i=1}^n (z-y_i)$ as above.

Furthermore, the homology on $E_2$ page is supported in $a$-degree zero and all higher differentials vanish, so that 
$$
E_2=E_{\infty}=\frac{\k[y_1,\ldots,y_n,u_0,\ldots,u_{n-1}]}{\left(d_N(\xi_0),\ldots,d_N(\xi_{n-1})\right)}
$$

\end{theorem}


\begin{proof}
First, we claim that the differential $d_N$ commutes with localization in $\Delta_n$ and satisfies the Leibniz rule. Indeed, this follows from $d_N(\Delta_n)=0$ and the fact that $d_N$ satisfies Leibniz rule on $\HY(\one_n)$. Note that 
$$
d_N\left(\frac{p}{\Delta_n^k}\right)=\frac{d_N(p)}{\Delta_n^k}
$$
for any $p\in \cJ_n^k$.

Next, we observe that $\cA_n$ and its localization $\cA_n[\Delta_n\inv]$ are graded (by the $a$-degree) so that $\theta_i,\xi_i$ have degree 1 and $x_i,y_i,u_i$ have degree zero. The differential $d_N$ decreases this degree by 1, so it sends $\xi_i$ to some polynomials in $y_i,u_i$. Also, $d_N(y_i)=d_N(u_i)=0$.

Now we use the equations \eqref{eq: interpolation u} and \eqref{eq: interpolation xi}. Let 
$$
g_N(z)=d_N(\xi_0)+d_N(\xi_1)z+d_N(\xi_2)z^2+\ldots+d_N(\xi_{n-1})z^{n-1}
$$
and 
$$
f_N(z)=(u_0+u_1z+u_2z^2+\ldots+u_{n-1}z^{n-1})^N.
$$
If we substitute $z=y_i$ for some $i=1,
\ldots,n$, we get
$$
g_N(z=y_i)=d_N(\xi_0)+d_N(\xi_1)y_i+d_N(\xi_2)y_i^2+\ldots+d_N(\xi_{n-1})y_i^{n-1}=
$$
$$
d_N\left(\xi_0+\xi_1y_i+\xi_2y_i^2+\ldots+\xi_{n-1}y_i^{n-1}\right)=d_N(\theta_i)=x_i^N
$$
while
$$
f_N(z=y_i)=(u_0+u_1y_i+u_2y_i^2+\ldots+u_{n-1}y_i^{n-1})^N=x_i^N.
$$
Note that here we used that $d_N$ commutes with $y_i$.
We conclude that $g_N(z=y_i)=f_N(z=y_i)$. Since $g_N(z)$ have $z$-degree at most $n-1$ by construction, by Lemma \ref{lem: remainder} we get $g_N(z)=f_N(z)\mod p(z)$. 

Let us prove that $E_2$ page is supported in $a$-degree zero. Observe that $(E_1,d_N)$ is the Koszul complex corresponding to $d_N(\xi_k)$, and by Lemma \ref{lem: regular sequence} below these form a regular sequence. Therefore all higher homology of the Koszul complex vanish. 
Finally, since $E_2$ page is supported in $a$-degree zero and all higher differentials decrease the $a$-degree, these must vanish and $E_2=E_{\infty}$.
\end{proof}






Below in Section \ref{sec: interpolation algebra} we give a more explicit description of the ideal $\left(d_N(\xi_0),\ldots,d_N(\xi_{n-1})\right)$.


\subsection{Back to the undeformed case}

 \begin{lemma}
 \label{lem: pi}
 Let $\k$ be a field of characteristic zero. We have $$\HHH(\PP_n;\k)\simeq \k\left[\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\ldots,\widetilde{\xi}_{n-1}\right].$$ The natural forgetful map
 $\pi:\HY(\PP_n^y;\k)\to \HHH(\PP_n;\k)$ is a surjective algebra homomorphism and  sends the generator $u_i$ (resp. $\xi_i$) defined by \eqref{eq: interpolation u} (resp. \eqref{eq: interpolation xi}) to $\widetilde{u}_i$  (resp. $\widetilde{\xi}_i$) up to nonzero scalars.
 \end{lemma}

 \begin{proof}
 This follows from the proof of Corollary \ref{cor: u tilde comparison}. By Lemma \ref{lem: parity} we have $\HHH(\PP_n;\k)=\HY(\PP_n^y;\k)/(\yy)$.
 By \eqref{eq: u tilde triangular} we have $u_i=p_{ii}\widetilde{u_i}\mod \yy$ and $p_{ii}\neq 0$, so $\pi(u_i)=p_{ii}\widetilde{u_i}$. The proof for $\xi_i$ is similar.
 \end{proof}

From now on we will rescale the generators $\widetilde{u}_i,\widetilde{\xi}_i$ such that $\pi(u_i)=\widetilde{u}_i$ and $\pi(\xi_i)=\widetilde{\xi}_i$.



\begin{theorem}
\label{thm: HHH differential}
Let $\k$ be a field of characteristic zero.
There is a spectral sequence with $E_1$ page $$E_1=\HHH(\PP_n;\k)\simeq \k\left[\widetilde{u}_0,\ldots,\widetilde{u}_{n-1},\widetilde{\xi}_0,\ldots,\widetilde{\xi}_{n-1}\right]$$  and $E_2$ page is given by 
$$
E_2=H^*(E_1,d_N),\  d_N\left(\widetilde{\xi}(z)\right)=\widetilde{u}(z)^N \mod z^n.
$$
The differential $d_N$ satisfies Leibniz rule.
\end{theorem}

\begin{proof}
Since the differential $d_N$ commutes with the projection $\pi$ by \ref{prop:HH with dN is functor}, its action   on generators follows from Theorem \ref{thm: y-ified projector} and Lemma \ref{lem: pi}.
By Lemma \ref{lem: pi} $\pi$ is an algebra homomorphism which sends $y_i$ to zero, $u_i$ to $\widetilde{u}_i$ and $\xi_i$ to $\widetilde{\xi}_i$, so we get
$$
d_N\left(\widetilde{\xi}(z)\right)=d_N(\pi(\xi(z)))=\pi(d_N(\xi(z))).
$$
By Theorem \ref{thm: y-ified projector} $d_N(\xi(z))$ is the remainder of $u(z)^N$ modulo $p(z)=\prod (z-y_i)$. Since $p(z)$ is a monic polynomial, the coefficients of the remainder are obtained as certain polynomials in the coefficients of  $u(z)^N$ and $p(z)$, and we can apply $\pi$ to specialize all of these. Since $\pi$ is a homomorphism, we get that $\pi(d_N(\xi(z)))$ is the remainder of $\pi(u(z)^N)=\overline{u}(z)^N$ modulo $\pi(p(z))=\prod (z-0)=z^n$. 

It remains to prove that $d_N$ satisfies Leibniz rule, we use surjectivity of $\pi$: assume $f,g\in \HHH(\PP_n;\k)$. Then $f=\pi(f_1),g=\pi(g_1)$ for some $f_1,g_1\in \HY(\PP_n^y;\k)$. Now 
$$
d_N(fg)=d_N(\pi(f_1g_1))=\pi(d_N(f_1g_1))=\pi(d_N(f_1)g_1+f_1d(g_1))=
$$
$$
d_N(\pi(f_1))\pi(g_1)+\pi(f_1)d_N(\pi(g_1))=d_N(f)g+fd_N(g).
$$
Here we also used that $d_N$ commutes with $\pi$ and $\pi$ is a homomorphism. 
\end{proof}



\section{The interpolation algebra}
\label{sec: interpolation algebra}

\subsection{A formula for $y$-ified differential}


Recall that $p(z)=\prod_{i=1}^{n}(z-y_i)$. We give a closed formula for the coefficients of the remainder $r(z)$ in \eqref{eq: division with remainder}.

\begin{lemma}
\label{lem: remainder skew Schur}
Suppose that $r(z)=f(z)\mod p(z)$ as in \eqref{eq: division with remainder} and 
$$f(z)=\sum_{k=0}^{\deg\ f} f_kz^k,\ r(z)=\sum_{k=0}^{n-1} r_kz^k.$$
Then 
\begin{equation}
\label{eq: rk}
r_k=f_k+(-1)^{n-1-k}\sum_{j=n}^{\deg\ f}f_js_{(j-n+1,1^{n-1-k})}(\yy).
\end{equation}
where $s_{(j-n+1,1^{n-1-k})}(\yy)$ is the Schur polynomial in $y_1,\ldots,y_n$ for the hook diagram $(j-n+1,1^{n-1-k})$.
\end{lemma}

\begin{proof}
We have 
$$
r_0+r_1y_i+\ldots+r_{n-1}y_i^{n-1}=r(y_i)=f(y_i)
$$
which can be interpreted as a linear system of equations for $r_k$. By solving this by Cramer's Rule, we get
$$
r_k=\frac{(-1)^{k}}{\Delta}\det\left[f(y_i); 1;  y_i;\ldots; \widehat{y_i^k};\ldots; y_i^{n-1}\right]_{i=1}^{n}=
$$
$$
\frac{(-1)^{k}}{\Delta}\sum_{j=0}^{\deg\ f}f_j\det\left[ y_i^j; 1;  y_i;\ldots; \widehat{y_i^k};\ldots; y_i^{n-1}\right]_{i=1}^{n}.
$$ 
The  determinant 
$$
\det\left[ y_i^j; 1;  y_i;\ldots; \widehat{y_i^k};\ldots; y_i^{n-1}\right]_{i=1}^{n}
$$
equals $(-1)^{k}\Delta$ for $j=k$ and vanishes when $j\neq k$ and $0\le j\le n-1$. For $j\ge n$ we get
$$
\det\left[ y_i^j; 1;  y_i;\ldots; \widehat{y_i^k};\ldots; y_i^{n-1}\right]_{i=1}^{n}=
(-1)^{n-1} 
\det\left[1;  y_i;\ldots; \widehat{y_i^k};\ldots; y_i^{n-1},y_i^{j}\right]_{i=1}^{n}=
$$
$$
(-1)^{n-1} \Delta s_{(j-n+1,1^{n-1-k})}(\yy),
$$
and the result follows. 
\end{proof}

In what follows it will be useful to change coordinates and consider linear combinations of $r_k$ instead.  

\begin{lemma}
\label{lem: change of variables}
We have
$$
r_k+h_1(\yy)r_{k+1}+\ldots+h_{n-1-k}(\yy)r_{n-1}=\sum_{j=k}^{\infty}f_jh_{j-k}(\yy).
$$
\end{lemma}

\begin{proof}
We substitute $r_k$ using \eqref{eq: rk}. The first terms add up to
$$
f_k+h_1(\yy)f_{k+1}+\ldots+h_{n-1-k}(\yy)f_{n-1}=\sum_{j=k}^{n-1}f_jh_{j-k}(\yy).
$$\
For $j\ge n$ it suffices to compare the coefficients at $f_j$ and prove the identity (compare with \cite[Corollary 2.9]{HRW}):
\begin{equation}
\label{eq: hook schur to h}
\sum_{s=0}^{n-k-1}(-1)^{n-1-k-s}h_{s}(\yy)s_{(j-n+1,1^{n-1-k-s})}(\yy)=h_{j-k}(\yy).
\end{equation}
Note that we can write
$$
s_{(j-n+1,1^{n-1-k-s})}(\yy)=\sum_{t=0}^{n-1-k-s}(-1)^{t}h_{j-n+1+t}(\yy)e_{n-1-k-s-t}(\yy),
$$
so the left hand side of \eqref{eq: hook schur to h} can be rewritten as
$$
\sum_{s=0}^{n-k-1}\sum_{t=0}^{n-1-k-s}(-1)^{n-1-k-s-t}h_{s}(\yy)h_{j-n+1+t}(\yy)e_{n-1-k-s-t}(\yy).
$$
By changing the order of summation and using
$$
\sum_{s=0}^{n-k-1-t}(-1)^{n-1-k-s-t}h_{s}(\yy)e_{n-1-k-s-t}(\yy)=\begin{cases}
1 & \mathrm{if}\ n-1-k-t=0\\
0 & \mathrm{otherwise}\\
\end{cases}
$$
we are left with the term  
$$
h_{j-n+1+t}(\yy)|_{t=n-1-k}=h_{j-k}(\yy).
$$
\end{proof}



\begin{lemma}
\label{lem: d_N explicit}
For $n$ and $N$ arbitrary and $0\le k\le n-1$ we have
\begin{multline}
\label{eq: dN xi}
d_N(\xi_k)=\sum_{j_1+\ldots+j_N=k}u_{j_1}\cdots u_{j_N}+\\
(-1)^{n-1-k}\sum_{j=n}^{N(n-1)}\sum_{j_1+\ldots+j_{N}=j}u_{j_1}\cdots u_{j_N} s_{(j-n+1,1^{n-1-k})}(\yy).
\end{multline}
Furthermore, if 
\begin{equation}
\label{eq: zeta}
\zeta_k=\xi_k+h_1(\yy)\xi_{k+1}+\ldots+h_{n-1-k}(\yy)\xi_{n-1},\ 0\le k\le n-1
\end{equation}
then 
\begin{equation}
\label{eq: dN zeta}
d_N(\zeta_k)=\sum_{j=k}^{N(n-1)}\sum_{j_1+\ldots+j_{N}=j}u_{j_1}\cdots u_{j_N} h_{j-k}(\yy).
\end{equation}
\end{lemma}

\begin{proof}
This follows from Lemmas \ref{lem: remainder skew Schur} and \ref{lem: change of variables} applied to the polynomial
$$
f(z)=(u_0+u_1z+\ldots+u_{n-1}z^{n-1})^N=\sum_{j=0}^{N(n-1)}\sum_{j_1+\ldots+j_{N}=j}u_{j_1}\cdots u_{j_N}z^j.
$$
\end{proof}

\begin{example}
For $n=2$ and $N\ge 2$ we get
$$
d_N(\xi_0)=u_0^N-y_1y_2\sum_{j=2}^{N}\binom{N}{j}u_0^{N-j}u_1^{j}h_{j-2}(y_1,y_2),
$$
$$
d_N(\xi_1)=Nu_0^{N-1}u_1+\sum_{j=2}^{N}\binom{N}{j}u_0^{N-j}u_1^{j}h_{j-1}(y_1,y_2).
$$
Here we used that $s_{(j-1,1)}(y_1,y_2)=y_1y_2h_{j-2}(y_1,y_2)$.
\end{example}


\subsection{Specialization}

In this section we consider a certain specialization of $u_k$. 

\begin{definition}
Fix a number $M\gg 0$. We define the specialization homomorphism
$$
\varphi_M:\Q[u_0,\ldots,u_{n-1},y_1,\ldots,y_n]\to \Q[y_1,\ldots,y_n]
$$
$$
\varphi_M(u_k)=(-1)^{n-1-k}s_{(M-n+1,1^{n-1-k})}(\yy).
$$
\end{definition}

\begin{lemma}
\label{lem: specialization}
Under the homomorphism $\varphi_M$, we have the following specializations:
$$
\varphi_M(x_i)=y_i^M,\quad \varphi_M(d_N(\zeta_k))=h_{MN-k}(\yy).
$$
\end{lemma}

\begin{proof}
Let us apply Lemma \ref{lem: remainder skew Schur}   to $f(z)=z^M$. We get $r_k=\varphi_M(u_k)$, so
$$
\varphi_M(u(z))=z^M\mod p(z)
$$
and $\varphi_M(x_i)=\varphi_M(u(y_i))=y_i^M$. This proves the first equation. For the second equation, note that by the above
\begin{equation}
\label{eq: Nth powers agree}
\varphi_M(u(z)^N)\mod p(z)=z^{MN}\mod p(z).
\end{equation}
By applying Lemma \ref{lem: remainder skew Schur} to both sides of \eqref{eq: Nth powers agree} , we get
$$
\varphi_M(d_N(\xi_k))=(-1)^{n-1-k}s_{MN-n+1,1^{n-1-k}}(\yy).
$$
and by Lemma \ref{lem: change of variables} we get
$$
\varphi_M(d_N(\zeta_k))=h_{MN-k}(\yy).
$$
\end{proof}

\begin{lemma}
\label{lem: regular sequence}
a) The polynomials $d_N(\zeta_k)$ defined by \eqref{eq: dN zeta} form a regular sequence. 

b) The polynomials $d_N(\xi_k)$ defined by \eqref{eq: dN xi} form a regular sequence.
\end{lemma}

\begin{proof}
Consider a longer sequence 
\begin{equation}
\label{eq: long sequence}
u_0-\varphi_M(u_0),\ldots,u_{n-1}-\varphi_M(u_{n-1}),d_N(\zeta_0),\ldots,d_N(\zeta_{n-1}).
\end{equation}
Clearly, $u_0-\varphi_M(u_0),\ldots,u_{n-1}-\varphi_M(u_{n-1})$ form a regular sequence, let $I$  denote the ideal generated by these polynomials. Then 
$$
\Q[u_0,\ldots,u_{n-1},y_1,\ldots,y_{n}]/I\simeq \Q[y_1,\ldots,y_n]
$$
and for all polynomials $g\in \Q[u_0,\ldots,u_{n-1},y_1,\ldots,y_{n}]$ we have $g=\varphi_M(g)\mod I$. In particular, by Lemma \ref{lem: specialization} we get
$$
d_N(\zeta_k)=\varphi_M(d_N(\zeta_k))=h_{MN-k}(\yy)\mod I.
$$
Since $h_{MN}(\yy),h_{MN-1}(\yy),\ldots,h_{MN-n+1}(\yy)$ form a regular sequence in $\Q[y_1,\ldots,y_n]$, we conclude that $d_N(\zeta_0),\ldots,d_N(\zeta_{n-1})$ form a regular sequence modulo $I$, and the sequence \eqref{eq: long sequence} is regular.

Next, we define a grading on $\Q[u_0,\ldots,u_{n-1},y_1,\ldots,y_{n}]$ such that $\deg(y_i)=1$ and $\deg(u_k)=M-k$. The polynomials $u_k-\varphi_M(u_k)$ are homogeneous with respect to this degree. The polynomials $d_N(\zeta_k)$ are also homogeneous since every term in \eqref{eq: dN zeta} has degree
$$
(M-j_1)+\ldots+(M-j_N)+(j_1+\ldots+j_N-k)=MN-k.
$$
It is well known that whenever a sequence of homogeneous polynomials in a (positively) graded ring is regular in one order, it is regular in any other order, and therefore any subsequence is regular. We conclude that $d_N(\zeta_0),\ldots,d_N(\zeta_{n-1})$ is a regular sequence. Since the $\xi_k$ are related to the $\zeta_k$ by a unitriangular matrix, the sequence $d_N(\xi_0), \dots,d_N(\xi_{n-1})$ is also regular and generates the same ideal.
\end{proof}

\subsection{Divided differences}

The symmetric group $S_n$ acts on $\k[\yy,\uu,\xxi]$ by permuting the $y_i$ and leaving the $u_k$ and $\xi_k$ fixed, and this action commutes with both the differential $d_N$ and the specialization map $\varphi_M$ from the previous section. Therefore, for $s_i = (i \quad i+1)$ a transposition, the divided difference operator
\begin{equation*}
    \partial_i: f \mapsto (f - s_if) / (y_i - y_{i+1})
\end{equation*}
acts on $\k[\yy,\uu,\xxi]$, commuting with $d_N$ and $\varphi_M$, since the coefficient in $\yy$ of any monomial in $\uu$ and $\xxi$ of $f - s_if$ will be divisible by $y_i - y_{i+1}$.

These operators provide another route to the above calculations. If we set $\partial_* = \partial_{n-1}\cdots\partial_2\partial_1$, then $\partial_* y_1^k = h_{k-n+1}(\yy)$, so the elements $\zeta_k$ from above may be expressed as
\begin{equation*}
    \zeta_k = \sum_i h_i(\yy) \xi_{k+i} = \partial_* \sum_i y_1^{k+n-1} \xi_{k+i} = \partial_* \left(y_1^{n-1-k} \theta_1 \right)
\end{equation*}
Therefore, $$d_N \zeta_k = \partial_*\left(y_1^{n-1-k} d_N(\theta_1) \right) = \partial_*\left(y_1^{n-1-k} x_1^N \right).$$ This immediately gives the specialization $$\varphi_M (d_N \zeta_k) = \partial_*\left(y_1^{n-1-k} \cdot y_1^{MN} \right) = h_{MN - k}(\yy),$$ and a slightly more involved calculation recovers equation~\eqref{eq: dN zeta} as well.

\subsection{Coproduct}

As a side remark, we can define a curious coproduct on $\HY(\PP_n^y)$ over $\k[\yy]$. Suppose that we have two interpolation problems
$$
u_0+u_1y_i+\ldots+u_{n-1}y_i^{n-1}=x_i,\ \widetilde{u}_0+\widetilde{u}_1y_i+\ldots+\widetilde{u}_{n-1}y_i^{n-1}=\widetilde{x_i}
$$
and we want to solve the interpolation problem 
$$
v_0+v_1y_i+\ldots+v_{n-1}y_i^{n-1}=x_i\widetilde{x_i}.
$$
Then we can write 
\begin{equation}
\label{eq: coproduct}
v(z)=u(z)\widetilde{u}(z)\mod p(z)
\end{equation}
and this uniquely determines $v_k$ as polynomials of $u_i,\widetilde{u}_i,y_i$. By Lemma \ref{lem: remainder skew Schur} we get
\begin{equation}
v_k=\sum_{i+j=k}u_i\widetilde{u}_{j}+(-1)^{n-k-1}\sum_{i+j\ge n}u_i\widetilde{u_j}s_{(i+j-n+1,1^{n-1-k})}(y_1,\ldots,y_n).
\end{equation}
We can interpret \eqref{eq: coproduct} as a coproduct
$$
\Delta:\HY(\PP_n^y)\to \HY(\PP_n^y)\otimes_{\k[\yy]}\HY(\PP_n^y),\  \Delta(u_k)=v_k(u_i,\widetilde{u}_i,y_i).
$$
It is easy to see that $\Delta$ is cocommutative and coassociative. 



\section{Further extensions}

\subsection{An algebraic conjecture}
\label{sec: algebraic conjecture}

In this section we introduce some classes in homology of $d_N$. See \cite[section 3.3]{GOR} and \cite[section 2.2]{GL}. Recall that 
$$
d_N(\xi(z))=u(z)^N\mod z^n.
$$

\begin{definition}
For $k=1,\ldots,n-1$ we define 
$$
\mu_k=\sum_{i+j=k}(Ni-j)u_i\xi_j .
$$
\end{definition}

\begin{lemma}
We have $d_N(\mu_k)=0$.
\end{lemma}

\begin{proof}
We consider the generating functions
$$
\xi(z)=\sum_{i=0}^{n-1}\xi_iz^i,\ u(z)=\sum_{i=0}^{n-1}u_iz^i,
\dot{\xi}(z)=\sum_{i=1}^{n-1}i\xi_iz^{i-1},\ 
\dot{u}(z)=\sum_{i=1}^{n-1}iu_iz^{i-1}
$$
We have
$$
d_N(\xi(z))=u(z)^N\mod z^n,\ d_N(\dot{\xi}(z))=N\dot{u}(z)u(z)^{N-1}\mod z^{n-1}.
$$
Furthermore, we can define $\mu(z)=\sum_{k=1}^{n-1}\mu_kz^{k-1}$, then
$$
\mu(z)=\sum_{i,j}(Ni-j)u_i\xi_j  z^{i+j-1}\mod z^{n-1}=$$
$$N\sum_{i,j}iu_i z^{i-1}\cdot \xi_j z^j-\sum_{i,j}u_i z^{i}\cdot j\xi_j z^{j-1}\mod z^{n-1}=
$$
$$
N\dot{u}(z)\xi(z)-u(z)\dot{\xi}(z)\mod z^{n-1}.
$$
Therefore
$$
d_N(\mu(z))=N\dot{u}(z)u(z)^N-u(z) N\dot{u}(z)u(z)^{N-1}=0\mod z^{n-1}.
$$
\end{proof}
\begin{example}
We have $\mu_1=Nu_1\xi_0-u_0\xi_1$. Since
$$
d_N(\xi_0)=u_0^{N},\ d_N(\xi_1)=Nu_0^{N-1}u_1
$$
we get $d_N(\mu_0)=0$.
\end{example}

\begin{conjecture}
\label{conj: mu}
The homology of $d_N$ is generated by $u_i$ and $\mu_k$ as an algebra.
\end{conjecture}

For $N=2$ and $n\le 8$ this conjecture has been extensively verified  in \cite{GOR}, but remains open in general.

\begin{theorem}
\label{thm: multiplicative collapse}
Assuming Conjecture \ref{conj: mu},  Rasmussen spectral sequence for $sl(N)$ homology of $T(n,\infty)$ collapses at the $E_2$ page.
\end{theorem}

\begin{proof}
We recall that a spectral sequence $(E^{p,q}_r,d_r)$ is \emph{multiplicative} if it satisfies the following:
\begin{itemize}
\item For each $r$ there is a collection of bigraded  products
$$
E^{p,q}_{r}\otimes E^{s,t}_{r}\to E^{p+s,q+t}_{r}
$$
In other words, the $r$-th page $E^{\bullet,\bullet}_{r}$ has a bigraded algebra structure.
\item The differential $d_{r}$ on $E^{\bullet,\bullet}_{r}$ satisfies the Leibniz rule
\item The induced multiplication on $H^*(E^{\bullet,\bullet}_{r},d_r)=E^{\bullet,\bullet}_{r+1}$ agrees with the algebra structure on $E^{\bullet,\bullet}_{r+1}$.
\end{itemize}
Let $d_N^{(r)}$ denote the $r$-th differential in the Rasmussen spectral sequence, with $d_N^{(1)}=d_N$. 
By Proposition \ref{prop: braid dN multiplicativity} the spectral sequence is multiplicative, and the differentials $d_N^{(r)}$ satisfy Leibniz rule. 

By Conjecture \ref{conj: mu} the $E_2$ page of the spectral sequence is generated by $u_k$ (which have $a$-degree 0) and $\mu_k$ (which have $a$-degree 1). The differential $d_N^{(r)}$ decreases the $a$-degree by $r$ and therefore 
$$
d_N^{(r)}(u_k)=d_N^{(r)}(\mu_k)=0
$$
and $d_N^{(r)}=0$. We conclude that the spectral sequence collapses at the $E_2$ page.
\end{proof}

\subsection{More general potentials}

Let $W\in \k[x]$ be an arbitrary one-variable polynomial called the potential, and let $\partial W$ denote its derivative with respect to $x$. One can construct a more general Khovanov--Rozansky link homology theory depending on $W$, with $W(x)=\frac{1}{N+1}x^{N+1}$ corresponding to $\gll_N$ homology. The construction runs as follows.

Let $M\in \SBim_n$ be a Soergel bimodule, and $F^{\bullet}$ is free resolution. As in Lemma \ref{lemma:res and h} we can find $d_{\partial W}\in \End(F^{\bullet})$ such that 
\begin{equation}
\label{eq: dW commutator}
[d_F,d_{\partial W}]=\sum_{i=1}^{n}\left(W(x_i)-W(x'_i)\right),
\end{equation}
since the right hand side is symmetric in $\xx,\xx'$ and vanishes on $M$. Furthermore $d_{\partial W}\circ d_{\partial W}$ is closed and exact. The right hand side of \eqref{eq: dW commutator} vanishes on $F^{\bullet}\otimes_{\k[\xx,\xx']}R$ and defines a differential $d_{\partial W}$ on $\HH(M)$. 

In the Koszul complex $\Delta_n(\xx,\xx')$ we have
$$
d_{\partial W}(\theta_i)=\frac{W(x_i)-W(x'_i)}{x_i-x'_i}
$$
which becomes $\partial W(x_i)$ after specializing $x_i=x'_i$. This explains the notations for the differential.

One can replace $d_N$ by $d_{\partial W}$  rest of the the constructions in Section \ref{ss: Rasmussen} extend verbatim and allow one to define link homology theory $H_{\partial W}$ (resp. $\HY_{\partial W}$), and a spectral sequence from $\HHH$ (resp. $\HY$) to it.
We can now generalize Theorem \ref{thm: y-ified differential} to this setting.

\begin{theorem}
\label{thm: y-ified W differential}
The differential $d_{\partial W}$ on $\HY(\PP_n^y)$ is given by the generating function
\begin{equation}
\label{eq: dN y-ified W}
d_{\partial W}(\xi(z))=\partial W(u(z)) \mod p(z).
\end{equation} 
\end{theorem}

\begin{proof}
As in the proof of Theorem \ref{thm: y-ified differential}, we note that $d_{\partial W}(y_i)=0$, so $d_{\partial W}(\Delta_n)=0$ and $d_{\partial W}$ commutes with localization in $\Delta_n$.

Furthermore, $d_{\partial W}(\xi_i)$ is a polynomial in $y_i,u_i$, and we define
$$
g_{\partial W}(z)=d_{\partial W}(\xi(z))=d_{\partial W}(\xi_0)+d_{\partial W}(\xi_1)z+\ldots+d_{\partial W}(\xi_{n-1})z^{n-1}.
$$
This is a polynomial in $z$ of degree at most $n-1$, and its value at $y_i$ equals
$$
g_{\partial W}(z=y_i)=
d_{\partial W}(\xi(z))=d_{\partial W}(\xi_0)+d_{\partial W}(\xi_1)y_i+\ldots+d_{\partial W}(\xi_{n-1})y_i^{n-1}=
$$
$$
d_{\partial W}(\xi_0+\xi_1y_i+\ldots+\xi_{n-1}y_i^{n-1})=d_{\partial W}(\theta_i)=\partial W(x_i)=\partial W(u_0+u_1y_i+\ldots+u_{n-1}y_i^{n-1}).
$$
Therefore by Lemma \ref{lem: remainder} we get
$$
g_{\partial W}(z)=\partial W(u(z))\mod p(z).
$$
\end{proof}

By specializing $y_i=0$ we get the following.

\begin{theorem}
\label{thm: HHH W differential}
There is a spectral sequence with $E_1$ page $$E_1=\HHH(\PP_n)\simeq \C[ u_0,\ldots, u_{n-1},\xi_0,\ldots,\xi_{n-1}]$$  and $E_2$ page is given by 
$$
E_2=H^*(E_1,d_{\partial W}),\  d_{\partial W}( \xi(z))=\partial W(u(z)) \mod z^n.
$$
The differential $d_{\partial W}$ satisfies Leibniz rule.
\end{theorem}


To find the analogue of $\mu(z)$ from Section \ref{sec: algebraic conjecture}, we define a polynomial 
$$H(x)=\mathrm{GCD}(\partial W(x),\partial^2 W(x)).$$
Concretely, if $\partial W(x)=\prod_{i=1}^{s} (x-\lambda_i)^{m_i}$ then $$H(x)=\prod_{m_i\ge 2} (x-\lambda_i)^{m_i-1}.$$
If all roots $\lambda_i$ of $\partial W(x)$ are simple and $m_i=1$ then we set $H(x)=1$.

\begin{lemma}
The coefficients of the following series are in the kernel of $d_{\partial W}$:
\begin{equation}
\mu^{W}(z)=\sum_{i=0}^{n-1}\mu^W_iz^i=\frac{\partial^2 W(u(z))}{H(u(z))}\dot{u}(z)\xi(z)-\frac{\partial W(u(z))}{H(u(z))}\dot{\xi}(z)\mod z^n.
\end{equation}
\end{lemma}

Note that by construction $H(x)$ divides both $\partial^2W(x)$ and $\partial W(x)$, so $\mu^{W}(z)$ is well defined.

\begin{proof}
Indeed, we have $d_{\partial W}(\xi(z))=\partial W(u(z))$, therefore $d_{\partial W}(\dot{\xi}(z))=\partial^2 W(u(z))\dot{u}(z)$. Now 
$$
d_{\partial W}(\mu^{W}(z))=d_{\partial W}\left(\frac{\partial^{2}W(u(z))}{H(u(z))}\dot{u}(z)\xi(z)-\frac{\partial W(u(z))}{H(u(z))}\dot{\xi}(z)\right)=
$$
$$
\frac{\partial^2 W(u(z))}{H(u(z))}\dot{u}(z)\partial W(u(z))-\frac{\partial W(u(z))}{H(u(z))}\partial^2 W(u(z))\dot{u}(z),
$$
and the result follows.
\end{proof}

\begin{conjecture}
\label{conj: mu W}
The homology of $d_W$ is generated by $u_i$ and $\mu_k^W$ as an algebra.
\end{conjecture}

We conclude the following.

\begin{theorem}
Assuming Conjecture \ref{conj: mu W},  Rasmussen spectral sequence for Khovanov--Rozansky homology of $T(n,\infty)$ with potential $W$ collapses at the $E_2$ page.
\end{theorem}


