\title{Unknottedness of symplectic submanifold fillings}
\author{Zhengyi Zhou}
\date{\today}
\begin{document}
	\maketitle
\begin{abstract}
We show that any symplectic filling of the standard contact submanifold $(\Sphere^{2n-1},\xi_{\std})$ of $(\Sphere^{2n+1},\xi_{\std})$ in $(\disk^{n+1},\omega_{\std})$ is smoothly unknotted if $n\ge 2$. We also give a self-contained proof of the Siefring intersection formula between punctured holomorphic curves and holomorphic hypersurfaces used in the proof using the $L$-simple setup of Bao-Honda. 
\end{abstract}
