\section{Cubic non-residues I}
\label{sec:I}
Let $K$ be a cyclic cubic field with a prime conductor $f$ and let us fix a Dirichlet character $\chi$ modulo $f$ of order $3$ (there are only two such characters, and they are complex conjugates). An integer $n$ is called a non-residue modulo $f$ if $\chi(n) \not \in \{0,1\}$. As described in~\cite{McGown1}, the norm-Euclideanity of $K$ is connected with the distribution of the first non-residues modulo $f$. Let $q_1<q_2$ denote the smallest prime cubic non-residues modulo $f$. In particular, the following criterion holds.

\begin{crit}\label{criterion: expl-non-Eucl}
\textnormal{Assume there exists some $m \in \N$ satisfying all of
\begin{align*}
&(m,q_1q_2)=1, \quad \chi(m) = \chi^{-1}(q_2), \\
&\text{if } q_1=2: 3q_2 m \leq f, \\
&\text{if } q_1\neq 2: 
\begin{cases}
    \max{\{3q_1 q_2 m,10 q_1^2 q_2\}} \leq f & \text{if} \quad q_2^2 m \equiv f \dmod{q_1} \text{ and } q_2 < 2 q_1, \\
    \max{\{2q_1 q_2 m,10 q_1^2 q_2\}} \leq f & \text{otherwise.}
\end{cases} 
\end{align*}
Then $K$ is not norm-Euclidean.}
\end{crit}
\begin{proof}
The case $q_1 = 2$ follows from Theorem 3.1 and Corollary 5.2 in \cite{McGown1}. The case $q_1 \neq 2$ is a slightly refined version of \cite[Prop.\ 6.1]{Lezowski}: to get this refinement, we note that the condition $3q_1 q_2 m \leq f$ may be replaced by $2q_1 q_2 m \leq f$ in the whole proof of \cite[Prop.\ 6.1]{Lezowski} except the case (d)(i) in which $q_2^2 m \equiv f \dmod{q_1}$ and $q_2 < 2 q_1$.
\end{proof}

This criterion is based on Heilbronn's original criterion \cite{Hei1950} and is the means by which we are able to rule out cyclic cubic fields lacking norm-Euclideanity. In order to invoke Criterion~\ref{criterion: expl-non-Eucl} for a conductor $f$, it is necessary to construct a sufficiently small non-residue $m$ which is coprime to $q_1$ and $q_2$. Theorem \ref{T:nonresidues} below ensures the existence of such an $m$ and will be one of our main detection tools for cyclic cubic fields lacking norm-Euclideanity. This theorem relies on upper bounds for the sum
\begin{equation*}
S_\chi(f,h,r):=\sum_{x=1}^{f}\left|\sum_{k=0}^{h-1}\chi(x+k)\right|^{2r}, \quad r,h \in \N,
\end{equation*}
which we cite in the proposition below.

\begin{prop}{\cite[Remark 2.1]{Trev2}}\label{prop2}
We have
\begin{equation*}
    S_\chi(f,h,r)\leq f^{1/2}h^{2r}  W(f,h,r),
\end{equation*}
where
\begin{equation*}
  W(f,h,r):=2r-1 + \frac{f^{1/2}}{h^{r}} r! \, d_r(h),
\end{equation*}
and
\begin{equation*}
  d_r(h) = \frac{1}{r! \, h^r} \sum_{n = 0}^{\lfloor \frac{r}{3} \rfloor} \left( \frac{r!}{n!(3!)^n} \right)^2 \frac{h^{r-n}}{(r - 3n)!}.
\end{equation*}
The values of $d_r(h)$, $1 \leq r \leq 6$ are provided in the table below.
\begin{center}
  \begin{tabular}{|c|c|}
  \hline
  $r$ & $d_r(h)$\\
  \hline
  $1$ & $1$\\
  $2$ & $1$\\
  $3$ & $1+1/(6h)$\\
  $4$ & $1+2/(3h)$\\
  $5$ & $1+5/(3h)$\\
  $6$ & $1+10/(3h)+5/(36h^2)$ \\
  \hline
  \end{tabular}
  \end{center}
\end{prop}
\begin{theorem}\label{T:nonresidues}
Let $\chi$ be a cubic Dirichlet character modulo a prime $f$.
Let $\omega$ denote a non-trivial cube root of unity.
Let $r,h,u,v\in\N$ where $u=u_{1}u_{2}\dots u_{k}$ is the product of pairwise distinct primes $u_{i}<h$, and $v=v_{1}v_{2}\dots v_{\ell}$ is the product of pairwise distinct primes satisfying $h\leq v_{i}<f$.
Let $H \in (0,f)$ be a real number and set $X=H/h$.  
Suppose $r\leq 9h$ and $\frac{X}{u}\geq 1$, and let 
\begin{equation}
E_u(X) = 1 - \frac{\pi^2}{6}\sigma(u) \left( \frac{\sigma(u)}{4} + \frac{\phi(u)}{u} + \frac{\phi(u)}{X} \right)\frac{1}{X},
\end{equation}
where $\sigma(u) = \sum_{d | u} d$. If $E_u(X) > 0$ and
\begin{equation} \label{eq: THm6-main-condition}
    \frac{1}{E_u(X)}\frac{\pi^2}{6}\frac{\sigma(u)}{\phi(u)}uhf^{1/2}\left(\frac{2h}{h-3 \ell}\right)^{2r}\frac{W(f,h,r)}{H^2}<1,
\end{equation}
then there exists a positive integer $m \leq H$ satisfying $(m,uv)=1$ and $\chi(m)=\omega$.
%Moreover, if one only requires that $\chi(m)\in\{\omega,\omega^{-1}\}$, then one can replace the term $\left(\frac{2h}{h-2\sqrt{3}s}\right)$ with $\left(\frac{h}{h-\sqrt{3}s}\right)$.
\end{theorem}
In most of our applications, $uv = q_1q_2$ and $h \in \N$ will determine whether $q_1,q_2$ are factors of $u$ or $v$. The value of $H$ will be chosen so that $m\le H$ aligns with Criterion~\ref{criterion: expl-non-Eucl}. 

We next state some preliminary results required for the proof of Theorem \ref{T:nonresidues}. For $t,q \in \Z$ with $0\leq t<q\leq X$ and $(t,q)=1$, we define the intervals
$$ \mathcal{I}(q,t):=\left(\frac{tf}{q},\,\frac{tf+H}{q}-h+1\right]\, \quad \text{and} \quad
\mathcal{J}(q,t):=\left[\frac{tf-H}{q},\,\frac{tf}{q}-h+1\right)\,. $$

\begin{lemma} \label{IJintervals}
Let us keep the notations from Theorem \ref{T:nonresidues} and suppose $0 \leq t < q \leq X$ with $(t,q) = 1$. 
\begin{enumerate}
\item 
Let $0\leq n\leq h-1$.
If $z\in\mathcal{I}(q,t)$ then $q(z+n)-ft\in(0,H]$,
and if $z\in\mathcal{J}(q,t)$ then $q(z+n)-ft\in[-H,0)$.
\item
If $X\geq 2$ and $2HX \leq f$, then $\mathcal{I}(q,t)$, $\mathcal{J}(q,t)$, are pairwise disjoint subsets of $[-H,f-H)$.
\end{enumerate}
\end{lemma}

\begin{proof}
See \cite[Proposition 3]{KevTim}.
\end{proof}

%Let $N(X)$ denote the number of integers in the union of all the defined intervals, that is
%\begin{equation*}
%    N(X)=\sum_{\substack{0\leq t<q\leq X\\(t,q)=1}}\sum_{z\in\mathcal{I}(q,t)\sqcup\mathcal{J}(q,t)}1.
%\end{equation*}
%We will require an explicit lower bound on $N(X)$.
%In~\cite{KevTim}, it is proved that for all %$X\geq 1$, one has
%$$
%  N(X)\geq E(X)\frac{6}{\pi^2}X^2\,,
%  \qquad
%  E(X)=1-\frac{2\pi^2}{9X}\,.
%$$
For $u \in \N$, let $N_u(X)$ denote the number of integers in the union of all the intervals $\mathcal{I}(q,t)$ and $\mathcal{J}(q,t)$ satisfying $u||q$, namely
\begin{equation} \label{eq: def-N-u}
    N_u(X):=\sum_{\substack{0\leq t<q\leq X\\(t,q)=1\\u||q}}\sum_{z\in\mathcal{I}(q,t)\sqcup\mathcal{J}(q,t)}1,
\end{equation}
where $u||q$ should be interpreted as $u|q$ and $(q/u,u)=1$.

In the next two lemmas, $\vartheta$ will denote a real number with $\vert \vartheta \vert \leq 1$; $\vartheta$ does not need to be the same at each appearance.
\begin{lemma}
For a real number $X\geq 1$ and an integer $u>1$,
\begin{equation}\label{lagavulin}
X\sum_{\substack{n\leq X\\(n,u)=1}}1-\sum_{\substack{n\leq X\\(n,u)=1}}n
=\frac{1}{2}\frac{\phi(u)}{u}X^2+\frac{\vartheta}{8}\sigma(u).
\end{equation}
\end{lemma}

\begin{proof}
First we observe that
\begin{align*}
\sum_{\substack{n\leq X\\(n,u)=1}}1
&=\sum_{n\leq X} \sum_{d|(n,u)}\mu(d)
=\sum_{\substack{d|u}}\mu(d)\sum_{\substack{n\leq X\\ d|n}}1
=\sum_{\substack{d|u}}\mu(d)\sum_{\substack{n\leq X/d}}1,
\\
\sum_{\substack{n\leq X\\(n,u)=1}}n
&=\sum_{n\leq X} n\sum_{d|(n,u)}\mu(d)
=\sum_{\substack{d|u}}\mu(d)\sum_{\substack{n\leq X\\ d|n}}n
=\sum_{\substack{d|u}}\mu(d)\sum_{\substack{n\leq X/d}}nd.
\end{align*}
The expression on the left-hand side of \eqref{lagavulin} is thus equal to
\begin{equation}\label{glenmorangie}
  \sum_{d|u}d\mu(d)\left(\frac{X}{d}\sum_{x\leq \frac{X}{d}}1-\sum_{n\leq\frac{X}{d}}n\right).
\end{equation}
Using the identity
\begin{equation*}
    X\sum_{n\leq X}1-\sum_{n\leq X}n=\frac{X^2}{2}-\frac{X}{2}+\frac{\{X\}-\{X\}^2}{2}
=\frac{X^2}{2}-\frac{X}{2}+\frac{\vartheta}{8},
\end{equation*}
we rewrite \eqref{glenmorangie} as follows
\begin{equation*}
    \frac{X^2}{2}\sum_{d|u}\frac{\mu(d)}{d}-\frac{X}{2}\sum_{d|u}\mu(d)+\frac{\vartheta}{8}\sum_{d|u}d\mu^2(d).
\end{equation*}
We conclude the proof by noting that $\sum_{d|u}\mu(d) = 0$ since $u>1$.
\end{proof}

\begin{lemma}\label{L:sumstuff}
For a real number $X\geq 1$ and an integer $u>1$, we have
\begin{equation*}
X\sum_{\substack{q\leq X\\u||q}}\frac{\phi(q)}{q}-\sum_{\substack{q\leq X\\u||q}}\phi(q)
=
\frac{3}{\pi^2u}\left(\prod_{p|u}\frac{p-1}{p+1}\right)X^2
+ \vartheta \frac{\phi(u) X}{2 u}
\left(
\frac{\sigma(u)}{4} + \frac{\phi(u)}{u} + \frac{\phi(u)}{X}
\right).
\end{equation*}
\end{lemma}

\begin{proof}
We have
\begin{align*}
&\sum_{\substack{q\leq X\\u||q}}\frac{\phi(q)}{q}
=
\sum_{\substack{q\leq \frac{X}{u}\\(q,u)=1}}\frac{\phi(uq)}{uq}
=
\frac{\phi(u)}{u}
\sum_{\substack{q\leq \frac{X}{u}\\(q,u)=1}}\sum_{d|q}\frac{\mu(d)}{d}
=
\frac{\phi(u)}{u}
\sum_{\substack{d\leq \frac{X}{u}\\(d,u)=1}}\frac{\mu(d)}{d}\sum_{\substack{q\leq \frac{X}{ud}\\(q,u)=1}} 1,
\\
&\sum_{\substack{q\leq X\\u||q}}\phi(q)
=
\sum_{\substack{q\leq \frac{X}{u}\\(q,u)=1}}\phi(uq)
=
\phi(u)\sum_{\substack{q\leq \frac{X}{u}\\(q,u)=1}}q\sum_{d|q}\frac{\mu(d)}{d}
=
\phi(u)
\sum_{\substack{d\leq \frac{X}{u}\\(d,u)=1}}
\mu(d)\sum_{\substack{q\leq \frac{X}{ud}\\(q,u)=1}} q.
\end{align*}
Therefore
\begin{align}\label{glenfiddich}
X\sum_{\substack{q\leq X\\u||q}}\frac{\phi(q)}{q}-\sum_{\substack{q\leq X\\u||q}}\phi(q)
&=
\phi(u)\sum_{\substack{d\leq\frac{X}{u}\\(d,u)=1}}\mu(d)
\left(
\frac{X}{ud}\sum_{\substack{q\leq\frac{X}{ud} \notag \\(q,u)=1}}1
-
\sum_{\substack{q\leq\frac{X}{ud}\\(q,u)=1}}q
\right)
\\
&=
\frac{1}{2}\frac{\phi(u)^2}{u^3}X^2
\sum_{\substack{d\leq \frac{X}{u}\\(d,u)=1}}\frac{\mu(d)}{d^2}
+
\frac{\phi(u)\sigma(u)}{8}\sum_{\substack{d\leq \frac{X}{u}\\(d,u)=1}}\vartheta,
\end{align}
where the absolute value of the second term in \eqref{glenfiddich} is bounded by
\begin{equation*}
    \frac{\phi(u)\sigma(u)}{8u} X.
\end{equation*}
We rewrite the first term in \eqref{glenfiddich} as follows
\begin{align*}
&
\frac{1}{2}\frac{\phi(u)^2}{u^3}X^2
\sum_{\substack{d\leq \frac{X}{u}\\(d,u)=1}}\frac{\mu(d)}{d^2}
\\
\qquad
&=
\frac{1}{2}\frac{\phi(u)^2}{u^3}X^2
\sum_{\substack{(d,u)=1}}\frac{\mu(d)}{d^2}
-
\frac{1}{2}\frac{\phi(u)^2}{u^3}X^2
\sum_{\substack{d>\frac{X}{u}\\(d,u)=1}}\frac{\mu(d)}{d^2}
\\
\qquad
&=
\frac{1}{2}\frac{\phi(u)^2}{u^3}X^2
\frac{6}{\pi^2}\prod_{p|u}\left(1-\frac{1}{p^2}\right)^{-1}+\frac{\vartheta}{2}\frac{\phi(u)^2}{u^3}X^2 \left( \frac{u}{X} + \frac{u^2}{X^2} \right)
\\
\qquad
&=
\frac{3}{\pi^2}\frac{1}{u}\left(\prod_{p|u}\frac{p-1}{p+1}\right)X^2+\frac{\vartheta}{2}\frac{\phi(u)^2}{u^2}X + \frac{\vartheta}{2} \frac{\varphi(u)^2}{u}.
\end{align*}

%\begin{align*}
%%\frac{\phi(u)\sigma(u)}{8}\sum_{\substack{d\leq \frac{X}{u}\\(d,u)=1}}1
%%\leq
%\frac{\phi(u)\sigma(u)}{8}\left(
%\frac{\phi(u)}{u}\frac{X}{u}+\tau(u)\right)
%=
%\frac{\phi(u)^2\sigma(u)}{8u^2}X+\frac{\phi(u)\sigma(u)\tau(u)}{8}
%\end{align*}
\end{proof}
We remark that with more work one could reduce the $\phi(u) \sigma(u)$ term in the conclusion of the lemma by a factor of $6\pi^{-2}$, by using the fact that we are summing over square-free numbers. The bound stated in the lemma is sufficient for our purposes.
\begin{lemma}\label{prop3}
Let us keep the notations from Theorem \ref{T:nonresidues} and let $N_u(X)$ be as in \eqref{eq: def-N-u}. We have
$$
  N_u(X)\geq E_u(X)\frac{6}{\pi^2}\frac{1}{u}\frac{\phi(u)}{\sigma(u)}X^2h\,.
$$
\end{lemma}
%Notice that the product can also be written as
%\[
%  \prod_{p|u}\frac{p-1}{p+1}=\frac{\phi(u)}{\sigma(u)}\geq \frac{C_1}{(\log\log u)^2}
%  \,.
%\]
%Moreover, one has
%\[
%  E_u(X)
%  \geq 1-\frac{C_2}{X}(u\log\log u)^2
%  \,.
%\]
\begin{proof}
Since the number of integer points in $I(q,t) \sqcup J(q,t)$ is at least $2\left(\frac{H}{q} - h\right)$, we have:
\begin{align*}
    N_u(X) &= \sum_{\substack{1 \leq q\leq X\\u||q}} \sum_{\substack{0 \leq t < q\\(t,q)=1}} \sum_{z \in I(q,t) \sqcup J(q,t)} 1 \\
    &\geq 2 \sum_{\substack{1 \leq q\leq X\\u||q}} \left(\frac{H}{q} - h\right) \sum_{\substack{0 \leq t < q\\(t,q)=1}} 1\\
    &= 2h \left( X \sum_{\substack{1 \leq q\leq X\\u||q}} \frac{\varphi(q)}{q} - \sum_{\substack{1 \leq q\leq X\\u||q}} \varphi(q) \right).
\end{align*}
The last lower bound combined with Lemma \ref{L:sumstuff} conclude the proof.
\end{proof}

The following is a modification of \cite[Lemma 5]{Ma}.

\begin{lemma}\label{nicelemma}
Let us keep the notations from Theorem \ref{T:nonresidues} and suppose $3\ell \leq h$. Consider coprime integers $q,t$ satisfying $0 \leq t < q \leq X$. For a fixed choice of cube root of unity $\omega$, assume that $\chi(N)\neq\omega$ for all integers $N\in[1,H]$
with $(N,uv)=1$. If $u\mid q$, then for every integer $z\in\mathcal{I}(q,t)\sqcup\mathcal{J}(q,t)$,
$$
  \left|\sum_{n=0}^{h-1}\chi(z+n)\right|
  \geq
  \frac{h-3\ell}{2}\,.
$$
\end{lemma}

\begin{proof}
We consider only $z\in\mathcal{I}(q,t)$, the case $z\in\mathcal{J}(q,t)$ has a similar proof. By Lemma \ref{IJintervals}, if $0\leq n\leq h-1$, then one has $q(z+n)-tf \in (0,H]$. If additionally, $(q(z+n)-tf, uv) = 1$, then $\chi(q(z+n)-tf) \neq \omega$ by assumption. Let us show that $(q(z+n)-tf, uv) \neq 1$ for at most $\ell$ choices of $n$.

Since $f$ is prime and $0 \leq q(z+n)-tf \leq H < f$, it follows that $(q(z+n)-tf,u)=1$. Thus, it is sufficient to show that for every $1 \leq i \leq \ell$, $v_{i}\mid q(z+n)-tf$ for at most one choice of $n \in [0, h-1]$.

Suppose that $v_{i}\mid q(z+n_1)-tf$ and $v_{i}\mid q(z+n_2)-tf$ for two different values $n_1,n_2 \in [0,h-1]$, then $v_{i}\mid q(n_1 - n_2)$. If $v_i \nmid q$, then $v_i \mid tf$ and thus $v_i \mid f$ by the coprimality of $t$ and $f$, which contradicts the primality of $f$. Hence, $v_i$ divides $n_1 - n_2$ implying $h \leq v_{i} \leq n_1-n_2 \leq h-1$, which contradicts the definitions of $n_1$ and $n_2$.

The argument above implies that $\chi(z+n)$, $0 \leq n \leq h-1$, coincides with $\omega$ for at most $\ell$ values of $n$. Moreover, $\chi(z+n) \neq 0$ since $0 < z + n < f$, whence we can write
\begin{equation*}
    \sum_{n=0}^{h-1} \chi(z+n) = a \times  \omega +b \times  \omega^2 +c \times  1,
\end{equation*}
where $a \leq \ell$ and $a+b+c = h$. We have
\begin{equation*}
\left| \sum_{n=0}^{h-1} \chi(z+n) \right| = | \omega |\left|\left(a-\frac{b+c}{2}\right) + i\left(\frac{\sqrt{3}}{2}(b-c)\right) \right| \geq \left|a-\frac{b+c}{2}\right|,
\end{equation*}
where $a - \frac{b+c}{2} = \frac{3a-h}{2} \leq \frac{3\ell-h}{2} \leq 0$ by assumption. This concludes the proof.
\end{proof}

\begin{proof}[Proof of Theorem \ref{T:nonresidues}]
Suppose that $\chi(n)\neq\omega$ for all $n\in[1,H]$ with $(n,uv)=1$.
%Let $q_1q_2=uv$ where $u$ and $v$ are as in Lemma \ref{nicelemma}.
%Recall that the lemma requires we write $u=q_{1}q_{2}\dots q_{k}$ with each prime
%$q_{i}<h$ and $v=r_{1}r_{2}\dots r_{j}$ with each prime $h\leq v_{i}<p$.
%In particular, we see
%\[
%  u=\begin{cases}
%  1 & h < q_1 < q_2\\
%  q_1 & q_1\leq h < q_2\\
%  q_1 q_2 & q_1<q_2\leq h
%  \,.
%  \end{cases}
%\]
%
%We will do most of the proof independent of which case we are in.
Using Lemma \ref{nicelemma} and Lemma \ref{prop3} we find
\begin{align*}
S_\chi(f,h,r)
&=
\sum_{x=0}^{f-1} \left|\sum_{m=0}^{h-1} \chi(x+m) \right|^{2r}
\\
&\geq
\sum_{\substack{0\leq t< q\leq X \\ (q,t) = 1\\u | q}}
\sum_{z\in\mathcal{I}(q,t)\sqcup\mathcal{J}(q,t)}
\left|\sum_{m=0}^{h-1}\chi(z+m) \right|^{2r} 
\\
&\geq
\left(\frac{h-3 \ell}{2}\right)^{2r}
N_u(X)
\\
&\geq
E_u(X)
\frac{6}{\pi^2}\frac{1}{u}\frac{\phi(u)}{u}X^2 h
\left(\frac{h-3 \ell}{2}\right)^{2r}
\,.
\end{align*}
Combining this with Proposition \ref{prop2} gives
$$
E_u(X)
\frac{6}{\pi^2}\frac{1}{u}\frac{\phi(u)}{u}X^2 h
\left(\frac{h-3 \ell}{2}\right)^{2r}
\leq
f^{1/2}h^{2r}
W(f,h,r).
$$
We substitute $X=H/h$ and solve for $H^2$ to find
$$
  H^2\leq
  \frac{1}{E_u(X)}
  \frac{\pi^2}{6}\frac{u^2}{\phi(u)}
  hf^{1/2}\left(\frac{2h}{h-3 \ell}\right)^{2r}
  W(f,h,r).
$$
\end{proof}

\section{The case when $q_1=2$}
\begin{theorem} \label{T:1}
When $q_1=2$, there are no norm-Euclidean cyclic cubic fields with conductor $f\geq 10^{14}$.
\end{theorem}
\begin{proof}
Suppose $q_1=2$ and $f\geq 10^{14}$. Our goal is to invoke Theorem \ref{T:nonresidues} with $uv = q_1 q_2$ to show there exists $m\in\N$ such that $(m,q_1q_2)=1$ and $3q_2 m\leq f$.

Let $\lambda=3/4$, and $h=\lceil \lambda f^{1/6}\rceil$.
Note that $162 \leq h \leq 0.76\,f^{1/6}$, which implies
\begin{equation}\label{talisker1}
  W(f,h,3)\leq 5+(6+h^{-1})\lambda^{-3}\leq 19.24
\end{equation}
and
\begin{equation}\label{talisker2}
\frac{2h}{h-3 \ell} \leq 2.1
\,.
\end{equation}
for $\ell \in \{0, 1, 2\}$.

At this point we split into two cases:  either $q_2<h$ or $q_2\geq h$.
First we assume $q_2<h$. This implies that $u=2q_2$ and $v=1$ and the condition $3q_2 m \leq f$ follows from $m \leq H$ with $H = \frac{f}{3h}$. Thus, it is left to check that \eqref{eq: THm6-main-condition} holds with the chosen parameters.

The following lower bounds
\begin{align*}
&\frac{X}{\sigma(u)}=\frac{f}{3h^2\sigma(u)}\geq \frac{f}{9 h^2 (h+1)} \geq \frac{f^{2/3}}{9 \times  0.76^2(0.76 f^{1/6}+1)}\geq 2.5\times  10^6, \\
&\frac{X}{\sigma^2(u)}=\frac{f}{3h^2\sigma^2(u)}\geq \frac{f}{27 h^2 (h+1)^2} \geq \frac{f^{2/3}}{27 \times  0.76^2(0.76 f^{1/6}+1)^2} \geq 5090, \\
&\frac{X}{\phi(u)}=\frac{f}{3h^2\phi(u)}\geq \frac{f}{3 h^3} \geq \frac{f^{1/2}}{3 \times  0.76^3}\geq 7.5\times  10^6,
\end{align*}
imply $E_u(X)\geq 0.9999$.

Since
\begin{equation*}
u\frac{\sigma(u)}{\phi(u)}=6 q_2\frac{q_2+1}{q_2-1}\leq 6h\frac{h+1}{h-1},
\end{equation*}
we have
\begin{equation*}
\frac{1}{E_u(X)}\frac{\pi^2}{6}u\frac{\sigma(u)}{\phi(u)}<7.6 f^{1/6}.    
\end{equation*}

Combining the above, we get
\begin{align*}
& \left(\frac{1}{E_u(X)}\frac{\pi^2}{6}u \frac{\sigma(u)}{\phi(u)}\right)hf^{1/2}\left(\frac{2h}{h-3 \ell}\right)^{2\times  3}W(f,h,3) \\
& \leq (7.6 f^{1/6})(0.76f^{1/6})f^{1/2} \times  2.1^6 \times  19.24 \\
& < 9532 f^{5/6}.
\end{align*} 
Thus, Theorem \ref{T:nonresidues} is invocable whenever 
$$ 9532 f^{5/6} < H^2 = \left(\frac{f}{3h}\right)^2. $$
Since $h\leq 0.76 f^{1/6}$, the last condition is implied by $223 \leq f^{5/12}$, which certainly holds for $f \geq 10^{14}$.

We turn to the case $q_2\geq h$, when $u=2$ and $v=q_2$. By \cite[Corollary 2]{Ma} with $n = n_0 = 2$ and $p_0 = 10^{10}$, we have $q_2\leq 1.821 f^{1/4}(\log f)^{3/2}$. It is sufficient to prove that we can invoke Theorem \ref{T:nonresidues} when
$$
H= \frac{f}{3 \times  1.821 f^{1/4}(\log f)^{3/2}} \geq \frac{f^{3/4}}{6(\log f)^{3/2}}\, ,
$$
since $3 q_2 m < f$ whenever $m < H$.
We have $X \geq 14213$, $E_2(X) \geq 0.9995$, and thus
\begin{equation*}
\frac{1}{E_2(X)}\frac{\pi^2}{6}\frac{\sigma(2)}{\phi(2)} \times  2 <10.
\end{equation*}

Therefore
\begin{align*}
& \left(\frac{1}{E_u(X)}\frac{\pi^2}{6}u \frac{\sigma(u)}{\phi(u)}\right)hf^{1/2}\left(\frac{2h}{h-3 \ell}\right)^{6}W(f,h,3) \\
& \leq (10)hf^{1/2} \times  2.1^6 \times  7.4 \\
& < 12543 f^{2/3}.
\end{align*} 
Thus, Theorem \ref{T:nonresidues} is invocable whenever 
$$ 12543 f^{2/3} < H^2 = \left(\frac{f^{3/4}}{6(\log f)^{3/2}}\right)^2. $$
The condition follows from $672 < f^{5/12}/(\log f)^{3/2}$,
which holds for $f\geq 10^{14}$. This concludes the proof.
\end{proof}
