\section{Lower bounds for $q_1$ and $q_2$}

We next focus on improving the upper bound for the conductor of a norm-Euclidean cyclic cubic field. We prove the following:
\begin{theorem}\label{T:2}
When $q_1\neq 2$, there are no norm-Euclidean cyclic cubic fields with conductor $f \geq 2 \times 10^{20}$.
\end{theorem}
In light of Theorem \ref{T:1}, we may assume throughout this section that $q_1\neq 2$. In addition, we assume $f \geq 2 \times 10^{20}$. 

Our proof of Theorem~\ref{T:2} proceeds in a number of stages. We first dispense with small values of $q_1,q_2$.

\begin{prop} \label{fixedprop14}
If the cubic cyclic number field $K$ with conductor $f\geq 2 \times 10^{20}$ is norm-Euclidean, then $q_1 \ge 379$ and $q_2 \ge 1.3 f^{1/6}$.
\end{prop}

To prove the proposition we will require the following result.
\begin{lemma}
\label{lem:mcgownR}
Let $\omega$ be a primitive root of unity. Then for every $k \in \N$, there exists a computable positive constant $D(k)$ such that whenever $f$ satisfies 
\begin{align}
\label{eq:mcgownq}
\frac{4f^{1/4}}{\log^{1/2}f}\geq (2D(k))^k,
\end{align}
there exists a positive integer $m$ satisfying $(m,q_1q_2)=1$, $\chi(m)=\omega$, and 
\begin{align}
\label{eq:mcgownr}
m<(2D(k))^{k}f^{(k+1)/(4k)}(\log^{1/2} f).
\end{align}
If $q_1 \ge 5$ then we may take $D(3)\leq 14.8368$.
\end{lemma}
\begin{proof}
This is a special case of~\cite[Proposition 5.7]{McGown1}.
\end{proof}

\begin{proof}[Proof of Proposition \ref{fixedprop14}]
We proceed via a contrapositive argument. Assume $q_1 < 379$ or $q_2 < 1.3 f^{1/6}$. We split the argument into three cases and show in each of them that Criterion \ref{criterion: expl-non-Eucl} holds, and thus $K$ is not norm-Euclidean.

\noindent
{\bf Case I:}  $3 = q_1 < q_2 < 1.3 f^{1/6}$.
We invoke Theorem~\ref{T:nonresidues} with $q_1 = 3$, $r = 3$, $h=\lceil 1.3 f^{1/6}\rceil$, $H = \frac{f}{9 h} \leq \frac{f}{3 q_1 q_2}$, and $u=3q_2$. Via computation in Python 3.12, the left-hand side of \eqref{eq: THm6-main-condition} never exceeds $10^{-14}$, hence by Theorem \ref{T:nonresidues}, there exists an integer $m \leq H \leq \frac{f}{3 q_1 q_2}$ coprime to $q_1 q_2$ and satisfying $\chi(m) = \chi^{-1}(q_2)$, i.e.,\ Criterion \ref{criterion: expl-non-Eucl} holds.

\noindent
{\bf Case II:}  $3 < q_1 < q_2 < 1.3 f^{1/6}$.
By Lemma \ref{lem:mcgownR}, for $5 \le q_1 < q_2$ and $k=3$, we have
\begin{equation*}
m < (2 \cdot 14.8369)^3 f^{1/3} (\log^{1/2} f) < 26129 f^{1/3} (\log^{1/2} f) \leq \frac{f}{3 q_1 q_2},
\end{equation*}
where the last bound is implied by $q_1 < q_2 < 1.3 f^{1/6}$ and $f \geq 2 \times 10^{20}$. We conclude that $K$ is not norm-Euclidean by Criterion \ref{criterion: expl-non-Eucl}.

\noindent
{\bf Case III:}  $q_1 < 379 < 1.3 f^{1/6} \le q_2$.
Then $q_1 \leq 373$ since it is prime and $q_2 \ge 1.3 f^{1/6} \ge 3143 > 2 q_1$. For each prime $q_1 \le 373$, we invoke Theorem \ref{T:nonresidues} with $r = 3$, $H = \frac{f}{2 \times  373 \times 1.821 \log^{3/2} f^{1/4}} \leq \frac{f}{2 q_1 q_2}$, and $u=q_1$. Via computation in Python 3.12, the left-hand side of \eqref{eq: THm6-main-condition} never exceeds $0.95456$, thus implying Criterion \ref{criterion: expl-non-Eucl}.
\end{proof}

\section{Character sum estimates}
\label{charsum}
To complete the proof of Theorem~\ref{T:2}, by Proposition~\ref{fixedprop14} it is sufficient to consider $q_1,q_2$ large. In this section we will establish new character sum estimates, which will be combined with Vinogradov's sieve in Section~\ref{sec:vino} to obtain improved bounds for $q_1,q_2$ in the cases not covered by Theorem~\ref{T:1} and Proposition~\ref{fixedprop14}. Finally, in Section~\ref{sec:II} we will complete the proof of Theorem~\ref{T:2}. Our main result of this section is as follows.
\begin{theorem}
\label{thm:1}
Let $f$ be prime and $U,V,T,r \in \N$. Consider the character $\chi$ modulo $f$ of order $3$ and some real number $0<\theta<1$. Define the quantities
\begin{align}
&S=\sum_{1\leq t \leq T}\sum_{1\leq u \leq U}\sum_{1\leq v \leq V}\chi(v-ut),\nonumber \\
&\Delta=\left(\frac{f^{1/2}W(f,T,r)}{UV}\right)^{1/2r} \label{eq:Deltadef}, \\
&
E(U, V)= \frac{6}{\pi^2} \left( U^{-1} + V^{-1} \right) \log^2 U + \left( 2.66 U^{-1} + 2.26 V^{-1} \right) \log U \label{eq:EUt}\\
&\quad \quad \quad \,\, \,+ 7.57 U^{-1} + 9.82 V^{-1},\nonumber\\
& E_1 = \Delta \times  \left(\frac{12}{\pi^2} \theta \log U + 1 + U^{\theta} \times  E(U,V)\right)^{1/2r},\nonumber\\
& E_2 = \frac{12}{\pi^2} \, U^{-\theta} + E(U,V).\nonumber
\end{align}
Suppose $UV < f$, then $|S|\leq TUV (E_1 + E_2)$.
\end{theorem}
We provide some preliminary estimates required for the proof of Theorem \ref{thm:1}. What follows is essentially due to Bourgain, Garaev, Konyagin and Shparlinski~\cite[Lemma 5]{BGKS}. Specialising to intervals starting at the origin allows for sharper numerical results. 
\begin{lemma}
\label{lem:1}
Let $f$ be prime and $U,V \in \N$ satisfying $UV < f$. Let $\lambda \not \equiv 0 \dmod{f}$ and for $1\leq \Delta$, suppose the congruence relation
\begin{equation} \label{eq:lem1cong}
v\equiv \lambda u \dmod{f}, \quad 1 \leq u \leq U, \quad 1 \leq v \leq V,
\end{equation}
has at least $\Delta$ solutions. Then there exist $u_0, v_0 \in \N$ satisfying 
\begin{align}
\label{eq:n0u0bound}
1 \leq u_0\leq \frac{U}{\Delta}, \quad 1 \leq v_0\leq \frac{V}{\Delta},  \quad (u_0, v_0)=1,
\end{align}
such that 
\begin{align*}
v_0 \equiv \lambda u_0 \dmod{f}.
\end{align*}
\end{lemma}
\begin{proof}
The congruence \eqref{eq:lem1cong} has at least one solution $(u, v)$ since $1 \leq \Delta$. Let
\begin{equation*}
    u_0 = \frac{u}{\gcd(u,v)}, \quad v_0 = \frac{v}{\gcd(u,v)}.
\end{equation*}
Since $1 \leq uv < f$, the numbers $f$ and $\gcd(u, v)$ are coprime, whence $(u_0, v_0)$ is also a solution to \eqref{eq:lem1cong}. We will show $u_0, v_0$ satisfy the inequalities in \eqref{eq:n0u0bound}. By the assumptions in the lemma,
\begin{align*}
|\{ (u, v)\in [1,U]\times [1,V] \ : \  u_0 v\equiv u v_0 \dmod{f}\}|\geq \Delta,
\end{align*}
which is equivalent to
\begin{equation} \label{eq1: lem BGKS}
|\{ (u, v)\in [1,U]\times [1,V] \ : \  u_0 v=u v_0\}|\geq \Delta,
\end{equation}
since $1 \leq UV < f$. Let $(u, v)$ be from the set in \eqref{eq1: lem BGKS}. Since $(u_0, v_0) = 1$, there exists $\ell \in \N$ such that $u = \ell u_0$ and $v = \ell v_0$. Hence, \eqref{eq1: lem BGKS} can be rewritten as follows
\begin{align*}
|\{ \ell \in \N \ : \  1\leq \ell u_0\leq U \quad \text{and} \quad 1\leq \ell n_0\leq N \}|\geq \Delta.
\end{align*}
In particular, this implies two inequalities
\begin{equation*}
|\{ \ell \in \N \ : \  1\leq \ell u_0\leq U  \}|\geq \Delta, \quad |\{ \ell \in \N \ : \  1\leq \ell n_0\leq U  \}|\geq \Delta,
\end{equation*}
and thus
\begin{equation*}
\Delta \leq \frac{U}{u_0}, \quad \Delta \leq \frac{V}{v_0},
\end{equation*}
which completes the proof of the lemma.
\end{proof}
The next lemma is elementary, though we are not aware of it appearing in the literature before now.
\begin{lemma}
\label{lem:coprimepair}
For any positive integers $U$ and $V$ we have 
\begin{equation} \label{eq1: lem coprime pairs}
|\{ (u, v)\in [1,U]\times [1,V] \ : \ (u,v)=1\}| \leq B_1(U, V),
\end{equation}
where
\begin{equation} \label{eq2: lem coprime pairs def B1(U,V)}
B_1(U, V) := \frac{6}{\pi^2} UV + \frac{6}{\pi^2} (U+V) \log U + 2.044 V + 1.652 U + 2.04 \frac{V}{\sqrt{U}} + 2.72 \sqrt{U}.
\end{equation}
\end{lemma}
\begin{proof}
Let $S$ denote the set on the left-hand side of \eqref{eq1: lem coprime pairs}. Let $\gamma = 0.577\ldots$ denote Euler's constant. Then
\begin{align*}
S&=\sum_{1\leq u \leq U}\sum_{\substack{1 \leq v\leq V \\ (u, v)=1}}1
= \sum_{1\leq u \leq U} \sum_{\substack{1 \leq v\leq V \\ d | (u, v)}} \mu(d) = \sum_{\substack{1 \leq u \leq U \\ d | u}} \mu(d) \left\lfloor \frac{V}{d} \right\rfloor = \sum_{1 \leq d \leq U} \mu(d) \left\lfloor \frac{U}{d} \right\rfloor \left\lfloor \frac{V}{d} \right\rfloor \\
&\leq UV \sum_{1 \leq d \leq U} \frac{\mu(d)}{d^2} + (U+V) \sum_{1 \leq d \leq U} \frac{\mu^2(d)}{d} + \sum_{1 \leq u \leq U} \mu^2(d) \\
&\leq UV \left( \frac{1}{\zeta(2)} + \frac{1}{U} \right) + (U + V) \left( \frac{\log U}{\zeta(2)} + \frac{\gamma}{\zeta(2)} - 2 \frac{\zeta'(2)}{\zeta^2(2)} + \frac{2.04}{\sqrt{U}} \right) + \frac{U}{\zeta(2)} + 0.68 \sqrt{U},
\end{align*}
where we used $\sum_{d \geq 1} \frac{\mu(d)}{d^2} = \frac{1}{\zeta(2)}$, \cite[(4.11)]{Buthe1}, and \cite[(4.6)]{Buthe1} respectively.
%\footnote{TST: Note Tim's slight improvement, Forrest's calculation, and the conjecture.}
We conclude by noting that $\zeta(2) = \frac{\pi^2}{6}$ and $\zeta'(2) \geq -0.94$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:1}]
Since $1 \leq u \leq U < f$, $u$ is invertible modulo $f$. Let $\overline{u}$ denote an inverse to $u$ modulo $f$, then
\begin{align*}
S&\leq \sum_{\substack{1\leq u \leq U \\ 1\leq v \leq V}}\left|\sum_{1\leq t \leq T}\chi(\overline{u}v-t)\right| \\
&\leq \sum_{\lambda=1}^{f-1}I(\lambda)\left|\sum_{1\leq t \leq T}\chi(\lambda - t)\right|,
\end{align*}
where 
\begin{align*}
I(\lambda)=\#\{ 1\leq u \leq U, \ \ 1\leq v \leq V \ : \ v\equiv \lambda u \dmod{f}\}.
\end{align*} 
Trivially, we have $I(\lambda)\leq U$. For each $j$  define the set 
\begin{align}
\label{eq:Djdef}
D_j=\{ 1\leq \lambda \leq f-1 \ : I(\lambda)=j\}.
\end{align}
We partition $S$ with respect to the parameter $\theta$ as follows
\begin{align}
\label{eq:S12}
S\leq \sum_{\substack{1\leq j \leq U^{\theta} }}\sum_{\lambda \in D_j}I(\lambda)\left|\sum_{1\leq t \leq T}\chi(\lambda - t)\right|+\sum_{\substack{ j> U^{\theta} }}\sum_{\lambda \in D_j}I(\lambda)\left|\sum_{1\leq t \leq T}\chi(\lambda - t)\right| =:  S_1+S_2.
\end{align}

\noindent
{\bf Estimation of $S_2$.}
\begin{align*}
S_2&\leq T\sum_{\substack{U^{\theta}\leq j \leq U}}j|D_j|=T\sum_{0\leq j \leq U-U^{\theta}}(U-j)|D_{U-j}| \\
&=TU\sum_{0\leq j \leq U-U^{\theta}}|D_{U-j}|-T\sum_{0\leq j \leq U-U^{\theta}}j|D_{U-j}|.
\end{align*}
By partial summation 
\begin{align*}
\sum_{0\leq j \leq U-U^{\theta}}j|D_{U-j}|=(U-U^{\theta})\sum_{0\leq j \leq U-U^{\theta}}|D_{U-j}|-\int_{0}^{U-U^{\theta}}\sum_{0\leq j \leq w}|D_{U-j}|dw,
\end{align*}
and hence 
\begin{align}
\label{eq:S2b111}
S_2\leq T \times  g(U, U^{\theta}),
\end{align}
where 
\begin{equation} \label{eq: def-g-U-Y}
g(U, Y) = Y\sum_{0\leq j \leq U-Y}|D_{U-j}|+\int_{0}^{U-Y}\sum_{0\leq j \leq w}|D_{U-j}|dw.
\end{equation}
Note that $I(\lambda)\geq (U-w)$ is equivalent to $\lambda \in D_{U-j}$ for some $0\leq j \leq w$, hence
\begin{align*}
\sum_{0\leq j \leq w}|D_{U-j}| = |\{ 0 \leq \lambda \leq q-1 \ :  \ I(\lambda)\geq U-w\}|.
\end{align*}
Let $D_{\geq U - w}$ denote the set on the right-hand side of the equation above. For each $\lambda \in D_{\geq U - w}$, we apply Lemma \ref{lem:1} with $\Delta=U-w$ to obtain a pair $(u_\lambda,v_\lambda)$ of positive integers satisfying 
\begin{equation*}
v_\lambda \equiv \lambda u_\lambda \dmod{f}, \quad 1 \leq u_\lambda\leq \frac{U}{(U-w)}, \quad 1\leq v_\lambda\leq \frac{V}{(U-w)}, \quad (u_\lambda,v_\lambda)=1.
\end{equation*}
Since for $\lambda_1 \neq \lambda_2$, the pairs $(u_{\lambda_1},v_{\lambda_1}) \neq (u_{\lambda_2},v_{\lambda_2})$, we have:
\begin{equation*}
    |D_{\geq U - w}| \leq \left|\left\{ (u, v)\in \left[1,\frac{U}{U-w}\right]\times \left[1,\frac{V}{U-w}\right] \ : \ (u,v)=1\right\}\right| \leq B_1\left( \frac{U}{U-w}, \frac{V}{U-w} \right),
\end{equation*}
with $B_1$ defined in \eqref{eq2: lem coprime pairs def B1(U,V)}. Hence by \eqref{eq:S2b111},
\begin{align*}
S_2\leq T U^{\theta} \times  B_1(U^{1-\theta}, U^{-\theta}V) + T \int_{0}^{U-U^{\theta}} B_1\left( \frac{U}{U-w}, \frac{V}{U-w} \right) dw.
\end{align*}
