S_2\leq TUV&\Big[\frac{12}{\pi^2}\frac{1}{U^{\theta}}+\frac{3}{\pi^2} (1-\theta)^2\log^2{U}\left(\frac{1}{U} + \frac{1}{V}\right) + (1-\theta)\log U \left( \frac{2.66}{U} + \frac{2.26}{V}\right) \\
&+ \frac{5.517}{U} + \frac{7.092}{V} - \frac{2.04}{U^{(3-\theta)/2}} - \frac{2.72}{U^{(1-\theta)/2}V}\Big].
\end{align}
\end{comment}

\noindent
{\bf Estimation of $S_1$.} Let $p = \frac{2r}{2r-1}$, $q = 2r$, and
\begin{equation*}
    a_\lambda = \left| \sum_{1 \leq t \leq T} \chi(\lambda - t) \right|,
\end{equation*}
then
\begin{equation*}
    S_1 = \sum_{1 \leq j \leq U^{\theta}} j \sum_{\lambda \in D_j} a_\lambda.
\end{equation*}
By H\"{o}lder's inequality,
\begin{equation*}
    \sum_{\lambda \in D_j} a_\lambda \leq |D_j|^{1/p} \left(\sum_{\lambda \in D_j} a_\lambda^{q}\right)^{1/q},
\end{equation*}
whence, by applying H\"{o}lder's inequality two more times, we get
\begin{align*} 
S_1 &\leq \sum_{1 \leq j \leq U^{\theta}} j |D_j|^{1/p} \left(\sum_{\lambda \in D_j} a_\lambda^{q}\right)^{1/q} \\
&\leq \left( \sum_{1 \leq j \leq U^{\theta}} j^p |D_j| \right)^{1/p} \times  \left( \sum_{1 \leq j \leq U^{\theta}} \left( \sum_{\lambda \in D_j} a_\lambda^{q} \right) \right)^{1/q} \\
&= \left( \sum_{1 \leq j \leq U^{\theta}} (j |D_j|)^{2-p} \times  (j^2 |D_j|)^{p-1} \right)^{1/p} \times  \left( \sum_{1 \leq j \leq U^{\theta}} \left( \sum_{\lambda \in D_j} a_\lambda^{q} \right) \right)^{1/q}\\
&\leq \left( \sum_{1 \leq j \leq U^{\theta}} j |D_j| \right)^{(2-p)/p} \times  \left(\sum_{1 \leq j \leq U^{\theta}} j^2 |D_j| \right)^{(p-1)/p} \times  \left( \sum_{1 \leq j \leq U^{\theta}} \left( \sum_{\lambda \in D_j} a_\lambda^{q} \right) \right)^{1/q}.
\end{align*}
The last chain of inequalities implies
\begin{equation} \label{eq: bound-S1-Holder}
    (S_1)^{2r} \leq \left(\sum_{1 \leq j \leq U^{\theta}}j |D_j|\right)^{2r-2}\left(\sum_{1 \leq j \leq U^{\theta}}j^2|D_j|\right) \left(\sum_{\lambda=1}^{f}\left|\sum_{1\leq t \leq T}\chi(\lambda-t)\right|^{2r}\right).
\end{equation}
We can bound the last factor on the right-hand side of \eqref{eq: bound-S1-Holder} by Proposition \ref{prop2},
\begin{equation} \label{eq: bound-S1-term3}
\sum_{\lambda=1}^{f}\left|\sum_{1\leq t \leq T}\chi(\lambda - t)\right|^{2r} = \sum_{\lambda=1}^{f}\left|\sum_{0\leq t \leq T-1}\chi(\lambda + t)\right|^{2r}
\leq f^{1/2}T^{2r}W(f,T,r).
\end{equation}
We bound the first factor in \eqref{eq: bound-S1-Holder} using
\begin{equation} \label{eq: bound-S1-term1}
\sum_{1 \leq j \leq U^{\theta}}j |D_{j}|\leq \sum_{1\leq \lambda \leq f}I(\lambda) \leq UV,
\end{equation}
since $I(\lambda)$, $1 \leq \lambda \leq f-1$, are pairwise disjoint subsets of $[1,U] \times [1,V]$. Finally, let us bound the second factor on the right-hand side of \eqref{eq: bound-S1-Holder}. By partial summation,
\begin{align*}
\sum_{1 \leq j \leq U^{\theta}}j^2|D_{j}|=U^{\theta}\sum_{1 \leq j \leq U^{\theta}}j|D_{j}|-\int_{1}^{U^{\theta}}\sum_{1\leq j\leq w}j|D_{j}|dw,
\end{align*} 
and
\begin{align*}
\sum_{1 \leq j \leq w}j |D_{j}|=UV-\sum_{w < j \leq U}j |D_{j}|,
\end{align*}
so that 
\begin{align} \label{eq: bound-j^2-Dj}
\sum_{1 \leq j \leq U^{\theta}}j^2|D_{j}|&=UV + \int_{1}^{U^{\theta}}\sum_{w < j \leq U}j |D_{j}|dw - U^{\theta}\sum_{U^{\theta} < j \leq U}j |D_{j}| \leq UV + \int_{1}^{U^{\theta}}\sum_{w \leq j \leq U}j |D_{j}|dw.
\end{align}

Arguing similarly to the proof of \eqref{eq:S2b11}, for $t\geq 1$ we have 
\begin{align*}
\sum_{w \leq j \leq U}j|D_{j}|\leq UV &\bigg( \frac{12}{\pi^2} w^{-1} + \frac{6}{\pi^2} \left( U^{-1} + V^{-1} \right) \log^2 U \\
    &\,\, + \left( 2.66 U^{-1} + 2.26 V^{-1} \right) \log U + 7.57 U^{-1} + 9.82 V^{-1} \bigg),
\end{align*}
and therefore 
\begin{align*}
\int_{1}^{U^{\theta}}\sum_{w \leq j \leq U}j |D_{j}|dw \leq 
UV &\bigg( \frac{12}{\pi^2} \theta \log U + \frac{6}{\pi^2} \left( U^{-1} + V^{-1} \right) U^{\theta}\log^2 U \\
    &\,\, + \left( 2.66 U^{-1} + 2.26 V^{-1} \right) U^{\theta} \log U + 7.57 U^{\theta -1} + 9.82 U^{\theta}V^{-1} \bigg).
\end{align*}
Combining with \eqref{eq: bound-j^2-Dj}, we obtain
\begin{equation} \label{eq: bound-S1-term2}
\sum_{1 \leq j \leq U^{\theta}}j^2|D_{j}| \leq 
UV \left( \frac{12}{\pi^2} \theta \log U + 1 + U^{\theta} \times  E(U,\theta) \right),
\end{equation}
where $E(U, \theta)$ is defined in \eqref{eq:EUt}.

The bounds \eqref{eq: bound-S1-Holder}, \eqref{eq: bound-S1-term3}, \eqref{eq: bound-S1-term1}, and \eqref{eq: bound-S1-term2} imply
\begin{equation*}
S_1 \leq TUV \times  \Delta \times \left( \frac{12}{\pi^2} \theta \log U + 1 + U^{\theta} \times  E(U,\theta) \right)^{1/2r},
\end{equation*}
with $\Delta$ defined in \eqref{eq:Deltadef}. Combining this with \eqref{eq:S12} and \eqref{eq:S2b11} completes the proof.
\end{proof}

\section{Cubic non-residues II}
\label{sec:vino}
The aim of this section is to improve on the upper bounds for $q_1,q_2$ whenever $q_1$ is bounded uniformly from below. Our approach is to combine the character sum estimates from Section~\ref{charsum} with Vinogradov's sieve.
\begin{theorem}
\label{thm:main1}
Let $2 \times 10^{20} \leq f \leq 4 \times  10^{49}$ be prime. If $q_1\geq 293$, then
$$q_{1} \leq q_{2} \leq 37  f^{0.232}.$$
\end{theorem}
The proof of Theorem~\ref{thm:main1} requires some preliminary results.
\begin{lemma}
\label{lem:dus1}
Let 
\begin{align*}
B=\gamma+\sum_{p}\left(\log\left(1-\frac{1}{p} \right)+\frac{1}{p} \right)= 0.26149\ldots.
\end{align*}
Then
\begin{align*}
%0.261497212847643
%&\sum_{p\leq x}\frac{1}{p} \leq \log\log{x}+B+\frac{0.7g81}{\log^{2}{x}} \quad \text{for } x \geq 101,\\
%&\sum_{p\leq x}\frac{1}{p} \leq \log\log{x}+B+\frac{0.5}{\log^{2}{x}} \quad \text{for } x \geq 286,\\
\sum_{p\leq x}\frac{1}{p} \leq \log\log{x}+B+\frac{1}{2\log^{2}{x}}\quad \text{for } x \geq 286.
%&\sum_{p\leq x}\frac{1}{p}<\log\log x+B+\frac{2}{\sqrt{x}\log x} \quad \text{for } 2 \leq x \leq 10^{12},\\
%&\sum_{p\leq x}\frac{1}{p}\leq\log\log x+B+\frac{6.836\times  10^{-6}}{\log x} \quad\text{for } x > 10^{12} \text{\cc{can be done with $\log^2 x$}}.
\end{align*}
\end{lemma}
\begin{proof}
See \cite[Theorem 5]{R-S}.
\end{proof}
\begin{lemma}
\label{lem:firsttwo11}
Let $T,U,V$ be positive integers, and let $V_0 = \max\{V, UT\}$. Let $\varepsilon>0$ and suppose
\begin{align}
\label{eq:firsttwoassumption}
\left|\sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U \\ 1\leq v \leq V}}\chi(v-ut)\right|\leq \varepsilon TUV.
\end{align}
If $q_2 \geq 286$ then we have 
\begin{align}
\label{eq:fft1}
\frac{1}{q_1}+\frac{1}{q_2}+\log\left(\frac{\log{V_0}}{\log{q_2}}\right)+\frac{1}{2\log^2{q_2}} + \frac{1}{2\log^2{V_0}} + \frac{2}{\log V_0} \geq \frac{2(1-\varepsilon)}{3},
\end{align}
and if moreover $q_1\geq 286$ then we have 
\begin{align}
\label{eq:fft2}
\frac{1}{q_1} + \log\left(\frac{\log{V_0}}{\log{q_1}}\right) + \frac{1}{2\log^2{q_1}} + \frac{1}{2\log^2{V_0}} + \frac{2}{\log V_0}\geq \frac{2(1-\varepsilon)}{3}.
\end{align}
\end{lemma}
\begin{proof}
The proof is based on Vinogradov's trick~\cite{Vin}. Let us define
\begin{align*}
&A_0=\{ (t,u,v)\in [1,T]\times [1,U]\times [1,V] \ : \ \chi(v-ut) = 1 \},\\
&A_0^{c}= [1,T]\times [1,U]\times [1,V] \setminus T_3.
\end{align*}
Let $\chi_0$ denote the principal character modulo $f$, and $\overline{\chi}$ the complex-conjugate character of $\chi$. Then we can express $A_0$ as follows
\begin{align*}
|A_0|=\frac{1}{3}\sum_{\psi \in \{\chi, \overline{\chi}, \chi_0\}}\sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U \\ 1\leq v \leq V}}\psi(v-ut).
\end{align*}
%where the term $-UV$ corresponds to triples $(n,u,v)$ satisfying $\psi(n-uv) = 0$. Since $|n - uv| \leq N-1 \leq f-1$, the last condition is equivalent to $n=uv$. 
By isolating the contribution from $\chi_0$ and using the assumption \eqref{eq:firsttwoassumption} for $\chi, \overline{\chi}$, we get 
\begin{align*}
|A_0| \leq \frac{1+2\varepsilon}{3}TUV,
\end{align*}
and hence 
\begin{align}
\label{eq:T3UB}
|A_0^{c}|\geq \frac{2(1-\varepsilon)}{3}TUV.
\end{align}
We note that $|v-ut| \leq V_0$ for all $(u,v,t) \in A_0^{c}$. By the definitions of $q_1, q_2$ every cubic non-residue not exceeding $V_0$ must be divisible by a prime $p$ satisfying $p=q_1$ or $q_2\leq p \leq V_0$. This implies
\begin{align}
\label{eq:T3lb1}
|A_0^{c}|\leq \sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U \\ 1\leq v \leq V \\ v-ut\equiv 0 \dmod{q_1}}}1+ \sum_{q_2\leq p \leq V_0}\sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U \\ 1\leq v \leq V \\ v-ut\equiv 0 \dmod{p}}}1,
\end{align}
and a slightly weaker bound
\begin{align}
\label{eq:T3lb2}
|A_0^{c}|\leq \sum_{q_1\leq p \leq V_0}\sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U \\ 1\leq v \leq V \\ v-ut\equiv 0 \dmod{p}}}1.
\end{align}
The bound \eqref{eq:T3lb1} implies
\begin{align*}
|A_0^{c}|&\leq \sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U}}\sum_{\substack{1\leq v \leq V  \\ v-ut\equiv 0 \dmod{q_1}}}1+ \sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U}}\sum_{q_2\leq p \leq V_0}\sum_{\substack{1\leq v \leq V  \\  v-ut\equiv 0 \dmod{p}}}1, \\
&\leq TUV\left(\frac{1}{q_1}+\sum_{q_2\leq p \leq V_0}\frac{1}{p} + \frac{2}{\log V_0} \right).
\end{align*}
Using the above and Lemma \ref{lem:dus1} for $q_2 \geq 286$, we get
\begin{align*}
|A_0^{c}|\leq TUV\left(\frac{1}{q_1}+\frac{1}{q_2}+\log\left(\frac{\log{V_0}}{\log{q_2}}\right)+\frac{1}{2\log^2{q_2}} + \frac{1}{2\log^2{V_0}} + \frac{2}{\log V_0}\right),
\end{align*}
which combined with \eqref{eq:T3UB} implies \eqref{eq:fft1}. Using \eqref{eq:T3lb2} and a similar argument with $q_1 \geq 286$ we get \eqref{eq:fft2}.
\end{proof}
\begin{cor}
\label{lem:firsttwo1}
Keep the notations and assumptions from Lemma \ref{lem:firsttwo11}. Let us define $\rho_1$ and $\rho_2$ implicitly by
\begin{align*}
q_1=V_0^{\rho_1}, \quad q_2=V_0^{\rho_2}.
\end{align*}
Then if $q_2 \geq 103$,
\begin{align*}
\log\left(\frac{1}{\rho_2}\right)\geq \frac{2(1-\varepsilon)}{3}-\frac{1}{q_1}-\frac{1}{q_2}-\frac{1}{2\log^{2} V_0} - \frac{1}{2\log^{2} q_2} - \frac{2}{\log V_0},
\end{align*}
and if $q_1 \geq 101$,
\begin{align*}
\log\left(\frac{1}{\rho_1}\right)\geq \frac{2(1-\varepsilon)}{3} - \frac{1}{q_1}-\frac{1}{2\log^{2} V_0} - \frac{1}{2\log^{2} q_1} - \frac{2}{\log V_0}.
\end{align*}
\end{cor}

\begin{proof}[Proof of Theorem \ref{thm:main1}]
By Theorem \ref{thm:1}, we have 
\begin{align}
\label{eq:SS11zz}
\left|\sum_{\substack{1\leq t \leq T \\ 1\leq u \leq U \\ 1\leq v \leq V}}\chi(v-ut)\right|&\leq TUV(E_1+E_2),
\end{align}
where we choose parameters
\begin{align*}
    r = 2, \quad \quad V=K_{1}f^{3/8}, \quad \quad U=\left\lceil \frac{\sqrt{3} V}{f^{1/4}}\right\rceil, \quad \quad T=\left\lceil \frac{f^{1/4}}{\sqrt{3}}\right\rceil,
\end{align*}
say, for some $K_1>0$ which we will fix shortly. This choice of parameters and Proposition~\ref{prop2} imply
\begin{align*}
\Delta^{4}\leq  \frac{3f^{1/2}}{UV}+\frac{f}{T^{2}UV}\leq \frac{2\sqrt{3}}{K_1^2} \leq 0.073.
\end{align*}
Thus, if we choose $K_1 = 350$ and $\theta = 0.5$, then for $2 \times 10^{20} \leq f \leq 3.8 \times  10^{49}$, we get $UV < f$ and
\begin{align*}
E_1+E_2\leq 0.1128,
\end{align*}
where the last bound was computed in Mathematica 12.0. We note that $V_0 = UT$ by its definition from Lemma \ref{lem:firsttwo11}. By Corollary \ref{lem:firsttwo1}, if $191 \leq q_1 = V_0^{\rho_1}$ and $191 \leq q_2 = V_0^{\rho_2}$, then
\begin{align*}
\rho_1 \leq \rho_2 \leq 0.6163,
\end{align*}
and thus
\begin{align*}
    q_1 \leq q_2 \leq (UT)^{0.6163} \leq ((1 + \eta) V)^{0.6163},
\end{align*}
with
\begin{equation*}
    \eta := \left( \sqrt{3} + \frac{1}{K_1 f^{1/8}} \right) \left( \frac{1}{\sqrt{3}} + \frac{1}{f^{1/4}} \right) - 1 \leq 2.5 \times  10^{-5} \quad \text{for } f \geq 2 \times  10^{20}.
\end{equation*}
The last two bound imply
\begin{align*}
    q_1 \leq q_2 \leq (K_1 (1 + 2.5 \times  10^{-5}))^{0.6163} \times  f^{0.6163 \times 3/8} \leq 37   f^{0.232},
\end{align*}
which completes the proof.
\end{proof}
Using Theorem \ref{T:nonresidues}, we are also able to give an upper bound for $m$ whenever $q_1$ and $q_2$ are both large. In particular, we are able to show:
\begin{prop}
\label{thm:main2}
Let $f\geq 2\times  10^{20}$ and suppose $q_1 > 0.02 f^{1/6}$. Then there exists a positive integer $m$ satisfying 
$$\chi(m)=\omega, \quad (m,q_1q_2)=1, \quad m\leq 7.3 f^{1/3}.$$
\end{prop}
\begin{proof}
It is sufficient to check that the conditions of Theorem \ref{T:nonresidues}  hold with $r=3$, $H = 7.3 \times  f^{1/3}$, $h = \lceil 0.12 f^{1/6} \rceil$. Indeed, we have $h \geq 49$, $u = 1$, $v = q_1 q_2$, $\ell = 2$, and
\begin{equation*}
    E_u(X) = 1 - \frac{\pi^2}{6}\left( \frac{5}{4} + \frac{1}{35 f^{1/6}} \right) \frac{1}{35 f^{1/6}} \geq 0.999.
\end{equation*}
In addition
\begin{align*}
W(f,h,3)\leq 11+\frac{1}{h} \leq 11.0207, \quad \frac{2h}{h-6}\leq 2.284,
\end{align*}
hence the left-hand side of \eqref{eq: THm6-main-condition} does not exceed $0.99$.
\end{proof}
In Proposition \ref{lem:main2m} below, we will give a variant of Vinogradov's trick which allows an estimation of $m$ similar to Proposition \ref{thm:main2}, but when $q_1$ is bounded from below by a constant. This is based on the following:
\begin{lemma}
\label{lem:large1}
Let $q$ be prime, $\chi$ mod $q$ be a character of order $3$, $\zeta$ be a primitive third root of unity and $\cS$ be a multiset. Suppose there exists some $i=0,1,2$ such that 
\begin{align*}
|\{ n\in \cS \ : \ \chi(n)=\zeta^{i}\}|\leq K.
\end{align*}
Then 
\begin{align}\label{oban}
\left|\sum_{n\in \cS}\chi(n)\right|\geq \frac{|\cS|-3K}{2}.
\end{align}
\end{lemma}
\begin{proof}
Since the bound in \eqref{oban} is decreasing with $K$ we may assume 
\begin{align}
\label{eq:large1assumption}
|\{ n\in \cS \ : \ \chi(n)=\zeta^{i}\}|=K.
\end{align}
Let 
$S=\sum_{n\in \cS}\chi(n)$,
and decompose 
\begin{align*}
S=\sum_{j=0}^{2}|\cA_j|\zeta^j,
\end{align*}
where $\cA_j=\{ n\in \cS \ : \ \chi(n)=\zeta^{j}\}$.
We have 
\begin{align*}
|S|=|\zeta^{-i}S|\geq \left|\sum_{j\neq i}|\cA_j|\zeta^{j-i}\right|-K.
\end{align*}
Hence there exists integers $N_1,N_2$ satisfying 
$N_1+N_2=|\cS|-K$,
such that 
\begin{align*}
|S|\geq \left|N_1e^{2\pi i/3}+N_2e^{-2\pi i /3} \right|-K.
\end{align*}
The result follows since 
$$\left|N_1e^{2\pi i/3}+N_2e^{-2\pi i /3} \right|\geq (N_1+N_2)\cos{\pi/3}\geq \frac{N-K}{2}.$$
\end{proof}
\begin{prop}
\label{lem:main2m}
Assume $2 \times 10^{20} \leq f \leq 2 \times 10^{49}$ and suppose
$q_1 \ge 379$.
Then there exists a positive integer $m$ satisfying 
\begin{align} \label{eq: prop23-cond-m}
\chi(m)=\omega, \quad (m,q_1 q_2)=1, \quad m \leq 14 f^{1/3}(\log{f})^{1/2}.
\end{align}
\end{prop}
\begin{proof}
For $T,U,V \in \N$, define the sets
\begin{align*}
S := & \{(t,u,v) \in \N^3 \mid \ t \leq T , \ u \leq U, v \leq V \}, \\
S^* := & \{(t,u,v) \in S \mid (v-ut,q_1q_2) = 1\},
\end{align*}
and the sums 
\begin{align*}
\Sigma_S:=\sum_{(t,u,v) \in S}\chi(v-ut) \quad \text{and} \quad
\Sigma_{S^{*}}:=\sum_{(t,u,v) \in S^*}\chi(v-ut).
\end{align*}
By the triangle inequality 
\begin{equation} \label{eq: lem23-triangle-ineq}
|\Sigma_S-\Sigma_{S^{*}}|\leq \sum_{(t,u,v) \in S \setminus S^*} 1.
\end{equation}
Since $q_1,q_2$ are prime
\begin{equation} \label{eq: lem23-delta}
\sum_{(t,u,v) \in S \setminus S^*} 1 \leq \sum_{\substack{(t,u,v) \in S \\ q_1 \mid v-ut}}1+\sum_{\substack{(t,u,v) \in S \\ q_2 \mid v-ut}}1 \leq TUV \left(\frac{1}{q_1}+\frac{1}{q_2} + \frac{2}{V}\right) =: \delta.
\end{equation}
Let us set:
\begin{align*}
r=3, \quad T=\left\lceil f^{1/6}\right\rceil, \quad U=\left\lceil \frac{V}{T}\right\rceil, \quad \theta=0.53, \quad \text{and } V=\lfloor 13 f^{1/3} \log^{1/2} f \rfloor,
\end{align*}
then, since $q_2>q_1\ge 379$ and $f \geq 2 \times 10^{20}$, we get $q_2 \geq 383$ and thus $\delta \leq 5.3 \times 10^{-3}$.

Invoking Theorem \ref{thm:1} with the parameters chosen as above, we obtain
\begin{align*}
|\Sigma_{S}|\leq TUV(E_1+E_2)<0.49 \times  TUV,
\end{align*}
where the computation was done in Mathematica 12.0. Thus by \eqref{eq: lem23-triangle-ineq},
\begin{align*}
|\Sigma_{S^{*}}|< (0.49 + \delta) TUV.
\end{align*}
Consider the multiset $\mathbf{S^*} := \{v-ut \mid (t,u,v) \in S^*\}$ and assume, for a contradiction, that $|\{m \in \mathbf{S^*} \mid \chi(m) = \omega \}| = 0$. By Lemma \ref{lem:large1}, we have
$$ \left| \Sigma_{S*} \right| = \left| \sum_{m \in \mathbf{S^*}} \chi(m) \right| \geq \frac{|\mathbf{S^*}|}{2}, \quad \text{implying} \quad  |\mathbf{S^*}|=|S^*| \leq 2 (0.49 + \delta) \, TUV. $$
On the other hand,
$$ |S^*| = |S|-|S\setminus S^*| \geq (1-\delta) TUV,$$
from where we get
\begin{align*}
1- \delta \leq 2 (0.49 + \delta) \quad \text{implying} \quad 0.02 \leq \delta,
\end{align*}
which leads to a contradiction. Thus, for any cube root of unity $\omega$, there an integer $m$, $|m| \leq \max\{TU, V\}$ coprime to $q_1 q_2$ and satisfying $\chi(m)=\omega$. Since $V \leq UT \leq 14 f^{1/3} \log^{1/2} f$ for $f \geq 2 \times 10^{20}$, $|m|$ is a positive integer satisfying \eqref{eq: prop23-cond-m}.
%If $m$ is positive, then the lemma is proved. If $m$ is negative, then $\chi(-m) = \chi(m)$ since $\chi$ is cubic. Thus, $-m$ is the required integer.
\end{proof}

\section{Proof of Theorem \ref{T:2}}
\label{sec:II}
We recall that we aim at showing that, for any $f\geq 2 \times 10^{20}$ and $q_1 \neq 2$, there exists a positive integer $m$ such that $(m,q_1q_2)=1$, and $\chi(m)=\omega$, and
\begin{align}
\label{eq:cond2}
3q_1 q_2 m<f,
\end{align}
\begin{align}
\label{eq:cond3}
10 q_1^2 q_2<f.
\end{align}

Furthermore, we may assume for contradiction that $K$ is norm-Euclidean. By Proposition \ref{fixedprop14}, we may assume $q_1\geq 379$ and $q_2 \geq 383$. Let $h = \lceil 0.02 f^{1/6} \rceil$, then we split the proof into three cases.

\noindent
{\bf Case I:}  $q_1 < q_2 < h$.
This case is covered by Proposition \ref{fixedprop14} since $h< 1.3 f^{1/6}$.

\noindent
{\bf Case II:} $q_1 < h \leq q_2$.
By Theorem \ref{thm:main1} we have 
$q_2 \leq 37 f^{0.232}$.
By Lemma \ref{lem:main2m},
$$m\leq 14 f^{1/3}\log^{1/2}{f}.$$
The bounds on $q_2$, $m$ above and $q_1 < h$ imply \eqref{eq:cond2} and \eqref{eq:cond3}.

\noindent
{\bf Case III:} $h \leq q_1 < q_2$.
By Lemma \ref{thm:main2} we have
$m\leq 7.3 f^{1/3}$,
and by Theorem \ref{thm:main1},
\begin{align*}
q_1< q_2 \leq 37 f^{0.232},
\end{align*}
implying \eqref{eq:cond2} and \eqref{eq:cond3}. This completes the proof of the theorem.

\section{Numerical verification}
In this section we describe an algorithm to enumerate primes $f$
with no small cubic non-residues modulo $f$, and its application
to complete the proof of Theorem~\ref{T:big}.
The full source code is available on request.

The algorithm is similar to methods of enumerating pseudosquares
(see \cite{Sorenson} and the references therein), the main difference
being that our sieve region is an ellipse rather than a line.
The enumeration could be improved using Bernstein's ``doubly-focused
enumeration'' strategy \cite{Bernstein} or \texttt{AVX} intrinsics for
better parallelism; however, it turns out that the post-processing steps
dominate the running time in our application, so we opted for a more
straightforward implementation.

We begin with some basic notation and lemmas.
Let $\omega=\frac{-1+\sqrt{-3}}{2}$. For $\alpha,\pi\in\Z[\omega]$
with $\pi$ prime, recall the cubic residue symbol
$\left(\frac{\alpha}{\pi}\right)_3\in\bigl\{0,1,\omega,\omega^{-1}\bigr\}$
defined by
\begin{equation*}
\left(\frac{\alpha}{\pi}\right)_3
\equiv\alpha^{\frac{\pi\overline{\pi}-1}{3}}
\pmod\pi.
\end{equation*}
\begin{lemma}\label{lem:2and3}
Let $p\equiv1\pmod3$ be a prime such that $2$ and $3$ are cubic residues
modulo $p$. Then $p$ can be written uniquely in the form $x^2+243y^2$,
where $x,y\in\Z$, $x\equiv 3y-1\pmod6$, and $y>0$.
\end{lemma}
\begin{proof}
By \cite[Prop.~9.6.2]{IR}, $2$ is a cubic residue modulo $p$ if and only
if $p$ is of the form $C^2+27D^2$ for $C,D\in\Z$, and this representation
is unique up to sign. We choose the signs such that $C\equiv-1\pmod3$ and
$D>0$, and write $\pi=C+3D\sqrt{-3}$, which is a prime of $\Z[\omega]$
satisfying $\pi\overline{\pi}=p$. By \cite[Ch.~9, Thm.~$1'$]{IR}, $3$
is a cubic residue modulo $p$ if and only if
\begin{align*}
1&=\left(\frac{3}{\pi}\right)_3=\left(\frac{-\omega^2(1-\omega)^2}{\pi}\right)_3
=\omega^{\frac23(p-1)}\omega^{\frac43(C+3D+1)}\\
&=\omega^{\frac23(C^2+2C+1+6D+27D^2)}=\omega^{\frac23(C+1)^2}\omega^{4D+18D^2}
=\omega^D.
\end{align*}
Hence $3\mid D$, and writing $C=x$, $D=3y$, we have $p=x^2+243y^2$, uniquely.
Finally note that since $p$ is odd, $x$ and $y$ must have opposite parity,
and hence $x\equiv3y-1\pmod6$.
\end{proof}

\begin{lemma}\label{lem:q}
Let $p=x^2+243y^2=\pi\overline{\pi}$ as in Lemma~\ref{lem:2and3},
and let $q>3$ be a prime number.
\begin{enumerate}
\item[(i)]
If $q\equiv1\pmod3$ then, as elements of $\F_q$,
\begin{equation*}
\bigl(p(x-9ys)\bigr)^{\frac{q-1}{3}}=
\begin{cases}
0&\text{if }\left(\frac{q}{\pi}\right)_3=0,\\
1&\text{if }\left(\frac{q}{\pi}\right)_3=1,\\
\frac{-1+s}{2}&\text{if }\left(\frac{q}{\pi}\right)_3=\omega,\\
\frac{-1-s}{2}&\text{if }\left(\frac{q}{\pi}\right)_3=\omega^{-1},
\end{cases}
\end{equation*}
where $s\in\F_q$ is any square root of $-3$.
\item[(ii)]
If $q\equiv2\pmod3$ then
$\bigl(x+9y\sqrt{-3}\bigr)^{\frac{q^2-1}{3}}=\left(\frac{q}{\pi}\right)_3$
in $\F_q\bigl[\sqrt{-3}\bigr]$.
\end{enumerate}
In particular, $q$ is a cubic residue modulo $p$ if and only if
$\bigl(p(x-9ys)\bigr)^{\frac{q-1}{3}}=1$ in case (i),
and $\bigl(x+9y\sqrt{-3}\bigr)^{\frac{q^2-1}{3}}=1$ in case (ii).
\end{lemma}
\begin{proof}
Suppose $q\equiv1\pmod3$, and
write $q=\Pi\overline{\Pi}$, where $\Pi\in\Z[\omega]$
with $\Pi\equiv2\pmod{3}$. Then by cubic reciprocity \cite[Ch.~9, Thm.~1]{IR},
\begin{equation*}
\left(\frac{q}{\pi}\right)_3
=\left(\frac{\Pi}{\pi}\right)_3
\left(\frac{\overline{\Pi}}{\pi}\right)_3
=\left(\frac{\pi}{\Pi}\right)_3
\left(\frac{\pi}{\overline{\Pi}}\right)_3.
\end{equation*}
Applying \cite[Prop.~9.3.4]{IR}, this becomes
$\left(\frac{\pi\overline{\pi}^2}{\Pi}\right)_3
=\left(\frac{p\overline{\pi}}{\Pi}\right)_3$. Fixing a choice of $s\in\Z$
with $s^2\equiv-3\pmod{q}$, we may swap $\Pi$ and $\overline{\Pi}$
if necessary to assume that $\sqrt{-3}\equiv s\pmod{\Pi}$. Hence we
have $\overline{\pi}=x-9y\sqrt{-3}\equiv x-9ys\pmod\Pi$, and the claim
follows from the definition of the cubic residue symbol.

Suppose now that $q\equiv2\pmod3$. Then by cubic reciprocity we have
$\left(\frac{q}{\pi}\right)_3=\left(\frac{\pi}{q}\right)_3$, and again by the
definition of the symbol this has image
$\bigl(x+9y\sqrt{-3}\bigr)^{\frac{q^2-1}{3}}$ in
$\F_q\bigl[\sqrt{-3}\bigr]$.
\end{proof}

Given a range $(B_1,B_2)$, we can
use these lemmas to quickly enumerate candidate primes $f\in(B_1,B_2)$
with no small cubic nonresidues mod $f$, as follows.
Using Lemma~\ref{lem:q} we precompute the values of
$\left(\frac{q}{\pi}\right)_3$, where $\pi=x+9y\sqrt{-3}$,
for every prime $q\in(3,541]$ and all $(x,y)\in\{0,\ldots,q-1\}^2$.
We then pick out the pairs for which the symbol is $1$ for all small $q$,
and use the Chinese remainder theorem to combine them into pairs
$(x,y)\in(\Z/M_i\Z)^2$ for two moduli $M_1,M_2$, where $M=M_1M_2$
is the product of the first several primes.
More specifically, for $(B_1,B_2)=\bigl(2\times10^{14},8.47\times10^{15}\bigr)$
we choose $M_1=2\cdot3\cdot5$, $M_2=7$, and for
$(B_1,B_2)=\bigl(8.47\times10^{15},2\times10^{20}\bigr)$ we choose
$M_1=2\cdot3\cdot5\cdot7\cdot11\cdot13\cdot17$,
$M_2=19\cdot23\cdot29$.

For a fixed $y\in\Z/M\Z$,
the admissible residues $x\in\Z/M\Z$ are then quickly computable via
\begin{equation*}
x=\bigl(x_1\overline{M}_2\bmod M_1\bigr)M_2 + \bigl(x_2\overline{M}_1\bmod M_2\bigr)M_1,
\end{equation*}
where $\overline{M}_i$ is a multiplicative inverse of $M_i\pmod{M_{3-i}}$,
and $x_i$ ranges over elements of $\{0,\ldots,M_i-1\}$ such that
$(x_i,y)\in(\Z/M_i\Z)^2$ is admissible. We precompute lists of the values
\begin{equation*}
x_i'=\bigl(x_i\overline{M}_{3-i}\bmod M_i\bigr)M_{3-i},
\end{equation*}
so this enumeration is very fast. Finally, we run through all
$x\equiv x_1'+x_2'\pmod{M}$ with $|x|\le\sqrt{B_2-243y^2}$.
The moduli are chosen so that for most $y$ there are
a few values of $x$ in this range for each $(x_1',x_2')$ pair.

We process $f=x^2+243y^2$ for a fixed pair $(x,y)\in\Z^2$ as follows:
\begin{enumerate}
\item We search for a cubic nonresidue $q_1\le317$, and if successful
we reject $f$ if it exceeds the corresponding threshold in
Table~\ref{tab:q1thresh} or fails a primality test.
\item If $q_1>317$, we test to see if $(x,y)>1$ or $f$ is a cube or fails a primality test,
and reject $f$ if so; otherwise we continue the search for $q_1$ up to $541$.
\item If $q_1\le541$ then we search for prime cubic nonresidues $q_2,m$
such that $q_1<q_2<m\le 541$ and $q_2m$ is a cubic residue, and apply
Criterion~\ref{criterion: expl-non-Eucl}.
\item Any candidates that remain at this point
(either because we could not find suitable $q_1,q_2,m\le541$ or
the criterion was not met) are printed.
\end{enumerate}
The thresholds in Table \ref{tab:q1thresh} are calculated in order to avoid computationally costly post-processing by immediately rejecting all sufficiently small $q_1$. The thresholds $(q_1,f_0)$ are determined for increasing prime values $q_1$ by varying $\lambda \in(0.1,2)$ such that $h = \lceil \lambda f^{1/6}\rceil$ and calculating the smallest value $f = f_0$ for which Theorem~\ref{T:nonresidues} holds. The process of checking the validity of each threshold is outlined in Remark~\ref{R:q1cutoffs}. Note that $f_0(q_1)$ could feasibly be lowered by choosing a finer partition of $(0.1,2)$ for $\lambda$, but this was unnecessary for our application. 

We ran this algorithm on a desktop PC with 6 cores (Intel
Core i7-8700).  The running time was approximately 6 hours for
$(B_1,B_2)=\bigl(2\times10^{14},8.47\times10^{15}\bigr)$, and 134 hours
for $(B_1,B_2)=\bigl(8.47\times10^{15},2\times10^{20}\bigr)$. Neither run
printed any exceptional primes, and this completes the proof that there
are no exceptions in $\bigl(2\times10^{14},2\times10^{20}\bigr)$. Combining Theorem~\ref{T:2} with our computational result yields Theorem~\ref{T:big}.

