\setcounter{AlgoLine}{0}

\begin{minipage}{\linewidth} 
\begin{algorithm}[H]
\caption{HMAS Implementation}\label{alg:hmas2e}

\KwData{Agent set $\mathcal{A}$, environment $\texttt{env}$, time limit $T_{\text{max}}$, task $\texttt{task}$}


$\texttt{Leader} \gets \mathcal{A}[0]$\;

$\texttt{GlobalState} \gets \{\}$\;

$\texttt{StepHistory} \gets \{\}$\;

$\texttt{state} \gets \texttt{env}.\texttt{reset}()$\;

\For{$t \gets 1$ \KwTo $T_{\text{max}}$}{
  \tcc{Parsing Observations and Generating Perceptions}
  \ForEach{$a \in \mathcal{A}$}{
