    $p_a \gets \texttt{LLM\_GeneratePerception}(a, \,o_a)$\;

    append $p_a$ to $\texttt{GlobalState}[a]$\;
  }
\tcc{Iterating Plans}    

    $\texttt{valid} \gets\texttt{False}$

    \While{$\texttt{valid} = \texttt{False}$}{

    $\texttt{valid} \gets\texttt{True}$

    $\texttt{plan} \gets \texttt{LLM\_GeneratePlan}_{leader}(\texttt{task}, \, \texttt{GlobalState}, \, \texttt{StepHistory}, \, \texttt{Review})$\;

    \tcc{Reviewing Plan}

    $\texttt{Review} = \{\}$


    \ForEach{$a \in \mathcal{A}$}{


      $\texttt{feedback}_a \gets \texttt{LLM\_ReviewPlan}_a(\texttt{plan}, \, \texttt{GlobalState}, \, \texttt{Step History})$\;

      \If{$\texttt{feedback}_a$ is REJECT}{
        append $\texttt{feedback}_a$ to $\texttt{Review}$\;

        $\texttt{valid} \gets \texttt{False}$\;

      }
    }

    }
    \ForEach{$\texttt{task}_a \in \texttt{plan}$}{
    $\texttt{action}_a \gets \texttt{LLM\_TranslateAction}(\texttt{task}_a)$
    }

    \tcc{Executing Actions}  

  $\texttt{actions} \gets \{\}$\;

  \ForEach{$a \in \mathcal{A}$}{


    $e_a \gets \texttt{ExecuteAction}(\texttt{action}_a)$\;

    \If{$\textbf{action is complete}$}{ 
        append $\texttt{action}_a$ to $\mathcal{H}_a$\;

        $\texttt{action}_a=\texttt{None}$\;
    }
    $E[a] \gets e_a$\;
  }

  append $(\texttt{GlobalState}, \texttt{actions})$ to $\texttt{StepHistory}$\;

  $(\texttt{state}, \texttt{score}) \gets \texttt{env}.\texttt{step}(\texttt{actions})$\;

  \If{$\texttt{score} \geq \texttt{MaxScore}$}{
    \textbf{break}\;
  }
}
\end{algorithm}
\end{minipage}

In our HMAS-2 Implementation, a $\textbf{leader agent}$ initially is chosen shown in line 1. Then, for each timestep, each agent parses their observations($o_a$) from the environment states, and then generates a text perception ($p_a$) given those observations through the \perception module (\ref{perception_prompt}). This perception($p_a$) is then appended to the $\texttt{GlobalState}$.

Then, the $\textbf{leader agent}$ generates a plan for the team through $\texttt{LLM\_GeneratePlan}_{leader}$ (\ref{HMAS-2_Central_Planner}) given the team's task, the Global State,  the Step History, and reviews from other agents in line 13. This will provide the leader agent with all agents' current perceptions and past perceptions and actions.

Then each agent will review the plan and provide feedback through $\texttt{LLM\_ReviewPlan}_{a}$ (\ref{HMAS-2_Feedback}) in line 16. If the feedback is to reject the plan, the feedback will be appended to $\texttt{Review}$ and $\texttt{valid}$ will be set to $\texttt{False}$. This will cause lines 12-19 to be repeated, reiterating the plan.

When the plan does not have any rejection, the finalized plan will be parsed into tasks for each agent and translated into a standardized action format through $\texttt{LLM\_TranslateAction}_a$ (\ref{translator_prompt}) in line 20. This action ($\texttt{action}_a$) will be each agent's active action.

Now, since all agents have an active action, each agent will generate an executable vector ($e_a$) through our \execution Module in line 23. If the current action ($\texttt{action}_a$) is complete or single-step, it will then be set to $\texttt{None}$ and appended to the agent's action history.

Lastly, all executable tensors will be combined and executed within the Wildfire Environment in line 28. If the max score has been reached, the algorithm ends.
