    \includegraphics[width=0.99\linewidth]{plots/bulge_sample_mdf_for_different_ecc_zmax_5kpc.png}
    \caption{MDFs across the $Z_{\mathrm{max}}$--eccentricity plane (see Fig. \ref{fig:ecc_zmax}) for the Bulge sample (full - orange, RVS - black , RPM - green).}
