\begin{equation}
    \begin{aligned}
    6_F \otimes \bar{6}_F (S) 
    & \left\{\begin{array}{l}
     S_6 = u_a^T C d_b [\bar{d}_a \gamma_5 C \bar{s}^T_b +
%     \bar{d}_b \gamma_5 C \bar{s}^T_a
     (a \leftrightarrow b)
