\begin{widetext}
    \begin{equation}
    \begin{aligned}
  S^{i j} (x) & =  \frac{\text{i} \Gamma \left( \frac{d}{2} \right)
  \slashed{x}}{2 \pi^{d / 2} (- x^2)^{d / 2}} \delta^{i j} + \frac{m \Gamma \left(
  \frac{d}{2} - 1 \right)}{4 \pi^{d / 2} (- x^2)^{d / 2 - 1}} \delta^{i j} -
  \frac{\delta^{i j}}{12} \langle \bar{\psi} \psi \rangle +
  \frac{\text{i} m \delta^{i j}}{12 d} \langle \bar{\psi} \psi \rangle
