%
where $m$ is the light quark mass, $i, j=1, 2, 3$ are color indices, $T^a (a=1,...,8)$ is the Gell-Mann matrix. We also use the following abbreviations
\begin{widetext}
\begin{equation}
    \begin{aligned}
  \gamma^{\mu \nu \rho} & \coloneqq  \gamma^{\mu} \gamma^{\nu} \gamma^{\rho}, \quad
  g^{\{ \mu \rho } x^{ \sigma \}}  \coloneqq  g^{\mu \rho}
  x^{\sigma} + g^{\mu \sigma} x^{\rho} + g^{\rho \sigma} x^{\mu}, \quad
  g^{\{ \mu \rho } \gamma^{ \sigma \}}  \coloneqq  g^{\mu \rho}
  \gamma^{\sigma} + g^{\mu \sigma} \gamma^{\rho} + g^{\rho \sigma}
  \gamma^{\mu},  \\
  x^{\{ \mu } & x^{\rho} \gamma^{ \sigma \}}  \coloneqq  x^{\mu}
  x^{\rho} \gamma^{\sigma} + x^{\mu} x^{\sigma} \gamma^{\rho} + x^{\rho}
  x^{\sigma} \gamma^{\mu}, \quad
  G_{\mu \nu ; \rho}^a  \coloneqq \tilde{D}_\rho^{ab} G^b_{\mu \nu}, \quad
  G_{\mu \nu ; \rho \sigma}^a  \coloneqq \tilde{D}_\sigma^{a b} \tilde{D}_\rho^{b c}  G^{c}_{\mu \nu},
    \end{aligned}
\end{equation}
\end{widetext}
in which $G_{\mu \nu}$ is the gluon filed strength, $\tilde{D}_\mu^{a b}=\delta^{a b}\partial_\mu-g f^{a b c} A^c_\mu$ is the covariant derivative operator in the adjoint representation and $A^c_\mu$ is the external gauge field. The origin of the full quark propagator in Eq.~\eqref{eq:chuanboz} includes both the background field and quantum field. In our calculation, we keep track of terms in the fifth order of the background quark field expansion $\frac{x^{\mu}x^{\nu} x^{\rho} x^{\sigma}}{4!} \langle \psi^i D_{\mu} D_{\nu} D_{\rho}
D_{\sigma} \bar{\psi}^j \rangle$. 
For the part of quantum fields, we include terms up to dimension-6 to fully compute the result of $\langle g^3 f G^3 \rangle$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%
In QCDSR studies for multiquark systems, the contribution of tri-gluon condensate $\langle
g^3 f G^3 \rangle$ is usually neglected due to the computational complexity and infrared divergence (IR) in fully calculations. 
%An exception is Ref.\cite{Li:2024rrs}, but they did not %summarize the cancellation of the IR divergence of $%\langle g^3 f G^3\rangle$ nor provide a detailed %analysis of its contribution. 
However, such contributions may be significant in fully  calculations at leading order (LO) by considering $\langle (D G) (D G)
\rangle$ and $\langle G (D D G) \rangle$ terms as the following~\cite{Zhong:2014jla,Chen:2013zia}
\begin{equation}
    \begin{aligned}
   &\langle  G^a_{\mu \nu ;\rho}  G^b_{\alpha \beta ;  \sigma} \rangle  = 
   \delta^{a b} 2Z
  g_{\rho \sigma} (g_{\mu \alpha} g_{\beta \nu} - g_{\alpha \nu} g_{\beta
  \mu}) \\
  & + \delta^{a b} Z  [g_{\nu \sigma} g_{\mu \alpha} g_{\beta \rho} + g_{\mu \sigma}
   g_{\nu \beta} g_{\alpha \rho} - (\mu \leftrightarrow \nu)]  
   \\
  & + \delta^{a b} Y [(g_{\nu \rho} g_{\mu \alpha} g_{\beta \sigma} + g_{\mu
  \rho} g_{\nu \beta} g_{\alpha \sigma}) - (\mu \leftrightarrow \nu)],
  \label{eq:njl}\\
  Z & =  - \frac{D (D - 2) g^2 \langle \bar{\psi} \psi \rangle^2 + 9 (D
  - 1) \langle g f G^3 \rangle}{72 (D - 2) (D - 1) D (D + 2)},\\
  Y & =  \frac{- D (D - 2) g^2 \langle \bar{\psi} \psi \rangle^2 + 27
  \langle g f G^3 \rangle}{72 (D - 2) (D - 1) D (D + 2)},
    \end{aligned}
\end{equation}
\begin{equation}
    \begin{aligned}
\langle G^a_{\mu \nu ; \rho}  G^b_{\alpha \beta ; \sigma} \rangle =  -
  \langle  G^a_{\mu \nu ; \rho \sigma} G^b_{\alpha \beta} \rangle = - \langle
  G^a_{\mu \nu} G^b_{\alpha \beta ; \sigma \rho} \rangle,
  \end{aligned} \label{eq:njl11}
\end{equation}
in which we adopt the $D$-dimensional condensates to  distinguish the dimension $d$ of the full quark propagator in Eq.~\eqref{eq:chuanboz}. $D$ and $d$ are identical, but such symbols are useful for addressing IR divergences, as shown in Appendix~\ref{appendix: IR for G}. In Ref.~\cite{Li:2024rrs}, the authors also address the IR divergence of $\langle g^3 f G^3\rangle$, they just did not summarize the corresponding cancellation tricks. One should note that the IR safety for the tri-gluon condensate $\langle g^3 f G^3 \rangle$ can not be guaranteed for calculating the $\langle (D G) (D G)
\rangle$ terms by using propagators up to dimension-6, as adopted in Ref.~\cite{Zhong:2014jla}.
