\section{IR safety for $\langle g^3 f G^3 \rangle$}\label{appendix: IR for G}
In this calculation, the IR divergences can appear in the Feynman diagrams Figs.~\ref{fig:Feynman4d}-\ref{fig:Feynman4f}, in which the involved condensates $\langle (GG)G\rangle$, $\langle  G(DDG)\rangle$ and $\langle  (DG) (DG)\rangle$ come from any two propagators. 
 This can be expressed as
\begin{equation}
    \begin{aligned}
        (\ldots) \ast S^{ij} \ast (\ldots) \ast S^{mn} \ast (\ldots),
    \end{aligned}
\end{equation}
where the ellipsis $(...)$ represents irrelevant part to divergences. For convenience, we define the following propagators
\begin{equation}
  \begin{aligned}
      S_2^{i j}& (x) 
      \coloneqq  X^{\mu\nu}(x) gG_{\mu \nu}^a T^a_{i j} 
       = \frac{\Gamma \left( \frac{d}{2} - 1 \right) \gamma^{\mu}
     \slashed{x} \gamma^{\nu}}{16 \pi^{d / 2} (- x^2)^{d / 2 - 1}} g G_{\mu \nu}^a
     T^a_{i j}, 
     \end{aligned}
\end{equation}
\begin{equation}
  \begin{aligned}
     S_{4b}^{i j}& (x)
     \coloneqq Z^{\mu\nu\rho\sigma}(x) g G_{\mu \nu ; \rho \sigma}^a T^a_{i j} \\
      = & \frac{- \Gamma \left( \frac{d}{2} - 2 \right) \left(
     {2 g^{\{ \mu \rho} x^{ \sigma \}}}
      + g^{\{ \mu \rho} \gamma^{ \sigma \}} \slashed{x} \right)
      \gamma^{\nu}}{2^8 \times 3 \pi^{d / 2} (- x^2)^{d / 2 - 2}} g G_{\mu \nu ;
      \rho \sigma}^a T^a_{i j} ,
     \end{aligned}
\end{equation}
\begin{equation}
  \begin{aligned}
      S^{i j}_{4a}& (x) 
       \coloneqq   g^2 G^a_{\mu\nu}G^b_{\rho\sigma}(T^aT^b)_{ij} Y^{\mu\nu\rho\sigma}(x)\\
      = &  g^2 G^a_{\mu \nu} G^b_{\rho \sigma} (T^a T^b)_{i j}
   \Bigg[ \frac{- \text{i} \Gamma \left( \frac{d}{2} - 2 \right) g^{\nu \sigma}
      \gamma^{\mu} \slashed{x} \gamma^{\rho}}{192 \pi^{d / 2} (- x^2)^{d / 2 - 2}}\\
      + & \frac{\text{i} \Gamma \left( \frac{d}{2} - 2 \right) \left( - 6
     g^{\nu \sigma} \slashed{x} \gamma^{\mu \rho} - 4 x^{\sigma} \gamma^{\mu \nu
     \rho}  \right)}{2^8 \times 3 \pi^{d / 2} (- x^2)^{d / 2 - 2}}   \\
     +   & \frac{\text{i} \Gamma \left( \frac{d}{2} - 2 \right) \left(  6 x^{\mu} \gamma^{\nu \rho \sigma} - 4 x^{\nu} \gamma^{\mu \sigma
     \rho} {+ 3 \gamma^{\mu} \slashed{x} \gamma^{\nu \rho
     \sigma}} \right)}{2^8 \times 3 \pi^{d / 2} (- x^2)^{d / 2 - 2}} \Bigg] ,
    \end{aligned}
\end{equation}
in which the subscript 2/4 represents the dimension of $S^{ij}(x)$. It is very clear that $S^{ij}_{4a}(x)$ and $S^{ij}_{4b}(x)$ are divergent with the factor $\Gamma(d/2-2)$ when $d=4$, which will appear in the Feynman diagrams Fig.~\ref{fig:Feynman4d} and Fig.~\ref{fig:Feynman4f} respectively. The sum of these two diagrams is shown in Fig.~\ref{fig:IR1} with the expression 
\begin{widetext}
\begin{equation}
    \begin{aligned} 
    (\ldots) &\ast S^{i j}_{4a}(x) \ast (\ldots) S^{m n}_2 \ast (\ldots) + (\ldots)
   \ast S^{i j}_{4b}(x) \ast (\ldots) S^{m n}_2 \ast (\ldots) =     \label{A.3}  
    \end{aligned}
\end{equation}
\begin{equation*}
    (\ldots)\ast [(T^b T^c)_{i j} g^2 G^b_{\mu_1 \nu_1} G^c_{\rho_1 \sigma_1} Y^{\mu_1 \nu_1 \rho_1 \sigma_1}(x) +T^a_{i j} gG^a_{\mu_2 \nu_2 ; \rho_2 \sigma_2} Z^{\mu_2 \nu_2 \rho_2 \sigma_2}(x) ] \ast (\ldots) \ast T^d_{m n} gG^d_{\mu \nu} X^{\mu\nu} \ast (\ldots).
\end{equation*}
\end{widetext}
We define following structures for the dimension-6 condensates
\begin{equation}
    \begin{aligned} 
   \langle G^a_{\mu \nu} G^b_{\alpha \beta} G^c_{\rho \sigma} \rangle & \coloneqq   f^{abc} W_{\mu\nu;\alpha\beta;\rho\sigma},\\
  \langle G^a_{\mu \nu ; \rho \sigma} G^b_{\alpha
  \beta} \rangle & \coloneqq \delta^{ab} U_{\mu\nu\alpha\beta;\rho\sigma} ,
    \end{aligned}
\end{equation}
where 
\begin{equation}
    \begin{aligned}
  &g^3  W_{\mu\nu;\alpha\beta;\rho\sigma}  = 
   \frac{-\langle g^3 f G^3\rangle}{24(D-2)(D-1)D} \\&[g_{\beta\nu}(g_{\alpha\rho}g_{\mu\sigma}-g_{\alpha\sigma}g_{\mu\rho})+ g_{\alpha\nu}(g_{\beta\sigma}g_{\mu\rho}-g_{\beta\rho}g_{\mu\sigma}) \\
  & + g_{\beta\mu}(g_{\alpha\sigma}g_{\nu\rho}-g_{\alpha\rho}g_{\nu\sigma}) +g_{\alpha\mu}(g_{\beta\rho}g_{\nu\sigma}-g_{\beta\sigma}g_{\nu\rho})].
    \end{aligned}
\end{equation}
The specific expression of $U_{\mu\nu\alpha\beta;\rho\sigma}$ is given by Eqs.~\eqref{eq:njl} and ~\eqref{eq:njl11}. Then we have
\begin{equation}
    \begin{aligned} 
   &(T^b T^c)_{i j} T^d_{m n} \langle G^b_{\mu_1 \nu_1} G^c_{\rho_1 \sigma_1}
  G^d_{\mu \nu} \rangle \\ =&  (T^b T^c)_{i j} T^d_{m n} f^{b c d} W_{\mu_1 \nu_1;\rho_1\sigma_1;\mu\nu},\label{A.6}
    \end{aligned}
\end{equation}
\begin{equation}
    \begin{aligned} 
   &T^a_{i j} T^d_{m n} \langle G^a_{\mu_2 \nu_2 ; \rho_2 \sigma_2} G^d_{\mu
  \nu} \rangle    =T^a_{i j} T^a_{m n} U_{\mu_2\nu_2\rho_2\sigma_2;\mu\nu}, \label{A.7}
    \end{aligned}
\end{equation}
and 
\begin{equation}
    \begin{aligned} 
 (T^b T^c)_{i j} T^d_{m n} f^{b c d}  =  \frac{3 \text{i}}{2}
   T^d_{m n} T^d_{i j}, \label{A.8}
   \end{aligned}
\end{equation}
where $f^{bce}$ and $d^{bce}$ are antisymmetric structure and symmetric constants of SU(3) group, respectively. Substituting Eqs.~\eqref{A.6}-\eqref{A.8} into Eq.~\eqref{A.3}
\begin{equation}
    \begin{aligned} 
    (...)\ast T^d_{m n}& T^d_{i j}  [ \frac{3 \text{i}}{2}  W_{\mu_1 \nu_1;\rho_1\sigma_1;\mu\nu}  g^3 Y^{\mu_1 \nu_1 \rho_1\sigma_1}(x) \\ +& U_{\mu_2\nu_2\rho_2\sigma_2;\mu\nu}  g^2 Z^{\mu_2   \nu_2\rho_2\sigma_2}(x) ] \ast (\dots) \ast X^{\mu\nu},
    \end{aligned}
\end{equation}
in which the result in the square brackets can be calculated as 
\begin{equation}
    \begin{aligned} 
 &\frac{\langle g^3 f G^3 \rangle \Gamma \left( \frac{d}{2} - 2 \right) (d -
   4) \left( \gamma_{\mu} \slashed{x} \gamma_{\nu} - \gamma_{\nu} \slashed{x}
   \gamma_{\mu} \right)}{3072 (d - 2) (d - 1) d \pi^{d / 2} (- x^2)^{d / 2 -
   2}} \\  =  & \frac{\langle g^3 f G^3 \rangle \Gamma \left( \frac{d}{2} - 1 \right)
   \left( \gamma_{\mu} \slashed{x} \gamma_{\nu} - \gamma_{\nu} \slashed{x}
   \gamma_{\mu} \right)}{1536 (d - 2) (d - 1) d \pi^{d / 2} (- x^2)^{d / 2 -
   2}} . 
   \end{aligned}
\end{equation}
It is fantastic that this result is finite, showing that the divergences in Fig.~\ref{fig:Feynman4d} and Fig.~\ref{fig:Feynman4f} exactly cancel out for each other. 

To ensure such a cancellation for the calculation of Fig.~\ref{fig:Feynman4e}, it is 
important to use the $d$-dimensional propagator and $D$-dimensional condensates, but not any one in the 4-dimensional. The propagator containing $G^a_{\mu\nu;\rho}$ can be written as
\begin{equation}
    \begin{aligned} 
    S_3^{ij} (x)& = S_{3a}^{ij} (x) + S_{3b}^{ij} (x) \coloneqq J^{\mu\nu\rho}_0  gG_{\mu \nu ; \rho}^a T^a_{i j},
   \end{aligned}
\end{equation}
\begin{equation}
    \begin{aligned} 
 S_{3a}^{ij} (x)& \coloneqq J^{\mu\nu\rho}_1  gG_{\mu \nu ; \rho}^a T^a_{i j}  \\ &= \frac{\Gamma \left( \frac{d}{2} - 1 \right)g G_{\mu
   \nu ; \rho}^a T^a_{i j}}{48
   \pi^{d / 2} (- x^2)^{d / 2 - 1}} \left( x_{\mu} \gamma_{\rho} \slashed{x}
   \gamma_{\nu} + x_{\rho} \gamma_{\mu} \slashed{x} \gamma_{\nu} \right)  , 
   \end{aligned}
\end{equation}
\begin{equation}
    \begin{aligned} 
 S_{3b}^{ij}(x)  & \coloneqq J^{\mu\nu\rho}_2  gG_{\mu \nu ; \rho}^a T^a_{i j} (x)  \\ & = \frac{\Gamma \left( \frac{d}{2} - 2 \right)g G_{\mu \nu ;
   \rho}^a T^a_{i j}}{96
   \pi^{d / 2} (- x^2)^{d / 2 - 2}} {(\gamma_{\mu \rho
   \nu} + \gamma_{\rho \mu \nu} - 4 g_{\mu \rho} \gamma_{\nu})} ,
   \end{aligned}
\end{equation}
where $J^{\mu\nu\rho}_0, J^{\mu\nu\rho}_1, J^{\mu\nu\rho}_2$ are corresponding tensor structures and $J^{\mu\nu\rho}_0=J^{\mu\nu\rho}_1+J^{\mu\nu\rho}_2$. 
It is clear that only $S_{3b}^{ij}$ is divergent while $S_{3a}^{ij}$ remains finite. The most divergent part of Fig.~\ref{fig:Feynman4e} can be written as
\begin{widetext}
    \begin{equation}
  \begin{aligned}  
     (\ldots) \ast S^{i j}_{3b} \ast (\ldots) S^{m n}_{3b} \ast (\ldots) & = (\ldots)
   \ast J_2^{\mu_1 \nu_1 \rho_1} T^a_{ij} g G_{\mu_1 \nu_1 ; \rho_1}^a \ast
   (\ldots) \ast J_2^{\mu \nu \rho} T^b_{m n} gG_{\mu \nu ; \rho}^b \ast (\ldots)\\ 
  & = (\ldots) \ast J_2^{\mu_1 \nu_1 \rho_1} T^a_{i j} T^b_{m n} g^2\langle G_{\mu_1 \nu_1 ; \rho_1}^a G_{\mu \nu ; \rho}^b \rangle \ast (\ldots) \ast J_2^{\mu \nu \rho} \ast (\ldots) ,
   \end{aligned}
\end{equation}
\end{widetext}
in which both $J_2^{\mu_1 \nu_1 \rho_1}$ and $J_2^{\mu \nu \rho}$ contain the divergent factor $\Gamma(\frac{d}{2}-2)$. However, such a divergence is trivial since the other part in the calculation is zero
\begin{equation}
    \begin{aligned} 
 &J_2^{\mu_1 \nu_1 \rho_1} T^a_{i j} T^b_{m n} g^2 \langle G_{\mu_1 \nu_1 ;
   \rho_1}^a G_{\mu \nu ; \rho}^b \rangle \\ =& T^a_{i j} T^b_{m n} \frac{\langle g^3 f G^3 \rangle
   \Gamma \left( \frac{d}{2} - 2 \right) (D - d) (g_{\rho \mu} \gamma_{\nu} -
   g_{\rho \nu} \gamma_{\mu})}{128 (D - 1) D (D^2 - 4) \pi^{d / 2} (- x^2)^{d
   / 2 - 2}}  \\ =& 0, 
   \end{aligned}
\end{equation}
where we use $D=d$ in the last step.
