\section{Main Result: A Novel Trace Inequality} \label{sec:main}

\begin{theo} \label{theo:sharp_one-shot}Let $A$ and $B$ be positive semi-definite trace-class operators on a infinite-dimensional separable Hilbert space. Suppose the support of $A$ is contained in support of $B$ and  $\Tr\left[ A \left( \log(A+B) - \log B \right) \right] < \infty$. Then
\begin{align}
	\Tr\left[ A \left( \log(A+B) - \log B \right) \right]
    &\leq
	c_s \int_0^\infty\Tr\left[ \left( A (B + t \I )^{-1} \right)^{1+s}  \right]\d t
    \\
    &\leq\frac{c_s}{s}\Tr\left[ \left( B^{-\frac{s}{2(1+s)}} A B^{-\frac{s}{2(1+s)}} \right)^{1+s} \right], \quad \forall\, s\in (0,1],
    \label{eq:sharp_one-shot}
\end{align}
where $c_s=s^s(1-s)^{1-s} \leq 1$ for all $s\in[0,1]$. 
\end{theo}
\begin{proof} \label{proof:sharp_one-shot}
We first prove our claim for finite-dimensional Hilbert spaces, and then employ the finite-rank approximations to extend our results to infinite dimensions \cite[\S III.C]{Mos23}.
Note that the support of $A$ must be contained in that of $B$; otherwise, the finiteness hypothesis of $\Tr\left[ A \left( \log(A+B) - \log B \right) \right]$ would be violated.

After confining the space to the positive support of $B$, we may suppose $B>0$.
By the recently established operator layer cake theorem given in Theorem~\ref{theo:Dlog_formula} below with $X\leftarrow A+B$, $Y\leftarrow B$ and the fundamental theorem of calculus, we have
\begin{align*}
	\log (A+B) - \log B
	&= \int_{0}^1 \mathrm{D}\log\left[ B + \beta A \right] (A) \, \d \beta
	\\
&= \int_0^1\int_{0}^\infty  \left\{ u (B+\beta A)< A   \right\}  \, \d u\,\d\beta 
    \\
&\overset{\textnormal{(a)}}{=} \int_0^1\int_{0}^{\nicefrac{1}{\beta}}  \left\{ u (B+\beta A)< A   \right\}  \, \d u\,\d\beta 
    \\
&\overset{\textnormal{(b)}}{=} \int_0^1\int_{0}^\infty  \left\{ A > \gamma B  \right\} \frac{1}{(1+\beta\gamma)^2} \, \d \gamma\,\d\beta 
	\\
&\overset{\textnormal{(c)}}{=} \int_0^\infty \left\{ A > \gamma B \right\} \frac{1}{\gamma + 1} \, \d \gamma.
\end{align*}
Here, in (a), we have, for $u\ge \nicefrac{1}{\beta}$,
\[ u (B+\beta A)\ge  \frac{1}{\beta} (B+\beta A) > A\pl. \]
In (b), we used the change of variable $\gamma=\frac{u}{1-u\beta}=\frac{1}{\beta}(\frac{1}{1-\mu\beta}-1), u\in [0,\nicefrac{1}{\beta}]$. 
In (c), we calculate: 
\begin{align*}&\int_{0}^1\frac{1}{(1+\beta\gamma)^2 }\,\d\beta =-\frac{1}{\gamma}\frac{1}{(1+\beta\gamma)}\Big\vert_{\beta=0}^{\beta=1}=-\frac{1}{\gamma(1+\gamma)}+\frac{1}{\gamma}= \frac{1}{1+\gamma} .
\end{align*}

By Young's inequality,
\[
\gamma+1=(1-s)\cdot\frac{\gamma}{1-s}+s\cdot\frac{1}{s}\geq \left(\frac{\gamma}{1-s}\right)^{1-s}\left(\frac{1}{s}\right)^s,
\]
which translates to
\[
\frac{1}{\gamma+1}\leq c_s\gamma^{s-1}.
\]


As a result,
\begin{align}
    \int_0^{\infty} \left\{ A > \gamma B \right\} \frac{1}{\gamma+1} \, \d \gamma 
    &\leq c_s\int_0^{\infty} \left\{ A > \gamma B \right\} \gamma^{s-1} \, \d \gamma\\
    &=c_s\int_0^{\infty} \frac{1}{B+t\I}\left(A\frac{1}{B+t\I}\right)^{s}\, \d t.
\end{align}
The equality comes from the change of variables (see Theorem~\ref{theo:change-of-variable} below).

Hence,
\begin{align*}
    \Tr\left[ A \left( \log(A+B) - \log B \right) \right]
    &\leq c_s\Tr\left[ A \int_0^{\infty} \frac{1}{B+t\I}\left(A\frac{1}{B+t\I}\right)^{s}\, \d t \right]\\
    &=c_s \int_0^\infty\Tr\left[ \left( A (B + t \I )^{-1} \right)^{1+s}  \right]\d t\\
    &=c_s \int_0^\infty\Tr\left[ \left( (B + t \I )^{-\frac{1}{2}} A (B + t \I )^{-\frac{1}{2}} \right)^{1+s}  \right]\d t\\
    &\leq \frac{c_s}{s}\Tr\left[ \left(B^{-\frac{s}{2(1+s)}}AB^{-\frac{s}{2(1+s)}} \right)^{1+s} \right].
\end{align*}
The last inequality comes from the Araki--Lieb--Thirring inequality (see e.g., \cite[Proposition~3.10]{beigi2025some} but for $\alpha = 1+s>1$).

We now extend \eqref{eq:sharp_one-shot} to infinite-dimensional Hilbert spaces.
Let $(P_n)_{n\in\mathds{N}}$ be a sequence of finite rank spectral projections of $B$ such that $P_{n-1} \leq P_n$ and $P_n \nearrow \I$ in the strong operator topology.
Denote by $A_n = P_n A P_n$, $B_n = P_n B P_n$, and define
$D(A \Vert B) := \Tr\left[ A (\log A - \log B )] +\Tr[ B - A\right]$ as the Lindblad extension of relative entropy to positive semi-definite operators.
We start with the left-hand side:
\begin{align}
&\Tr\left[ A \left( \log (A+B) - \log B \right)\right]
\notag
\\
&= \Tr\left[ (A+B) \left( \log (A+B) - \log B \right) \right] - \Tr\left[ B \left( \log (A+B) - B \log B \right) \right]
\\
&= D(A+B\Vert B) + D(B\Vert A+B)
\\
&= \lim_{n\to\infty} \left\{ D\left( A_n+B_n \Vert B_n \right) 
+ D( B_n \Vert A_n+B_n ) \right\},
\end{align}
where we used Lemma~\ref{lemm:finit-rank} for approximating $D(\cdot\Vert\cdot)$ in the last line. Note that here the first equality is well-defined as we never run into ``$\infty-\infty$", because $D(B\Vert A+B)$ is always finite as $B\le A+B$.

On the other hand, for any integer $n\in\mathds{N}$,
we have shown 
\begin{align*}
    D\left( A_n+B_n \Vert B_n \right) 
    + D\left( B_n \Vert A_n+B_n \right) 
    &=
    \Tr\left[ A_n \left( \log(A_n+B_n) - \log B_n \right) \right]
    \\
    &\leq 
    c_s \Tr\left[ \left( (B_n + t \I )^{-\frac{1}{2}} A_n (B_n + t \I )^{-\frac{1}{2}} \right)^{1+s}  \right]
    \\
    &\leq \frac{c_s}{s}\Tr\left[ \left(B_n^{-\frac{s}{2(1+s)}} A_n B_n ^{-\frac{s}{2(1+s)}} \right)^{1+s} \right]
    \\
    &=: \frac{c_s}{s} \widetilde{Q}_{1+s}(A_n\Vert B_n), \quad \forall\, s\in (0,1].
\end{align*}
By applying Lemma~\ref{lemm:finit-rank-integral} for approximating the intermediate term $\Tr[ ( (B + t \I )^{-\nicefrac{1}{2}} A (B + t \I )^{-\nicefrac{1}{2}} )^{1+s}  ]$ and 
Lemma~\ref{lemm:finit-rank} again for approximating $\widetilde{Q}_{1+s}(\cdot\Vert\cdot)$, 
we conclude the proof.
\end{proof}

\begin{theo}[Operator layer cake {\cite[Theorem B.1]{preparation}}] \label{theo:Dlog_formula}
For any positive definite operator $X$ and any positive semi-definite operator $Y$ on a finite-dimensional Hilbert space,
the following representation holds:
\begin{align} \label{eq:Dlog_formula}
\mathrm{D} \log[X](Y) = \int_{0}^{\infty} \{ uX < Y \} \d u,
\end{align}
where $ \mathrm{D} \log[X](Y) $ is the directional derivative of the operator logarithm at $X$ with direction $Y$,
and $ \{ uX < Y \} \equiv \{ Y - uX > 0 \} $ denotes the projection onto the positive part of $Y-uX$.
\end{theo}

\begin{theo}[Operator change of variables {\cite[Theorem~C.1]{preparation}}]  \label{theo:change-of-variable}
Let $A$ and $B$ be finite-dimensional positive semi-definite operators satisfying $r := \|A B^{-1} \|_{\infty} < \infty$.
Then, for any Lebesgue-integrable function $h$ on $[0,r]$,
\begin{align} \label{eq:change-of-variable}
	\int_0^r \proj{ A > \gamma B } h(\gamma) \, \d \gamma
    % &= \int_0^\infty (B+t\I)^{-1} A (B+t\I)^{-1} h\left( A (B+t\I)^{-1} \right) \d t.
    &= \int_0^\infty \frac{1}{B+t\I} A \frac{1}{B+t\I} h\left( A \frac{1}{B+t\I} \right) \d t.
\end{align}
\end{theo}

\begin{remark}
The operators \( A(B + t\I)^{-1} \) and \( (B + t\I)^{-1}A \) are diagonalizable and have the same spectrum as \( (B + t\I)^{-1/2} A (B + t\I)^{-1/2} \) for all $t\geq 0$, since they are all similar. This implies that
\[
\frac{1}{B+t\I} h\left(A\frac{1}{B+t\I}\right)
= \frac{1}{\sqrt{B+t\I}} h\left(\frac{1}{\sqrt{B+t\I}} A \frac{1}{\sqrt{B+t\I}}\right)\frac{1}{\sqrt{B+t\I}}
= h\left(\frac{1}{B+t\I} A\right)\frac{1}{B+t\I}.
\]
Hence, each integrand in the right-hand side of \eqref{eq:change-of-variable} is self-adjoint, i.e.,
\begin{align}
    \frac{1}{\sqrt{B+t\I}} \underbrace{\frac{1}{\sqrt{B+t\I}} A  \frac{1}{\sqrt{B+t\I}} h\left(\frac{1}{\sqrt{B+t\I}} A \frac{1}{\sqrt{B+t\I}}\right)}_{ \text{self-adjoint} } \frac{1}{\sqrt{B+t\I}}.
\end{align}
\end{remark}



