\section{Applications} \label{sec:applictaion}

In this section, we demonstrate how the established trace inequality in Theorem~\ref{theo:sharp_one-shot} sharpens the existing one-shot achievability bounds in various quantum information-theoretic tasks including classical-quantum soft covering (Section~\ref{sec:covering}),
privacy amplification against quantum side information (Section~\ref{sec:PA}),
convex splitting (Section~\ref{sec:splitting}),
quantum information decoupling (Section~\ref{sec:decoupling}),
as well as quantum channel simulation (Section~\ref{sec:simulation}).
We will express the error estimates in terms of the integral \Renyi divergence \cite{hirche2023quantum, beigi2025some}
\begin{align}
    D_{\alpha}(\rho\Vert\sigma)
    \coloneq \frac{1}{\alpha-1}\log (\alpha-1) \int_0^\infty \Tr\left[ \left( B + t\I\right)^{-\nicefrac{1}{2}} A \left( B + t\I\right)^{-\nicefrac{1}{2}}  \right]\d t
\end{align}
or the sandwiched \Renyi divergence \cite{MDS+13, WWY14}:
\begin{align}
    \widetilde{D}_{\alpha} (\rho\Vert\sigma) 
    \coloneq \frac{1}{\alpha-1}\log \Tr\left[ \left( \sigma^{-\frac{1}{2\alpha}} \rho  \sigma^{-\frac{1}{2\alpha}} \right)^{\alpha} \right], \quad \alpha > 1
\end{align}
where $\rho$ and $\sigma$ are positive semi-definite trace-class operators with $\Tr[\rho] = 1$.
There, the error criterion is either under the purified distance 
\begin{align}
    P(\rho, \sigma) := \sqrt{  1 - \e^{- \widetilde{D}_{1/2}(\rho\Vert\sigma)}  },
\end{align}
or the quantum relative entropy \cite{Ume56}:
\begin{align}
D(\rho\Vert\sigma) = \lim_{\alpha \searrow 1 } \widetilde{D}_{\alpha} (\rho\Vert\sigma) 
= \Tr\left[ \rho ( \log \rho - \log \sigma ) \right].
\end{align}

\subsection{Soft Covering} \label{sec:covering}

% \cite{Hay15}

\begin{defn}[Classical-quantum soft covering with non-uniform randomness] \label{defn:covering}
	Let $\rho_{\X\B} = \sum_{x\in\X} p_{\X}(x) |x\rangle \langle x|_{\X} \otimes \rho_{\B}^x$ be a classical-quantum state, where $p_{\X}$ is a probability distribution on a finite alphabet $\X$, and each $\rho_{\B}^x$ is a density operator (i.e.~a positive semi-definite operator with unit trace), and the marginal state on system $\B$ is $\rho_{\B} = \sum_{x\in\X} p_{\X} (x) \rho_{\B}^x$.
    Let $p_{\mathsf{M}}$ be a probability distribution on an alphabet $\mathsf{M}$.
	\begin{enumerate}[1.]
		\item Alice has classical registers $\mathsf{M}$ and $\X$.

		\item Alice samples from the set $\mathsf{M}$ according distribution $p_{\mathsf{M}}$.

		\item For each sample $m\in\mathsf{M}$, Alice encodes it to a codeword $x(m)$ in $\X$.

		\item Alice queries the classical-quantum channel $x\mapsto \rho_{\B}^x$ with the codeword $x(m)$.
	\end{enumerate}

	An $(M, \eps)$-resolvability code is a codebook $\{x(m)\}_{m\in\mathsf{M}}$ satisfying $|\mathsf{M}| = M$ such that the codebook-induced state $\mathds{E}_{m \sim p_{\mathsf{M}}}[\rho_{\B}^{x(m)}]$ is at least $\varepsilon$-close to the target state $\rho_{\B}$ in terms of relative entropy, i.e.~
	\begin{align} \notag
		 D\left(\mathds{E}_{m \sim p_{\mathsf{M}}} [\rho_{\B}^{x(m)}] \Vert \rho_{\B} \right)
		\leq \varepsilon.
	\end{align}
\end{defn}

We adopt the random coding as follows.
For each $m\in\mathsf{M}$, Alice chooses the codeword $x(m)$ according to the input distribution $p_{\X}$ pairwise independently, i.e., the random codeword $x(m)$ is independent of $x(\bar{m})$ for $m\neq \bar{m}$.
Channel resolvability via random coding is called \emph{soft covering}; see \cite{Hay15, CG22, SGC22b, HCG24}.

\begin{prop} \label{prop:covering}
For any classical-quantum state $\rho_{\X\B} = \sum_{x\in\X} p_{\X}(x) |x\rangle \langle x|_{\X} \otimes \rho_{\B}^x$ and distribution $p_{\mathsf{M}}$ given in Definition~\ref{defn:covering}, the random coding error satisfies
\begin{align} \label{eq:covering}
\mathds{E}_{x(m)\sim p_{\X}} D\left(\mathds{E}_{m \sim p_{\mathsf{M}}} [\rho_{\B}^{x(m)}] \Vert \rho_{\B} \right)
\leq \frac{c_{\alpha-1}}{\alpha-1} \e^{ - (\alpha-1) \left[ H_{\alpha}(\mathsf{M})_{p} - {D}_{\alpha}\left( \rho_{\X\B} \Vert \rho_{\X} \otimes \rho_{\B} \right) \right]  }, \quad \forall\,\alpha \in (1,2],
\end{align}
where $H_{\alpha}(\mathsf{M})_{p} := \frac{1}{1-\alpha}\log \sum_m p_{\mathsf{M}}(m)^{\alpha}$ is the R\'enyi entropy.
\end{prop}

Proposition~\ref{prop:covering} improves on \cite[Lemma 4]{Hay15} by a factor $c_{\alpha-1} \in [1/2,1]$ for $\alpha \in (1,2]$ and by removing the dimension-dependent factor $|\text{spec}(\mathcal{H}_{\B})|^{\alpha-1}$. This in turn improves mutual information leakage to quantum eavesdroppers via a classical-quantum wiretap channel by the same fashion; c.f.~\cite[(65)]{Hay15}.


If uniform randomness is available at Alice, i.e.,
$p_{\mathsf{M}}$ is a uniform distribution,  Definition~\ref{defn:covering} reduces to the conventional {classical-quantum channel resolvability} via uniform randomness, and the right-hand side of \eqref{eq:covering} becomes $\frac{c_{\alpha-1}}{\alpha-1} \e^{ - (\alpha-1) \left[ \log |\mathsf{M}| - \widetilde{D}_{\alpha}(\rho_{\X\B}\Vert \rho_{\X} \otimes \rho_{\B}) \right]  }$.
In the $n$-fold independent and identical setting where $\rho_{\X\B}\leftarrow \rho_{\X\B}^{\otimes n}$ and $|\mathsf{M}| = \exp(nR)$ with $R > I(\X:\B)_{\rho} = D(\rho_{\X\B}\Vert \rho_{\X}\otimes \rho_{\B})$, we remark that the (regularized) error exponent obtained in Proposition~\ref{prop:covering}, i.e.,
\begin{align}
\sup_{\alpha \in (1,2]} (\alpha-1) \left[ R - \widetilde{D}_{\alpha}(\rho_{\X\B}\Vert \rho_{\X} \otimes \rho_{\B}) \right]
\end{align}
is tight for the commuting case \cite[Theorem 3]{TPM17}.

\begin{proof}[Proof of Proposition~\ref{prop:covering}]
The first part of the proof essentially follows \cite[Lemma 4]{Hay15}.
Given each $m\in\mathsf{M}$ and the corresponding realization of a codeword $x(m) \in \X $, we first calculate the conditional expectation:
\begin{DispWithArrows}[displaystyle]
&\mathds{E}_{x(\bar{m})\mid x(m)} \left[ \log \sum_{\bar{m}\in \mathsf{M}} p_{\mathsf{M}}(\bar{m}) \rho_{\B}^{x(\bar{m})}\right]
\notag
\\
&= \mathds{E}_{x(\bar{m})\mid x(m)} \left[ \log \left( p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} + \sum_{\bar{m}\neq m} p_{\mathsf{M}}(\bar{m}) \rho_{\B}^{x(\bar{m})} \right)\right]
\Arrow{\textnormal{$\log$ is operator concave}}
\notag
\\
&\leq \log \left( p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} + \mathds{E}_{x(\bar{m})\mid x(m)} \left[ \sum_{\bar{m}\neq m} p_{\mathsf{M}}(\bar{m}) \rho_{\B}^{x(\bar{m})} \right]\right)
\Arrow{\textnormal{pairwise independence}}
\notag
\\
&= \log \left( p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} + \sum_{\bar{m}\neq m} p_{\mathsf{M}}(\bar{m})  \rho_{\B} \right)
\Arrow{\textnormal{$\sum_{\bar{m}\neq m} p_{\mathsf{M}}(\bar{m})\leq 1$ \&} \\  \textnormal{$\log$ is operator monotone}}
\notag
\\
&\leq \log \left( p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} + \rho_{\B} \right).
\notag
\end{DispWithArrows}

Using the above operator inequality, we have 
\begin{DispWithArrows}[displaystyle]
\mathds{E}_{x(m)\sim p_{\X}} D\left(\mathds{E}_{m \sim p_{\mathsf{M}}} [\rho_{\B}^{x(m)}] \Vert \rho_{\B} \right)
% &= \mathds{E}_{\mathcal{C}} \Tr\left[ \sum_m p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} \left( \log \sum_m p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} - \log \rho_{\B} \right) \right]
% \\
&= \sum_{m\in\mathsf{M}} \mathds{E}_{x(m)} \Tr \left[  
 p_{\mathsf{M}}(m)  \rho_{\B}^{x(m)} \mathds{E}_{x(\bar{m})\mid x(m)} \left( \log \sum_{\bar{m}\in\mathsf{M}} p_{\mathsf{M}}(\bar{m}) \rho_{\B}^{x(\bar{m})} - \log \rho_{\B} \right) \right]
 \notag
\\
&\leq \sum_{m\in\mathsf{M}} \mathds{E}_{x(m)} \Tr  \left[  p_{\mathsf{M}}(m)  \rho_{\B}^{x(m)} \left(  \log \left( p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} + \rho_{\B} \right) - \log \rho_{\B} \right) \right]
\notag
\\
&\leq \frac{c_{\alpha-1}}{\alpha-1} \sum_{m\in\mathsf{M}} \mathds{E}_{x(m)}   p_{\mathsf{M}}(m)^{\alpha} \e^{ (\alpha-1) \widetilde{D}_{\alpha} \left( \rho_{\B}^{x(m)} \Vert \rho_{\B} \right) }
\notag
\\
&= \frac{c_{\alpha-1}}{\alpha-1} \e^{ - (\alpha-1) \left[ H_{\alpha}(\mathsf{M})_{p} - \widetilde{D}_{\alpha}\left( \rho_{\X\B} \Vert \rho_{\X} \otimes \rho_{\B} \right) \right]  }, \quad \forall\,\alpha \in (1,2],
\notag
\end{DispWithArrows}
where the second inequality follows from Theorem~\ref{theo:sharp_one-shot} with $A\leftarrow p_{\mathsf{M}}(m) \rho_{\B}^{x(m)} $ and $B\leftarrow \rho_{\B}$.
\end{proof}



\subsection{Privacy Amplification} \label{sec:PA}


\begin{defn} \label{defn:PA}
Let $\rho_{\X\E} = \sum_{x\in\X} p_{\X}(x) |x\rangle \langle x|_{\X} \otimes \rho_{\E}^x$ be a classical-quantum state.
\begin{enumerate}[1.]
    \item 
    Alice has a classical register $\X$ and the eavesdropper has a quantum register $\E$.
    Initially, they share the state $\rho_{\X\E}$.

    \item
    Alice applies a linear operation $\mathscr{R}^h( \rho_{\X\E} )$ on her system according to a hash function $h:\X\to \Z$:
    \begin{align} 
    \mathscr{R}^h( \rho_{\X\E} )
    := \sum_{x\in\X} p_{\X}(x) |h(x)\rangle \langle h(x)|_{\Z} \otimes \rho_{\E}^x
    = \sum_{z\in\Z} |z\rangle \langle z |_{\Z} \otimes \sum_{x: h(x) = z} p_{\X}(x) \rho_{\E}^x.
    \label{eq:R^h}
    \end{align}
\end{enumerate}
The aim of Alice is for her resulting state $\mathscr{R}^h( \rho_{\X\E} )$ to be independent to the quantum system $\E$ and close to uniform randomness in relative entropy:
\begin{align} \label{eq:error_PA}
D\left( \mathscr{R}^h( \rho_{\X\E} ) \Vert \nicefrac{\I}{|\mathsf{Z}|} \otimes \rho_{\E} \right)
\end{align}
with as larger $|\Z|$ as possible.
\end{defn}

As noted in \cite[Equation (9)]{Hay15_PA}, the security criterion given in \eqref{eq:error_PA} ensures the mutual information between the systems $\Z$ and $\E$ to be controlled, i.e.
\begin{align}
D\left( \mathscr{R}^h( \rho_{\X\E} ) \Vert \nicefrac{\I}{|\mathsf{Z}|} \otimes \rho_{\E} \right)
&= I(\Z : \E)_{ \mathscr{R}^h( \rho_{\X\E} ) } + D\left(\mathscr{R}^h( \rho_{\X} )\Vert \nicefrac{\I}{|\mathsf{Z}|} \right).
\end{align}

We adopt a \emph{$2$-universal random hash function} $h:\X\to \Z$ satisfying for all $x,\bar{x} \in \X$ with $x\neq \bar{x}$,
\begin{align} \label{eq:2-universal}
\Pr_{h}\left\{  h(x) = h(\bar{x}) \right\} \leq \frac{1}{|\Z|}.
\end{align}

\begin{prop} \label{prop:PA}
Following Definition~\ref{defn:PA} and using a $2$-universal random hash function, we have
\begin{align}
\mathds{E}_{h} D\left( \mathscr{R}^h( \rho_{\X\E} )  \Vert \nicefrac{\I}{|\mathsf{Z}|} \otimes \rho_{\E} \right)
&\leq
\frac{c_{\alpha-1}}{\alpha-1}  \e^{ - (\alpha-1) \left[ -\log |\Z| - {D}_{\alpha} \left( \rho_{\X\E} \Vert \I_{\X}\otimes \rho_{\E} \right)  \right] }, \quad \forall\, \alpha \in (1,2]
\end{align}
\end{prop}

Proposition~\ref{prop:PA} improves on \cite[Theorem 1]{Hay15_PA} by a factor $c_{\alpha-1} \in [\nicefrac{1}{2},1]$ for $\alpha \in (1,2]$ and by removing the dimension-dependent factor $|\text{spec}(\mathcal{H}_{\E})|^{\alpha-1}$ at the eavesdropper.

In the $n$-fold independent and identical setting where $\rho_{\X\E}\leftarrow \rho_{\X\E}^{\otimes n}$ and $|\Z| = \exp(nR)$ with $R < H(\X\mid\E)_{\rho} := - D(\rho_{\X\E}\Vert \I_{\X}\otimes \rho_{\E})$, we remark that the (regularized) error exponent obtained in Proposition~\ref{prop:PA}, i.e.,
\begin{align}
\sup_{\alpha \in (1,2]} (\alpha-1) \left[ -\widetilde{D}_{\alpha}(\rho_{\X\E}\Vert \I_{\X} \otimes \rho_{\E}) - R \right]
\end{align}
is tight for $\left.\frac{\d}{\d s} - s \widetilde{D}_{1+s}(\rho_{\X\E}\Vert\I_{\X}\otimes \rho_{\E})\right|_{s=1} \leq R < H(\X\mid\E)_{\rho}$ \cite[Theorem 1]{KL21} (see also \cite[Theorem 1]{HT17} for the classical case).

\begin{proof}[Proof of Proposition~\ref{prop:PA}]
    The proof follows closely from that of Proposition~\ref{prop:covering}, which is also inspired by that of \cite[Theorem 1]{Hay15_PA}.
    The key difference is that we will employ Theorem~\ref{theo:sharp_one-shot} in the derivations.

    For each fixed $x\in\X$, the operator concavity of logarithm implies
    \begin{DispWithArrows}[displaystyle]
    \mathds{E}_h \log \left( \sum_{\bar{x}\colon h(\bar{x}) = h(x) } p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} \right)
    &\leq \log \left( \mathds{E}_h \left[ \sum_{\bar{x}\colon h(\bar{x}) = h(x) } p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} \right] \right)
    \notag
    \\
    &=\log \left( \mathds{E}_h \left[ p_{\X}({x}) \rho_{\E}^{{x}}  + \sum_{\substack{\bar{x}\colon h(\bar{x}) = h(x) \\ \bar{x}\neq x} } p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} \right]\right)
    % \Arrow{\textnormal{by} \eqref{eq:2-universal}}
    \notag
    \\
    &\overset{\textnormal{(a)}}{\leq} \log \left(  p_{\X}({x}) \rho_{\E}^{{x}}  + \frac{1}{|\Z|} \sum_{\bar{x} \colon \bar{x}\neq x } p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} \right)
    % \Arrow{\textnormal{$\sum_{\bar{x}\neq x} p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} \leq \rho_{\E}$ \&} \\  \textnormal{$\log$ is operator monotone}}
    \notag
    \\
    &\overset{\textnormal{(b)}}{\leq}  \log \left(  p_{\X}({x}) \rho_{\E}^{{x}}  + \frac{1}{|\Z|} \rho_{\E} \right), 
    \label{eq:PA_1}
    \end{DispWithArrows}
    where (a) is by the definition of $2$-universal hash functions in \eqref{eq:2-universal} and the operator monotonicity of logarithm, 
    and (b) is because $\sum_{\bar{x}\neq x} p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} \leq \sum_{\bar{x} \in \X} p_{\X}(\bar{x}) \rho_{\E}^{\bar{x}} = \rho_{\E}$ and again logarithm is operator monotone.

    Then, using \eqref{eq:R^h}, we calculate
    \begin{DispWithArrows}[displaystyle]
    \mathds{E}_{h} D\left( \mathscr{R}^h( \rho_{\X\E} )  \Big\Vert \frac{\I}{|\mathsf{Z}|} \otimes \rho_{\E} \right)
    % &= \mathds{E}_{h} \Tr\left[ \sum_{z\in\Z} |z\rangle \langle z|_{\X} \otimes \sum_{x\colon h(x) = z} p_{\X}(x)\rho_{\E}^x \left( \log\left( \right) - \log \frac{1}{|\Z|}\otimes \rho_{\E} \right) \right]
    &{=} \mathds{E}_h D \left( \sum_{z\in\Z} |z\rangle \langle z|_{\X} \otimes \sum_{x\colon h(x) = z} p_{\X}(x)\rho_{\E}^x \,\bigg\Vert\, \frac{\I}{|\Z|}\otimes \rho_{\E} \right)
    \\
    &\overset{\textnormal{(a)}}{=} \mathds{E}_h \sum_{z\in\Z} \Tr\left[ \sum_{x\colon h(x) = z} p_{\X}(x)\rho_{\E}^x \left( \log\left( \sum_{ \bar{x} \colon h(\bar{x}) = z} p_{\X}(\bar{x})\rho_{\E}^{\bar{x}} \right) - \log \frac{\rho_{\E}}{|\Z|} \right) \right]
    \\
    &= \mathds{E}_h \sum_{x\in\X} \Tr\left[  p_{\X}(x)\rho_{\E}^x \left( \log\left( \sum_{ \bar{x} \colon h(\bar{x}) = h(x) } p_{\X}(\bar{x})\rho_{\E}^{\bar{x}} \right) - \log \frac{\rho_{\E}}{|\Z|} \right) \right]
    \\
    &\overset{\textnormal{(b)}}{\leq} \sum_{x\in\X} \Tr\left[  p_{\X}(x)\rho_{\E}^x \left( \log \left(  p_{\X}({x}) \rho_{\E}^{{x}}  + \frac{\I}{|\Z|} \rho_{\E} \right) - \log \frac{\rho_{\E}}{|\Z|} \right) \right]
    \\
    &\overset{\textnormal{(c)}}{\leq} \frac{c_{\alpha-1}}{\alpha-1}  \sum_{x\in\X} p_{\X}(x)^{\alpha} \e^{ (\alpha-1) \left[ \widetilde{D}_{\alpha}\left( \rho_{\E}^x \Vert \rho_{\E} \right) + \log |\Z| \right]  }
    \\
    &= \frac{c_{\alpha-1}}{\alpha-1}  \sum_{x\in\X} p_{\X}(x)^{\alpha} \e^{ (\alpha-1) \left[ \widetilde{D}_{\alpha}\left( \rho_{\E}^x \Vert \rho_{\E} \right) + \log |\Z| \right]  }, 
    \\ &=\frac{c_{\alpha-1}}{\alpha-1}  \e^{ - (\alpha-1) \left[ -\log |\Z| - \widetilde{D}_{\alpha} \left( \rho_{\X\E} \Vert \I_{\X}\otimes \rho_{\E} \right)  \right] }
    \quad \forall\, \alpha \in (1,2],
    \end{DispWithArrows}
    where %(a) follows from \eqref{eq:R^h},
    (a) follows from the direct-sum structure of $D(\cdot\Vert \cdot)$,
    (b) follows from \eqref{eq:PA_1},
    and (c) follows from Theorem~\ref{theo:sharp_one-shot} with $A\leftarrow p_{\X}(x) \rho_{\E}^x$ and $B\leftarrow {\rho_{\E}}/{|\Z|}$.
\end{proof}

\subsection{Convex Splitting} \label{sec:splitting}

\begin{defn}[Convex splitting with non-uniform randomness] \label{defn:splitting}
Let $\rho_{\A\B}$ and $\tau_{\A}$ be quantum states satisfying $\textrm{supp}(\rho_{\A}) \subseteq \textrm{supp}(\tau_{\A})$, let $\mathsf{M} = \{1,2,\ldots, M\} =: [M]$ be a finite set, and let $p_{\mathsf{M}}$ be a probability distribution on $\mathsf{M}$.
\begin{enumerate}[1.]
    \item 
    Alice has quantum registers $\A_1, \A_2, \ldots, \A_M$, where $\A_m \simeq \A$ all initialized with state $\tau_{\A_m}$ and has a quantum register $\A$, and Bob has a quantum register $\B$.
    The initial state on system $\A\B$ is $\rho_{\A\B}$.

    \item
    Alice randomly embeds her state on $\A$ to $\A_m$ with probability $p_{\mathsf{M}}(m)$.
\end{enumerate}
    The aim of Alice is for the mixture
    \begin{align}
	\omega_{\A_1\ldots \A_M \B} = \sum_{m=1}^M p_{\mathsf{M}} (m) \cdot \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes [M]\backslash \{m\}}
    \end{align}
    to be close to the product state $\otimes_{m=1}^M \tau_{\A_m} \otimes \rho_{\B}$ in relative entropy:
    \begin{align}
	\begin{split} \label{eq:D}
		&\Delta^{D}_{M}\left( \rho_{AB} \,\Vert\, \tau_{\A} \right) :=
		D\left( \omega_{\A_1\ldots \A_M \B} \, \Vert\, \tau_{\A}^{\otimes M} \otimes \rho_B \right) 
        \notag
        \\
		&= \sum_{m\in\mathsf{M}} \Tr\left[  p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \left( \log \left( \sum_{\bar{m}\in\mathsf{M}} p_{\mathsf{M}}(\bar{m}) \rho_{\A_{\bar{m}} \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{\bar{m}\}} \right) - \log \tau_{\A}^{\otimes M} \otimes \rho_B \right) \right]
	\end{split}
    \end{align}
    as least integer $M$ as possible.
\end{defn}

We remark that convex splitting was proposed by Anshu \textit{et al.} \cite{ADJ17}.
A tight analysis under trace distance was studied by parts of the authors \cite{CG22b}.


\begin{prop} \label{prop:splitting}
Let $\rho_{\A\B}$ and $\tau_{\A}$ be quantum states satisfying $\textrm{supp}(\rho_{\A}) \subseteq \textrm{supp}(\tau_{\A})$.
Following Definition~\ref{defn:splitting}, we have
\begin{align}
\Delta^{D}_{M}\left( \rho_{\A\B} \,\Vert\, \tau_{\A} \right)
% D\left( \omega_{\A_1\ldots \A_M \B} \, \Vert\, \tau_{\A}^{\otimes M} \otimes \rho_B \right) 
&\leq
\frac{c_{\alpha-1}}{\alpha-1}  \e^{ - (\alpha-1) \left[ H_{\alpha}(\mathsf{M})_p - {D}_{\alpha} \left( \rho_{\A\B} \Vert \tau_{\A}\otimes \rho_{\B} \right)  \right] }, \quad \forall\, \alpha \in (1,2]
\end{align}
\end{prop}

Proposition~\ref{prop:splitting} improves on 
\cite[Lemma 13]{LY21b} by a factor $c_{\alpha-1} \in [\nicefrac{1}{2},1]$ for $\alpha \in (1,2]$ and by removing the dimension-dependent factor $|\text{spec}(\mathcal{H}_{\A} \otimes \mathcal{H}_{\B})|^{\alpha-1}$.

\begin{proof}
First, for each $m\in [M]$, we define a completely positive trace-preserving map to trace out all the $\A_{\bar{m}}$ systems for $\bar{m}\neq m$ and append it with a state $\tau_{\A_{\bar{m}}}$, i.e.,
\begin{align}
	\mathscr{N}^{(m)} = \Tr_{ \A_{[M]\backslash \{m\} } }\left[\,\cdot\, \right] \otimes \tau_{\A}^{\otimes [M]\backslash \{{m}\}},
\end{align}
such that
\begin{align} \label{eq:splitting_trace_out}
\begin{split}
	\mathscr{N}^{(m)} \left( \rho_{\A_{\bar{m}} \B} \otimes \tau_{\A}^{\otimes [M]\backslash \{\bar{m}\}} \right)
	=
	\begin{dcases}
		\rho_{\A_{{m}} B} \otimes \tau_{\A}^{\otimes[M]\backslash \{{m}\}} & \bar{m} = m, \\
		\tau_{\A}^{\otimes M} \otimes \rho_B & \bar{m} \neq m. \\
	\end{dcases}
    \end{split}
\end{align}
%{\color{red} Naturally, we may choose $\mathscr{N}^{(m)} = \Tr_{ A_{[M]\backslash \{m\} } }\left[\,\cdot\, \right] \otimes \tau_{\A}^{\otimes [M]\backslash \{\bar{m}\}} $, but it is not unital.}
Then, data-processing inequality of Umegaki's relative entropy \cite{Ume54} implies that, for each $m\in[M]$,
\begin{align}
	D\left( \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \, \Vert\, \omega_{\A_1\ldots \A_M \B} \right)
	&\geq D\left( \mathscr{N}^{(m)} \left( \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}}  \right) \, \Vert\, \mathscr{N}^{(m)} \left( \omega_{\A_1\ldots \A_M \B}  \right) \right)\\
	&= D\left( \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}}  \, \Vert\, \mathscr{N}^{(m)} \left( \omega_{\A_1\ldots \A_M \B}  \right) \right),
\end{align}
which translates to
\begin{align}
	\Tr\left[ \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \log \omega_{\A_1\ldots \A_M \B} \right] \leq
	\Tr\left[ \rho_{\A_m \B} \otimes  \tau_{\A}^{\otimes[M]\backslash \{m\}} \log  \mathscr{N}^{(m)} \left(\omega_{\A_1\ldots \A_M \B} \right) \right]. \label{eq:D1}
\end{align}


By applying \eqref{eq:D1}, we bound the first term in the bracket of \eqref{eq:D} as follows: for each $m\in[M]$,
\begin{align}
	&\Tr\left[ p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \log \omega_{\A_1\ldots \A_M \B} \right] \\
	&\leq 	\Tr\left[ p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \log   \mathscr{N}^{(m)} \left(\omega_{\A_1\ldots \A_M \B} \right) \right] \\
	&\overset{\textnormal{(a)}}{=} \Tr\left[ p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \log \left( p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} + \sum_{\bar{m}\neq m} p_{\mathsf{M}}(\bar{m}) \tau_{\A}^{\otimes M} \otimes \rho_B \right) \right] \\
	&\overset{\textnormal{(b)}}{\leq} \Tr\left[ p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \log \left( p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} +  \tau_{\A}^{\otimes M} \otimes \rho_B \right) \right], \label{eq:D2}
\end{align}
where we invoked \eqref{eq:splitting_trace_out} in (a) and used the operator monotonicity of logarithm in (b).
Combining \eqref{eq:D} with \eqref{eq:D2}, we have, for all $s\in[0,1]$:
\begin{DispWithArrows}[displaystyle]
	&D\left( \omega_{\A_1\ldots \A_M \B} \, \Vert \tau_{\A}^{\otimes M} \otimes \rho_B \right)
    \notag
    \\ 
    &\leq \sum_{m\in\mathsf{M}} \Tr\left[ p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \left( \log \left( p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} +  \tau_{\A}^{\otimes M} \otimes \rho_B \right) - \log \tau_{\A}^{\otimes M} \otimes \rho_{\B} \right)\right]
    % \Arrow{additivity \& symmetry}
    \notag
    \\
    &= \sum_{m\in\mathsf{M}} \Tr\left[ p_{\mathsf{M}}(m)\rho_{\A\B} \left( \log ( p_{\mathsf{M}}(m) \rho_{\A\B} + \tau_{\A}\otimes \rho_{\B}) - \log \tau_{\A}\otimes \rho_{\B} \right) \right] 
    \notag
    \\
    &\leq \frac{c_{\alpha-1}}{\alpha-1} \sum_{m\in\mathsf{M}} \mathds{E}_{x(m)}   p_{\mathsf{M}}(m)^{\alpha} \e^{ (\alpha-1) \widetilde{D}_{\alpha} \left( \rho_{\A\B} \Vert \tau_{\A}\otimes \rho_{\B} \right) }
    \notag
    \\
    &= \frac{c_{\alpha-1}}{\alpha-1}  \e^{ - (\alpha-1) \left[ H_{\alpha}(\mathsf{M})_p - \widetilde{D}_{\alpha} \left( \rho_{\A\B} \Vert \tau_{\A}\otimes \rho_{\B} \right)  \right] }, \quad \forall\, \alpha \in (1,2],
\end{DispWithArrows}
where the first inequality follows from 
\begin{align*}&\Tr\left[\rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \left( \log \left( p_{\mathsf{M}}(m) \rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} +  \tau_{\A}^{\otimes M} \otimes \rho_B \right) - \log \tau_{\A}^{\otimes M} \otimes \rho_{\B} \right)\right]
\\=& \Tr\left[\rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \left( \log \left( (p_{\mathsf{M}}(m) \rho_{\A_m \B}+\tau_{\A}^{\otimes M}) \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}}\right) - \log \tau_{\A}\otimes \rho_{\B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}}\right)\right]
\\=& \Tr\left[\rho_{\A_m \B} \otimes \tau_{\A}^{\otimes[M]\backslash \{m\}} \left( \log (p_{\mathsf{M}}(m) \rho_{\A_m \B}+\tau_{\A}^{\otimes M})  - \log \tau_{\A}\otimes \rho_{\B} \right)\right]
\\=& \Tr\left[\rho_{\A_m \B}  \left( \log (p_{\mathsf{M}}(m) \rho_{\A_m \B}+\tau_{\A}^{\otimes M})  - \log \tau_{\A}\otimes \rho_{\B} \right)\right]\ 
\end{align*}
and the second inequality follows from Theorem~\ref{theo:sharp_one-shot} with $A\leftarrow p_{\mathsf{M}}(m) \rho_{\A\B} $ and $B\leftarrow \tau_{\A}\otimes \rho_{\B}$.
\end{proof}

If $p_{\mathsf{M}}$ is uniform, we then have the following achievable (regularized) error exponent for any $n$-fold product expansion: for all $R > D(\rho_{\A\B}\Vert \tau_{\A}\otimes \rho_{\B})$,
\begin{align}
	\lim_{n\to \infty} -\frac1n \log \Delta^{D}_{\mathrm{e}^{nR}}\left( \rho_{AB}^{\otimes n} \,\Vert\, \tau_{\A}^{\otimes n} \right)
	\geq
	\sup_{\alpha\in (1,2]} (\alpha-1) \left( R - \widetilde{D}_\alpha(\rho_{AB}\,\Vert\, \tau_{\A}\otimes \rho_B)  \right).
\end{align}

\subsubsection{Quantum State Redistribution} \label{sec:QSR}

% {\color{ForestGreen}
% \textbf{Need references.}
% }

\begin{defn}[Quantum State Redistribution] \label{defn:QSR}

	Let $\rho_{\R \A \C \B}$ be a pure state.
	\begin{enumerate}[1.]
		\item 
        Alice has quantum registers $\A$ and $\C$ at sender,
        Bob has a quantum register $\B$ at receiver, and $\R$ is an inaccessible reference system.
        The initial state of the protocol is $\rho_{\R \A \C \B}$.

		\item A resource of free entanglement, say $|\tau\rangle_{\bar{\A} \bar{\B}}$, is shared between the sender (holding register $\bar{\A}$) and the receiver (holding register $\bar{\B}$), and noiseless one-way classical communication from the sender to receiver is available.

		\item Alice applies a local operation on her system and the shared entanglement to obtain $\log M$ nats of classical messages.

		\item The sender sends the above message to the receiver via one-way noiseless classical communication.

		\item 
		Upon receiving the messages, the receiver applies a local operation on his shared entanglement to obtain an overall resulting state $\widehat{\rho}_{\R \A \B \C}$ and now the quantum register $\C$ is held by Bob at the receiver.
\end{enumerate}

An $(M, \eps)$ Quantum State Redistribution protocol for $\rho_{\R \A \C}$ with entanglement $|\tau\rangle_{\bar{\A}' \bar{\B}'}$ satisfies
		\begin{align}
			P\left( \widehat{\rho}_{\R \A \B \C} , \rho_{\R \A \B \C} \right) \leq \eps.
		\end{align}
		% where $\rho_{\R \A \B \C} := (\id_{\C \to \C} \otimes \id_{\A\R}) \rho_{\R \A \C \B}$.
\end{defn}

\begin{prop} \label{prop:QSR}
For any pure state $\rho_{\R\A\C\B} = |\rho\rangle\langle \rho|_{\R\A\C\B}$, there exists an $(M, \eps)$ Quantum State Redistribution protocol for $\rho_{\R\A\C\B}$ with entanglement $|\tau\rangle_{\bar{\A} \bar{\B}}^{\otimes M}$ (where $\bar{\A} \cong \bar{\B} \cong \C $) satisfying
	\begin{align} \label{eq:error_QSS}
	\eps &\leq
	\sqrt{ \frac{c_{\alpha-1}}{\alpha-1} } \cdot
    \e^{- \frac{(\alpha-1)}{2}\left[ \log M - {D}_{\alpha}(\rho_{\C\R\B} \Vert \tau_{\C} \otimes \rho_{\R\B} ) \right]  }, \quad \forall\, \alpha \in (1,2].
	\end{align}
\end{prop}

\begin{proof} \label{proof:QSR}
The achievability (i.e., the upper bound on $\eps$) of Quantum State Redistribution has been shown via convex splitting in Ref.~\cite{ADK+17} (see also \cite{AJW18, BCG25}).
Below, we will demonstrate how the sharpened convex splitting (Proposition~\ref{prop:splitting}) can improve the error bound using $\log M$ nats of noiseless classical communication. The idea of using convex splitting for Quantum State Redistribution is due to Anshu \textit{et al.} \cite{ADJ17}.

% Let $\tau_{\bar{\A}}$ be a state that will be specified later.
To begin the protocol, we let the sender (Alice) and the receiver (Bob) share $M$-copies of entanglement $\otimes_{m\in[M]} |\tau\rangle_{\bar{\A}_{m} \bar{\B}_{m}}$,
where Bob holds register $\bar{\B}_{m} \cong \C$  that purifies Alice's register $\bar{\A}_{m} \cong \C$, and $[M]:= \{1,2,\ldots, M\}$
We begin with the following pure state:
\begin{align} \label{eq:initial_bipartite}
|{\omega}\rangle := |\rho\rangle_{\R\A\C\B} 
\otimes_{m\in[M]} |\tau\rangle_{\bar{\A}_{m} \bar{\B}_{m}}.
\end{align}

Suppose, hopefully, by the protocol, we end up with the following pure state:
\begin{align} \label{eq:target_bipartite}
\begin{split} 
|\widehat{\omega}\rangle
&:= \frac{1}{\sqrt{M}} \sum_{m\in [M]} |m\rangle_{\mathsf{M}} 
|\rho\rangle_{\R\A\B\C_{m}} |0\rangle_{\bar{\A}_{m}}
\otimes_{\bar{m} \in [M]\setminus \{m\}} |\tau\rangle_{\bar{\A}_{\bar{m}} \bar{\B}_{\bar{m}}},
\end{split}
\end{align}
where Alice holds registers $\mathsf{M}$, $\A$, $\bar{\A}_{[M]} := \bar{\A}_{1} \bar{\A}_{2}\ldots \bar{\A}_{M}$,
Bob holds registers $\bar{\B}_{[M]} := \bar{\B}_{1} \bar{\B}_{2} \ldots \bar{\B}_{M}$, and notice that the register ${\C}_m \cong \bar{\B}_m$ for each $m\in[M]$ is held by Bob.
Alice measures her system $\mathsf{M}$, and sends the measurement outcome $m \in [M]$ to Bob via $\log M$ nats of classical communication.
At the receiver, Bob picks up the $m$-th register $\C_{m}$ to end up with $|\rho\rangle_{\R\A\B\C_{m}} \cong |\rho\rangle_{\R\A\B\C}$, which is exactly the target state we aimed for the Quantum State Splitting protocol.

Then, it remains to show that there exists a local operation protocol at Alice such that the desired state $|{\widehat{\omega}}\rangle$ in Eq.~\eqref{eq:target_bipartite} can be approximated via the Quantum State Redistribution protocol.
Note that the reduced state of the initial state $|{\omega}\rangle$ is
\begin{align}
{\omega}_{\R\B \bar{\B}_{[M]}} &= \rho_{\R\B}  \otimes_{m\in[M]} \tau_{\bar{\B}_{m}}. %\text{ ($\C_m$ at Alice)}
\end{align}
The convex splitting established in Proposition~\ref{prop:splitting} ensures that ${\omega}_{\R\B\bar{\B}_{[M]}}$ can be approximated  
by the following state
\begin{align} %\label{eq:omega_bipartite_QSS}
\begin{split}
\widehat{\omega}_{\R\B\bar{\B}_{[M]}}
&:= \frac{1}{M} \sum_{m\in [M] }
\rho_{\R\B\bar{\B}_{m}} 
\otimes_{\bar{m} \in [M]\setminus \{m\}} \tau_{\bar{\B}_{\bar{m}}},
\end{split}
\end{align}
within an error $\eps$ (in terms of purified distance) satisfying
\begin{align} \label{eq:error_QSR1}
\eps =   P\left(\widehat{\omega}_{\R\B\bar{\B}_{[M]}}, {\omega}_{\R\B \bar{\B}_{[M]}} \right)
    \leq \sqrt{ \frac{c_{\alpha-1}}{\alpha-1} } \cdot
    \e^{- \frac{(\alpha-1)}{2}\left[ \log M - {D}_{\alpha}(\rho_{\bar{B}\R\B} \Vert \tau_{\bar{B}} \otimes \rho_{\R\B} ) \right]  }, \quad \forall\, \alpha \in (1,2]
\end{align}
(by substituting registers $\A$ by $\bar{B}$ and $\B$ by $\R\B$).
Note that the sandwiched \Renyi divergence is invariant under isometry $\id_{\bar{B} \to \C}$ (since $\bar{B}\cong\C$); we can express the error bound in terms of ${D}_{\alpha}(\rho_{\C\R\B} \Vert \tau_{\C} \otimes \rho_{\R\B} )$. (Here, the register $\C$ is held by Alice or Bob is immaterial as it does not affect the divergence $\widetilde{D}_{\alpha}$.


Lastly, observe that $\widehat{\omega}_{\R\B \bar{\B}_{[M]}}$ is the reduced state of the desired pure state $|\widehat{\omega}\rangle$ given in Eq.~\eqref{eq:target_bipartite}. 
Hence, by Uhlmann's theorem (see Lemma~\ref{lemm:Uhlmann}), there exists an isometry $\mathscr{V}$ acting on register $\A\C\bar{\A}_{[M]}$ to register $\mathsf{M}\A\bar{\A}_{[M]}$ such that $P(\mathscr{V} (|{\omega}\rangle\langle \omega |), |\widehat{\omega}\rangle\langle\widehat{\omega}|)  = P(\widehat{\omega}_{\R\B\bar{\B}_{[M]}}, {\omega}_{\R\B \bar{\B}_{[M]}} )$.
Moreover, since the isometry $V$ is a local operation acting only on Alice's registers, this constitutes the Quantum State Splitting protocol with an error $\eps$.
\end{proof}




