\begin{defn}[Catalytic quantum information decoupling via removing a subsystem] \label{defn:decoupling}
Let $\rho_{\A\E}$ be a quantum state.
The protocol aims to decouple quantum information in system $\A$ from system $\E$ with assistance of a catalytic system $\bar{\A}$.
\begin{enumerate}[1.]
	\item 
	Alice holds a quantum register $\A$ and a catalytic register $\bar{\A}$, and Eve holds a quantum register $\E$.

	\item 
    Alice is free to choose a state $\tau_{\bar{\A}}$ in the catalytic system $\bar{\A}$.

	\item Alice applies a local unitary $\mathscr{U}$ on her systems $\A\bar{\A}$ to end up with systems $\A_1 \A_2$ (i.e., $|\A\bar{\A}| = |\A_1\A_2|)$, and then remove the system $\A_2$ (via partial trace).
\end{enumerate}		
	An $(M, \eps)$ catalytic quantum information decoupling protocol for $\rho_{\A\E}$ is the existence of the catalytic system $\bar{\A}$, a state $\tau_{\bar{\A}}$ on it, and a unitary $\mathscr{U}_{\A\bar{\A}\to \A_1\A_2}$ satisfying $|\A_2| \leq M$ and 
	\begin{align}
	\inf_{\omega_{\A_1}} P\left( \Tr_{\A_2}\left[ \mathscr{U}_{\A\bar{\A}\to \A_1\A_2}(\rho_{\A\E}\otimes \tau_{\bar{\A}}) \right], \omega_{\A_1} \otimes \rho_{\E} \right) \leq \eps,
	\end{align}
	where infimum is over all states $\omega_{\A_1}$.
\end{defn}

% \begin{remark}
% {\color{ForestGreen}
% Equivalence by ~\cite[Proposition 6]{LY21a} 
% }
% \end{remark}

\begin{prop} \label{prop:catalystic_decoupling}
Let $\rho_{\A\E}$ be a quantum state.
Following Definition~\ref{defn:decoupling}, there exists an $(M, \eps)$ catalytic quantum information decoupling protocol for $\rho_{\A\E}$ satisfying
\begin{align}
    \eps 
    &\leq \sqrt{\frac{c_{\alpha-1}}{\alpha-1}} \e^{- (\alpha-1)\left[ \log M - \frac12 \inf_{\tau_{\A}} {D}_{\alpha}\left(\rho_{\A\E} \Vert \tau_{\A} \otimes \rho_{\E} \right) \right] }, \quad \forall\, \alpha\in(1,2].
\end{align}
\end{prop}

\begin{proof}
The proof strategy follows in a similar way to that of \cite[Theorem 7]{LY21a}.
Our contribution is to employ a key technique of sharpened one-shot bound for convex splitting established in Proposition~\ref{prop:splitting}.
For completeness, we detail the proof below.

We first show that there exists an $(\sqrt{M},\eps)$ decoupling operation via random unitaries:
\begin{align}
\mathscr{R}_{\A\bar{A}}: X \mapsto \frac{1}{\sqrt{M}} \sum_{m=1}^{\sqrt{M}} \mathscr{U}_m(X),
\end{align}
where $\bar{\A} = \A_2 \A_3 \ldots \A_{\sqrt{M}}$, and each unitary $\mathscr{U}_m$ is a swap between system $\A_m$ with $\A_1 \cong \A$. 
Let the catalytic state be $\otimes_{m=2}^{\sqrt{M}} \tau_{\A_m}$.
We have
\begin{align}
\mathscr{R}_{\A\bar{\A}}\left( \rho_{\A\R} \otimes \otimes_{m=2}^{\sqrt{M}} \tau_{\A_m} \right)
= \frac{1}{M} \sum_{m=1}^{\sqrt{M}} \rho_{\A_m \R} \otimes_{\bar{m}\neq m} \tau_{\A_{\bar{m}}}.
\end{align}

Via the convex splitting established in Proposition~\ref{prop:splitting},
\begin{align}
P\left( \mathscr{R}_{\A\bar{\A}}\left( \rho_{\A\R} \otimes \otimes_{m=2}^{\sqrt{M}} \tau_{\A_m} \right), \rho_{\R} \otimes \tau_{\A}^{\otimes \sqrt{M}} \right)
&\leq \sqrt{\frac{c_{\alpha-1}}{\alpha-1}} \e^{- (\alpha-1)\left[ \frac12 \log M - \frac12 {D}_{\alpha}\left(\rho_{\A\R} \Vert \tau_{\A} \otimes \rho_{\R} \right) \right] }, \quad \forall\, \alpha\in(1,2].
\end{align}

Lastly, recall that the existence of a $(\sqrt{M},\eps)$ decoupling map via the above random unitaries is equivalent to the existence of an $({M},\eps)$ decoupling map by removing systems (Definition~\ref{defn:decoupling}) \cite[Proposition 6]{LY21a}, we conclude the proof.
\end{proof}

\subsection{Quantum Channel Simulation} \label{sec:simulation}

% \cite{LY21b}



\begin{defn}[Entanglement-assisted quantum channel simulation]\label{defn:channel-simulation}
Let $\mathscr{N}_{\A\to \B}$ be a quantum channel.
\begin{enumerate}[1.]
	\item 
	Alice at the sender holds a quantum register $\A$, and Bob at the receiver holds a quantum register
	$\B$, and $\R$ is an inaccessible reference system.

	\item A resource of free entanglement is shared between Alice (holding registers $\bar{\A}$) and Bob (holding register $\bar{\B}$).

	\item Alice applies a local operation on her systems and sends $\log M$
	nats of classical information to the receiver.

	\item 
	Upon receiving the message, Bob applies a local operation on his own system.
\end{enumerate}		
	An $( M, \eps)$ quantum channel simulation protocol for $\mathscr{N}_{\A\to\B}$ with a \emph{fixed} pure input state $\theta_{\R\A}$ satisfies
	\begin{align}
	P\left( \widehat{\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) , {\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) \right) \leq \eps,
	\end{align}
	where $\widehat{\mathscr{N}}_{\A\to \B}(\theta_{\R\A})$ is the effectively resulting state from Alice's register $\A$ to Bob's register $\B$. 
	The $\log M$ denotes the classical communication costs in the channel simulation protocol.

    An $( M, \eps)$ quantum channel simulation protocol for $\mathscr{N}_{\A\to\B}$ with an \emph{arbitrary} pure input state satisfies
	\begin{align}
	\sup_{\theta_{\R\A}} P\left( \widehat{\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) , {\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) \right) \leq \eps,
	\end{align}
    where the supremum is taken over all pure states $\theta_{\R\A}$.
\end{defn}


\subsubsection{Channel Simulation With a Fixed Input} \label{sec:QSS}

\begin{prop} \label{prop:simulation_fixed}
Let $\mathscr{N}_{\A\to \B}$ be a quantum channel and let $\theta_{\R\A}$ be a fixed pure input state.
Following Definition~\ref{defn:channel-simulation}, there exists an $( M, \eps)$ quantum channel simulation protocol for $\mathscr{N}_{\A\to\B}$ with the input state $\theta_{\R\A}$ satisfying
	\begin{align} \label{eq:error_simulation_fixed}
	\eps &\leq
	\sqrt{ \frac{c_{\alpha-1}}{\alpha-1} } \cdot
    \e^{- \frac{(\alpha-1)}{2}\left[ \log M - \inf_{\tau_{\B}} {D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} ) \right]  }, \quad \forall\, \alpha \in (1,2],
	\end{align}
    where $\rho_{\R\B} := \mathscr{N}_{\A\to\B}(\theta_{\R\A})$ and the infimum on the right-hand side is over all states $\tau_{\B}$.
\end{prop}

Proposition~\ref{prop:simulation_fixed} improves on \cite[Proposition 13]{LY21b} by a factor $c_{\alpha-1} \in [1/2,1]$ for $\alpha \in (1,2]$ and by removing the dimension-dependent factor $|\text{spec}(\mathcal{H}_{\B})|^{\alpha-1}$.

\begin{proof}
Let $\mathscr{U}_{\A\to\B\E}$ be a Stinespring dilation of $\mathscr{N}_{\A\to\B}$.
% and let $\theta_{\A\R\bar{\R}}$ be a purification of the input $\theta_{\A\R}$.
Alice first simulates a local isometry $\mathscr{U}_{\A\to\B\E}$ at her side to obtain the state
\begin{align}
\rho_{\R\E\B} :=
\left(\mathscr{U}_{\A\to\B\E} \otimes \id_{\R \bar{\R}} \right) \theta_{\A\R}.
\end{align}
Next, we apply the Quantum State Splitting for $\rho_{\R\E\B}$ given in Section~\ref{sec:QSR} with registers 
$\R\leftarrow \R$ at the reference system, 
$\A \leftarrow \E$ at Alice, 
and $\C \leftarrow \B$ at Bob (i.e., a Quantum State Redistribution with the register $\B$ being void), to send the channel output system $\B$ to Bob via $\log M$ nats of classical communication and $M$-copies of $|\tau\rangle_{\bar{\A}\bar{\B}}$, where $\bar{B}\cong \B$.

Let the overall resulting state be $\mathscr{U}_{\A\to\B\E}(\theta_{\A\R})$. We obtain the following error bound by Proposition~\ref{prop:QSR}:
\begin{align}
    P\left( \hat{\mathscr{U}}_{\A\to\B\E}(\theta_{\A\R}), \mathscr{U}_{\A\to\B\E}(\theta_{\A\R}) \right)
    &\leq \sqrt{ \frac{c_{\alpha-1}}{\alpha-1} } \cdot
    \e^{- \frac{(\alpha-1)}{2}\left[ \log M - {D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} ) \right]  }, \quad \forall\, \alpha \in (1,2].
\end{align}
Lastly, by tracing out the systems $\E$, the data-processing inequality of purified distance $P(\cdot,\cdot)$, and optimizing over all shared entangled states $|\tau\rangle_{\bar{\A}\bar{\B}}$, we conclude the proof.
\end{proof}


\subsubsection{Channel Simulation With Arbitrary Inputs} \label{sec:simulation_arbitrary}

\begin{prop} \label{prop:simulation_arbitrary}
Let $\mathscr{N}_{\A\to \B}$ be a quantum channel.
Following Definition~\ref{defn:channel-simulation}, there exists an $( M, \eps)$ quantum channel simulation protocol for $\mathscr{N}_{\A\to\B}$ with arbitrary pure input states satisfying
	\begin{align} \label{eq:error_simulation_arbitrary}
	\eps &\leq
	\sqrt{ \frac{c_{\alpha-1}}{\alpha-1} } \cdot
    \e^{- \frac{(\alpha-1)}{2}\left[ \log M - \sup_{\theta_{\R\A}} \inf_{\tau_{\B}} {D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} ) \right]  }, \quad \forall\, \alpha \in (1,2],
	\end{align}
    where $\rho_{\R\B} := \mathscr{N}_{\A\to\B}(\theta_{\R\A})$, 
    the supremum is over all pure input states $\theta_{\R\A}$, and
    the infimum is over all states $\tau_{\B}$.
\end{prop}

Proposition~\ref{prop:simulation_arbitrary} improves on \cite[Theorem 9]{LY21b} by a factor $c_{\alpha-1} \in [1/2,1]$ for $\alpha \in (1,2]$ and by removing the dimension-dependent factor $ |\text{spec}(\mathcal{H}_{\A})|^2 \cdot
|\text{spec}(\mathcal{H}_{\R})|^{\alpha-1} \cdot |\text{spec}(\mathcal{H}_{\B})|^{\alpha-1}$.


In the $n$-fold independent and identical setting where $\mathscr{N}_{\A\to\B}\leftarrow \mathscr{N}_{\A\to\B}^{\otimes n}$ and $M = \exp(nR)$ with $R > D(\rho_{\B\R}\Vert \rho_{\B} \otimes \rho_{\R})$,
the additivity property (see Lemma~\ref{lemm:sandwiched_channel_additive} below) and Proposition~\ref{prop:simulation_arbitrary} yield an achievable (regularized) error exponent:
\begin{align}
\sup_{\alpha \in (1,2]} \frac{(\alpha-1)}{2}\left[ R - \sup_{\theta_{\R\A}} \inf_{\tau_{\B}} \widetilde{D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} ) \right],
\end{align}
which has been shown to be tight for $R < \left.\frac{\d}{\d s} s \inf_{\tau_{\B}} \widetilde{D}_{1+s}(\rho_{\B\R}\Vert\tau_{\B}\otimes \rho_{\R})\right|_{s=1}$ \cite[Theorem 11]{LY21b}.



Before commencing the proof, let us add some historical remarks.
Quantum channel simulation with arbitrary input states has been extensively studied in the literature \cite{BSS+02,BDH+14,BCR11,LY21b, BCG25}.
Preliminary methods of handling arbitrary input states rely on the so-called \emph{post-selection technique} \cite{ChristKoenRennerPostSelect}, which is also known as the \emph{de Finetti reduction}.
A recent work \cite{CJT24} proposed the idea of using the minimax identity to bypass the post-selection technique for bounding the minimal communication cost.
Below, we demonstrate that the minimax identity is also useful in the error bound by resorting to a concavity and convexity properties of the sandwiched \Renyi divergence (Lemmas~\ref{lemm:concavity_state} and \ref{lemm:convexity_order}).

\begin{proof}[Proof of Proposition~\ref{prop:simulation_arbitrary}]\label{proof:simulation_arbitrary}
By Definition~\ref{defn:channel-simulation}, we would like to show the existence of an $(M,\eps)$-quantum simulation protocol such that for all pure input states $\theta_{\R\A}$, the purified distance is at most $\eps$.
Thanks to the minimax identity to interchange the supremum between $\theta_{\R\A}$ and infimum between all protocols (Lemma~\ref{lemm:minimax}), it is sufficient to show the error bound for each input states $\theta_{\R\A}$, and then choose the worst input in the end.

For any pure input state $\theta_{\R\A}$, we apply Proposition~\ref{prop:simulation_fixed} to simulate a channel $\hat{\mathscr{N}}_{\A\to\B}$ with an error
\begin{align}
P\left( \widehat{\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) , {\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) \right) 
&\leq
	\sqrt{ \frac{c_{\alpha-1}}{\alpha-1} } \cdot
    \e^{- \frac{(\alpha-1)}{2}\left[ \log M - \inf_{\tau_{\B}} {D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} ) \right]  }, \quad \forall\, \alpha \in (1,2],
	\end{align}
where $\rho_{\R\B} := \mathscr{N}_{\A\to\B}(\theta_{\R\A})$.

Then, we maximize over all pure input states $\theta_{\R\A}$ (i.e., the worst case scenario).
By invoking the convexity of the map $\alpha \mapsto (\alpha-1) \inf_{\tau_{\B}} \widetilde{D}_{\alpha} (\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R})$ on the convex set $\alpha \in (1,2]$ (Lemma~\ref{lemm:convexity_order}),
the concavity of the map $\theta_{\R\A} \mapsto \inf_{\tau_{\B}} \widetilde{D}_{\alpha} (\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R})$ (Lemma~\ref{lemm:concavity_state})\footnote{The input state $\theta_{\R\A}$ can be taken to be general mixed state, but it can be attained by pure states due to the convexity. Hence, without loss of generality, we only consider pure input states in Definition~\ref{defn:channel-simulation}},
and Sion's minimax theorem, we have
\begin{align}
\inf_{\theta_{\R\A}} \sup_{\alpha \in (1,2]} (1-\alpha) \inf_{\tau_{\B}} \widetilde{D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} )
&=  \sup_{\alpha \in (1,2]} \inf_{\theta_{\R\A}} (1-\alpha) \inf_{\tau_{\B}} \widetilde{D}_{\alpha}(\rho_{\B\R} \Vert \tau_{\B} \otimes \rho_{\R} ),
\end{align}
which concludes the proof.
\end{proof}

