\begin{lemm}[Finite-rank approximations, relative entropy and sandwiched quasi divergence {\cite[Lemmas 3 \& 4]{Lin74}}, {\cite[Corollary 5.12]{Petz_book_1993}}, {\cite[Proposition~III.39]{Mos23}}] \label{lemm:finit-rank}
Let $A$ and $B$ be non-zero trace-class operators on an infinite-dimensional separable Hilbert space.
Then, for any $\alpha >1 $,
\begin{align}
D(A \Vert B) 
&\coloneq \Tr\left[ A (\log A - \log B) + B-A \right]
= \lim_{n\to\infty} D(P_n A P_n \Vert P_n B P_n),
% \\
% \widetilde{D}_{\alpha}(A \Vert B) 
% &= \lim_{n\to\infty} \widetilde{D}_{\alpha}(P_n A P_n \Vert P_n B P_n),
\\
\widetilde{Q}_{\alpha}(A \Vert B) 
&\coloneq 
\Tr\left[ \left( \sigma^{-\frac{1}{2\alpha}} \rho  \sigma^{-\frac{1}{2\alpha}} \right)^{\alpha} \right]
= \lim_{n\to\infty} \widetilde{Q}_{\alpha}(P_n A P_n \Vert P_n B P_n)
\end{align}
where $(P_n)_{n\in\mathds{N}}$ is any sequence of projections such that $\Tr[P_n] = n$, $P_{n-1} \leq P_n$, and $P_n \nearrow \I$ in the strong operator topology.
\end{lemm}
[Go back to \hyperref[proof:sharp_one-shot]{\textit{Proof of Theorem~\ref{theo:sharp_one-shot}}}]

\medskip

\begin{lemm}[Finite-rank approximations, integral quasi divergence] \label{lemm:finit-rank-integral}
Let $A$ and $B$ be non-zero trace-class operators on an infinite-dimensional separable Hilbert space.

Then, for any $\alpha >1 $,
\begin{align}
{Q}_{\alpha}(A \Vert B) 
&\coloneq (\alpha-1) \int_0^\infty \Tr\left[ \left( \left( B + t\I\right)^{-\nicefrac{1}{2}} A \left( B + t\I\right)^{-\nicefrac{1}{2}} \right)^{\alpha} \right]\d t
= \lim_{n\to\infty} {Q}_{\alpha}(P_n A P_n \Vert P_n B P_n)
\end{align}
where $(P_n)_{n\in\mathds{N}}$ is a sequence of projections of $B$ such that $\Tr[P_n] = n$, $P_{n-1} \leq P_n$, and $P_n \nearrow \I$ in the strong operator topology.
\end{lemm}
[Go back to \hyperref[proof:sharp_one-shot]{\textit{Proof of Theorem~\ref{theo:sharp_one-shot}}}]

\begin{proof}[Proof of Lemma~\ref{lemm:finit-rank-integral}]
Fix $s>0$. Assume
\begin{align}
    \int_0^\infty \Tr\left[ \left( (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}} \right)^{1+s} \right] \, \d t < \infty.
\end{align}
Denote 
\begin{align}
    f(t)
    &= \int_0^\infty \Tr\left[ \left( (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}} \right)^{1+s} \right] \, \d t,
    \\
    f_n(t)
    &= \int_0^\infty \Tr\left[ \left( (B+t\I)^{-\nicefrac{1}{2}} P_n A P_n (B+t\I)^{-\nicefrac{1}{2}} \right)^{1+s} \right] \, \d t
    \\
    &= \int_0^\infty \Tr\left[ \left( (P_n B P_n +t\I)^{-\nicefrac{1}{2}} P_n A P_n ( P_n B P_n +t\I)^{-\nicefrac{1}{2}} \right)^{1+s} \right] \, \d t.
\end{align}
where $P_n$ is the spectral projection for $B$ and $P_n \nearrow \I$.
Since $t\mapsto f(t)$ is decreasing, we have $f(t) < \infty$ for all $t>0$.

It suffices to show $f_n \leq f$ and $f_n \to f$ pointwise.
Then, by Monotone Convergence Theorem,
\begin{align}
    \int_0^\infty f_n(t) \, \d t
    \nearrow \int_0^\infty f(t) \, \d t.
\end{align}

We first show $f(t) \geq f_n (t)$ for all $t>0$.
Define the channel $\Phi_n (X) = P_n^\perp X P_n^{\perp} + P_n X P_n$.
Note that $\Phi_n$ is unital and trace-preserving.
Hence, the Schatten $p$-norm is contractive under $\Phi_n$, i.e.,
\begin{align}
\left\| \Phi_n(X) \right\| \leq \|X\|_p, \quad \forall\, p\geq 1.
\end{align}
Then,
\begin{align}
    f_n(t)
    &= \Tr\left[ \left(  \frac{P_n A P_n}{ P_n B P_n + t \I } \right)^{1+s} \right]
    \\
    &= \Tr\left[ \left( P_n (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}}  P_n \right)^{1+s} \right]
    \\
    &\leq \Tr\left[ \left( P_n (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}}  P_n \right)^{1+s} \right]
    + \Tr\left[ \left( P_n^\perp (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}}  P_n^\perp \right)^{1+s} \right]
    \\
    &= \left\| \Phi_n \left( (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}} \right) \right\|_{1+s}^{1+s}
    \\
    &\leq 
    \left\| (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}} \right\|_{1+s}^{1+s}
    \\
    &= f(t).
\end{align}

Next, by using the fact that $P_n$ is a spectral projection of $B$, we calculate
\begin{align}
f_n(t)^{\frac{1}{1+s}} - f(t)^{\frac{1}{1+s}} 
&= \left\| (B+t\I)^{-\nicefrac{1}{2}} P_n A P_n (B+t\I)^{-\nicefrac{1}{2}} \right\|_{1+s}
- \left\| (B+t\I)^{-\nicefrac{1}{2}} A (B+t\I)^{-\nicefrac{1}{2}} \right\|_{1+s}
\\
&\leq \left\| (B+t\I)^{-\nicefrac{1}{2}} \right\|_{\infty} \left\| P_n A P_n - A \right\|_{1+s} \left\| (B+t\I)^{-\nicefrac{1}{2}} \right\|_{1+s}
\\
&\leq t^{-1} \left\| P_n A P_n - A \right\|_1.
\end{align}
Then,
\begin{align}
    \left\| P_n A P_n - A \right\|_1
    &\leq \left\| P_n - A \right\|_1 
    + \left\| P_n A P_n - P_n A \right\|_1
    \\
    &\leq \left\| P_n A^{-\nicefrac{1}{2}} - A^{\nicefrac{1}{2}} \right\|_2
    \left\|A^{\nicefrac{1}{2}} \right\|_2
    + \left\| P_n A^{\nicefrac{1}{2}}  \right\|_2 \left\|  A^{-\nicefrac{1}{2}} P_n  - A^{\nicefrac{1}{2}} \right\|_2
    \\
    &= \sqrt{ \Tr\left[ P_n A P_n + A - P_n A - A P_n  \right]  \Tr\left[ A \right] }
    + \sqrt{ \Tr\left[ P_n A \right]\Tr\left[ P_n A P_n + A - P_n A - A P_n  \right]   }
    \\
    &\rightarrow 0,
\end{align}
as $\lim_{n\to\infty} \Tr\left[ P_n A P_n \right] = \lim_{n\to 0} \Tr[P_n A ] = \Tr[A]$.
Hence, $f_n \to f$ pointwise.
We complete the proof.
\end{proof}

