\begin{lemm}[A Minimax identity {\cite{CJT24}}] \label{lemm:minimax}
Let $\mathfrak{P}_{\A\to\B}^{(M)}$ be the set of all quantum simulation protocols for the channel in Definition~\ref{defn:channel-simulation}, i.e.,~all entanglement-assisted local operations and $\log M$ nats of one-way classical communication.
Then, for any quantum channel $\mathscr{N}_{\A\to\B}$,
\begin{align}
\inf_{\hat{\mathscr{N}}_{\A\to\B} \in \mathfrak{P}_{\A\to\B}^{(M)}} \sup_{\theta_{\R\A}} P\left( \widehat{\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) , {\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) \right)
= \sup_{\theta_{\R\A}} \inf_{\hat{\mathscr{N}}_{\A\to\B} \in \mathfrak{P}_{\A\to\B}^{(M)}}  P\left( \widehat{\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) , {\mathscr{N}}_{\A\to \B}(\theta_{\R\A}) \right).
\end{align}
\end{lemm}
