\begin{lemm}[Additivity {\cite[Lemma 5]{GW14}}] \label{lemm:sandwiched_channel_additive}
Let $\mathscr{N}: \A \to \B$ be a quantum channel.
For any integer $n$, let $\rho_{\R^n\B^n} := \mathscr{N}_{\A\to\B}^{\otimes n}(\theta_{\R^n\A^n})$ for any pure state $\theta_{\R^n\A^n}$.
Then, for all $\alpha > 1$,
\begin{align}
\sup_{\theta_{\R^n\A^n}} \inf_{\sigma_{\B^n}} \widetilde{D}_{\alpha}\left(\rho_{\R^n\B^n} \Vert \rho_{\R^n} \otimes \sigma_{\B^n} \right)
= n \cdot \sup_{\theta_{\R\A}} \inf_{\sigma_{\B}} \widetilde{D}_{\alpha}\left(\rho_{\R\B} \Vert \rho_{\R} \otimes \sigma_{\B} \right).
\end{align}
\end{lemm}
