\begin{lemm}[Concavity in state {\cite[Lemma 4]{GW14}}] \label{lemm:concavity_state}
Let $\mathscr{N}: \A \to \B$ be a quantum channel and let $\rho_{\R\B} := \mathscr{N}_{\A\to\B}(\theta_{\R\A})$ for any state $\theta_{\R\A}$.
Then, the map
\begin{align}
\theta_{\R\A} &\mapsto \inf_{\sigma_{\B}} \widetilde{D}_{\alpha} (\rho_{\R\B} \Vert \rho_{\R} \otimes \sigma_{\B})
\end{align}
is concave for all states on $\mathcal{H}_{\R}\otimes \mathcal{H}_{\A}$.
\end{lemm}
\noindent [Go back to \hyperref[proof:simulation_arbitrary]{\textit{Proof of Proposition~\ref{prop:simulation_arbitrary}}}]
