\begin{lemm}[Convexity in order] \label{lemm:convexity_order}
Let $\rho_{\A\B}$ be a state.
Then, the map
% \begin{align}
% s &\mapsto s \inf_{\sigma_{\B}} \widetilde{D}_{\frac{1}{1+s}} (\rho_{\A\B} \Vert \rho_{\A} \otimes \sigma_{\B}), \end{align}
% is concave for $s \in (-1,0)$, and the map
\begin{align}
