\noindent [Go back to \hyperref[proof:simulation_arbitrary]{\textit{Proof of Proposition~\ref{prop:simulation_arbitrary}}}]

\begin{proof}[Proof of Lemma~\ref{lemm:convexity_order}] \label{proof:convexity_order}
The case of system $\A$ being classical has been shown in \cite[Theorem 11]{CGH19}. In the following, we adopt a similar proof technique via complex interpolation theory.

For all $\alpha\geq 1$, we let $\alpha' = \frac{\alpha}{\alpha-1}$ be its H\"older conjugate.
Fix $\alpha = (1-\theta) \alpha_0 + \theta \alpha_1$, $\theta \in [0,1]$, and $\alpha_0, \alpha_1 \geq 1$.
By the definition of the sandwiched \Renyi divergence, we write
\begin{align}
\inf_{\sigma_{\B}} \widetilde{D}_{\alpha} \left( \rho_{\A\B} \Vert \rho_{\A} \otimes \sigma_{\B} \right)
&= \frac{\alpha}{\alpha-1} \log \left\| \left( \rho_{\A}^{- \frac{1}{2\alpha'}} \otimes \sigma_{\B}^{- \frac{1}{2\alpha'}} \right) \rho_{\A\B} \left( \rho_{\A}^{- \frac{1}{2\alpha'}} \otimes \sigma_{\B}^{- \frac{1}{2\alpha'}} \right) \right\|_{\alpha}
\\
&=: \frac{\alpha}{\alpha-1} \log \left\|  \rho_{\A}^{- \frac{1}{2\alpha'}} \rho_{\A\B} \rho_{\A}^{- \frac{1}{2\alpha'}} \right\|_{S_1(\B, S_\alpha(\A))}, 
\end{align}
by using the notation of the amalgamated norm \cite{JP10}.
The desired convexity is then equivalent to 
\begin{align}
\left\|  \rho_{\A}^{- \frac{1}{2\alpha'}} \rho_{\A\B} \rho_{\A}^{- \frac{1}{2\alpha'}} \right\|_{S_1(\B, S_\alpha(\A))}
\leq 
\left\|  \rho_{\A}^{- \frac{1}{2\alpha_0'}} \rho_{\A\B} \rho_{\A}^{- \frac{1}{2\alpha_0'}} \right\|_{S_1(\B, S_{\alpha_0}(\A))}^{\frac{\alpha_0(1-\theta)}{\alpha}}
\left\|  \rho_{\A}^{- \frac{1}{2\alpha_1'}} \rho_{\A\B} \rho_{\A}^{- \frac{1}{2\alpha_1'}} \right\|_{S_1(\B, S_{\alpha_1}(\A))}^{\frac{\alpha_1\theta}{\alpha}}.
\end{align}

Denote $y = \frac{\alpha_1 \theta}{\alpha}$ and $1-y = \frac{\alpha_0(1-\theta)}{\alpha}$ such that $\frac{1}{\alpha} = \frac{1-y}{\alpha_0} + \frac{y}{\alpha_1}$.
We consider an analytic family of operators:
\begin{align}
    F: z \mapsto \mathtt{N}^y \mathtt{M}^{1-y} \rho_{\A}^{-\frac12(1-\frac{1-z}{\alpha_0}-\frac{z}{\alpha_1})} \rho_{\A\B} \rho_{\A}^{-\frac12(1-\frac{1-z}{\alpha_0}-\frac{z}{\alpha_1})},
\end{align}
where
\begin{align}
    \mathtt{M}
    &:= \left\| \rho_{\A}^{-\frac{1}{2\alpha_0'}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha_0'}} \right\|_{S_1(\B,S_{\alpha_0}(\A))}^{-1},
    \\
    \mathtt{N}
    &:= \left\| \rho_{\A}^{-\frac{1}{2\alpha_1'}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha_1'}} \right\|_{S_1(\B,S_{\alpha_1}(\A))}^{-1}.
\end{align}
We bound the boundary the map $F$ as follows:
\begin{align}
\left\|F(\mathrm{i}t)\right\|_{S_1(\B,S_{\alpha_0}(\A))} &= \left\| \mathtt{M}^{-\mathrm{i}t} \mathtt{N}^{\mathrm{i}t} \mathtt{N}^{-1} \rho_{\A}^{-\frac{1}{2\alpha_0}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha_0}} \right\|_{S_1(\B,S_{\alpha_0}(\A))}
\leq 1,
\\
\left\|F(1+\mathrm{i}t)\right\|_{S_1(\B,S_{\alpha_1}(\A))} &= \left\| \mathtt{M}^{\mathrm{i}t} \mathtt{N}^{-\mathrm{i}t} \mathtt{M}^{-1} \rho_{\A}^{-\frac{1}{2\alpha_1}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha_1}} \right\|_{S_1(\B,S_{\alpha_1}(\A))}
\leq 1.
\end{align}

By interpolation (Lemma~\ref{lemm:interpolation}) and the fact that  the amalgamated norm forms an interpolation spaces~\cite{JP10},
\begin{align}
    1 
    &\geq \left\|F(y)\right\|_{S_1(\B,S_{\alpha}(\A))}
    \\
    &= \left\| \mathtt{N}^y \mathtt{M}^{1-y} \rho_{\A}^{-\frac{1}{2\alpha'}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha'}} \right\|_{S_1(\A,S_{\alpha}(\B))}
    \\
    &= \mathtt{N}^y \mathtt{M}^{1-y} \left\|  \rho_{\A}^{-\frac{1}{2\alpha'}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha'}} \right\|_{S_1(\A,S_{\alpha}(\B))},
\end{align}
which translates to the desired convexity:
\begin{align}
\left\|  \rho_{\A}^{-\frac{1}{2\alpha'}} \rho_{\A\B} \rho_{\A}^{-\frac{1}{2\alpha'}} \right\|_{S_1(\A,S_{\alpha}(\B))}
\leq \mathtt{M}^{y-1} \mathtt{N}^{-y} .
\end{align}
\end{proof}

\begin{lemm}[Riesz--Thorin interpolation theorem  {\cite{BL76}}] \label{lemm:interpolation} Let $(X_0, X_1)$ and $(Y_0, Y_1)$ be two compatible couples of Banach spaces and let $(X_0, X_1)_\theta$ and $(Y_0, Y_1)_\theta$ be the corresponding complex interpolation space of exponent $\theta\in [0,1]$. Suppose $T:X_0 + X_1 \to Y_0 + Y_1$, is a linear operator bounded from $X_j$ to $Y_j$, $j=0, 1$. Then $T$ is bounded from $(X_0, X_1)_\theta$ to $(Y_0, Y_1)_\theta$, and moreover,
\[ \|T:(X_0, X_1)_\theta\to (Y_0, Y_1)_\theta\|_{}\leq \|T:X_0\to Y_0\|_{}^{1-\theta }\|T:X_1\to Y_1\|_{}^{\theta}\ ,\  \theta\in [0,1].\]
\end{lemm}
\noindent [Go back to \hyperref[proof:convexity_order]{\textit{Proof of Lemma~\ref{lemm:convexity_order}}}]

