\begin{theorem}
\label{th:shallow}
     Let $\eps>0$, $p=p(n)\in[0,1]$, and $\mathbf{G}\sim G_{n,p}$.
     \begin{enumerate}
     \item If $p\geq (1+\eps)n^{-1/3}$, then w.h.p.\ there exists a tree $T\subseteq \mathbf{G}$ of diameter 4 such that $T\to \mathbf{G}$.
     \item If $p<(2^{-7/3}-\eps)n^{-1/3}$, then w.h.p.\ there is no tree $T\subseteq \mathbf{G}$ of diameter at most $n^{1/18-\eps}$ such that $T\to \mathbf{G}$.
     \end{enumerate}
\end{theorem}
