\begin{definition}[Simply Connected Complex]
    A simplicial complex $X$ with a connected skeleton $X^{(1)}$ is {\it simply connected}, if every cycle $C\subseteq X^{(1)}$ is contractible in $X$ (or, equivalently, every closed walk is contractible).  
\end{definition}

Let $G$ be a graph. The {\it clique complex} of $G$ is the simplicial complex $X(G)$ that consists of all cliques of $G$. In particular $X^{(2)}(G)$ comprises all triangles, edges, and vertices of $G$.



\subsection{Random graphs}
\label{sc:pre-RG}

In this section, we describe certain properties of $\mathbf{G}\sim G_{n, p}$ that we will use in the proofs. First of all, we recall that degrees of vertices in $G_{n,p}$ have binomial distribution and, thus, they are well-concentrated.

\begin{claim}[\cite{Bollobas}, Chapter 3]
\label{cl:degrees}
If $pn\gg\ln n$, then w.h.p.\ every vertex has degree $(1+o(1))np$ in $\mathbf{G}$.
\end{claim}


The same applies to co-degrees. Indeed, for fixed different vertices $u,v\in[n]$, their common neighbourhood $N(u)\cap N(v)$ has size $\mathrm{Bin}(n-2,p)$. Therefore, due to the Chernoff bound (see, e.g.~\cite[Theorem 2.1]{Janson}), the following is true:
\begin{claim}
\label{cl:co-deg}
If $np^2\gg\ln n$, then % \AC{for every fixed $u,v\in [n]$}
$$
 \mathbb{P}\biggl(\forall u,v\quad |N(u)\cap N(v)|=(1+o(1))np^2\biggr)=1-\exp(-\omega(\ln n)).
$$
\end{claim}

We also recall that, if for some positive constant $\eps$, we have $np\geq 1+\eps$, then w.h.p.\ $\mathbf{G}$ contains a unique component of linear size in $n$. Moreover, the size of this component $\mathbf{g}_n$ has exponential tails.
\begin{theorem}[O'Connell \cite{Oco1998}]\label{th:giant}
Let $C=C(\varepsilon)$ satisfy $C=1-e^{-(1+\varepsilon)C}$ and suppose that $np\geq 1+\eps$. Then, for every $\delta>0$, with probability $1-\exp(-\Omega(n))$, the graph $\mathbf{G}$ contains a unique component of size $\mathbf{g}_n>(1-\delta)Cn$ and all other components have size less than $(1-2\delta)Cn$.
\end{theorem}

Finally, we need the following theorem about the threshold for the existence of extensions in random graphs. A rooted graph $(K,S)$, where $K$ is a graph and $S\subseteq V(K)$ is a proper {\it ordered} subset, is called {\it strictly balanced}, if, for every set $S'\supseteq S$, which is also a proper subset of $V(K)$,
$$
 \frac{|E(K[S'])|-|E(K[S])|}{|S'|-|S|}<
 \frac{|E(K)|-|E(K[S])|}{|V(K)|-|S|}=:\rho(K,S).
$$
The quantity $\rho(K,S)$ is called the {\it density} of the rooted graph $(K,S)$. Rooted graphs $(\tilde K,\tilde S)$ and $(K,S)$ are {\it isomorphic}, if there exists a bijection $\varphi:V(K)\to V(\tilde K)$ with the following properties: 
\begin{itemize}
\item for every $i\in[|S|]$, the bijection $\varphi$ maps the $i$-th vertex from $S$ to the $i$-th vertex from $\tilde S$;
\item for every pair of vertices $u,u'\in V(K)$, such that at least one of them is not in $S$, we have that $\{u,u'\}\in E(K)$ if and only if $\{\varphi(u),\varphi(u')\}\in E(\tilde K)$. %\MZ{I do not like adding a noun expressing the mathematical object $a$ in front of expression like $a\in...$, $a=...$, etc, unless it plays a role of a part of an expression for a quantification. It does not seem grammatically correct, but I am not 100\% sure.}
\end{itemize}
%\AC{Don't we need to map $S$ to $\tilde{S}$?}

\begin{theorem}[Spencer \cite{Spe1990}]
\label{th:extensions}
Let $(K,S)$ be a strictly balanced rooted graph with density $\rho$. There exists a constant $C=C(K,S)>0$ such that, if $p>(\ln n)^{C} n^{-1/\rho}$ and $\mathbf{G}\sim G_{n,p}$, then w.h.p., for every set $\tilde S\subseteq [n]$ of size $|S|$, there exists a subgraph $\tilde K\subseteq \mathbf{G}$ such that the rooted graphs $(\tilde K,\tilde S)$ and $(K,S)$ are isomorphic.
\end{theorem}




