\section{Proof of Lemma~\ref{obs:activation implies simple connectivity} and Theorem~\ref{th:general}, part 2}
\label{sc:general-0_proof}

Let $n^{-1/2}<p<n^{-1/3-\varepsilon}$, $\mathbf{G}\sim G_{n,p}$. The goal of this section is to prove that w.h.p.\ $\wsat(\mathbf{G},K_3) \neq n-1$ or, in other words, that w.h.p.\ there is no spanning tree that activates $\mathbf{G}$. It immediately follows from Theorem~\ref{th:Babson} and the following lemma.

\begin{lemma}
\label{lem: main lemma for 0-statement}
    If there exists a spanning tree $T$ in a graph $G$ such that $T\to G$, then $X^{(2)}(G)$ is simply connected.
\end{lemma}



Let us first give an `informal proof' of Lemma~\ref{lem: main lemma for 0-statement}. For any cycle $C\subseteq G$ consider the process of activation of its edges from $T$. Then, $C$ can be contracted in the following way: at step $i$, we have a closed walk $C_i$ on $G$ (in particular, $C_0=C$). Let $\{x_1,x_2\}\in C_i$ be the last activated edge in $C_i$ (it may have several instances in $C_i$) and let $\{x_1,x_2,x_3\}$ be the triangle that was used to activate $e$. Then replace each $\{x_1,x_2\}$ in $C_i$ with the pair of edges $\{x_1,x_3\},\{x_2,x_3\}$ that was used to activate it. Eventually, we get a walk on $T$ which is clearly contractible.

In order to formalise the above argument, we introduce an algorithm to construct a van Kampen diagram in the specific case when a cycle can be activated from a tree. We call the output of this algorithm the {\it algorithmic van Kampen diagram}. For a bootstrap percolation process $H:=H_0\subset H_1\subset\cdots\subset H_s=:G_0$ on edges of a graph $G$ initiated at a subgraph $H\subseteq G$ and a graph $G_0\subseteq G$ activated in this process, we will write $H\stackrel{G}\to G_0$. For every $i\in[s]$, let $\Delta_i\subseteq H_i$ be a triangle the edge $H_i\setminus H_{i-1}$ belongs to. We will call the tuple $(H;\Delta_1,\ldots,\Delta_s)$ an {\it activation process}.


%Let $H:=H_0\subset H_1\subset\cdots\subset H_s=:G$ be a $K_3$-bootstrap percolation process where each edge $H_i\setminus H_{i-1}$ belongs to a triangle $\Delta_i\subseteq H_i$. and let $G'\subseteq G$. We say that $H$ {\it activates} $G'$ in $G$, write $H\stackrel{G}\to G'$, and call the tuple $(H;\Delta_1,\ldots,\Delta_s)$ an {\it activation process}. For simplicity of presentation we write $H\to G$ instead of $H\stackrel{G}\to G$, when the activated graph $G'$ and the ambient graph $G$ coincide.
%If $H:=H_0\subset H_1\subset\cdots\subset H_m=:G$ is a $K_3$-bootstrap percolation process where each edge $H_i\setminus H_{i-1}$ belongs to a triangle $F_i\subseteq H_i$ and if $G'\subseteq G$, we will say that $H$ {\it activates} $G'$ in $G$, write $H\stackrel{G}\to G'$, and call the tuple $(H;F_1,\ldots,F_s)$ an {\it activation process}. We will simply write $H\to G$ when $H\stackrel{G}\to G$.

%\AC{In the above, do we need $H$ to be spanning subgraph of $G$?}

\begin{definition}[Algorithmic Van Kampen Diagram]
    Suppose that $H\subseteq G$ are graphs and $C\subseteq G$ is a cycle such that $H$ activates $C$ in a process $\mathbf{A}=(H;\Delta_{1},\ldots ,\Delta_{s})$.
    Moreover, for every $1\leq k\leq s$ denote by $e_k=\{x_k^1,x_k^2\}$ the edge that was activated at step $k$, i.e.\ $e_k\coloneqq \Delta_{k}\setminus \left(H\cup \bigcup_{i=1}^{k-1}\Delta_i\right)$. Define the following sequence of labelled complexes iteratively (labels of different vertices are not necessarily different):
    \begin{enumerate}
        \item Start by initialising $D_{s+1}:=C$.
        \item Let $k\geq 1$ and suppose that $D_{k+1}$ is defined. Then, define the complex $D_{k}$ by gluing the triangle $\Delta_{k}=e_k\cup\{y_k\}$, to every edge of $D_{k+1}$ whose vertices are labelled by $x_k^1$ and $x_k^2$. For every attached instance of $\Delta_k$, label its third vertex by $y_k$.
    \end{enumerate}
    We call the resulting labelled simplicial complex $D_1$, the \emph{algorithmic $\mathbf{A}$-diagram} of $C$. Note that $D_1$ may have {\it different} vertices labelled by the same label. We also note that an embedding of $D_1$ into the plane is homotopic to an embedding of an annulus. The labelled version of the boundary of the `hole' contains only edges of $H$. See Figure \ref{Fig-diagrams} that compares different diagrams.
\end{definition}


