d_H\coloneqq |E(H)|-|V(H)|+1
$$ 
the {\it complexity} of $H$ i.e.\ its edit distance from the closest tree. %\AC{How about changing $|E(H)|$ and $|V(H)|$ to $e(H),v(H)$?} \MZ{not sure...}

\begin{lemma}\label{lem: number of edges in minimal process}
    Suppose that $C$ is an $\ell$-cycle and $H{\rightarrow}C$ via a nice $\mathbf{A}=(H;\Delta_1,\ldots,\Delta_s)$. Let $G=K^{(1)}(\mathbf{A})$. Then,   
    \[
        |E(G)|\geq 3|V(H)|+3d_H+\exc({\mathbf{A}})-(3+\ell).
    \]
\end{lemma}

%\AC{The notation for the number of edges is a bit unpleasant. This is the reason why in the previous version I introduced $F\coloneqq K^{(1)}(\mathcal{I})$.} \MZ{It is with a graph in brackets actually --- not in the subscrpit. I think that this is fine if we use a different style $e$ for the Euler's number --- say, $\mathrm{e}$.}

\begin{proof}    
    The proof follows from a double counting argument. We count the set of pairs $(\Delta_i,e)$ such that $e\subset\Delta_i$ and $\Delta_i$ does not activate $e$.

    On the one hand, recalling that $s$ is the number of activation steps in $\mathbf{A}$, the number of such pairs is exactly 
    \[
        2s=2(|E(G)|-|E(H)|)= 2|E(G)|-2|E(H)|.
    \]
    On the other hand, the number of such pairs equals %\MZ{Well, maybe we indeed want to convert all edges $e$ to $f$?} \AC{I'm not sure what is the problem with using $e$ for an edge and $e(G)$ for the number of edges. If I think using $f$ is weird and might confuse people with faces.} \MZ{OK}
    \begin{align*}
        \sum_{e\in G} \con_{\mathbf{A}}(e)&=\sum_{e\in C\setminus H} \exc_{\mathbf{A}}(e)+\sum_{e\not\in C\triangle
        H} (1+\exc_{\mathbf{A}}(e))+\sum_{e\in H\setminus C}(2+ \exc_{\mathbf{A}}(e))\\
        &=|E(G)|-|E(H\cup C)|+|E({C\cap H})|+2|E({H\setminus C})|+\exc({\mathbf{A}})\\
        &=|E({G})|-|E({H\setminus C})|-|E({C})|+|E({C\cap H})|+2|E({H\setminus C})|+\exc({\mathbf{A}})\\
        &=|E(G)|+|E({H})|-\ell+\exc({\mathbf{A}}).
    \end{align*}
%    \AC{You mentioned that the connected assumption is not needed. I do not understand why. The inequality is not an equality if $e(H)<v(H)-1$.}
    Due to Observation~\ref{obs:nice_connected}, the graph $H$ is connected. Thus, $|E(H)|\geq |V(H)|-1$ and hence we conclude that 
    \[
        |E(G)|=3|E(H)|+\exc({\mathbf{A}})-\ell\geq 3|V(H)|+3d_{H}+\exc({\mathbf{A}})-(3+\ell) .\qedhere
    \]
\end{proof}

