\begin{lemma}
    Assume that $H\stackrel{G}{\rightarrow} C$ via a nice process $\mathbf{A}=(H;\Delta_1,\ldots ,\Delta_s)$ where $C$ is a cycle.
    Then the internal boundary of the activation diagram has $2|E(H)|+\exc({\mathbf{A}})=2(|V(H)|-1)+2d_{H}+\exc({\mathbf{A}})$ vertices\footnote{Vertices with equal labels are considered as different vertices here.}.
\label{lemma:internal-length}
\end{lemma}


\begin{proof}
First, we note that 
\begin{align*}
     2|E(H)|+\exc({\mathbf{A}})%&=\sum_{e\in E(K(\mathbf{A}))}(\exc_{\mathbf{A}}(e)+2\cdot \mathbbm{1}_{e\in E(H)})\\
     &= \sum_{e\in E(H)}(\exc_{\mathbf{A}}(e)+2)+\sum_{e\in E(K(\mathbf{A}))\setminus E(H)}\exc_{\mathbf{A}}(e)\\
     &=\sum_{e\in E(H)\setminus E(C)}\con_{\mathbf{A}}(e)+\sum_{e\in E(H)\cap E(C)}(\con_{\mathbf{A}}(e)+1)+\sum_{e\in E(K(\mathbf{A}))\setminus E(H)}\exc_{\mathbf{A}}(e).
\end{align*}

Hence, it is enough to prove the following:
\begin{enumerate}[label=\textbf{(C\arabic*)}]
    \item \label{item: case 1} Every $e\in E(H)$ appears exactly $\con_{\mathbf{A}}(e)+\mathbbm{1}_{e\in E(C)}$ times along the internal boundary.
    \item \label{item: case 2} Every $e\in E(K(\mathbf{A}))\setminus E(H)$ appears exactly $\exc_{\mathbf{A}}(e)$ times along the internal boundary.
\end{enumerate}

Recall that $\Delta_i$ {\it does not activate} $e\in E(K(\mathbf{A}))\cap \Delta_i$ if $e\in E(H)\cup \Delta_1 \cup \cdots \cup \Delta_{i-1}$. Otherwise, we say that $\Delta_i$ {\it activates} $e$. With this terminology, for every $e\in E(K(\mathbf{A}))\setminus E(C)$, the number of edges labelled as $e$ in the activation diagram $D_1$ is the number of triangles $\Delta_i$ containing $e$ but not activating $e$. This is exactly $\con_\mathbf{A}(e)$.
Furthermore, as each edge $e\in E(C)$ is presented in $D_{s+1}$, the number of edges labelled as $e$ in $D_1$ is $\con_{\mathbf{A}}(e)+1$. We further prove separately \ref{item: case 1} and \ref{item: case 2}.

\paragraph{Proof of \ref{item: case 1}:}
Let $e\in E(H)$. As mentioned, the number of edges labelled as $e$ in $D_1$ is $\con_\mathbf{A}(e)+\mathbbm{1}_{e\in E(C)}$.
Since $e\in E(H)$, its contribution in $\mathbf{A}$ equals to the number of triangles $\Delta_i$ containing $e$.
Hence, to conclude the proof, it is enough to show that every instance of $e$ in $D_1$ belongs to the internal boundary. 


To this end, note that, in the process generating $D_1$, once an edge is added, it becomes an edge of the internal boundary.
Thus, for an edge not to be on the internal boundary, there must be some triangle $\Delta_i$ activating it. Since $e\in E(H)$, no triangle $\Delta_i$ activates $e$, and thus every copy of $e$ lies at the internal boundary.



\paragraph{Proof of \ref{item: case 2}:}
Let $e\in E(K(\mathbf{A}))\setminus E(H)$. Recalling that $e$ appears $\con_{\mathbf{A}}(e)+\mathbbm{1}_{e\in E(C)}$ times in $D_1$ and that $\con_{\mathbf{A}}(e)=\exc_{\mathbf{A}}(e)+\mathbbm{1}_{e\not\in E(C)}$, we find that $e$ appears $\exc_{\mathbf{A}}(e)+\mathbbm{1}_{e\not\in E(C)}+\mathbbm{1}_{e\in E(C)}=\exc_{\mathbf{A}}(e)+1$ times in $D_1$. Hence, it suffices to show that, outside of the internal boundary, there is a single edge labelled as $e$.


Indeed, as before, in the process generating $D_1$, once an edge is added, it becomes an edge of the internal boundary. As $e\in E(K(\mathbf{A}))\setminus E(H)$ there is a triangle $\Delta_i$ that activates $e$ --- clearly, this triangle is unique. For any $j>i$, all edges labelled $e$ in $D_j$ also belong to the internal boundary of $D_j$. As $e$ is activated through $\Delta_i$, a single edge labelled $e$ belonging to the internal boundary of $D_{i+1}$, becomes a non-internal boundary edge in $D_{i}$. 
%In $D_i$ the triangle $\Delta_i$ is attached. As $e$ is activated through $\Delta_i$, a single edge labelled $e$ belonging to the internal boundary of $D_{i+1}$, becomes a non-internal boundary edge in $D_{i}$.  
 Further, for all $j<i$ we have $e\not \in \Delta_j$. Thus, the number of edges labelled $e$ in the internal boundary of $D_j$ equals the number of edges labelled $e$ in $D_i$.
In particular, the above holds for $j=1$, completing the proof. 
\end{proof}

