There exists $\mathbf{A}$ a nice activation process of $C$ in $G_{n,p}$ starting from $H$ with 
\[
	 v(H)< K \ell\ln n\quad \text{and}\quad 2d_\mathbf{A}+\exc(\mathbf{A})<  36K \ell \ln(\ell \ln n).
\]

We now split into two cases, in each showing, respectively, that $\E[X_1]=o(\E[Y])$ and $\E[X_2]\leq n^{(2/3-\eps-\eps_0)\ell}=o((n-\ell)^{\ell}p^{\ell})=o(\E[Y])$ for some small enough $\eps_0>0$. This will imply that $\E[X]=o(\E[Y])$, as required.
Indeed, let us now split into the above cases.



\paragraph{Case 1:} Bounding $\E[X_1]$. \\
\noindent Let us start by noting that if $\mathbf{A}=(H;\Delta_1,\ldots ,\Delta_s)$ is an activation process of an $\ell$-cycle in a graph $G$, then $K^{(1)}(\mathbf{A})\subseteq G$. 
If further $\mathbf{A}$ is a nice activation process, with $v(K(\mathbf{A}))=v$ and with $w=2d_H+\exc({\mathbf{A}})=\omega(\ell)$, then by our assumption, and by lemma \ref{lem: number of edges in minimal process}, for large $n$ we have 
    \[
        e({K(\mathbf{A})})\geq 3v+w-(3+\ell)\geq 3v+w/2\geq 3v+ 18K \ell \ln(\ell \ln n).
    \]
Hence, to conclude the proof of this case, it is enough to show that with probability at most $o(p^{\ell})$, we have $Z(k_1,k_2;m)>0$, for $k_1=\ell,k_2=K\ell\ln n$, and $m= 18K \ell \ln(\ell \ln n)$. By applying Lemma \ref{lem: no too dense graphs} for some small enough $\delta>0$, we obtain the required,
\[
	\mathbb{P}(Z(k_1,k_2;m)>0)\leq n ^{- \delta K \ell \ln(\ell \ln n)} = o(p^{\ell}).
\]


\paragraph{Case 2:} Bounding $\E[X_2]$.\\
\noindent  
For any labelled $\ell$-cycle $C$, denote by $Z(C)$ the indicator for the following event:
The complex $X_2(G_{n,p})$ contains a diagram $D\in P_{v,w}$ such that both $\ell\leq v\leq K\ell\ln n$ and $w\leq  36K \ell \ln(\ell \ln n)$, and moreover, the external boundary of $D$ is $C$.

Recall that an activation process of an $\ell$-cycle $\mathbf{A}=(H;\Delta_1,\ldots ,\Delta_s)$, induces an activation diagram.
If further $\mathbf{A}$ is a nice process, with $v(K(\mathbf{A}))=v$, and with $2d_H+\exc({\mathbf{A}})=w$, then $\mathbf{A}$ actually induces an activation diagram in $P_{v,w}$.   
Thus, 
\[
	\E[X_2]\leq \sum_{C\cong C_{\ell}}\E[Z(C)] = \sum_{v=\ell}^{K\ell \ln n} \ \sum_{w=0}^{ 36K \ell \ln(\ell \ln n)}\E[Z_{v,w}^{\ell}]. 
\]
Lemma \ref{lem: expectation of the number of activations} and the bounds $\ell \leq n^{\eps}$ and $\gamma c^3<1$ imply the following for any $\eps_1,\eps_2>0$ and large enough $n$,
    \begin{align*}
         \sum_{v=\ell}^{K\ell\ln n} \ \sum_{w=0}^{ 36K \ell \ln(\ell \ln n)} \E[Z_{v,w}^{\ell}]&\leq \sum_{v=\ell}^{K\ell\ln n} \ \sum_{w =0}^{36K \ell \ln(\ell \ln n)}  (2v)^{5w} w^w  (cn^{-\frac{1}{3}})^{w-3-\ell}(\gamma c^3)^{v/2}\\
         &\leq \sum_{v=\ell}^{K\ell\ln n} \ \sum_{w =0}^{36K\ell \ln(\ell \ln n)} (cn^{-\frac{1}{3}})^{-3-\ell}  (\gamma c^3)^{v/2}\\
        &\leq n^{1+2\eps+\eps_1+(\frac{1}{3}+\eps_2)\ell},
    \end{align*}
    where the second inequality holds as $cv^5w\leq n^{6\eps+o(1)}$.
Our assumed upper bounds on $\eps,\eps'$ and lower bound on $\ell$, imply that for $\eps_0,\eps_1,\eps_2>0$ small enough so that 
\[
     \eps_0+\eps_2<1/3-\eps-\eps'\quad \text{and} \quad 4\eps_0+\eps_1+4\eps_2< 1/3-6\eps-4\eps',
\]
we have $1+2\eps+\eps_1+(\frac{1}{3}+\eps_2)\ell < (2/3-\eps-\eps'-\eps_0)\ell$. This then implies the required inequality for sufficiently large $n$:
\[
		\E[X_2]\leq \sum_{v=\ell}^{K\ell\ln n} \ \sum_{w=0}^{36K\ell\ln(\ell\ln n)} \E[Z_{v,w}^{\ell}] \leq n^{1+2\eps+\eps_1+(\frac{1}{3}+\eps_2)\ell}=o(n^{(2/3-\eps-\eps'-\eps_0)\ell}).\qedhere
\]
\end{proof}


