\begin{equation}\label{eq: union of activations}
	\{\Delta_{i_j}:j=1,\ldots,t\}=\{\Delta_i^{(1)}:i=1,\ldots ,s_1\}\cup \{\Delta_i^{(2)}:i=1,\ldots ,s_2\}.
\end{equation}

For every $k\in[t]$, we denote by $e_k$ the edge activated by $\Delta_{i_k}$ in $\mathbf{A}$. In a similar way, for every $i\in[s_1]$ and $j\in[s_2]$, we denote by $e^{(1)}_i$ and $e^{(2)}_j$ the edges activated by $\Delta^{(1)}_i$ in $\mathbf{A}_1$ and $\Delta^{(2)}_j$ in $\mathbf{A}_2$, respectively. 
