We then conclude that $C^*$ is an $(\ell+1)$-cycle.












%Next, by a similar argument to the proof of Claim \ref{claim: last triangle is not boundary triangle}, we find the length of $C$ is maximal.

\begin{claim}
    $\ell=100d$.
 \label{cl:ell=100d}
\end{claim}

\begin{proof}
Assume towards contradiction that $\ell<100d$. Claim \ref{claim: last triangle is not boundary triangle} implies that $C^*$ is a cycle of length $\ell+1\leq 100d$. It can be activated by the subprocess of $\mathbf{A}$ without the last triangle $\Delta_s$. Recalling that $\mathbf{A}$ starts from $T$ and, therefore, the considered subprocess as well, by the minimality of $s(C)$, we get that $C^*\in\mathcal{X}$. In particular, $C^*$ admits a nice activation subprocess of $\mathbf{A}^*\subseteq\mathbf{T}$ with less than $K_1(\ell+1)\ln n$ vertices, and such that $C^*$ is contractible in $K(\mathbf{A}^*)$. 

 As in the proof of Claim \ref{claim: last triangle is not boundary triangle}, we note that $\mathbf{A}^{**}\coloneqq (\{e',e''\};\Delta_s)$ is a nice activation process of $\Delta_s$ and $\Delta_s$ is contractible in $K(\mathbf{A}^{**})$. We also note that $\mathbf{A}^{**}$ is a subprocess of $\mathbf{T}$ since $\Delta_s$ participates in $\mathbf{T}$, where it activates the same edge as in $\mathbf{A}^{**}$. We then apply Lemma~\ref{lm:union_contractible} and get that the process $\mathbf{A}^{\cup}:=\mathbf{A}^*\cup\mathbf{A}^{**}$ activates $C$ and $C$ is contractible in $K(\mathbf{A}^{\cup})$. Therefore, by Lemma \ref{lemma: activations contain good activations} there is a nice activation subprocess of $\mathbf{A}^{\cup}$ that activates $C$ and such that $C$ is contractible in the respective activation complex. By Observation~\ref{obs: union of complexes}, $K(\mathbf{A}^{\cup})$ has at most $K_1(\ell+1)\ln n <K_2\ell \ln n$ vertices --- a contradiction to the assumption that $C\notin\mathcal{X}$.
\end{proof}





We are now ready to complete the proof of Proposition \ref{prop: local to global}. Below we describe the last step of the proof: roughly speaking, we show that if an $\ell$-cycle is activated via a process involving more than $K_2\ell\ln n$ triangles, then there is also an $\ell'$-cycle whose activation process essentially involves `moderately' many triangles, that is some number which is between $K_1\ell'\ln n$ and $K_2\ell'\ln n$. This would contradict \ref{local1} and complete the proof of Theorem~\ref{th:shallow} due to the observation that $\mathcal{X}\neq\emptyset$. 

Consider two antipodal vertices $x,y$ of $C^*$, that is $\dist_{C^*}(x,y)=50d$. Let  $P$ the unique path between $x$ and $y$ in $T$. Recall that $T$ has diameter at most $d$, and therefore $|E(P)|\leq d$. 
\begin{claim}\label{claim: creating two cycles}
    There is a path $P'\subseteq P$ such that
    \[
        V(P')\cap V(C^*)=\{a,b\} \quad \text{and}\quad\dist_{C^*}(a,b)>\dist_{P}(a,b)=|E(P')|.
    \]
\end{claim}

\begin{proof}
    Let $P=(x=v_1v_2\ldots v_r=y)$, and recall that $r\leq d+1$. Let $1=i_1<\ldots<i_k=r$ be indices of all the vertices $v_{i_1},\ldots,v_{i_k}$ of the path $P$ that also belong to the cycle $C^*$. Then, for all $1\leq j\leq k-1$ we let $P_{j}\subseteq P$ be the induced subpath between $v_{i_j}$ and $v_{i_{j+1}}$. Let us show that at least one of these $P_j$ satisfies the assertion of the claim. Indeed, otherwise, for all $1\leq j\leq k-1$ we have $\dist_{C^*}(v_{i_j},v_{i_{j+1}})\leq \dist_{P}(v_{i_j},v_{i_{j+1}})$, which by the triangular inequality implies
    \[
        50d=\dist_{C^*}(x,y)\leq \sum_{j=1}^{k-1}\dist_{C^*}(v_{i_j},v_{i_{j+1}})\leq \sum_{j=1}^{k-1}\dist_{P}(v_{i_j},v_{i_{j+1}})=\dist_P(x,y)=r-1 \leq d
    \]
--- a contradiction.
\end{proof}

Fix $P'$ as in Claim \ref{claim: creating two cycles}, and set $V(P')\cap V(C^*)=\{a,b\}$.
Let $P_1,P_2$ be the two distinct paths starting from $a$ and ending at $b$ in $C^*$. The path $P'$ splits $C^*$ into two cycles $C_1$ and $C_2$, where, for $i\in\{1,2\}$, $C_i=P_i\cup P'$ --- see Figure \ref{Fig-local-to-global}. Without loss of generality, assume that $|E(P_1)|\leq |E(P_2)|$. By Claim \ref{claim: creating two cycles}, we also have $|E(P')|< |E(P_1)|\leq |E(P_2)|$. In particular, it implies that both $C_i$ are actually cycles, i.e. $|E(C_2)|\geq |E(C_1)|\geq 3$ . Moreover, recalling that $|E(C^*)|=\ell+1=100d+1$ due to Claim~\ref{cl:ell=100d},  we get that, for $i\in\{1,2\}$,
$$
   |E(C_i)|=|E(P_i)|+|E(P')| \leq |E(P_i)|+|E(P_1)|-1\leq |E(P_2)|+|E(P_1)|-1=|E(C^*)|-1=100d.
$$
%and also
%\[
%  e_{C_i} \geq \dist_C(s,t)+\dist_{P'}(s,t) \geq 2\dist_{P}(s,t)+1\geq 3.
%\]
We conclude that $3\leq |E(C_i)|\leq 100d$ for both $i=1$ and $i=2$.

Both $C_1,C_2$ are activated from the subprocess of $\mathbf{A}$ without the last triangle $\Delta_s$, since this subprocess starts from $T$ and $P'\subseteq T$.
By the minimality of $s(C)$, we get that $C_1,C_2\in\mathcal{X}$. Hence, both cycles $C_1,C_2$ admit nice activation subprocesses $\mathbf{A}_1,\mathbf{A}_2\subseteq\mathbf{T}$ with at most $K_1\ln n$ vertices, and such that $C_1,C_2$ are contractible in $K(\mathbf{A}_1),K(\mathbf{A}_2)$, respectively. In the same way as in the proofs of Claims~\ref{claim: last triangle is not boundary triangle},~\ref{cl:ell=100d}, we now observe that $\mathbf{A}_3\coloneqq (\{e',e''\};\Delta_s)\subseteq\mathbf{T}$ is a nice activation process of $\Delta_s$ and $\Delta_s$ is contractible in $K(\mathbf{A}_3)$. Two applications of  Lemma~\ref{lm:union_contractible} imply that the process $\mathbf{A}^{\cup}:=\mathbf{A}_1\cup\mathbf{A}_2\cup\mathbf{A}_3$ activates $C$ and $C$ is contractible in $K(\mathbf{A}^{\cup})$. Therefore, by Lemma \ref{lemma: activations contain good activations} there is a nice activation subprocess of $\mathbf{A}^{\cup}$ that activates $C$ and such that $C$ is contractible in its activation complex. By Observation~\ref{obs: union of complexes}, $|K^{(0)}(\mathbf{A}^{\cup})|\leq 2K_1\ell\ln n<K_2\ell \ln n$. This contradicts the assumption that $C\notin\mathcal{X}$ and concludes the proof of Proposition \ref{prop: local to global}.\qedhere










