\subsection{A-stable and L-stable of (\ref{eq5})}
In this subsection, we rigorously establish that the one-step scheme \eqref{eq5} achieves both A-stability and L-stability under the parametric regime where $\beta_1$ and $\beta_2$ satisfy the stipulated algebraic constraints.
\begin{theorem}\label{th3}
If there exists $\beta_1$ and $\beta_2$ to satisfy
\begin{equation}
0\leq\beta_1+\beta_2-1\leq2\beta_1\beta_2,
\end{equation}
then the following inequality always holds true for any given negative real number $z\leq0$:
\begin{equation}
\label{teq1}
\left\vert\frac{g_1(z)}{g_2(z)}\right\vert\leq1.
\end{equation}
\end{theorem}

\begin{proof}
We first demonstrate that the denominator $g_2(z)$ remains strictly non-zero throughout the parameter domain, achieved via proof by contradiction.
Assuming that there exists $z_0<0$ to satisfy $g_2(z_0)=\beta_1\beta_2z_0^2-(\beta_1+\beta_2)z_0+2=0$, then invoking the quadratic formula, we obtain that the roots $z_0$ can be explicitly given by the following expression:
\begin{equation}
z_0=\frac{\beta_1+\beta_2\pm\sqrt{\beta_1^2+\beta_2^2-6\beta_1\beta_2}}{2\beta_1\beta_2}.
\end{equation}

Considering that $\beta_1\beta_2\geq0$ and $\beta_1+\beta_2\geq1$, we have
\begin{equation}
(\beta_1+\beta_2)^2-(\beta_1^2+\beta_2^2-6\beta_1\beta_2)=8\beta_1\beta_2\geq0,
\end{equation}
which means $\beta_1+\beta_2\pm\sqrt{\beta_1^2+\beta_2^2-6\beta_1\beta_2}\geq0$. Then we have $z_0\geq0$ which contradicts the premise $z_0<0$, hence $g_2(z)\neq0$.


Subsequently, we prove inequality \eqref{teq1}. Considering that $g_2(z)\neq0$, then the inequality \eqref{teq1} is equivalent to 
\begin{equation}
\label{teq2}
g_1(z)^2-g_2(z)^2\leq0
\end{equation} 

For notational clarity, we define $h(z)=g_1(z)^2-g_2(z)^2,\;\alpha_1=\beta_1+\beta_2-2\beta_1\beta_2-1$ and $\alpha_2=\beta_1+\beta_2-1$. 
Then $h(z)$ can be derive
\begin{equation}\label{eq14}
\begin{aligned}
h(z)=&\alpha_1\alpha_2z^4+2(\alpha_2^2-\alpha_1)z^3-8\alpha_2z^2+8z \\
=&z(\alpha_2z-2)(\alpha_1z^2+2\alpha_2z-4).
\end{aligned}
\end{equation}

We now just need to demonstrate that 
\begin{equation}
\begin{aligned}
h(z)\leq0,\quad\forall z\leq0,\quad\forall\alpha_1\leq0,\quad\forall\alpha_2\geq0.
\end{aligned}
\end{equation}
Firstly, if $\alpha_1=0$, the expression of $h(z)$ can be reducible to:
\begin{equation}
h(z)=2z(\alpha_2z-2)^2.
\end{equation}
It is now evident that we readily obtain $h(z)\leq0$, $\forall z\leq0$. Secondly, if $\alpha_1<0$ and $\alpha_2=0$, $h(z)$ will be simplified as the following
\begin{equation}
h(z)=-2z(\alpha_1z^2-4).
\end{equation}
It is obviously easy to obtain $h(z)\leq0$, $\forall z\leq0$ and $\forall \alpha_1<0$. Thirdly, if $\alpha_1<0,\;\alpha_2>0$, 
the product of the first two terms of $h(z)$ in \eqref{eq14} satisfies $z(\alpha_2z-2)\geq0$. For the third term of $h(z)$, we have $$(\alpha_1z^2+2\alpha_2z-4)|_z=2\alpha_1z+2\alpha_2\geq0,\quad\forall z\leq0,$$ 
which means $\alpha_1z^2+2\alpha_2z-4$ is increasing for $z\in(-\infty,0]$. Noting that $\alpha_1z^2+2\alpha_2z-4|_{z=0}=-4<0$, we have $\alpha_1z^2+2\alpha_2z-4<0,\ \forall z\leq0$. In summary, we eventually reach $h(z)\leq0$, $\forall z\leq0$.
\end{proof}

\begin{theorem}
For all complex numbers $Re(z)\leq0$, if their exists $\beta_1$ and $\beta_2$ to satisfy
\begin{equation}
\label{teq3}
0\leq\beta_1+\beta_2-1\leq2\beta_1\beta_2,
\end{equation}
then the following inequality always holds true
\begin{equation}
\label{teq4}
\left\vert\frac{g_1(z)}{g_2(z)}\right\vert\leq1,
\end{equation}
which indicates that the new one-step schemes (\ref{eq5}) are A-stable.
\end{theorem}

\begin{proof}
From Theorem \ref{th3}, we are easy to obtain $g_2(z)\neq0$, $\forall Re(z)\leq0$. Then the inequality \eqref{teq4} is equivalent with the following
\begin{equation}
\label{teq5}
h(z)=g_1(z)g_1(\overline z)-g_2(z)g_2(\overline z)\leq0, \quad\forall Re(z)\leq0.
\end{equation}

Define $z=re^{i\theta}$, where $r\geq0$ and $\theta\in[\frac{\pi}{2},\frac{3\pi}{2}]$. We can derive
\begin{equation}\label{eq15}
\begin{aligned}
h(z)=&\alpha_1\alpha_2r^4+2(\alpha_2^2-\alpha_1)r^3\cos\theta-4\alpha_2r^2(1+\cos2\theta)+8r\cos\theta \\
=&\alpha_1\alpha_2r^4(\cos^2\theta+\sin^2\theta)^2+2(\alpha_2^2-\alpha_1)r^3\cos\theta(\cos^2\theta+\sin^2\theta) \\
&-8\alpha_2r^2\cos^2\theta+8r\cos\theta \\
=&\alpha_1\alpha_2(r\cos\theta)^4+2(\alpha_2^2-\alpha_1)(r\cos\theta)^3-8\alpha_2(r\cos\theta)^2+8(r\cos\theta) \\
&+\alpha_1\alpha_2(2\cos^2\theta\sin^2\theta+\sin^4\theta)r^4+2(\alpha_2^2-\alpha_1)\cos\theta\sin^2\theta r^3
\end{aligned}
\end{equation}

Based on the conclusion of Theorem \ref{th3} combined with $Re(z)=r\cos\theta\leq0$, we obtain that the sum of the first four terms in the expression of $h(z)$ in \eqref{eq15} is negative, i.e.,
\begin{equation}
\alpha_1\alpha_2(r\cos\theta)^4+2(\alpha_2^2-\alpha_1)(r\cos\theta)^3-8\alpha_2(r\cos\theta)^2+8(r\cos\theta)\leq0.
\end{equation}

Given $r\geq0$, $\alpha_1\leq0,\;\alpha_2\geq0$ and $\theta\in[\frac{\pi}{2},\frac{3\pi}{2}]$, it is obviously to obtain the fifth and sixth terms of $h(z)$ in \eqref{eq15} are both negative:
\begin{equation}
\begin{aligned}
\alpha_1\alpha_2(2\cos^2\theta\sin^2\theta+\sin^4\theta)r^4&\leq0, \\
2(\alpha_2^2-\alpha_1)\cos\theta\sin^2\theta r^3&\leq0.
\end{aligned}
\end{equation}

Therefore, we conclude $h(z)\le0$, $\forall Re(z)\leq0$.
\end{proof}
\begin{remark}
The existence condition of $\beta_1$ and $\beta_2$ in \eqref{teq3} to keep the proposed one-step schemes \eqref{eq5} A-stable is fairly relaxed. For example, if we fix $\beta_1=1$, then the inequality \eqref{teq3} will become:
\begin{equation}
0\leq\beta_2\leq2\beta_2,
\end{equation}
which implies that it holds for all $\beta_2\geq0$.
\end{remark}

Next, we will determine the conditions on $\beta_1$ and $\beta_2$ that guarantee L-stability of the proposed one-step schemes \eqref{eq5}.
\begin{theorem}
If $\beta_1$ and $\beta_2$ satisfy the following
\begin{equation}
\label{teq6}
\beta_1+\beta_2-1>0,\;(\beta_1-1)(\beta_2-1)=0,
\end{equation}
then $\forall z\leq0$, we obtain
\begin{equation}
\label{teq7}
\lim_{z\to-\infty}\frac{g_1(z)}{g_2(z)}=0.
\end{equation}
which indicates that the new one-step schemes \eqref{eq5} are L-stable.
\end{theorem}

\begin{proof}
Noting that 
$$
(\beta_1-1)(\beta_2-1)=\beta_1\beta_2-(\beta_1+\beta_2-1)=0,
$$
which means $\beta_1\beta_2>0$ and $2\beta_1\beta_2\geq\beta_1+\beta_2-1>0$, then we obtain the new schemes (\ref{eq5}) are also A-stable under the condition of \eqref{teq6}. Meanwhile, $g_1(z)$ will be simplified as $g_1(z)=(2-\beta_1-\beta_2)z+2$ which leads to the following
\begin{equation}
\lim_{z\to-\infty}\frac{g_1(z)}{g_2(z)}=\lim_{z\to-\infty}\frac{(2-\beta_1-\beta_2)z+2}{\beta_1\beta_2z^2-(\beta_1+\beta_2)z+2}=0.
\end{equation}
Then we obtain the new one-step schemes (\ref{eq5}) are L-stable which completes the proof.
\end{proof}
\begin{remark}
The condition \eqref{teq6} for achieving L-stable of the schemes \eqref{eq5} can be equivalently expressed as the following inequality:
\begin{equation*}
\beta_1=1,~\beta_2>0,\quad or\quad \beta_2=1,~\beta_1>0, 
\end{equation*}
which implies that if either $\beta_1$ or $\beta_2$ takes the value 1, it suffices for the other ($\beta_2$ or $\beta_1$) to be positive.
\end{remark}

