\title[Strong time-periodic solutions to a multilayered FSI problem]{Strong time-periodic solutions to a multilayered fluid-structure interaction problem}


\author{Felix Brandt}
\address{Department of Mathematics, University of California at Berkeley, Berkeley, 94720, CA, USA.}
\email{fbrandt@berkeley.edu}
\author{Claudiu M\^{i}ndril\u{a}}
