\begin{algorithm}
\caption{Compute $w_A(T)$ Bound for Hybrid Systems}
\begin{algorithmic}[1]
\State Input: Operators $A, X, Y$
\State Compute $Y^{\sharp_A} \gets A^{-1}Y^*A$
