\subsection{Mixed-state gapped phases with $\bbZ_2^{(1)}\times \bbZ_2^{(2)}$ symmetry}
In this section, we present the mixed-state phases with \(\mathbb{Z}_2^{(1)} \times \mathbb{Z}_2^{(2)}\) symmetry. We denote by \(\mathbb{Z}_2^{(1,2)}\) the \(\mathbb{Z}_2\) subgroup generated by the product of the generators of \(\mathbb{Z}_2^{(1)}\) and \(\mathbb{Z}_2^{(2)}\).
The phases are obtained by calculating the condensable algebras of the open SymTFT $\CZ\big({\rm Vec}_{\bbZ_2^{(1)}\times \bbZ_2^{(2)}\times \overline{\bbZ_2^{(1)}\times \bbZ_2^{(2)}}}\Big)$, whose $16\times 16$ simple anyons are labeled by
\be \big\{ e_1^{a_1} m_1^{a_2} e_2^{a_3} m_2^{a_4} \bar{e}_1^{a_5} \bar{m}_1^{a_6} \bar{e}_2^{a_7} \bar{m}_2^{a_8}  \big\} \ , \ a_i\in\bbZ_2   \ee
There are in total $16$ phases with 10 inherent mixed-state phases:
\begin{enumerate}
    \item The Lagrangian algebra
    \[\CL_S = \expval{ e_1,e_2,\bar{e}_1,\bar{e}_2 }    \]
    is assumed to be the topological boundary condition. Choosing it to be also the physical boundary condition would yield the pure-state phase of complete $\bbZ_2^{(1)}\times \bbZ_2^{(2)}$ SSB;
    \item The pure-state phase of $\bbZ_2^{(1)}$ SSB, $\bbZ_2^{(2)}$ SSB, and $\bbZ_2^{(1,2)}$ SSB are realized by condensable algebras on the physical boundary
    \begin{equation*}\ba
    \CA_1 &= \expval{e_1,m_2,\bar{e}_1,\bar{m}_2}  \\
    \CA_2 &= \expval{e_2,m_1,\bar{e}_2,\bar{m}_1} \\
    \CA_3 &= \expval{e_1e_2,m_1m_2,\bar{e}_1\bar{e}_2,\bar{m}_1\bar{m}_2} \ , \ea
    \end{equation*} 
    respectively.
    \item The pure-state phase of trivial symmetric state is given by all $m$-anyon condensation on the physical boundary,
    \[\CA_4 = \expval{m_1,m_2,\bar{m}_1,\bar{m}_2} \ . \]
    \item The pure-state phase of cluster state SPT is given by the physical boundary condition
    \[ \CA_5 = \expval{e_1m_2, e_2m_1, \bar{e}_1\bar{m}_2,\bar{e}_2\bar{m}_1} \ ; \]
    \item The SWSSB phase with symmetry broken down to $\bbZ_2^{(1),w}\times \bbZ_2^{(2),w}$ symmetry is given by condensing all the diagonal anyons,
    \[\CM_1 = \expval{e_1 \bar{e}_1, m_1 \bar{m}_1, e_2 \bar{e}_2, m_2\bar{m}_2} \ ; \]
    \item The SWSSB phase with symmetry broken down to $\bbZ_2^{(1),w}$ symmetry, to $\bbZ_2^{(2),w}$ symmetry, and to $\bbZ_2^{(1,2)),w}$ symmetry are given by anyon condensation
    \be\ba \CM_2 &= \expval{e_2,\bar{e}_2,e_1 \bar{e}_1, m_1\bar{m}_1,} \\
     \CM_3 &= \expval{e_1,\bar{e}_1,e_2 \bar{e}_2, m_2\bar{m}_2,} 
 \\
   \CM_4 &= \expval{ e_1e_2,\bar{e}_1\bar{e}_2,e_1\bar{e}_1,e_2\bar{e}_2,m_1m_2\bar{m}_1\bar{m}_2 } \ , \ea\ee
    respectively.
    \item The SWSSB phase with symmetry broken down to $\bbZ_2^{(1),s}\times \bbZ_2^{(2),w}$, the SWSSB phase with $\bbZ_2^{(2),s}\times \bbZ_2^{(1),w}$ symmetry, and the SWSSB phase with$\bbZ_2^{(1,2),w}\times \bbZ_2^{(1),s}$ symmetry respectively,
    \be\ba \CM_5 &= \expval{m_1,\bar{m}_1,e_2\bar{e}_2,m_2 \bar{m}_2} \\
     \CM_6 &= \expval{m_2,\bar{m}_2,e_1\bar{e}_1,m_1 \bar{m}_1} \ . \\
     \CM_7 &= \expval{m_1m_2,m_1\bar{m}_2,\bar{m}_1m_2,e_1e_2\bar{e}_1\bar{e}_2} \ ;\ea\ee
    \item The SWSSB phase with $\bbZ_2^{(1),s}\times \bbZ_2^{(2),w}$ symmetry and ASPT, and its $\bbZ_2^{(2),s}\times \bbZ_2^{(1),w}$ symmetric ASPT, $\bbZ_2^{(1,2),w}\times \bbZ_2^{(1),s}$ symmetric ASPT counterparts are given by
    \be\ba \CM_8 = &\expval{ e_2m_1,\bar{e}_2\bar{m}_1,e_2\bar{e}_2,m_1\bar{m}_1,e_1\bar{e}_1m_2\bar{m}_2}  \\
     \CM_9 = &\expval{ e_1m_2,\bar{e}_1\bar{m}_2,e_1\bar{e}_1,m_2\bar{m}_2,e_2\bar{e}_2m_1\bar{m}_1} \\
     \CM_{10} = &\langle e_1e_2m_1m_2,\bar{e}_1\bar{e}_2\bar{m}_1\bar{m}_2,e_1e_2\bar{e}_1\bar{e}_2,\\ &e_2\bar{e}_2 m_2\bar{m}_2,\bar{e}_1\bar{m}_1e_2m_2,e_1m_1\bar{e}_2\bar{m}_2 \rangle   
     \ea\ee
    respectively.

\end{enumerate}

