\subsection{Proof of Corollaries \ref{Corollary: Spectral Geometry} and \ref{Corollary: Variance}}
\label{Section: Proof of Spectral Geometry}

%

We first consider Corollary \ref{Corollary: Spectral Geometry}-(1).
By \eqref{Equation: Main Asymptotic 1} and \eqref{Equation: Smooth Heat Trace},
\[\mbf E\big[2\pi t_n\msf T_\ka(t_n)\big]=\msf{A}(D)+o(1)
\qquad\text{and}\qquad
\mbf{Var}\big[2\pi t_n\msf T_\ka(t_n)\big]=O(t_n^2)\]
as $n\to\infty$. Thus, by a combination of the Borel-Cantelli lemma
and Chebyshev's inequality, it suffices to show that there exists some $\eta\in(0,2)$ such that
\[\mbf P\left[\Big|\mbf E\big[2\pi t_n\msf T_\ka(t_n)-\mbf E\big[2\pi t_n\msf T_\ka(t_n)\big]\Big|>t_n^{\eta/2}\right]=O(t_n^{2-\eta})\]
is summable in $n$. If $t_n\leq cn^{-1/2-\eps}$ for some $c,\eps>0$, then we get that
\[\sum_{n=1}^\infty t_n^{2-\eta}\leq c\sum_{n=1}^\infty n^{(-1/2-\eps)(2-\eta)}
=c\sum_{n=1}^\infty n^{-1-2\eps+\eta(1/2+\eps)}.\]
For every $\eps>0$, we can always find $\eta$ small enough so that
$-2\eps+\eta(1/2+\eps)<0$, thus making the above summable.

%

Corollaries \ref{Corollary: Spectral Geometry}-(2) and \ref{Corollary: Variance}
are proved similarly:
By \eqref{Equation: Main Asymptotic 1} and \eqref{Equation: Smooth Heat Trace},
\[\mbf E\left[4\sqrt{2\pi t_n}\left(\tfrac{\msf{A}(D)}{2\pi}t_n^{-1}-\msf T_\ka(t_n)\right)\right]=\msf{L}(\partial D)+o(1),\]
\[\mbf{Var}\left[4\sqrt{2\pi t_n}\left(\tfrac{\msf{A}(D)}{2\pi}t_n^{-1}-\msf T_\ka(t_n)\right)\right]=O(t_n),\]
as $n\to\infty$, and similarly by \eqref{Equation: Main Asymptotic 1},
\[\mbf E\left[\tfrac{4\pi^2}{\msf{A}(D)\log t_n}\big(\mathsf T_\ka(t_n)-\msf T_0(t_n)\big)\right]=\ka^2+o(1),\]
\[\mbf{Var}\left[\tfrac{4\pi^2}{\msf{A}(D)\log t_n}\big(\mathsf T_\ka(t_n)-\msf T_0(t_n)\big)\right]=O\big((\log t_n)^{-2}\big).\]
Thus, by Borel-Cantelli and Chebyshev's inequality, it suffices to show that there exists $\eta>0$
such that $\sum_{n=1}^\infty t_n^{1-\eta}<\infty$ in the case of Corollary \ref{Corollary: Spectral Geometry}-(2)
(this works if $t_n\leq cn^{-1-\eps}$),
and similarly $\sum_{n=1}^\infty (\log t_n)^{-2+\eta}<\infty$ in the case of Corollary \ref{Corollary: Variance}
(this works if $t_n\leq\tilde c\mr e^{-cn^{1/2+\eps}}$). This concludes the proofs of Corollaries \ref{Corollary: Spectral Geometry}
and \ref{Corollary: Variance}.

%

\subsection{Proof of Corollary \ref{Corollary: Fractal Dimension}}
\label{Section: Proof of Fractal Dimension}

%

It suffices to show that there exists random variables $\mf c,\mf N>1$ such that,
almost surely,
\begin{align}
\label{Equation: Fractal Dimension Sufficient Condition}
\mf c^{-1}\,t_n^{1-\msf d_M(\partial D)/2}\leq\msf{A}(D)-\msf M_\ka(t_n)\leq\mf c\,t_n^{1-\msf d_M(\partial D)/2}
\qquad\text{for every }n\geq\mf N.
\end{align}
For this purpose, let us write
\[\msf{A}(D)-\msf M_\ka(t_n)
=\big(\msf{A}(D)-\msf M_0(t_n)\big)
+\big(\msf M_0(t_n)-\mbf E\big[\msf M_\ka(t_n)\big]\big)
+\big(\mbf E\big[\msf M_\ka(t_n)\big]-\msf M_\ka(t_n)\big).\]
Since $t\log t=o(t^{1-\msf d_M(\partial D)/2})$,
thanks to the expectation asymptotic in \eqref{Equation: Main Asymptotic 2} and \eqref{Equation: Fractal Dimension Heat Content},
there exists nonrandom constants $\tilde c,\tilde N>1$ such that
\[\tilde c^{-1}\,t_n^{1-\msf d_M(\partial D)/2}\leq\big(\msf{A}(D)-\msf M_0(t_n)\big)+\big(\msf M_0(t_n)-\mbf E\big[\msf M_\ka(t_n)\big]\big)\leq\tilde c\,t_n^{1-\msf d_M(\partial D)/2}
\qquad\text{for }n\geq\tilde N.\]
Thus, it suffices to show that for every $\eta>0$ (in particular, $\eta<\tilde c$),
\[\mbf P\left[\big|\msf M_\ka(t_n)-\mbf E\big[\msf M_\ka(t_n)\big]\big|>\eta t_n^{1-\msf d_M(\partial D)/2}\text{ infinitely often}\right]=0.\]
By the Borel-Cantelli lemma and Chebyshev's inequality (using the variance bound in \eqref{Equation: Main Asymptotic 2}), this follows from
\[\sum_{n=1}^\infty t_n^{2-2(1-\msf d_M(\partial D)/2)}=\sum_{n=1}^\infty t_n^{\msf d_M(\partial D)}<\infty.\]
If we choose $t_n\leq cn^{-1/\msf d_M(\partial D)-\eps}$ for any fixed $c,\eps>0$,
then we get
\[\sum_{n=1}^\infty t_n^{\msf d_M(\partial D)}\leq c\sum_{n=1}^\infty n^{-1-\eps\msf d_M(\partial D)}<\infty,\]
as desired.




































