\title{Categorical products of cellular automata}
\author[1]{Alonso Castillo-Ramirez\footnote{Email: alonso.castillor@academicos.udg.mx}}
\author[1]{Alejandro Vazquez-Aceves \footnote{Email: alejandro.vazquez5702@alumnos.udg.mx }}
