\section{Product of cellular automata}

The category of cellular automata over a group $G$, denoted by $\CA(G)$, consists of objects that are \emph{configuration spaces} over $G$; this is, sets of $A^G:=\{x:G\to A \}$ where $A$ is a set, usually called an \emph{alphabet}. The morphisms of $\CA(G)$ are \emph{cellular automata}, as given in the following definition, which is a slightly more general than Definition 1.4.1 in \cite{CAG}, as it involves two arbitrary alphabets $A$ and $B$ (see \cite[Sec. 1.1.4]{ExCAG}).

\begin{definition}\label{def-CA}
Let $A^G$ and $B^G$ be two configuration spaces. We say that a function $\tau:A^G\to B^G$ is a \emph{cellular automaton} if there exists a finite subset $S\subseteq G$ (called a \emph{memory set}) and a function $\mu:A^S\to B$ (called a \emph{local function}) such that:
\[ \tau(x)(g) = \mu((g \cdot x)|_S), \quad \forall x \in A^G, g \in G,  \]
where $\cdot$ is the \emph{shift action} of $G$ on $A^G$ given by
\[ (g\cdot x)(h)=x(hg), \quad \forall x\in A^G,  g,h\in G. \]
and $x|_S$ is the restriction of $x \in A^G$ to $S$. 
\end{definition}

\begin{remark}
Alternatively as introduced in Definition \ref{def-CA}, we may consider the shift action of $G$ on $A^G$ to be
\[ (g\star x)(h)=x(g^{-1}h), \quad \forall x\in A^G,  g,h\in G. \]
However, we may check that $\cdot$ and $\star$ are \emph{equivalent actions} in a formal sense: there exists a bijection $\beta : A^G \to A^G$ given by $\beta(x)(g) := x(g^{-1})$, for all $x \in A^G$, $g \in G$, such that 
\[ \beta(g \cdot x) = g \star \beta(x), \quad \forall x \in A^G, g \in G. \]  
\end{remark}

Since the composition of two cellular automata is a cellular automaton by \cite[Prop. 1.4.9]{CAG} and the identity function of $A^G$ is a cellular automaton, then $\CA(G)$ is a category.

\begin{example}\label{ex-ind}
For any function $f:A\to B$ between sets we may define a cellular automaton $f^G : A^G\to B^G$ by
\[ f^G(x) := f \circ x , \quad \forall x\in A^G. \]
It is clear that $f^G$ has memory set $\{e \}$, where $e \in G$ is the identity element of the group, and local function $f : A^{\{e\}} \to A$.
\end{example}

The next result shows that the category $\CA(G)$ has concrete finite products. 

\begin{theorem}\label{th-prod}
Let $G$ be a group, and let $A_2^G$ and $A_2^G$ be two configuration spaces in $\CA(G)$. The product of $A_1^G$ and $A_2^G$ in the category $\CA(G)$
is the configuration space $(A_1 \times A_2)^G$ together with the cellular automata $\pi_i^G: (A_1\times A_2)^G\to A_i^G$ induced, as in Example \ref{ex-ind}, by the usual projections $\pi_i : A_1 \times A_2 \to A_i$ in the category of sets. 
\end{theorem}
\begin{proof}
Let $B^G\in\CA(G)$ be a configuration space, and consider two cellular automata $\tau_1:B^G\to A_1^G$ and $\tau_2:B^G\to A_2^G$. Let $S_1, S_2\subseteq G$ be memory sets, and let $\mu_1: B^{S_1} \to A_1$ and $\mu_2: B^{S_2} \to A_2$ be local functions for $\tau_1$ and $\tau_2$, respectively. Define a finite set $S := S_1\cup S_2\subseteq G$ and local functions
\[  \hat{\mu}_1 : B^S\to A_1 \text{ and } \hat{\mu}_2 :B^S \to A_2,  \]
by $\hat{\mu}_1(x) := \mu_1(x \vert_{S_1})$ and $\hat{\mu}_2(x):= \mu_2(x \vert_{S_2})$, for all $x \in B^S$. The universal property of the product in the category of sets tells us that there exists a unique function 
\begin{equation}\label{eq-proj}
 \mu:B^S\to A_1 \times A_2 \text{ such that } \pi_i \circ \mu= \hat{\mu}_i, \quad i \in \{1,2\}. 
\end{equation}
 Now let $\tau:B^G\to(A_1\times A_2)^G$ be the cellular automaton defined by the local function $\mu$. We shall check that the diagram given in Figure \ref{dia-prodCA} commutes.
\begin{figure}[h!]
\centering
\begin{tikzcd}
 & B^G \arrow[ld, "\tau_1"'] \arrow[rd, "\tau_2"] \arrow[d, "\tau"] & \\
 A_1^G & (A_1\times A_2)^G \arrow[l, "\pi_1^G"] \arrow[r, "\pi_2^G"'] & A_2^G
 \end{tikzcd}
 \caption{Product of two configuration spaces in $\CA(G)$.}
\label{dia-prodCA}
\end{figure}
Indeed, for any $x\in B^G$ and $g\in G$, we have
\begin{eqnarray*}
(\pi_i^G\circ\tau)(x)(g) &=& \pi_i ( \tau(x) (g) ) \\
&= &\pi_i(\mu((g\cdot x)|_S))\\
&=& \hat{\mu}_i((g\cdot x)|_S)  \quad \quad \quad \text{(by eq. (\ref{eq-proj}))} \\ 
&=& \mu_i((g\cdot x)|_{S_i})\\
&=& \tau_i(x)(g).
\end{eqnarray*}
Therefore, $\pi_i^G\circ\tau = \tau_i$, for $i \in \{1,2\}$. 

Finally, to prove that $\tau$ is unique, suppose there exists another cellular automaton $\sigma:B^G\to(A_1\times A_2)^G$ such that $\tau_i=\pi_i^G\circ\sigma$. Then, for all $x\in B^G$ and $g\in G$ we have:
\[ \pi_i(\sigma(x)(g)) = \pi_i^G(\sigma(x))(g)=\pi_i^G(\tau(x))(g)=\pi_i(\tau(x)(g))\] 
for $i \in \{1,2 \}$. Hence $\sigma(x)(g)=\tau(x)(g)$ for all $x\in B^G$ and $g\in G$,
which implies that $\sigma=\tau$.
\end{proof}

\begin{corollary}
For any cellular automata $\tau_1 : A_1^G \to B_1^G$ and $\tau_2 : A_2^G \to B_2^G$ in $\CA(G)$ there is a unique cellular automaton $\tau_1 \times \tau_2 : (A_1 \times A_2)^G \to (B_1 \times B_2)^G$ such that
\[ \pi_{B_1}^G \circ (\tau_1 \times \tau_2)  = \tau_1 \circ \pi_{A_1}^G \text{ and } \pi_{B_2}^G \circ (\tau_1 \times \tau_2) = \tau_2 \circ \pi_{A_2}^G,  \]  
This is equivalent to,
\[(\tau_1 \times \tau_2)(x)(g) = (\tau_1(\pi_{A_1} \circ x) (g), \tau_2(\pi_{A_2} \circ x)(g)),  \quad \forall x \in (A_1 \times A_2)^G, g \in G. \] 
\end{corollary}


