\section{Preliminaries}

\subsection{Lorentzian Background}

This subsection provides a brief overview of Lorentzian geometry, presenting definitions and results used throughout. For a comprehensive treatment of the basic theory, see~\cite{oneill}.

\subsubsection{Spacetimes}

A \emph{Lorentzian manifold} is a pair $(M,g)$, where $M$ is a smooth manifold of dimension $n + 1$ and $g$ is a Lorentzian metric on $M$, that is, a metric tensor of signature $(1,n)$. Each non-zero tangent vector $X \in TM$ is classified as \emph{timelike}, \emph{null}, or \emph{spacelike}, according to whether $g(X,X)$ is negative, zero, or positive, respectively. Timelike and null vectors are collectively referred to as \emph{causal}. The $g$-norm of a tangent vector $X \in TM$ is defined by
\[
	\norm{X}_g = \sqrt{\abs{g(X,X)}}.
\]
Causal vectors satisfy a reverse form of the Cauchy--Schwarz inequality.

\begin{proposition}[Reverse Cauchy--Schwarz Inequality]
	Let $X,Y \in TM$ be causal vectors at the same point. Then
	\[
		g(X,Y)^2 \geq g(X,X)g(Y,Y),
	\] 
	with equality if and only if $X$ and $Y$ are linearly dependent.
\end{proposition}

A \emph{time orientation} on a Lorentzian manifold $(M,g)$ is a smooth timelike vector field $\vartheta$ on $M$. A causal vector $X \in TM$ is \emph{future-directed} (respectively, \emph{past-directed}) if $g(X,\vartheta) < 0$ (respectively, $g(X,\vartheta) > 0$). The following lemma ensures that every causal vector must be either future-directed or past-directed. The proof is provided in Appendix~\ref{chap:Deferred_Proofs}.

\begin{lemma}
	\label{lem:causal_timelike}
	Let $X,T \in TM$ be tangent vectors at the same point, with $X$ causal and $T$ timelike. Then $g(X,T) \neq 0$.
\end{lemma}

The following characterization of past-directed timelike vectors will be used throughout this work. The proof is provided in Appendix~\ref{chap:Deferred_Proofs}.

\begin{lemma}
	\label{lem:past_timelike}
	Let $p \in M$, and let $h_p$ be any Euclidean inner product on $T_pM$. Then the following conditions on a tangent vector $T \in T_pM$ are equivalent:
	\begin{enumerate}
		\item $T$ is past-directed timelike.
		\item For every future-directed causal vector $X \in T_pM$, $g(X,T) > 0$.
		\item There exists a constant $C > 0$ such that, for all future-directed causal vectors $X \in T_pM$,
		\[
			g(T,X) \geq C\norm{X}_{h_p}.
		\]
	\end{enumerate}
\end{lemma}

A \emph{spacetime} is a connected, time-oriented Lorentzian manifold. Unless otherwise specified, the pair $(M,g)$ will denote a spacetime.

\begin{example}
	The most basic example of a spacetime is the $(n+1)$-dimensional \emph{Minkowski spacetime}:
	\[
		\mathbb{M}^{n+1} = (\RR^{n+1}, \eta),
	\]
	where
	\[
		\eta = -dt^2 + d(x^1)^2 + \dots + d(x^n)^2
	\]
	is the Minkowski metric expressed in Cartesian coordinates. The time orientation is given by the coordinate vector field $\partial_t$.

	Throughout this work, we denote points in $\mathbb{M}^{n+1}$ by $p = (t_p, x_p)$, where $t_p \in \mathbb{R}$ is the temporal component and $x_p \in \mathbb{R}^n$ the spatial one. Moreover, given two points $p, q \in \mathbb{M}^{n+1}$, we denote by $[p, q]$ the straight-line segment from $p$ to $q$, regarded as a parametrized curve.
\end{example}

\begin{example}
	A \emph{generalized Robertson--Walker (GRW) spacetime} is a spacetime of the form 
	\[
		(M,g) = (I \times S, -dt^2 + f(t)^2h),
	\]
	where $I \subseteq \RR$ is an open interval, $(S,h)$ is an $n$-dimensional connected Riemannian manifold, and $f \from I \to \RR$ is a smooth, strictly positive function called the \emph{scale factor}. The time orientation is given by the coordinate vector field $\partial_t$. 

	Note that Minkowski spacetime $\mathbb{M}^{n+1}$ arises as a special case of a GRW spacetime by taking $I = \RR$, $f \equiv 1$, and $(S,h)$ equal to the $n$-dimensional Euclidean space.
\end{example}

\subsubsection{Causality}

A smooth curve $\gamma \from I \to M$ is called \emph{timelike} (respectively, \emph{null}, \emph{spacelike}, \emph{causal}) if its tangent vector $\gamma'$ is everywhere timelike (respectively, null, spacelike, causal). A causal curve is \emph{future-directed} (respectively, \emph{past-directed}) if its tangent vector is everywhere future-directed (respectively, past-directed). 

The \emph{causal future} of a point $p \in M$ is defined by
\[
	J^+(p) = \{ q \in M \mid \text{there exists a future-directed causal curve from }p \text{ to }q \} \cup \{p\}.
\]
Similarly, the \emph{chronological future} of $p$ is given by
\[
	I^+(p) = \{ q \in M \mid \text{there exists a future-directed timelike curve from }p \text{ to }q \}.
\]
The \emph{causal past} $J^-(p)$ and the \emph{chronological past} $I^-(p)$ are defined analogously, replacing future-directed curves with past-directed ones. For any $p,q \in M$, we write $p \leq q$ if and only if $q \in J^+(p)$, or equivalently, $p \in J^-(q)$.

\begin{proposition}
	\label{prop:futures_open}
	For every point $p \in M$, the chronological future $I^+(p)$ and the chronological past $I^-(p)$ are open subsets of $M$.
\end{proposition}

\subsubsection{Time Functions}

A continuous function $\tau \from M \to \RR$ is called a \emph{time function} if it is strictly increasing along all future-directed causal curves. 

Recall that, if a function $f \from M \to \RR$ is differentiable at a point $p \in M$, then its gradient at $p$ is the unique tangent vector satisfying
\[
	g((\nabla f)_p, X) = \mathrm{d}_pf(X) \quad \text{for all } X \in T_pM.
\]
The following lemma shows that if a time function is differentiable at a point, then its monotonicity along future-directed causal curves imposes constraints on the causal character of its gradient. The proof is provided in Appendix~\ref{chap:Deferred_Proofs}.

\begin{lemma}
	\label{lem:time_functions_gradient}
	Let $\tau$ be a time function on $M$. If $\tau$ is differentiable at a point $p \in M$, then the gradient vector $(\nabla \tau)_p$ is either past-directed causal or zero.
\end{lemma}

As a consequence, the gradient of a differentiable time function is either past-directed causal or zero at every point. However, it is not necessarily timelike everywhere. A differentiable function whose gradient is everywhere past-directed timelike is called a \emph{temporal function}. Every temporal function is, in particular, a time function.

\begin{proposition}
	\label{lem:gradient_implies_time_function}
	Let $f \from M \to \RR$ be a temporal function. Then $f$ is a time function.
\end{proposition}
\begin{proof}
	Let $\alpha$ be a future-directed causal curve. Since $\nabla f$ is past-directed timelike and $\alpha'$ is future-directed casual, Lemma~\ref{lem:past_timelike} implies that
	\[
		(f\circ\alpha)' = g(\nabla f, \alpha') > 0.
	\]
	It follows that $f$ is strictly increasing along $\alpha$, and thus a time function. 
\end{proof}

\begin{example}
	\label{ex:GRW_temporal_functions}
	In a GRW spacetime
	\[
		(M,g) = (I \times S, -dt^2 + f(t)^2h),
	\]
	consider a differentiable function of the form $\tau(t,x)= \phi(t)$, where $\phi \from I \to \RR$ satisfies $\phi'(t) > 0$ for all $t \in I$. Then $\tau$ is a temporal function. Indeed, its gradient is given by
	\[
		\nabla \tau = -\phi'(t)\partial_t,
	\]
	which is everywhere past-directed timelike.
\end{example}

We now briefly recall some standard causality conditions. A spacetime $(M,g)$ is said to be \emph{causal} if it contains no closed causal curves, and \emph{stably causal} if this property persists under small perturbations of the metric $g$. Every stably causal spacetime is, in particular, \emph{strongly causal}, meaning that for every point $p \in M$ and every open neighborhood $U$ of $p$, there exists an open neighborhood $V \subseteq U$ of $p$ such that every causal curve with endpoints in $V$ is entirely contained in $U$. The following is a fundamental result in Lorentzian geometry.

\begin{theorem}
	\label{thm:strongly_causal}
	Let $(M,g)$ be a spacetime. Then the following conditions are equivalent:
	\begin{enumerate}
		\item $(M,g)$ admits a time function.
		\item $(M,g)$ admits a smooth temporal function.
		\item $(M,g)$ is stably causal.
	\end{enumerate}
\end{theorem}
\begin{proof}
	See~\cite[Thm.~4.12]{ChruścielGrantMinguzzi2016}.
\end{proof}

\subsubsection{Lorentzian Distance}

The \emph{Lorentzian length} of a causal curve $\gamma \from I \to M$ is defined by
\[
	L_g(\gamma) = \int_I \sqrt{ -g(\gamma'(s), \gamma'(s)) } \, ds.
\]
The \emph{Lorentzian distance} between two points $p,q \in M$ is then given by
\[
	d_g(p,q) = \sup\{ L_g(\gamma) \mid \gamma \text{ is a future-directed causal curve from }p \text{ to }q \}.
\]
If $q = p$ or $q \notin J^+(p)$, we set $d_g(p,q) = 0$. Despite its name, the Lorentzian distance is not a metric, as it may vanish for distinct points and is generally not symmetric, except in trivial cases.

\subsection{Metric Background}

This subsection introduces definitions and results from metric geometry that will be used throughout. We adopt much of the notation and terminology of~\cite{bbi}, to which we also refer for many of the proofs.

\subsubsection{Metric Spaces}

\begin{definition}
	Let $X$ be a set. A function $d \from X \times X \to \RR \cup \{\infty\}$ is called a \emph{metric} on $X$ if the following conditions hold for all $x,y,z \in X$:
	\begin{enumerate}
		\item Positiveness: $d(x,y) \geq 0$, with equality if and only if $x = y$.
		\item Symmetry: $d(x,y) = d(y,x)$.
		\item Triangle inequality: $d(x,z) \leq d(x,y) + d(y,z)$.
	\end{enumerate}	
	The condition that $d(x,y) = 0$ implies $x = y$ is referred to as definiteness. If $d$ satisfies all the conditions above except definiteness, it is called a \emph{semi-metric} on $X$.
\end{definition}

A \emph{metric space} is a pair $(X,d)$, where $X$ is a set and $d$ is a metric on it. Unless multiple metrics on the same set $X$ are considered, we will omit an explicit reference to the metric and write "a metric space $X$" instead of "a metric space $(X,d)$". 

For any $x \in X$ and $r > 0$, we denote by $B_r(x)$ the open ball of radius $r$ centered at $x$, that is, the set of points $y \in X$ such that $d(x,y) < r$. Given a nonempty subset $S \subseteq X$, its diameter is defined by
\[
	\diam(S) = \sup\{ d(x,y) \mid x,y \in S \}.
\]
If $\diam(S) < \infty$, the set $S$ is said to be bounded. Given two nonempty subsets $A,B \subseteq X$, their distance is defined by
\[
	\dist(A,B) = \inf\{ d(a,b) \mid a \in A,\ b \in B \}.
\]

The following result, known as Lebesgue's number lemma, will be used throughout this work.

\begin{proposition}[Lebesgue's Number Lemma]
	Let $X$ be a compact metric space, and let $\{ U_{\alpha} \}_{\alpha \in A}$ be an open cover of $X$. Then there exists $\varepsilon > 0$ such that every ball of radius $\varepsilon$ in $X$ is entirely contained in some $U_{\alpha}$.
\end{proposition} 
\begin{proof}
	See~\cite[Thm.~1.6.11]{bbi}.
\end{proof}

\subsubsection{Hausdorff Distance}

For any nonempty $S \subseteq X$ and $r > 0$, we denote by $U_r(S)$ the tubular open neighborhood of radius $r$ around $S$, that is, the set of points $x \in X$ such that $\dist(x,S) < r$. Equivalently, 
\[
	U_r(S) = \bigcup_{x \in S} B_r(x).
\]
Given two nonempty subsets $A,B \subseteq X$, their \emph{Hausdorff distance} is defined by
\[
	d_H(A,B) = \inf\{ r > 0 \mid A \subseteq U_r(B),\ B \subseteq U_r(A) \}.
\]
It is straightforward to verify the following equivalent expression:
\[
	d_H(A,B) = \max\{ \sup\nolimits_{a \in A}\dist(a,B),\ \sup\nolimits_{b \in B}\dist(b,A) \}.
\]

\begin{proposition}
	Let $X$ be a metric space. Then the Hausdorff distance is a semi-metric on the set of all nonempty subsets of $X$. Moreover, if $A$ and $B$ are closed nonempty subsets of $X$ such that $d_H(A,B) = 0$, then $A = B$. 
\end{proposition}
\begin{proof}
	See~\cite[Prop.~7.3.3]{bbi}.
\end{proof}

We denote by $\mathcal{F}(X)$ the set of all nonempty closed subsets of $X$ (from the French \emph{fermé}), and by $\mathcal{F}_b(X)$ the set of all nonempty closed and bounded subsets of $X$. The previous proposition shows that the Hausdorff distance is a metric on $\mathcal{F}(X)$. Moreover, it is straightforward to verify that $\mathcal{F}_b(X)$ is a closed subset of $\mathcal{F}(X)$.

\begin{lemma}
	Let $X$ be a metric space, and let $\diam \from \mathcal{F}_b(X) \to [0,\infty)$ denote the function that assigns to each set its diameter. Then $\diam$ is $2$-Lipschitz with respect to the Hausdorff distance. 
\end{lemma}
\begin{proof}
	Let $A,B \in \mathcal{F}_b(X)$, and set $d = d_H(A,B)$. By the definition of the Hausdorff distance, for every $\varepsilon > 0$ we have 
	\[
		A \subseteq U_{d + \varepsilon}(B) \quad \text{and} \quad B \subseteq U_{d + \varepsilon}(A).
	\]
	This implies
	\[
		\abs{ \diam(A) - \diam(B) } \leq 2( d_H(A,B) + \varepsilon ).
	\]
	The conclusion follows by letting $\varepsilon \to 0$.
\end{proof}

The following lemma follows directly from the continuity of $\diam$ with respect to the Hausdorff distance and the fact that $\mathcal{F}_b(X)$ is closed in $\mathcal{F}(X)$.

\begin{lemma}
	\label{lem:diam_convergence}
	Let $X$ be a metric space, and let $A_j \in \mathcal{F}_b(X)$ be a sequence of nonempty closed and bounded subsets. If $A_j$ converges to a set $A \in \mathcal{F}(X)$ in the Hausdorff sense, then $A \in \mathcal{F}_b(X)$ and
	\[
		\diam(A) = \lim_{j \to \infty} \diam(A_j).
	\]
\end{lemma}

\subsubsection{Metric Completion}

\begin{proposition}
	Let $X$ be a metric space. Then there exist a complete metric space $\overline{X}$ and an isometric embedding of $X$ as a dense subset of $\overline{X}$. Moreover, any other complete metric space containing an isometric copy of $X$ as a dense subset is isometric to $\overline{X}$.
\end{proposition}
\begin{proof}
	See~\cite[Thm.~1.5.10]{bbi}.
\end{proof}

The space $\overline{X}$ is called the \emph{metric completion} of $X$. In what follows, we identify $X$ with its isometric copy in $\overline{X}$, writing $X \subseteq \overline{X}$ and using the same symbol $d$ to denote both the original metric on $X$ and its extension to $\overline{X}$.

\begin{proposition}
	Let $X$ be a metric space, and let $S \subseteq X$ be a dense subset. Let $Y$ be a complete metric space, and let $f \from S \to Y$ be a $C$-Lipschitz function for some $C > 0$. Then there exists a unique $C$-Lipschitz function $\tilde{f} \from X \to Y$ such that $\at{\tilde{f}}{S} = f$.
\end{proposition}
\begin{proof}
	See~\cite[Prop.~1.5.9]{bbi}.
\end{proof}

\begin{corollary}
	\label{cor:extension_completion}
	Let $f \from X \to Y$ be a $C$-Lipschitz function from a metric space $X$ to a complete metric space $Y$. Then $f$ admits a unique $C$-Lipschitz extension $\overline{f} \from \overline{X} \to Y$ to the metric completion of $X$.
\end{corollary}

