\section{Null Distance} 

This section focuses on the notion of null distance, as introduced by Sormani and Vega in~\cite{SormaniVega2016}. Definitions, key results, and proofs are drawn from their work, sometimes adapted for the present context.

\subsection{Definitions}

\begin{definition}
	A curve $\beta \from [a,b] \to M$ is called a \emph{piecewise causal curve} if there exists a partition $a = s_0 < \dots < s_N = b$ such that each restriction $\beta_i = \at{\beta}{[s_i,s_{i+1}]}$ is either a future-directed or a past-directed causal curve. 
\end{definition}

\begin{definition}
	Let $\tau$ be a time function on $M$. The \emph{null length} of a piecewise causal curve $\beta \from [a,b] \to M$, with breakpoints $a = s_0 < \dots < s_N = b$, is defined by
	\[
		\hat{L}_{\tau}(\beta) = \sum_{i=0}^{N-1} \abs{ \tau(\beta(s_{i+1})) - \tau(\beta(s_i)) }.
	\]
	The \emph{null distance} between two points $p,q \in M$ is then given by
	\[
		\hat{d}_{\tau}(p,q) = \inf\{ \hat{L}_{\tau}(\beta) \mid \beta \text{ is a piecewise causal curve from $p$ to $q$} \}.
	\]
	If $q = p$, we set $\hat{d}_{\tau}(p,q) = 0$.
\end{definition}

The following lemma ensures that the null distance between any two points is well-defined.

\begin{lemma}
	\label{lem:null_distance_well-definiteness}
	For any pair of points $p,q \in M$, there exists a piecewise causal curve from $p$ to $q$.
\end{lemma}
\begin{proof}
	Let $\gamma \from [a,b] \to M$ be a smooth curve with $\gamma(a) = p$ and $\gamma(b) = q$. Since 
	\[
		M = \bigcup_{x \in M} I^-(x),
	\]
	and each set $I^-(x)$ is open by Proposition~\ref{prop:futures_open}, the collection $\{ \gamma^{-1}(I^-(x)) \}_{x \in M}$ forms an open cover of the compact interval $[a,b]$. By the Lebesgue's number lemma, there exists $\varepsilon > 0$ such that every subinterval of $[a,b]$ of length less than $\varepsilon$ is contained in some $\gamma^{-1}(I^-(x))$.

	Let $a \leq t_0 < \dots < t_{N-1} \leq b$ be a finite collection of points such that the open intervals $( t_i - \varepsilon/2,\ t_i + \varepsilon/2 )$ cover $[a,b]$. For each $i = 1,\dots,N-1$, choose a point $s_i \in [a,b]$ such that
	\[
		t_{i-1} < s_i < t_i, \quad s_i - t_{i-1} < \frac{\varepsilon}{2}, \quad \text{and} \quad t_i - s_i < \frac{\varepsilon}{2}.
	\]
	Define $s_0 = a$ and $s_N = b$. Then each interval $[s_i, s_{i+1}]$ has length less than $\varepsilon$, and is therefore contained in $\gamma^{-1}(I^-(x_i))$ for some $x_i \in M$. It follows that both endpoints $\gamma(s_i)$ and $\gamma(s_{i+1})$ lie in $I^-(x_i)$. Consequently, there exist a future-directed causal curve from $\gamma(s_i)$ to $x_i$ and a past-directed causal curve from $x_i$ to $\gamma(s_{i+1})$. Their concatenation yields a piecewise causal curve from $\gamma(s_i)$ to $\gamma(s_{i+1})$, with a breakpoint at $x_i$. The full concatenation of these segments is a piecewise causal curve from $\gamma(s_0) = p$ to $\gamma(s_N) = q$.
\end{proof}

\subsection{Basic Properties}

\begin{lemma}
	\label{lem:null_distance_basic_properties}
	Let $\tau$ be a time function on $M$, and let $\beta \from [a,b] \to M$ be a piecewise causal curve from $p$ to $q$, with breakpoints $a = s_0 < \dots < s_N = b$. Then:
	\begin{enumerate}
		\item \label{item:1_null_distance_basic_properties} $\hat{L}_{\tau}(\beta) = \tau(q) - \tau(p)$  if and only if $\beta$ is future-directed causal.
		\item \label{item:2_null_distance_basic_properties} The following inequalities hold:
		\[
			\hat{L}_{\tau}(\beta) \geq \max_{s \in [a,b]} \tau(\beta(s)) - \min_{s \in [a,b]} \tau(\beta(s)) \geq \abs{\tau(q) - \tau(p)}.
		\]
		\item \label{item:3_null_distance_basic_properties} If $\tau$ is $C^1$ along $\beta$, then 
		\[
			\hat{L}_{\tau}(\beta) = \int_a^b \abs{(\tau\circ\beta)'} \de s = \sum_{i=0}^{N-1} \int_{s_i}^{s_{i+1}} \abs{(\tau\circ\beta_i)'} \de s.
		\]
	\end{enumerate}
\end{lemma}
\begin{proof}
	\cref{item:1_null_distance_basic_properties} follows directly from the definition of null length and the triangle inequality.

	\cref{item:2_null_distance_basic_properties} follows from the triangle inequality and the strict monotonicity of $\tau\circ\beta$ on each subinterval $[s_i, s_{i+1}]$, which implies that its maximum and minimum over $[a,b]$ are attained at some of the breakpoints.

	\cref{item:3_null_distance_basic_properties} follows from
	\begin{align*}
		\hat{L}_{\tau}(\beta) &= \sum_{i=0}^{N-1} \abs{ \tau(\beta(s_{i+1})) - \tau(\beta(s_i)) } \\
		&= \sum_{i=0}^{N-1} \abs{ \int_{s_i}^{s_{i+1}} (\tau\circ\beta_i)' \de s } \\
		&= \sum_{i=0}^{N-1} \int_{s_i}^{s_{i+1}} \abs{(\tau\circ\beta_i)'} \de s,
	\end{align*}
	where the last equality holds since $(\tau\circ\beta_i)'$ does not change sign on $[s_i,s_{i+1}]$, due to the causal character of $\beta_i$.
\end{proof}

The following proposition follows readily from the definition of null distance and Lemma~\ref{lem:null_distance_well-definiteness}.

\begin{proposition}
	\label{prop:null_distance_semi-metric}
	Let $\tau$ be a time function on $M$. Then $\hat{d}_{\tau}$ is a semi-metric on $M$.
\end{proposition}

In general, $\hat{d}_{\tau}$ is not a metric, as it may vanish for distinct points (See~\cite[Prop.~3.4]{SormaniVega2016}). We will later introduce the local anti-Lipschitz condition on the time function, which is equivalent to the definiteness of $\hat{d}_{\tau}$. For now, we observe that the following lemma shows that non-definiteness can only occur for pairs of points lying on the same level set of $\tau$.

\begin{lemma}
	\label{lem:time_functions_1Lip}
	Let $\tau$ be a time function on $M$. Then, for every $p,q \in M$,
	\[
		\hat{d}_{\tau}(p,q) \geq \abs{\tau(q) - \tau(p)}.
	\]
	Consequently, definiteness may fail only for pairs of points lying on the same level set of $\tau$:
	\[
		\hat{d}_{\tau}(p,q) = 0 \implies \tau(p) = \tau(q).
	\]
\end{lemma}
\begin{proof}
	Let $\beta$ be a piecewise causal curve from $p$ to $q$. By Lemma~\ref{lem:null_distance_basic_properties}, we have
	\[
		\hat{L}_{\tau}(\beta) \geq \abs{\tau(q) - \tau(p)}.
	\]
	The conclusion follows by taking the infimum over all such curves.
\end{proof}

As a consequence of the previous lemma, we obtain the following causality property of the null distance.
\begin{lemma}
	\label{lem:null_distance_causality_property}
	Let $\tau$ be a time function on $M$. Then $\hat{d}_{\tau}$ satisfies the causality property:
	\[
		p \leq q \implies \hat{d}_{\tau}(p,q) = \tau(q) - \tau(p).
	\]
\end{lemma}
\begin{proof}
	Suppose $p \leq q$, and let $\beta$ be a future-directed causal curve from $p$ to $q$. Since $\hat{L}_{\tau}(\beta) = \tau(q) - \tau(p)$ by Lemma~\ref{lem:null_distance_basic_properties}, it follows that $\hat{d}_{\tau}(p,q)  \leq \tau(q) - \tau(p)$. The reverse inequality follows from Lemma~\ref{lem:time_functions_1Lip}.
\end{proof}

\subsection{Topology}

\begin{lemma}
	\label{lem:diamonds}
	Let $\tau$ be a time function on $M$. Then:
	\begin{enumerate}
		\item \label{item:1_diamonds}$\tau$ is bounded on diamonds: $p \leq x \leq q \implies \tau(p) \leq \tau(x) \leq \tau(q)$.
		\item \label{item:2_diamonds} $\hat{d}_{\tau}$ is bounded on diamonds: $p \leq x, y \leq q \implies \hat{d}_{\tau}(x, y) \leq 2\left( \tau(q) - \tau(p) \right)$.
	\end{enumerate}
\end{lemma}
\begin{proof}
	\cref{item:1_diamonds} follows directly from the fact that $\tau$ is strictly increasing along future-directed causal curves. 

	To prove~\cref{item:2_diamonds}, let $\beta$ be a piecewise causal curve consisting of a future-directed causal curve from $x$ to $q$, followed by a past-directed causal curve from $q$ to $y$. Then 
	\[
		\hat{L}_{\tau}(\beta) = \abs{ \tau(q) - \tau(x) } + \abs{ \tau(y) - \tau(q) } \leq 2\left( \tau(q) - \tau(p) \right),
	\]
	where the inequality follows from \cref{item:1_diamonds}.
	Since $\hat{d}_{\tau}(x, y)$ is defined as the infimum of $\hat{L}_{\tau}$ over all piecewise causal curves from $x$ to $y$, the claim follows.
\end{proof}

\begin{lemma}
	Let $\tau$ be a time function on $M$. Then $\hat{d}_{\tau}$ is continuous on $M \times M$.
\end{lemma}
\begin{proof}
	Fix any two points $x,y \in M$. Let $\alpha_x$ be a future-directed timelike curve with $\alpha_x(0) = x$, and let $\alpha_y$ be a future-directed timelike curve with $\alpha_y(0) = y$. Choose $\delta > 0$ sufficiently small so that both curves are defined on the interval $[-\delta, \delta]$. Then, for all $x' \in I^+(\alpha_x(-\delta)) \cap I^-(\alpha_x(\delta))$ and $y' \in I^+(\alpha_y(-\delta)) \cap I^-(\alpha_y(\delta))$, we have
	\begin{align*}
		\abs{ \hat{d}_{\tau}(x,y) - \hat{d}_{\tau}(x',y') } &\leq \hat{d}_{\tau}(x,x') + \hat{d}_{\tau}(y,y') \\
		&\leq 2\left( \tau(\alpha_x(\delta)) - \tau(\alpha_x(-\delta)) \right) + 2\left( \tau(\alpha_y(\delta)) - \tau(\alpha_y(-\delta)) \right),
	\end{align*}
	where the first inequality follows from the reverse triangle inequality, and the second from point~\cref{item:2_diamonds} of Lemma~\ref{lem:diamonds}. Since $\tau$ is continuous, the right-hand side tends to zero as $\delta \to 0$. Hence, $\hat{d}_{\tau}$ is continuous at $(x,y)$.
\end{proof}

As a semi-metric, $\hat{d}_{\tau}$ induces a topology on $M$ generated by the \emph{open null balls}:
\[
	\hat{B}_r(x) = \{ y \in M \mid \hat{d}_{\tau}(x,y) < r \}.
\]

\begin{proposition}
	\label{prop:null_distance_topology}
	Let $\tau$ be a time function on $M$. If $\hat{d}_{\tau}$ is definite, then the topology induced by $\hat{d}_{\tau}$ coincides with the manifold topology.
\end{proposition}
\begin{proof}
	Since $\hat{d}_{\tau}$ is continuous on $M \times M$, every open null ball $\hat{B}_r(x)$ is open in the manifold topology. Hence, the topology induced by $\hat{d}_{\tau}$ is coarser than or equal to the manifold topology.

	Conversely, suppose $U \subseteq M$ is open in the manifold topology, and fix any point $x_0 \in U$. Choose a Riemannian metric $h$ on $M$, and denote by $d_h$ the corresponding distance function. Since $U$ is open, there exists $\varepsilon > 0$ such that the Riemannian ball 
	\[
		B = B^h_{\varepsilon}(x_0) = \{ y \in M \mid d_h(x_0,y) < \varepsilon \}
	\]
	is contained in $U$. Since $\hat{d}_{\tau}$ is definite and continuous, and $\partial B$ is compact, the continuous function 
	\[
		z \mapsto \hat{d}_{\tau}(x_0,z)
	\]
	attains a positive minimum on $\partial B$. Define
	\[
		\varepsilon_0 = \min_{z \in \partial B} \hat{d}_{\tau}(x_0,z) > 0.
	\]
	Now let $y \notin B$, and let $\beta$ be any piecewise causal curve from $x_0$ to $y$. Let $z_0 \in \partial B$ be the first point at which $\beta$ intersects $\partial B$, and denote by $\beta_0$ the initial segment of $\beta$ from $x_0$ to $z_0$. Then
	\[
		\hat{L}_{\tau}(\beta) \geq \hat{L}_{\tau}(\beta_0) \geq \varepsilon_0.
	\]
	Taking the infimum over all such curves $\beta$ yields 
	\[
		y \notin B \implies \hat{d}_{\tau}(x_0,y) \geq \varepsilon_0.
	\]
	Thus, we have 
	\[
		\hat{B}_{\varepsilon_0}(x_0) \subseteq B \subseteq U.
	\]
	Since $x_0 \in U$ was arbitrary, $U$ is open in the topology induced by $\hat{d}_{\tau}$. Therefore, the two topologies coincide.
\end{proof}

\subsection{Definiteness}

\subsubsection{Definiteness and Anti-Lipschitz Condition}

\begin{definition}
	A function $f \from M \to \RR$ is said to be \emph{anti-Lipschitz} on a subset $U \subseteq M$ if there exists a metric $d_U$ on $U$ such that, for all $x,y \in U$, 
	\[
		x \leq y \implies f(y) - f(x) \geq d_U(x,y).
	\]
	The function $f$ is called \emph{locally anti-Lipschitz} if it is anti-Lipschitz on some open neighborhood of every point in $M$.
\end{definition}

Since all metrics on a manifold are locally Lipschitz equivalent, the following lemma follows immediately.

\begin{lemma}
	\label{lem:anti-Lip_equivalent_conditions}
	Let $h$ be any Riemannian metric on $M$, and denote by $d_h$ the corresponding distance function. Then the following conditions on a function $f \from M \to \RR$ are equivalent:
	\begin{enumerate}
		\item $f$ is locally anti-Lipschitz.
		\item For every point $p \in M$, there exist an open neighborhood $U$ of $p$ and a constant $C > 0$ such that, for all $x,y \in U$,
		\[
				x \leq y \implies f(y) - f(x) \geq Cd_h(x,y).
		\]
	\end{enumerate}
\end{lemma}

\begin{proposition}
	\label{prop:null_distance_definiteness}
	Let $\tau$ be a time function on $M$. Then $\hat{d}_{\tau}$ is definite if and only if $\tau$ is locally anti-Lipschitz.
\end{proposition}
\begin{proof}
	Suppose first that $\hat{d}_{\tau}$ is definite. Then, by Lemma~\ref{lem:null_distance_causality_property}, it follows that $\tau$ is anti-Lipschitz on all of $M$, and in particular locally anti-Lipschitz.

	Conversely, assume that $\tau$ is locally anti-Lipschitz. Let $p,q \in M$ be distinct points, and let $U$ be an open neighborhood of $p$ on which $\tau$ is anti-Lipschitz. Choose a precompact open set $B \subseteq U$ such that $p \in B$ and $q \notin B$, and let $\beta$ be any piecewise causal curve from $p$ to $q$. Let $z_0 \in \partial B$ be the first point at which $\beta$ intersects $\partial B$, and denote by $\beta_0$ the initial segment of $\beta$ from $p$ to $z_0$, with breakpoints $p = x_0, x_1, \dots, x_N = z_0$. Since $\beta_0 \subseteq U$ and $\tau$ is anti-Lipschitz on $U$, we have
	\begin{align*}
		\hat{L}_{\tau}(\beta) &\geq \hat{L}_{\tau}(\beta_0) = \sum_{i=0}^{N-1} \abs{\tau(x_{i+1}) - \tau(x_i)} \\
		&\geq \sum_{i=0}^{N-1} d_U(x_{i+1},x_i) \\
		&\geq d_U(p,z_0) \\
		&\geq \dist(p,\partial B).
	\end{align*}
	Taking the infimum over all such curves $\beta$, it follows that 
	\[
		\hat{d}_{\tau}(p,q) \geq \dist(p,\partial B) > 0,
	\]
	which proves that $\hat{d}_{\tau}$ is definite.
\end{proof}

Combining Propositions~\ref{prop:null_distance_semi-metric},~\ref{prop:null_distance_topology}, and~\ref{prop:null_distance_definiteness}, we obtain the following result.

\begin{theorem}
	Let $\tau$ be a time function on $M$. If $\tau$ is locally anti-Lipschitz, then $\hat{d}_{\tau}$ is a metric on $M$ that induces the manifold topology.
\end{theorem}

\subsubsection{Temporal Functions}

Every temporal function $f \from M \to \RR$ is, in particular, a time function. As such, the associated null distance $\hat{d}_f$ is a semi-metric on $M$. A natural question is whether $\hat{d}_f$ is actually a metric, or equivalently, whether $f$ is locally anti-Lipschitz. This is indeed the case for $C^1$ temporal functions. Moreover, within the $C^1$  class, the local anti-Lipschitz condition characterizes temporal functions.

\begin{theorem}
	\label{thm:temporal_functions_anti-Lip}
	Let $f \from M \to \RR$ be a $C^1$ function. Then $f$ is locally anti-Lipschitz if and only if it is a temporal function.
\end{theorem}

The following proposition provides an equivalent characterization of the local anti-Lipschitz condition for $C^1$ functions.
\begin{proposition}
	\label{prop:C1_functions_anti-Lip}
	Let $h$ be any Riemannian metric on $M$, and denote by $d_h$ the corresponding distance function. Then the following conditions on a $C^1$ function $f \from M \to \RR$ are equivalent:
	\begin{enumerate}
		\item \label{item:1_C1_functions_anti-Lip} For every point $p \in M$, there exist an open neighborhood $U$ of $p$ and a constant $C > 0$ such that, for all $x,y \in U$,
		\[
			x \leq y \implies f(y) - f(x) \geq Cd_h(x,y).
		\]
		\item \label{item:2_C1_functions_anti-Lip} For every point $p \in M$, there exist an open neighborhood $U$ of $p$ and a constant $C > 0$ such that, for all future-directed causal vectors $X \in TU$,
		\[
			g(\nabla f, X) \geq C\norm{X}_h.
		\]
	\end{enumerate}
\end{proposition}
\begin{proof}
	\cref{item:1_C1_functions_anti-Lip}$\implies$\cref{item:2_C1_functions_anti-Lip}. Fix a point $p \in M$, and let $U$ and $C$ be as in~\cref{item:1_C1_functions_anti-Lip}. Let $q \in U$, and	consider any future-directed timelike vector $X \in T_qU$. Let $\alpha \from (-\delta, \delta) \to M$ be an $h$-geodesic with $\alpha(0) = q$ and $\alpha'(0) = X / \norm{X}_h$, for some $\delta > 0$ small enough so that $\alpha(t) \in U$ for all $t \in (-\delta, \delta)$. Since $\alpha'(0)$ is future-directed timelike, the curve $\alpha$ is future-directed timelike near $t = 0$. Furthermore, being an $h$-geodesic, $\alpha$ is locally minimizing for $d_h$. Therefore, for all sufficiently small $t > 0$, we have $\alpha(0) \leq \alpha(t)$ and $d_h(\alpha(0), \alpha(t)) = t$. Applying the inequality in~\cref{item:1_C1_functions_anti-Lip}, we obtain
	\[
		f(\alpha(t)) - f(\alpha(0)) \geq Ct.
	\]
	Dividing both sides by $t$ and taking the limit $t \to 0^+$ yields
	\[
		(f\circ\alpha)'(0) = \lim_{t \to 0^+} \frac{f(\alpha(t)) - f(\alpha(0))}{t} \geq C.
	\]
	Since $(f \circ \alpha)'(0) = g( \nabla f, X / \norm{X}_h )$, we conclude that
	\[
		g(\nabla f, X) \geq C\norm{X}_h.
	\]
	By continuity of $g$ and $h$, this inequality extends to all future-directed causal vectors $X \in TU$. 

	\cref{item:2_C1_functions_anti-Lip}$\implies$\cref{item:1_C1_functions_anti-Lip}. Fix a point $p \in M$, and let $U$ and $C$ be as in~\cref{item:2_C1_functions_anti-Lip}. By Lemma~\ref{lem:past_timelike}, the inequality in \cref{item:2_C1_functions_anti-Lip} implies that $\nabla f$ is past-directed timelike on all of $M$. Hence, $f$ is a temporal function. In particular, it is a time function, and thus $M$ is strongly causal by Theorem~\ref{thm:strongly_causal}. Therefore, there exists an open neighborhood $V \subseteq U$ of $p$ such that every future-directed causal curve with endpoints in $V$ is entirely contained in $U$. Let $x,y \in V$ with $x \leq y$, and let $\alpha \from [a,b] \to M$ be a future-directed causal curve from $x$ to $y$. Since $\alpha$ is entirely contained in $U$, we obtain
	\[
		f(y) - f(x) = \int_a^b (f\circ\alpha)' \de s = \int_a^b g(\nabla f, \alpha') \de s \geq CL_h(\alpha) \geq Cd_h(x,y),
	\]
	where the first inequality follows from the assumption in~\cref{item:2_C1_functions_anti-Lip}, and the second from the definition of $d_h(x,y)$ as the infimum of the $h$-length over all smooth curves from $x$ to $y$.
\end{proof}

\begin{definition}
	\label{def:bounded_away_zero}
	Let $h$ be any Riemannian metric on $M$ and let $\mathcal{T} \subseteq TM$ be a collection of tangent vectors. We say that $\mathcal{T}$ is \emph{locally bounded away from zero} if, for every point $p \in M$, there exist an open neighborhood $U$ of $p$ and a constant $C > 0$ such that, for all $T \in \mathcal{T} \cap TU$, $\norm{T}_g \geq C$.
\end{definition}

\begin{lemma}
	\label{lem:bounded_away_zero}
	Let $h$ be any Riemannian metric on $M$, and let $\mathcal{T} \subseteq TM$ be a collection of tangent vectors. If the vectors in $\mathcal{T}$ are past-directed timelike and locally bounded away from zero, then, for every point $p \in M$, there exist an open neighborhood $U$ of $p$ and a constant $C > 0$ such that, for all future-directed causal vectors $X \in TU$ and all $T \in \mathcal{T} \cap TU$, 
	\[
		g(T,X) \geq C\norm{X}_h.
	\]
\end{lemma}
\begin{proof}
	Suppose, for contradiction, that the conclusion fails at some point $p_0 \in M$. Let $U$ and $C $ be as in Definition~\ref{def:bounded_away_zero}, corresponding to $p = p_0$. Then there exist a sequence of points $p_j \in U$, with $p_j \to p_0$, a sequence of future-directed causal vectors $X_j \in T_{p_j}M$, and a sequence of past-directed timelike vectors $T_j \in \mathcal{T} \cap T_{p_j}M$ such that
	\[
		g(T_j, X_j) < j^{-1}\norm{X_j}_h.
	\]
	By rescaling and passing to a subsequence if necessary, we may assume that $\norm{X_j}_h = 1$ for all $j$ and that $X_j \to X_0$ for some future-directed causal vector $X_0 \in T_{p_0}M$. Assume first that the sequence $T_j$ is bounded in the $h$-norm. Then, up to a further subsequence, $T_j \to V_0 \in T_{p_0}M$, where $V_0$ is either past-directed causal or zero. Passing to the limit in the inequality yields
	\[
		g(V_0, X_0) = 0.
	\]
	By Lemma~\ref{lem:past_timelike}, it follows that $V_0$ is either null or zero. In both cases, we have $\norm{T_j}_g \to \norm{V_0}_g = 0$, contradicting the assumption $\norm{T_j}_g \geq C > 0$.	Suppose instead that $\norm{T_j}_h \to \infty$. Define $W_j = T_j / \norm{T_j}_h$. Then, for sufficiently large $j$, we have $\norm{T_j}_h \geq 1$, and thus
	\[
		g(W_j, X_j) < j^{-1}\norm{T_j}_h^{-1} \leq j^{-1}.
	\]
	Since $\norm{W_j}_h = 1$ for all $j$, we may extract a subsequence such that $W_j \to W_0$ for some past-directed causal vector $W_0 \in T_{p_0}M$. Passing to the limit in the inequality yields 
	\[
		g(W_0, X_0) = 0.
	\]
	By Lemma~\ref{lem:past_timelike}, it follows that $V_0$ is null. This contradicts the assumption, since for sufficiently large $j$ we have
	\[
		0 < C \leq \frac{\norm{T_j}_g}{\norm{T_j}_h} = \norm{W_j}_g \to \norm{W_0}_g = 0.
	\]
\end{proof}

We are now ready to prove Theorem~\ref{thm:temporal_functions_anti-Lip}.

\begin{proof}[Proof of Theorem~\ref{thm:temporal_functions_anti-Lip}]
	Suppose first that $f$ is locally anti-Lipschitz, and let $h$ be any Riemannian metric on $M$. Then, by Proposition~\ref{prop:C1_functions_anti-Lip} and Lemma~\ref{lem:anti-Lip_equivalent_conditions}, for every point $p \in M$, there exist an open neighborhood $U$ of $p$ and a constant $C > 0$ such that, for all future-directed causal vectors $X \in TU$,
	\[
		g(\nabla f, X) \geq C\norm{X}_h.
	\]
	By Lemma~\ref{lem:past_timelike}, it follows that $\nabla f$ is past-directed timelike on all of $M$, and therefore $f$ is a temporal function.

	Conversely, suppose that $f$ is a temporal function. Then $\nabla f$ is a continuous past-directed timelike vector field on $M$. By continuity, the collection $\{ (\nabla f)_p \}_{p \in M}$ is locally bounded away from zero. It then follows from Lemma~\ref{lem:bounded_away_zero}, Proposition~\ref{prop:C1_functions_anti-Lip}, and Lemma~\ref{lem:anti-Lip_equivalent_conditions} that $f$ is locally anti-Lipschitz.
\end{proof}

\clearpage
\section{Main Result}

The purpose of this section is to establish Theorem~\ref{thm:inequality}. We begin by analyzing a guiding example in the two-dimensional Minkowski spacetime.

\begin{example}
	\label{ex:Minkowski_inequality}
	Consider the temporal function $f(t,x) = t$ on the two-dimensional Minkowski spacetime $\mathbb{M}^2$. For any fixed $t \in \RR$, let $p,q \in M_t$ be two distinct points lying on the same level set
	\[
		M_t = f^{-1}(t) = \{ (t',x') \in \RR^2 \mid t' = t \},
	\]
	and let $d = \abs{ x_q - x_p }$ denote the Euclidean distance between their spatial components.	Since the induced Riemannian metric $h_t$ on $M_t$ coincides with the standard Euclidean metric, it follows that
	\[
		d_{h_t}(p,q) = d.
	\]
	Now consider the point 
	\[
		r = \left( t - \frac{d}{2}, \frac{x_p + x_q}{2} \right), 
	\]
	which lies at the intersection of the past null cones of $p$ and $q$. Define the piecewise causal curve $\beta$ as the concatenation of the null segments $[p, r]$ and $[r, q]$. Then 
	\[
		\hat{L}_f(\beta) = 2\abs{t_r - t} = d.
	\]
	Therefore,
	\[
		\frac{\hat{d}_f(p,q)}{d_{h_t}(p,q)} \leq \frac{\hat{L}_f(\beta)}{d_{h_t}(p,q)} = 1.
	\]
\end{example}

The key idea in the previous example is the construction of a piecewise causal curve whose null length equals the spatial distance between its endpoints. The strategy underlying the proof of Theorem~\ref{thm:inequality} is to asymptotically reproduce this construction, as formalized in the following lemma.

\begin{lemma}
	\label{lem:local_curve_construction}
	Let $(M,g)$ be a spacetime admitting a smooth temporal function $f \from M \to \RR$. Suppose there exist $t \in \RR$ and $C > 0$ such that the level set $M_t = f^{-1}(t)$ is nonempty and the equality 
	\[
		g(\nabla f, \nabla f) = -C^2
	\]
	holds at every point of $M_t$. Fix a point $p \in M_t$, and let $\gamma \from [0,L] \to M_t$ be a smooth unit-speed curve starting at $p$. Then, for every $\varepsilon \in (0,1)$ and every $s \in (0,L]$, there exists a piecewise causal curve $\beta_s$ from $p$ to $\gamma(s)$ such that\footnote{The curve $\beta_s$ depends on both $s$ and $\varepsilon$, but only the dependence on $s$ is made explicit to simplify the notation.}
	\[
		\lim_{\varepsilon \to 0^+} \lim_{s \to 0^+} \frac{\hat{L}_f(\beta_s)}{L_{h_t}(\at{\gamma}{[0,s]})} = C,
	\]
	where $h_t$ denotes the induced Riemannian metric on $M_t$ and $L_{h_t}$ is the associated length functional. Consequently,
	\[
		\lim_{s \to 0^+} \frac{\hat{d}_f(p, \gamma(s))}{L_{h_t}(\at{\gamma}{[0,s]})} \leq C.
	\]
\end{lemma}

To prove this lemma, we first establish a preliminary result showing that, within a sufficiently small normal coordinate neighborhood, piecewise causal curves for a suitably perturbed Minkowski metric are mapped to piecewise causal curves for the spacetime metric. 

For each $\varepsilon \in (0,1)$, define the \emph{$\varepsilon$-slim Minkowski metric} on $\RR^{n+1}$ by 
\[
	\eta_{\varepsilon} = -(1-\varepsilon)dt^2 + d(x^1)^2 + \dots + d(x^n)^2,
\]
and denote by $C_{\varepsilon}$ the corresponding causal cone:
\[
	C_{\varepsilon} = \{ v \in \RR^{n+1} \setminus \{ 0 \} \mid \eta_{\varepsilon}(v,v) \leq 0 \}. 
\]
We then have the following result.

\begin{lemma}
	\label{lem:slim_Minkowski}
	Let $(U,\varphi)$ be a normal coordinate chart centered at $p \in M$. Then, for every $\varepsilon \in (0,1)$, there exists an open neighborhood $U_{\varepsilon} \subseteq U$ of $p$ such that every piecewise $\eta_{\varepsilon}$-causal curve in $\varphi(U_{\varepsilon})$ is mapped by $\varphi^{-1}$ to a piecewise $g$-causal curve in $U_{\varepsilon}$.
\end{lemma}
\begin{proof}	
	At the origin $0 \in \RR^{n+1}$, the pullback of $g$ under $\varphi^{-1}$ satisfies\footnote{We identify the tangent space at any point of $\RR^{n+1}$ with $\RR^{n+1}$ itself.}
	\[
		((\varphi^{-1})^*g)_0(v,v) = \eta(v,v) < \eta_{\varepsilon}(v,v) 
	\]
	for all $v \in C_{\varepsilon}$. In particular, the inequality holds on the compact set 
	\[
		D_{\varepsilon} = S^n \cap C_{\varepsilon},
	\]
	where $S^n$ denotes the unit sphere in $\RR^{n+1}$.	Define the function
	\[
		F \from \varphi(U) \times D_{\varepsilon} \to \RR, \quad F(x,v) = ((\varphi^{-1})^*g)_x(v,v) - \eta_{\varepsilon}(v,v).
	\]
	By continuity of $F$ and the fact that $F(0,v) < 0$ for all $v \in D_{\varepsilon}$, for every $v \in D_{\varepsilon}$ there exist open neighborhoods $U_v \subseteq \varphi(U)$ of $0$ and $V_v \subseteq D_{\varepsilon}$ of $v$ such that $F(x,w) < 0$ for all $(x,w) \in U_v \times V_v$. By compactness of $D_{\varepsilon}$, there exist finitely many points $v_1,\dots,v_N \in D_{\varepsilon}$ such that 
	\[
		D_{\varepsilon} \subseteq \bigcup_{i=1}^N V_{v_i}.
	\]
	For each $i=1,\dots,N$, let $r_{i} > 0$ be such that the Euclidean open ball $B_{r_i}(0)$ is contained in $U_{v_i}$, and define
	\[
		r_{\min} = \min_{1 \leq i \leq N} r_i, \quad U_{\varepsilon} = \varphi^{-1}( B_{r_{\min}}(0) ).
	\]
	Fix $x \in \varphi(U_{\varepsilon})$ and $w \in C_{\varepsilon}$. Then the normalized vector $\hat{w} = w/\abs{w}$ lies in $D_{\varepsilon}$, hence in some $V_{v_i}$, and $x \in B_{r_i}(0) \subseteq U_{v_i}$. Therefore,
	\[
		F(x,w) = \abs{w}^2 F(x, \hat{w}) < 0,
	\]
	which implies 
	\[
		((\varphi^{-1})^*g)_x(w,w) < \eta_{\varepsilon}(w,w).
	\]
	Thus, $\mathrm{d}_x(\varphi^{-1})$ maps $\eta_{\varepsilon}$-causal vectors to $g$-causal vectors. Consequently, $\varphi^{-1}$ maps piecewise $\eta_{\varepsilon}$-causal curves in $\varphi(U_{\varepsilon})$ to piecewise $g$-causal curves in $U_{\varepsilon}$.
\end{proof}

We now proceed with the proof of Lemma~\ref{lem:local_curve_construction}.

\begin{proof}[Proof of Lemma~\ref{lem:local_curve_construction}]
	Let $(U,\varphi)$ be a normal coordinate chart centered at $p$. Since $(\nabla f)_p$ is a past-directed timelike vector satisfying 
	\[
		g_p((\nabla f)_p, (\nabla f)_p) = -C^2,
	\]
	and $\gamma'(0)$ is a spacelike unit vector, we may, up to a Lorentz transformation, assume that
	\begin{equation}
		\label{eqn:e_0}
		\mathrm{d}_p\varphi((\nabla f)_p) = -Ce_0
	\end{equation}
	and
	\begin{equation}
		\label{eqn:e_1}
		\mathrm{d}_p\varphi(\gamma'(0)) = e_1,
	\end{equation}
	where $\{ e_i \}_{i=0}^n$ denotes the standard orthonormal basis of the Minkowski spacetime $\mathbb{M}^{n+1}$. Fix $\varepsilon \in (0,1)$, and let $U_{\varepsilon} \subseteq U$ be the open neighborhood provided by Lemma~\ref{lem:slim_Minkowski}. For each $s \in (0,L]$, define $q_s = \varphi(\gamma(s))$ and write $q_s = (t_s,x_s)$, where $t_s \in \RR$ and $x_s \in \RR^n$ denote the temporal and spatial components of $q_s$, respectively. Equation~\eqref{eqn:e_1} ensures that $\abs{x_s} \neq 0$ for sufficiently small $s$. Furthermore, the first-order Taylor expansion of $\varphi\circ\gamma$ at zero yields
	\begin{equation}
		\label{eqn:expansions}
		\abs{x_s} = s + o(s), \quad t_s = o(s) \quad \text{as }\,s \to 0^+.
	\end{equation}
	It follows that, for sufficiently small $s$, 
	\[
		\abs{x_s}^2 - (1-\varepsilon)t_s^2 \neq 0,
	\]
	ensuring that the quantity
	\[
		t^*_s = \frac{\abs{x_s}^2 - (1-\varepsilon)t_s^2}{2\sqrt{1-\varepsilon} \left(  \abs{x_s} - \sqrt{1-\varepsilon}\, t_s \right)}.
	\]
	is well-defined and nonzero. Consequently, for sufficiently small $s$, the point
	\[
		 r_s = \left( t^*_s, \sqrt{1-\varepsilon}\, t^*_s\frac{x_s}{\abs{x_s}} \right),
	\]
	is well-defined and nonzero. Substituting the expansions in~\eqref{eqn:expansions} into the expression for $t^*_s$ and simplifying by absorbing higher-order terms into $o(s)$, we find
	\[
		t^*_s = \frac{1}{2\sqrt{1 - \varepsilon}} (s + o(s)) \quad \text{as }\,s \to 0^+,
	\]
	and thus,
	\[
		\lim_{s \to 0^+} \frac{t^*_s}{s} = \frac{1}{2\sqrt{1 - \varepsilon}}.
	\]	
	A direct computation shows that the straight-line segments $[0, r_s]$ and $[r_s, q_s]$ are $\eta_{\varepsilon}$-null. Furthermore, the Euclidean norm of $r_s$ satisfies
	\begin{equation}
		\label{eqn:norm_rs}
		\abs{r_s} = \sqrt{2 - \varepsilon}\, \abs{t^*_s} = \frac{1}{2}\sqrt{\frac{2 - \varepsilon}{1 - \varepsilon}}\, \abs{ s + o(s) } \quad \text{as }\,s \to 0^+.
	\end{equation}
	Define the piecewise $\eta_{\varepsilon}$-null curve $\tilde{\beta}_s$ as the concatenation of the segments $[0, r_s]$ and $[r_s, q_s]$. Since $\varphi(U_{\varepsilon})$ is open and both $r_s$ and $q_s$ converge to $0$ as $s \to 0^+$, the curve $\tilde{\beta}_s$ is entirely contained in $\varphi(U_\varepsilon)$ for sufficiently small $s$. By Lemma~\ref{lem:slim_Minkowski}, the curve $\beta_s = \varphi^{-1}\circ\tilde{\beta}_s$ is piecewise $g$-causal in $U_{\varepsilon}$, and its null length satisfies
	\begin{align*}
		\hat{L}_f(\beta_s) &= 2\abs{ (f\circ\varphi^{-1})(r_s) - (f\circ\varphi^{-1})(0) } \\
		&= 2\abs{ (\nabla(f\circ\varphi^{-1}))_0 \cdot r_s + o(\abs{r_s}) } \quad \text{as }\,\abs{r_s} \to 0,
	\end{align*}
	where the second equality follows from the first-order Taylor expansion of $f\circ\varphi^{-1}$ at the origin. Moreover, using the definition of the gradient, equation~\eqref{eqn:e_0}, and the fact that $\varphi$ is a normal coordinate chart, we obtain
	\begin{align*}
		(\nabla(f\circ\varphi^{-1}))_0 \cdot r_s &= \mathrm{d}_0(f\circ\varphi^{-1})(r_s) = \mathrm{d}_pf ( \mathrm{d}_0\varphi^{-1}(r_s) ) \\
		&= g_p( (\nabla f)_p, \mathrm{d}_0\varphi^{-1}(r_s) ) = \eta( \mathrm{d}_p\varphi((\nabla f)_p), r_s ) \\
		&= \eta(-Ce_0, r_s) = Ct^*_s.
	\end{align*}
	It follows that
	\[
		\hat{L}_f(\beta_s) = 2\abs{ Ct^*_s + o(\abs{r_s}) } \quad \text{as }\,\abs{r_s} \to 0.
	\]
	Since $\gamma$ is unit-speed, we have $L_{h_t}(\at{\gamma}{[0,s]}) = s$. Therefore,
	\begin{equation}
		\label{eqn:ratio}
		\frac{ \hat{L}_f(\beta_s) }{ L_{h_t}(\at{\gamma}{[0,s]}) } = \frac{2\abs{ Ct^*_s + o(\abs{r_s}) }}{s} \quad \text{as }\,\abs{r_s} \to 0.
	\end{equation}
	Using~\eqref{eqn:norm_rs}, we deduce that
	\[
		\lim_{s \to 0^+} \frac{o(\abs{r_s})}{s} = 0.
	\]
	Taking the limits $s \to 0^+$ and then $\varepsilon \to 0^+$ in~\eqref{eqn:ratio}, we conclude that
	\[
		\lim_{\varepsilon \to 0^+} \lim_{s \to 0^+} \frac{ \hat{L}_f(\beta_s) }{ L_{h_t}(\at{\gamma}{[0,s]}) } = \lim_{\varepsilon \to 0^+} \lim_{s \to 0^+} \frac{2\abs{ Ct^*_s + o(\abs{r_s}) }}{s} = \lim_{\varepsilon \to 0^+} \frac{C}{\sqrt{1-\varepsilon}} = C.
	\]
\end{proof}

We now complete the argument by establishing Theorem~\ref{thm:inequality}.
\begin{proof}[Proof of Theorem~\ref{thm:inequality}]
    Let $\delta > 0$, and let $\gamma : [0,L] \to M_t$ be a smooth unit-speed curve from $p$ to $q$ satisfying
    \begin{equation}
    	\label{eqn:almost_min_curve}
        L_{h_t}(\gamma) < d_{h_t}(p,q) + \delta.
    \end{equation}
    By Lemma~\ref{lem:local_curve_construction}, for every $s \in [0,L]$, there exists $\varepsilon_s > 0$ such that, for all $s' \in [0,L]$ with $\abs{s - s'} < \varepsilon_s$, we have
    \[
        \hat{d}_f(\gamma(s),\gamma(s')) \leq (C+\delta)L_{h_t}(\at{\gamma}{[s,s']}).
    \]
    The collection of intervals $\{ (s - \varepsilon_s/2, s + \varepsilon_s/2) \}_{s \in [0,L]}$ forms an open cover of $[0,L]$. Using the Lebesgue's number lemma, we can find a partition $0 = s_0 < \dots < s_N = L$ such that, for each $i = 0, \dots, N-1$,
    \begin{equation}
    	\label{eqn:local_estimates}
        \hat{d}_f(\gamma(s_i),\gamma(s_{i+1})) \leq (C+\delta)L_{h_t}(\at{\gamma}{[s_i,s_{i+1}]}).
    \end{equation}
    Applying the triangle inequality together with estimates~\eqref{eqn:local_estimates} and~\eqref{eqn:almost_min_curve}, we obtain
    \begin{align*}
        \hat{d}_f(p,q) &\leq \sum_{i=0}^{N-1} \hat{d}_f(\gamma(s_i),\gamma(s_{i+1})) \\
        &\leq (C + \delta)\sum_{i=0}^{N-1} L_{h_t}(\at{\gamma}{[s_i,s_{i+1}]}) \\
        &= (C + \delta)L_{h_t}(\gamma) \\
        &< (C + \delta)(d_{h_t}(p,q) + \delta).
    \end{align*}
    The conclusion follows by letting $\delta \to 0$.
\end{proof}

As a direct consequence of Theorem~\ref{thm:inequality} and Example~\ref{ex:GRW_temporal_functions}, we obtain the following result.

\begin{corollary}
	In a GRW spacetime
	\[
		(M,g) = (I \times S, -dt^2 + f(t)^2h),
	\]
	consider a smooth temporal function of the form $\tau(t,x)= \phi(t)$, where $\phi \from I \to \RR$ satisfies $\phi'(t) > 0$ for all $t \in I$. For any $t \in I$, consider the level set $M_t = \tau^{-1}(t)$. Then, for every $p,q \in M_t$, 
	\[
		\hat{d}_{\tau}(p,q) \leq \phi'(t)d_{h_t}(p,q),
	\]
	where $h_t$ denotes the induced Riemannian metric on $M_t$ and $d_{h_t}$ is the corresponding distance function. 
\end{corollary}

