\section{Cosmological Time}

This section focuses on the notion of regular cosmological time, as introduced by Andersson, Galloway, and Howard in~\cite{AnderssonGallowayHoward1998}. It also presents the proof of Theorem~\ref{thm:initial_level_set}.

\subsection{Regular Cosmological Time}

The \emph{cosmological time function} $\tau_g \from M \to [0,\infty]$ is defined by
\[
	\tau_g(q) = \sup_{p \leq q} d_g(p,q).
\]
In general, the function $\tau_g$ is not necessarily well-behaved; for instance, it is identically infinite in Minkowski spacetime. In \cite{AnderssonGallowayHoward1998}, Andersson, Galloway, and Howard introduced a notion of regularity for the cosmological time function and proved that, under this condition, several important properties hold. A future-directed causal curve $\gamma \from (a,b) \to M$ is said to be \emph{past inextendible} if there exists no point $p \in M$ such that 
\[
	\lim_{s \to a^+} \gamma(s) = p.
\]
The cosmological time function $\tau_g$ is called \emph{regular} if it satisfies the following conditions:
\begin{enumerate}
	\item $\tau_g(q) < \infty$ for all $q \in M$;
	\item $\tau_g \to 0$ along all past inextendible future-directed causal curves.
\end{enumerate}

\begin{proposition}[{\cite[Thm.~1.2]{AnderssonGallowayHoward1998}}]
	\label{prop:generators}
	Suppose that the cosmological time function $\tau_g$ is regular. Then the following properties hold:
	\begin{enumerate}
		\item \label{item:1_generators} $\tau_g$ is a time function, and for all $x,y \in M$,
		\[
			x \leq y \implies \tau_g(y) - \tau_g(x) \geq d_g(x,y).
		\]
		\item The gradient $\nabla \tau_g$ exists almost everywhere.
		\item \label{item:3_generators} For every point $q \in M$, there exists a future-directed timelike unit-speed geodesic $\gamma_q \from (0,\tau_g(q)] \to M$ such that $\gamma_q(\tau_g(q)) = q$ and $\tau_g(\gamma_q(t)) = t$ for all $t \in (0,\tau_g(q))$. 
	\end{enumerate}
\end{proposition}

A curve as in point~\cref{item:3_generators} above is called a \emph{generator} at $q$. The following result shows that, wherever it exists, the gradient of a regular $\tau_g$ is a past-directed timelike unit vector.

\begin{proposition}
	\label{prop:cosmo_time_unit_norm}
	Suppose that the cosmological time function $\tau_g$ is regular and differentiable at a point $q \in M$. Then there exists a unique generator $\gamma_q$ at $q$, and $(\nabla \tau_g)_q = -\gamma_q'(\tau_g(q))$. 
\end{proposition}
\begin{proof}
	Set $\tau = \tau_g$, and let $\gamma = \gamma_q$ be any generator at $q$. Define $u = \gamma'(\tau(q))$, which is a future-directed timelike unit vector at $q$. Then the gradient of $\tau$ at $q$ can be expressed as 
	\[
		(\nabla \tau)_q = -au + bv,
	\]
	where $v \in T_qM$ is a spacelike unit vector orthogonal to $u$, and $a,b \geq 0$. Since $\gamma$ is a generator at $q$, we have
	\[
		a = g((\nabla \tau)_q, u) = \frac{\mathrm{d}}{\mathrm{d}t}(\tau\circ\gamma) = \frac{\mathrm{d}}{\mathrm{d}t}(t) = 1.
	\]
	Thus, $(\nabla \tau)_q = -u + bv$. By Lemma~\ref{lem:time_functions_gradient}, the vector $(\nabla \tau)_q$ must be causal, which implies $0 \leq b \leq 1$. In particular,
	\[
		\norm{(\nabla \tau)_q}_g = \sqrt{1 - b^2} \leq 1.
	\]
	Now fix any future-directed timelike unit vector $V \in T_qM$, and let $\alpha \from (-\delta,\delta) \to M$ be a future-directed timelike unit-speed curve with $\alpha(0) = q$ and $\alpha'(0) = V$. By point~\cref{item:1_generators} of Proposition~\ref{prop:generators}, we obtain 
	\[
		g((\nabla \tau)_q, V) = \lim_{t \to 0^+} \frac{\tau(\alpha(t)) - \tau(\alpha(0))}{t} \geq \lim_{t \to 0^+} \frac{d_g(\alpha(0), \alpha(t))}{t} \geq 1.
	\]
	We now show that this forces $b = 0$, hence $(\nabla \tau)_q = -u$. First, suppose $b \neq 1$, so that $(\nabla \tau)_q$ is not null. Applying the inequality above to $V = -(\nabla \tau)_q / \norm{(\nabla \tau)_q}_g$ yields 
	\[
		\norm{(\nabla \tau)_q}_g = g((\nabla \tau)_q, V) \geq 1.
	\]
	Combining this with the earlier bound $\norm{(\nabla \tau)_q}_g \leq 1$, we conclude that $\norm{(\nabla \tau)_q}_g = 1$, and thus $b = 0$. Now suppose $b = 1$. For every $A \geq 1$, consider the future-directed timelike unit vector 
	\[
		V = Au - \sqrt{A^2 - 1}\, v.
	\]
	Then
	\[
		1 \leq g((\nabla \tau)_q, V) = A - \sqrt{A^2 - 1}.
	\]
	However, the right-hand side tends to $0$ as $A \to \infty$, yielding a contradiction. Therefore, the case $b = 1$ is excluded, and from the previous argument we deduce that $b = 0$.

	Finally, the uniqueness of the generator at $q$ follows from the uniqueness of geodesics with given initial data.
\end{proof}

\subsection{Initial Level Set}

As a consequence of Proposition~\ref{prop:cosmo_time_unit_norm}, a smooth regular cosmological time function $\tau_g$ is a smooth temporal function with unit gradient everywhere. Then the associated null distance $\hat{d}_{\tau_g}$ is a metric on $M$ that induces the manifold topology. Furthermore, by Lemma~\ref{lem:time_functions_1Lip}, $\tau_g$ is $1$-Lipschitz with respect to $\hat{d}_{\tau_g}$, and by Corollary~\ref{cor:extension_completion}, it admits a unique $1$-Lipschitz extension $\overline{\tau_g} \from \overline{M} \to [0,\infty)$ to the metric completion of $(M, \hat{d}_{\tau_g})$.

\begin{lemma}
	\label{lem:generators_1Lip}
	Suppose that the cosmological time function $\tau_g$ is smooth and regular. Then, for every $q \in M$, the unique generator $\gamma_q \from (0,\tau_g(q)] \to M$ at $q$ is $1$-Lipschitz with respect to $\hat{d}_{\tau_g}$. In particular, $\gamma_q$ admits a unique $1$-Lipschitz extension $\overline{\gamma}_q \from [0,\tau_g(q)] \to \overline{M}$.
\end{lemma}
\begin{proof}
	For all $t,t' \in (0,\tau_g(q)]$, we have
	\[
		\hat{d}_{\tau_g}(\gamma_q(t), \gamma_q(t')) \leq \hat{L}_{\tau_g}(\at{\gamma_q}{[t,t']}) = \abs{ \tau_g(t) - \tau_g(t') } = \abs{t - t'}
	\]
	where we used Lemma~\ref{lem:null_distance_basic_properties} and the fact that $\gamma_q$ is a generator. This shows that $\gamma_q$ is $1$-Lipschitz with respect to $\hat{d}_{\tau_g}$. The existence and uniqueness of the extension then follow from Corollary~\ref{cor:extension_completion}.
\end{proof}

We are now ready to prove Theorem~\ref{thm:initial_level_set}.

\begin{proof}[Proof of Theorem~\ref{thm:initial_level_set}]
	We first prove that $\overline{\tau_g}^{-1}(0) \neq \emptyset$. Fix a point $q \in M$, and let $\gamma_q \from (0,\tau_g(q)] \to M$ be the unique generator at $q$. Consider a sequence $t_k \in (0,\tau(q)]$ with $t_k \to 0$. Then the sequence $\gamma_q(t_k) \in M$ is Cauchy with respect to $\hat{d}_{\tau_g}$: 
	\[
		\hat{d}_{\tau_g}(\gamma_q(t_k), \gamma_q(t_j)) \leq \abs{t_k - t_j} \to 0,
	\]
	where we used Lemma~\ref{lem:generators_1Lip}. Since $\overline{M}$ is complete, the sequence converges to a point $q_0 \in \overline{M}$. By continuity of $\overline{\tau_g}$ and the fact that $\gamma_q$ is a generator, we obtain
	\[
		\overline{\tau_g}(q_0) = \lim_k \tau_g(\gamma_q(t_k)) = \lim_k t_k = 0,
	\]
	which shows that $q_0 \in \overline{\tau_g}^{-1}(0)$. 

	We now prove that $\overline{\tau_g}^{-1}(0)$ consists of a single point. Since $\tau_g$ is a smooth temporal function with unit gradient everywhere, Theorem~\ref{thm:inequality} implies that for any $t > 0$ such that $M_t$ is nonempty, and for every $p,q \in M_t$, 
	\[
		\hat{d}_{\tau_g}(p,q) \leq d_{h_t}(p,q).
	\]
	In particular, it follows that
	\[
		\lim_{t \to 0^+} \diam_{\hat{d}_{\tau_g}}(M_t) = 0.
	\]
	Since, for sufficiently small $t > 0$, $M_t$ is a nonempty closed and bounded subset of $\overline{M}$, and $\overline{\tau_g}^{-1}(0)$ is nonempty and closed, Lemma~\ref{lem:diam_convergence} applies; hence, it suffices to show that $M_t$ converges to $\overline{\tau_g}^{-1}(0)$ in the Hausdorff sense as $t \to 0$. Indeed, in that case,
	\[
		\diam(\overline{\tau_g}^{-1}(0)) = \lim_{t \to 0^+} \diam_{\hat{d}_{\tau_g}}(M_t) = 0,
	\]
	which implies that $\overline{\tau_g}^{-1}(0)$ consists of a single point. For every $t > 0$ such that $M_t$ is nonempty, we have
	\[
		d_{H}( M_t, \overline{\tau_g}^{-1}(0) ) = \max\{ \sup\nolimits_{q_t \in M_t}\dist(q_t, \overline{\tau_g}^{-1}(0)),\ \sup\nolimits_{q_0 \in \overline{\tau_g}^{-1}(0)}\dist(q_0, M_t) \}.
	\]
	We estimate each term separately. Fix any point $q_t \in M_t$, and let $\gamma_{q_t} \from (0,t] \to M$ be the unique generator at $q_t$. Let $\overline{\gamma}_{q_t} \from [0,t] \to \overline{M}$ be its $1$-Lipschitz extension. Then
	\begin{equation}
		\label{eqn:t_estimate_1}
		\dist(q_t, \overline{\tau_g}^{-1}(0)) \leq \hat{d}_{\tau_g}(q_t, \overline{\gamma}_{q_t}(0)) = \hat{d}_{\tau_g}(\overline{\gamma}_{q_t}(t), \overline{\gamma}_{q_t}(0)) \leq t.
	\end{equation}
	Now fix any point $q_0 \in \overline{\tau_g}^{-1}(0)$, and let $q_i \in M$ be a sequence converging to $q_0$. Choose any point $q \in M_t$, and let $\gamma_q \from (0,t] \to M$ be its generator. Given $\varepsilon > 0$, choose $0 < \tilde{t} \leq t$ such that
	\[
		\diam_{\hat{d}_{\tau_g}}(M_{t'}) < \varepsilon/2 \quad \text{for all } 0 < t' \leq \tilde{t}.
	\]
	Since $q_i \to q_0$ and $\tau_g(q_i) \to 0$, we can select $i$ sufficiently large so that 
	\[
	\hat{d}_{\tau_g}(q_0,q_i) < \varepsilon/2 \quad \text{ and } \quad \tau_g(q_i) < \tilde{t}.
	\]
	Then
	\begin{align*}
		\dist(q_0, M_t) &\leq \hat{d}_{\tau_g}(q_0, q) \\
		&\leq \hat{d}_{\tau_g}(q_0, q_i) + \hat{d}_{\tau_g}(q_i, \gamma_q(\tau_g(q_i))) + \hat{d}_{\tau_g}(\gamma_q(\tau_g(q_i)), q) \\
		&< \varepsilon / 2 + \diam_{\hat{d}_{\tau_g}}(M_{\tau_g(q_i)}) + (t - \tau_g(q_i)) \\
		&< t + \varepsilon.
	\end{align*}
	Taking the limit $\varepsilon \to 0$, we conclude that
	\begin{equation}
		\label{eqn:t_estimate_2}
		\dist(q_0, M_t) \leq t.
	\end{equation}
	Combining estimates~\eqref{eqn:t_estimate_1} and~\eqref{eqn:t_estimate_2}, we obtain
	\[
		d_{H}( M_t, \overline{\tau_g}^{-1}(0) ) \leq t,
	\]
	which implies that $M_t$ converges to $\overline{\tau_g}^{-1}(0)$ in the Hausdorff sense as $t \to 0$.
\end{proof}

