\section{Appendix}

\subsection{Deferred Proofs}	
\label{chap:Deferred_Proofs}

\begin{lemma*}[Lemma~\ref{lem:causal_timelike} (restated)]
	Let $X,T \in TM$ be tangent vectors at the same point, with $X$ causal and $T$ timelike. Then $g(X,T) \neq 0$.
\end{lemma*}
\begin{proof}
	Suppose, for contradiction, that $g(X,T) = 0$. Since $T$ is timelike and the metric $g$ has signature $(1,n)$, $X$ cannot be timelike and must therefore be null. Given that $g(X,T) = 0$ and $X$ is null, equality is attained in the reverse Cauchy--Schwarz inequality, which implies that $X$ and $T$ are linearly dependent. This is a contradiction, as $X$ is null and $T$ is timelike.
\end{proof}

\begin{lemma*}[Lemma~\ref{lem:past_timelike} (restated)]
	Let $p \in M$, and let $h_p$ be any Euclidean inner product on $T_pM$. Then the following conditions on a tangent vector $T \in T_pM$ are equivalent:
	\begin{enumerate}
		\item \label{item:1_past_timelike} $T$ is past-directed timelike.
		\item \label{item:2_past_timelike} For every future-directed causal vector $X \in T_pM$, $g(X,T) > 0$.
		\item \label{item:3_past_timelike} There exists a constant $C > 0$ such that, for all future-directed causal vectors $X \in T_pM$,
		\[
			g(T,X) \geq C\norm{X}_{h_p}.
		\]
	\end{enumerate}
\end{lemma*}
\begin{proof}
	\cref{item:1_past_timelike}$\implies$\cref{item:2_past_timelike}. By Lemma~\ref{lem:causal_timelike}, for every future-directed causal vector $X \in T_pM$, we have $g(X,T) \neq 0$. Suppose, for contradiction, that $g(X,T) < 0$ for some such $X$. Let $\vartheta$ denote the time orientation, and define
	\[
		T' = T + \lambda\vartheta,
	\]
	where $\lambda < 0$ is chosen so that 
	\[
		g(X,T') = g(X,T) + \lambda g(X,\vartheta) = 0.
	\]
	Then $T'$ is timelike and $g(X,T') = 0$, contradicting Lemma~\ref{lem:causal_timelike}.

	\cref{item:2_past_timelike}$\implies$\cref{item:3_past_timelike}. Suppose, for contradiction, that the conclusion fails. Then there exists a sequence of future-directed causal vectors $X_j \in T_pM$ such that 
	\[
		g(T,X_j) < j^{-1}\norm{X_j}_{h_p}. 
	\]
	By rescaling and passing to a subsequence if necessary, we may assume that $\norm{X_j}_{h_p} = 1$ for all $j$ and that $X_j \to X_0$ for some future-directed causal vector $X_0 \in T_pM$. Passing to the limit in the inequality yields
	\[
		g(T,X_0) = 0,
	\]
	which contradicts~\cref{item:2_past_timelike}. 

	\cref{item:3_past_timelike}$\implies$\cref{item:1_past_timelike}. Suppose, for contradiction, that $T$ is either zero, null, or spacelike. 
	Then there exists a future-directed causal vector $X \in T_pM$ such that $g(T,X) = 0$, contradicting the inequality in~\cref{item:3_past_timelike}.  Hence, $T$ must be timelike. Moreover, since the time orientation $\vartheta$ is future-directed timelike, the inequality
	\[
		g(T,\vartheta) \geq C\norm{\vartheta}_h > 0
	\]
	implies that $T$ is past-directed.
\end{proof}

\begin{lemma*}[Lemma~\ref{lem:time_functions_gradient} (restated)]
	Let $\tau$ be a time function on $M$. If $\tau$ is differentiable at a point $p \in M$, then the gradient vector $(\nabla \tau)_p$ is either past-directed causal or zero.
\end{lemma*}
\begin{proof}
	We first claim that for every future-directed timelike vector $T \in T_pM$, $g((\nabla \tau)_p, T) \geq 0$. Indeed, let $\gamma \from (-\delta,\delta) \to M$ be a future-directed timelike curve with $\gamma(0) = p$ and $\gamma'(0) = T$. Since $\tau$ is a time function, the composition $\tau\circ\gamma$ is strictly increasing. Hence, its derivative at zero satisfies $(\tau\circ\gamma)'(0) \geq 0$. This derivative equals $\mathrm{d}_p\tau(T) = g((\nabla \tau)_p, T)$, so the claim follows.

	Suppose, for contradiction, that $(\nabla \tau)_p$ is spacelike, that is, $g((\nabla \tau)_p, (\nabla \tau)_p) > 0$. Choose a future-directed timelike vector $T \in T_pM$ such that $g(T, (\nabla \tau)_p) = 0$, and define
	\[
		T' = T + \lambda(\nabla \tau)_p,
	\]
	where $\lambda < 0$ is chosen so that
	\[
		g(T,T) + \lambda^2g((\nabla \tau)_p, (\nabla \tau)_p) < 0.
	\]
	Let $\vartheta$ denote the time orientation. Then:
	\begin{enumerate}
		\item $T'$ is timelike, since
		\begin{align*}
			g(T',T') &= g(T + \lambda (\nabla \tau)_p, T + \lambda (\nabla \tau)_p) \\
			&= g(T,T) +2\lambda g(T, (\nabla \tau)_p) + \lambda^2 g((\nabla \tau)_p, (\nabla \tau)_p) \\
			&= g(T,T) + \lambda^2 g((\nabla \tau)_p, (\nabla \tau)_p) \\
			&< 0.
		\end{align*}
		\item $T'$ is future-directed, since
		\[
			g(T', \vartheta) = g(T, \vartheta) + \lambda g((\nabla \tau)_p, \vartheta) < 0,
		\]
		where we used that $g(T, \vartheta) < 0$ because $T$ is future-directed, and that $g((\nabla \tau)_p, \vartheta) \geq 0$ by the initial claim.
	\end{enumerate}
	However,
	\begin{align*}
		g((\nabla \tau)_p, T') &= g((\nabla \tau)_p, T) + \lambda g((\nabla \tau)_p, (\nabla \tau)_p) \\
		&= \lambda g((\nabla \tau)_p, (\nabla \tau)_p) \\
		&< 0,
	\end{align*}
	which contradicts the initial claim. Hence, $(\nabla \tau)_p$ cannot be spacelike and must be either causal or zero. Finally, if $(\nabla \tau)_p$ is causal, then it must be past-directed since $g((\nabla \tau)_p, \vartheta) \geq 0$.
\end{proof}

